import https from 'node:https';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// ── Interfaces PokeAPI ────────────────────────────────────────────────────────
interface PokeAPIName { language: { name: string }; name: string; }
interface PokeAPIStat { base_stat: number; stat: { name: string }; }
interface PokeAPIType { type: { name: string }; }
interface PokeAPIAbility { ability: { name: string; url: string }; is_hidden: boolean; }
interface PokeAPIMove {
  move: { name: string; url: string };
  version_group_details: Array<{
    level_learned_at: number;
    move_learn_method: { name: string };
    version_group: { name: string };
  }>;
}
interface PokeAPIFlavorText { flavor_text: string; language: { name: string }; version: { name: string }; }
interface PokeAPISpecies {
  flavor_text_entries: PokeAPIFlavorText[];
  names: PokeAPIName[];
  evolution_chain: { url: string };
}
interface PokeAPIPokemon {
  id: number;
  name: string;
  stats: PokeAPIStat[];
  types: PokeAPIType[];
  abilities: PokeAPIAbility[];
  moves: PokeAPIMove[];
}

// ── Caché de nombres para evitar redundancia ─────────────────────────────────
const NAME_CACHE: Record<string, Record<string, string>> = {
  moves: {},
  abilities: {},
  species: {}
};

// ── Versión target para learnset ──────────────────────────────────────────────
const TARGET_VERSIONS = ['firered-leafgreen', 'ruby-sapphire', 'emerald', 'heartgold-soulsilver'];

const httpsGet = <T>(url: string): Promise<T> => new Promise((resolve, reject) => {
  https.get(url, { headers: { 'User-Agent': 'PokeBorrador-AddPokemon/1.0' } }, (res: import('node:http').IncomingMessage) => {
    if (res.statusCode !== 200) return reject(new Error(`HTTP ${res.statusCode} for ${url}`));
    let data = '';
    res.on('data', (c: Buffer | string) => data += c);
    res.on('end', () => { try { resolve(JSON.parse(data) as T); } catch(e) { reject(e); } });
  }).on('error', reject);
});

async function getSpanishName(url: string, type: 'moves' | 'abilities' | 'species'): Promise<string | null> {
  const cache = NAME_CACHE[type];
  if (cache && cache[url]) return cache[url];

  try {
    const data = await httpsGet<{ names: PokeAPIName[] }>(url);
    const esEntry = data.names.find(n => n.language.name === 'es');
    const name = esEntry ? esEntry.name : null;
    if (name && cache) cache[url] = name;
    return name;
  } catch (_e) {
    return null;
  }
}

async function fetchPokemon(pokemonName: string) {
  const name = pokemonName.toLowerCase().trim();
  console.log(`\nFetching data for "${name}" from PokeAPI...`);

  // 1. Fetch basic pokemon data
  const pokemon = await httpsGet<PokeAPIPokemon>(`https://pokeapi.co/api/v2/pokemon/${name}`);

  const nationalId = pokemon.id;
  const officialName = pokemon.name;

  // Stats
  const statMap: Record<string, number> = {};
  pokemon.stats.forEach(s => { statMap[s.stat.name] = s.base_stat; });

  // Types
  const types = pokemon.types.map(t => t.type.name);
  const type1 = types[0]!;
  const type2 = types[1] || null;

  // Abilities
  const abilities = await Promise.all(pokemon.abilities.map(async (a) => {
    const enName = a.ability.name;
    const esName = await getSpanishName(a.ability.url, 'abilities');
    return { en: enName, es: esName, isHidden: a.is_hidden };
  }));

  // 2. Learnset from Gen 3 version groups
  const levelMoves = [];
  const machineMoves = [];

  const seenLevelMoves = new Set();
  const seenMachineMoves = new Set();

  for (const moveEntry of pokemon.moves) {
    for (const vgd of moveEntry.version_group_details) {
      if (TARGET_VERSIONS.includes(vgd.version_group.name)) {
        const enName = moveEntry.move.name;
        if (vgd.move_learn_method.name === 'level-up') {
          if (!seenLevelMoves.has(enName)) {
            seenLevelMoves.add(enName);
            const esName = await getSpanishName(moveEntry.move.url, 'moves');
            levelMoves.push({
              lv: vgd.level_learned_at,
              en: enName,
              es: esName || `⚠️ TRADUCIR: ${enName}`,
              pp: 35
            });
          }
        } else if (vgd.move_learn_method.name === 'machine') {
          if (!seenMachineMoves.has(enName)) {
            seenMachineMoves.add(enName);
            const esName = await getSpanishName(moveEntry.move.url, 'moves');
            machineMoves.push({ en: enName, es: esName });
          }
        }
      }
    }
  }

  // Remove duplicates keeping lowest level, then sort
  const uniqueMovesMap: Record<string, { lv: number; en: string; es: string; pp: number }> = {};
  levelMoves.forEach(m => {
    const key = m.en;
    const existing = uniqueMovesMap[key];
    if (!existing || m.lv < existing.lv) {
      uniqueMovesMap[key] = m;
    }
  });
  const sortedLearnset = Object.values(uniqueMovesMap).sort((a, b) => a.lv - b.lv);

  // 3. Species data (flavor text)
  console.log('Fetching species data...');
  const species = await httpsGet<PokeAPISpecies>(`https://pokeapi.co/api/v2/pokemon-species/${nationalId}`);
  const flavorEs = species.flavor_text_entries.find(e => e.language.name === 'es' && ['ruby', 'sapphire', 'firered', 'leafgreen', 'emerald'].includes(e.version.name));
  const flavorEn = species.flavor_text_entries.find(e => e.language.name === 'en' && ['ruby', 'sapphire', 'firered', 'leafgreen', 'emerald'].includes(e.version.name));
  const nameEs = species.names.find(n => n.language.name === 'es')?.name || officialName;

  // Evolution chain
  const evoChainUrl = species.evolution_chain.url;
  const evoChain = await httpsGet<{ chain: unknown }>(evoChainUrl);

  // ── Build output ─────────────────────────────────────────────────────────────
  const result = {
    meta: {
      pokemon_name_en: officialName,
      pokemon_name_es: nameEs,
      national_id: nationalId,
      type1,
      type2,
      sprite_url: `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${nationalId}.png`,
    },
    stats: {
      hp: statMap['hp'] || 0,
      atk: statMap['attack'] || 0,
      def: statMap['defense'] || 0,
      spa: statMap['special-attack'] || 0,
      spd: statMap['special-defense'] || 0,
      spe: statMap['speed'] || 0,
    },
    abilities: abilities,
    flavor_text: {
      es: flavorEs?.flavor_text?.replace(/\n/g, ' ').replace(/\f/g, ' ') || 'No disponible',
      en: flavorEn?.flavor_text?.replace(/\n/g, ' ').replace(/\f/g, ' ') || 'Not available',
    },
    learnset: sortedLearnset,
    machine_moves: machineMoves,
    evolution_chain: JSON.stringify(evoChain.chain, null, 2),
  };

  // ── Generate ready-to-use code ───────────────────────────────────────────────
  const learnsetCode = sortedLearnset.map(m =>
    `    { lv: ${m.lv}, name: '${m.es.replace("'", "\\'")}', pp: ${m.pp} }`
  ).join(',\n');

  const abilityNames = abilities.filter(a => !a.isHidden).map(a => a.es ? `'${a.es}'` : `'⚠️ ${a.en}'`).join(', ');

  const pokemonDbCode = `  ${name}: {
    name: '${nameEs}', emoji: '${type1 === 'fire' ? '🔥' : type1 === 'water' ? '💧' : type1 === 'grass' ? '🌿' : type1 === 'psychic' ? '🔮' : type1 === 'dark' ? '🌑' : type1 === 'ghost' ? '👻' : type1 === 'ice' ? '🧊' : type1 === 'dragon' ? '🐉' : type1 === 'electric' ? '⚡' : type1 === 'ground' ? '🏔️' : type1 === 'rock' ? '🪨' : type1 === 'poison' ? '☠️' : type1 === 'flying' ? '🦅' : type1 === 'bug' ? '🐛' : type1 === 'fighting' ? '🥊' : type1 === 'steel' ? '⚙️' : type1 === 'normal' ? '⭐' : '❓'}', type: '${type1}',
    hp: ${statMap['hp']}, atk: ${statMap['attack']}, def: ${statMap['defense']}, spa: ${statMap['special-attack']}, spd: ${statMap['special-defense']}, spe: ${statMap['speed']},
    learnset: [
${learnsetCode}
    ]
  },`;

  const abilitiesCode = `  ${name}: [${abilityNames}],`;

  const pokedexSpriteCode = `  ${name}: ${nationalId},`;
  const pdexOrderNote = `'${name}',  // Insertar en PDEX_ORDER en la posición #${nationalId}`;

  const type2Code = type2 ? `  ${name}: '${type2}',` : null;

  // ── Write output ─────────────────────────────────────────────────────────────
  const outputDir = path.join(__dirname, '_output');
  if (!fs.existsSync(outputDir)) fs.mkdirSync(outputDir);

  const outputPath = path.join(outputDir, `${name}.json`);
  fs.writeFileSync(outputPath, JSON.stringify(result, null, 2));

  const codePath = path.join(outputDir, `${name}_code.txt`);
  const codeContent = `
=================================================================
DATOS PARA AGREGAR: ${nameEs.toUpperCase()} (#${nationalId})
Generado automáticamente desde PokeAPI
=================================================================

⚠️  ADVERTENCIAS:
${sortedLearnset.filter(m => m.es.includes('TRADUCIR')).map(m => `   - Traduce manualmente: ${m.en}`).join('\n') || '   Ninguna — todos los movimientos tienen traducción.'}
${abilities.filter(a => !a.es).map(a => `   - Habilidad sin traducción: ${a.en}`).join('\n') || ''}

-----------------------------------------------------------------
1. POKEMON_DB en src/data/pokemonDB.js
   (Agregar antes del cierre del objeto POKEMON_DB)
-----------------------------------------------------------------
${pokemonDbCode}

-----------------------------------------------------------------
2. TIPO SECUNDARIO en SECONDARY_TYPES en src/data/types.js
-----------------------------------------------------------------
${type2Code || `// ${nameEs} no tiene tipo secundario, no agregar nada.`}

-----------------------------------------------------------------
3. ABILITIES en POKEMON_ABILITIES en src/data/abilities.js
-----------------------------------------------------------------
${abilitiesCode}

-----------------------------------------------------------------
4. EVOLUCIÓN en src/data/evolutionData.js
   (Revisar la cadena completa abajo y agregar en el objeto correcto)
-----------------------------------------------------------------
// Cadena de evolución completa:
${result.evolution_chain}

-----------------------------------------------------------------
5. POKEMON_SPRITE_IDS en src/logic/pokedexConstants.js
-----------------------------------------------------------------
${pokedexSpriteCode}

-----------------------------------------------------------------
6. PDEX_ORDER en src/logic/pokedexConstants.js
-----------------------------------------------------------------
${pdexOrderNote}

-----------------------------------------------------------------
7. TM_COMPAT en src/logic/pokedexConstants.js
   (Lista de movimientos aprendibles por MT - traducir TM ids manualmente)
   Movimientos por MQ en Gen 3: 
${machineMoves.map(m => `   ${m.en} → ${m.es || '⚠️ TRADUCIR'}`).join('\n')}

   Ejemplo aproximado (VERIFICAR con Bulbapedia):
  ${name}: [/* TM IDs aquí - ver SKILL.md */],

-----------------------------------------------------------------
8. DESCRIPCIÓN POKÉDEX
-----------------------------------------------------------------
ES: ${result.flavor_text.es}
EN: ${result.flavor_text.en}

-----------------------------------------------------------------
9. SNIPPETS DE INYECCIÓN (Para probar inmediatamente)
   (Copiar y pegar en la consola del navegador una vez insertado el código)
-----------------------------------------------------------------

// OPCIÓN A: Pokémon REAL (Naturaleza, IVs y Movimientos naturales)
injectPokemonToBox(makePokemon('${name}', 50));

// OPCIÓN B: Pokémon de PRUEBA (Para validar visualmente variantes)
injectPokemonToBox({
  uid: crypto.randomUUID(),
  id: '${name}',
  name: '${nameEs}',
  level: 50,
  hp: 150, maxHp: 150,
  atk: 100, def: 100, spa: 100, spd: 100, spe: 100,
  ivs: { hp: 31, atk: 31, def: 31, spa: 31, spd: 31, spe: 31 },
  nature: 'Seria',
  ability: '${abilities[0].es || 'Espesura'}',
  moves: [
    { name: '${sortedLearnset[0]?.es || 'Placaje'}', pp: 35, maxPP: 35 },
    { name: '${sortedLearnset[1]?.es || 'Gruñido'}', pp: 40, maxPP: 40 }
  ],
  isShiny: true, // Forzamos shiny para prueba visual
  exp: 0, expNeeded: 100, friendship: 70
});

=================================================================
¡VERIFICAR CON SKILL.md ANTES DE INSERTAR EN EL JUEGO!
=================================================================
`;

  fs.writeFileSync(codePath, codeContent);

  console.log(`\n✅ Datos guardados en:`);
  console.log(`   📄 Datos raw:  ${outputPath}`);
  console.log(`   📋 Código:     ${codePath}`);
  console.log(`\n📊 Resumen:`);
  console.log(`   Nombre:     ${nameEs} (${officialName})`);
  console.log(`   ID:         #${nationalId}`);
  console.log(`   Tipos:      ${types.join(', ')}`);
  console.log(`   Stats:      HP:${statMap['hp']} ATK:${statMap['attack']} DEF:${statMap['defense']} SPA:${statMap['special-attack']} SPD:${statMap['special-defense']} SPE:${statMap['speed']}`);
  console.log(`   Habilidades:${abilities.map(a => ` ${a.es || a.en}${a.isHidden ? ' (oculta)' : ''}`).join(',')}`);
  console.log(`   Movimientos por nivel (Gen 3): ${sortedLearnset.length}`);
  console.log(`   Movimientos por MT:            ${machineMoves.length}`);

  const unmapped = sortedLearnset.filter(m => m.es.includes('TRADUCIR'));
  if (unmapped.length > 0) {
    console.log(`\n⚠️  ${unmapped.length} movimientos necesitan traducción manual:`);
    unmapped.forEach(m => console.log(`   - ${m.en}`));
  }

  console.log(`\n➡️  Siguiente paso: Abre ${codePath} y copia los snippets al juego siguiendo SKILL.md`);
}

// ── Main ──────────────────────────────────────────────────────────────────────
const pokemonName = process.argv[2];
if (!pokemonName) {
  console.error('❌ Uso: node fetch_pokemon.js <nombre_en_ingles>');
  console.error('   Ejemplo: node fetch_pokemon.js houndour');
  process.exit(1);
}

fetchPokemon(pokemonName).catch(err => {
  console.error('❌ Error:', err.message);
  process.exit(1);
});

/**
 * @file admin_supabase_users.ts
 * @description Script automático de administración de usuarios Supabase (Nube o NAS),
 * permitiendo desbanear, cambiar contraseñas, actualizar correos, cambiar nombres de usuario
 * y promover a rol de administrador directamente desde la CLI, sin necesidad de escribir código SQL manual.
 * 
 * UTILIDAD:
 * Reemplaza las consultas manuales de las Secciones 7 y 8 del README mediante comandos limpios:
 * --server=<perfil> --action=<unban|set-password|set-email|set-username|promote> --email=<email> [...]
 * 
 * CUMPLE CON:
 * - Regla de Aislamiento y Parseo Multi-Servidor (env-multi-server-parser).
 * - Estándares Node.js 26+ (Explicit Resource Management con 'using', prefijos node:).
 * - Arquitectura Zero-Warning y Zero-Any.
 */

import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';
import postgres from 'postgres';
import { readAndParseEnv, buildDatabaseUrl } from './lib/supabaseClient.ts';

// Optimizar ejecución en ejecuciones sucesivas
enableCompileCache();

export async function adminSupabaseUsers() {
  console.log(styleText('bold', '\n--- 🛡️ SUPABASE USER ADMIN MANAGER (Node.js 26+) ---'));

  const serverConfigs = await readAndParseEnv();
  const baseProfiles = Object.keys(serverConfigs);
  if (baseProfiles.length === 0) {
    console.error(styleText('red', '❌ Error: No se encontraron configuraciones de servidor (SERVER_<profile>_*) en el .env.'));
    process.exit(1);
  }

  const allAvailable = Array.from(new Set(baseProfiles.concat(Object.values(serverConfigs).map(c => c.ID).filter(Boolean) as string[])));

  // Parsear argumentos de la línea de comandos
  const args = process.argv.slice(2);
  const getArg = (flag: string): string | undefined => {
    const idx = args.findIndex(a => a === flag);
    if (idx !== -1 && args[idx + 1] !== undefined) {
      return args[idx + 1];
    }
    return args.find(a => a.startsWith(`${flag}=`))?.split('=')[1];
  };

  const serverArg = getArg('--server');
  const actionArg = getArg('--action');
  const emailArg = getArg('--email');
  const passwordArg = getArg('--password');
  const newEmailArg = getArg('--new-email');
  const usernameArg = getArg('--username');

  if (!serverArg || !actionArg || (!emailArg && !usernameArg)) {
    console.log(styleText('yellow', '⚠️  Faltan argumentos obligatorios. Uso requerido:'));
    console.log(styleText('cyan', `npm run servers:db:admin -- --server=<perfil> --action=<accion> [--email=<email> | --username=<username>]`));
    console.log(styleText('gray', '\nAcciones disponibles:'));
    console.log(styleText('gray', '  --action=unban             : Desbanea una cuenta de usuario.'));
    console.log(styleText('gray', '  --action=set-password      : Cambia la contraseña (requiere --password=<nueva_pass>).'));
    console.log(styleText('gray', '  --action=set-email         : Cambia el correo (requiere --new-email=<nuevo_email>).'));
    console.log(styleText('gray', '  --action=set-username      : Cambia el nombre de entrenador (requiere --username=<nombre>).'));
    console.log(styleText('gray', '  --action=promote           : Otorga rol de administrador (ADMIN) al usuario.'));
    console.log(styleText('cyan', `\nPerfiles disponibles: ${allAvailable.join(', ')}`));
    process.exit(1);
  }

  const profile = serverArg;
  let conf = serverConfigs[profile];
  if (!conf) {
    const found = Object.keys(serverConfigs).find(p => serverConfigs[p]?.ID === profile);
    if (found) conf = serverConfigs[found];
  }
  if (!conf) {
    console.error(styleText('red', `❌ Error: El perfil o ID "${profile}" no existe en el archivo .env.`));
    process.exit(1);
  }

  console.log(styleText('bold', styleText('blue', `\n==================================================`)));
  console.log(styleText('bold', styleText('cyan', `🛡️ EJECUTANDO ACCIÓN DE ADMIN [${actionArg.toUpperCase()}] EN: [${profile}]`)));
  console.log(styleText('bold', styleText('blue', `==================================================`)));

  // Construir URL de Conexión Postgres
  const dbUrl = buildDatabaseUrl(conf, profile);

  if (!dbUrl) {
    console.error(styleText('red', `❌ Error: No se pudo construir la URL de conexión Postgres para el perfil "${profile}".`));
    console.error(styleText('yellow', `👉 Asegúrate de tener SERVER_${profile}_POSTGRES_PASSWORD y SERVER_${profile}_SUPABASE_PUBLIC_URL en el .env`));
    process.exit(1);
  }

  if (dbUrl.includes('placeholder')) {
    console.error(styleText('red', `❌ Error: La contraseña para "${profile}" es un placeholder. Operación cancelada.`));
    process.exit(1);
  }

  const isSupabaseCloud = dbUrl.includes('.supabase.co');
  console.log(styleText('cyan', `🔌 Conectando al servidor Postgres de [${profile}]...`));

  const sql = postgres(dbUrl, { ssl: isSupabaseCloud ? 'require' : false, max: 1 });

  try {
    let targetEmail = emailArg || null;
    let targetUsername = usernameArg || null;

    // Resolver identificadores desde la base de datos si falta alguno
    if (targetUsername && !targetEmail) {
      const existing = await sql`
        SELECT email FROM public.profiles WHERE username = ${targetUsername} LIMIT 1;
      `;
      if (existing.length > 0 && existing[0]?.email) {
        targetEmail = existing[0].email;
      }
    } else if (targetEmail && !targetUsername) {
      const existing = await sql`
        SELECT username FROM public.profiles WHERE email = ${targetEmail} LIMIT 1;
      `;
      if (existing.length > 0 && existing[0]?.username) {
        targetUsername = existing[0].username;
      }
    }

    const displayName = targetEmail || targetUsername || '';
    console.log(styleText('cyan', `👤 Identificador objetivo: ${displayName}`));

    if (actionArg === 'unban') {
      const res = await sql`
        UPDATE public.profiles
        SET is_banned = false, ban_reason = NULL
        WHERE email = ${targetEmail} OR username = ${targetUsername};
      `;
      if (res.count === 0) {
        console.log(styleText('yellow', `⚠️  No se encontró ningún usuario con "${displayName}" en la tabla profiles.`));
      } else {
        console.log(styleText('green', `✔️ Cuenta de "${displayName}" desbaneada exitosamente.`));
      }

    } else if (actionArg === 'set-password') {
      if (!targetEmail) {
        throw new Error('La acción set-password requiere un correo electrónico asociado al usuario.');
      }
      if (!passwordArg) {
        throw new Error('La acción set-password requiere el argumento --password=<nueva_pass>');
      }
      const res = await sql`
        UPDATE auth.users
        SET encrypted_password = crypt(${passwordArg}, gen_salt('bf'))
        WHERE email = ${targetEmail};
      `;
      if (res.count === 0) {
        console.log(styleText('yellow', `⚠️  No se encontró ningún usuario con el correo "${targetEmail}" en auth.users.`));
      } else {
        console.log(styleText('green', `✔️ Contraseña de "${targetEmail}" actualizada exitosamente.`));
      }

    } else if (actionArg === 'set-email') {
      if (!targetEmail) {
        throw new Error('La acción set-email requiere un correo actual.');
      }
      if (!newEmailArg) {
        throw new Error('La acción set-email requiere el argumento --new-email=<nuevo_email>');
      }
      await sql.begin(async (tx) => {
        const resAuth = await tx`
          UPDATE auth.users
          SET email = ${newEmailArg}, email_confirmed_at = NOW()
          WHERE email = ${targetEmail};
        `;
        const resProfile = await tx`
          UPDATE public.profiles
          SET email = ${newEmailArg}
          WHERE email = ${targetEmail};
        `;
        if (resAuth.count === 0 && resProfile.count === 0) {
          console.log(styleText('yellow', `⚠️  No se encontró ningún usuario con el correo "${targetEmail}".`));
        } else {
          console.log(styleText('green', `✔️ Correo actualizado exitosamente de "${targetEmail}" a "${newEmailArg}".`));
        }
      });

    } else if (actionArg === 'set-username') {
      if (!targetEmail) {
        throw new Error('La acción set-username requiere un correo electrónico asociado al usuario.');
      }
      if (!usernameArg) {
        throw new Error('La acción set-username requiere el argumento --username=<nombre>');
      }
      try {
        const res = await sql`
          UPDATE public.profiles
          SET username = ${usernameArg}
          WHERE email = ${targetEmail};
        `;
        if (res.count === 0) {
          console.log(styleText('yellow', `⚠️  No se encontró ningún usuario con el correo "${targetEmail}" en la tabla profiles.`));
        } else {
          console.log(styleText('green', `✔️ Nombre de entrenador de "${targetEmail}" actualizado exitosamente a "${usernameArg}".`));
        }
      } catch (uErr: unknown) {
        if ((uErr as Error).message.includes('unique') || (uErr as Error).message.includes('violates unique constraint')) {
          throw new Error(`El nombre de usuario "${usernameArg}" ya está en uso por otro jugador.`);
        }
        throw uErr;
      }

    } else if (actionArg === 'promote') {
      let userFound = false;
      if (targetEmail || targetUsername) {
        const check = await sql`
          SELECT id FROM public.profiles 
          WHERE (${targetEmail}::text IS NOT NULL AND email = ${targetEmail})
             OR (${targetUsername}::text IS NOT NULL AND username = ${targetUsername});
        `;
        userFound = check.length > 0;
      }

      if (userFound) {
        await sql`
          UPDATE public.profiles
          SET role = 'admin'
          WHERE (${targetEmail}::text IS NOT NULL AND email = ${targetEmail})
             OR (${targetUsername}::text IS NOT NULL AND username = ${targetUsername});
        `;
        console.log(styleText('green', `✔️ Usuario "${displayName}" promovido exitosamente a rol de ADMINISTRADOR (admin).`));
      } else {
        throw new Error(`El usuario "${displayName}" no existe en la base de datos.`);
      }

    } else {
      console.error(styleText('red', `❌ Error: Acción desconocida "${actionArg}".`));
