import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join, extname } from 'node:path';

function walkDir(dir: string): string[] {
  const results: string[] = [];
  const IGNORE = new Set(['node_modules', 'dist', '.git', 'backup_legacy_code', 'public']);
  for (const entry of readdirSync(dir)) {
    if (IGNORE.has(entry)) continue;
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) results.push(...walkDir(full));
    else if (['.ts', '.vue'].includes(extname(full))) results.push(full);
  }
  return results;
}

const root = new URL('..', import.meta.url).pathname.replace(/^\/([A-Z]:)/, '$1');
let fixed = 0;

for (const file of walkDir(root)) {
  const content = readFileSync(file, 'utf-8');
  // Remove .ts suffix from .vue imports: './Foo.vue' → './Foo.vue'
  const updated = content.replace(/(['"])(\.\.?\/[^'"]*\.vue)\.ts(['"])/g, '$1$2$3');
  if (updated !== content) {
    writeFileSync(file, updated, 'utf-8');
    fixed++;
    console.log('Fixed:', file);
  }
}

console.log(`\n✅ Reverted .vue.ts → .vue in ${fixed} files.`);

/**
 * scripts/fix_vue_inline_imports.ts
 *
 * Removes spurious `import { setTimeout } from 'node:timers/promises'`
 * that was injected INLINE into `<script setup lang="ts">` tags.
 * 
 * Pattern to fix:
 *   <script setup lang="ts">import { setTimeout } from 'node:timers/promises';
 *   
 * Expected result:
 *   <script setup lang="ts">
 *
 * [PureVue-Ignore]
 */

import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join, extname } from 'node:path';

const IGNORE_DIRS = new Set(['node_modules', 'dist', '.git', 'backup_legacy_code', 'public', 'scripts']);

function walkDir(dir: string): string[] {
  const results: string[] = [];
  for (const entry of readdirSync(dir)) {
    if (IGNORE_DIRS.has(entry)) continue;
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) results.push(...walkDir(full));
    else if (['.ts', '.vue'].includes(extname(full))) results.push(full);
  }
  return results;
}

const root = new URL('..', import.meta.url).pathname.replace(/^\/([A-Z]:)/, '$1');
const srcDir = join(root, 'src');

let fixed = 0;

for (const file of walkDir(srcDir)) {
  const content = readFileSync(file, 'utf-8');

  // Pattern 1: <script setup lang="ts">import { setTimeout } from 'node:timers/promises';
  // Replace with: <script setup lang="ts">
  let updated = content.replace(
    /(<script[^>]*>)import \{ setTimeout \} from ['"]node:timers\/promises['"];?\r?\n/g,
    '$1\n'
  );

  // Pattern 2: standalone line inside vue files (fallback)
  updated = updated.replace(
    /^import \{ setTimeout \} from ['"]node:timers\/promises['"];?\r?\n/gm,
    ''
  );

  if (updated !== content) {
    writeFileSync(file, updated, 'utf-8');
    fixed++;
    console.log('Fixed:', file);
  }
}

console.log(`\n✅ Cleaned inline node:timers/promises from ${fixed} Vue/TS files.`);

/**
 * @file generate_migrations.js
 * @description Generador automático de manifiesto de migraciones SQL.
 * 
 * UTILIDAD: 
 * Escanea el directorio 'database/migrations/' en busca de archivos .sql y los 
 * empaqueta en un único archivo JavaScript ('src/logic/db/migrations_data.ts').
 * 
 * IMPORTANCIA: 
 * Este script es el puente entre el diseño de base de datos (SQL) y la lógica de ejecución (JS).
 * Permite que el DBRouter ejecute actualizaciones de esquema de forma determinista tanto en 
 * Supabase como en el SQLite local, manteniendo la "Triple Fuente de Verdad".
 * 
 * Se ejecuta automáticamente durante el proceso de build y en Hot Update mediante Vite.
 */

import fs from 'node:fs/promises';
import path from 'node:path';


const MIGRATIONS_DIR = path.resolve(process.cwd(), 'database/migrations');
const OUTPUT_FILE = path.resolve(process.cwd(), 'src/logic/db/migrations_data.ts');

export async function generateMigrations() {
  console.log('[Migrations Generator] Scanning directory:', MIGRATIONS_DIR);

  try {
    await fs.access(MIGRATIONS_DIR);
  } catch {
    console.warn('[Migrations Generator] Migrations directory not found.');
    return;
  }

  // 1. Get all SQL files
  const list = await fs.readdir(MIGRATIONS_DIR);
  const files = list
    .filter(f => f.endsWith('.sql') && !f.includes('baseline_schema'))
    .sort((a, b) => a.localeCompare(b));

  const migrations = await Promise.all(files.map(async (filename) => {
    const id = filename.replace('.sql', '');
    const content = await fs.readFile(path.join(MIGRATIONS_DIR, filename), 'utf-8');

    // Parse metadata from comments
    // Example: -- check: { "table": "profiles", "column": "role" }
    let check = null;
    const checkMatch = content.match(/--\s*check:\s*({.+})/);
    if (checkMatch && checkMatch[1]) {
      try {
        check = JSON.parse(checkMatch[1]);
      } catch (e) {
        console.error(`[Migrations Generator] Error parsing check metadata in ${filename}:`, e);
      }
    }

    // Prepare SQL: remove comments and normalize newlines to keep it compact
    const sqlLines = content.split('\n')
      .map(line => {
        // Strip inline comments starting with --
        const commentIndex = line.indexOf('--');
        if (commentIndex !== -1) {
          // Keep part before comment, but only if it's not the 'check:' metadata line
          if (line.includes('check:')) return '';
          return line.substring(0, commentIndex);
        }
        return line;
      })
      .filter(line => line.trim().length > 0)
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim();

    return {
      id,
      sql: sqlLines,
      check
    };
  }));

  const output = `/**
 * AUTO-GENERATED FILE - DO NOT EDIT MANUALLY
 * Generated by scripts/generate_migrations.js
 * Last generated: ${Temporal.Now.instant().toString()}
 */

export const DATABASE_MIGRATIONS = ${JSON.stringify(migrations, null, 2)};
`;

  // Create directory if it doesn't exist
  const outputDir = path.dirname(OUTPUT_FILE);
  await fs.mkdir(outputDir, { recursive: true });

  {
    await using fileHandle = await fs.open(OUTPUT_FILE, 'w');
    await fileHandle.writeFile(output);
  }
  console.log(`[Migrations Generator] Generated ${migrations.length} migrations in ${OUTPUT_FILE}`);
}

// Support running directly
const isDirectRun = process.argv[1] && (
  process.argv[1].endsWith('generate_migrations.ts') ||
  process.argv[1].includes('generate_migrations.ts')
);

if (isDirectRun) {
  generateMigrations().catch(console.error);
}

/**
 * scripts/generate_move_translations.ts
 * 
 * MOVE TRANSLATION GENERATOR (Node.js 26+ Native)
 * Fetches spanish translations from PokeAPI and generates a static translation JSON map.
 * 
 * Usage: node --permission --experimental-strip-types --allow-fs-read=. --allow-fs-write=. --allow-net=pokeapi.co scripts/generate_move_translations.ts
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';

enableCompileCache();

interface PokeApiMoveListResponse {
  results: Array<{ name: string; url: string }>;
}

interface PokeApiMove {
  name: string;
  names: Array<{ name: string; language: { name: string } }>;
  flavor_text_entries?: Array<{
    flavor_text: string;
    language: { name: string };
    version_group: { name: string };
  }>;
}

const SHOWDOWN_DB_FILE = path.resolve(process.cwd(), 'showdown/sandbox_db/data/showdown_db.json');
const OUTPUT_FILE = path.resolve(process.cwd(), 'showdown/sandbox_db/data/move_translations.json');
const OUTPUT_DESC_FILE = path.resolve(process.cwd(), 'showdown/sandbox_db/data/move_descriptions.json');
const CACHE_DIR = path.resolve(process.cwd(), 'scripts/.cache');
const CACHE_FILE = path.join(CACHE_DIR, 'pokeapi_move_cache.json');

async function getPokeApiMoves(): Promise<PokeApiMove[]> {
  try {
    await fs.mkdir(CACHE_DIR, { recursive: true });
    const cacheExists = await fs.access(CACHE_FILE).then(() => true).catch(() => false);

    if (cacheExists) {
      console.log(styleText('blue', "ℹ️ Cargando movimientos de PokeAPI desde la caché..."));
      const content = await fs.readFile(CACHE_FILE, 'utf8');
      return JSON.parse(content) as PokeApiMove[];
    }
  } catch {
    console.log(styleText('yellow', "⚠️ No se pudo acceder a la caché de PokeAPI. Descargando de nuevo..."));
  }

  console.log(styleText('cyan', "🌐 Conectando con PokeAPI para descargar nombres en español (Gen 3)..."));

  try {
    // Gen 3 abarca los primeros 354 movimientos de la franquicia
    const response = await fetch('https://pokeapi.co/api/v2/move?limit=354');
    if (!response.ok) throw new Error(`Status: ${response.status}`);
    const listResp = await response.json() as PokeApiMoveListResponse;

    const results: PokeApiMove[] = [];
    const chunkSize = 20;

    for (let i = 0; i < listResp.results.length; i += chunkSize) {
      const chunk = listResp.results.slice(i, i + chunkSize);
      const promises = chunk.map(async (entry) => {
        const res = await fetch(entry.url);
        if (!res.ok) return null;
        return res.json() as Promise<PokeApiMove>;
      });

      const chunkResults = await Promise.all(promises);
      results.push(...chunkResults.filter((item): item is PokeApiMove => !!item));
      process.stdout.write(`Obtenidos ${Math.min(i + chunkSize, listResp.results.length)} / ${listResp.results.length}\r`);
    }

    console.log(styleText('green', "\n✅ Descarga de PokeAPI completada con éxito."));
    await fs.writeFile(CACHE_FILE, JSON.stringify(results, null, 2));
    return results;
  } catch (error) {
    console.error(styleText('red', `\n❌ Error al conectar con PokeAPI: ${(error as Error).message}`));
    return [];
  }
}

async function main() {
  console.log(styleText('bold', '\n--- 🔤 GENERADOR DE TRADUCCIONES Y DESCRIPCIONES DE MOVIMIENTOS ---'));

  try {
    await fs.access(SHOWDOWN_DB_FILE);
  } catch {
    console.error(styleText('red', `❌ No se encontró el archivo de base de datos de Showdown: ${SHOWDOWN_DB_FILE}`));
    process.exit(1);
  }

  const showdownDbRaw = await fs.readFile(SHOWDOWN_DB_FILE, 'utf8');
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const showdownDb = JSON.parse(showdownDbRaw) as any;
  const showdownMoves = Object.keys(showdownDb.moves || {});

  console.log(`📊 Movimientos detectados en Showdown Sandbox: ${showdownMoves.length}`);

  const apiMoves = await getPokeApiMoves();
  if (apiMoves.length === 0) {
    console.error(styleText('red', '❌ No se pudieron obtener datos de PokeAPI. Abortando.'));
    process.exit(1);
  }

  // Mapas de traducción y descripción
  const translations: Record<string, string> = {};
  const descriptions: Record<string, string> = {};

  // Mapeamos las traducciones usando normalización de nombres
  for (const move of apiMoves) {
    // Normalizar ID de PokeAPI eliminando guiones medios para coincidir con Showdown (ej. dragon-rage -> dragonrage)
    const showdownId = move.name.replace(/-/g, '').toLowerCase();

    // Obtener traducción en español
    const spanishNameEntry = move.names.find(n => n.language.name === 'es');
    if (spanishNameEntry) {
      translations[showdownId] = spanishNameEntry.name;
    }

    // Obtener descripción en español
    if (move.flavor_text_entries && move.flavor_text_entries.length > 0) {
      const spanishDescEntries = move.flavor_text_entries.filter(e => e.language.name === 'es');
      if (spanishDescEntries.length > 0) {
        // Tomamos la descripción más reciente/moderna (última en la lista)
        const lastEntry = spanishDescEntries[spanishDescEntries.length - 1];
        if (lastEntry) {
          const rawDesc = lastEntry.flavor_text;
          // Limpiamos saltos de página y de línea de PokeAPI
          const cleanDesc = rawDesc.replace(/[\n\f\r\t]/g, ' ').replace(/\s+/g, ' ').trim();
          descriptions[showdownId] = cleanDesc;
        }
      }
    }
  }

  // Agregamos traducciones especiales manuales que pueden variar en formato o traducción oficial
  const customOverrides: Record<string, string> = {
    'doubleedge': 'Doble Filo',
    'extremespeed': 'Velocidad Extrema',
    'selfdestruct': 'Autodestrucción',
    'willowisp': 'Fuego Fatuo',
    'sandtomb': 'Bucle Arena',
    'poisonfang': 'Colmillo Veneno',
    'meteorpunch': 'Puño Meteoro',
    'softboiled': 'Amortiguador',
    'smellingsalts': 'Estímulo',
    'hijumpkick': 'Patada Salto Alta',
    'featherdance': 'Danza Pluma',
    'vicegrip': 'Agarre',
    'sonicboom': 'Onda Sónica',
    'bubblebeam': 'Rayo Burbuja',
    'solarbeam': 'Rayo Solar',
    'poisonpowder': 'Polvo Veneno',
    'stunspore': 'Paralizador',
    'sleeppowder': 'Somnífera',
    'dragonrage': 'Furia Dragón',
    'superfang': 'Súper Colmillo',
    'dynamicpunch': 'Puño Dinámico',
    'ancientpower': 'Poder Pasado'
  };

  for (const [id, name] of Object.entries(customOverrides)) {
    translations[id] = name;
  }

  // Agregamos descripciones manuales en español si faltan o son mejores
  const customDescOverrides: Record<string, string> = {
    'grudge': 'Si el usuario se debilita, el ataque usado por el rival pierde todos sus PP.',
    'spite': 'Resta de 2 a 5 PP del último movimiento utilizado por el rival.',
    'snatch': 'Roba el efecto de cualquier movimiento curativo o de mejora de características del rival.',
    'recycle': 'Recupera un objeto consumible equipado para volver a usarlo.'
  };

  for (const [id, desc] of Object.entries(customDescOverrides)) {
    descriptions[id] = desc;
  }

  // Validamos si nos falta algún movimiento de Showdown sin traducir
  let missingCount = 0;
  let missingDescCount = 0;
  for (const moveId of showdownMoves) {
    if (!translations[moveId]) {
      // Intentar una coincidencia aproximada o formateo
      const formattedId = moveId.replace(/[^a-z0-9]/g, '');
      if (translations[formattedId]) {
        translations[moveId] = translations[formattedId]!;
      } else {
        missingCount++;
        // Colocar como fallback el nombre en inglés formateado de Showdown
        const showdownMove = showdownDb.moves[moveId];
        translations[moveId] = showdownMove ? showdownMove.name : moveId;
      }
    }

    if (!descriptions[moveId]) {
      const formattedId = moveId.replace(/[^a-z0-9]/g, '');
      if (descriptions[formattedId]) {
        descriptions[moveId] = descriptions[formattedId]!;
      } else {
        missingDescCount++;
        // Colocar como fallback el shortDesc de Showdown en inglés (saneado)
        const showdownMove = showdownDb.moves[moveId];
        const rawDesc = showdownMove ? (showdownMove.shortDesc || showdownMove.desc || '') : '';
        descriptions[moveId] = rawDesc.replace(/[\n\f\r\t]/g, ' ').replace(/\s+/g, ' ').trim();
      }
    }
  }

  // Guardar archivo final de traducción
  await fs.writeFile(OUTPUT_FILE, JSON.stringify(translations, null, 2), 'utf-8');

  // Guardar archivo final de descripciones
  await fs.writeFile(OUTPUT_DESC_FILE, JSON.stringify(descriptions, null, 2), 'utf-8');

  console.log(styleText('green', `\n💾 Archivo de traducciones guardado exitosamente en: \n   ${OUTPUT_FILE}`));
  console.log(styleText('green', `💾 Archivo de descripciones guardado exitosamente en: \n   ${OUTPUT_DESC_FILE}`));
  console.log(`✅ Nombres traducidos con éxito. Sin traducción (con fallback en inglés): ${missingCount}`);
  console.log(`✅ Descripciones localizadas con éxito. Sin descripción (con fallback en inglés): ${missingDescCount}`);
  console.log('🏁 Proceso finalizado.\n');
}

main().catch(err => {
  console.error(styleText('red', `\n💥 Error fatal: ${err.message}`));
  process.exit(1);
});

// scripts/import_backup_to_sqlite.ts
import { DatabaseSync } from 'node:sqlite';
import fs from 'node:fs';
import path from 'node:path';
import { TABLES_SCHEMA } from '../src/logic/db/schema.ts';
import { SHOP_ITEMS } from '../src/data/items.ts';

console.log('\n--- 📥 IMPORTADOR DE RESPALDOS A SQLITE LOCAL ---');

// 1. Obtener argumentos de línea de comandos y normalizar según el .env
const args = process.argv.slice(2);
let serverNameInput = 'official_prod';

for (const arg of args) {
  if (arg.startsWith('--server=')) {
    serverNameInput = arg.split('=')[1] || 'official_prod';
  }
}

// Normalizar usando el .env si existe
let serverName = serverNameInput;
const envPath = path.resolve(process.cwd(), '.env');
if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  const lines = envContent.split('\n');
  const serverConfigs: Record<string, Record<string, string>> = {};

  const KNOWN_SUFFIXES = [
    'SUPABASE_PUBLIC_URL', 'API_EXTERNAL_URL', 'SUPABASE_ANON_KEY',
    'SERVICE_ROLE_KEY', 'POSTGRES_PASSWORD', 'SECRET_KEY_BASE',
    'DASHBOARD_USERNAME', 'DASHBOARD_PASSWORD', 'KONG_HTTPS_PORT',
    'PG_META_CRYPTO_KEY', 'VAULT_ENC_KEY', 'DATABASE_URL',
    'JWT_SECRET', 'SUPABASE_URL', 'TENANT_ID', 'IS_DEFAULT',
    'ANON_KEY', 'SITE_URL', 'REGION', 'NAME', 'KEY', 'URL', 'ID',
  ];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match && match[1] !== undefined && match[2] !== undefined) {
      const fullKey = match[1].trim();
      let value = match[2].trim();
      if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      if (fullKey.startsWith('SERVER_')) {
        const withoutPrefix = fullKey.slice('SERVER_'.length);
        const matchedSuffix = KNOWN_SUFFIXES.find(s => withoutPrefix.endsWith(`_${s}`));
        if (matchedSuffix === undefined) continue;

        const profile = withoutPrefix.slice(0, withoutPrefix.length - matchedSuffix.length - 1);
        if (!profile) continue;

        const cleanKey = matchedSuffix;
        if (!serverConfigs[profile]) {
          serverConfigs[profile] = {};
        }
        const targetConf = serverConfigs[profile];
        if (targetConf) {
          targetConf[cleanKey] = value;
        }
      }
    }
  }

  // Buscar coincidencia por nombre de perfil o por ID
  let conf = serverConfigs[serverNameInput];
  if (!conf) {
    const found = Object.keys(serverConfigs).find(p => serverConfigs[p]?.ID === serverNameInput);
    if (found) conf = serverConfigs[found];
  }

  if (conf) {
    serverName = conf.ID || serverNameInput;
  }
}

const backupDir = path.resolve('database/backups', serverName);
if (!fs.existsSync(backupDir)) {
  console.error(`❌ Error: El directorio de backups para "${serverName}" no existe en ${backupDir}`);
  process.exit(1);
}

// 2. Buscar el archivo de backup más reciente
const files = fs.readdirSync(backupDir).filter(f => f.endsWith('.json'));
if (files.length === 0) {
  console.error(`❌ Error: No se encontraron archivos de backup (.json) en ${backupDir}`);
  process.exit(1);
}

// Ordenar archivos (por convención de nombre con timestamp, el último elemento es el más reciente)
files.sort();
const latestBackupFile = files[files.length - 1]!;
const backupPath = path.join(backupDir, latestBackupFile);

console.log(`📂 Respaldo detectado: ${latestBackupFile}`);

let backupContent: string;
try {
  backupContent = fs.readFileSync(backupPath, 'utf8');
} catch (err) {
  console.error(`❌ Error al leer el archivo de backup: ${(err as Error).message}`);
  process.exit(1);
}

let backupData: { data: Record<string, unknown[]> };
try {
  backupData = JSON.parse(backupContent);
} catch (err) {
  console.error(`❌ Error al parsear el archivo JSON: ${(err as Error).message}`);
  process.exit(1);
}

if (!backupData.data) {
  console.error('❌ Error: El backup no contiene una propiedad "data" válida.');
  process.exit(1);
}

// 3. Crear mapeo de IDs: UUID -> local_<username>
console.log('🔗 Generando diccionario de mapeo de IDs...');
const idMap = new Map<string, string>();
const profiles = backupData.data.profiles || [];

for (const profile of profiles as Array<{ id: string; username?: string; email?: string }>) {
  if (profile.id) {
    let cleanName = '';
    if (profile.username) {
      cleanName = profile.username.toLowerCase().replace(/\s+/g, '_');
    } else if (profile.email) {
      cleanName = profile.email.split('@')[0]!.toLowerCase().replace(/\s+/g, '_');
    } else {
      cleanName = profile.id.toLowerCase();
    }
    idMap.set(profile.id, `local_${cleanName}`);
  }
}
