/**
 * @file reportUtils.ts
 * @description Utilidades compartidas para formateo de reportes y salida de scripts de validación
 * del proyecto. Evita la duplicación de lógica de generación de archivos de reporte.
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';

export interface ValidationSummary {
  title: string;
  scannedMetrics: Record<string, number>;
  errors: string[];
  warnings: string[];
}

export function printConsoleHeader(title: string) {
  console.log(styleText('bold', `\n--- 🛡️  ${title} ---`));
}

export function printConsoleSummary(summary: ValidationSummary, verbose: boolean = true) {
  console.log(`\n════════════════════════════════════`);
  console.log(`    ${summary.title.toUpperCase()}`);
  console.log(`════════════════════════════════════`);
  for (const [key, value] of Object.entries(summary.scannedMetrics)) {
    console.log(`📦 ${key}: ${value}`);
  }
  console.log(`════════════════════════════════════\n`);

  if (!verbose) {
    console.log(styleText('cyan', `\n[INFO] Modo resumen activo: ${summary.errors.length} errores, ${summary.warnings.length} advertencias.`));
  } else {
    if (summary.warnings.length) {
      console.log(styleText('yellow', `⚠️  WARNINGS (${summary.warnings.length}):`));
      const limit = 30;
      summary.warnings.slice(0, limit).forEach(w => console.log(`   ${w}`));
      if (summary.warnings.length > limit) {
        console.log(styleText('cyan', `   ... y ${summary.warnings.length - limit} advertencias más (usa -o para ver todas)`));
      }
      console.log('');
    }

    if (summary.errors.length) {
      console.log(styleText('red', `❌ ERRORS (${summary.errors.length}):`));
      const limit = 30;
      summary.errors.slice(0, limit).forEach(e => console.log(`   ${e}`));
      if (summary.errors.length > limit) {
        console.log(styleText('cyan', `   ... y ${summary.errors.length - limit} errores más (usa -o para ver todos)`));
      }
      console.log('\n' + styleText('red', 'Corrige estos errores para asegurar la integridad de los datos.'));
    } else {
      console.log(styleText('green', '✅ Todos los componentes pasaron la validación con éxito!'));
    }
  }
}

export async function writeReportFile(outputPathArg: string, summary: ValidationSummary) {
  const outputPath = path.resolve(process.cwd(), outputPathArg);
  const metricLines = Object.entries(summary.scannedMetrics).map(([key, val]) => `${key}: ${val}`);

  const lines = [
    `--- ${summary.title.toUpperCase()} ---`,
    ...metricLines,
    `\nErrors (${summary.errors.length}):`,
    ...summary.errors.map(e => `  - ${e}`),
    `\nWarnings (${summary.warnings.length}):`,
    ...summary.warnings.map(w => `  - ${w}`)
  ];

  await fs.writeFile(outputPath, lines.join('\n'), 'utf-8');
  console.log(styleText('cyan', `\n✨ Reporte completo escrito en: ${outputPathArg}`));
}

/**
 * @file supabaseClient.ts
 * @description Helper compartido para leer el archivo .env maestro, parsear perfiles de servidor
 * y generar URLs de conexión de PostgreSQL consistentes entre scripts de administración.
 */

import fsPromises from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';

const ENV_FILE = path.resolve(process.cwd(), '.env');

export interface ServerConfig {
  SUPABASE_PUBLIC_URL?: string;
  API_EXTERNAL_URL?: string;
  SUPABASE_ANON_KEY?: string;
  SERVICE_ROLE_KEY?: string;
  POSTGRES_PASSWORD?: string;
  SECRET_KEY_BASE?: string;
  DASHBOARD_USERNAME?: string;
  DASHBOARD_PASSWORD?: string;
  KONG_HTTPS_PORT?: string;
  PG_META_CRYPTO_KEY?: string;
  VAULT_ENC_KEY?: string;
  DATABASE_URL?: string;
  JWT_SECRET?: string;
  SUPABASE_URL?: string;
  TENANT_ID?: string;
  IS_DEFAULT?: string;
  ANON_KEY?: string;
  SITE_URL?: string;
  REGION?: string;
  NAME?: string;
  KEY?: string;
  URL?: string;
  ID?: string;
  POSTGRES_PORT?: string;
  DB_PORT?: string;
  DB_PASSWORD?: string;
  POSTGRES_URL?: string;
  PG_URL?: string;
  [key: string]: string | undefined;
}

export async function readAndParseEnv(): Promise<Record<string, ServerConfig>> {
  try {
    await fsPromises.access(ENV_FILE);
  } catch {
    console.error(styleText('red', '❌ Error: Archivo .env maestro no encontrado.'));
    process.exit(1);
  }

  let envContent = '';
  try {
    // Uso de Explicit Resource Management (await using) para la lectura del .env
    await using fileHandle = await fsPromises.open(ENV_FILE, 'r');
    envContent = await fileHandle.readFile({ encoding: 'utf-8' });
  } catch (e: unknown) {
    console.error(styleText('red', `❌ Error al leer el archivo .env: ${(e as Error).message}`));
    process.exit(1);
  }

  const lines = envContent.split('\n');
  const serverConfigs: Record<string, ServerConfig> = {};

  const KNOWN_SUFFIXES = [
    'SUPABASE_PUBLIC_URL', 'API_EXTERNAL_URL', 'SUPABASE_ANON_KEY',
    'SERVICE_ROLE_KEY', 'POSTGRES_PASSWORD', 'SECRET_KEY_BASE',
    'DASHBOARD_USERNAME', 'DASHBOARD_PASSWORD', 'KONG_HTTPS_PORT',
    'PG_META_CRYPTO_KEY', 'VAULT_ENC_KEY', 'DATABASE_URL',
    'JWT_SECRET', 'SUPABASE_URL', 'TENANT_ID', 'IS_DEFAULT',
    'ANON_KEY', 'SITE_URL', 'REGION', 'NAME', 'KEY', 'URL', 'ID',
    'POSTGRES_PORT', 'DB_PORT', 'DB_PASSWORD', 'POSTGRES_URL', 'PG_URL'
  ];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match && match[1] !== undefined && match[2] !== undefined) {
      const fullKey = match[1].trim();
      let value = match[2].trim();

      if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      if (fullKey.startsWith('SERVER_')) {
        const withoutPrefix = fullKey.slice('SERVER_'.length);
        const matchedSuffix = KNOWN_SUFFIXES.find(s => withoutPrefix.endsWith(`_${s}`));
        if (matchedSuffix === undefined) continue;

        const profile = withoutPrefix.slice(0, withoutPrefix.length - matchedSuffix.length - 1);
        if (!profile) continue;

        const cleanKey = matchedSuffix;
        if (!serverConfigs[profile]) {
          serverConfigs[profile] = {};
        }
        const targetConf = serverConfigs[profile];
        if (targetConf) {
          targetConf[cleanKey] = value;
        }
      }
    }
  }

  return serverConfigs;
}

export function buildDatabaseUrl(conf: ServerConfig, canonicalName: string): string {
  let dbUrl = conf.DATABASE_URL || conf.POSTGRES_URL || conf.PG_URL || '';
  if (!dbUrl) {
    const pass = conf.POSTGRES_PASSWORD || conf.DB_PASSWORD || '';
    const rawPubUrl = conf.SUPABASE_PUBLIC_URL || conf.SUPABASE_URL || conf.SITE_URL || conf.API_EXTERNAL_URL || conf.URL || '';
    if (rawPubUrl && pass) {
      try {
        const u = new URL(rawPubUrl);
        let host = u.hostname;
        let port = '5432';
        if (host.endsWith('.supabase.co')) {
          const ref = conf.TENANT_ID || conf.POOLER_TENANT_ID || host.split('.')[0] || 'postgres';
          host = `db.${host.split('.')[0]}.supabase.co`;
          console.log(styleText('cyan', `🏷️  Tenant ID / Project Ref detectado para [${canonicalName}]: ${ref}`));
          dbUrl = `postgres://postgres:${encodeURIComponent(pass)}@${host}:${port}/postgres`;
        } else {
          port = conf.POSTGRES_PORT || conf.DB_PORT || '5432';
          const tenant = conf.TENANT_ID || conf.POOLER_TENANT_ID || 'your-tenant-id';
          console.log(styleText('cyan', `🏷️  Tenant ID detectado para [${canonicalName}]: ${tenant}`));
          dbUrl = `postgres://postgres.${tenant}:${encodeURIComponent(pass)}@${host}:${port}/postgres`;
        }
      } catch {
        // ignore
      }
    }
  }
  return dbUrl;
}

/**
 * scripts/migrate_temporal.ts
 * 
 * Script de migración masiva: Date -> Temporal API
 * 
 * Basado en los estándares del proyecto (Regla 7).
 */

import fs from 'node:fs/promises';
import path from 'node:path';

const IGNORE_DIRS = new Set(['node_modules', '.git', 'dist', '_raw-assets', 'scripts']);

async function getFilesToMigrate(dir: string): Promise<string[]> {
  const files: string[] = [];
  const pattern = '**/*.{ts,js,vue}';

  for await (const entry of fs.glob(pattern, { cwd: dir, exclude: (p) => Array.from(IGNORE_DIRS).some(d => p.includes(d)) })) {
    files.push(path.resolve(dir, entry));
  }
  return files;
}

async function migrate(filePath: string) {
  if (filePath.includes('migrate_temporal.ts')) {
    return;
  }
  let content = await fs.readFile(filePath, 'utf-8');
  const original = content;

  // 1. Date.now() -> Temporal.Now.instant().epochMilliseconds
  content = content.replace(/Date\.now\(\)/g, 'Temporal.Now.instant().epochMilliseconds');

  // 2. new Date() -> Temporal.Now.instant() (Sin argumentos)
  content = content.replace(/new Date\(\)/g, 'Temporal.Now.instant()');

  // 3. new Date(valor) -> Temporal.Instant.fromEpochMilliseconds(valor)
  content = content.replace(/new Date\(([^)]+)\)/g, (match, p1) => {
    if (p1.trim() === '') return match;
    return `Temporal.Instant.fromEpochMilliseconds(${p1})`;
  });

  // 4. .getTime() -> .epochMilliseconds
  content = content.replace(/\.getTime\(\)/g, '.epochMilliseconds');

  // 5. .toISOString() -> .toString() (Temporal usa toString() para ISO por defecto)
  content = content.replace(/\.toISOString\(\)/g, '.toString()');

  // 6. .toDateString() -> .toString().split('T')[0]
  content = content.replace(/\.toDateString\(\)/g, ".toString().split('T')[0]");

  // 7. date.toTemporalInstant() -> Temporal.Instant.fromEpochMilliseconds(date.epochMilliseconds || date.getTime())
  content = content.replace(/(\w+)\.toTemporalInstant\(\)/g, 'Temporal.Instant.fromEpochMilliseconds($1.epochMilliseconds || $1.getTime())');

  // 7. Inyectar import si se usa Temporal y no está presente
  if (content.includes('Temporal') && !content.includes("'@js-temporal/polyfill'")) {
    const importStmt = "\n";
    if (content.includes('<script')) {
      // Para archivos .vue
      content = content.replace(/(<script[^>]*>)/, `$1\n${importStmt}`);
    } else {
      // Para archivos .ts/.js
      content = importStmt + content;
    }
  }

  if (content !== original) {
    await fs.writeFile(filePath, content, 'utf-8');
    console.log(`[TEMPORAL] Migrado: ${filePath}`);
  }
}

async function main() {
  const targets = ['src', 'tests'];
  for (const t of targets) {
    const files = await getFilesToMigrate(path.join(process.cwd(), t));
    for (const file of files) {
      await migrate(file);
    }
  }
  console.log('\n✨ Migración a Temporal finalizada.');
}

main();

