  const analyzeVariantImage = async (
    varSourcePath: string,
    pokemonId: string,
    suffix: string
  ): Promise<AnimationAnalysisResult> => {
    const image = sharp(varSourcePath);
    const metadata = await image.metadata();
    const width = metadata.width || 0;
    const height = metadata.height || 0;

    if (width === 0 || height === 0) {
      throw new Error(`Dimensiones inválidas para ${varSourcePath}`);
    }

    const size = height;
    const totalFrames = Math.floor(width / size);

    // Extraer frames raw
    const frames: Buffer[] = [];
    for (let i = 0; i < totalFrames; i++) {
      const frameImg = image
        .clone()
        .extract({ left: i * size, top: 0, width: size, height: size });
      const frameBuffer = await frameImg.raw().toBuffer();
      frames.push(frameBuffer);
    }

    const areBuffersSimilar = (buf1: Buffer, buf2: Buffer, maxDiffPerPixel = 12, maxMismatchedPixelsPercent = 0.04): boolean => {
      if (buf1.length !== buf2.length) return false;
      let mismatches = 0;
      const numPixels = buf1.length / 4;
      const maxAllowedMismatches = numPixels * maxMismatchedPixelsPercent;

      for (let i = 0; i < buf1.length; i += 4) {
        const dr = Math.abs(buf1[i]! - buf2[i]!);
        const dg = Math.abs(buf1[i + 1]! - buf2[i + 1]!);
        const db = Math.abs(buf1[i + 2]! - buf2[i + 2]!);
        const da = Math.abs(buf1[i + 3]! - buf2[i + 3]!);

        if (dr > maxDiffPerPixel || dg > maxDiffPerPixel || db > maxDiffPerPixel || da > maxDiffPerPixel) {
          mismatches++;
          if (mismatches > maxAllowedMismatches) {
            return false;
          }
        }
      }
      return true;
    };

    // Calcular IDs únicos de frames
    const uniqueFrames: Buffer[] = [];
    const frameToUniqueId: number[] = [];

    for (let i = 0; i < totalFrames; i++) {
      const currentFrame = frames[i]!;
      let uniqueId = uniqueFrames.findIndex(uf => areBuffersSimilar(uf, currentFrame));
      if (uniqueId === -1) {
        uniqueId = uniqueFrames.length;
        uniqueFrames.push(currentFrame);
      }
      frameToUniqueId.push(uniqueId);
    }

    // Analizar secuencia de frames
    const total = frameToUniqueId.length;
    interface TransitionInfo {
      frameId: number;
      originalIndices: number[];
    }
    const transitions: TransitionInfo[] = [];
    for (let i = 0; i < total; i++) {
      const fId = frameToUniqueId[i]!;
      if (transitions.length === 0 || transitions[transitions.length - 1]!.frameId !== fId) {
        transitions.push({ frameId: fId, originalIndices: [i] });
      } else {
        transitions[transitions.length - 1]!.originalIndices.push(i);
      }
    }

    const transTotal = transitions.length;
    interface CandidateCycle {
      length: number;
      repeats: number;
      firstOccurrenceIndex: number;
      score?: number;
    }
    const candidates: CandidateCycle[] = [];

    for (let T = 2; T <= Math.floor(transTotal / 2); T++) {
      for (let startIdx = 0; startIdx <= transTotal - T * 2; startIdx++) {
        let isCycle = true;
        for (let i = 0; i < T; i++) {
          if (transitions[startIdx + i]!.frameId !== transitions[startIdx + i + T]!.frameId) {
            isCycle = false;
            break;
          }
        }
        if (isCycle) {
          let repeats = 2;
          while (startIdx + (repeats + 1) * T <= transTotal) {
            let match = true;
            for (let j = 0; j < T; j++) {
              if (transitions[startIdx + repeats * T + j]!.frameId !== transitions[startIdx + j]!.frameId) {
                match = false;
                break;
              }
            }
            if (match) {
              repeats++;
            } else {
              break;
            }
          }
          candidates.push({ length: T, repeats, firstOccurrenceIndex: startIdx });
        }
      }
    }

    if (candidates.length === 0) {
      let hasNonAdjacentDuplicates = false;
      for (let i = 0; i < totalFrames; i++) {
        for (let j = i + 2; j < totalFrames; j++) {
          if (areBuffersSimilar(frames[i]!, frames[j]!)) {
            hasNonAdjacentDuplicates = true;
            break;
          }
        }
        if (hasNonAdjacentDuplicates) break;
      }

      if (hasNonAdjacentDuplicates) {
        return {
          pokemonId,
          suffix,
          hasIdle: true,
          idleRange: [0, totalFrames - 1],
          attackRange: null,
          warning: `No se pudo detectar el ciclo de animación en ${varSourcePath}, pero existen frames no adyacentes duplicados. Se asume Idle completo.`
        };
      }

      return {
        pokemonId,
        suffix,
        hasIdle: true,
        idleRange: [0, totalFrames - 1],
        attackRange: null
      };
    }

    candidates.forEach(c => {
      let totalFramesInCycle = 0;
      for (let i = 0; i < c.length * c.repeats; i++) {
        const trans = transitions[c.firstOccurrenceIndex + i];
        if (trans) {
          totalFramesInCycle += trans.originalIndices.length;
        }
      }
      c.score = totalFramesInCycle;
    });

    candidates.sort((a, b) => ((b.score ?? 0) - (a.score ?? 0)) || b.repeats - a.repeats || b.length - a.length);
    const idleCandidate = candidates[0]!;

    const idleStart = 0;
    // const lastTransIdx = idleCandidate.firstOccurrenceIndex + (idleCandidate.length * idleCandidate.repeats) - 1;
    // const idleEnd = transitions[lastTransIdx]!.originalIndices[transitions[lastTransIdx]!.originalIndices.length - 1]!;

    const firstCycleEndTransIdx = idleCandidate.firstOccurrenceIndex + idleCandidate.length - 1;
    const firstCycleEnd = transitions[firstCycleEndTransIdx]!.originalIndices[transitions[firstCycleEndTransIdx]!.originalIndices.length - 1]!;

    const idleFramesSet = new Set<number>();
    for (let i = 0; i < idleCandidate.length; i++) {
      idleFramesSet.add(transitions[idleCandidate.firstOccurrenceIndex + i]!.frameId);
    }

    // El ataque comienza buscando desde el inicio (frame 0) para hacer trim de los idles iniciales y finales
    let s = 0;
    let e = total - 1;
    while (s <= e && idleFramesSet.has(frameToUniqueId[s]!)) {
      s++;
    }
    while (e >= s && idleFramesSet.has(frameToUniqueId[e]!)) {
      e--;
    }

    let attackRange: [number, number] | null = null;
    let warning: string | undefined;

    if (e >= s) {
      const attackLength = e - s + 1;
      if (attackLength <= 2) {
        // Descartar ataque de <= 2 frames y tratar como idle puro
        return {
          pokemonId,
          suffix,
          hasIdle: true,
          idleRange: [0, totalFrames - 1],
          attackRange: null
        };
      } else if (attackLength === 3) {
        warning = `Posible ataque falso corto de 3 frames (rango: ${s} a ${e})`;
        attackRange = [s, e];
      } else {
        attackRange = [s, e];
      }
    }

    return {
      pokemonId,
      suffix,
      hasIdle: true,
      idleRange: [idleStart, firstCycleEnd],
      attackRange,
      warning
    };
  };

  const runWorker = async () => {
    const name = path.parse(fileName).name;
    const match = name.match(/^(\d+)(.*)$/);
    if (!match) {
      parentPort?.postMessage({ success: true });
      return;
    }

    const pokemonId = match[1]!;
    const suffix = match[2]!;

    // Guard: skip files that are already processed outputs.
    // Output files have suffix starting with i, v, or a (idle/variation/attack).
    // Raw inputs may have: empty suffix, or suffixes starting with _ (e.g. _f, _m, _1, _1_f, _2_m)
    // or directly f/m for gender forms without underscore (e.g. 14f.png, 14m.png).
    if (/^[iva]/.test(suffix)) {
      parentPort?.postMessage({ success: true });
      return;
    }

    // 1. Analizar el Front principal para el reporte y coherencia
    const frontPath = path.join(FRONT_DIR, fileName);
    const frontAnalysis = await analyzeVariantImage(frontPath, pokemonId, suffix);

    // 2. Procesar variantes
    const folders = ['Front', 'Back', 'Front shiny', 'Back shiny'];

    const processVariant = async (folder: string): Promise<void> => {
      const varSourcePath = path.join(RAW_ASSETS_DIR, 'public', 'assets', 'sprites', 'pokemon', 'animated', folder, fileName);
      try {
        await fs.access(varSourcePath);
      } catch {
        return;
      }

      // Analizar esta variante de forma independiente
      const varAnalysis = await analyzeVariantImage(varSourcePath, pokemonId, suffix);

      const varImage = sharp(varSourcePath);
      const varMetadata = await varImage.metadata();
      const varWidth = varMetadata.width || 0;
      const varHeight = varMetadata.height || 0;
      if (varWidth === 0 || varHeight === 0) return;

      const varSize = varHeight;
      const varTotalFrames = Math.floor(varWidth / varSize);

      // Extraer los frames
      const varFrames: Buffer[] = [];
      for (let i = 0; i < varTotalFrames; i++) {
        const frameImg = varImage
          .clone()
          .extract({ left: i * varSize, top: 0, width: varSize, height: varSize });
        const frameBuffer = await frameImg.raw().toBuffer();
        varFrames.push(frameBuffer);
      }

      const processAndPadVarFrames = async (indices: number[]): Promise<Buffer[]> => {
        const paddedList: Buffer[] = [];
        for (const idx of indices) {
          const safeIdx = Math.min(idx, varFrames.length - 1);
          const padded = await sharp(varFrames[safeIdx], {
            raw: {
              width: varSize,
              height: varSize,
              channels: 4
            }
          })
          .extend({
            top: 1,
            bottom: 1,
            left: 1,
            right: 1,
            background: { r: 0, g: 0, b: 0, alpha: 0 }
          })
          .png()
          .toBuffer();
          paddedList.push(padded);
        }
        return paddedList;
      };

      const varNewSize = varSize + 2;
      const saveVarSpritesheet = async (paddedFrames: Buffer[], outputPath: string) => {
        const compositeInputs = paddedFrames.map((buf, index) => ({
          input: buf,
          left: index * varNewSize,
          top: 0
        }));

        await sharp({
          create: {
            width: varNewSize * paddedFrames.length,
            height: varNewSize,
            channels: 4,
            background: { r: 0, g: 0, b: 0, alpha: 0 }
          }
        })
        .composite(compositeInputs)
        .png()
        .toFile(outputPath);
      };

      // Guardar Idle para esta variante
      if (varAnalysis.hasIdle && varAnalysis.idleRange) {
        const [idleStart, idleEndIdx] = varAnalysis.idleRange;
        const idleIndices = Array.from({ length: idleEndIdx - idleStart + 1 }, (_, i) => idleStart + i);
        const paddedIdle = await processAndPadVarFrames(idleIndices);
        const idleOutPath = path.join(RAW_ASSETS_DIR, 'public', 'assets', 'sprites', 'pokemon', 'animated', folder, `${pokemonId}i${suffix}.png`);
        await saveVarSpritesheet(paddedIdle, idleOutPath);
      }

      // Guardar Variación única de la variante si tiene una propia detectada
      if (varAnalysis.attackRange !== null) {
        const varAtk = varAnalysis.attackRange;
        const attackIndices = Array.from({ length: varAtk[1] - varAtk[0] + 1 }, (_, i) => varAtk[0] + i);
        const paddedAttack = await processAndPadVarFrames(attackIndices);
        const attackOutPath = path.join(RAW_ASSETS_DIR, 'public', 'assets', 'sprites', 'pokemon', 'animated', folder, `${pokemonId}v${suffix}.png`);
        await saveVarSpritesheet(paddedAttack, attackOutPath);
      }

      // Always remove the original bare spritesheet after splitting into i/v files.
      // Leaving it in place (e.g. 14.png) would cause convert_assets to generate
      // 14.webp without suffix, which breaks the animated sprite database lookup.
      await fs.unlink(varSourcePath);
    };

    for (const f of folders) {
      await processVariant(f);
    }

    let extraDetails = '';
    if (frontAnalysis.attackRange !== null) {
      extraDetails = `Idle: frames ${frontAnalysis.idleRange[0]} a ${frontAnalysis.idleRange[1]}. Ataque: frames ${frontAnalysis.attackRange[0]} a ${frontAnalysis.attackRange[1]}`;
    } else {
      extraDetails = `Idle: frames ${frontAnalysis.idleRange[0]} a ${frontAnalysis.idleRange[1]}. Sin ataque.`;
    }

    parentPort?.postMessage({
      success: true,
      pokemonId,
      suffix,
      animationsFound: frontAnalysis.attackRange !== null ? 1 : 0,
      details: extraDetails,
      warning: frontAnalysis.warning
    });
  };

  runWorker().catch(err => {
    parentPort?.postMessage({ success: false, error: err.message });
  });
}

// -----------------------------------------------------------------------------
// CÓDIGO PRINCIPAL (ORQUESTADOR DE HILOS CON WORKER POOL)
// -----------------------------------------------------------------------------
if (isMainThread) {
  const extraAnimationsReport: { pokemonId: string; suffix: string; animationsFound: number; details: string }[] = [];
  const warningsReport: { pokemonId: string; suffix: string; warning: string }[] = [];

  const writeFinalReport = async (): Promise<void> => {
    const reportPath = path.join(SCRATCH_DIR, 'sprite_optimization_report.md');
    let mdContent = `# Reporte de Optimización de Animaciones\n\n`;
    mdContent += `Este reporte resume el procesamiento de spritesheets optimizados y detalla los Pokémon donde se detectaron 2 o más sub-animaciones de ataque o idles adicionales, o ataques sospechosos muy cortos.\n\n`;

    if (extraAnimationsReport.length === 0) {
      mdContent += `### ✅ No se encontraron animaciones adicionales complejas.\n`;
      mdContent += `Todos los spritesheets se dividieron correctamente en 1 Idle (\`i\`) y 1 Ataque (\`v\`).\n\n`;
    } else {
      mdContent += `## ⚠️ Pokémon con 2 o más animaciones detectadas:\n\n`;
      mdContent += `| Pokémon ID | Sufijo | Animaciones Totales | Detalles de Segmentación |\n`;
      mdContent += `| ---------- | ------ | ------------------- | ------------------------- |\n`;
      for (const item of extraAnimationsReport) {
        mdContent += `| **${item.pokemonId}** | \`${item.suffix || 'Ninguno'}\` | ${item.animationsFound} | ${item.details} |\n`;
      }
      mdContent += `\n`;
    }

    if (warningsReport.length > 0) {
      mdContent += `## 🔍 Alertas de ataques cortos (exactamente 3 frames):\n\n`;
      mdContent += `| Pokémon ID | Sufijo | Advertencia |\n`;
      mdContent += `| ---------- | ------ | ----------- |\n`;
      for (const item of warningsReport) {
        mdContent += `| **${item.pokemonId}** | \`${item.suffix || 'Ninguno'}\` | ${item.warning} |\n`;
      }
      mdContent += `\n`;
    }

    await fs.writeFile(reportPath, mdContent, 'utf-8');

    const files = await fs.readdir(FRONT_DIR);
    interface PokemonAnimData {
      id: string;
      suffix: string;
      idle: string | null;
      variation: string | null;
    }
    const manifestMap = new Map<string, PokemonAnimData>();

    for (const file of files) {
      if (!file.endsWith('.png')) continue;
      const name = path.parse(file).name;
      const idleMatch = name.match(/^(\d+)i(.*)$/);
      if (idleMatch) {
        const id = idleMatch[1]!;
        const suffix = idleMatch[2]!;
        const key = `${id}_${suffix}`;
        if (!manifestMap.has(key)) {
          manifestMap.set(key, { id, suffix, idle: null, variation: null });
        }
        manifestMap.get(key)!.idle = file;
        continue;
      }

      const varMatch = name.match(/^(\d+)v(.*)$/);
      if (varMatch) {
        const id = varMatch[1]!;
        const suffix = varMatch[2]!;
        const key = `${id}_${suffix}`;
        if (!manifestMap.has(key)) {
          manifestMap.set(key, { id, suffix, idle: null, variation: null });
        }
        manifestMap.get(key)!.variation = file;
      }
    }

    const sortedManifest = Array.from(manifestMap.values()).sort((a, b) => {
      const numA = parseInt(a.id, 10);
      const numB = parseInt(b.id, 10);
      if (numA !== numB) return numA - numB;
      return a.suffix.localeCompare(b.suffix);
    });

    const manifestPath = path.join(SCRATCH_DIR, 'sprites_manifest.json');
    await fs.writeFile(manifestPath, JSON.stringify(sortedManifest, null, 2), 'utf-8');

    const jsDataPath = path.join(SCRATCH_DIR, 'sprites_data.js');
    const jsContent = `var pokemonList = ${JSON.stringify(sortedManifest, null, 2)};`;
    await fs.writeFile(jsDataPath, jsContent, 'utf-8');
  };

  const main = async () => {
    const { values } = parseArgs({
      options: {
        all: { type: 'boolean', default: false },
        id: { type: 'string' },
        range: { type: 'string' },
        // NOTE: always true — leaving bare files (e.g. 14.png) without i/v suffix
        // corrupts the convert_assets pipeline which would generate 14.webp instead of 14i.webp
        'remove-original': { type: 'boolean', default: true }
      }
    });

    try {
      const files = await fs.readdir(FRONT_DIR);
      const targetFiles = files.filter(file => {
        if (!file.endsWith('.png')) return false;
        const name = path.parse(file).name;
        const match = name.match(/^(\d+)(.*)$/);
        if (!match) return false;
        const id = match[1]!;
        if (id === '0') return false;
        return true;
      });

      let filteredFiles = targetFiles;
      if (values.id) {
        filteredFiles = targetFiles.filter(file => {
          const name = path.parse(file).name;
          const match = name.match(/^(\d+)(.*)$/);
          if (!match) return false;
          const pid = match[1]!;
          const suffix = match[2]!;
          return pid === values.id || `${pid}${suffix}` === values.id;
        });
        console.log(`🎯 Filtrado por ID "${values.id}": ${filteredFiles.length} archivo(s) encontrado(s).`);
      } else if (values.range) {
        const [startStr, endStr] = values.range.split('-');
        const start = parseInt(startStr || '0', 10);
        const end = parseInt(endStr || '9999', 10);
        filteredFiles = targetFiles.filter(file => {
          const name = path.parse(file).name;
          const match = name.match(/^(\d+)(.*)$/);
          if (!match) return false;
          const pid = parseInt(match[1]!, 10);
          return pid >= start && pid <= end;
        });
        console.log(`🎯 Filtrado por Rango "${values.range}": ${filteredFiles.length} archivo(s) encontrado(s).`);
      }

      if (filteredFiles.length === 0) {
        console.log(`❌ No se encontraron archivos para procesar.`);
        process.exit(0);
      }

      if (!values.all && !values.id && !values.range) {
        console.log('Debes ejecutar con --all para procesamiento masivo, --id <id> para uno específico, o --range <inicio>-<fin> para un rango.');
        process.exit(0);
      }

      // Configuración de Hilos lógicos
      const numCPUs = os.cpus().length || 4;
      const workerPoolLimit = values.id ? 1 : numCPUs; 
      console.log(`🚀 Iniciando Worker Pool con límites de concurrencia: ${workerPoolLimit} hilo(s).`);

      let activeWorkers = 0;
      let completedCount = 0;
      let failedCount = 0;
      let hasErrors = false;
      let fileIndex = 0;

      const runNextWorker = () => {
        if (fileIndex >= filteredFiles.length) {
          if (activeWorkers === 0) {
            writeFinalReport().then(() => {
              if (hasErrors) {
                console.error(`\n❌ Proceso finalizado con ${failedCount} error(es) en hilos.`);
                process.exit(1);
              } else {
                console.log('\n🎉 ¡Procesamiento completado con éxito!');
                process.exit(0);
              }
            });
          }
          return;
        }

        const file = filteredFiles[fileIndex]!;
        fileIndex++;
        activeWorkers++;

        const worker = new Worker(__filename, {
          workerData: { fileName: file, removeOriginal: values['remove-original'] }
        });

        worker.on('message', (msg) => {
          if (msg.success) {
            completedCount++;
            if (msg.details) {
              extraAnimationsReport.push({
                pokemonId: msg.pokemonId,
                suffix: msg.suffix,
                animationsFound: msg.animationsFound,
                details: msg.details
              });
            }
            if (msg.warning) {
              warningsReport.push({
                pokemonId: msg.pokemonId,
                suffix: msg.suffix,
                warning: msg.warning
              });
            }
            console.log(`   [OK - HILO] Procesado con éxito: ${file} (${completedCount + failedCount}/${filteredFiles.length})`);

            // Actualizar DB en tiempo real al superar bloques de 32, o al final de listas cortas
            if (completedCount % 32 === 0 || filteredFiles.length < 32) {
              writeFinalReport().catch(() => {});
            }
          } else {
            hasErrors = true;
            failedCount++;
            console.error(`❌ Error en hilo procesando ${file}:`, msg.error);
          }
        });

        worker.on('error', (err) => {
          hasErrors = true;
          failedCount++;
          console.error(`❌ Error general de Worker para ${file}:`, err);
        });

        worker.on('exit', () => {
          activeWorkers--;
          runNextWorker();
        });
      };

      // Inundar la piscina de workers hasta el número total de CPUs/hilos lógicos del sistema (32 concurrentes)
      for (let w = 0; w < workerPoolLimit; w++) {
        runNextWorker();
      }

    } catch (err) {
      console.error('❌ Error general durante el procesamiento masivo:', err);
      process.exit(1);
    }
  };

  main().catch(err => {
    console.error('❌ Error crítico en main:', err);
    process.exit(1);
  });
}

/**
 * @file restore_supabase_db.ts
 * @description Script automático para restaurar un respaldo completo (backup) en formato JSON
 * hacia la base de datos Supabase elegida (nube o NAS), extrayendo credenciales y Tenant ID del .env maestro.
 * 
 * UTILIDAD:
 * Permite al usuario elegir un servidor (--server=<perfil>) y un archivo de respaldo opcional (--file=<ruta>).
 * Si no se especifica --file, detecta automáticamente el respaldo más reciente para ese servidor en database/backups/.
 * Realiza una limpieza limpia en orden inverso y restaura transaccionalmente todas las filas.
 * 
 * CUMPLE CON:
 * - Regla de Aislamiento y Parseo Multi-Servidor (env-multi-server-parser).
 * - Estándares Node.js 26+ (Explicit Resource Management con 'using', prefijos node:).
 * - Arquitectura Zero-Warning y Zero-Any.
 */

import fsPromises from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';
import postgres from 'postgres';
import { readAndParseEnv, buildDatabaseUrl } from './lib/supabaseClient.ts';

// Optimizar ejecución en ejecuciones sucesivas
enableCompileCache();

const BACKUPS_DIR = path.resolve(process.cwd(), 'database/backups');

export async function restoreSupabaseDb() {
  console.log(styleText('bold', '\n--- 🔄 SUPABASE DATABASE RESTORE MANAGER (Node.js 26+) ---'));

  const serverConfigs = await readAndParseEnv();
  const baseProfiles = Object.keys(serverConfigs);
  if (baseProfiles.length === 0) {
    console.error(styleText('red', '❌ Error: No se encontraron configuraciones de servidor (SERVER_<profile>_*) en el .env.'));
    process.exit(1);
  }

  const allAvailable = Array.from(new Set(baseProfiles.concat(Object.values(serverConfigs).map(c => c.ID).filter(Boolean) as string[])));

  // Parsear argumentos de la línea de comandos
  const args = process.argv.slice(2);
  let serverArg: string | undefined;
  const serverFlagIdx = args.findIndex(a => a === '--server');
  if (serverFlagIdx !== -1 && args[serverFlagIdx + 1] !== undefined) {
    serverArg = args[serverFlagIdx + 1];
  } else {
    serverArg = args.find(a => a.startsWith('--server='))?.split('=')[1];
  }

  let fileArg: string | undefined;
  const fileFlagIdx = args.findIndex(a => a === '--file');
  if (fileFlagIdx !== -1 && args[fileFlagIdx + 1] !== undefined) {
    fileArg = args[fileFlagIdx + 1];
  } else {
    fileArg = args.find(a => a.startsWith('--file='))?.split('=')[1];
  }

  if (!serverArg) {
    console.log(styleText('yellow', '⚠️  Especifica qué servidor deseas restaurar usando la bandera --server=<perfil>.'));
    console.log(styleText('cyan', `Perfiles disponibles: ${allAvailable.join(', ')}`));
    console.log(styleText('gray', 'Ejemplo: npm run servers:db:restore -- --server=nas_franco'));
    console.log(styleText('gray', 'Ejemplo con archivo específico: npm run servers:db:restore -- --server=nas_franco --file=database/backups/nas_franco_backup_...json'));
    process.exit(1);
  }

  const profile = serverArg;
  let conf = serverConfigs[profile];
  if (!conf) {
    const found = Object.keys(serverConfigs).find(p => serverConfigs[p]?.ID === profile);
    if (found) conf = serverConfigs[found];
  }
  if (!conf) {
    console.error(styleText('red', `❌ Error: El perfil o ID "${profile}" no existe en el archivo .env.`));
    process.exit(1);
  }

  const canonicalName = conf.ID || profile;

  console.log(styleText('bold', styleText('blue', `\n==================================================`)));
  console.log(styleText('bold', styleText('cyan', `🔄 INICIANDO RESTAURACIÓN DE BASE DE DATOS: [${canonicalName}]`)));
  console.log(styleText('bold', styleText('blue', `==================================================`)));

  // 1. Resolver archivo de respaldo a utilizar
  let targetBackupPath = fileArg ? path.resolve(process.cwd(), fileArg) : '';

  if (!targetBackupPath) {
    const serverBackupDir = path.join(BACKUPS_DIR, canonicalName);
    console.log(styleText('cyan', `🔍 Buscando archivo de respaldo más reciente para [${canonicalName}] en database/backups/${canonicalName}/...`));
    try {
      const files = await fsPromises.readdir(serverBackupDir);
      const matchingFiles = files
        .filter(f => f.startsWith(`${canonicalName}_backup_`) && f.endsWith('.json'))
        .sort()
        .reverse();

      if (matchingFiles.length === 0 || matchingFiles[0] === undefined) {
        console.error(styleText('red', `❌ Error: No se encontraron archivos de respaldo automáticos para "${canonicalName}" en ${serverBackupDir}.`));
        console.error(styleText('yellow', `👉 Ejecuta primero un respaldo con: npm run servers:db:backup -- --server=${canonicalName} o especifica --file=<ruta>`));
        process.exit(1);
      }

      targetBackupPath = path.join(serverBackupDir, matchingFiles[0]);
      console.log(styleText('green', `🏷️  Archivo de respaldo detectado automáticamente: ${matchingFiles[0]}`));
    } catch (rErr: unknown) {
      console.error(styleText('red', `❌ Error al inspeccionar el directorio de respaldos: ${(rErr as Error).message}`));
      process.exit(1);
    }
  } else {
    console.log(styleText('green', `🏷️  Archivo de respaldo especificado manualmente: ${fileArg}`));
  }

  // 2. Leer y validar archivo de respaldo
  let backupContent = '';
  try {
    await using backupHandle = await fsPromises.open(targetBackupPath, 'r');
    backupContent = await backupHandle.readFile({ encoding: 'utf-8' });
  } catch (bErr: unknown) {
    console.error(styleText('red', `❌ Error al leer el archivo de respaldo ${targetBackupPath}: ${(bErr as Error).message}`));
    process.exit(1);
  }

  interface BackupObject {
    metadata?: { profile?: string; timestamp?: string; totalTables?: number; totalRows?: number };
    data?: Record<string, Record<string, unknown>[]>;
    auth?: {
      users?: Record<string, unknown>[];
      identities?: Record<string, unknown>[];
    };
  }

  let backupObj: BackupObject;
  try {
    backupObj = JSON.parse(backupContent) as BackupObject;
    if (!backupObj.data || typeof backupObj.data !== 'object') {
      throw new Error('El archivo JSON no tiene la propiedad "data" estructurada.');
    }
  } catch (jErr: unknown) {
    console.error(styleText('red', `❌ Error: Archivo de respaldo JSON inválido o corrupto: ${(jErr as Error).message}`));
    process.exit(1);
  }

  const backupData = backupObj.data;
  const tableNames = Object.keys(backupData);
  console.log(styleText('cyan', `📦 Respaldo cargado en memoria: ${tableNames.length} tablas detectadas (Fecha de origen: ${backupObj.metadata?.timestamp || 'Desconocida'}).`));

  // 3. Construir URL de Conexión Postgres
  const dbUrl = buildDatabaseUrl(conf, canonicalName);

  if (!dbUrl) {
    console.error(styleText('red', `❌ Error: No se pudo construir la URL de conexión Postgres para el perfil "${canonicalName}".`));
    console.error(styleText('yellow', `👉 Asegúrate de tener SERVER_${profile}_POSTGRES_PASSWORD y SERVER_${profile}_SUPABASE_PUBLIC_URL en el .env`));
    process.exit(1);
  }

  if (dbUrl.includes('placeholder')) {
    console.error(styleText('red', `❌ Error: La contraseña para "${canonicalName}" es un placeholder. No se puede restaurar.`));
    process.exit(1);
  }

  const isSupabaseCloud = dbUrl.includes('.supabase.co');
  console.log(styleText('cyan', `🔌 Conectando al servidor Postgres de [${canonicalName}]...`));

  const sql = postgres(dbUrl, { ssl: isSupabaseCloud ? 'require' : false, max: 1 });

  try {
    // 3.5. Obtener lista de tablas existentes en el destino
    interface TableRow { table_name: string }
    interface LegacyPassiveBattleResult {
      id: string;
      attacker_id: string;
      defender_id: string;
      result: string;
      attacker_elo_change?: number;
      defender_elo_change?: number;
      created_at: string;
    }

    const tables = await sql<TableRow[]>`
      SELECT table_name 
      FROM information_schema.tables 
      WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
    `;
    const existingTables = new Set(tables.map(t => t.table_name));

    interface ColumnRow { table_name: string; column_name: string }
    const cols = await sql<ColumnRow[]>`
      SELECT table_name, column_name 
      FROM information_schema.columns 
      WHERE table_schema = 'public'
    `;
    const tableColumns = new Map<string, Set<string>>();
    for (const col of cols) {
      if (!tableColumns.has(col.table_name)) {
        tableColumns.set(col.table_name, new Set());
      }
      tableColumns.get(col.table_name)?.add(col.column_name);
    }

    interface AuthColumnRow { table_name: string; column_name: string; is_generated?: string; is_updatable?: string }
    const authCols = await sql<AuthColumnRow[]>`
      SELECT table_name, column_name, is_generated, is_updatable
      FROM information_schema.columns 
      WHERE table_schema = 'auth'
    `;
    const authTableColumns = new Map<string, Set<string>>();
    for (const col of authCols) {
      if (col.is_generated === 'ALWAYS') continue;
      if (col.is_updatable === 'NO') continue;
      if (col.table_name === 'identities' && col.column_name === 'email') continue;
      if (!authTableColumns.has(col.table_name)) {
        authTableColumns.set(col.table_name, new Set());
      }
      authTableColumns.get(col.table_name)?.add(col.column_name);
    }

    // Recolectar todos los user_ids del respaldo para asegurar su existencia en auth.users
    const backupUserIds = new Map<string, string>();
    const profileRows = backupData['profiles'] || [];
    for (const r of profileRows) {
      const userId = String(r.id || r.user_id || '');
      const email = String(r.email || `user_${userId}@test.com`);
      if (userId && userId.length === 36) {
        backupUserIds.set(userId, email);
      }
    }

    const userIdKeys = ['user_id', 'requester_id', 'addressee_id', 'sender_id', 'opponent_id', 'player_id', 'winner_id'];
    for (const tableName of tableNames) {
      const rows = backupData[tableName];
      if (!rows) continue;
      for (const r of rows) {
        for (const key of userIdKeys) {
          const val = String(r[key] || '');
          if (val && val.length === 36 && !backupUserIds.has(val)) {
            backupUserIds.set(val, `user_${val}@test.com`);
          }
        }
      }
    }

    // 4. Ordenar tablas por prioridad de dependencias (Padres primero para INSERT, Hijos primero para DELETE)
    const priorityOrder = ['system_config', '_migrations', 'events_config', 'profiles'];
    const orderedTables = [...tableNames].sort((a, b) => {
      const idxA = priorityOrder.indexOf(a);
      const idxB = priorityOrder.indexOf(b);
      if (idxA !== -1 && idxB !== -1) return idxA - idxB;
      if (idxA !== -1) return -1;
      if (idxB !== -1) return 1;
      return a.localeCompare(b);
    });

    console.log(styleText('yellow', `⚠️  Iniciando transacción de restauración. Se limpiarán las tablas existentes y se reinsertarán los datos del respaldo.`));

    await sql.begin(async (tx) => {
      // Paso A: Limpiar tablas públicas en orden inverso de dependencias (Hijos primero)
      const reverseOrderedTables = [...orderedTables].reverse();
      for (const tableName of reverseOrderedTables) {
        if (!existingTables.has(tableName)) {
          if (tableName === 'passive_battle_results' && existingTables.has('passive_battle_reports')) {
            try {
              await tx.unsafe(`DELETE FROM public.passive_battle_reports`);
              console.log(styleText('gray', `   🧹 Tabla passive_battle_reports (mapeada de passive_battle_results) limpiada correctamente.`));
            } catch (dErr: unknown) {
              console.error(styleText('yellow', `   ⚠️ Advertencia al limpiar tabla passive_battle_reports: ${(dErr as Error).message}`));
            }
          } else {
            console.log(styleText('yellow', `   ⚠️ Advertencia: La tabla "${tableName}" del respaldo no existe en el destino. Se omitirá la limpieza.`));
          }
          continue;
        }

        try {
          await tx.unsafe(`DELETE FROM public."${tableName}"`);
          console.log(styleText('gray', `   🧹 Tabla ${tableName} limpiada correctamente.`));
        } catch (dErr: unknown) {
          console.error(styleText('yellow', `   ⚠️ Advertencia al limpiar tabla ${tableName} (puede no existir o estar vacía): ${(dErr as Error).message}`));
        }
      }

      // Paso A.2: Limpiar tablas de auth si existe respaldo de auth para evitar conflictos
      const authBackup = backupObj.auth;
      const hasAuthBackup = authBackup && Array.isArray(authBackup.users) && authBackup.users.length > 0;
      if (hasAuthBackup) {
        try {
          console.log(styleText('cyan', `\n🧹 Limpiando tablas de autenticación en destino...`));
          await tx`DELETE FROM auth.identities`;
          console.log(styleText('gray', `   🧹 Tabla auth.identities limpiada correctamente.`));
          await tx`DELETE FROM auth.users`;
          console.log(styleText('gray', `   🧹 Tabla auth.users limpiada correctamente.`));
        } catch (cleanAuthErr: unknown) {
          console.error(styleText('yellow', `   ⚠️ Advertencia al limpiar tablas de auth: ${(cleanAuthErr as Error).message}`));
        }
      }

      // Paso A.5: Asegurar la existencia de todos los usuarios en auth.users y auth.identities
      if (hasAuthBackup && authBackup && Array.isArray(authBackup.users)) {
        console.log(styleText('cyan', `\n👤 Restaurando ${authBackup.users.length} usuarios auténticos en auth.users...`));
        const usersCols = authTableColumns.get('users');
        const emptyStringCols = new Set([
          'confirmation_token',
          'recovery_token',
          'email_change_token_new',
          'email_change',
          'email_change_token_current',
          'phone_change',
          'phone_change_token',
          'reauthentication_token'
        ]);

        if (usersCols) {
          for (const u of authBackup.users) {
            try {
              const cleanUser: Record<string, unknown> = {};
              for (const col of usersCols) {
                const val = u[col];
                if ((col === 'raw_app_meta_data' || col === 'raw_user_meta_data') && val !== null && val !== undefined) {
                  try {
                    cleanUser[col] = typeof val === 'string' ? JSON.parse(val) : val;
                  } catch {
                    cleanUser[col] = val;
                  }
                } else if (emptyStringCols.has(col)) {
                  cleanUser[col] = (val === null || val === undefined) ? '' : val;
                } else {
                  cleanUser[col] = val !== undefined ? val : null;
                }
              }
              const updateCols = Object.keys(cleanUser).filter(k => k !== 'id');
              await tx`
                INSERT INTO auth.users ${ tx(cleanUser) }
                ON CONFLICT (id) DO UPDATE SET ${ tx(cleanUser, ...updateCols) }
              `;
            } catch (authErr: unknown) {
              console.error(styleText('yellow', `   ⚠️ Advertencia al restaurar usuario ${u.id} (${u.email}): ${(authErr as Error).message}`));
            }
          }
        } else {
          console.error(styleText('red', '❌ Error: No se pudo obtener la definición de columnas para auth.users.'));
        }
      } else {
        console.log(styleText('cyan', `\n👤 Asegurando que todos los usuarios del respaldo (${backupUserIds.size}) existan en auth.users...`));
        for (const [userId, email] of backupUserIds.entries()) {
          try {
            await tx`
              INSERT INTO auth.users (id, email, aud, role, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous)
              VALUES (${userId}, ${email}, 'authenticated', 'authenticated', NOW(), '{}'::jsonb, '{}'::jsonb, false, false)
              ON CONFLICT (id) DO NOTHING
            `;
          } catch (authErr: unknown) {
            console.error(styleText('yellow', `   ⚠️ Advertencia al asegurar usuario ${userId} (${email}): ${(authErr as Error).message}`));
          }
        }
      }

      // Restaurar identidades si existen en el backup
      if (hasAuthBackup && authBackup && Array.isArray(authBackup.identities)) {
        console.log(styleText('cyan', `👤 Restaurando ${authBackup.identities.length} identidades de usuario en auth.identities...`));
        const idenCols = authTableColumns.get('identities');
        if (idenCols) {
          for (const iden of authBackup.identities) {
            try {
              const cleanIden: Record<string, unknown> = {};
              for (const col of idenCols) {
                const val = iden[col];
                if (col === 'identity_data' && val !== null && val !== undefined) {
                  try {
                    cleanIden[col] = typeof val === 'string' ? JSON.parse(val) : val;
                  } catch {
                    cleanIden[col] = val;
                  }
                } else {
                  cleanIden[col] = val !== undefined ? val : null;
                }
              }
              const updateCols = Object.keys(cleanIden).filter(k => k !== 'id');
              await tx`
                INSERT INTO auth.identities ${ tx(cleanIden) }
                ON CONFLICT (id) DO UPDATE SET ${ tx(cleanIden, ...updateCols) }
              `;
            } catch (idenErr: unknown) {
              console.error(styleText('yellow', `   ⚠️ Advertencia al restaurar identidad ${iden.id}: ${(idenErr as Error).message}`));
            }
          }
        } else {
          console.error(styleText('red', '❌ Error: No se pudo obtener la definición de columnas para auth.identities.'));
        }
      }

      console.log(styleText('green', `\n✨ Limpieza completada. Iniciando inserción de datos en orden jerárquico...`));

      // Paso B: Insertar filas en orden directo jerárquico (Padres primero)
      let totalRestoredRows = 0;
      for (const tableName of orderedTables) {
        let rows = backupData[tableName];
        if (!rows || rows.length === 0) {
          console.log(styleText('gray', `   ⏩ ${tableName}: 0 filas en el respaldo. Omitiendo.`));
          continue;
        }

        if (!existingTables.has(tableName)) {
          if (tableName === 'passive_battle_results' && existingTables.has('passive_battle_reports')) {
            console.log(styleText('cyan', `   🔄 Mapeando passive_battle_results a passive_battle_reports (${rows.length} filas)...`));
            const mappedRows = (rows as unknown as LegacyPassiveBattleResult[]).map((r) => ({
              id: r.id,
              user_id: r.attacker_id,
              opponent_id: r.defender_id,
              result: r.result,
              report_data: {
                attacker_elo_change: r.attacker_elo_change ?? 0,
                defender_elo_change: r.defender_elo_change ?? 0
              },
              created_at: r.created_at
            }));

            // Podar columnas inválidas para passive_battle_reports
            const validCols = tableColumns.get('passive_battle_reports');
            if (validCols) {
              for (const r of mappedRows) {
                for (const key of Object.keys(r)) {
                  if (!validCols.has(key)) {
                    delete (r as Record<string, unknown>)[key];
                  }
                }
              }
            }

            try {
              await tx`INSERT INTO public.passive_battle_reports ${tx(mappedRows)}`;
              totalRestoredRows += mappedRows.length;
              console.log(styleText('green', `   ✔️ passive_battle_reports (mapeada de passive_battle_results): ${mappedRows.length} filas restauradas exitosamente.`));
            } catch (iErr: unknown) {
              throw new Error(`Error al insertar en tabla adaptada "passive_battle_reports": ${(iErr as Error).message}`);
            }
          } else {
            console.log(styleText('yellow', `   ⏩ Tabla "${tableName}" no existe en el destino y no tiene mapeo. Omitiendo inserción.`));
          }
          continue;
        }

        // Podar columnas inválidas del respaldo que no existen en el destino
        const validCols = tableColumns.get(tableName);
        if (validCols) {
          rows = rows.map((r: Record<string, unknown>) => {
            const cleanRow: Record<string, unknown> = {};
            for (const key of Object.keys(r)) {
              if (validCols.has(key)) {
                cleanRow[key] = r[key];
              }
            }
            return cleanRow;
          });
        }

        try {
          await tx`INSERT INTO public.${tx(tableName)} ${tx(rows)}`;
          totalRestoredRows += rows.length;
          console.log(styleText('green', `   ✔️ ${tableName}: ${rows.length} filas restauradas exitosamente.`));
        } catch (iErr: unknown) {
          throw new Error(`Error al insertar en tabla "${tableName}": ${(iErr as Error).message}`);
        }
      }

      console.log(styleText('cyan', `\n🛡️ Asegurando privilegios de roles estándar en el esquema public...`));
      await tx`GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;`;
      await tx`GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO postgres, service_role;`;
      await tx`GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO anon, authenticated;`;
      await tx`GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO postgres, service_role;`;
      await tx`GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated;`;
      await tx`GRANT ALL PRIVILEGES ON ALL FUNCTIONS IN SCHEMA public TO postgres, service_role;`;
      await tx`GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO anon, authenticated;`;
      console.log(styleText('green', `   ✔️ Privilegios restablecidos correctamente.`));

      console.log(styleText('bold', styleText('green', `\n🎉 Transacción completada con éxito. ${totalRestoredRows} filas totales restauradas en [${canonicalName}].`)));
    });

    await sql.end();
  } catch (restErr: unknown) {
    console.error(styleText('red', `\n❌ Error fatal durante la restauración en [${canonicalName}]: ${(restErr as Error).message}`));
    console.error(styleText('yellow', `🔄 La transacción ha sido revertida (ROLLBACK automático). La base de datos mantiene su estado anterior.`));
    try { await sql.end(); } catch { /* ignore */ }
    process.exit(1);
  }
}

// Permitir ejecución directa
const isDirectRun = process.argv[1] && (
  process.argv[1].endsWith('restore_supabase_db.ts') ||
  process.argv[1].includes('restore_supabase_db.ts')
);

if (isDirectRun) {
  restoreSupabaseDb().catch((err) => {
    console.error(styleText('red', `❌ Error fatal: ${err.message}`));
    process.exit(1);
  });
}

import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { execSync } from 'node:child_process';

// Define directories relative to this script
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const SOURCE_DIR = path.resolve(__dirname, '..');
const TARGET_DIR = path.resolve(SOURCE_DIR, '..', 'pokevicio-test');

const DIRECTORIES_TO_COPY: string[] = [
  'api',
  path.join('database', 'migrations'),
  'public',
  'scripts',
  'src'
];

const FILES_TO_COPY: string[] = [
  'package.json',
  'package-lock.json',
  'vite.config.ts',
  'tsconfig.json',
  'tsconfig.app.json',
  'tsconfig.node.json',
  'index.html',
  '.gitignore',
  '.env.example',
  'eslint.config.js',
  '.prettierrc',
  '.markdownlint.json',
  'README.md',
  path.join('tests', 'vitest.setup.ts')
];

const PRESERVED_PATTERNS: string[] = [
  '.git',
  '.github'
];

function shouldPreserve(name: string): boolean {
  return PRESERVED_PATTERNS.includes(name) || name.startsWith('.git') || name.startsWith('.github');
}

async function copyRecursive(src: string, dest: string, ignoreFilter?: (p: string) => boolean): Promise<void> {
  if (ignoreFilter && ignoreFilter(src)) {
    return;
  }
  const stat = await fs.stat(src);
  if (stat.isDirectory()) {
    await fs.mkdir(dest, { recursive: true });
    const entries = await fs.readdir(src, { withFileTypes: true });
    for (const entry of entries) {
      await copyRecursive(
        path.join(src, entry.name),
        path.join(dest, entry.name),
        ignoreFilter
      );
    }
  } else {
    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.copyFile(src, dest);
  }
}

async function main(): Promise<void> {
  console.log(`\n🚀 Starting Sync PokeBorrador -> pokevicio-test`);
  console.log(`Source: ${SOURCE_DIR}`);
  console.log(`Target: ${TARGET_DIR}\n`);

  // 1. Validate Source Path
  try {
    await fs.access(SOURCE_DIR);
  } catch (_err) {
    console.error(`❌ Error: Source directory ${SOURCE_DIR} does not exist.`);
    process.exit(1);
  }

  // 2. Validate Target Path (and clone if it does not exist)
  try {
    await fs.access(TARGET_DIR);
  } catch {
    console.log(`📡 Target directory pokevicio-test not found. Cloning repository...`);
    try {
      const parentDir = path.resolve(SOURCE_DIR, '..');
      execSync('git clone git@github.com:francogp/pokevicio-test.git pokevicio-test', {
        cwd: parentDir,
        stdio: 'inherit'
      });
      console.log(`✅ Clone completed successfully.`);
    } catch (err) {
      console.error(`❌ Failed to clone repository:`, err);
      process.exit(1);
    }
  }

  // 3. Clean target directory
  console.log(`🧹 Cleaning target directory (preserving Git files)...`);
  const targetEntries = await fs.readdir(TARGET_DIR, { withFileTypes: true });
  for (const entry of targetEntries) {
    if (shouldPreserve(entry.name)) {
      console.log(`   [PRESERVED] ${entry.name}`);
      continue;
    }
    const fullPath = path.join(TARGET_DIR, entry.name);
    console.log(`   [DELETE] ${entry.name}`);
    await fs.rm(fullPath, { recursive: true, force: true });
  }

  // 4. Copy directories
  console.log(`\n📂 Copying folders...`);
  const ignoreFilter = (srcPath: string): boolean => {
    const rel = path.relative(SOURCE_DIR, srcPath);
    // Ignore .cache folder in scripts
    if (rel.split(path.sep).includes('.cache')) {
      return true;
    }
    return false;
  };

  for (const dir of DIRECTORIES_TO_COPY) {
    const srcPath = path.join(SOURCE_DIR, dir);
    const destPath = path.join(TARGET_DIR, dir);
    try {
      await fs.access(srcPath);
      console.log(`   [COPY DIR] ${dir}`);
      await copyRecursive(srcPath, destPath, ignoreFilter);
    } catch {
      console.warn(`   [WARNING] Directory ${dir} not found, skipping.`);
    }
  }

  // 5. Copy files
  console.log(`\n📄 Copying files...`);
  for (const file of FILES_TO_COPY) {
    const srcPath = path.join(SOURCE_DIR, file);
    const destPath = path.join(TARGET_DIR, file);
    try {
      await fs.access(srcPath);
      console.log(`   [COPY FILE] ${file}`);
      await copyRecursive(srcPath, destPath);
    } catch {
      console.warn(`   [WARNING] File ${file} not found, skipping.`);
    }
  }

  console.log(`\n✨ Sync completed successfully!\n`);
}

main().catch(err => {
  console.error(`❌ Error during sync:`, err);
  process.exit(1);
});

/**
 * @file update_supabase_db.ts
 * @description Script automático para acceder a los servidores Supabase y gestionar la base de datos.
 * 
 * UTILIDAD:
 * 1. Consultar si existen las tablas del juego en el servidor Supabase seleccionado.
 * 2. Si no existen, crear toda la base de datos de cero ejecutando el baseline_schema.
 * 3. Si existen, aplicar los parches (migraciones) necesarios de forma incremental y segura.
 * 
 * CARACTERÍSTICAS:
 * - Permite elegir actualizar TODOS los servidores o uno en particular (--server=<perfil> o --all).
 * - Cumple con las normativas env-multi-server-parser para extraer credenciales del .env maestro.
 * - Estándares Node.js 26+ (Explicit Resource Management con 'using', prefijos node:).
 */

import fsPromises from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';
import postgres from 'postgres';
import { readAndParseEnv, buildDatabaseUrl } from './lib/supabaseClient.ts';

// Optimizar ejecución en ejecuciones sucesivas
enableCompileCache();

const MIGRATIONS_DIR = path.resolve(process.cwd(), 'database/migrations');
const BASELINE_FILE = path.resolve(process.cwd(), 'database/migrations/20240416000000_baseline_schema.sql');

export async function updateSupabaseDb() {
  console.log(styleText('bold', '\n--- 🛡️ SUPABASE DATABASE MANAGER & MIGRATOR (Node.js 26+) ---'));

  const serverConfigs = await readAndParseEnv();
  const baseProfiles = Object.keys(serverConfigs);
  if (baseProfiles.length === 0) {
    console.error(styleText('red', '❌ Error: No se encontraron configuraciones de servidor (SERVER_<profile>_*) en el .env.'));
    process.exit(1);
  }

  const allAvailable = Array.from(new Set(baseProfiles.concat(Object.values(serverConfigs).map(c => c.ID).filter(Boolean) as string[])));

  // Parsear argumentos de la línea de comandos
  const args = process.argv.slice(2);
  let serverArg: string | undefined;
  const serverFlagIdx = args.findIndex(a => a === '--server');
  if (serverFlagIdx !== -1 && args[serverFlagIdx + 1] !== undefined) {
    serverArg = args[serverFlagIdx + 1];
  } else {
    serverArg = args.find(a => a.startsWith('--server='))?.split('=')[1];
  }
  const isAll = args.includes('--all');

  if (!serverArg && !isAll) {
    console.log(styleText('yellow', '⚠️  Especifica qué servidor deseas actualizar usando la bandera --server=<perfil> o --all.'));
    console.log(styleText('cyan', `Perfiles disponibles: ${allAvailable.join(', ')}`));
    console.log(styleText('gray', 'Ejemplo: npm run servers:db:update -- --server=cloud'));
    console.log(styleText('gray', 'Ejemplo: npm run servers:db:update -- --server=nas_franco'));
    console.log(styleText('gray', 'Ejemplo: npm run servers:db:update -- --all'));
    process.exit(1);
  }

  const targetProfiles = serverArg ? [serverArg] : baseProfiles;

  for (const profile of targetProfiles) {
    let conf = serverConfigs[profile];
    if (!conf) {
      const found = Object.keys(serverConfigs).find(p => serverConfigs[p]?.ID === profile);
      if (found) conf = serverConfigs[found];
    }
    if (!conf) {
      console.error(styleText('red', `❌ Error: El perfil o ID "${profile}" no existe en el archivo .env.`));
      continue;
    }

    console.log(styleText('bold', styleText('blue', `\n==================================================`)));
    console.log(styleText('bold', styleText('cyan', `🚀 INICIANDO ACTUALIZACIÓN DE BASE DE DATOS: [${profile}]`)));
    console.log(styleText('bold', styleText('blue', `==================================================`)));

    const dbUrl = buildDatabaseUrl(conf, profile);

    if (!dbUrl) {
      console.error(styleText('red', `❌ Error: No se pudo construir la URL de conexión Postgres para el perfil "${profile}".`));
      console.error(styleText('yellow', `👉 Asegúrate de tener SERVER_${profile}_POSTGRES_PASSWORD y SERVER_${profile}_SUPABASE_PUBLIC_URL en el .env`));
      continue;
    }

    const isSupabaseCloud = dbUrl.includes('.supabase.co');
    const sql = postgres(dbUrl, { ssl: isSupabaseCloud ? 'require' : false, max: 1 });

    try {
      console.log(styleText('cyan', `🔌 Conectando al servidor Postgres de [${profile}]...`));

      // 1. Consultar si existen las tablas del juego
      const tables = await sql`
        SELECT table_name 
        FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name IN ('profiles', 'system_config', '_migrations')
      `;

      const existingTables = tables.map(t => t.table_name as string);
      console.log(styleText('cyan', `📊 Tablas detectadas en el esquema public: ${existingTables.length > 0 ? existingTables.join(', ') : 'Ninguna'}`));

      let baselineContent = '';
      try {
        await using baseHandle = await fsPromises.open(BASELINE_FILE, 'r');
        baselineContent = await baseHandle.readFile({ encoding: 'utf-8' });
      } catch (baseErr: unknown) {
        console.error(styleText('red', `❌ Error al leer baseline_schema.sql: ${(baseErr as Error).message}`));
        process.exit(1);
      }

      if (existingTables.length === 0) {
        // 2. Si no existen, crear toda la base de datos de cero
        console.log(styleText('yellow', `⚠️  Base de datos limpia detectada en [${profile}]. Inicializando esquema base desde cero...`));
        console.log(styleText('gray', `📄 Ejecutando: 20240416000000_baseline_schema.sql`));

        await sql.unsafe(baselineContent);
        console.log(styleText('green', `✅ Esquema base creado exitosamente en [${profile}].`));

        await sql`CREATE TABLE IF NOT EXISTS public._migrations (id TEXT PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT NOW())`;
        await sql`INSERT INTO public._migrations (id) VALUES ('20240416000000_baseline_schema') ON CONFLICT DO NOTHING`;
      } else {
        console.log(styleText('green', `✅ Esquema base ya existe en [${profile}]. Procediendo a verificar parches...`));
        await sql`CREATE TABLE IF NOT EXISTS public._migrations (id TEXT PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT NOW())`;
      }

      // 3. Si existe, aplicar los parches necesarios
      const appliedRows = await sql`SELECT id FROM public._migrations`;
      const appliedIds = new Set(appliedRows.map(r => r.id as string));

      const files = (await fsPromises.readdir(MIGRATIONS_DIR))
        .filter(f => f.endsWith('.sql') && !f.includes('baseline_schema'))
        .sort((a, b) => a.localeCompare(b));

      let patchesApplied = 0;

      for (const filename of files) {
        const migrationId = filename.replace('.sql', '');
        if (!appliedIds.has(migrationId)) {
          console.log(styleText('cyan', `📦 Aplicando parche: ${filename}...`));
          const filePath = path.join(MIGRATIONS_DIR, filename);
          let migContent = '';
          try {
            await using migHandle = await fsPromises.open(filePath, 'r');
            migContent = await migHandle.readFile({ encoding: 'utf-8' });
          } catch (mErr: unknown) {
            console.error(styleText('red', `❌ Error al leer archivo de migración ${filename}: ${(mErr as Error).message}`));
            continue;
          }

          let sqlContent = migContent;
          // Adaptar dialecto SQLite a Postgres para manipulación de texto sobre columnas TIMESTAMPTZ y dependencias CASCADE
          sqlContent = sqlContent.replace(/created_at NOT LIKE/g, "CAST(created_at AS TEXT) NOT LIKE");
          sqlContent = sqlContent.replace(/SET created_at = REPLACE\(created_at, ' ', 'T'\) \|\| 'Z'/g, "SET created_at = CAST(REPLACE(CAST(created_at AS TEXT), ' ', 'T') || 'Z' AS TIMESTAMPTZ)");
          sqlContent = sqlContent.replace(/DROP TABLE IF EXISTS events_config;/g, "DROP TABLE IF EXISTS events_config CASCADE;");

          try {
            await sql.begin(async (tx) => {
              await tx.unsafe(sqlContent);
              await tx`INSERT INTO public._migrations (id) VALUES (${migrationId})`;
            });
            console.log(styleText('green', `   ✅ Parche ${migrationId} aplicado correctamente.`));
            patchesApplied++;
          } catch (patchErr: unknown) {
            const pMsg = patchErr instanceof Error ? patchErr.message : String(patchErr);
            if (pMsg.toLowerCase().includes('already exists') || pMsg.toLowerCase().includes('duplicate')) {
              console.log(styleText('yellow', `   ⚠️ Parche ${migrationId} ya estaba aplicado parcialmente (duplicado benigno). Registrando como completado.`));
              await sql`INSERT INTO public._migrations (id) VALUES (${migrationId}) ON CONFLICT DO NOTHING`;
              patchesApplied++;
            } else {
              throw patchErr;
            }
          }
        }
      }

      // 4. Sincronizar db_version en system_config con la migración más reciente aplicada
      const allAppliedRows = await sql`SELECT id FROM public._migrations`;
      const versions = allAppliedRows
        .map(r => parseInt((r.id as string).split('_')[0] || '0'))
        .filter(v => v > 0);
      if (versions.length > 0) {
        const maxAppliedVersion = Math.max(...versions);
        console.log(styleText('cyan', `🔄 Sincronizando db_version en system_config de [${profile}] a la versión: ${maxAppliedVersion}`));
        await sql`
          INSERT INTO public.system_config (key, value) 
          VALUES ('db_version', ${maxAppliedVersion}::jsonb) 
          ON CONFLICT (key) 
          DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
        `;
      }

      // 5. Sincronizar app_version en system_config
      let appVersion = 'v0.5.0';
      try {
        const verPath = path.resolve(process.cwd(), 'public/version.json');
        const verContent = JSON.parse(await fsPromises.readFile(verPath, 'utf-8'));
        if (verContent && verContent.version) {
          appVersion = verContent.version;
        }
      } catch (_e) {
        // Fallback
      }
      console.log(styleText('cyan', `🔄 Sincronizando app_version en system_config de [${profile}] a la versión: ${appVersion}`));
      await sql`
        INSERT INTO public.system_config (key, value) 
        VALUES ('app_version', ${appVersion}::jsonb) 
        ON CONFLICT (key) 
        DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
      `;

      if (patchesApplied === 0) {
        console.log(styleText('green', `✨ La base de datos de [${profile}] ya está completamente actualizada. No se requieren parches.`));
      } else {
        console.log(styleText('green', `✨ Proceso completado en [${profile}]: ${patchesApplied} parches aplicados exitosamente.`));
      }

    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(styleText('red', `❌ Error al conectar o migrar la base de datos de [${profile}]: ${msg}`));
      if (msg.includes('password authentication failed') || msg.includes('placeholder')) {
        console.error(styleText('yellow', `👉 Advertencia: SERVER_${profile}_POSTGRES_PASSWORD parece ser un placeholder o es incorrecta.`));
        console.error(styleText('yellow', `👉 Configura la contraseña real en el archivo .env para poder aplicar migraciones en este servidor.`));
      }
      if (msg.toLowerCase().includes('tenant or user not found')) {
        console.error(styleText('yellow', `👉 Advertencia: El servidor proxy/pooler (Supavisor) rechazó la conexión por falta de Tenant ID.`));
        console.error(styleText('yellow', `👉 Configura SERVER_${profile}_DATABASE_URL con la cadena de conexión directa (ej. puerto 5432 directo o usuario postgres.<tenant>) en .env`));
      }
    } finally {
      await sql.end();
    }
  }
}

const isDirectRun = process.argv[1] && (
  process.argv[1].endsWith('update_supabase_db.ts') ||
  process.argv[1].includes('update_supabase_db.ts')
);

if (isDirectRun) {
  updateSupabaseDb().catch((err) => {
    console.error(styleText('red', `❌ Error fatal: ${err.message}`));
    process.exit(1);
  });
}

/**
 * scripts/validate_abilities.ts
 * 
 * ABILITY INTEGRITY VALIDATOR (Node.js 26+)
 * Validates integrity of POKEMON_ABILITIES and ABILITY_DATA against PokeAPI.
 * 
 * Usage: npm run validate:abilities
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { setupValidation } from './lib/validationBase.ts';

interface PokeApiListResponse {
  results: Array<{ name: string; url: string }>;
}

interface NameEntry {
  name: string;
  language: { name: string };
}

interface FlavorTextEntry {
  flavor_text: string;
  language: { name: string };
}

interface PokeApiAbility {
  name: string;
  names: NameEntry[];
  flavor_text_entries: FlavorTextEntry[];
}

const DATA_FILE = path.resolve(process.cwd(), 'src/data/abilities.ts');
const CACHE_DIR = path.resolve(process.cwd(), 'scripts/.cache');
const CACHE_FILE = path.join(CACHE_DIR, 'pokeapi_ability_cache.json');

async function getPokeApiAbilities(): Promise<PokeApiAbility[]> {
  try {
    const cacheExists = await fs.access(CACHE_FILE).then(() => true).catch(() => false);
    if (cacheExists) {
      console.log(styleText('blue', "ℹ️ Cargando habilidades de PokeAPI desde la caché..."));
      return JSON.parse(await fs.readFile(CACHE_FILE, 'utf8')) as PokeApiAbility[];
    }
    await fs.mkdir(CACHE_DIR, { recursive: true });
  } catch {
    // Silently fail and fetch if cache error
  }

  console.log(styleText('cyan', "🌐 Obteniendo habilidades de PokeAPI (esto puede tardar unos segundos)..."));

  try {
    const response = await fetch('https://pokeapi.co/api/v2/ability?limit=350');
    if (!response.ok) throw new Error(`Status: ${response.status}`);
    const listResp = await response.json() as PokeApiListResponse;

    const results: PokeApiAbility[] = [];
    const chunkSize = 20;

    for (let i = 0; i < listResp.results.length; i += chunkSize) {
      const chunk = listResp.results.slice(i, i + chunkSize);
      const promises = chunk.map(async (entry: { url: string }) => {
         const res = await fetch(entry.url);
         if (!res.ok) return null;
         return res.json() as Promise<PokeApiAbility>;
      });

      const chunkResults = await Promise.all(promises);
      results.push(...chunkResults.filter((item): item is PokeApiAbility => !!item));
      process.stdout.write(`Obtenidas ${Math.min(i + chunkSize, listResp.results.length)} / ${listResp.results.length}\r`);
    }

    console.log(styleText('green', "\n✅ Descarga de habilidades completada."));
    await fs.writeFile(CACHE_FILE, JSON.stringify(results, null, 2));
    return results;
  } catch (error: unknown) {
    console.error(styleText('red', `\n❌ Error al conectar con PokeAPI: ${(error as Error).message}`));
    console.log(styleText('yellow', "⚠️ Continuando validación solo con datos locales..."));
    return [];
  }
}

async function main() {
  const validator = setupValidation({
    title: 'POKEMON ABILITY VALIDATOR',
    requiredFiles: [DATA_FILE]
  });

  await validator.checkFiles();

  const content = await fs.readFile(DATA_FILE, 'utf8');

  // 1. Extract ABILITY_DATA (descriptions)
  const abilityData: Record<string, string> = {};
  const dataBlockMatch = content.match(/export const ABILITY_DATA = {([\s\S]+?)\n};/);
  if (dataBlockMatch) {
    const block = dataBlockMatch[1]!;
    const entryRegex = /'([^']+)':\s*{\s*desc:\s*'([^']+)'\s*}/g;
    let m;
    while ((m = entryRegex.exec(block)) !== null) {
      abilityData[m[1]!] = m[2]!;
    }
  }

  // 2. Extract POKEMON_ABILITIES (assignments)
  const gameAbilities = new Set<string>();
  const assignmentBlockMatch = content.match(/export const POKEMON_ABILITIES = {([\s\S]+?)\n};/);
  if (assignmentBlockMatch) {
    const block = assignmentBlockMatch[1]!;
    const listRegex = /\[([^\]]+)\]/g;
    let m;
    while ((m = listRegex.exec(block)) !== null) {
      const names = m[1]!.match(/'([^']+)'/g);
      if (names) {
        names.forEach(n => gameAbilities.add(n.replace(/'/g, '')));
      }
    }
  }

  console.log(`📦 Habilidades únicas detectadas en el código: ${gameAbilities.size}`);
  console.log(`📝 Habilidades con descripción en ABILITY_DATA: ${Object.keys(abilityData).length}\n`);

  const apiAbilities = await getPokeApiAbilities();
  const errors: string[] = [];
  const warnings: string[] = [];

  // Map Spanish names to API entries
  const translatedMap: Record<string, PokeApiAbility> = {};
  apiAbilities.forEach((ab: PokeApiAbility) => {
    const esNameObj = ab.names.find((n: NameEntry) => n.language.name === 'es');
    if (esNameObj) {
      const cleaned = esNameObj.name.trim();
      translatedMap[cleaned] = ab;
      translatedMap[cleaned.toLowerCase()] = ab;
    }
  });

  const customMapping: Record<string, string> = {
    'Cura natural': 'natural-cure',
    'Gran encanto': 'cute-charm'
  };

  for (const abName of Array.from(gameAbilities)) {
    const tag = `[${abName}]`;

    // Check if it has a description
    if (!abilityData[abName]) {
      errors.push(`${tag} Falta descripción en ABILITY_DATA.`);
    }

    if (apiAbilities.length > 0) {
      let apiEntry: PokeApiAbility | undefined = translatedMap[abName]!;
      if (!apiEntry && customMapping[abName]) {
        apiEntry = apiAbilities.find((a: PokeApiAbility) => a.name === customMapping[abName]);
      }
      if (!apiEntry) {
        apiEntry = apiAbilities.find((a: PokeApiAbility) => a.names.some((n: NameEntry) => n.language.name === 'es' && n.name.toLowerCase() === abName.toLowerCase()));
      }

      if (!apiEntry) {
        warnings.push(`${tag} No se encontró coincidencia en PokeAPI. Revisa si el nombre es correcto.`);
      } else {
        // Basic check: Does the official text mention something critical we missed?
        const esFlavor = apiEntry.flavor_text_entries.find((f: FlavorTextEntry) => f.language.name === 'es');
        if (!esFlavor) {
          warnings.push(`${tag} No tiene texto oficial en español en PokeAPI.`);
        }
      }
    }
  }

  // Check for orphan descriptions
  Object.keys(abilityData).forEach(name => {
    if (!gameAbilities.has(name)) {
      warnings.push(`[${name}] Definida en ABILITY_DATA pero no asignada a ningún Pokémon.`);
    }
  });

  await validator.finish(
    {
      'Habilidades únicas detectadas': gameAbilities.size,
      'Habilidades en ABILITY_DATA': Object.keys(abilityData).length
    },
    errors,
    warnings
  );
}

main().catch(err => {
  console.error(styleText('red', `\n💥 Error fatal: ${err.message}`));
  process.exit(1);
});

/**
 * validate_fsm_flow_parity.ts
 * Auditoría de paridad de flujo: Compara secuencias Mermaid vs Implementación Dinámica.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { setupValidation } from './lib/validationBase.ts';

const SRC_ROOT = path.resolve(process.cwd(), 'src');
const MANUAL_PATH = path.resolve(process.cwd(), '.agents/skills/project-standards/references/battle/battle_mechanics_manual.md');

interface TransitionStep {
  from: string;
  to: string;
  isLoop: boolean;
}

// ─── Utilidades de Descubrimiento ───────────────────────────────────────────
async function walk(dir: string): Promise<string[]> {
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    const files = await Promise.all(entries.map((res) => {
      const resPath = path.resolve(dir, res.name);
      return res.isDirectory() ? walk(resPath) : (['.ts', '.vue'].includes(path.extname(res.name)) ? [resPath] : []);
    }));
    return files.flat();
  } catch { return []; }
}

async function getExecutionSequence(): Promise<string[]> {
  const allFiles = await walk(SRC_ROOT);
  const sequence: { file: string, state: string, index: number }[] = [];

  for (const file of allFiles) {
    const content = await fs.readFile(file, 'utf-8');
    const transRx = /fsm\.transition\([^,]+,\s*(?:BATTLE_SUBSTATES\.|BATTLE_STATES\.)([A-Z0-9_]+)/g;
    let m: RegExpExecArray | null;
    while ((m = transRx.exec(content)) !== null) {
      if (m[1]) {
        sequence.push({ 
          file: path.basename(file), 
          state: m[1], 
          index: m.index 
        });
      }
    }
  }

  return sequence.map(s => s.state);
}

function parseMermaidSequences(content: string) {
  const sequences: TransitionStep[][] = [];
  const blockRx = /```mermaid\n([\s\S]*?)```/g;
  let m: RegExpExecArray | null;
  while ((m = blockRx.exec(content)) !== null) {
    const block = m[1] || '';
    if (!block.includes('stateDiagram-v2')) continue;

    const seq: TransitionStep[] = [];
    block.split('\n').forEach(line => {
      const clean = line.trim();
      const trans = clean.match(/^([A-Za-z0-9_]+)\s+-->\s+([A-Za-z0-9_]+)(?:\s*:\s*([^%]+))?/);
      if (trans?.[1] && trans[2] && trans[1] !== '[*]' && trans[2] !== '[*]') {
        const label = trans[3] || '';
        seq.push({ 
          from: trans[1], 
          to: trans[2],
          isLoop: label.includes('↺') || label.toLowerCase().includes('loop') || label.toLowerCase().includes('circular')
        });
      }
    });
    if (seq.length > 0) sequences.push(seq);
  }
  return sequences;
}

async function main() {
  const validator = setupValidation({
    title: 'FSM FLOW PARITY VALIDATOR',
    requiredFiles: [MANUAL_PATH]
  });

  await validator.checkFiles();

  const manual = await fs.readFile(MANUAL_PATH, 'utf-8');
  const executionSequence = await getExecutionSequence();
  const mermaidSeqs = parseMermaidSequences(manual);

  console.log(styleText('cyan', `\nSecuencia detectada en el código (${executionSequence.length} pasos):`));
  console.log(executionSequence.slice(0, 10).join(' -> ') + (executionSequence.length > 10 ? ' ...' : ''));

  const errors: string[] = [];
  const warnings: string[] = [];
  const okTransitions: string[] = [];
  const loopTransitions: string[] = [];

  mermaidSeqs.forEach((seq, idx) => {
    seq.forEach((step: TransitionStep) => {
      const allFromIndices = executionSequence.map((s, i) => s === step.from ? i : -1).filter(i => i !== -1);
      const allToIndices = executionSequence.map((s, i) => s === step.to ? i : -1).filter(i => i !== -1);

      if (allFromIndices.length === 0 || allToIndices.length === 0) return;

      const hasValidSequence = allFromIndices.some(fIdx => allToIndices.some(tIdx => tIdx > fIdx));

      if (!hasValidSequence && !step.isLoop) {
        errors.push(`Secuencia Mermaid #${idx + 1}: ${step.from} -> ${step.to} no encontrada en el código.`);
      } else if (step.isLoop) {
        loopTransitions.push(`Secuencia Mermaid #${idx + 1}: ${step.from} -> ${step.to} (Loop circular)`);
      } else {
        okTransitions.push(`Secuencia Mermaid #${idx + 1}: ${step.from} -> ${step.to}`);
      }
    });
  });

  console.log(`\n════════════════════════════════════`);
  console.log(`    FSM FLOW PARITY REPORT`);
  await validator.finish(
    {
      'Pasos detectados en código': executionSequence.length,
      'Secuencias Mermaid evaluadas': mermaidSeqs.length,
      'Transiciones correctas': okTransitions.length,
      'Transiciones loop/circular': loopTransitions.length
    },
    errors,
    warnings
  );
}

main().catch(err => {
  console.error(styleText('red', `\n💥 Error fatal: ${err.message}`));
  process.exit(1);
});

/**
 * AUDITOR MAESTRO FSM v7.6 - RIGUROSIDAD QUIRÚRGICA TOTAL + DINAMISMO.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { setupValidation } from './lib/validationBase.ts';

const SRC_ROOT = path.resolve(process.cwd(), 'src');
const MANUAL_PATH = path.resolve(process.cwd(), '.agents/skills/project-standards/references/battle/battle_mechanics_manual.md');
const FSM_PATH = path.join(SRC_ROOT, 'logic/battle/battleStateMachine.ts');

// ─── Descubrimiento Dinámico de Archivos ──────────────────────────────────────
async function walk(dir: string): Promise<string[]> {
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    const files = await Promise.all(entries.map((res) => {
      const resPath = path.resolve(dir, res.name);
      return res.isDirectory() ? walk(resPath) : (['.ts', '.vue'].includes(path.extname(res.name)) ? [resPath] : []);
    }));
    return files.flat();
  } catch { return []; }
}

async function discoverFsmRelatedFiles() {
  const allFiles = await walk(SRC_ROOT);
  const relevant: { path: string, content: string }[] = [];
  for (const file of allFiles) {
    const content = await fs.readFile(file, 'utf-8');
    if (content.includes('fsm.transition') || content.includes('isSubState') || content.includes('BATTLE_SUBSTATES') || content.includes('BATTLE_STATES')) {
      relevant.push({ path: file, content });
    }
  }
  return relevant;
}

// ─── Parsers Robustos ─────────────────────────────────────────────────────────
function parseMermaid(manualCode: string) {
  const states = new Set<string>();
  const syncRequired = new Set<string>();
  const blockRx = /```mermaid\n([\s\S]*?)```/g;
  let m: RegExpExecArray | null;
  while ((m = blockRx.exec(manualCode)) !== null) {
    const block = m[1] || '';
    if (!block.includes('stateDiagram-v2')) continue;
    block.split('\n').forEach(line => {
      const clean = line.trim();
      if (!clean || clean.startsWith('note') || clean.startsWith('%%') || clean.startsWith('[*]')) return;
      const defMatch = clean.match(/state\s+(?:"[^"]*"\s+as\s+)?([A-Za-z0-9_]+)/);
      if (defMatch?.[1]) states.add(defMatch[1]);
      const transMatch = clean.match(/^([A-Za-z0-9_]+)\s+-->\s+([A-Za-z0-9_]+)/);
      if (transMatch) {
        if (transMatch[1] && transMatch[1] !== '[*]') states.add(transMatch[1]);
        if (transMatch[2] && transMatch[2] !== '[*]') states.add(transMatch[2]);
      }
      if (clean.includes('note') && (clean.includes('await') || clean.includes('sync'))) {
        const target = clean.match(/of\s+([A-Za-z0-9_]+)/);
        if (target?.[1]) syncRequired.add(target[1]);
      }
    });
  }
  return { states, syncRequired };
}

function parseFsmConstants(fsmCode: string) {
  const allKeys = new Set<string>();
  const substates = new Set<string>();
  const objRx = /export const (BATTLE_STATES|BATTLE_SUBSTATES)\s*=\s*\{([\s\S]*?)\}\s*(as const)?\s*;/g;
  let m: RegExpExecArray | null;
  while ((m = objRx.exec(fsmCode)) !== null) {
    const isTop = m[1] === 'BATTLE_STATES';
    const keyRx = /([A-Z][A-Z0-9_]+)\s*:/g;
    let km: RegExpExecArray | null;
    while ((km = keyRx.exec(m[2]!)) !== null) if (km?.[1]) {
      allKeys.add(km[1]);
      if (!isTop) substates.add(km[1]);
    }
  }
  return { allKeys, substates };
}

async function main() {
  const validator = setupValidation({
    title: 'FSM IMPLEMENTATION VALIDATOR',
    requiredFiles: [MANUAL_PATH, FSM_PATH]
  });

  await validator.checkFiles();

  const manualCode = await fs.readFile(MANUAL_PATH, 'utf-8');
  const fsmCode = await fs.readFile(FSM_PATH, 'utf-8');
  const fileData = await discoverFsmRelatedFiles();

  const externalCode = fileData.filter(f => !f.path.includes('battleStateMachine.ts')).map(d => d.content).join('\n\n');
  const allCode = fileData.map(d => d.content).join('\n\n');

  const { states: mermaidStates, syncRequired } = parseMermaid(manualCode);
  const { allKeys, substates } = parseFsmConstants(fsmCode);

  const errors: string[] = [];
  const warnings: string[] = [];

  // 1. Mermaid -> JS
  mermaidStates.forEach(s => {
    if (!allKeys.has(s)) {
      errors.push(`[CHECK 1] Nodo Mermaid '${s}' falta en JS.`);
    }
  });

  // 2. Uso de Constantes
  allKeys.forEach(k => {
    const usageRx = new RegExp(`(?:\\.|'|")(${k})(?:'|")?`, 'g');
    if (!externalCode.match(usageRx)) {
      warnings.push(`[CHECK 2] Constante '${k}' definida pero sin uso real fuera de battleStateMachine.ts.`);
    }
  });

  // 3. Subestados (Referencias de transiciones)
  substates.forEach(s => {
    const refRx = new RegExp(`(?:isSubState|fsm\\.transition|emit|SUBSTATES)\\s*\\(\\s*[^)]*${s}|['"]${s}['"]`, 'g');
    if (!externalCode.match(refRx)) {
      warnings.push(`[CHECK 3] Subestado [PENDIENTE/HUÉRFANO]: '${s}'`);
    }
  });

  // 4. Timers Ciegos
  fileData.forEach(file => {
    file.content.split('\n').forEach((line, idx) => {
      const t = line.trim();
      if (!t.includes('setTimeout') || t.startsWith('//')) return;
      const isAtomic = t.includes('await new Promise') || t.startsWith('await') || t.includes('return new Promise') || t.includes('=>');
      if (!isAtomic) {
        warnings.push(`[CHECK 4] setTimeout no atómico en ${path.basename(file.path)}:${idx + 1}: ${t.slice(0, 60)}`);
      }
    });
  });

  // 5. Sincronización Mandatoria (await)
  syncRequired.forEach(sub => {
    const usageRx = new RegExp(`(?:\\.|'|")(${sub})(?:'|")?`, 'g');
    let um: RegExpExecArray | null;
    let found = false; let unawaited = false;
    while ((um = usageRx.exec(allCode)) !== null) {
      const idx = um.index;
      const context = allCode.slice(Math.max(0, idx - 300), idx);
      if (context.includes(`${sub}:`) || context.includes('//')) continue;
      found = true;
      if (!context.includes('await')) unawaited = true;
    }
    if (found && unawaited) {
      warnings.push(`[CHECK 5] '${sub}' exige await según manual.`);
    }
  });

  // 6. Guardas de Idempotencia
  ['isProcessing', 'handleFaint', 'faintedSides'].forEach(g => {
    if (!allCode.includes(g)) {
      errors.push(`[CHECK 6] Falta guarda de idempotencia '${g}'`);
    }
  });

  // 7. Regla de Asientos (HUD)
  const seatRuleRx = /!s\?\.enemy\s*&&\s*!s\?\._initialEnemy|!battleStore\.state\.enemy|battleStore\.state\.enemy\s*===\s*null|!battleStore\.state\?\.enemy|!s\?\.enemy/;
  if (!seatRuleRx.test(allCode)) {
    errors.push(`[CHECK 7] No se detecta la regla de asientos para visibilidad HUD.`);
  }

  // 8. Ciclo Level Up
  if (!(allCode.includes('levelUpPokemon') && allCode.includes('CHECK_PENDING') && allCode.includes('pendingMoves'))) {
    errors.push(`[CHECK 8] Ciclo de Level Up desalineado (falta levelUpPokemon, CHECK_PENDING o pendingMoves).`);
  }

  // 9. Persistencia
  if (!(allCode.includes('persistenceMode') && (allCode.includes("'SINGLE'") || allCode.includes('"SINGLE"')))) {
    errors.push(`[CHECK 9] Rama persistenceMode SINGLE no detectada en código.`);
  }

  // 10. Referencias a Estados/Subestados Inexistentes (Código Basura)
  fileData.forEach(file => {
    const lines = file.content.split('\n');
    lines.forEach((line, idx) => {
      // 10a. Referencias explícitas por objeto BATTLE_STATES/BATTLE_SUBSTATES
      const explicitMatches = line.matchAll(/\bBATTLE_(?:SUB)?STATES\.([A-Z0-9_]+)\b/g);
      for (const match of explicitMatches) {
        const stateName = match[1];
        if (stateName && !allKeys.has(stateName)) {
          errors.push(`[CHECK 10] Referencia explícita a estado inexistente en ${path.basename(file.path)}:${idx + 1}: BATTLE_(SUB)STATES.${stateName}`);
        }
      }

      // 10b. Literales de texto en llamadas a FSM
      const fsmCallMatches = line.matchAll(/(?:transition|isSubState|isState|currentState\.value\s*===\s*|currentState\s*===\s*|state\s*===\s*)\(\s*(?:[^,]+,\s*)?['"]([A-Z0-9_]+)['"]/g);
      for (const match of fsmCallMatches) {
        const stateName = match[1];
        if (stateName && !allKeys.has(stateName) && !['SINGLE', 'PLAYER', 'ENEMY', 'ACTIVE'].includes(stateName)) {
          errors.push(`[CHECK 10] Literal de FSM inexistente referenciado en ${path.basename(file.path)}:${idx + 1}: '${stateName}'`);
        }
      }
    });
  });

  await validator.finish(
    {
      'Archivos escaneados': fileData.length,
      'Estados Mermaid': mermaidStates.size,
      'Constantes FSM': allKeys.size,
      'Subestados': substates.size
    },
    errors,
    warnings
  );
}

main().catch(err => {
  console.error(styleText('red', `\n💥 Error fatal: ${err.message}`));
  process.exit(1);
});

/**
 * scripts/validate_items.ts
 * 
 * ITEM VALIDATOR SCRIPT (Node.js 26+)
 * Validates integrity of SHOP_ITEMS and HEALING_ITEMS across:
 *   - src/data/items.js            -> SHOP_ITEMS[]
 *   - src/logic/items/itemEffects.js -> HEALING_ITEMS{}
 *
 * Usage: npm run validate:items
 */

import fs from 'node:fs/promises';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { styleText } from 'node:util';
import { setupValidation } from './lib/validationBase.ts';

// Runtime permission check
if (process.permission && !process.permission.has('fs.read', process.cwd())) {
  console.error(styleText('red', '\n❌ Error: Este script requiere permisos de lectura. Ejecútalo con --permission --allow-fs-read=.\n'));
  process.exit(1);
}

const SHOP_FILE   = path.resolve(process.cwd(), 'src/data/items.ts');
const BATTLE_FILE = path.resolve(process.cwd(), 'src/logic/items/itemEffects.ts');

interface ShopItem {
  id: string;
  _line: number;
  name?: string | null;
  cat?: string | null;
  sprite?: string | null;
  icon?: string | null;
  desc?: string | null;
  type?: string | null;
  price?: number | null;
  market?: boolean | null;
  [key: string]: unknown;
}

async function main() {
  const validator = setupValidation({
    title: 'ITEM INTEGRITY VALIDATOR',
    requiredFiles: [SHOP_FILE, BATTLE_FILE]
  });

  await validator.checkFiles();

  const shopContent   = await fs.readFile(SHOP_FILE, 'utf8');
  const battleContent = await fs.readFile(BATTLE_FILE, 'utf8');

  // ─── 1. Extract SHOP_ITEMS entries (line-based parser) ───────────────────────
  const shopLines = shopContent.split('\n');
  const shopItems: ShopItem[] = [];
  const shopStart = shopLines.findIndex(l => l.includes('export const SHOP_ITEMS'));
  const shopEnd   = shopLines.length;

  let current: ShopItem | null = null;

  for (let i = shopStart; i < shopEnd; i++) {
    const line = shopLines[i]!;
    const idMatch = line.match(/\bid:\s*'([^']+)'/);
    if (idMatch) {
      if (current && current.name && current.cat) shopItems.push(current);
      current = { id: idMatch[1]!, _line: i + 1 };
    }

    if (!current) continue;

    const tryMatch = (rx: RegExp) => { const m = line.match(rx); return m ? m[1] : null; };

    if (!current.name)   current.name   = tryMatch(/\bname:\s*'([^']+)'/);
    if (!current.cat)    current.cat    = tryMatch(/\bcat:\s*'([^']+)'/);
    if (!current.sprite) current.sprite = tryMatch(/\bsprite:\s*'([^']+)'/);
    if (!current.icon)   current.icon   = tryMatch(/\bicon:\s*'([^']+)'/);
    if (!current.desc)   current.desc   = tryMatch(/\bdesc:\s*'([^']+)'/);
    if (!current.type)   current.type   = tryMatch(/\btype:\s*'([^']+)'/);

    const priceM  = line.match(/\bprice:\s*(\d+)/);
    const marketM = line.match(/\bmarket:\s*(true|false)/);
    if (priceM  && current.price  == null) current.price  = parseInt(priceM[1]!);
    if (marketM && current.market == null) current.market = marketM[1] === 'true';
  }
  if (current && current.name && current.cat) shopItems.push(current);

  // ─── 2. Extract HEALING_ITEMS keys ───────────────────────────────────────────
  const healingItems = new Set<string>();
  const healingRegex = /^\s+'([^']+)':\s*\(?[\s\S]*?\)?\s*=>/gm;
  let m;
  while ((m = healingRegex.exec(battleContent)) !== null) {
    healingItems.add(m[1]!);
  }

  // ─── Run validations ──────────────────────────────────────────────────────────
  const errors: string[]   = [];
  const warnings: string[] = [];

  const MUST_BE_USABLE     = ['pociones', 'potions', 'utility', 'booster', 'stones', 'stone'];
  const MUST_NOT_BE_USABLE = ['held', 'combat_held', 'pokeballs', 'breeding', 'breeding_held', 'raw_material', 'refined_material', 'component', 'machinery', 'tms'];
  const REQUIRED_FIELDS    = ['id', 'name', 'cat', 'sprite', 'icon', 'desc', 'price'];
  const VALID_CATS         = [
    'pociones', 'potions', 'utility', 'tools', 'booster', 'especial', 'held', 'combat_held', 'pokeballs', 'stones', 'stone', 'breeding', 'breeding_held',
    'healing', 'tm', 'special', 'raw_material', 'refined_material', 'component', 'machinery', 'tms', 'otros'
  ];

  shopItems.forEach(item => {
    const tag = `[${item.name || item.id} (line ~${item._line})]`;

    REQUIRED_FIELDS.forEach(f => {
      const val = item[f];
      if (val == null || val === '') {
        errors.push(`${tag} Missing required field: '${f}'`);
      }
    });

    if (item.sprite) {
      const physicalPath = path.resolve(process.cwd(), 'public/assets/sprites', `${item.sprite}.webp`);
      if (!existsSync(physicalPath)) {
        errors.push(`${tag} Sprite file does not exist: '${physicalPath}'`);
      }
    }

    if (item.cat && !VALID_CATS.includes(item.cat)) {
      errors.push(`${tag} Unknown category: '${item.cat}'`);
    }

    if (item.cat && MUST_BE_USABLE.includes(item.cat) && item.id && !healingItems.has(item.id)) {
      if (!item.name?.startsWith('MT')) {
        errors.push(`${tag} cat='${item.cat}' but '${item.id}' has no entry in HEALING_ITEMS.`);
      }
    }

    if (item.cat && MUST_NOT_BE_USABLE.includes(item.cat) && item.id && healingItems.has(item.id)) {
      // 'Restaurador de Vigor' (vigor_restorer) is a breeding item that is explicitly usable to restore vigor
      if (item.id !== 'vigor_restorer') {
        errors.push(`${tag} cat='${item.cat}' should NOT be in HEALING_ITEMS.`);
      }
    }

    if ((item.cat === 'held' || item.cat === 'combat_held') && item.type !== 'held') {
      errors.push(`${tag} cat='${item.cat}' but missing 'type: held'.`);
    }

    // TMs are handled dynamically in getDynamicItemEffect, so they don't need to be in the main object
    if (item.name?.startsWith('MT')) return;
  });

  const shopItemIds = new Set(shopItems.map(i => i.id));

  healingItems.forEach(id => {
    if (id.startsWith('MT')) return;
    if (!shopItemIds.has(id)) {
      warnings.push(`[PHANTOM] '${id}' is in HEALING_ITEMS but has NO entry in SHOP_ITEMS.`);
    }
  });

  await validator.finish(
    {
      'SHOP_ITEMS scanned': shopItems.length,
      'HEALING_ITEMS scanned': healingItems.size
    },
    errors,
    warnings
  );
}

main().catch(err => {
  console.error(styleText('red', `\n💥 Fatal error: ${err.message}`));
  process.exit(1);
});

/**
 * scripts/validate_moves.ts
 * 
 * MOVE INTEGRITY VALIDATOR (Node.js 26+)
 * Validates integrity of MOVE_DATA against learnsets, semantic rules, and PokeAPI.
 * 
 * Usage: npm run validate:moves
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText, parseArgs } from 'node:util';
import { enableCompileCache } from 'node:module';

enableCompileCache();

interface PokeApiMoveListResponse {
  results: Array<{ name: string; url: string }>;
}

interface PokeApiMove {
  name: string;
  names: Array<{ name: string; language: { name: string } }>;
  meta?: {
    category?: { name: string };
  };
  effect_chance?: number;
  effect_entries: Array<{
    short_effect: string;
    language: { name: string };
  }>;
}

const DB_FILE = path.resolve(process.cwd(), 'src/data/pokemonDB.ts');
const MOVES_FILE = path.resolve(process.cwd(), 'src/data/moves.ts');
const UTILS_FILE = path.resolve(process.cwd(), 'src/logic/pokemonUtils.ts');
const CACHE_DIR = path.resolve(process.cwd(), 'scripts/.cache');
const CACHE_FILE = path.join(CACHE_DIR, 'pokeapi_move_cache.json');

function normalizeName(name: string) {
  return name.toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]/g, '');
}

async function getPokeApiMoves(): Promise<PokeApiMove[]> {
  try {
    const cacheExists = await fs.access(CACHE_FILE).then(() => true).catch(() => false);
    if (cacheExists) {
      console.log(styleText('blue', "ℹ️ Cargando movimientos de PokeAPI desde la caché..."));
      return JSON.parse(await fs.readFile(CACHE_FILE, 'utf8')) as PokeApiMove[];
    }
    await fs.mkdir(CACHE_DIR, { recursive: true });
  } catch {
    console.log(styleText('yellow', "⚠️ No se pudo acceder a la caché de PokeAPI."));
  }

  console.log(styleText('cyan', "🌐 Obteniendo movimientos de PokeAPI (esto puede tardar unos segundos)..."));

  try {
    const response = await fetch('https://pokeapi.co/api/v2/move?limit=354');
    if (!response.ok) throw new Error(`Status: ${response.status}`);
    const listResp = await response.json() as PokeApiMoveListResponse;

    const results: PokeApiMove[] = [];
    const chunkSize = 20;

    for (let i = 0; i < listResp.results.length; i += chunkSize) {
      const chunk = listResp.results.slice(i, i + chunkSize);
      const promises = chunk.map(async (entry: { url: string }) => {
        const res = await fetch(entry.url);
        if (!res.ok) return null;
        return res.json() as Promise<PokeApiMove>;
      });

      const chunkResults = await Promise.all(promises);
      results.push(...chunkResults.filter((item): item is PokeApiMove => !!item));
      process.stdout.write(`Obtenidos ${Math.min(i + chunkSize, listResp.results.length)} / ${listResp.results.length}\r`);
    }

    console.log(styleText('green', "\n✅ Descarga de movimientos completada."));
    await fs.writeFile(CACHE_FILE, JSON.stringify(results, null, 2));
    return results;
  } catch (error: unknown) {
    console.error(styleText('red', `\n❌ Error al conectar con PokeAPI: ${(error as Error).message}`));
    return [];
  }
}

async function main() {
  const { values } = parseArgs({
    options: {
      output: { type: 'string', short: 'o' },
      summary: { type: 'boolean', short: 's' }
    }
  });

  console.log(styleText('bold', '\n--- 🛡️  POKEMON MOVE VALIDATOR ---'));

  try {
    await fs.access(DB_FILE);
    await fs.access(MOVES_FILE);
  } catch (_e) {
    console.error(styleText('red', `❌ Archivos de datos no encontrados.`));
    process.exit(1);
  }

  const dbContent = await fs.readFile(DB_FILE, 'utf8');
  const movesContent = await fs.readFile(MOVES_FILE, 'utf8');

  const errors: string[] = [];
  const warnings: string[] = [];

  // 1. Extract moves from learnsets (using English ID)
  const learnsetBlockRegex = /learnset:\s*\[([\s\S]+?)\]/g;
  const moveIdRegex = /id:\s*'([^']+)'/g;
  const learnsetMoves = new Set<string>();

  let blockMatch;
  while ((blockMatch = learnsetBlockRegex.exec(dbContent)) !== null) {
    const block = blockMatch[1]!;
    let idMatch;
    while ((idMatch = moveIdRegex.exec(block)) !== null) {
      if (idMatch[1] !== 'Unknown') learnsetMoves.add(idMatch[1]!);
    }
  }

  // 2. Extract defined moves from MOVE_DATA (using English keys)
  const definedMoves = new Map<string, { line: number, content: string }>();
  const movesLines = movesContent.split('\n');

  movesLines.forEach((line, index) => {
    const match = line.match(/'([^']+)':\s*\{/);
    if (match) {
      const key = match[1]!;
      if (definedMoves.has(key)) {
        errors.push(`[${key}] Duplicado en MOVE_DATA (Línea ${index + 1}).`);
      }
      definedMoves.set(key, { line: index + 1, content: line });
    }
  });

  console.log(`📊 Movimientos en learnsets: ${learnsetMoves.size}`);
  console.log(`📚 Movimientos definidos en MOVE_DATA: ${definedMoves.size}\n`);

  const apiMoves = await getPokeApiMoves();

  // 3. Structural & Semantic Validation (English ID match)
  learnsetMoves.forEach(move => {
    if (!definedMoves.has(move)) {
      errors.push(`[${move}] Aparece en un learnset pero NO está definido en MOVE_DATA.`);
    }
  });

  definedMoves.forEach((data, name) => {
    const { content, line } = data;
    const tag = `[${name} (Línea ${line})]`;

    // Status moves with power > 0
    if (content.includes("cat: 'status'") && content.match(/power:\s*([1-9]\d*)/)) {
      errors.push(`${tag} Movimiento de estado con potencia mayor a 0.`);
    }

    // Specific move checks (using English keys)
    if (name === 'dragon_rage' && !content.includes('fixedDmg: 40')) {
      errors.push(`${tag} Falta 'fixedDmg: 40'.`);
    }
    if (name === 'super_colmillo' && !content.includes('halfHP: true')) {
      errors.push(`${tag} Falta 'halfHP: true'.`);
    }
    if (name === 'endeavor' && !content.includes('endeavor: true')) {
      errors.push(`${tag} Falta 'endeavor: true'.`);
    }

    // Schema enforcement
    const boolProps = ['halfHP', 'ohko', 'selfKO', 'endeavor'];
    boolProps.forEach(prop => {
      if (content.includes(`effect: '${prop}'`)) {
        errors.push(`${tag} Usa "effect: '${prop}'" en lugar del esquema requerido "${prop}: true".`);
      }
    });

    if (content.includes("effect: 'fixedDmg'")) {
      errors.push(`${tag} Usa "effect: 'fixedDmg'" en lugar de "fixedDmg: X".`);
    }

    // PokeAPI Semantic Sync (English Name match)
    if (apiMoves.length > 0) {
      const norm = normalizeName(name);
      const apiMove = apiMoves.find((m: PokeApiMove) => {
        return normalizeName(m.name) === norm || normalizeName(m.name) === norm.replace(/_/g, '');
      });

      if (apiMove) {
        const apiCat = apiMove.meta?.category?.name || '';
        const apiChance = apiMove.effect_chance;
        const apiEffectEntries = apiMove.effect_entries.find((e: { language: { name: string } }) => e.language.name === 'en')?.short_effect || '';

        // Check for missing effects based on category
        if (apiCat && apiCat !== 'damage' && !content.includes('effect:') && !content.match(/(ohko|drain|recoil|endeavor|halfHP|fixedDmg):/)) {
          if (!content.includes("cat: 'status'")) {
            warnings.push(`${tag} Podría faltar lógica de efecto (Categoría PokeAPI: '${apiCat}').`);
          }
        }

        // Check for effect chance mismatch
        if (apiChance && content.includes('effect:')) {
          const ourChanceMatch = content.match(/_(\d+)'/);
          const ourChance = ourChanceMatch ? parseInt(ourChanceMatch[1]!) : 100;
          if (ourChance !== apiChance) {
            warnings.push(`${tag} Discrepancia en probabilidad de efecto: PokeAPI ${apiChance}% vs Local ${ourChance}%.`);
          }
        }

        // Check for flinch
        if (apiEffectEntries.toLowerCase().includes('flinch') && !content.includes('flinch')) {
          warnings.push(`${tag} PokeAPI menciona 'flinch', pero no se detectó en la definición local.`);
        }
      }
    }
  });

  // 4. UI Description Parity
  try {
    const utilsContent = await fs.readFile(UTILS_FILE, 'utf8');
    const effectsMatch = utilsContent.match(/const effects:.* = {([\s\S]+?)};/);
    if (effectsMatch) {
      const registeredEffects = new Set<string>();
      const keyRegex = /'([^']+)':/g;
      let k;
      while ((k = keyRegex.exec(effectsMatch[1]!)) !== null) {
        registeredEffects.add(k[1]!);
      }

      definedMoves.forEach((data, name) => {
        const eMatch = data.content.match(/effect:\s*'([^']+)'/);
        if (eMatch) {
          const effectName = eMatch[1]!;
          if (!registeredEffects.has(effectName)) {
            warnings.push(`[${name}] Usa el efecto '${effectName}' pero no tiene descripción en pokemonUtils.ts.`);
          }
        }
      });
    }
  } catch (_e) {
    warnings.push(`No se pudo validar pokemonUtils.ts para descripciones de efectos.`);
  }

  console.log(`\n════════════════════════════════════`);
  console.log(`    REPORTE DE INTEGRIDAD DE MOVIMIENTOS`);
  console.log(`════════════════════════════════════`);
  console.log(`📊 Movimientos en learnsets:          ${learnsetMoves.size}`);
  console.log(`📚 Movimientos definidos:             ${definedMoves.size}`);
  console.log(`════════════════════════════════════\n`);

  if (values.output) {
    const outputPath = path.resolve(process.cwd(), values.output as string);
    const lines = [
      `--- REPORTE DE INTEGRIDAD DE MOVIMIENTOS ---`,
      `Movimientos en learnsets:          ${learnsetMoves.size}`,
      `Movimientos definidos:             ${definedMoves.size}`,
      `\nErrores (${errors.length}):`,
      ...errors.map(e => `  - ${e}`),
      `\nAdvertencias (${warnings.length}):`,
      ...warnings.map(w => `  - ${w}`)
    ];
    await fs.writeFile(outputPath, lines.join('\n'), 'utf-8');
    console.log(styleText('cyan', `\n✨ Reporte completo escrito en: ${values.output}`));
  }

  if (values.summary) {
    console.log(styleText('cyan', `\n[INFO] Modo resumen activo: ${errors.length} errores, ${warnings.length} advertencias.`));
  } else {
    if (warnings.length) {
      console.log(styleText('yellow', `⚠️  ADVERTENCIAS (${warnings.length}):`));
      const limit = 30;
      warnings.slice(0, limit).forEach(w => console.log(`   ${w}`));
      if (warnings.length > limit) {
        console.log(styleText('cyan', `   ... y ${warnings.length - limit} advertencias más (usa -o para ver todas)`));
      }
      console.log('');
    }

    if (errors.length) {
      console.log(styleText('red', `❌ ERRORES (${errors.length}):`));
      const limit = 30;
      errors.slice(0, limit).forEach(e => console.log(`   ${e}`));
      if (errors.length > limit) {
        console.log(styleText('cyan', `   ... y ${errors.length - limit} errores más (usa -o para ver todos)`));
      }
      console.log('\n' + styleText('red', 'Corrige estos errores en src/data/moves.ts.'));
    } else {
      console.log(styleText('green', '✅ Todos los movimientos pasaron la validación de integridad.'));
    }
  }

  if (errors.length > 0) {
    process.exit(1);
  }
}

main().catch(err => {
  console.error(styleText('red', `\n💥 Error fatal: ${err.message}`));
  process.exit(1);
});

/**
 * scripts/validate_sandbox_moves_tooltip.ts
 * 
 * SHOWDOWN SANDBOX TRANSLATION, DESCRIPTION & TOOLTIP INTEGRITY VALIDATOR (Node.js 26+)
 * 
 * Performs a deep audit of:
 *   1. Existence & coverage of move name translations (move_translations.json)
 *   2. Existence & coverage of move descriptions in Spanish (move_descriptions.json)
 *   3. Detection of English-language descriptions via linguistic heuristics
 *   4. Integration of the Premium Mathematical Tooltip component
 *   5. Store sanitization & auto-population logic for leader moves
 *   6. Cross-reference parity between names and descriptions databases
 * 
 * Usage: node --permission --allow-fs-read=. --experimental-strip-types scripts/validate_sandbox_moves_tooltip.ts
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText, parseArgs } from 'node:util';
import { enableCompileCache } from 'node:module';

enableCompileCache();

interface ExtractedMove {
  id: string;
  name: string;
  type: string;
  category: string;
  basePower: number;
  accuracy: number | boolean;
  pp: number;
  desc?: string;
  shortDesc?: string;
}

interface ShowdownLocalDB {
  pokemon: Record<string, unknown>;
  moves: Record<string, ExtractedMove>;
  abilities: Record<string, unknown>;
}

// Target Paths
const SHOWDOWN_DB_PATH = path.resolve(process.cwd(), 'showdown/sandbox_db/data/showdown_db.json');
const TRANSLATIONS_PATH = path.resolve(process.cwd(), 'showdown/sandbox_db/data/move_translations.json');
const DESCRIPTIONS_PATH = path.resolve(process.cwd(), 'showdown/sandbox_db/data/move_descriptions.json');
const TOOLTIP_COMP_PATH = path.resolve(process.cwd(), 'showdown/components/ShowdownMoveTooltip.vue');
const SANDBOX_VIEW_PATH = path.resolve(process.cwd(), 'showdown/ShowdownSandboxView.vue');
const TEAMBUILDER_PATH = path.resolve(process.cwd(), 'showdown/components/ShowdownTeambuilder.vue');
const STORE_PATH = path.resolve(process.cwd(), 'showdown/useShowdownSandboxStore.ts');

/**
 * Common English words that should NOT appear in a properly localized Spanish description.
 * Weighted heuristic: if 2+ of these are found in a single description, it is flagged as English.
 */
const ENGLISH_MARKER_WORDS = [
  'the', 'user', 'target', 'opponent', 'raises', 'lowers', 'foe',
  'power', 'move', 'attack', 'damage', 'hits', 'causes', 'restores',
  'increases', 'decreases', 'boosts', 'fails', 'turn', 'chance',
  'if', 'when', 'this', 'that', 'with', 'from', 'each', 'other',
  'also', 'will', 'does', 'has', 'can', 'may', 'its', 'their',
  'faints', 'loses', 'drains', 'heals', 'switches', 'prevents',
  'sharply', 'harshly', 'always', 'never', 'before', 'after'
];

/**
 * Detects if a description string is likely written in English
 * using a word-frequency heuristic against known English markers.
 */
function isLikelyEnglish(text: string): boolean {
  const lowerText = text.toLowerCase();
  const words = lowerText.split(/\s+/);
  let englishHits = 0;

  for (const marker of ENGLISH_MARKER_WORDS) {
    if (words.includes(marker)) {
      englishHits++;
    }
  }

  // Threshold: 2+ English marker words → flag as English
  return englishHits >= 2;
}

async function fileExists(filePath: string): Promise<boolean> {
  try {
    await fs.access(filePath);
    return true;
  } catch {
    return false;
  }
}

async function main() {
  const { values } = parseArgs({
    options: {
      output: { type: 'string', short: 'o' },
      summary: { type: 'boolean', short: 's' }
    }
  });

  console.log(styleText('bold', '\n══════════════════════════════════════════════════════════════'));
  console.log(styleText('bold', '🛡️  AUDITORÍA INTEGRAL: TRADUCCIONES, DESCRIPCIONES & TOOLTIP 🛡️'));
  console.log(styleText('bold', '══════════════════════════════════════════════════════════════\n'));

  const errors: string[] = [];
  const warnings: string[] = [];
  const achievements: string[] = [];

  // ═══════════════════════════════════════════════════════════
  // FASE 1: Infraestructura de Archivos
  // ═══════════════════════════════════════════════════════════
  const criticalFiles: Array<{ path: string; label: string }> = [
    { path: SHOWDOWN_DB_PATH, label: 'Base de datos Showdown (showdown_db.json)' },
    { path: TRANSLATIONS_PATH, label: 'Traducciones de nombres (move_translations.json)' },
    { path: DESCRIPTIONS_PATH, label: 'Descripciones en español (move_descriptions.json)' },
    { path: TOOLTIP_COMP_PATH, label: 'Componente Tooltip Premium (ShowdownMoveTooltip.vue)' },
    { path: SANDBOX_VIEW_PATH, label: 'Vista del Sandbox (ShowdownSandboxView.vue)' },
    { path: TEAMBUILDER_PATH, label: 'Teambuilder (ShowdownTeambuilder.vue)' },
    { path: STORE_PATH, label: 'Store Pinia (useShowdownSandboxStore.ts)' },
  ];

  let criticalMissing = false;
  for (const file of criticalFiles) {
    if (!(await fileExists(file.path))) {
      errors.push(`Archivo crítico faltante: ${file.label} → ${file.path}`);
      criticalMissing = true;
    } else {
      achievements.push(`✔ ${file.label} encontrado.`);
    }
  }

  if (criticalMissing) {
    console.error(styleText('red', '❌ Faltan archivos de infraestructura críticos. Abortando.'));
    errors.forEach(e => console.error(`   - ${e}`));
    process.exit(1);
  }

  // ═══════════════════════════════════════════════════════════
  // FASE 2: Cobertura de Traducciones de Nombres
  // ═══════════════════════════════════════════════════════════
  const showdownDbRaw = await fs.readFile(SHOWDOWN_DB_PATH, 'utf8');
  const showdownDb = JSON.parse(showdownDbRaw) as ShowdownLocalDB;

  const translationsRaw = await fs.readFile(TRANSLATIONS_PATH, 'utf8');
  const translations = JSON.parse(translationsRaw) as Record<string, string>;

  const allMoveIds = Object.keys(showdownDb.moves);
  const totalMovesInDB = allMoveIds.length;

  const missingNameTranslations: string[] = [];
  for (const moveId of allMoveIds) {
    if (!translations[moveId]) {
      const move = showdownDb.moves[moveId]!;
      missingNameTranslations.push(`${moveId} (${move.name})`);
    }
  }

  if (missingNameTranslations.length > 0) {
    errors.push(`Faltan traducciones de NOMBRE para ${missingNameTranslations.length} movimientos.`);
  } else {
    achievements.push(`100% de movimientos (${totalMovesInDB}) tienen traducción de nombre en español.`);
  }

  // ═══════════════════════════════════════════════════════════
  // FASE 3: Cobertura y Calidad de Descripciones en Español
  // ═══════════════════════════════════════════════════════════
  const descriptionsRaw = await fs.readFile(DESCRIPTIONS_PATH, 'utf8');
  const descriptions = JSON.parse(descriptionsRaw) as Record<string, string>;

  const missingDescriptions: string[] = [];
  const englishDescriptions: string[] = [];

  for (const moveId of allMoveIds) {
    const desc = descriptions[moveId];
    if (!desc || desc.trim() === '') {
      const move = showdownDb.moves[moveId]!;
      missingDescriptions.push(`${moveId} (${move.name})`);
    } else if (isLikelyEnglish(desc)) {
      const move = showdownDb.moves[moveId]!;
      englishDescriptions.push(`${moveId} (${move.name}): "${desc}"`);
    }
  }

  if (missingDescriptions.length > 0) {
    errors.push(`Faltan DESCRIPCIONES en español para ${missingDescriptions.length} movimientos.`);
  } else {
    achievements.push(`100% de movimientos (${totalMovesInDB}) tienen descripción en español.`);
  }

  if (englishDescriptions.length > 0) {
    errors.push(`Se detectaron ${englishDescriptions.length} descripciones probablemente en INGLÉS en move_descriptions.json.`);
  } else {
    achievements.push('Todas las descripciones pasaron la heurística anti-inglés. 100% español verificado.');
  }

  // ═══════════════════════════════════════════════════════════
  // FASE 4: Integración del Tooltip Premium en Frontend
  // ═══════════════════════════════════════════════════════════
  const tooltipCode = await fs.readFile(TOOLTIP_COMP_PATH, 'utf8');

  // 4a. Verify Tooltip consumes move_descriptions.json
  const tooltipImportsDescriptions = tooltipCode.includes('move_descriptions.json') || tooltipCode.includes('moveDescriptions');
  if (tooltipImportsDescriptions) {
    achievements.push('El Tooltip Premium importa y consume `move_descriptions.json` para fallback en español.');
  } else {
    errors.push('El Tooltip NO importa `move_descriptions.json`. Las descripciones en español no se mostrarán.');
  }

  // 4b. Premium math calculations
  const hasStabCalc = tooltipCode.includes('isStab') || tooltipCode.includes('STAB') || tooltipCode.includes('stabMultiplier');
  const hasTypeEffectiveness = tooltipCode.includes('getCombinedEffectiveness') || tooltipCode.includes('effectiveness');
  const hasGsapAnimation = tooltipCode.includes('gsap') || tooltipCode.includes('onBeforeEnter') || tooltipCode.includes('onEnter');
  const hasEstimatedPower = tooltipCode.includes('estimatedPower');

  if (hasStabCalc) {
    achievements.push('El Tooltip incluye cálculo dinámico de STAB (x1.5).');
  } else {
    warnings.push('No se detectó cálculo de STAB en el Tooltip.');
  }

  if (hasTypeEffectiveness) {
    achievements.push('El Tooltip integra cálculo cruzado de efectividades elementales.');
  } else {
    warnings.push('No se detectó cálculo de efectividad de tipos en el Tooltip.');
  }

  if (hasEstimatedPower) {
    achievements.push('El Tooltip calcula la potencia estimada final (BP × STAB × Efectividad).');
  } else {
    warnings.push('No se detectó cálculo de potencia estimada en el Tooltip.');
  }

  if (hasGsapAnimation) {
    achievements.push('El Tooltip utiliza GSAP para transiciones de entrada y salida.');
  } else {
    warnings.push('No se detectaron transiciones GSAP en el Tooltip.');
  }

  // 4c. Verify ShowdownSandboxView integrations (supporting modular subcomponents)
  const viewCode = await fs.readFile(SANDBOX_VIEW_PATH, 'utf8');
  let controlsCode = '';
  let battleMenuCode = '';
  try {
    const controlsPath = path.resolve(process.cwd(), 'showdown/components/ShowdownControls.vue');
    controlsCode = await fs.readFile(controlsPath, 'utf8');
  } catch {
    // Fail silently if ShowdownControls.vue is not found (legacy support)
  }
  try {
    const battleMenuPath = path.resolve(process.cwd(), 'showdown/components/ShowdownBattleMenu.vue');
    battleMenuCode = await fs.readFile(battleMenuPath, 'utf8');
  } catch {
    // Fail silently if ShowdownBattleMenu.vue is not found
  }

  const combinedCode = viewCode + '\n' + controlsCode + '\n' + battleMenuCode;

  const importsTooltip = combinedCode.includes('ShowdownMoveTooltip') &&
    (combinedCode.includes('./components/ShowdownMoveTooltip.vue') || 
     combinedCode.includes('./components/ShowdownMoveTooltip') ||
     combinedCode.includes('./ShowdownMoveTooltip.vue') ||
     combinedCode.includes('./ShowdownMoveTooltip'));
  const instantiatesTooltip = combinedCode.includes('<ShowdownMoveTooltip') || combinedCode.includes('<showdown-move-tooltip');
  const hasHoverEvents = (combinedCode.includes('onMoveMouseEnter') || combinedCode.includes('handleMoveMouseEnter')) &&
    (combinedCode.includes('onMoveMouseLeave') || combinedCode.includes('handleMoveMouseLeave'));
  const hasMobileFallback = combinedCode.includes('hover: hover') || combinedCode.includes('activeTooltipMove') || combinedCode.includes('matchMedia');

  if (importsTooltip && instantiatesTooltip) {
    achievements.push('`ShowdownMoveTooltip` se importa e instancia correctamente en la vista del Sandbox (o sus subcomponentes).');
  } else {
    errors.push('El Sandbox no incluye o no instancia `ShowdownMoveTooltip` en su plantilla.');
  }

  if (hasHoverEvents) {
    achievements.push('La cuadrícula de ataques tiene eventos interactivos de ratón (mouseenter/mouseleave).');
  } else {
    warnings.push('No se detectaron controladores hover en la cuadrícula de ataques.');
  }

  if (hasMobileFallback) {
    achievements.push('El Sandbox implementa interactividad responsiva (Desktop hover / Mobile doble-toque).');
  } else {
    warnings.push('No se detectó lógica para compatibilidad táctil móvil.');
  }

  // 4d. Verify Teambuilder integration
  const teambuilderCode = await fs.readFile(TEAMBUILDER_PATH, 'utf8');
  const tbImportsTranslations = teambuilderCode.includes('move_translations.json') || teambuilderCode.includes('moveTranslations');
  const tbAlphabeticalSort = teambuilderCode.includes('localeCompare') && teambuilderCode.includes('nameEs');

  if (tbImportsTranslations) {
    achievements.push('El Teambuilder importa las traducciones oficiales de nombres.');
  } else {
    warnings.push('No se detectó consumo de traducciones de nombres en el Teambuilder.');
  }

  if (tbAlphabeticalSort) {
    achievements.push('El selector de ataques del Teambuilder ordena alfabéticamente por nombre en español.');
  } else {
    warnings.push('No se detectó ordenamiento por nombre localizado en el Teambuilder.');
  }

  // ═══════════════════════════════════════════════════════════
  // FASE 5: Sanitización y Auto-Poblado en el Store
  // ═══════════════════════════════════════════════════════════
  const storeCode = await fs.readFile(STORE_PATH, 'utf8');

  // 5a. setPlayerLeader / setEnemyLeader auto-population
  const hasSetPlayerLeader = storeCode.includes('setPlayerLeader');
  const hasSetEnemyLeader = storeCode.includes('setEnemyLeader');
  const hasGetRandomMoves = storeCode.includes('getRandomMoves');

  if (hasSetPlayerLeader && hasSetEnemyLeader) {
    achievements.push('El store implementa `setPlayerLeader` y `setEnemyLeader` para auto-poblado reactivo.');
  } else {
    errors.push('Faltan las acciones `setPlayerLeader` / `setEnemyLeader` en el store.');
  }

  if (hasGetRandomMoves) {
    achievements.push('La función `getRandomMoves` genera movimientos aleatorios garantizando STAB.');
  } else {
    errors.push('Falta la función `getRandomMoves` en el store.');
  }

  // 5b. Sanitization in generateTeam
  const hasSanitization = storeCode.includes('sanitizedMoves') || storeCode.includes('SANITIZE');
  const hasDeduplication = storeCode.includes('new Set(') || storeCode.includes('Set(sanitized');
  const hasFilterEmpty = storeCode.includes("filter(m => m !== ''") || storeCode.includes('.filter(m =>');

  if (hasSanitization) {
    achievements.push('`generateTeam` implementa sanitización estricta de movimientos del líder.');
  } else {
    errors.push('No se detectó sanitización de movimientos en `generateTeam`.');
  }

  if (hasDeduplication) {
    achievements.push('La sanitización elimina movimientos duplicados vía `Set`.');
  } else {
    warnings.push('No se detectó deduplicación de movimientos en la sanitización.');
  }

  if (hasFilterEmpty) {
    achievements.push('La sanitización filtra entradas vacías.');
  } else {
    warnings.push('No se detectó filtrado de entradas vacías.');
  }

  // 5c. Teambuilder wiring
  const tbUsesSetPlayerLeader = teambuilderCode.includes('setPlayerLeader') || teambuilderCode.includes('store.setPlayerLeader');
  const tbUsesSetEnemyLeader = teambuilderCode.includes('setEnemyLeader') || teambuilderCode.includes('store.setEnemyLeader');

  if (tbUsesSetPlayerLeader && tbUsesSetEnemyLeader) {
    achievements.push('El Teambuilder invoca `setPlayerLeader` / `setEnemyLeader` al cambiar de Pokémon.');
  } else {
    errors.push('El Teambuilder NO invoca las acciones de auto-poblado del store.');
  }

  // ═══════════════════════════════════════════════════════════
  // FASE 6: Paridad Cruzada Nombres ↔ Descripciones
  // ═══════════════════════════════════════════════════════════
  const translationKeys = new Set(Object.keys(translations));
  const descriptionKeys = new Set(Object.keys(descriptions));

  const inNamesNotInDescs: string[] = [];
  const inDescsNotInNames: string[] = [];

  for (const key of translationKeys) {
    if (!descriptionKeys.has(key)) {
      inNamesNotInDescs.push(key);
    }
  }

  for (const key of descriptionKeys) {
    if (!translationKeys.has(key)) {
      inDescsNotInNames.push(key);
    }
  }

  if (inNamesNotInDescs.length > 0) {
    warnings.push(`${inNamesNotInDescs.length} movimientos tienen nombre traducido pero NO descripción.`);
  }

  if (inDescsNotInNames.length > 0) {
    warnings.push(`${inDescsNotInNames.length} movimientos tienen descripción pero NO nombre traducido.`);
  }

  if (inNamesNotInDescs.length === 0 && inDescsNotInNames.length === 0) {
    achievements.push('Paridad cruzada perfecta: todos los nombres traducidos tienen descripción.');
  }

  // Output formatting & reporting
  console.log(`\n════════════════════════════════════`);
  console.log(`    SANDBOX MOVES & TOOLTIP INTEGRITY`);
  console.log(`════════════════════════════════════`);
  console.log(`📦 Movimientos en DB:     ${totalMovesInDB}`);
  console.log(`✨ Logros/Aciertos:       ${achievements.length}`);
  console.log(`⚠️  Advertencias:          ${warnings.length}`);
  console.log(`❌ Errores detectados:    ${errors.length}`);
  console.log(`════════════════════════════════════\n`);

  if (values.output) {
    const outputPath = path.resolve(process.cwd(), values.output as string);
    const lines = [
      `--- SANDBOX MOVES & TOOLTIP INTEGRITY REPORT ---`,
      `Movimientos en DB:     ${totalMovesInDB}`,
      `Logros/Aciertos:       ${achievements.length}`,
      `Advertencias:          ${warnings.length}`,
      `Errores:               ${errors.length}`,
      `\nLogros (${achievements.length}):`,
      ...achievements.map(a => `  - ${a}`),
      `\nErrores (${errors.length}):`,
      ...errors.map(e => `  - ${e}`),
      `\nAdvertencias (${warnings.length}):`,
      ...warnings.map(w => `  - ${w}`)
    ];
    await fs.writeFile(outputPath, lines.join('\n'), 'utf-8');
    console.log(styleText('cyan', `\n✨ Reporte completo escrito en: ${values.output}`));
  }

  if (values.summary) {
    console.log(styleText('cyan', `\n[INFO] Modo resumen activo: ${errors.length} errores, ${warnings.length} advertencias.`));
  } else {
    if (achievements.length > 0) {
      console.log(styleText('green', `🌟 VALIDACIONES CORRECTAS (${achievements.length}):`));
      const limit = 30;
      achievements.slice(0, limit).forEach(a => console.log(`   ✅ ${a}`));
      if (achievements.length > limit) {
        console.log(styleText('cyan', `   ... y ${achievements.length - limit} aciertos más (usa -o para ver todos)`));
      }
      console.log('');
    }

    if (warnings.length > 0) {
      console.log(styleText('yellow', `⚠️  ADVERTENCIAS (${warnings.length}):`));
      const limit = 30;
      warnings.slice(0, limit).forEach(w => console.log(`   🟡 ${w}`));
      if (warnings.length > limit) {
        console.log(styleText('cyan', `   ... y ${warnings.length - limit} advertencias más (usa -o para ver todas)`));
      }
      console.log('');
    }

    if (errors.length > 0) {
      console.log(styleText('red', `❌ ERRORES DE INTEGRIDAD DETECTADOS (${errors.length}):`));
      const limit = 30;
      errors.slice(0, limit).forEach(e => console.log(`   🚨 ${e}`));
      if (errors.length > limit) {
        console.log(styleText('cyan', `   ... y ${errors.length - limit} errores más (usa -o para ver todos)`));
      }
      console.log('\n' + styleText('red', 'Corrige los errores listados para asegurar la perfecta experiencia del Sandbox.'));
    } else {
      console.log(styleText('green', '✨ ¡FELICITACIONES! El Sandbox ha pasado la auditoría con éxito absoluto.'));
    }
  }

  if (errors.length > 0) {
    process.exit(1);
  }
}

main().catch(err => {
  console.error(styleText('red', `\n💥 Error fatal durante la auditoría: ${(err as Error).message}`));
  process.exit(1);
});

/**
 * scripts/validate_sql_migrations.ts
 * 
 * VALIDADOR DE MIGRACIONES SQL (Node.js 26+)
 * 
 * Este script utiliza el módulo nativo 'node:sqlite' para verificar la integridad
 * sintáctica de las migraciones SQL antes de que lleguen al cliente o producción.
 * 
 * Proceso:
 * 1. Escanea 'database/migrations/'.
 * 2. Crea una base de datos SQLite en memoria.
 * 3. Traduce y ejecuta cada migración.
 * 4. Reporta errores detallados con número de línea.
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { styleText, parseArgs } from 'node:util';
import { enableCompileCache } from 'node:module';
import { splitSQLStatements, translatePostgresToSqlite } from '../src/logic/db/sqlTranslator.ts';

// Speed up execution on subsequent runs
enableCompileCache();

const MIGRATIONS_DIR = path.resolve(process.cwd(), 'database/migrations');

async function validateMigrations() {
  const { values } = parseArgs({
    options: {
      output: { type: 'string', short: 'o' },
      summary: { type: 'boolean', short: 's' }
    }
  });

  console.log(styleText('bold', '\n--- 🛡️  SQL MIGRATION VALIDATOR (Node.js 26) ---'));

  try {
    await fs.access(MIGRATIONS_DIR);
  } catch {
    console.error(styleText('red', '❌ Error: Directorio de migraciones no encontrado.'));
    process.exit(1);
  }

  // 1. Crear DB en memoria para validación (Explicit Resource Management)
  using db = new DatabaseSync(':memory:');
  db.exec("CREATE TABLE IF NOT EXISTS _migrations (id TEXT PRIMARY KEY, applied_at TEXT DEFAULT (datetime('now')))");
  console.log(styleText('green', '✅ Base de datos temporal creada con tabla de migraciones.'));

  // 2. Obtener y ordenar archivos
  const allFiles = await fs.readdir(MIGRATIONS_DIR);
  const files = allFiles
    .filter(f => f.endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));

  const translationCache = new Map<string, string>();
  const errors: string[] = [];
  const achievements: string[] = [];

  console.log(styleText('cyan', `📦 Procesando ${files.length} archivos de migración...\n`));

  for (const filename of files) {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const content = await fs.readFile(filePath, 'utf-8');

    try {
      const statements = splitSQLStatements(content);

      for (const stmt of statements) {
        let translated = translationCache.get(stmt);
        if (translated === undefined) {
          translated = translatePostgresToSqlite(stmt);
          translationCache.set(stmt, translated);
        }

        if (translated) {
          try {
            db.exec(translated);
          } catch (sqlErr: unknown) {
            const msg = (sqlErr as Error).message.toLowerCase();
            const isDuplicate = msg.includes('already exists') || msg.includes('duplicate column');

            if (!isDuplicate) {
              throw sqlErr;
            }
          }
        }
      }
      achievements.push(`[Migración] ${filename}: VÁLIDA`);
    } catch (e: unknown) {
      errors.push(`[Migración] ${filename}: FALLÓ: ${(e as Error).message}`);
    }
  }

  console.log(`\n════════════════════════════════════`);
  console.log(`    SQL MIGRATIONS REPORT`);
  console.log(`════════════════════════════════════`);
  console.log(`📦 Archivos detectados:  ${files.length}`);
  console.log(`✅ Migraciones válidas:  ${achievements.length}`);
  console.log(`❌ Migraciones fallidas: ${errors.length}`);
  console.log(`════════════════════════════════════\n`);

  if (values.output) {
    const outputPath = path.resolve(process.cwd(), values.output as string);
    const lines = [
      `--- SQL MIGRATIONS REPORT ---`,
      `Archivos detectados:  ${files.length}`,
      `Migraciones válidas:  ${achievements.length}`,
      `Migraciones fallidas: ${errors.length}`,
      `\nLogros (${achievements.length}):`,
      ...achievements.map(a => `  - ${a}`),
      `\nErrors (${errors.length}):`,
      ...errors.map(e => `  - ${e}`)
    ];
    await fs.writeFile(outputPath, lines.join('\n'), 'utf-8');
    console.log(styleText('cyan', `\n✨ Reporte completo escrito en: ${values.output}`));
  }

  if (values.summary) {
    console.log(styleText('cyan', `\n[INFO] Modo resumen activo: ${errors.length} errores.`));
  } else {
    if (achievements.length > 0) {
      console.log(styleText('green', `🌟 MIGRACIONES VÁLIDAS (${achievements.length}):`));
      const limit = 30;
      achievements.slice(0, limit).forEach(a => console.log(`   ✅ ${a}`));
      if (achievements.length > limit) {
        console.log(styleText('cyan', `   ... y ${achievements.length - limit} migraciones más (usa -o para ver todas)`));
      }
      console.log('');
    }

    if (errors.length > 0) {
      console.log(styleText('red', `❌ ERRORES DE INTEGRIDAD DETECTADOS (${errors.length}):`));
      const limit = 30;
      errors.slice(0, limit).forEach(e => console.log(`   🚨 ${e}`));
      if (errors.length > limit) {
        console.log(styleText('cyan', `   ... y ${errors.length - limit} errores más (usa -o para ver todos)`));
      }
    } else {
      console.log(styleText('green', '✨ TODAS LAS MIGRACIONES SON VÁLIDAS PARA SQLITE.'));
    }
  }

  if (errors.length > 0) {
    process.exit(1);
  } else {
    process.exit(0);
  }
}

validateMigrations();

/**
 * @file vite-plugin-sass-traps.ts
 * @description Plugin de Vite para normalización automática de SASS y CSS Variables.
 * 
 * Safe Version: Explicitly ignores .module and $variable calls.
 */

import fs from 'node:fs';

const SASS_TRAPS = [
  'scale', 'grayscale', 'invert', 'opacity', 'brightness', 
  'blur', 'rotate', 'translate', 'saturate', 'drop-shadow',
  'translatex', 'translatey', 'translatez', 'skewx', 'skewy', 'matrix',
  'rgba', 'rgb'
];

export function sassTrapsFixer() {
  const fixContent = (code: string) => {
    // Regex that captures optional prefix (. or $)
    return code.replace(/([.$])?\b([a-zA-Z0-9-]+)\(/g, (match, prefix, func) => {
      // 1. If preceded by . or $, it's a SASS module or variable call. IGNORE.
      if (prefix) return match;

      const lowerFunc = func.toLowerCase();
      if (SASS_TRAPS.includes(lowerFunc)) {
        // 2. Capitalize traps
        if (lowerFunc.includes('-')) {
          return lowerFunc.split('-').map((p: string) => p.charAt(0).toUpperCase() + p.slice(1)).join('-') + '(';
        }
        return lowerFunc.charAt(0).toUpperCase() + lowerFunc.slice(1) + '(';
      }

      return match;
    });
  };

  return {
    name: 'vite-plugin-sass-traps',
    enforce: 'pre' as const,

    transform(code: string, id: string) {
      if (!id.endsWith('.scss') && !id.endsWith('.vue')) return null;

      // If it's a .vue file, we only want to fix the <style> blocks
      if (id.endsWith('.vue')) {
        const styleRegex = /<style[^>]*>([\s\S]*?)<\/style>/gi;
        const newCode = code.replace(styleRegex, (match, styleContent) => {
          return match.replace(styleContent, fixContent(styleContent));
        });
        if (newCode !== code) return { code: newCode, map: null };
        return null;
      }

      const newCode = fixContent(code);
      if (newCode !== code) return { code: newCode, map: null };
      return null;
    },

    handleHotUpdate({ file, read }: { file: string, read: () => string | Promise<string> }) {
      if (!file.endsWith('.scss') && !file.endsWith('.vue')) return;

      Promise.resolve(read()).then((content: string) => {
        let fixed = content;
        if (file.endsWith('.vue')) {
          const styleRegex = /<style[^>]*>([\s\S]*?)<\/style>/gi;
          fixed = content.replace(styleRegex, (match, styleContent) => {
            return match.replace(styleContent, fixContent(styleContent));
          });
        } else {
          fixed = fixContent(content);
        }

        if (fixed !== content) {
          fs.writeFileSync(file, fixed, 'utf-8');
        }
      });
    }

  };
}

import gsap from 'gsap';
import type { ParsedEvent } from '../sandbox_db/ShowdownParser.ts';
import type { SandboxPokemon } from './showdownMath.ts';

interface SandboxStore {
  battleLog: ParsedEvent[];
  currentMessage: string;
  playerHP: number;
  playerMaxHP: number;
  enemyHP: number;
  enemyMaxHP: number;
  playCry: (id: string) => void;
  playerPokemon: SandboxPokemon | null;
  enemyPokemon: SandboxPokemon | null;
  playerTeam: SandboxPokemon[];
  enemyTeam: SandboxPokemon[];
  activePlayerIndex: number;
  activeEnemyIndex: number;
}

/**
 * Orquestador secuencial de animaciones para la cola de eventos de batalla
 */
export async function executeAnimationQueue(store: SandboxStore, events: ParsedEvent[]): Promise<void> {
  for (const event of events) {
    store.battleLog.push(event);
    await animateEvent(store, event);
  }
}

/**
 * Ejecuta animaciones y desplazamientos físicos mediante GSAP.
 * Devuelve una Promesa para garantizar la secuencialidad perfecta.
 */
export function animateEvent(store: SandboxStore, event: ParsedEvent): Promise<void> {
  return new Promise<void>((resolve) => {
    store.currentMessage = event.text;

    const tl = gsap.timeline({ onComplete: () => resolve() });
    const data = event.data;

    if (event.type === 'move' && data) {
      const spriteId = data.isPlayerAttacking ? '#player-sprite' : '#enemy-sprite';
      const direction = data.isPlayerAttacking ? 25 : -25;

      tl.to(spriteId, {
        x: `+=${direction}`,
        y: `-=${direction / 2}`,
        duration: 0.15,
        ease: 'power1.out',
      })
      .to(spriteId, {
        x: 0,
        y: 0,
        duration: 0.25,
        ease: 'power2.inOut',
      });
    } else if (event.type === 'damage' && data) {
      const spriteId = data.isPlayer ? '#player-sprite' : '#enemy-sprite';
      const hpBarId = data.isPlayer ? '#player-hp' : '#enemy-hp';
      const currentHP = data.currentHP ?? 0;
      const maxHP = data.maxHP ?? 100;
      const hpPct = (currentHP / maxHP) * 100;

      tl.to(spriteId, {
        x: '+=6',
        filter: 'brightness(1.8) sepia(1) saturate(1000%) hue-rotate(-50deg)',
        duration: 0.05,
        yoyo: true,
        repeat: 5,
      })
      .to(spriteId, {
        x: 0,
        filter: 'none',
        duration: 0.05,
      })
      .to(hpBarId, {
        width: `${hpPct}%`,
        duration: 0.4,
        ease: 'power1.out',
        onStart: () => {
          if (data.isPlayer) {
            store.playerHP = currentHP;
            store.playerMaxHP = maxHP;
          } else {
            store.enemyHP = currentHP;
            store.enemyMaxHP = maxHP;
          }
        }
      }, '<');
    } else if (event.type === 'heal' && data) {
      const spriteId = data.isPlayer ? '#player-sprite' : '#enemy-sprite';
      const hpBarId = data.isPlayer ? '#player-hp' : '#enemy-hp';
      const currentHP = data.currentHP ?? 0;
      const maxHP = data.maxHP ?? 100;
      const hpPct = (currentHP / maxHP) * 100;

      tl.to(spriteId, {
        filter: 'brightness(1.5) saturate(1000%) hue-rotate(90deg)',
        duration: 0.3,
        yoyo: true,
        repeat: 1,
      })
      .to(spriteId, {
        filter: 'none',
        duration: 0.1,
      })
      .to(hpBarId, {
        width: `${hpPct}%`,
        duration: 0.4,
        onStart: () => {
          if (data.isPlayer) {
            store.playerHP = currentHP;
            store.playerMaxHP = maxHP;
          } else {
            store.enemyHP = currentHP;
            store.enemyMaxHP = maxHP;
          }
        }
      }, '<');
    } else if (event.type === 'faint' && data) {
      const spriteId = data.isPlayer ? '#player-sprite' : '#enemy-sprite';

      tl.to(spriteId, {
        y: '+=80',
        opacity: 0,
        duration: 0.5,
        ease: 'power1.in',
        onStart: () => {
          const pokemonId = data.isPlayer ? store.playerPokemon?.id : store.enemyPokemon?.id;
          if (pokemonId) {
            store.playCry(pokemonId);
          }
        }
      });
    } else if (event.type === 'switch' && data) {
      const isPlayer = data.isPlayer;
      const spriteId = isPlayer ? '#player-sprite' : '#enemy-sprite';

      tl.to(spriteId, {
        x: isPlayer ? -150 : 150,
        y: 50,
        scale: 0.2,
        opacity: 0,
        duration: 0.4,
        ease: 'back.in(1.7)',
        onComplete: () => {
          const incomingSpeciesId = data.moveId || '';
          const team = isPlayer ? store.playerTeam : store.enemyTeam;
          const idx = team.findIndex((p: SandboxPokemon) => p.id === incomingSpeciesId);

          if (idx !== -1) {
            const incomingPoke = team[idx];
            if (incomingPoke !== undefined) {
              if (isPlayer) {
                store.activePlayerIndex = idx;
                store.playerPokemon = incomingPoke;
                store.playerHP = data.currentHP ?? store.playerHP;
                store.playerMaxHP = data.maxHP ?? store.playerMaxHP;
              } else {
                store.activeEnemyIndex = idx;
                store.enemyPokemon = incomingPoke;
                store.enemyHP = data.currentHP ?? store.enemyHP;
                store.enemyMaxHP = data.maxHP ?? store.enemyMaxHP;
              }
            }
          }

          if (incomingSpeciesId) {
            store.playCry(incomingSpeciesId);
          }
        }
      })
      .set(spriteId, {
        x: isPlayer ? 150 : -150,
        y: -50,
        scale: 0.1,
        opacity: 0
      })
      .to(spriteId, {
        x: 0,
        y: 0,
        scale: 1,
        opacity: 1,
        duration: 0.5,
        ease: 'back.out(1.2)',
        clearProps: 'transform,opacity'
      });
    } else if (event.type === 'ability') {
      tl.to({}, { duration: 0.1 })
        .to({}, { duration: 1.0 });
    } else if (event.type === 'miss' || event.type === 'status' || event.type === 'weather' || event.type === 'info') {
      tl.to({}, { duration: 0.9 });
    } else {
      tl.to({}, { duration: 1.0 });
    }
  });
}

import typeChart from '../sandbox_db/data/type_chart.json';

export interface SandboxPokemon {
  id: string;
  name: string;
  types: string[];
  hp?: number;
  maxHp?: number;
  status?: string;
  storedStats?: {
    atk: number;
    def: number;
    spa: number;
    spd: number;
    spe: number;
  } | null;
  boosts?: {
    atk: number;
    def: number;
    spa: number;
    spd: number;
    spe: number;
    accuracy: number;
    evasion: number;
  } | null;
  moveSlots?: Array<{
    id: string;
    pp: number;
    maxpp: number;
    disabled?: boolean | string;
  }> | null;
}

export interface SandboxMove {
  id: string;
  name: string;
  type: string;
  category: string;
  basePower: number;
  accuracy: number | boolean;
}

export interface DamageResult {
  minDamage: number;
  maxDamage: number;
  minPercent: number;
  maxPercent: number;
  effectiveness: number;
  isImmune: boolean;
  koChanceText: string;
}

/**
 * Obtiene el multiplicador del nivel de estadística (boosts/debuffs) de la Generación 3
 */
function getBoostMultiplier(stage: number): number {
  if (stage === 0) return 1;
  if (stage > 0) return (2 + stage) / 2;
  return 2 / (2 - stage);
}

/**
 * Calcula el rango de daño síncrono estimado de un movimiento en el Sandbox de Showdown
 */
export function calculateDamageRange(
  attacker: SandboxPokemon,
  defender: SandboxPokemon,
  move: SandboxMove,
  currentWeather: string = 'none'
): DamageResult {
  const level = 50; // Sandbox Pokémon Gen 3 estándar
  const power = move.basePower;

  // Si el movimiento no causa daño (ej. movimientos de estado), retornar daño cero
  if (power <= 0 || move.category.toLowerCase() === 'status') {
    return {
      minDamage: 0,
      maxDamage: 0,
      minPercent: 0,
      maxPercent: 0,
      effectiveness: 1,
      isImmune: false,
      koChanceText: ''
    };
  }

  // 1. Obtener estadísticas base stored del Pokémon
  const attackerAtk = attacker.storedStats?.atk || 80;
  const attackerSpA = attacker.storedStats?.spa || 80;
  const defenderDef = defender.storedStats?.def || 80;
  const defenderSpD = defender.storedStats?.spd || 80;

  // 2. Resolver boosts y debuffs dinámicos de combate
  const atkBoost = attacker.boosts?.atk || 0;
  const spaBoost = attacker.boosts?.spa || 0;
  const defBoost = defender.boosts?.def || 0;
  const spdBoost = defender.boosts?.spd || 0;

  const activeAtk = Math.floor(attackerAtk * getBoostMultiplier(atkBoost));
  const activeSpA = Math.floor(attackerSpA * getBoostMultiplier(spaBoost));
  const activeDef = Math.floor(defenderDef * getBoostMultiplier(defBoost));
  const activeSpD = Math.floor(defenderSpD * getBoostMultiplier(spdBoost));

  // 3. Determinar estadísticas ofensivas y defensivas según categoría del movimiento
  const isPhysical = move.category.toLowerCase() === 'physical';
  const offensiveStat = isPhysical ? activeAtk : activeSpA;
  const defensiveStat = isPhysical ? activeDef : activeSpD;

  // 4. Calcular efectividad de tipos elemental
  let effectiveness = 1;
  const moveType = move.type;

  if (defender.types && defender.types.length > 0) {
    for (const defType of defender.types) {
      const typeChartRow = (typeChart as Record<string, Record<string, number>>)[moveType];
      if (typeChartRow && typeChartRow[defType] !== undefined) {
        effectiveness *= typeChartRow[defType]!;
      }
    }
  }

  // Inmunidad completa
  if (effectiveness === 0) {
    return {
      minDamage: 0,
      maxDamage: 0,
      minPercent: 0,
      maxPercent: 0,
      effectiveness: 0,
      isImmune: true,
      koChanceText: 'Inmune'
    };
  }

  // 5. Bonificación STAB (Same-Type Attack Bonus)
  const hasStab = attacker.types.includes(moveType);
  const stabMultiplier = hasStab ? 1.5 : 1.0;

  // 6. Modificador por clima activo en combate
  let weatherMultiplier = 1.0;
  const normalizedWeather = currentWeather.toLowerCase();
  if (normalizedWeather === 'sunnyday' || normalizedWeather === 'sun') {
    if (moveType === 'Fire') weatherMultiplier = 1.5;
    else if (moveType === 'Water') weatherMultiplier = 0.5;
  } else if (normalizedWeather === 'raindance' || normalizedWeather === 'rain') {
    if (moveType === 'Water') weatherMultiplier = 1.5;
    else if (moveType === 'Fire') weatherMultiplier = 0.5;
  }

  // 7. Modificador por Quemadura (Reduce daño físico a la mitad)
  const isBurned = attacker.status === 'brn';
  const burnMultiplier = (isBurned && isPhysical) ? 0.5 : 1.0;

  // 8. Cálculo de base de daño (fórmula de Gen 3 oficial)
  const baseDamage = Math.floor(
    Math.floor(
      Math.floor((2 * level) / 5 + 2) * power * offensiveStat / defensiveStat
    ) / 50
  ) + 2;

  // 9. Aplicar multiplicadores en cascada ordenados
  const stabDmg = baseDamage * stabMultiplier;
  const weatherDmg = stabDmg * weatherMultiplier;
  const typeDmg = weatherDmg * effectiveness;
  const finalMultiplierDmg = typeDmg * burnMultiplier;

  // 10. Calcular rango aleatorio (Random Roll: min 0.85, max 1.00)
  const maxDamage = Math.floor(finalMultiplierDmg);
  const minDamage = Math.floor(finalMultiplierDmg * 0.85);

  // 11. Calcular porcentajes de daño sobre la salud ACTUAL del oponente
  const targetHP = defender.hp !== undefined ? defender.hp : 100;
  const targetMaxHP = defender.maxHp || 100;

  const minPercent = targetMaxHP > 0 ? Math.min(100, Math.round((minDamage / targetMaxHP) * 100)) : 0;
  const maxPercent = targetMaxHP > 0 ? Math.min(100, Math.round((maxDamage / targetMaxHP) * 100)) : 0;

  // 12. Estimar turnos requeridos para debilitamiento (KOs Chance)
  let koChanceText = 'Resta salud';
  if (minDamage >= targetHP) {
    koChanceText = '¡Garantiza OHKO!';
  } else if (maxDamage >= targetHP) {
    const chance = Math.round(((maxDamage - targetHP) / (maxDamage - minDamage || 1)) * 100);
    koChanceText = `Chance de OHKO: ${Math.max(1, Math.min(99, chance))}%`;
  } else if (minDamage * 2 >= targetHP) {
    koChanceText = 'Garantiza 2HKO';
  } else if (maxDamage * 2 >= targetHP) {
    koChanceText = 'Posible 2HKO';
  } else if (minDamage * 3 >= targetHP) {
    koChanceText = 'Garantiza 3HKO';
  } else {
    koChanceText = 'Daño residual';
  }

  return {
    minDamage,
    maxDamage,
    minPercent,
    maxPercent,
    effectiveness,
    isImmune: false,
    koChanceText
  };
}

import type { ShowdownLocalDB } from './cloner/extract_logic.ts';
import showdownDB from './data/showdown_db_es.json' with { type: 'json' };
import moveTranslations from './data/move_translations.json' with { type: 'json' };

const typedDB = showdownDB as unknown as ShowdownLocalDB;

export interface ParsedEvent {
  type: 'start' | 'move' | 'damage' | 'heal' | 'faint' | 'supereffective' | 'resisted' | 'crit' | 'info' | 'miss' | 'ability' | 'status' | 'weather' | 'clearallboost' | 'unhandled' | 'switch';
  text: string;
  data?: {
    isPlayerAttacking?: boolean;
    moveId?: string;
    isPlayer?: boolean;
    currentHP?: number;
    maxHP?: number;
  };
}

/**
 * Helper para obtener el nombre localizado de un Pokémon a partir de su identificador de Showdown (ej: p1a: Pikachu)
 */
function getPokemonName(rawId: string): string {
  if (!rawId) return '';
  const parts = rawId.split(': ');
  const displayName = parts[1] || rawId;
  const cleanId = displayName.toLowerCase().replace(/[^a-z0-9]/g, '');
  const localPoke = typedDB.pokemon[cleanId];
  return localPoke ? localPoke.name : displayName;
}

/**
 * Helper para obtener el nombre de un movimiento localizado en español
 */
function getMoveName(moveId: string): string {
  if (!moveId) return '';
  const cleanId = moveId.toLowerCase().replace(/[^a-z0-9]/g, '');
  return (moveTranslations as Record<string, string>)[cleanId] || typedDB.moves[cleanId]?.name || moveId;
}

/**
 * Helper para obtener el nombre de una habilidad localizado en español
 */
function translateAbility(abilityName: string): string {
  if (!abilityName) return '';
  const cleanId = abilityName.toLowerCase().replace(/[^a-z0-9]/g, '');
  return typedDB.abilities[cleanId]?.name || abilityName;
}

/**
 * Helper para obtener el nombre de un objeto localizado en español
 */
function translateItem(itemName: string): string {
  if (!itemName) return '';
  const cleanId = itemName.toLowerCase().replace(/[^a-z0-9]/g, '');
  const itemMap: Record<string, string> = {
    leftovers: 'Restos',
    choiceband: 'Cinta Elegida',
    lumberry: 'Baya Lum',
    sitrusberry: 'Baya Cidra',
    salacberry: 'Baya Salac',
    liechiberry: 'Baya Lichi',
    focusband: 'Cinta Enfocada',
    brightpowder: 'Polvo Brillo',
    quickclaw: 'Garra Rápida',
    mentalherb: 'Hierba Mental',
    whiteherb: 'Hierba Mental',
    kingsrock: 'Roca del Rey'
  };
  return itemMap[cleanId] || itemName;
}

/**
 * Helper para obtener el nombre localizado en español de cualquier efecto, habilidad, objeto o movimiento
 */
function translateEffect(effect: string): string {
  if (!effect) return '';

  // Normalizar y remover prefijos comunes de Showdown
  let cleanEffect = effect;
  let prefix = '';

  if (effect.startsWith('move: ')) {
    cleanEffect = effect.replace('move: ', '');
    prefix = 'move';
  } else if (effect.startsWith('ability: ')) {
    cleanEffect = effect.replace('ability: ', '');
    prefix = 'ability';
  } else if (effect.startsWith('item: ')) {
    cleanEffect = effect.replace('item: ', '');
    prefix = 'item';
  }

  const cleanId = cleanEffect.toLowerCase().replace(/[^a-z0-9]/g, '');

  // 1. Traducir movimientos
  if (prefix === 'move' || typedDB.moves[cleanId]) {
    return getMoveName(cleanEffect);
  }

  // 2. Traducir habilidades
  if (prefix === 'ability' || typedDB.abilities[cleanId]) {
    return translateAbility(cleanEffect);
  }

  // 3. Traducir objetos comunes
  if (prefix === 'item') {
    return translateItem(cleanEffect);
  }

  // 4. Traducir términos y estados comunes en inglés
  const commonMap: Record<string, string> = {
    confusion: 'Confusión',
    leechseed: 'Drenadoras',
    substitute: 'Sustituto',
    perishsong: 'Canto Mortal',
    uproar: 'Alboroto',
    attract: 'Atracción',
    taunt: 'Mofa',
    encore: 'Otra Vez',
    disable: 'Anulación',
    torment: 'Tormento',
    yawn: 'Bostezo',
    nightmare: 'Pesadilla',
    destinybond: 'Mismo Destino',
    grudge: 'Rabia',
    imprison: 'Sellar',
    ingrain: 'Arraigo',
    charge: 'Carga',
    magnetrise: 'Levidad',
    embargo: 'Embargo',
    healblock: 'Anticura',
    focuspunch: 'Puño Certero',
    flinch: 'Retroceso'
  };

  return commonMap[cleanId] || cleanEffect;
}

export function filterShowdownLogs(logs: string[]): string[] {
  const filtered: string[] = [];
  for (let i = 0; i < logs.length; i++) {
    const line = logs[i];
    if (line !== undefined) {
      if (line.startsWith('|split|')) {
        // La directiva |split| indica que las siguientes dos líneas son la versión privada y pública del mismo evento.
        // Conservamos la primera línea (privada) y descartamos la segunda (pública).
        const privateLine = logs[i + 1];
        if (privateLine !== undefined) {
          filtered.push(privateLine);
        }
        i += 2; // Omitimos la directiva split, la línea privada ya procesada y la línea pública redundante.
      } else {
        filtered.push(line);
      }
    }
  }
  return filtered;
}

/**
 * Parsea el log crudo de Showdown y lo traduce a una lista de eventos legibles por la UI
 */
export function parseShowdownLog(logs: string[]): ParsedEvent[] {
  const events: ParsedEvent[] = [];
  const filteredLogs = filterShowdownLogs(logs);

  for (const line of filteredLogs) {
    if (!line.startsWith('|')) continue;

    const parts = line.split('|').slice(1);
    const action = parts[0] || '';

    switch (action) {
      case 'start':
        events.push({ type: 'start', text: '¡Comienza el combate!' });
        break;

      case 'switch':
      case 'drag': {
        const rawTarget = parts[1] || ''; // ej: p1a: Charizard
        // El elemento parts[2] contiene los detalles del Pokémon (ej: Charizard, L50)
        const rawHpStatus = parts[3] || ''; // ej: 100/100 par o 250/250

        const targetName = getPokemonName(rawTarget);

        // Parsear salud y estado
        const hpInfo = rawHpStatus.split(' ');
        const hpRatio = hpInfo[0] || '100/100';

        const hpParts = hpRatio.split('/');
        const currentHP = parseInt(hpParts[0] || '100', 10);
        const maxHP = parseInt(hpParts[1] || '100', 10);

        const isPlayer = rawTarget.startsWith('p1');
        const speciesId = rawTarget.split(': ')[1]?.toLowerCase().replace(/[^a-z0-9]/g, '') || '';

        events.push({
          type: 'switch',
          text: `¡${isPlayer ? 'Tú envías' : 'El rival envía'} a ${targetName} al combate!`,
          data: {
            isPlayer,
            currentHP: isNaN(currentHP) ? 100 : currentHP,
            maxHP: isNaN(maxHP) ? 100 : maxHP,
            moveId: speciesId, // Reutilizado para pasar la especie al motor visual
          }
        });
        break;
      }

      case 'move': {
        const rawAttacker = parts[1] || '';
        const rawMove = parts[2] || '';
        const attacker = getPokemonName(rawAttacker);
        const moveName = getMoveName(rawMove);
        events.push({
          type: 'move',
          text: `¡${attacker} usó ${moveName}!`,
          data: {
            isPlayerAttacking: rawAttacker.startsWith('p1'),
            moveId: rawMove.toLowerCase().replace(/[^a-z0-9]/g, ''),
          },
        });
        break;
      }

      case '-damage': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const rawHp = parts[2] || '';
        const hpInfo = rawHp.split('/');
        const currentHP = parseInt(hpInfo[0] || '0', 10);
        const maxHP = parseInt(hpInfo[1] || '100', 10);
        const fromSource = parts[3] || '';

        let text = `¡${target} recibió daño!`;
        if (fromSource.includes('[from] Leech Seed')) text = `¡Las drenadoras robaron energía a ${target}!`;
        else if (fromSource.includes('[from] brn')) text = `¡${target} se resiente de la quemadura!`;
        else if (fromSource.includes('[from] psn') || fromSource.includes('[from] tox')) text = `¡El veneno resta salud a ${target}!`;
        else if (fromSource.includes('[from] Sandstorm')) text = `¡La tormenta de arena daña a ${target}!`;
        else if (fromSource.includes('[from] Hail')) text = `¡El granizo golpea a ${target}!`;
        else if (fromSource.includes('[from] Recoil')) text = `¡${target} recibe daño de retroceso!`;
        else if (fromSource.includes('[from] confusion')) text = `¡${target} se hirió a sí mismo en su confusión!`;

        events.push({
          type: 'damage',
          text,
          data: {
            isPlayer: rawTarget.startsWith('p1'),
            currentHP: isNaN(currentHP) ? 0 : currentHP,
            maxHP: isNaN(maxHP) ? 100 : maxHP,
          },
        });
        break;
      }

      case '-heal': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const rawHp = parts[2] || '';
        const hpInfo = rawHp.split('/');
        const currentHP = parseInt(hpInfo[0] || '0', 10);
        const maxHP = parseInt(hpInfo[1] || '100', 10);
        const fromSource = parts[3] || '';

        let text = `¡${target} recuperó salud!`;
        if (fromSource.includes('[from] drain')) text = `¡La salud de ${target} fue restaurada!`;
        else if (fromSource.includes('[from] item: Leftovers')) text = `¡${target} recuperó salud gracias a Restos!`;
        else if (fromSource.includes('[from] Leech Seed')) text = `¡La salud de ${target} fue restaurada por las drenadoras!`;

        events.push({
          type: 'heal',
          text,
          data: {
            isPlayer: rawTarget.startsWith('p1'),
            currentHP: isNaN(currentHP) ? 0 : currentHP,
            maxHP: isNaN(maxHP) ? 100 : maxHP,
          },
        });
        break;
      }

      case 'faint': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        events.push({
          type: 'faint',
          text: `¡${target} se ha debilitado!`,
          data: { isPlayer: rawTarget.startsWith('p1') },
        });
        break;
      }

      case 'cant': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const reason = parts[2] || '';
        let text = `¡${target} no puede moverse!`;
        if (reason === 'flinch') text = `¡${target} retrocedió y no pudo atacar!`;
        else if (reason === 'par') text = `¡${target} está paralizado y no puede moverse!`;
        else if (reason === 'slp') text = `¡${target} está profundamente dormido!`;
        else if (reason === 'frz') text = `¡${target} está congelado sólido!`;
        else if (reason.includes('recharge')) text = `¡${target} debe recargar energía!`;

        events.push({ type: 'info', text });
        break;
      }

      case '-immune': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const fromSource = parts[2] || '';
        let text = `¡No afecta a ${target}!`;
        if (fromSource.includes('Levitate')) text = `¡${target} levita en el aire! Los ataques de tierra no le afectan.`;

        events.push({ type: 'ability', text });
        break;
      }

      case '-weather': {
        const weatherId = parts[1] || '';
        let text = '';
        if (weatherId === 'none') text = 'El clima ha vuelto a la normalidad.';
        else if (weatherId === 'SunnyDay') text = 'El sol brilla con fuerza.';
        else if (weatherId === 'RainDance') text = 'Sigue lloviendo a cántaros.';
        else if (weatherId === 'Sandstorm') text = 'La tormenta de arena arrecia.';
        else if (weatherId === 'Hail') text = 'El granizo sigue cayendo.';

        if (text) events.push({ type: 'weather', text });
        break;
      }

      case '-status': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const status = parts[2] || '';
        let text = `¡${target} sufre un problema de estado!`;
        if (status === 'brn') text = `¡${target} se ha quemado!`;
        else if (status === 'psn' || status === 'tox') text = `¡${target} ha sido envenenado!`;
        else if (status === 'par') text = `¡${target} ha sido paralizado!`;
        else if (status === 'slp') text = `¡${target} se ha quedado dormido!`;
        else if (status === 'frz') text = `¡${target} se ha congelado!`;

        events.push({ type: 'status', text });
        break;
      }

      case '-curestatus': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        events.push({ type: 'status', text: `¡${target} se ha curado de su problema de estado!` });
        break;
      }

      case '-boost':
      case '-unboost': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const stat = parts[2] || '';
        const amount = parseInt(parts[3] || '1', 10);

        const statNames: Record<string, string> = {
          atk: 'Ataque', def: 'Defensa', spa: 'Ataque Esp.', spd: 'Defensa Esp.', spe: 'Velocidad', accuracy: 'Precisión', evasion: 'Evasión'
        };
        const statName = statNames[stat] || stat;
        const direction = action === '-boost' ? 'subió' : 'bajó';
        const much = amount > 1 ? ' mucho' : '';

        events.push({ type: 'info', text: `¡El ${statName} de ${target} ${direction}${much}!` });
        break;
      }

      case '-supereffective':
        events.push({ type: 'supereffective', text: '¡Es súper eficaz!' });
        break;

      case '-resisted':
        events.push({ type: 'resisted', text: 'No es muy eficaz...' });
        break;

      case '-crit':
        events.push({ type: 'crit', text: '¡Un golpe crítico!' });
        break;

      case '-miss': {
        const rawTarget = parts[2] || '';
        const target = getPokemonName(rawTarget);
        events.push({ type: 'miss', text: `¡El ataque falló en acertar a ${target}!` });
        break;
      }

      case '-fail': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        events.push({ type: 'miss', text: `¡Pero el ataque de ${target} falló!` });
        break;
      }

      case '-prepare': {
        const rawTarget = parts[1] || '';
        const rawMove = parts[2] || '';
        const target = getPokemonName(rawTarget);
        const moveName = getMoveName(rawMove);
        events.push({ type: 'info', text: `¡${target} se está preparando para usar ${moveName}!` });
        break;
      }

      case '-activate': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const effect = parts[2] || '';
        const source = parts[3] || '';

        let text = `¡Se activó un efecto en ${target}!`;
        if (effect.includes('Protect')) {
          text = `¡${target} se protegió!`;
        } else if (effect.includes('Substitute')) {
          text = `¡El sustituto de ${target} absorbió el daño!`;
        } else if (effect.startsWith('move: ')) {
          const rawMoveName = effect.replace('move: ', '');
          const moveName = getMoveName(rawMoveName);
          if (rawMoveName.toLowerCase() === 'beat up' || rawMoveName.toLowerCase() === 'beatup') {
            const ofPoke = source.replace('[of] ', '');
            text = `¡El ataque es liderado por ${getPokemonName(ofPoke)}!`;
          } else if (rawMoveName.toLowerCase() === 'splash') {
            text = `¡Pero no pasó nada!`;
          } else {
            text = `¡El efecto de ${moveName} se activó en ${target}!`;
          }
        } else if (effect.startsWith('ability: ')) {
          const ability = translateAbility(effect.replace('ability: ', ''));
          text = `¡La habilidad ${ability} de ${target} se activó!`;
        } else if (effect.startsWith('item: ')) {
          const item = translateItem(effect.replace('item: ', ''));
          text = `¡El objeto ${item} de ${target} hizo efecto!`;
        } else if (effect === 'Trapped') {
          text = `¡${target} no puede escapar!`;
        }

        events.push({ type: 'ability', text });
        break;
      }

      case '-ability': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const ability = translateAbility(parts[2] || '');
        events.push({ type: 'ability', text: `¡Se activó la habilidad ${ability} de ${target}!` });
        break;
      }

      case '-endability': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        events.push({ type: 'ability', text: `¡${target} perdió su habilidad!` });
        break;
      }

      case '-item': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const item = translateItem(parts[2] || '');
        events.push({ type: 'info', text: `¡${target} obtuvo el objeto ${item}!` });
        break;
      }

      case '-enditem': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const item = translateItem(parts[2] || '');
        events.push({ type: 'info', text: `¡${target} consumió o perdió el objeto ${item}!` });
        break;
      }

      case '-singleturn': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const effect = parts[2] || '';
        let text = `¡${target} se preparó para este turno!`;

        if (effect.includes('Protect')) text = `¡${target} se está protegiendo!`;
        else if (effect.includes('Endure')) text = `¡${target} se preparó para resistir el golpe!`;
        else if (effect.includes('Roost')) text = `¡${target} aterrizó para recuperar energías!`;
        else if (effect.startsWith('move: ')) {
          const moveName = getMoveName(effect.replace('move: ', ''));
          text = `¡${target} activó el efecto de ${moveName}!`;
        }

        events.push({ type: 'info', text });
        break;
      }

      case '-start': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const effect = parts[2] || '';
        let text = '';
        if (effect.includes('confusion')) text = `¡${target} se ha confundido!`;
        else if (effect.includes('Leech Seed')) text = `¡A ${target} le han plantado drenadoras!`;
        else if (effect.includes('Substitute')) text = `¡${target} creó un sustituto!`;
        else if (effect.startsWith('perish')) {
          const count = effect.replace('perish', '');
          text = `¡La cuenta de Canto Mortal de ${target} bajó a ${count}!`;
        } else {
          const translated = translateEffect(effect);
          if (effect.startsWith('move: ')) {
            text = `¡A ${target} le afecta el movimiento ${translated}!`;
          } else if (effect.startsWith('ability: ')) {
            text = `¡A ${target} le afecta la habilidad ${translated}!`;
          } else {
            text = `¡A ${target} le afecta el efecto de ${translated}!`;
          }
        }

        events.push({ type: 'status', text });
        break;
      }

      case '-end': {
        const rawTarget = parts[1] || '';
        const target = getPokemonName(rawTarget);
        const effect = parts[2] || '';
        let text = '';
        if (effect.includes('confusion')) text = `¡${target} ya no está confundido!`;
        else if (effect.includes('Substitute')) text = `¡El sustituto de ${target} se desvaneció!`;
        else {
          const translated = translateEffect(effect);
          if (effect.startsWith('move: ')) {
            text = `¡El efecto de ${translated} en ${target} ha terminado!`;
          } else {
            text = `¡El efecto de ${translated} en ${target} ha terminado!`;
          }
        }

        events.push({ type: 'info', text });
        break;
      }

      case '-clearallboost':
        events.push({ type: 'info', text: '¡Todos los cambios en las estadísticas fueron eliminados!' });
        break;

      default:
        // Ignoramos otras directivas internas
        break;
    }
  }

  return events;
}

