  console.log('🚀 [Clonador Showdown] Iniciando extracción de base de datos Gen 3...');

  // 1. Extraer Lógica Gen 3 (movimientos, habilidades, Pokémon Gen 1-3)
  const db: ShowdownLocalDB = extractGen3Logic();
  console.log(`📊 Datos lógicos de Gen 3 extraídos correctamente:`);
  console.log(`   - Habilidades: ${Object.keys(db.abilities).length}`);
  console.log(`   - Movimientos: ${Object.keys(db.moves).length}`);
  console.log(`   - Pokémon: ${Object.keys(db.pokemon).length}`);

  // Leer argumentos de consola (ej: --limit=10)
  let limit: number | null = null;
  const limitArg = process.argv.find((arg) => arg.startsWith('--limit='));
  if (limitArg) {
    const parts = limitArg.split('=');
    const valStr = parts[1];
    if (valStr) {
      limit = parseInt(valStr, 10);
      console.log(`⚠️ Limitando descargas de sprites a los primeros ${limit} Pokémon para pruebas rápidas.`);
    }
  }

  // 2. Obtener IDs de TODOS los Pokémon (Gen 1-9) para descargar sprites completos
  const fullDex = Dex.forGen(9);
  let allPokemonIds = fullDex.species.all()
    .filter(s => s.isNonstandard === null || s.isNonstandard === 'Past')
    .map(s => s.id);

  if (limit !== null && !isNaN(limit)) {
    allPokemonIds = allPokemonIds.slice(0, limit);
  }

  console.log(`\n🌍 Descargando sprites para ${allPokemonIds.length} Pokémon (Gen 1-9)...`);

  // 3. Descargar Sprites y Sonidos para todas las generaciones
  try {
    const spriteMap = await downloadAllSprites(allPokemonIds, 5, 50);

    // Integrar mapeo de sprites en el JSON solo para los Pokémon del DB Gen 3
    for (const id of Object.keys(db.pokemon)) {
      const poke = db.pokemon[id];
      const sprites = spriteMap[id];
      if (poke && sprites) {
        poke.sprites = {
          front: sprites.front,
          frontAnimated: sprites.frontAnimated,
          back: sprites.back,
          backAnimated: sprites.backAnimated,
          frontShiny: sprites.frontShiny,
          frontShinyAnimated: sprites.frontShinyAnimated,
          backShiny: sprites.backShiny,
          backShinyAnimated: sprites.backShinyAnimated,
          cry: sprites.cry,
        };
      }
    }
  } catch (err) {
    console.error('❌ Error al descargar los sprites y sonidos:', err);
  }

  // Si aplicamos un límite, recortamos el JSON lógico para base de datos de pruebas compacta
  if (limit !== null && !isNaN(limit)) {
    const limitedPokemon: typeof db.pokemon = {};
    const gen3Ids = Object.keys(db.pokemon).slice(0, limit);
    for (const id of gen3Ids) {
      const poke = db.pokemon[id];
      if (poke) {
        limitedPokemon[id] = poke;
      }
    }
    db.pokemon = limitedPokemon;
  }

  // Asegurar la existencia del directorio de datos
  await fs.mkdir(DATA_DIR, { recursive: true });

  // 4. Escribir archivo de base de datos original (Inglés)
  await fs.writeFile(JSON_OUTPUT_PATH, JSON.stringify(db, null, 2), 'utf-8');
  console.log(`\n💾 Base de datos original (EN) guardada exitosamente en:\n   ${JSON_OUTPUT_PATH}`);

  // 5. Cargar diccionarios de traducción de movimientos
  console.log('\n📖 Cargando diccionarios de traducción para generar la versión en español...');
  const TRANSLATIONS_PATH = path.join(DATA_DIR, 'move_translations.json');
  const DESCRIPTIONS_PATH = path.join(DATA_DIR, 'move_descriptions.json');

  let moveTranslations: Record<string, string> = {};
  let moveDescriptions: Record<string, string> = {};

  try {
    const transRaw = await fs.readFile(TRANSLATIONS_PATH, 'utf-8');
    moveTranslations = JSON.parse(transRaw);
  } catch (_e) {
    console.warn('⚠️ No se pudo cargar move_translations.json, se usarán fallbacks.');
  }

  try {
    const descRaw = await fs.readFile(DESCRIPTIONS_PATH, 'utf-8');
    moveDescriptions = JSON.parse(descRaw);
  } catch (_e) {
    console.warn('⚠️ No se pudo cargar move_descriptions.json, se usarán fallbacks.');
  }

  // 6. Generar clon profundo traducido al español
  console.log('🔄 Traduciendo lógica al español...');
  const dbEs: ShowdownLocalDB = JSON.parse(JSON.stringify(db));

  // A. Traducir Habilidades
  for (const abiId of Object.keys(dbEs.abilities)) {
    const abi = dbEs.abilities[abiId];
    if (abi) {
      const manualName = ABILITY_MANUAL_MAP[abiId.toLowerCase()];
      if (manualName) {
        abi.name = manualName;
        const data = (ABILITY_DATA as Record<string, { desc: string }>)[manualName];
        if (data) {
          abi.desc = data.desc;
          abi.shortDesc = data.desc;
        }
      } else {
        const found = Object.entries(ABILITY_DATA).find(([k]) => k.toLowerCase() === abi.name.toLowerCase());
        if (found) {
          abi.name = found[0];
          abi.desc = found[1].desc;
          abi.shortDesc = found[1].desc;
        }
      }
    }
  }

  // B. Traducir Movimientos
  for (const moveId of Object.keys(dbEs.moves)) {
    const move = dbEs.moves[moveId];
    if (move) {
      move.name = moveTranslations[moveId.toLowerCase()] || move.name;
      move.shortDesc = moveDescriptions[moveId.toLowerCase()] || move.shortDesc;
      if (move.desc) {
        move.desc = moveDescriptions[moveId.toLowerCase()] || move.desc;
      }
      move.type = TYPE_TRANSLATIONS[move.type] || move.type;
    }
  }

  // C. Traducir Pokémon (nombres, tipos y referencias a habilidades)
  for (const pokeId of Object.keys(dbEs.pokemon)) {
    const poke = dbEs.pokemon[pokeId];
    if (poke) {
      // Traducir nombre
      const localPoke = (POKEMON_DB as Record<string, { name: string }>)[pokeId.toLowerCase()];
      if (localPoke) {
        poke.name = localPoke.name;
      }

      // Traducir tipos
      poke.types = poke.types.map(t => TYPE_TRANSLATIONS[t] || t);

      // Traducir referencias de habilidades del Pokémon (sus IDs)
      poke.abilities = poke.abilities.map(aId => {
        const manualName = ABILITY_MANUAL_MAP[aId.toLowerCase()];
        return manualName || aId;
      });
    }
  }

  // 7. Escribir archivo de base de datos traducido (Español)
  await fs.writeFile(JSON_ES_OUTPUT_PATH, JSON.stringify(dbEs, null, 2), 'utf-8');
  console.log(`💾 Base de datos traducida (ES) guardada exitosamente en:\n   ${JSON_ES_OUTPUT_PATH}`);
  console.log('🏁 [Clonador Showdown] Proceso finalizado con éxito.');
}

main().catch((err) => {
  console.error('❌ Error fatal en el proceso del Clonador:', err);
  process.exit(1);
});

import * as fs from 'node:fs/promises';
import * as path from 'node:path';

// URLs base de Pokémon Showdown para Sprites y Audio
const BASE_URLS = {
  animatedFront: 'https://play.pokemonshowdown.com/sprites/ani/',
  animatedBack: 'https://play.pokemonshowdown.com/sprites/ani-back/',
  staticFront: 'https://play.pokemonshowdown.com/sprites/dex/',
  staticBack: 'https://play.pokemonshowdown.com/sprites/dex-back/',
  animatedFrontShiny: 'https://play.pokemonshowdown.com/sprites/ani-shiny/',
  animatedBackShiny: 'https://play.pokemonshowdown.com/sprites/ani-back-shiny/',
  staticFrontShiny: 'https://play.pokemonshowdown.com/sprites/dex-shiny/',
  staticBackShiny: 'https://play.pokemonshowdown.com/sprites/dex-back-shiny/',
  cries: 'https://play.pokemonshowdown.com/audio/cries/',
};

// Rutas locales de almacenamiento dentro de showdown/assets
const OUTPUT_DIRS = {
  front: path.resolve('showdown/assets/front'),
  back: path.resolve('showdown/assets/back'),
  frontShiny: path.resolve('showdown/assets/front-shiny'),
  backShiny: path.resolve('showdown/assets/back-shiny'),
  cries: path.resolve('showdown/assets/cries'),
};

/**
 * Helper para descargar un archivo con reintentos y fallback.
 */
async function downloadFile(url: string, destPath: string): Promise<boolean> {
  // Verificar si el archivo ya existe localmente para evitar descargas redundantes
  try {
    const stat = await fs.stat(destPath);
    if (stat.size > 0) {
      return true;
    }
  } catch {
    // El archivo no existe, proceder con la descarga
  }

  try {
    const res = await fetch(url);
    if (!res.ok) {
      return false;
    }
    const arrayBuffer = await res.arrayBuffer();
    await fs.writeFile(destPath, Buffer.from(arrayBuffer));
    return true;
  } catch (_error) {
    return false;
  }
}

/**
 * Descarga los sprites y gritos para un Pokémon específico.
 */
export async function downloadPokemonAssets(pokemonId: string): Promise<{
  front: { file: string; isAnimated: boolean };
  back: { file: string; isAnimated: boolean };
  frontShiny: { file: string; isAnimated: boolean };
  backShiny: { file: string; isAnimated: boolean };
  cry: { file: string };
}> {
  const result = {
    front: { file: '', isAnimated: false },
    back: { file: '', isAnimated: false },
    frontShiny: { file: '', isAnimated: false },
    backShiny: { file: '', isAnimated: false },
    cry: { file: '' },
  };

  // 1. Descargar Sprite Frontal Normal (Intentar Animado -> Fallback Estático)
  const frontGifPath = path.join(OUTPUT_DIRS.front, `${pokemonId}.gif`);
  const frontPngPath = path.join(OUTPUT_DIRS.front, `${pokemonId}.png`);
  if (await downloadFile(`${BASE_URLS.animatedFront}${pokemonId}.gif`, frontGifPath)) {
    result.front = { file: `${pokemonId}.gif`, isAnimated: true };
  } else if (await downloadFile(`${BASE_URLS.staticFront}${pokemonId}.png`, frontPngPath)) {
    result.front = { file: `${pokemonId}.png`, isAnimated: false };
  }

  // 2. Descargar Sprite Trasero Normal (Intentar Animado -> Fallback Estático)
  const backGifPath = path.join(OUTPUT_DIRS.back, `${pokemonId}.gif`);
  const backPngPath = path.join(OUTPUT_DIRS.back, `${pokemonId}.png`);
  if (await downloadFile(`${BASE_URLS.animatedBack}${pokemonId}.gif`, backGifPath)) {
    result.back = { file: `${pokemonId}.gif`, isAnimated: true };
  } else if (await downloadFile(`${BASE_URLS.staticBack}${pokemonId}.png`, backPngPath)) {
    result.back = { file: `${pokemonId}.png`, isAnimated: false };
  }

  // 3. Descargar Sprite Frontal Shiny (Intentar Animado -> Fallback Estático)
  const frontShinyGifPath = path.join(OUTPUT_DIRS.frontShiny, `${pokemonId}.gif`);
  const frontShinyPngPath = path.join(OUTPUT_DIRS.frontShiny, `${pokemonId}.png`);
  if (await downloadFile(`${BASE_URLS.animatedFrontShiny}${pokemonId}.gif`, frontShinyGifPath)) {
    result.frontShiny = { file: `${pokemonId}.gif`, isAnimated: true };
  } else if (await downloadFile(`${BASE_URLS.staticFrontShiny}${pokemonId}.png`, frontShinyPngPath)) {
    result.frontShiny = { file: `${pokemonId}.png`, isAnimated: false };
  }

  // 4. Descargar Sprite Trasero Shiny (Intentar Animado -> Fallback Estático)
  const backShinyGifPath = path.join(OUTPUT_DIRS.backShiny, `${pokemonId}.gif`);
  const backShinyPngPath = path.join(OUTPUT_DIRS.backShiny, `${pokemonId}.png`);
  if (await downloadFile(`${BASE_URLS.animatedBackShiny}${pokemonId}.gif`, backShinyGifPath)) {
    result.backShiny = { file: `${pokemonId}.gif`, isAnimated: true };
  } else if (await downloadFile(`${BASE_URLS.staticBackShiny}${pokemonId}.png`, backShinyPngPath)) {
    result.backShiny = { file: `${pokemonId}.png`, isAnimated: false };
  }

  // 5. Descargar Grito (Audio) en formato MP3 (con fallback a ogg por si acaso)
  const cryMp3Path = path.join(OUTPUT_DIRS.cries, `${pokemonId}.mp3`);
  const cryOggPath = path.join(OUTPUT_DIRS.cries, `${pokemonId}.ogg`);
  if (await downloadFile(`${BASE_URLS.cries}${pokemonId}.mp3`, cryMp3Path)) {
    result.cry = { file: `${pokemonId}.mp3` };
  } else if (await downloadFile(`${BASE_URLS.cries}${pokemonId}.ogg`, cryOggPath)) {
    result.cry = { file: `${pokemonId}.ogg` };
  }

  return result;
}

/**
 * Asegura la existencia de los directorios de salida necesarios.
 */
export async function ensureDirsExist() {
  for (const dir of Object.values(OUTPUT_DIRS)) {
    await fs.mkdir(dir, { recursive: true });
  }
}

/**
 * Orquesta la descarga de todos los sprites y sonidos en lotes concurrentes con delay de cortesía.
 */
export async function downloadAllSprites(
  pokemonIds: string[],
  concurrencyLimit = 5,
  delayMs = 50
): Promise<Record<string, {
  front: string;
  frontAnimated: boolean;
  back: string;
  backAnimated: boolean;
  frontShiny: string;
  frontShinyAnimated: boolean;
  backShiny: string;
  backShinyAnimated: boolean;
  cry: string;
}>> {
  await ensureDirsExist();
  const assetMap: Record<string, {
    front: string;
    frontAnimated: boolean;
    back: string;
    backAnimated: boolean;
    frontShiny: string;
    frontShinyAnimated: boolean;
    backShiny: string;
    backShinyAnimated: boolean;
    cry: string;
  }> = {};

  const total = pokemonIds.length;
  console.log(`\n📥 Iniciando descarga de sprites (normal/shiny) y sonidos para ${total} Pokémon en lotes de ${concurrencyLimit}...`);

  for (let i = 0; i < total; i += concurrencyLimit) {
    const batch = pokemonIds.slice(i, i + concurrencyLimit);

    // Descargar el lote actual en paralelo
    const promises = batch.map(async (id) => {
      const res = await downloadPokemonAssets(id);
      assetMap[id] = {
        front: res.front.file,
        frontAnimated: res.front.isAnimated,
        back: res.back.file,
        backAnimated: res.back.isAnimated,
        frontShiny: res.frontShiny.file,
        frontShinyAnimated: res.frontShiny.isAnimated,
        backShiny: res.backShiny.file,
        backShinyAnimated: res.backShiny.isAnimated,
        cry: res.cry.file,
      };
    });

    await Promise.all(promises);

    const progress = Math.min(i + concurrencyLimit, total);
    console.log(`[Progreso] ${progress}/${total} Pokémon procesados...`);

    // Delay de cortesía para evitar rate-limits
    if (i + concurrencyLimit < total && delayMs > 0) {
      await new Promise((resolve) => setTimeout(resolve, delayMs));
    }
  }

  console.log('✅ Descarga de todos los recursos (comunes, shinies y gritos) finalizada.');
  return assetMap;
}

