interface LocalMove {
  id: string;
  name: string;
  type: string;
  basePower: number;
}

/**
 * Genera movimientos aleatorios para un Pokémon del banco, garantizando al menos un ataque STAB
 */
function getRandomMoves(pokemonTypes: string[], allMoves: LocalMove[]): string[] {
  const moves: string[] = [];
  const primaryType = pokemonTypes[0];
  const sameTypeMoves = allMoves.filter(m => m.type === primaryType && m.basePower > 0);

  if (sameTypeMoves.length > 0) {
    const idx = Math.floor(Math.random() * sameTypeMoves.length);
    const chosenMove = sameTypeMoves[idx];
    if (chosenMove) {
      moves.push(chosenMove.id);
    }
  }

  while (moves.length < 4) {
    const randomMove = allMoves[Math.floor(Math.random() * allMoves.length)];
    if (randomMove && !moves.includes(randomMove.id)) {
      moves.push(randomMove.id);
    }
  }
  return moves;
}

export const useShowdownSandboxStore = defineStore('showdownSandbox', {
  state: () => ({
    // Setup UI
    isSetupMode: true,
    playerPokemonId: 'charizard',
    playerMoves: ['flamethrower', 'airslash', 'dragonpulse', 'roost'],
    enemyPokemonId: 'blastoise',
    enemyMoves: ['surf', 'icebeam', 'darkpulse', 'shellsmash'],
    playerShiny: false,
    enemyShiny: false,

    // Battle State
    worker: null as Worker | null,
    playerPokemon: null as SandboxPokemon | null,
    enemyPokemon: null as SandboxPokemon | null,
    playerTeam: [] as SandboxPokemon[],
    enemyTeam: [] as SandboxPokemon[],
    playerSimTeam: [] as SandboxSimPokemon[],
    enemySimTeam: [] as SandboxSimPokemon[],
    activePlayerIndex: 0,
    activeEnemyIndex: 0,
    forcedSwitchRequired: false,
    playerHP: 100,
    playerMaxHP: 100,
    enemyHP: 100,
    enemyMaxHP: 100,
    battleLog: [] as ParsedEvent[],
    currentMessage: '¡Esperando conexión con el motor de Showdown!',
    isAnimating: false,
    gameOver: false,
    winner: null as string | null,
    weather: { weather: '', weatherDuration: 0 } as { weather: string; weatherDuration: number },
    playerSideConditions: [] as Array<{ id: string; duration?: number; layers?: number }>,
    enemySideConditions: [] as Array<{ id: string; duration?: number; layers?: number }>,
  }),

  actions: {
    /**
     * Establece el líder Pokémon del jugador y auto-completa sus movimientos según su tipo elemental
     */
    setPlayerLeader(pokemonId: string) {
      this.playerPokemonId = pokemonId;
      this.playCry(pokemonId);
      const poke = typedDB.pokemon[pokemonId];
      if (poke) {
        const allLocalMoves = Object.values(typedDB.moves) as LocalMove[];
        this.playerMoves = getRandomMoves(poke.types, allLocalMoves);
      }
    },

    /**
     * Establece el líder Pokémon del rival y auto-completa sus movimientos según su tipo elemental
     */
    setEnemyLeader(pokemonId: string) {
      this.enemyPokemonId = pokemonId;
      this.playCry(pokemonId);
      const poke = typedDB.pokemon[pokemonId];
      if (poke) {
        const allLocalMoves = Object.values(typedDB.moves) as LocalMove[];
        this.enemyMoves = getRandomMoves(poke.types, allLocalMoves);
      }
    },

    /**
     * Genera un equipo completo de 6 Pokémon usando autocompletado competitivo
     */
    generateTeam(leaderId: string, leaderMoves: string[], isShiny: boolean, isPlayer: boolean): SandboxPokemon[] {
      const allPokeIds = Object.keys(typedDB.pokemon);
      const allMoves = Object.values(typedDB.moves);
      const team: SandboxPokemon[] = [];

      // 1. Agregar al líder seleccionado
      const leaderPoke = typedDB.pokemon[leaderId];
      if (leaderPoke && leaderPoke.sprites) {
        // SANITIZE LEADER MOVES: Filtrar vacíos, nulos, no válidos o duplicados
        let sanitizedMoves = leaderMoves
          .map(m => m ? m.trim().toLowerCase() : '')
          .filter(m => m !== '' && typedDB.moves[m]);

        sanitizedMoves = [...new Set(sanitizedMoves)];

        // Autocompletar hasta tener exactamente 4 movimientos válidos
        if (sanitizedMoves.length < 4) {
          const allLocalMoves = Object.values(typedDB.moves) as LocalMove[];
          const extraMoves = getRandomMoves(leaderPoke.types, allLocalMoves);
          for (const moveId of extraMoves) {
            if (!sanitizedMoves.includes(moveId) && sanitizedMoves.length < 4) {
              sanitizedMoves.push(moveId);
            }
          }
        }

        const leaderAbility = leaderPoke.abilities && leaderPoke.abilities.length > 0
          ? leaderPoke.abilities[0]
          : 'Espesura';
        const leaderNature = NATURES[Math.floor(Math.random() * NATURES.length)] || 'Serio';

        team.push({
          id: leaderId,
          name: leaderPoke.name,
          types: leaderPoke.types,
          spriteUrl: isShiny
            ? (isPlayer ? `showdown/assets/back-shiny/${leaderPoke.sprites.backShiny}` : `showdown/assets/front-shiny/${leaderPoke.sprites.frontShiny}`)
            : (isPlayer ? `showdown/assets/back/${leaderPoke.sprites.back}` : `showdown/assets/front/${leaderPoke.sprites.front}`),
          isAnimated: isShiny
            ? (isPlayer ? leaderPoke.sprites.backShinyAnimated : leaderPoke.sprites.frontShinyAnimated)
            : (isPlayer ? leaderPoke.sprites.backAnimated : leaderPoke.sprites.frontAnimated),
          moves: sanitizedMoves,
          hp: leaderPoke.baseStats.hp,
          maxHp: leaderPoke.baseStats.hp,
          status: '',
          num: leaderPoke.num,
          ability: leaderAbility,
          nature: leaderNature,
        });
      }

      // 2. Autocompletar con otros 5 Pokémon aleatorios
      const availableIds = allPokeIds.filter(id => id !== leaderId);

      // Mezclar usando el algoritmo Fisher-Yates
      for (let i = availableIds.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        const temp = availableIds[i];
        if (temp !== undefined) {
          availableIds[i] = availableIds[j]!;
          availableIds[j] = temp;
        }
      }

      for (let k = 0; k < 5; k++) {
        const pokeId = availableIds[k];
        if (!pokeId) continue;
        const poke = typedDB.pokemon[pokeId];
        if (poke && poke.sprites) {
          const moves = getRandomMoves(poke.types, allMoves);
          const spriteUrl = isPlayer
            ? `showdown/assets/back/${poke.sprites.back}`
            : `showdown/assets/front/${poke.sprites.front}`;

          const benchAbility = poke.abilities && poke.abilities.length > 0
            ? poke.abilities[Math.floor(Math.random() * poke.abilities.length)]
            : 'Espesura';
          const benchNature = NATURES[Math.floor(Math.random() * NATURES.length)] || 'Serio';

          team.push({
            id: pokeId,
            name: poke.name,
            types: poke.types,
            spriteUrl,
            isAnimated: isPlayer ? poke.sprites.backAnimated : poke.sprites.frontAnimated,
            moves,
            hp: poke.baseStats.hp,
            maxHp: poke.baseStats.hp,
            status: '',
            num: poke.num,
            ability: benchAbility,
            nature: benchNature,
          });
        }
      }

      return team;
    },

    /**
     * Sincroniza de forma segura la salud y estados alterados reportados por el Worker
     * sin destruir las propiedades enriquecidas de la UI (sprites, movimientos, tipos).
     */
    syncTeamStatus(isPlayer: boolean, workerTeam: SandboxPokemon[]) {
      const localTeam = isPlayer ? this.playerTeam : this.enemyTeam;
      for (const workerPoke of workerTeam) {
        const localPoke = localTeam.find(p => p.id === workerPoke.id);
        if (localPoke) {
          localPoke.hp = workerPoke.hp;
          localPoke.maxHp = workerPoke.maxHp;
          localPoke.status = workerPoke.status;
          localPoke.baseStoredStats = workerPoke.baseStoredStats;
          localPoke.storedStats = workerPoke.storedStats;
          localPoke.boosts = workerPoke.boosts;
          localPoke.statusState = workerPoke.statusState;
          localPoke.moveSlots = workerPoke.moveSlots;
          if (workerPoke.ability) localPoke.ability = workerPoke.ability;
          if (workerPoke.nature) localPoke.nature = workerPoke.nature;
          localPoke.volatiles = workerPoke.volatiles;
        }
      }

      // Actualizar también la referencia del Pokémon activo
      if (isPlayer && this.playerPokemon) {
        const activeLocal = localTeam.find(p => p.id === this.playerPokemon!.id);
        if (activeLocal) {
          this.playerPokemon = { ...activeLocal };
        }
      } else if (!isPlayer && this.enemyPokemon) {
        const activeLocal = localTeam.find(p => p.id === this.enemyPokemon!.id);
        if (activeLocal) {
          this.enemyPokemon = { ...activeLocal };
        }
      }
    },

    /**
     * Inicializa el combate completo de 6vs6 relevos
     */
    async startMockBattle() {
      this.isSetupMode = false;
      this.gameOver = false;
      this.winner = '';
      this.battleLog = [];
      this.forcedSwitchRequired = false;
      this.currentMessage = '¡El combate está por comenzar!';
      this.playerSimTeam = [];
      this.enemySimTeam = [];

      // 1. Generar los equipos completos de 6 miembros
      this.playerTeam = this.generateTeam(this.playerPokemonId, this.playerMoves, this.playerShiny, true);
      this.enemyTeam = this.generateTeam(this.enemyPokemonId, this.enemyMoves, this.enemyShiny, false);

      // Asignar líderes activos
      this.activePlayerIndex = 0;
      this.activeEnemyIndex = 0;
      this.playerPokemon = this.playerTeam[0] || null;
      this.enemyPokemon = this.enemyTeam[0] || null;

      // Reproducir gritos de entrada de manera secuencial y determinista usando GSAP
      const entranceTimeline = gsap.timeline();
      entranceTimeline.to({}, {
        duration: 0.1,
        onStart: () => {
          this.playCry(this.playerPokemonId);
        }
      }).to({}, {
        duration: 0.8,
        onStart: () => {
          this.playCry(this.enemyPokemonId);
        }
      });

      // Inicializar valores de salud
      this.playerHP = 100;
      this.playerMaxHP = 100;
      this.enemyHP = 100;
      this.enemyMaxHP = 100;

      // 2. Destruir worker anterior si existe
      if (this.worker) {
        this.worker.terminate();
      }

      // 3. Crear Web Worker dinámico
      this.worker = new Worker(
        new URL('./sandbox_db/ShowdownWorker.ts', import.meta.url),
        { type: 'module' }
      );

      // 4. Escuchar eventos del Worker
      this.worker.addEventListener('message', async (event) => {
        const { action, data } = event.data;

        if (action === 'started') {
          this.playerSimTeam = data.playerTeam || [];
          this.enemySimTeam = data.enemyTeam || [];
          this.weather = data.fieldState || { weather: '', weatherDuration: 0 };
          this.playerSideConditions = data.playerSideConditions || [];
          this.enemySideConditions = data.enemySideConditions || [];
          // Sincronizar equipos de 6 y HP reales del líder
          this.syncTeamStatus(true, data.playerTeam);
          this.syncTeamStatus(false, data.enemyTeam);
          this.playerHP = data.playerHP;
          this.playerMaxHP = data.playerMaxHP;
          this.enemyHP = data.enemyHP;
          this.enemyMaxHP = data.enemyMaxHP;

          const events = parseShowdownLog(data.logs);
          await this.executeAnimationQueue(events);
        } else if (action === 'turn_resolved') {
          const events = parseShowdownLog(data.logs);
          await this.executeAnimationQueue(events);

          this.playerSimTeam = data.playerTeam || [];
          this.enemySimTeam = data.enemyTeam || [];
          this.weather = data.fieldState || { weather: '', weatherDuration: 0 };
          this.playerSideConditions = data.playerSideConditions || [];
          this.enemySideConditions = data.enemySideConditions || [];
          // Sincronizar estadísticas de los equipos después de animar
          this.syncTeamStatus(true, data.playerTeam);
          this.syncTeamStatus(false, data.enemyTeam);
          this.playerHP = data.playerHP;
          this.playerMaxHP = data.playerMaxHP;
          this.enemyHP = data.enemyHP;
          this.enemyMaxHP = data.enemyMaxHP;

          // Comprobar condiciones de fin de combate o relevo obligatorio
          const playerActiveFainted = data.playerFainted;
          const enemyActiveFainted = data.enemyFainted;

          if (playerActiveFainted) {
            const hasHealthy = this.playerTeam.some(p => (p.hp ?? 0) > 0 && p.status !== 'fnt');
            if (hasHealthy) {
              this.forcedSwitchRequired = true;
              this.currentMessage = '¡Tu Pokémon activo se ha debilitado! ¡Debes elegir un relevo obligatorio!';
            } else {
              this.gameOver = true;
              this.winner = 'IA Rival';
              this.currentMessage = '¡Todo tu equipo ha sido debilitado! ¡Has perdido el combate!';
            }
          } else if (enemyActiveFainted) {
            const hasHealthy = this.enemyTeam.some(p => (p.hp ?? 0) > 0 && p.status !== 'fnt');
            if (!hasHealthy) {
              this.gameOver = true;
              this.winner = 'Jugador';
              this.currentMessage = '¡Has debilitado a todo el equipo rival! ¡Felicidades, ganaste!';
            }
          }
        } else if (action === 'error') {
          this.currentMessage = `Error de simulación: ${data.message}`;
          this.isAnimating = false;
        }
      });

      // 5. Iniciar batalla en el worker des-proxiada
      this.worker.postMessage({
        action: 'start',
        data: {
          playerTeam: JSON.parse(JSON.stringify(this.playerTeam)),
          enemyTeam: JSON.parse(JSON.stringify(this.enemyTeam)),
        },
      });
    },

    /**
     * Reproduce el grito oficial del Pokémon usando HTML5 Audio
     */
    playCry(pokemonId: string) {
      const pokemon = typedDB.pokemon[pokemonId];
      if (pokemon && pokemon.sprites && pokemon.sprites.cry) {
        if (typeof window !== 'undefined' && typeof Audio !== 'undefined') {
          const audio = new Audio(`showdown/assets/cries/${pokemon.sprites.cry}`);
          audio.volume = 0.4;
          audio.play().catch(err => {
            console.warn('El audio no pudo reproducirse (bloqueo de autoplay):', err);
          });
        }
      }
    },

    /**
     * Envía la elección del movimiento del jugador al Web Worker
     */
    chooseMove(moveIndex: number) {
      if (this.isAnimating || this.gameOver || !this.worker) return;

      this.isAnimating = true;
      this.worker.postMessage({
        action: 'choose',
        data: {
          playerChoice: `move ${moveIndex + 1}`,
        },
      });
    },

    /**
     * Envía la elección de relevo al Web Worker
     */
    chooseSwitch(targetIndex: number) {
      if (this.isAnimating || this.gameOver || !this.worker) return;

      this.isAnimating = true;
      this.forcedSwitchRequired = false;

      // Mapear el targetIndex (de la UI estática playerTeam) al simIndex (de la simulación dinámica playerSimTeam)
      const clickedPoke = this.playerTeam[targetIndex];
      let simIndex = targetIndex;
      if (clickedPoke && this.playerSimTeam.length > 0) {
        const foundIndex = this.playerSimTeam.findIndex(p => p.id === clickedPoke.id);
        if (foundIndex !== -1) {
          simIndex = foundIndex;
        }
      }

      this.worker.postMessage({
        action: 'choose',
        data: {
          playerChoice: `switch ${simIndex + 1}`,
        },
      });
    },

    /**
     * Orquestador secuencial de animaciones delegadas
     */
    async executeAnimationQueue(events: ParsedEvent[]) {
      await executeAnimationQueue(this, events);
      this.isAnimating = false;
    },
  },
});

import { ref, computed, watch, onMounted } from 'vue'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { generateRandomIVs } from '@/logic/pokemon/pokemonUtils'
import { NATURE_DATA } from '@/data/natures'
import { ABILITY_DATA } from '@/data/abilities'
import type { MapLocation } from '@/types/encounters'
import type { PokemonIVs } from '@/types/pokemon'

export interface PokemonConfig {
  id: string
  level: number
  isShiny: boolean
  isGuardian: boolean
  nature: string
  ability: string
  gender: 'M' | 'F'
  nickname: string
  friendship: number
  heldItem: string
  mapId: string
  ivs: PokemonIVs
  moves: (string | null)[]
  protocol: string
}

export interface SpeciesOption {
  id: string
  name: string
  icon?: string
}

export interface MapOption {
  id: string
  name: string
}

export function useDebugPokemonCreator() {
  const config = ref<PokemonConfig>({
    id: 'bulbasaur',
    level: 5,
    isShiny: false,
    isGuardian: false,
    nature: 'Firme',
    ability: 'Espesura',
    gender: 'M',
    nickname: '',
    friendship: 70,
    heldItem: '',
    mapId: 'route_1',
    ivs: { hp: 31, atk: 31, def: 31, spa: 31, spd: 31, spe: 31 },
    moves: [],
    protocol: 'catch'
  })

  const selectedMinigame = ref<'fishing' | 'archaeology'>('fishing')

  const allSpecies = computed<SpeciesOption[]>(() => {
    const db = pokemonDataProvider.getPokemonDb()
    return Object.keys(db).map(id => ({ 
      id, 
      name: db[id]?.name || id,
      icon: pokemonDataProvider.getSpriteUrl(id)
    }))
  })

  const allNatures = Object.keys(NATURE_DATA).map(n => ({ id: n, name: n }))
  const allAbilities = Object.keys(ABILITY_DATA).map(a => ({ id: a, name: a }))

  const allMaps = computed<MapOption[]>(() => {
    const maps = pokemonDataProvider.getMaps() as { id: string, name?: string }[]
    return maps.map(m => ({ id: m.id, name: m.name || m.id }))
  })

  const filteredMaps = computed(() => {
    const maps = pokemonDataProvider.getMaps() as unknown as MapLocation[]
    return maps
      .filter(m => {
        if (selectedMinigame.value === 'fishing') {
          return !!m.fishing
        } else if (selectedMinigame.value === 'archaeology') {
          return !!m.archaeology
        }
        return true
      })
      .map(m => ({ id: m.id, name: m.name || m.id }))
  })

  watch(selectedMinigame, () => {
    if (filteredMaps.value.length > 0) {
      config.value.mapId = filteredMaps.value[0]?.id || ''
    }
  })

  const speciesMoves = computed<string[]>(() => {
    const data = pokemonDataProvider.getPokemonData(config.value.id)
    if (!data || !data.learnset) return []
    return [...new Set(data.learnset.map(m => m.name))]
  })

  const baseStats = computed(() => {
    const data = pokemonDataProvider.getPokemonData(config.value.id)
    if (!data) return { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 }
    return {
      hp: data.hp || 0,
      atk: data.atk || 0,
      def: data.def || 0,
      spa: data.spa || 0,
      spd: data.spd || 0,
      spe: data.spe || 0
    }
  })

  function selectSpecies(p: SpeciesOption) {
    config.value.id = p.id
    const abilities = pokemonDataProvider.getSpeciesAbilities(p.id)
    if (abilities.length > 0) {
      config.value.ability = abilities[0] || ''
    }
    autoFillMoves()
  }

  watch(() => config.value.level, () => {
    autoFillMoves()
  })

  function autoFillMoves() {
    const data = pokemonDataProvider.getPokemonData(config.value.id)
    if (!data?.learnset) return

    const learnedMoves = data.learnset
      .filter(m => m.lv <= config.value.level)
      .sort((a, b) => b.lv - a.lv)
      .map(m => m.name)

    const uniqueMoves = [...new Set(learnedMoves)].slice(0, 4)
    const finalMoves: (string | null)[] = [...uniqueMoves]
    while (finalMoves.length < 4) finalMoves.push(null)

    config.value.moves = finalMoves as (string | null)[]
  }

  function randomFillMoves() {
    const data = pokemonDataProvider.getPokemonData(config.value.id)
    if (!data?.learnset || data.learnset.length === 0) return

    const allLearnsetMoves = [...new Set(data.learnset.map(m => m.name))]
    const shuffled = allLearnsetMoves.sort(() => 0.5 - Math.random())
    const selected = shuffled.slice(0, 4)
    const finalMoves: (string | null)[] = [...selected]
    while (finalMoves.length < 4) finalMoves.push(null)

    config.value.moves = finalMoves
  }

  function randomizeSpecies() {
    const speciesList = allSpecies.value
    if (speciesList.length === 0) return
    const randomSpecies = speciesList[Math.floor(Math.random() * speciesList.length)]
    if (randomSpecies) {
      selectSpecies(randomSpecies)
    }
  }

  function randomizeLevel() {
    config.value.level = Math.floor(Math.random() * 100) + 1
  }

  function randomizeIVs() {
    config.value.ivs = generateRandomIVs()
  }

  function randomizeNature() {
    const natures = allNatures
    const randomNature = natures[Math.floor(Math.random() * natures.length)]
    if (randomNature) {
      config.value.nature = randomNature.id
    }
  }

  function randomizeAbility() {
    const abilities = pokemonDataProvider.getSpeciesAbilities(config.value.id)
    if (abilities.length > 0) {
      const randomAbility = abilities[Math.floor(Math.random() * abilities.length)]
      if (randomAbility) {
        config.value.ability = randomAbility
      }
    }
  }

  function randomizeNickname() {
    const names = ['POKI', 'CRACK', 'VICIADO', 'RAYO', 'TITAN', 'FURIA', 'CHISPA', 'GOKU', 'PEPE']
    config.value.nickname = Math.random() > 0.3 ? names[Math.floor(Math.random() * names.length)] || '' : ''
  }

  function randomizeMinigame() {
    selectedMinigame.value = Math.random() > 0.5 ? 'fishing' : 'archaeology'
  }

  function randomizeOrigin() {
    const maps = filteredMaps.value.length > 0 ? filteredMaps.value : allMaps.value
    if (maps.length > 0) {
      const randomMap = maps[Math.floor(Math.random() * maps.length)]
      if (randomMap) {
        config.value.mapId = randomMap.id
      }
    }
  }

  function randomizeBase() {
    randomizeSpecies()
    randomizeLevel()
    randomizeNature()
    randomizeAbility()
    randomizeIVs()
  }

  function randomizeVisuals() {
    config.value.isShiny = Math.random() < 0.05
    config.value.isGuardian = Math.random() < 0.01
    config.value.gender = Math.random() > 0.5 ? 'M' : 'F'
  }

  function randomizeExtras() {
    randomizeNickname()
    randomizeMinigame()
    randomizeOrigin()
    config.value.friendship = Math.floor(Math.random() * 256)
  }

  function handleRandomize() {
    randomizeBase()
    randomizeVisuals()
    randomizeExtras()
    randomFillMoves()
  }

  onMounted(() => {
    if (allMaps.value.length > 0) {
      const firstMap = allMaps.value[0]
      if (firstMap) {
        config.value.mapId = firstMap.id
      }
    }
  })

  return {
    config,
    selectedMinigame,
    allSpecies,
    allNatures,
    allAbilities,
    allMaps,
    filteredMaps,
    speciesMoves,
    baseStats,
    selectSpecies,
    autoFillMoves,
    randomFillMoves,
    randomizeBase,
    randomizeSpecies,
    randomizeLevel,
    randomizeNature,
    randomizeAbility,
    randomizeIVs,
    randomizeVisuals,
    randomizeExtras,
    randomizeNickname,
    randomizeMinigame,
    randomizeOrigin,
    handleRandomize
  }
}

import { computed, watch, ref } from 'vue'
import { useBattleStore } from '@/stores/battle'
import { useUIStore } from '@/stores/ui'
import { useMapStore } from '@/stores/map'
import { useModalStore } from '@/stores/modals'
import { useGameStore } from '@/stores/game'
import { usePlayerClassStore } from '@/stores/playerClass'
import { getRouteWeather } from '@/logic/weather/weatherUtils'
import { getWeatherAnimSeed } from '@/logic/weather/weatherMath.ts'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import { POKEMON_FEET_DATABASE } from '@/data/pokemonFeetDatabase'
import { GYMS } from '@/data/gyms.ts'
import { logger } from '@/logic/utils/logger'
import type { Pokemon } from '@/types/pokemon'

export function useBattleArena(
  p1Pos: { x: number; y: number },
  p2Pos: { x: number; y: number },
  resetAll: () => void,
  preloadCombatCoords: (
    player: Pokemon | null,
    enemy: Pokemon | null,
    p1: { x: number; y: number },
    p2: { x: number; y: number },
    pTeam: Pokemon[],
    eTeam: Pokemon[]
  ) => void
) {
  const battleStore = useBattleStore()
  const mapStore = useMapStore()
  const uiStore = useUIStore()
  const gameStore = useGameStore()
  const classStore = usePlayerClassStore()
  const modalStore = useModalStore()

  const battle = computed(() => battleStore.state)
  const enemy = computed(() => battle.value?.enemy)

  const trainerShadowUrl = ref('')

  if (typeof document !== 'undefined') {
    const canvas = document.createElement('canvas')
    canvas.width = 10
    canvas.height = 7
    const ctx = canvas.getContext('2d')
    if (ctx) {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.35)'
      ctx.beginPath()
      ctx.ellipse(5, 3.5, 5, 3.5, 0, 0, Math.PI * 2)
      ctx.fill()
      trainerShadowUrl.value = canvas.toDataURL('image/png')
    }
  }

  const getTrainerShadowStyle = (spriteUrl: string, entitySize: number) => {
    let dbKey = spriteUrl || ''
    const base = import.meta.env.BASE_URL || '/'
    if (base !== '/' && dbKey.startsWith(base)) {
      dbKey = dbKey.slice(base.length - 1)
    }
    try {
      dbKey = decodeURIComponent(dbKey)
    } catch (_e) {
      // Ignore decode error
    }
    const cached = POKEMON_FEET_DATABASE[dbKey] || { feetY: 0.9, feetX: 0.5 }

    const widthPx = 0.7 * entitySize
    const heightPx = entitySize * 0.08
    const offsetX = (cached.feetX - 0.5) * entitySize

    return {
      position: 'absolute' as const,
      backgroundImage: `url(${trainerShadowUrl.value})`,
      backgroundSize: '100% 100%',
      backgroundRepeat: 'no-repeat',
      left: `calc(50% + ${offsetX}px)`,
      top: `${cached.feetY * 100}%`,
      width: `${widthPx}px`,
      height: `${heightPx}px`,
      transform: 'translate(-50%, -75%)',
      zIndex: -1,
      pointerEvents: 'none' as const
    }
  }

  const playerBackSpriteUrl = computed(() => {
    const spriteId = classStore.currentClassDef?.avatarSpriteId || classStore.currentClassDef?.id || 'entrenador'
    const gender = gameStore.state.gender || 'h'
    return getAssetUrl(ASSET_TYPES.TRAINER, spriteId, { trainerSuffix: 'back', gender })
  })

  const showStandingTrainers = computed(() => {
    return battleStore.isBattleActive && 
           battleStore.currentFsmState !== 'FIRST_INTRO' && 
           battleStore.currentFsmState !== 'INITIALIZING' &&
           !battleStore.isSearching
  })

  const trainerDialogText = computed(() => {
    if (!battle.value) return ''
    if (battle.value.isGym && battle.value.gymId) {
      const gym = GYMS.find(g => g.id === battle.value?.gymId)
      if (gym) return gym.quote
    }
    if (battle.value.quote) return battle.value.quote
    return '¡Prepárate para combatir! ¡No te lo pondré fácil!'
  })

  const triggerPreloadCoords = () => preloadCombatCoords(
    battle.value?.player || null,
    battle.value?.enemy || null,
    p1Pos,
    p2Pos,
    battle.value?.playerTeam || [],
    battle.value?.enemyTeam || []
  )

  const handleMinigameCancel = async () => {
    logger.warn('useBattleArena', 'Minigame CANCELLED by user')
    if (battleStore.state) {
      battleStore.state.isFishing = false
      battleStore.state.isArchaeology = false
    }
    resetAll()
    battleStore.attackerSide = null
    battleStore.activeMove = null
    battleStore.enemyStages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 }
    await battleStore.completeBattleFlow('map')
  }

  const handleFishingSuccess = async () => {
    logger.success('useBattleArena', 'Fishing SUCCESS')
    if (battleStore.state) {
      battleStore.state.isFishing = false
      battleStore.state.isArchaeology = false
    }
    resetAll()
    await battleStore.startEncounter()
  }

  const handleFishingFail = async () => {
    logger.warn('useBattleArena', 'Fishing FAIL')
    uiStore.notify('El Pokémon escapó...', '💨')
    battleStore.addLog('El Pokémon escapó...', 'log-info')

    if (battleStore.state) {
      battleStore.state.isFishing = false
      battleStore.state.isArchaeology = false
    }
    resetAll()
    battleStore.attackerSide = null
    battleStore.activeMove = null
    battleStore.enemyStages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 }

    await battleStore.completeBattleFlow('search')
  }

  const handleArchaeologySuccess = async (difficulty: string) => {
    logger.success('useBattleArena', `Archaeology SUCCESS: ${difficulty}`)
    const locId = battleStore.state?.locationId || 'route1'
    await mapStore.triggerArchaeologyRewards(locId, difficulty)

    if (battleStore.state) {
      battleStore.state.isArchaeology = false
      battleStore.state.isFishing = false
    }
    resetAll()
    battleStore.attackerSide = null
    battleStore.activeMove = null
    battleStore.enemyStages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 }

    await battleStore.completeBattleFlow('search')
  }

  const handleArchaeologyFail = async () => {
    logger.warn('useBattleArena', 'Archaeology FAIL')

    let fossilName = 'Ámbar Viejo'
    let emoji = '💎'
    if (enemy.value?.id === 'kabuto') {
      fossilName = 'Fósil Domo'
      emoji = '🛡'
    } else if (enemy.value?.id === 'omanyte') {
      fossilName = 'Fósil Hélix'
      emoji = '🐚'
    }

    const { getItemByName } = await import('@/data/items')
    const itemData = getItemByName(fossilName)
    const itemSprite = itemData ? getAssetUrl(ASSET_TYPES.ITEM, itemData.sprite) : emoji

    uiStore.notify(`El ${fossilName} se desmoronó...`, itemSprite)
    battleStore.addLog(`El ${fossilName} se desmoronó...`, 'log-info', fossilName)

    if (battleStore.state) {
      battleStore.state.isArchaeology = false
      battleStore.state.isFishing = false
    }
    resetAll()
    battleStore.attackerSide = null
    battleStore.activeMove = null
    battleStore.enemyStages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 }

    await battleStore.completeBattleFlow('search')
  }

  const computedWeather = computed(() => {
    if (mapStore.globalWeather) return mapStore.globalWeather
    return getRouteWeather(battle.value?.locationId || 'route1', mapStore.currentSeason.id, mapStore.currentEpochHour, mapStore.currentCycle)
  })

  const atmosphereSeed = computed(() => {
    return getWeatherAnimSeed(battle.value?.locationId || 'route1')
  })

  // FSM Watcher Setup
  watch(
    () => {
      const fsm = battleStore.fsm
      if (!fsm) return [null, null]
      return [fsm.currentState, fsm.currentSubState]
    },
    async ([newState, newSubState]) => {
      logger.debug('useBattleArena', `FSM: ${newState} ${newSubState || ''}`)
      if (!newState) return

      if (newState === 'FIRST_INTRO') {
        logger.info('useBattleArena', 'Phase: FIRST_INTRO')
      }

      if (newState === 'REWARDS_PHASE' && newSubState === 'EMPTY_WAIT') {
        logger.info('useBattleArena', '-> EMPTY_WAIT (REWARDS_PHASE)')
        resetAll()
        battleStore.attackerSide = null
        battleStore.activeMove = null
        battleStore.enemyStages = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 }
      }

      if (newSubState === 'MINIGAME_CHECK' && enemy.value) {
        if (battleStore.state?.isFishing) {
          modalStore.open('Fishing', {
            pokemon: enemy.value,
            rarity: battle.value?.rarity || 50,
            onWin: handleFishingSuccess,
            onFail: handleFishingFail,
            onCloseCallback: handleMinigameCancel
          })
        } else if (battleStore.state?.isArchaeology) {
          modalStore.open('Archaeology', {
            pokemon: enemy.value,
            rarity: battle.value?.rarity || 50,
            onWin: handleArchaeologySuccess,
            onFail: handleArchaeologyFail,
            onCloseCallback: handleMinigameCancel
          })
        }
      }
    },
    { immediate: true }
  )

  watch(() => battleStore.currentSubState, async (sub) => {
    if (sub === 'PRELOAD_FINAL_COORDS') await triggerPreloadCoords()
  })

  return {
    computedWeather,
    atmosphereSeed,
    trainerDialogText,
    showStandingTrainers,
    playerBackSpriteUrl,
    getTrainerShadowStyle,
    triggerPreloadCoords,
    handleMinigameCancel
  }
}

import { watch, type Ref, nextTick, type ComputedRef, computed } from 'vue'
import { gsap } from 'gsap'
import { gameBus } from '@/logic/events/gameBus'
import { WORLD_CONSTANTS } from '@/logic/combat/spatialCoordinator'
import type { Pokemon } from '@/types/pokemon'
import type { BattleStages } from '@/types/battle'
import { isFlying } from '@/composables/useBattleShadows'

interface SparkleData {
  id: string | number
  tx: number
  ty: number
  tf: number
  scale: number
  delay: string
}

interface BattleCombatantProps {
  side: 'player' | 'enemy'
  pokemon?: Pokemon | null
  position: { x: number; y: number }
  targetPosition?: { x: number; y: number } | null
  baseSize: number
  groundY?: string
  shadowKey?: string | null
  animState?: 'catching' | 'trapped' | 'releasing' | null
  ballId?: string
  isShaking?: boolean
  isBlinking?: boolean
  isHealing?: boolean
  isSilhouette?: boolean
  isAttacking?: boolean
  activeMove?: { side: string; cat: 'physical' | 'special' | 'status' | 'selfKO'; name: string; selfKO?: boolean } | null
  showGuides?: boolean
  isCaptureSuccess?: boolean
  sparkles?: SparkleData[]
  isFainting?: boolean
  isEmerging?: boolean
  suppressFX?: boolean
  hidden?: boolean
  hasSeat?: boolean
  stages?: Partial<BattleStages>
}

export function useBattleCombatantAnims(
  props: BattleCombatantProps,
  spriteRef: Ref<HTMLElement | null>,
  spriteRotationRef: Ref<HTMLElement | null>,
  shadowWrapperRef: Ref<HTMLElement | null>,
  pokeballImgRef: Ref<HTMLImageElement | null>,
  idleWrapperRef: Ref<HTMLElement | null>,
  cacheKey: ComputedRef<string>,
  getSpriteFeetOrigin: () => string,
  getBallTargetCoords: () => { x: number; y: number },
  rawCoordsCache: Map<string, { x: number; y: number }>,
  wasCaptured: Ref<boolean>
) {
  let successBlinkTween: gsap.core.Tween | null = null
  let idleTween: gsap.core.Tween | null = null

  const isFloating = computed(() => {
    if (!props.pokemon) return false
    return isFlying(props.pokemon)
  })

  const initIdleAnim = () => {
    if (!idleWrapperRef.value || !props.pokemon) return
    if (idleTween) {
      idleTween.kill()
      idleTween = null
    }

    const status = props.pokemon.status?.toLowerCase() || ''
    const isFrozen = status === 'freeze' || status === '🧊'
    const isPara = status.includes('paraly') || status.includes('para') || status === '⚡'
    const isConfused = (props.pokemon.confused || 0) > 0
    const isTrapped = (props.animState as string) === 'trapped'
    const isCatching = props.animState === 'catching'

    // Reset existing transforms before starting new tweens to prevent properties persisting between states
    gsap.killTweensOf(idleWrapperRef.value)

    if (isFrozen || isPara || isConfused || isTrapped || isCatching) {
      gsap.set(idleWrapperRef.value, { y: 0, rotation: 0, scaleX: 1, scaleY: 1 })
      return
    }

    if (isFloating.value) {
      gsap.set(idleWrapperRef.value, { scaleX: 1, scaleY: 1 })
      idleTween = gsap.to(idleWrapperRef.value, {
        y: () => `-${10 + Math.random() * 6}%`,
        rotation: () => (Math.random() > 0.5 ? 1 : -1) * (1 + Math.random() * 4),
        duration: () => 2 + Math.random() * 1,
        repeat: -1,
        yoyo: true,
        repeatRefresh: true,
        ease: 'sine.inOut'
      })
    } else {
      gsap.set(idleWrapperRef.value, { y: 0 })
      idleTween = gsap.to(idleWrapperRef.value, {
        scaleX: () => 1.01 + Math.random() * 0.02,
        scaleY: () => 0.97 + Math.random() * 0.02,
        rotation: () => (Math.random() > 0.5 ? 1 : -1) * (0.5 + Math.random() * 1),
        duration: () => 1.5 + Math.random() * 0.5,
        repeat: -1,
        yoyo: true,
        repeatRefresh: true,
        ease: 'sine.inOut'
      })
    }
  }

  watch(() => [props.pokemon?.status, props.pokemon?.confused, props.animState, isFloating.value], () => {
    if (idleWrapperRef.value) initIdleAnim()
  }, { deep: true })

  watch(idleWrapperRef, (el) => {
    if (el) initIdleAnim()
  })

  const triggerBallAnimation = (val: string | null) => {
    if (!spriteRef.value || !val) return

    if (val === 'catching') {
      const origin = getSpriteFeetOrigin()
      const cachedRaw = rawCoordsCache.get(cacheKey.value)
      const coords = cachedRaw || getBallTargetCoords()

      if (shadowWrapperRef.value) {
        gsap.set(shadowWrapperRef.value, { display: "none" })
      }

      gsap.killTweensOf(spriteRef.value)

      gsap.set(spriteRef.value, { 
        transformOrigin: origin,
        filter: "url(#pixel-energy-optimized)" 
      })

      const tween = gsap.to(spriteRef.value, {
        x: coords.x,
        y: coords.y,
        scale: 0,
        opacity: 0,
        duration: 0.5,
        ease: "power2.inOut",
        onComplete: () => {
          if (spriteRef.value) {
            gsap.set(spriteRef.value, { x: 0, y: 0, scale: 0, opacity: 0, filter: "none", clearProps: "transformOrigin" })
          }
        }
      })

      const animKey = `${props.side}-${props.pokemon?.uid || 'active'}`
      gameBus.emit('REGISTER_TWEEN', { key: animKey, tween })
    } else if (val === 'releasing') {
      const origin = getSpriteFeetOrigin()
      const cachedRaw = rawCoordsCache.get(cacheKey.value)
      const coords = cachedRaw || getBallTargetCoords()

      if (shadowWrapperRef.value) {
        gsap.set(shadowWrapperRef.value, { display: "none" })
      }

      gsap.killTweensOf(spriteRef.value)

      gsap.set(spriteRef.value, { 
        transformOrigin: origin,
        x: coords.x, 
        y: coords.y, 
        scale: 0, 
        opacity: 0, 
        filter: "url(#pixel-energy-optimized)" 
      })

      const tween = gsap.to(spriteRef.value, {
        x: 0,
        y: 0,
        scale: 1,
        opacity: 1,
        duration: 0.5,
        ease: "power2.inOut",
        onComplete: () => {
          if (spriteRef.value) {
            gsap.set(spriteRef.value, { clearProps: "transform,filter,transformOrigin,opacity" })
          }
          if (shadowWrapperRef.value) {
            gsap.set(shadowWrapperRef.value, { clearProps: "display" })
          }
        }
      })

      const animKey = `${props.side}-${props.pokemon?.uid || 'active'}`
      gameBus.emit('REGISTER_TWEEN', { key: animKey, tween })
    }
  }

  watch(() => props.animState, (val) => {
    nextTick(() => triggerBallAnimation(val || null))
  }, { immediate: true })

  watch(spriteRef, (newEl) => {
    if (newEl) {
      nextTick(() => triggerBallAnimation(props.animState || null))
    }
  })

  watch(() => props.isEmerging, (val) => {
    const target = idleWrapperRef.value || spriteRef.value
    if (val && target) {
      const tl = gsap.timeline({
        onComplete: () => {
          gsap.set(target, { clearProps: "transform" })
        }
      })
      tl.to(target, { y: 8, scaleX: 1.2, scaleY: 0.75, duration: 0.1, ease: "power1.in" })
        .to(target, { y: -60, scaleX: 0.85, scaleY: 1.2, duration: 0.3, ease: "power2.out" })
        .to(target, { y: 0, scaleX: 1.1, scaleY: 0.9, duration: 0.2, ease: "bounce.out" })
        .to(target, { scaleX: 1, scaleY: 1, duration: 0.1 })
    }
  })

  watch(() => props.isFainting, (val) => {
    if (val && spriteRef.value) {
      const tl = gsap.timeline()

      gsap.set(spriteRef.value, { transition: "none" })

      if (shadowWrapperRef.value) {
        gsap.set(shadowWrapperRef.value, { display: "none" })
      }

      tl.addLabel("fallStart")

      tl.to(spriteRef.value, { 
        y: 60, 
        duration: 1.0, 
        ease: "power2.in" 
      }, "fallStart") 

      const blinkPattern = [
        { t: 0.05, op: 0 }, { t: 0.13, op: 1 },
        { t: 0.21, op: 0 }, { t: 0.29, op: 1 },
        { t: 0.37, op: 0 }, { t: 0.45, op: 1 },
        { t: 0.53, op: 0 }, { t: 0.61, op: 1 },
        { t: 0.69, op: 0 }, { t: 0.77, op: 1 },
        { t: 0.85, op: 0 }, { t: 0.93, op: 1 },
        { t: 0.98, op: 0 }
      ]

      blinkPattern.forEach(b => {
        tl.set(spriteRef.value, { opacity: b.op }, `fallStart+=${b.t}`)
      })
    } else if (!val && spriteRef.value) {
      gsap.set(spriteRef.value, { clearProps: "opacity,y,transition" })
      if (shadowWrapperRef.value) {
        gsap.set(shadowWrapperRef.value, { clearProps: "display" })
      }
    }
  })

  watch(() => {
    if (!props.isAttacking || !props.activeMove) return null
    return `${props.isAttacking}-${props.activeMove.name}-${props.activeMove.cat}`
  }, (newVal) => {
    if (newVal && spriteRef.value) {
      const move = props.activeMove
      if (!move) return
      const isPlayerSide = props.side === 'player'
      const cat = move.cat
      const tl = gsap.timeline()

      let nx = isPlayerSide ? 1 : -1
      let ny = isPlayerSide ? -0.5 : 0.5

      if (props.targetPosition) {
        const scale = (WORLD_CONSTANTS as { OBJECT_SCALE: number }).OBJECT_SCALE || 2
        const mySize = props.baseSize * scale
        const targetBase = isPlayerSide ? (WORLD_CONSTANTS as { BASE_ENTITY_SIZE_ENEMY: number }).BASE_ENTITY_SIZE_ENEMY : (WORLD_CONSTANTS as { BASE_ENTITY_SIZE_PLAYER: number }).BASE_ENTITY_SIZE_PLAYER
        const targetSize = targetBase * scale

        const myCenterX = props.position.x + (mySize / 2)
        const myCenterY = props.position.y + (mySize / 2)

        const targetCenterX = props.targetPosition.x + (targetSize / 2)
        const targetCenterY = props.targetPosition.y + (targetSize / 2)

        const dx = targetCenterX - myCenterX
        const dy = targetCenterY - myCenterY
        const length = Math.sqrt(dx * dx + dy * dy)
        if (length > 0) {
          nx = dx / length
          ny = dy / length
        }
      }

      if (move.selfKO || cat === 'selfKO') {
        const shakeTimeline = gsap.timeline()
        for (let i = 0; i < 8; i++) {
          const shakeX = (Math.random() - 0.5) * 30
          const shakeY = (Math.random() - 0.5) * 30
          shakeTimeline.to(spriteRef.value, {
            x: shakeX,
            y: shakeY,
            duration: 0.05,
            ease: "none"
          })
        }
        tl.add(shakeTimeline)

        tl.add(() => {
          gameBus.emit('PLAY_SOUND', 'faint')
        })

        tl.to(spriteRef.value, {
          scale: 1.6,
          filter: "Brightness(1.8) Drop-Shadow(0 0 25px #ff4500)",
          duration: 0.25,
          ease: "power2.out"
        })

        tl.to(spriteRef.value, {
          scale: 0,
          opacity: 0,
          filter: "Brightness(3) Drop-Shadow(0 0 35px #ffffff)",
          duration: 0.35,
          ease: "power2.in"
        })

        tl.to(spriteRef.value, {
          x: 0,
          y: 0,
          scale: 1,
          opacity: 1,
          filter: "Brightness(1)",
          clearProps: "all",
          duration: 0.01
        })
      } else if (cat === 'physical' || !cat) {
        const dashDist = 60
        const prepDist = -15

        tl.to(spriteRef.value, { x: nx * prepDist, y: ny * prepDist, duration: 0.1 })
          .to(spriteRef.value, { x: nx * dashDist, y: ny * dashDist, scale: 1.1, duration: 0.15, ease: "power2.out" })
          .to(spriteRef.value, { x: 0, y: 0, scale: 1, duration: 0.15, ease: "power1.inOut" })
      } else if (cat === 'special') {
        const pulseDist = 15
        tl.fromTo(spriteRef.value, 
          { filter: "Brightness(1)", x: 0, y: 0, scale: 1 },
          { 
            x: nx * pulseDist, 
            y: ny * pulseDist, 
            scale: 1.15, 
            filter: "Brightness(1.4)", 
            duration: 0.2, 
            yoyo: true, 
            repeat: 1,
            ease: "power2.out"
          }
        )
      } else if (cat === 'status') {
        const rot = isPlayerSide ? 12 : -12
        tl.fromTo(spriteRotationRef.value, 
          { filter: "Brightness(1)", rotation: 0, scale: 1 },
          { 
            rotation: rot, 
            scale: 1.1, 
            filter: "Brightness(1.2)", 
            duration: 0.2, 
            yoyo: true, 
            repeat: 1,
            ease: "power2.out"
          }
        )
      }

      const animKey = `attack-${props.side}`
      gameBus.emit('REGISTER_TWEEN', { key: animKey, tween: tl })
    }
  })

  watch(() => props.pokemon?.status, (newS, oldS) => {
    if (!spriteRotationRef.value) return

    if (newS && newS !== oldS) {
      const statusColors: Record<string, string> = {
        burn: '#ff4500',
        poison: '#9400d3',
        paralysis: '#ffd700',
        freeze: '#00ffff',
        sleep: '#ffffff'
      }
      const color = statusColors[newS] || '#ffffff'

      gsap.killTweensOf(spriteRotationRef.value, "filter")

      gsap.fromTo(spriteRotationRef.value,
        { filter: `Drop-Shadow(0 0 0px ${color}) Brightness(1)` },
        { 
          filter: `Drop-Shadow(0 0 20px ${color}) Brightness(2)`, 
          duration: 0.25, 
          yoyo: true, 
          repeat: 3, 
          ease: "power1.inOut",
          onComplete: () => {
            if (spriteRotationRef.value) {
              gsap.set(spriteRotationRef.value, { clearProps: "filter" })
            }
          }
        }
      )
    } else if (!newS && oldS) {
      if (spriteRotationRef.value) {
        gsap.killTweensOf(spriteRotationRef.value, "filter")
        gsap.set(spriteRotationRef.value, { clearProps: "filter" })
      }
    }
  })

  watch(() => props.isShaking, (shaking) => {
    if (pokeballImgRef.value) {
      if (shaking) {
        gameBus.emit('PLAY_SOUND', 'wobble')
        gsap.to(pokeballImgRef.value, {
          keyframes: [
            { rotation: 18, duration: 0.08, ease: 'power1.out' },
            { rotation: -18, duration: 0.16, ease: 'power1.inOut' },
            { rotation: 12, duration: 0.14, ease: 'power1.inOut' },
            { rotation: -12, duration: 0.14, ease: 'power1.inOut' },
            { rotation: 0, duration: 0.08, ease: 'power1.in' }
          ]
        })
      }
    } 
    else if (!props.isCaptureSuccess) {
      if (shaking && spriteRef.value) {
        const shakeDist = props.side === 'player' ? -10 : 10
        gsap.set(spriteRef.value, { transition: "none" })

        gsap.fromTo(spriteRef.value,
          { x: 0 },
          { 
            x: shakeDist, 
            duration: 0.08, 
            yoyo: true, 
            repeat: 5, 
            ease: 'power1.inOut',
            onComplete: () => { if (spriteRef.value) gsap.set(spriteRef.value, { clearProps: "x,opacity,transition" }) }
          }
        )

        const tl = gsap.timeline()
        const blinkPattern = [
          { t: 0.00, op: 0 }, { t: 0.08, op: 1 },
          { t: 0.16, op: 0 }, { t: 0.24, op: 1 },
          { t: 0.32, op: 0 }, { t: 0.40, op: 1 },
          { t: 0.48, op: 1 }
        ]
        blinkPattern.forEach(b => {
          tl.set(spriteRef.value, { opacity: b.op }, b.t)
        })
      }
    }
  })

  watch(() => props.isBlinking, (blinking) => {
    if (pokeballImgRef.value) {
      if (blinking) {
        gsap.fromTo(pokeballImgRef.value,
          { filter: 'Brightness(1)' },
          { filter: 'Brightness(2) Hue-Rotate(10deg)', duration: 0.2, yoyo: true, repeat: 1, ease: 'power1.inOut' }
        )
      }
    } 
    else if (!props.isCaptureSuccess) {
      if (blinking && spriteRef.value) {
        const shakeDist = props.side === 'player' ? -10 : 10
        gsap.set(spriteRef.value, { transition: "none" })
        gsap.fromTo(spriteRef.value,
          { x: 0, filter: 'Brightness(1)' },
          { 
            x: shakeDist,
            filter: 'Brightness(2)', 
            duration: 0.08, 
            yoyo: true, 
            repeat: 5, 
            ease: 'power1.inOut',
            onComplete: () => { if (spriteRef.value) gsap.set(spriteRef.value, { clearProps: "x,filter,transition" }) }
          }
        )
      }
    }
  })

  watch(() => props.isHealing, (val) => {
    if (val && spriteRotationRef.value) {
      gsap.set(spriteRotationRef.value, { transition: "none" })
      const tl = gsap.timeline()
      tl.to(spriteRotationRef.value, {
        y: -15,
        scale: 1.08,
        filter: "brightness(1.4) sepia(0.8) hue-rotate(300deg) saturate(2)",
        duration: 0.25,
        ease: "power1.out"
      })
      .to(spriteRotationRef.value, {
        y: 0,
        scale: 1,
        filter: "brightness(1) sepia(0) hue-rotate(0deg) saturate(1)",
        duration: 0.25,
        ease: "power1.in",
        onComplete: () => {
          if (spriteRotationRef.value) {
            gsap.set(spriteRotationRef.value, { clearProps: "y,scale,filter,transition" })
          }
        }
      })
    }
  })

  watch(() => props.isCaptureSuccess, (success) => {
    if (success) {
      wasCaptured.value = true
    }
    if (!pokeballImgRef.value) return
    if (success) {
      successBlinkTween = gsap.fromTo(pokeballImgRef.value,
        { filter: 'Brightness(1)' },
        { filter: 'Brightness(1.8) Sepia(0.5) Hue-Rotate(-10deg)', duration: 0.25, yoyo: true, repeat: -1, ease: 'power1.inOut' }
      )
    } else {
      if (successBlinkTween) {
        successBlinkTween.kill()
        successBlinkTween = null
      }
      gsap.set(pokeballImgRef.value, { clearProps: 'filter' })
    }
  })
}

export function onSparkleEnter(el: Element, done: () => void) {
  const htmlEl = el as HTMLElement
  const tx = parseFloat(htmlEl.dataset.tx || '0')
  const ty = parseFloat(htmlEl.dataset.ty || '0')
  const tf = parseFloat(htmlEl.dataset.tf || '0')
  const delay = parseFloat((htmlEl.dataset.delay || '0s').replace('s', ''))
  const scale = parseFloat(htmlEl.dataset.scale || '1')

  // Reset inicial forzado para evitar flashes o estados quietos
  gsap.set(htmlEl, { 
    x: 0, 
    y: 0, 
    xPercent: -50, 
    yPercent: -50, 
    scale: 0, 
    opacity: 1,
    rotation: 0
  })

  // Animación Horizontal y Rotación (Toda la duración)
  gsap.to(htmlEl, {
    x: tx,
    rotation: 720,
    duration: 0.8,
    delay: delay,
    ease: 'power1.out'
  })

  // Fase 1: Salto hacia arriba (Fountain Up)
  gsap.to(htmlEl, {
    y: ty,
    scale: scale,
    duration: 0.3,
    delay: delay,
    ease: 'power2.out',
    onComplete: () => {
      // Fase 2: Caída y desvanecimiento (Fountain Down)
      gsap.to(htmlEl, {
        y: tf,
        opacity: 0,
        duration: 0.5,
        ease: 'power2.in',
        onComplete: done
      })
    }
  })
}

export function onBallEnter(el: Element, done: () => void) {
  gsap.fromTo(el, 
    { opacity: 0, scale: 0.5 }, 
    { opacity: 1, scale: 1, duration: 0.4, ease: 'back.out(1.7)', onComplete: done }
  )
}

export function onBallLeave(el: Element, side: 'player' | 'enemy', done: () => void) {
  const tween = gsap.to(el, { 
    opacity: 0, 
    scale: 0.8, 
    duration: 0.3,
    ease: 'power2.in', 
    onComplete: done 
  })
  const animKey = `ball-fadeout-${side}`
  gameBus.emit('REGISTER_TWEEN', { key: animKey, tween })
}

import { ref, computed, watch, onMounted, onUnmounted, toValue } from 'vue';
