  opacity: number;
}

// Persistent cache for Pokéball coordinates and raw coordinates
const pokeballCoordsCache = new Map<string, { top: string; left: string }>();
const rawCoordsCache = new Map<string, { x: number; y: number }>();

export function useBattleCombatantState(
  props: BattleCombatantProps,
  emit: (e: 'load', size: { w: number; h: number }) => void,
  spriteRef: { value: HTMLElement | null }
) {
  const naturalSize = ref({ w: 0, h: 0 });
  const seatKey = computed(() => `${props.side}-${props.position.x}-${props.position.y}`);
  const cacheKey = computed(() => {
    if (props.pokemon) {
      return props.pokemon.uid || `${props.side}-${props.pokemon.id}`;
    }
    return seatKey.value;
  });

  const isFloating = computed(() => {
    if (!props.pokemon) return false;
    const data = pokemonDataProvider.getPokemonData(props.pokemon.id);
    if (!data) return false;
    if (data.isFloating !== undefined) return data.isFloating;
    const types: string[] = [];
    if (data.type) types.push(data.type.toLowerCase());
    if (data.type2) types.push(data.type2.toLowerCase());
    return types.includes('flying');
  });

  const isPlayer = computed(() => props.side === 'player');
  const isEnemy = computed(() => props.side === 'enemy');

  const spriteKey = computed(() => {
    if (!props.pokemon) return '';
    const id = props.pokemon.id;
    const stringId = String(id).toLowerCase();
    const num = (POKEMON_SPRITE_IDS as Record<string, number>)[stringId] || id;
    return String(num);
  });

  const idleKey = computed(() => {
    if (!spriteKey.value) return null;
    const match = spriteKey.value.match(/^(\d+)(.*)$/);
    if (!match) return null;
    const numId = match[1]!;
    const suffix = match[2]!;
    const isFemale = props.pokemon?.gender === 'F';

    const candidates = [`${numId}i${suffix}`, `${numId}${suffix}`];
    for (const cand of candidates) {
      if (isPlayer.value) {
        if (isFemale && ANIMATED_SPRITE_DATABASE[`${cand}_f_back`]) {
          return `${cand}_f_back`;
        }
        if (ANIMATED_SPRITE_DATABASE[`${cand}_back`]) {
          return `${cand}_back`;
        }
      } else {
        if (isFemale && ANIMATED_SPRITE_DATABASE[`${cand}_f`]) {
          return `${cand}_f`;
        }
        if (ANIMATED_SPRITE_DATABASE[cand]) {
          return cand;
        }
      }
    }
    return null;
  });

  const variationKey = computed(() => {
    if (!spriteKey.value) return null;
    const match = spriteKey.value.match(/^(\d+)(.*)$/);
    if (!match) return null;
    const numId = match[1]!;
    const suffix = match[2]!;
    const isFemale = props.pokemon?.gender === 'F';

    const cand = `${numId}v${suffix}`;
    if (isPlayer.value) {
      if (isFemale && ANIMATED_VARIATION_FRAMES[`${cand}_f_back`] !== undefined) {
        return `${cand}_f_back`;
      }
      if (ANIMATED_VARIATION_FRAMES[`${cand}_back`] !== undefined) {
        return `${cand}_back`;
      }
    } else {
      if (isFemale && ANIMATED_VARIATION_FRAMES[`${cand}_f`] !== undefined) {
        return `${cand}_f`;
      }
      if (ANIMATED_VARIATION_FRAMES[cand] !== undefined) {
        return cand;
      }
    }
    return null;
  });

  const isAnimated = computed(() => !!idleKey.value);

  const animatedMeta = computed(() => {
    if (!idleKey.value) return null;
    return ANIMATED_SPRITE_DATABASE[idleKey.value] || null;
  });

  const variationMeta = computed(() => {
    if (!variationKey.value) return null;
    const directMeta = ANIMATED_SPRITE_DATABASE[variationKey.value];
    if (directMeta) return directMeta;

    if (!animatedMeta.value) return null;
    const frames = ANIMATED_VARIATION_FRAMES[variationKey.value] || 0;
    return {
      frames,
      size: animatedMeta.value.size,
      feetY: animatedMeta.value.feetY,
      feetX: animatedMeta.value.feetX,
      bodyH: animatedMeta.value.bodyH,
      bodyW: animatedMeta.value.bodyW,
      bodyRadius: animatedMeta.value.bodyRadius
    };
  });

  const frames = computed(() => animatedMeta.value?.frames ?? 1);
  const frameSize = computed(() => animatedMeta.value?.size ?? 96);
  const scaleFactor = computed(() => {
    if (!animatedMeta.value) return 1.0;
    const maxSize = isPlayer.value ? MAX_ANIMATED_SPRITE_SIZE_BACK : MAX_ANIMATED_SPRITE_SIZE_FRONT;
    return animatedMeta.value.size / maxSize;
  });

  const displaySize = computed(() => {
    const sideMultiplier = props.side === 'enemy' ? 2 : 1.5;
    return Math.round(props.baseSize * scaleFactor.value * sideMultiplier);
  });

  const imageUrl = computed(() => {
    if (!props.pokemon) return '';
    return getAssetUrl(ASSET_TYPES.POKEMON, props.pokemon.id, {
      isShiny: !!props.pokemon.isShiny,
      isBack: isPlayer.value,
      isAnimated: isAnimated.value,
    });
  });

  const feetPoints = computed(() => {
    if (isFloating.value) {
      return { feetX: 0.5, feetY: 0.9 };
    }
    if (isAnimated.value && animatedMeta.value) {
      return {
        feetX: animatedMeta.value.feetX ?? 0.5,
        feetY: animatedMeta.value.feetY ?? 0.9
      };
    }
    const url = imageUrl.value;
    if (!url) return { feetX: 0.5, feetY: 0.9 };

    let key = url;
    const base = import.meta.env.BASE_URL || '/';
    if (base !== '/' && url.startsWith(base)) {
      key = url.slice(base.length - 1);
    }
    try {
      key = decodeURIComponent(key);
    } catch (_e) {
      // ignore
    }

    const dbPoints = POKEMON_FEET_DATABASE[key];
    if (!dbPoints) {
      throw new Error(`[PokemonFeetDatabase] Sprite key "${key}" not found in POKEMON_FEET_DATABASE. Did you forget to compile assets? Run "npm run assets:convert".`);
    }
    return {
      feetX: dbPoints.feetX,
      feetY: dbPoints.feetY
    };
  });

  const getAttackAnimClass = computed(() => {
    if (!props.isAttacking || !props.activeMove) return '';
    const move = props.activeMove;
    if (move.side !== props.side) return '';
    if (move.cat === 'physical') return 'atk-physical';
    if (move.cat === 'special') return 'atk-special';
    if (move.cat === 'status') return 'atk-status';
    return 'atk-default';
  });

  const pokeballShadowUrl = computed(() => {
    if (typeof document === 'undefined') return '';
    const w = 10,
      h = 7;
    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d');
    if (!ctx) return '';
    ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
    ctx.beginPath();
    ctx.ellipse(w / 2, h / 2, w / 2, h / 2, 0, 0, Math.PI * 2);
    ctx.fill();
    return `url(${canvas.toDataURL('image/png')})`;
  });

  const shadowStore = useCombatShadowStore();
  const battleStore = useBattleStore();
  const currentShadow = computed(() => (props.shadowKey ? shadowStore.activeShadows.get(props.shadowKey) : null));

  const localGroundY = computed(() => {
    // Ground line is fixed at 75% from top (= 25% from bottom of the entity box).
    // feetY from the DB is only used to ALIGN the sprite vertically (offset in the top calc).
    // It must NOT define where the ground line itself lives inside the entity box.
    const cached = pokeballCoordsCache.get(cacheKey.value);
    if (cached) return cached.top;
    return props.groundY || '75%';
  });

  const fxScale = computed(() => props.baseSize / 100);

  const fxRadius = computed(() => {
    if (!animatedMeta.value) {
      return 25;
    }
    if (animatedMeta.value.bodyRadius === undefined) {
      throw new Error(`[useBattleCombatantState] bodyRadius is not defined in animated database for: ${props.pokemon?.id}`);
    }
    // bodyRadius [0-1] = half the body occupancy relative to the sprite frame.
    // The pokemon-atmosphere-wrapper has size displaySize * 2 px.
    // Radius as % of the wrapper = bodyRadius * 100 (so diameter = bodyRadius * 200%).
    return Math.max(10, Math.min(80, animatedMeta.value.bodyRadius * 100));
  });

  // Exposed so the BattleCombatant template can show/hide the inline poke-radius debug guide
  // without importing battleStore directly in the component.
  const debugShowPokeRadius = computed(() => battleStore.debugShowPokeRadius);

  const stickyCoords = computed(() => {
    const scale = (WORLD_CONSTANTS as { OBJECT_SCALE: number }).OBJECT_SCALE || 2;
    const entitySize = props.baseSize * scale;
    const offsetX = (feetPoints.value.feetX - 0.5) * entitySize;
    const left = `calc(50% + ${offsetX}px)`;
    const top = localGroundY.value;
    return { top, left };
  });

  const isBallVisible = computed(() => {
    return (
      props.animState === 'trapped' ||
      props.animState === 'catching' ||
      props.animState === 'releasing' ||
      !!props.isCaptureSuccess
    );
  });

  const wasCaptured = ref(false);
  const internalBallId = ref('pokeball');
  const memorizedBallCoords = ref({ top: '90%', left: '50%' });

  const getSpriteFeetOrigin = () => {
    const scale = (WORLD_CONSTANTS as { OBJECT_SCALE: number }).OBJECT_SCALE || 2;
    const entitySize = props.baseSize * scale;
    const feetX = feetPoints.value.feetX;
    const offsetX = (feetX - 0.5) * entitySize;

    let floatOffset = 0;
    if (isFloating.value) {
      const isMobile = typeof window !== 'undefined' && window.innerWidth <= 690;
      floatOffset = isMobile ? 18 : 40;
    }

    return `calc(50% + ${offsetX}px) calc(${localGroundY.value} - ${floatOffset}px)`;
  };

  const getBallTargetCoords = () => {
    const scale = (WORLD_CONSTANTS as { OBJECT_SCALE: number }).OBJECT_SCALE || 2;
    const containerHeight = props.baseSize * scale;

    let floatOffset = 0;
    if (isFloating.value) {
      const isMobile = typeof window !== 'undefined' && window.innerWidth <= 690;
      floatOffset = isMobile ? 18 : 40;
    }

    const ballHeight = 40 * scale;
    const groundPct = parseFloat(localGroundY.value) / 100;
    const groundOffsetFromBottom = containerHeight * (groundPct - 1);

    const targetX = (feetPoints.value.feetX - 0.5) * (props.baseSize * scale);
    const targetY = groundOffsetFromBottom - ballHeight * 0.35 + floatOffset;

    return { x: targetX, y: targetY };
  };

  watch(
    () => [isBallVisible.value, stickyCoords.value] as const,
    ([visible]) => {
      if (visible) {
        internalBallId.value = props.ballId || 'pokeball';
        const newCoords = { ...stickyCoords.value };
        memorizedBallCoords.value = newCoords;
        pokeballCoordsCache.set(cacheKey.value, newCoords);
        rawCoordsCache.set(cacheKey.value, getBallTargetCoords());
      } else {
        const cached = pokeballCoordsCache.get(cacheKey.value);
        if (cached) {
          memorizedBallCoords.value = { ...cached };
        }
      }
    },
    { immediate: true, deep: true }
  );

  const handleImageError = (e: Event) => {
    (e.target as HTMLImageElement).src = getAssetUrl(ASSET_TYPES.ENVIRONMENT, 'bush-1');
  };

  const handleBallError = () => {
    throw new Error(`[BattleCombatant] Failed to load Pokeball image asset for ID: ${props.ballId}`);
  };

  const handleLoad = (e: Event) => {
    const target = e.target as HTMLImageElement;
    naturalSize.value = { w: target.naturalWidth, h: target.naturalHeight };
    emit('load', naturalSize.value);
  };

  // Escape Smoke Particles
  const smokeParticles = ref<SmokeParticle[]>([]);

  const runEscapeAnimation = (type: 'teleport' | 'flee') => {
    if (!spriteRef.value) return;

    if (type === 'teleport') {
      gameBus.emit('PLAY_SOUND', 'flee');

      const tl = gsap.timeline();
      const tween = tl.to(spriteRef.value, {
        scaleY: 2.0,
        scaleX: 0.1,
        opacity: 0,
        filter: 'brightness(3) contrast(1.5)',
        duration: 0.4,
        ease: 'power3.in',
        onComplete: () => {
          if (spriteRef.value) {
            gsap.set(spriteRef.value, { clearProps: 'scale,transform,filter' });
          }
        },
      });
      const animKey = `escape-${props.side}`;
      gameBus.emit('REGISTER_TWEEN', { key: animKey, tween });
    } else {
      gameBus.emit('PLAY_SOUND', 'flee');

      const count = 15;
      const list: SmokeParticle[] = [];
      for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = 1.5 + Math.random() * 3;
        list.push({
          id: `smoke-${Temporal.Now.instant().epochMilliseconds}-${i}-${Math.random()}`,
          x: 0,
          y: -10,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed - 1.5,
          scale: 1.0 + Math.random() * 1.5,
          opacity: 0.9,
        });
      }
      smokeParticles.value = list;

      const updateTicker = () => {
        let active = false;
        smokeParticles.value.forEach((p) => {
          p.x += p.vx;
          p.y += p.vy;
          p.opacity -= 0.03;
          p.scale += 0.02;
          if (p.opacity > 0) active = true;
        });

        if (active) {
          requestAnimationFrame(updateTicker);
        } else {
          smokeParticles.value = [];
        }
      };
      requestAnimationFrame(updateTicker);

      const tween = gsap.to(spriteRef.value, {
        x: 400,
        opacity: 0,
        scale: 0.7,
        duration: 0.45,
        ease: 'power2.in',
        onComplete: () => {
          if (spriteRef.value) {
            gsap.set(spriteRef.value, { clearProps: 'scale,transform,x' });
          }
        },
      });
      const animKey = `escape-${props.side}`;
      gameBus.emit('REGISTER_TWEEN', { key: animKey, tween });
    }
  };

  const handleEscapeEvent = (e: Event) => {
    const data = (e as CustomEvent).detail;
    if (data.side === props.side && (!data.pokemon || data.pokemon.uid === props.pokemon?.uid)) {
      const stateVal = toValue(battleStore.state);
      const isTrainerCombat = !!stateVal?.isTrainer || !!stateVal?.isGym;
      if (isTrainerCombat) return;
      runEscapeAnimation(data.type);
    }
  };

  onMounted(() => {
    gameBus.on('TRIGGER_COMBATANT_ESCAPE', handleEscapeEvent);
  });

  onUnmounted(() => {
    gameBus.off('TRIGGER_COMBATANT_ESCAPE', handleEscapeEvent);
  });

  return {
    naturalSize,
    cacheKey,
    isFloating,
    isPlayer,
    isEnemy,
    imageUrl,
    getAttackAnimClass,
    pokeballShadowUrl,
    localGroundY,
    fxScale,
    fxRadius,
    debugShowPokeRadius,
    isBallVisible,
    wasCaptured,
    internalBallId,
    memorizedBallCoords,
    getSpriteFeetOrigin,
    getBallTargetCoords,
    rawCoordsCache,
    handleImageError,
    handleBallError,
    handleLoad,
    smokeParticles,
    isAnimated,
    frames,
    frameSize,
    scaleFactor,
    displaySize,
    currentShadow,
    feetPoints,
    idleKey,
    variationKey,
    variationMeta
  };
}

import { computed, type Ref } from 'vue'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import { MAP_ROUTE_MAPPING } from '@/data/map-assets'
import { translateType } from '@/data/types'
import { useUIStore } from '@/stores/ui'
import { useGameStore } from '@/stores/game'
import { useMapStore } from '@/stores/map'
import { getRouteWeather, getWeatherMultiplier } from '@/logic/weather/weatherUtils'
import { getMechanicalWeather, WEATHER_UI_METADATA, WEATHER_VISUAL_METADATA, WEATHER_REGISTRY } from '@/logic/weather/weatherRegistry'
import { checkPlayerWinner, calculateSpawnGrid } from '@/logic/map/mapCardHelper'
import type { MapLocation } from '@/types/encounters'
import type { DominanceInfo } from '@/types/stores'

interface SpawnPool {
  generic: string[]
  specific: string[]
  rates: Record<string, number>
}

interface MapCardProps {
  map: MapLocation
  isLocked?: boolean
  isSafariLocked?: boolean
  cycle?: 'morning' | 'day' | 'dusk' | 'night'
  weather?: string
  badgeCount?: number
  dominance?: DominanceInfo | null
  isRocketExtorted?: boolean
  spawnPool?: SpawnPool
  forcedWeather?: string | null
}

export function useMapCardState(props: MapCardProps, currentCols: Ref<number>, isVisible: Ref<boolean>) {
  const uiStore = useUIStore()
  const gameStore = useGameStore()
  const mapStore = useMapStore()

  const computedWeather = computed(() => {
    return props.forcedWeather || mapStore.globalWeather || getRouteWeather(props.map.id, mapStore.currentSeason.id, mapStore.currentEpochHour, props.cycle || 'day')
  })

  const imgPath = computed(() => {
    const fileName = (MAP_ROUTE_MAPPING as Record<string, string>)[props.map.id] || 'default'
    return getAssetUrl(ASSET_TYPES.MAP, fileName, { 
      cycle: props.cycle,
      isLowPower: uiStore.isLowPowerActive
    })
  })

  const cycleEmoji = computed(() => {
    const emojis: Record<string, string> = { morning: '🌅', day: '🌞', dusk: '🌇', night: '🌙' }
    return emojis[props.cycle as string] || '🌞'
  })

  const cycleName = computed(() => {
    const names: Record<string, string> = { morning: 'Mañana', day: 'Día', afternoon: 'Tarde', dusk: 'Atardecer', night: 'Noche' }
    return names[props.cycle as string] || 'Normal'
  })

  const seasonName = computed(() => mapStore.currentSeason.label)
  const seasonEmoji = computed(() => mapStore.currentSeason.icon)

  const weatherEmoji = computed(() => {
    const visual = WEATHER_VISUAL_METADATA[computedWeather.value as string]
    if (visual) return visual.icon
    const mech = getMechanicalWeather(computedWeather.value as string)
    return WEATHER_UI_METADATA[mech]?.icon || ''
  })

  const weatherName = computed(() => {
    const visual = WEATHER_VISUAL_METADATA[computedWeather.value as string]
    if (visual) return visual.label
    const mech = getMechanicalWeather(computedWeather.value as string)
    return WEATHER_UI_METADATA[mech]?.label || 'Normal'
  })

  const weatherModifiersDescription = computed(() => {
    const entry = WEATHER_REGISTRY[computedWeather.value as string]
    const mods = entry?.modifiers
    if (!mods) return ''

    const formatList = (list?: string[]) => (list || []).map(translateType).join(', ')

    const lines = []
    if (mods.boost?.length) lines.push(`▲ ${formatList(mods.boost)}`)
    if (mods.debuff?.length) lines.push(`▼ ${formatList(mods.debuff)}`)
    if (mods.block?.length) lines.push(`🚫 ${formatList(mods.block)}`)

    return lines.length ? `\n\n${lines.join('\n')}` : ''
  })

  const cardSeed = computed(() => {
    const sum = props.map.name.split('').reduce((acc, char, i) => {
      return acc + (char.charCodeAt(0) * (i + 1))
    }, 0)
    return (sum % 100) / 100
  })

  const getPokemonSprite = (id: string) => getAssetUrl(ASSET_TYPES.POKEMON, id)

  const getFormattedTypes = (data: { type: string | string[]; type2?: string }): string => {
    const types: string[] = []
    if (Array.isArray(data.type)) {
      types.push(...data.type)
    } else {
      if (data.type) types.push(data.type)
      if (data.type2) types.push(data.type2)
    }
    return types.map(translateType).join('/').toUpperCase()
  }

  const processedGuardian = computed(() => {
    if (!props.dominance?.guardian) return null
    const id = props.dominance.guardian.id
    let isSeen = (gameStore.state.seenPokedex || []).includes(id) || (gameStore.state.pokedex || []).includes(id)
    let isCaught = (gameStore.state.pokedex || []).includes(id)

    if (uiStore.debugPokedexMode === 'caught') {
      isSeen = true; isCaught = true
    } else if (uiStore.debugPokedexMode === 'seen') {
      isSeen = true
    } else if (uiStore.debugPokedexMode === 'none') {
      isSeen = false; isCaught = false
    }

    const data = isSeen ? pokemonDataProvider.getPokemonData(id) : null
    const name = isSeen ? (data?.name || id.toUpperCase()) : 'Desconocido'
    const typeInfo = (isSeen && data) ? getFormattedTypes(data) : '???'
    const captured = props.dominance.guardian.captured || false

    return { 
      ...props.dominance.guardian, 
      isSeen, 
      isCaught, 
      name, 
      typeInfo, 
      captured,
      sprite: getPokemonSprite(id), 
      seed: id.split('').reduce((acc: number, char: string) => acc + char.charCodeAt(0), 0) / 100
    }
  })

  const isPlayerWinner = computed(() => checkPlayerWinner(props.dominance?.winner || null, gameStore.state.faction))

  const allSpawns = computed(() => {
    const pool = props.spawnPool || { generic: [], specific: [], rates: {} }
    return [...pool.generic, ...pool.specific]
  })

  const spawnGrid = computed(() => {
    const weather = computedWeather.value
    const cycle = props.cycle || 'day'
    const wildList = props.map.wild?.[cycle] || []

    const filteredSpawns = allSpawns.value.filter(id => {
      const isVisitor = !!(props.map.weather?.[weather]?.visitors as Record<string, unknown>)?.[id]
      const isExclusive = !!(props.map.weather?.[weather]?.exclusive as Record<string, unknown>)?.[id]
      const isFishingActive = !!props.map.fishing?.pool?.includes(id)
      const hasWildRestrictions = !!props.map.wild
      const isWildActive = !hasWildRestrictions || wildList.includes(id) || isVisitor || isExclusive || isFishingActive

      return isWildActive && getWeatherMultiplier(id, weather) > 0
    })

    const { rows, cols, totalSlots } = calculateSpawnGrid(filteredSpawns.length, currentCols.value)
    const grid = new Array(totalSlots).fill(null)
    filteredSpawns.forEach((id, index) => { grid[totalSlots - 1 - index] = id })
    return { slots: grid, rows, cols }
  })

  const processedGrid = computed(() => {
    const gridData = spawnGrid.value
    const slots = gridData.slots || []
    const seenPokedex = gameStore.state.seenPokedex || []
    const caughtPokedex = gameStore.state.pokedex || []

    return slots.map((id: string | null, index: number) => {
      if (!id) return { id: null, key: `empty-${index}` }
      let isSeen = seenPokedex.includes(id) || caughtPokedex.includes(id)
      let isCaught = caughtPokedex.includes(id)

      if (uiStore.debugPokedexMode === 'caught') {
        isSeen = true; isCaught = true
      } else if (uiStore.debugPokedexMode === 'seen') {
        isSeen = true
      }
      const pool = props.spawnPool || { generic: [], specific: [], rates: {} }
      const rate = pool.rates?.[id] || 10
      const data = isSeen ? pokemonDataProvider.getPokemonData(id) : null
      const name = isSeen ? (data?.name || id.toUpperCase()) : 'Desconocido'
      const typeInfo = (isSeen && data) ? `Tipo: ${getFormattedTypes(data)}` : ''

      const cycles = ['morning', 'day', 'dusk', 'night']
      const appearingCycles = cycles.filter(c => (props.map.wild?.[c] || []).includes(id))
      const isLimited = appearingCycles.length > 0 && appearingCycles.length < cycles.length

      const emojiMap: Record<string, string> = { morning: '🌅', day: '🌞', dusk: '🌇', night: '🌙' }

      const weather = computedWeather.value
      const isVisitor = !!(props.map.weather?.[weather]?.visitors as Record<string, unknown>)?.[id]
      const isExclusive = !!(props.map.weather?.[weather]?.exclusive as Record<string, unknown>)?.[id]

      let timeText = ''

      if (isLimited && isSeen) {
        const emojis = appearingCycles.map(c => emojiMap[c] || c).join('')
        timeText = `Aparición: ${emojis}`
      }

      const multiplier = getWeatherMultiplier(id, weather)
      const isBoosted = !isVisitor && !isExclusive && multiplier > 1.0
      const isDebuffed = !isVisitor && !isExclusive && multiplier < 1.0 && multiplier > 0
      const isSpecialWeatherSpawn = isVisitor || isExclusive

      if (isSpecialWeatherSpawn || isBoosted || isDebuffed) {
        if (isSeen) {
          const weatherTag = isVisitor ? 'Visitante' : (isExclusive ? 'Exclusivo' : (isBoosted ? 'Potenciado' : 'Debilitado'))
          const weatherLine = `${weatherEmoji.value} ${weatherTag} por el clima.`
          timeText = timeText ? `${timeText}\n${weatherLine}` : weatherLine
        } else {
          timeText = `${weatherEmoji.value} Anomalía Atmosférica detectada.`
        }
      }

      if (!timeText) {
        timeText = 'Habitante común.'
      }

      return {
        id, 
        key: `${id}-${index}`, 
        name, 
        sprite: getAssetUrl(ASSET_TYPES.POKEMON, id), 
        isSeen, 
        isCaught, 
        isRare: (rate > 0 && rate <= 2) || isExclusive, 
        isAtmospheric: isSpecialWeatherSpawn, 
        tooltipTitle: name, 
        tooltipDesc: typeInfo ? `${typeInfo}\n${timeText}` : timeText, 
        seed: (id.split('').reduce((acc: number, char: string) => acc + char.charCodeAt(0), 0) + index) / 100
      }
    })
  })

  const keepWarm = computed(() => {
    const isMobileDevice = uiStore.windowWidth < 768
    return !isMobileDevice && !uiStore.isLowPowerActive
  })

  const showBg = computed(() => {
    return isVisible.value || keepWarm.value
  })

  const lockReason = computed(() => {
    if (props.isSafariLocked) return 'REQUIERE TICKET SAFARI'
    if (gameStore.isSaveLocked && !uiStore.hasDismissedSessionLock) return 'SESIÓN BLOQUEADA'
    if (!props.isLocked) return ''
    const requiredBadges = props.map.badges || 0
    const badgeCount = props.badgeCount || 0
    if (badgeCount < requiredBadges) return `REQUIERE ${requiredBadges} MEDALLAS`
    return 'BLOQUEADO'
  })

  const isCardLocked = computed(() => {
    if (props.isLocked) return true
    if (gameStore.isSaveLocked && !uiStore.hasDismissedSessionLock) return true
    return false
  })

  const lockDescription = computed(() => {
    if (props.isSafariLocked) return 'Necesitas un Ticket Safari para entrar a esta zona.'
    if (gameStore.isSaveLocked && !uiStore.hasDismissedSessionLock) return 'Sesión activa en otra pestaña. Toma el control para habilitar el guardado.'
    if (!props.isLocked) return ''
    return `Consigue ${props.map.badges} medallas para acceder a esta zona.`
  })

  return {
    computedWeather,
    imgPath,
    cycleEmoji,
    cycleName,
    seasonName,
    seasonEmoji,
    weatherEmoji,
    weatherName,
    weatherModifiersDescription,
    cardSeed,
    processedGuardian,
    isPlayerWinner,
    allSpawns,
    spawnGrid,
    processedGrid,
    showBg,
    lockReason,
    isCardLocked,
    lockDescription
  }
}

import { ref, computed, onMounted, watch } from 'vue'
import { useGameStore } from '@/stores/game'
import { PLAYER_CLASSES } from '@/data/playerClasses'
import { useAuthStore } from '@/stores/auth'
import { useChatStore } from '@/stores/chat'
import { useSocialStore, type Friend } from '@/stores/social'
import { getXPNeededForClassLevel } from '@/logic/player/classMath'

