    trainersDefeated?: number
    wins?: number
    losses?: number
    maxDamage?: number
    totalBattles?: number
    tradeVolume?: number
    captureAttempts?: number
    captureSuccesses?: number
  }
  pvpStats?: {
    wins?: number
    losses?: number
    draws?: number
  }
  eloRating?: number
  warCoins?: number
  money?: number
  battleCoins?: number
  classData?: {
    criminality?: number
    reputation?: number
    longestStreak?: number
  }
  warMyPtsLocal?: Record<string, number>
}

export function useTrainerProfile(getUserId: () => string | null | undefined) {
  const gameStore = useGameStore()
  const authStore = useAuthStore()
  const chatStore = useChatStore()
  const socialStore = useSocialStore()

  const loading = ref(true)
  const profile = ref<ProfileRow | null>(null)
  const saveState = ref<SaveStateData | null>(null)
  const error = ref<string | null>(null)

  const userId = computed(getUserId)

  const isOwnProfile = computed(() => {
    return authStore.user?.id === userId.value
  })

  const fetchData = async () => {
    const id = userId.value
    if (!id) {
      error.value = 'ID de usuario no proporcionado'
      loading.value = false
      return
    }

    loading.value = true
    error.value = null
    profile.value = null
    saveState.value = null

    try {
      const db = gameStore.db
      if (!db) {
        error.value = 'Base de datos no disponible'
        return
      }

      // 1. Fetch profile
      const { data: prof, error: pErr } = await db
        .from('profiles')
        .select('*')
        .eq('id', id)
        .maybeSingle()

      if (pErr) throw pErr
      profile.value = (prof as ProfileRow) || null

      // 2. Fetch game save
      const { data: saveRow, error: sErr } = (await db
        .from('game_saves')
        .select('save_data')
        .eq('user_id', id)
        .maybeSingle()) as { data: { save_data: unknown } | null, error: Error | null }

      if (sErr) throw sErr

      if (!profile.value && !saveRow?.save_data) {
        error.value = 'Perfil de entrenador no encontrado'
        return
      }

      if (saveRow?.save_data) {
        let rawSave: unknown = saveRow.save_data
        if (typeof rawSave === 'string') {
          try {
            rawSave = JSON.parse(rawSave)
          } catch (_) {
            rawSave = null
          }
        }
        saveState.value = rawSave as SaveStateData
      }
    } catch (e: unknown) {
      const err = e as Error
      error.value = `Error: ${err.message || 'No se pudieron recuperar los datos'}`
    } finally {
      loading.value = false
    }
  }

  onMounted(() => {
    fetchData()
  })

  watch(userId, () => {
    fetchData()
  })

  const trainerName = computed(() => {
    const id = userId.value
    const cached = id ? chatStore.profileCosmetics[id] : null
    if (cached?.username) return cached.username
    const friend = id ? socialStore.friends.find((f: Friend) => f.id === id) : null
    if (friend?.username) return friend.username
    return saveState.value?.trainer || profile.value?.username || 'Entrenador'
  })

  const faction = computed(() => {
    return profile.value?.faction || saveState.value?.faction || null
  })

  const playerClass = computed(() => {
    const id = userId.value
    const cached = id ? chatStore.profileCosmetics[id] : null
    if (cached?.player_class !== undefined) return cached.player_class
    const friend = id ? socialStore.friends.find((f: Friend) => f.id === id) : null
    if (friend?.playerClass !== undefined) return friend.playerClass
    return profile.value?.player_class || saveState.value?.playerClass || null
  })

  const classDef = computed(() => {
    if (!playerClass.value) return null
    return (PLAYER_CLASSES as Record<string, { id: string; name: string; color: string; description: string }>)[playerClass.value] || null
  })

  const trainerLevel = computed(() => {
    const id = userId.value
    const cached = id ? chatStore.profileCosmetics[id] : null
    if (cached?.trainer_level !== undefined) return cached.trainer_level
    const friend = id ? socialStore.friends.find((f: Friend) => f.id === id) : null
    if (friend?.level !== undefined) return friend.level
    return profile.value?.trainer_level ?? saveState.value?.trainerLevel ?? 1
  })

  const avatarStyle = computed(() => {
    const id = userId.value
    const cached = id ? chatStore.profileCosmetics[id] : null
    if (cached?.avatar_style !== undefined) return cached.avatar_style
    const friend = id ? socialStore.friends.find((f: Friend) => f.id === id) : null
    if (friend?.avatar_style !== undefined) return friend.avatar_style
    return profile.value?.avatar_style ?? saveState.value?.avatar_style ?? ''
  })

  const nickStyle = computed(() => {
    const id = userId.value
    const cached = id ? chatStore.profileCosmetics[id] : null
    if (cached?.nick_style !== undefined) return cached.nick_style
    const friend = id ? socialStore.friends.find((f: Friend) => f.id === id) : null
    if (friend?.nick_style !== undefined) return friend.nick_style
    return profile.value?.nick_style ?? saveState.value?.nick_style ?? ''
  })

  const gender = computed(() => {
    const id = userId.value
    const cached = id ? chatStore.profileCosmetics[id] : null
    if (cached?.gender !== undefined) return cached.gender
    const friend = id ? socialStore.friends.find((f: Friend) => f.id === id) : null
    if (friend?.gender !== undefined) return friend.gender
    return profile.value?.gender ?? saveState.value?.gender ?? 'h'
  })

  const badgesCount = computed(() => {
    return saveState.value?.badges ?? saveState.value?.defeatedGyms?.length ?? 0
  })

  const pokedexCaught = computed(() => {
    return saveState.value?.pokedex?.length ?? 0
  })

  const pokedexSeen = computed(() => {
    return saveState.value?.seenPokedex?.length ?? 0
  })

  const trainersDefeated = computed(() => {
    return saveState.value?.stats?.trainersDefeated ?? 0
  })

  const wildWins = computed(() => {
    return saveState.value?.stats?.wins ?? 0
  })

  const pvpWins = computed(() => {
    return profile.value?.pvp_wins ?? saveState.value?.pvpStats?.wins ?? 0
  })

  const pvpLosses = computed(() => {
    return profile.value?.pvp_losses ?? saveState.value?.pvpStats?.losses ?? 0
  })

  const eloRating = computed(() => {
    return profile.value?.elo_rating ?? saveState.value?.eloRating ?? 1000
  })

  const warCoins = computed(() => {
    return saveState.value?.warCoins ?? 0
  })

  const criminality = computed(() => {
    return saveState.value?.classData?.criminality ?? 0
  })

  const reputation = computed(() => {
    return saveState.value?.classData?.reputation ?? 0
  })

  const captureStreak = computed(() => {
    return saveState.value?.classData?.longestStreak ?? 0
  })

  const totalWarPoints = computed<number>(() => {
    if (!saveState.value?.warMyPtsLocal) return 0
    const points = Object.values(saveState.value.warMyPtsLocal) as number[]
    return points.reduce((a: number, b: number) => Number(a) + Number(b), 0)
  })

  const isGymDefeated = (gymId: string) => {
    const list = saveState.value?.defeatedGyms || []
    return list.includes(gymId)
  }

  const factionLabel = computed(() => {
    const f = faction.value
    if (!f || f === 'null' || f === 'undefined' || f.trim() === '') return 'Sin Bando'
    if (f === 'union') return 'Equipo Unión'
    if (f === 'poder') return 'Equipo Poder'
    if (f === 'rocket') return 'Equipo Rocket'
    return f.toUpperCase()
  })

  const factionColor = computed(() => {
    const f = faction.value
    if (!f || f === 'null' || f === 'undefined' || f.trim() === '') return 'rgba(148, 163, 184, 0.5)'
    if (f === 'union') return 'rgba(59, 130, 246, 1)'
    if (f === 'poder') return 'rgba(239, 68, 68, 1)'
    if (f === 'rocket') return 'rgba(148, 163, 184, 1)'
    return 'rgba(148, 163, 184, 1)'
  })

  const playtimeHours = computed(() => {
    const secs = profile.value?.playtime ?? saveState.value?.playtime ?? 0
    return Math.floor(secs / 3600)
  })

  const createdAt = computed(() => {
    return profile.value?.created_at || (isOwnProfile.value ? Temporal.Now.instant().toString() : null)
  })

  const lastPlayedAt = computed(() => {
    return profile.value?.last_played_at || null
  })

  const rankedMaxElo = computed(() => {
    return profile.value?.ranked_max_elo ?? saveState.value?.rankedMaxElo ?? 1000
  })

  const classLevel = computed(() => {
    return profile.value?.class_level ?? saveState.value?.classLevel ?? 1
  })

  const classXP = computed(() => {
    return profile.value?.class_xp ?? saveState.value?.classXP ?? 0
  })

  const classXPNeeded = computed(() => {
    return getXPNeededForClassLevel(classLevel.value)
  })

  const boxCount = computed(() => {
    return profile.value?.box_count ?? saveState.value?.box?.length ?? 0
  })

  const pvpDraws = computed(() => {
    return profile.value?.pvp_draws ?? saveState.value?.pvpStats?.draws ?? 0
  })

  const longestStreak = computed(() => {
    return profile.value?.longest_streak ?? saveState.value?.classData?.longestStreak ?? 0
  })

  const shinyCount = computed(() => {
    if (profile.value?.shiny_count !== undefined && profile.value?.shiny_count !== null) {
      return profile.value.shiny_count
    }
    const teamShinies = ((saveState.value?.team || []) as { isShiny?: boolean }[]).filter(p => p.isShiny).length
    const boxShinies = ((saveState.value?.box || []) as { isShiny?: boolean }[]).filter(p => p.isShiny).length
    return teamShinies + boxShinies
  })

  const maxDamage = computed(() => {
    return profile.value?.max_damage ?? saveState.value?.stats?.maxDamage ?? 0
  })

  const totalBattles = computed(() => {
    return profile.value?.total_battles ?? saveState.value?.stats?.totalBattles ?? 0
  })

  const tradeVolume = computed(() => {
    return profile.value?.trade_volume ?? saveState.value?.stats?.tradeVolume ?? 0
  })

  const captureAttempts = computed(() => {
    return profile.value?.capture_attempts ?? saveState.value?.stats?.captureAttempts ?? 0
  })

  const captureSuccesses = computed(() => {
    return profile.value?.capture_successes ?? saveState.value?.stats?.captureSuccesses ?? 0
  })

  const captureEfficiency = computed(() => {
    const attempts = captureAttempts.value
    const successes = captureSuccesses.value
    if (attempts <= 0) return 0
    return Math.round((successes / attempts) * 100)
  })

  const money = computed(() => {
    return saveState.value?.money ?? 0
  })

  const battleCoinsCount = computed(() => {
    return saveState.value?.battleCoins ?? 0
  })

  return {
    loading,
    profile,
    saveState,
    error,
    isOwnProfile,
    trainerName,
    faction,
    playerClass,
    classDef,
    trainerLevel,
    avatarStyle,
    nickStyle,
    gender,
    badgesCount,
    pokedexCaught,
    pokedexSeen,
    trainersDefeated,
    wildWins,
    pvpWins,
    pvpLosses,
    eloRating,
    warCoins,
    criminality,
    reputation,
    captureStreak,
    totalWarPoints,
    isGymDefeated,
    factionLabel,
    factionColor,
    playtimeHours,
    createdAt,
    lastPlayedAt,
    rankedMaxElo,
    classLevel,
    classXP,
    classXPNeeded,
    boxCount,
    pvpDraws,
    longestStreak,
    shinyCount,
    maxDamage,
    totalBattles,
    tradeVolume,
    captureAttempts,
    captureSuccesses,
    captureEfficiency,
    money,
    battleCoinsCount,
    fetchData
  }
}

import { ref } from 'vue'
import type { Ref } from 'vue'
import { makePokemon } from '@/logic/pokemon/pokemonFactory'
import { FIRE_RED_MAPS } from '@/data/maps'
import type { Pokemon } from '@/types/pokemon'
import type { MapLocation } from '@/types/encounters'
import { useGameStore } from '@/stores/game'
import { useBattleStore } from '@/stores/battle'
import { useInventoryStore } from '@/stores/inventory'
import { useShopStore } from '@/stores/shop'
import { useMapStore } from '@/stores/map'


import { TRAINER_TYPES } from '@/data/trainerTypes'
import { getRandomQuoteForTrainer } from '@/data/trainerPhrases'
import { getSpritesForArchetype } from '@/logic/utils/npcSpriteRouter'

interface AdventureEventsConfig {
  isTraveling: Ref<boolean>
  isPaused: Ref<boolean>
  currentSegmentIndex: Ref<number>
  calculatedPath: Ref<string[]>
  currentMapId: Ref<string>
  originMap: Ref<string>
  activeHMs: Ref<Set<string>>
  travelLog: Ref<string[]>
  injectedItems: Ref<Set<string>>
  activeTravelModifiers: Ref<{ encounterRateMod: number; expMultiplier: number; moneyMultiplier: number; shinyChanceMod: number; typeFocus: string | null }>
  activeSweetScent: Ref<boolean>
  startMinigame: (type: 'archaeology' | 'fishing') => void
  triggerExtraLoot: (itemId: string, defaultQtyValue?: number) => void
  resumeTravelAfterEvent: () => void
  cancelTravel: () => void
  hasHealthyTeam: Ref<boolean>
  mapLocationsById: Ref<Record<string, MapLocation>>
  getSpawnPoolForMap: (loc: MapLocation) => { generic: string[]; specific: string[]; rates: Record<string, number> }
  getTravelTween: () => gsap.core.Tween | null
  getMarkerTimeline: () => gsap.core.Timeline | null

  gameStore: ReturnType<typeof useGameStore>
  battleStore: ReturnType<typeof useBattleStore>
  inventoryStore: ReturnType<typeof useInventoryStore>
  shopStore: ReturnType<typeof useShopStore>
  mapStore: ReturnType<typeof useMapStore>
}

export function useAdventureEvents(config: AdventureEventsConfig) {
  const activeEvent = ref<{
    type: 'combat' | 'combat_won' | 'obstacle_cut' | 'obstacle_strength' | 'obstacle_rock_smash' | 'fishing';
    title: string;
    desc: string;
    moRequired?: string;
    resolved: boolean;
    wildPokemon?: Pokemon;
    isTrainer?: boolean;
    trainerName?: string;
    trainerSprite?: string;
    enemyTeam?: Pokemon[];
    quote?: string;
  } | null>(null)

  const pendingEscapedCombatEvent = ref(false)

  async function generateTrainerEncounter(mapData: MapLocation) {
    const keys = Object.keys(TRAINER_TYPES) as Array<keyof typeof TRAINER_TYPES>
    const typeKey = keys[Math.floor(Math.random() * keys.length)] || 'caza_bichos'
    const t = TRAINER_TYPES[typeKey]

    const baseLv = mapData.lv?.[0] || 5
    const trainerLv = baseLv + 2
    const teamSize = Math.floor(Math.random() * 3) + 1

    // Pick a random sprite from the full archetype catalog (not just the hardcoded fallback)
    const archetypeSprites = getSpritesForArchetype(t.archetype)
    const trainerSprite = archetypeSprites[Math.floor(Math.random() * archetypeSprites.length)] || t.sprite

    const { buildTrainerTeam } = await import('@/logic/battle/trainerFactory')
    const enemyTeam = await buildTrainerTeam(t.pool as unknown as string[], trainerLv, teamSize)
    const quote = getRandomQuoteForTrainer(typeKey)
    return {
      trainerName: t.name,
      trainerSprite,
      enemyTeam,
      quote
    }
  }

  const triggerRandomEvent = async (targetMapId?: string) => {
    const travelTween = config.getTravelTween()
    const markerTimeline = config.getMarkerTimeline()

    if (travelTween) travelTween.pause()
    if (markerTimeline) markerTimeline.pause()
    config.isPaused.value = true

    const nextSegmentMapId = config.isTraveling.value && config.calculatedPath.value[config.currentSegmentIndex.value + 1]
      ? config.calculatedPath.value[config.currentSegmentIndex.value + 1]
      : config.currentMapId.value

    const mapId = (targetMapId || nextSegmentMapId || 'route1') as string
    const mapData = FIRE_RED_MAPS.find(m => m.id === mapId) as MapLocation | undefined

    if (!mapData) return

    const isCaveOrMountain = mapData.isMountain || mapId.includes('cave') || mapId.includes('tunnel') || mapId.includes('moon') || mapId.includes('road')
    const isWaterMap = mapId.includes('seafoam') || ['route19', 'route20', 'route21'].includes(mapId)
    const hasFishing = !!mapData.fishing

    const eventTypes: Array<'combat' | 'obstacle_cut' | 'obstacle_strength' | 'obstacle_rock_smash' | 'fishing'> = ['combat']

    if (isWaterMap) {
      eventTypes.push('fishing')
    } else if (isCaveOrMountain) {
      eventTypes.push('obstacle_rock_smash')
      eventTypes.push('obstacle_strength')
    } else {
      eventTypes.push('obstacle_cut')
      if (hasFishing) {
        eventTypes.push('fishing')
      }
    }

    let chosenType: 'combat' | 'obstacle_cut' | 'obstacle_strength' | 'obstacle_rock_smash' | 'fishing' = 'combat'
    if (Math.random() > 0.70 && eventTypes.length > 1) {
      const nonCombatTypes = eventTypes.filter(t => t !== 'combat')
      chosenType = nonCombatTypes[Math.floor(Math.random() * nonCombatTypes.length)]!
    }

    const destinationName = mapData.name || mapId

    const eventTemplates = {
      combat: {
        title: targetMapId ? `¡Emboscada al entrar a ${destinationName}!` : '¡Encuentro de Combate!',
        desc: isWaterMap
          ? 'Un entrenador en bañador surge del oleaje y te desafía a un combate acuático.'
          : (isCaveOrMountain ? 'Un montañero te desafía en la penumbra del sendero.' : 'Un entrenador rival sale de la hierba alta y te desafía.'),
        moRequired: undefined
      },
      obstacle_cut: {
        title: 'Obstáculo: Arbusto Espeso',
        desc: 'Un arbusto espinoso y denso corta el paso en la ruta.',
        moRequired: 'cut'
      },
      obstacle_strength: {
        title: 'Obstáculo: Gran Roca',
        desc: 'Una inmensa roca redonda bloquea el túnel, impidiendo continuar.',
        moRequired: 'strength'
      },
      obstacle_rock_smash: {
        title: 'Obstáculo: Roca Agrietada',
        desc: 'Una formación de rocas agrietadas bloquea el sendero empinado.',
        moRequired: 'rock_smash'
      },
      fishing: {
        title: 'Zona de Pesca Abundante',
        desc: isWaterMap
          ? 'El oleaje está tranquilo. Te detienes a lanzar la caña de pescar.'
          : 'Te detienes junto a un estanque en la ruta a probar suerte con la caña.',
        moRequired: undefined
      }
    }

    let combatDesc = eventTemplates.combat.desc
    let wildPoke: Pokemon | null = null
    let isTrainer = false
    let trainerName = ''
    let trainerSprite = ''
    let enemyTeam: Pokemon[] = []
    let trainerData: { trainerName: string; trainerSprite: string; enemyTeam: Pokemon[]; quote: string } | null = null

    if (chosenType === 'combat') {
      if (Math.random() < 0.35) {
        isTrainer = true
        trainerData = await generateTrainerEncounter(mapData)
        trainerName = trainerData.trainerName
        trainerSprite = trainerData.trainerSprite
        enemyTeam = trainerData.enemyTeam
        combatDesc = `💥 ¡El entrenador ${trainerName} te desafía a un combate en el camino!`
      } else {
        const poolData = config.getSpawnPoolForMap(mapData)
        const spawns = [...poolData.generic, ...poolData.specific]
        if (spawns.length > 0) {
          let chosenSpawn = spawns[Math.floor(Math.random() * spawns.length)]!
          if (config.activeTravelModifiers.value.typeFocus) {
            const typeMatch = spawns.find(s => s.toLowerCase().includes(config.activeTravelModifiers.value.typeFocus!))
            if (typeMatch) chosenSpawn = typeMatch
          }
          const pokemonName = chosenSpawn.charAt(0).toUpperCase() + chosenSpawn.slice(1)
          const minLv = mapData.lv?.[0] || 5
          const maxLv = mapData.lv?.[1] || 10
          const level = Math.floor(Math.random() * (maxLv - minLv + 1)) + minLv

          const generated = makePokemon(chosenSpawn, level, { shinyMultiplier: config.activeTravelModifiers.value.shinyChanceMod })
          if (generated) {
            wildPoke = generated as Pokemon
            if (wildPoke.isShiny) {
              combatDesc = `✨ ¡Un ${pokemonName} VARIOPINTO (Shiny) salvaje apareció brillando en el sendero! (Tasa Shiny: x${config.activeTravelModifiers.value.shinyChanceMod.toFixed(1)})`
            } else {
              combatDesc = `¡Un ${pokemonName} salvaje apareció en el sendero y te desafía a un combate!`
            }
          }
        }
      }
    }

    const template = eventTemplates[chosenType]
    activeEvent.value = {
      type: chosenType,
      title: template.title,
      desc: chosenType === 'combat' ? combatDesc : template.desc,
      moRequired: template.moRequired,
      resolved: false,
      wildPokemon: wildPoke || undefined,
      isTrainer,
      trainerName: isTrainer ? trainerName : undefined,
      trainerSprite: isTrainer ? trainerSprite : undefined,
      enemyTeam: isTrainer ? enemyTeam : undefined,
      quote: isTrainer && trainerData ? trainerData.quote : undefined
    }

    config.travelLog.value.push(`🛑 Evento: ${template.title}`)
  }

  const resolveEvent = () => {
    if (!activeEvent.value) return
    const evt = activeEvent.value
    const isManualExploration = !config.isTraveling.value

    if (evt.moRequired && !config.activeHMs.value.has(evt.moRequired)) {
      config.travelLog.value.push(`🚶 Ignorando obstáculo: No tienes la MO ${evt.moRequired.toUpperCase()}. Rodeas el obstáculo y continúas.`)
      if (isManualExploration) { activeEvent.value = null; return }
      config.resumeTravelAfterEvent()
      return
    }

    if (evt.type === 'obstacle_rock_smash') {
      config.startMinigame('archaeology')
      return
    }

    if (evt.type === 'fishing') {
      config.startMinigame('fishing')
      return
    }

    if (evt.type === 'obstacle_cut') {
      config.inventoryStore.addItem('berry_bronze', 2)
      config.injectedItems.value.add('berry_bronze')
      config.inventoryStore.addItem('berry_silver', 1)
      config.injectedItems.value.add('berry_silver')
      config.travelLog.value.push('✂️ ¡Cortas el arbusto con MO Corte y recolectas bayas del árbol!')
      config.travelLog.value.push('🫐 +2 Baya de Bronce, +1 Baya de Plata obtenidas en tu mochila de pruebas.')

      config.triggerExtraLoot('berry_bronze', 1)

      if (isManualExploration) { activeEvent.value = null; return }
      config.resumeTravelAfterEvent()
      return
    }

    if (evt.type === 'obstacle_strength') {
      config.inventoryStore.addItem('nugget', 1)
      config.injectedItems.value.add('nugget')
      config.travelLog.value.push('💪 ¡Empujas la roca con MO Fuerza y descubres un cofre oculto!')
      config.travelLog.value.push('📦 +1 Pepita obtenida en tu mochila de pruebas.')

      config.triggerExtraLoot('nugget', 1)

      if (isManualExploration) { activeEvent.value = null; return }
      config.resumeTravelAfterEvent()
      return
    }

    if (evt.type === 'combat') {
      const healthy = (config.gameStore.state.team || []).some((p: Pokemon) => p && p.hp > 0)
      if (!healthy) {
        config.travelLog.value.push('⚠️ No tienes Pokémon conscientes en tu equipo de pruebas para combatir.')
        return
      }

      const travelTween = config.getTravelTween()
      const markerTimeline = config.getMarkerTimeline()
      if (travelTween) travelTween.pause()
      if (markerTimeline) markerTimeline.pause()
      config.isPaused.value = true

      if (evt.isTrainer && evt.enemyTeam && evt.enemyTeam.length > 0 && evt.enemyTeam[0]) {
        config.travelLog.value.push(`💥 Iniciando combate contra el entrenador ${evt.trainerName}...`)
        config.battleStore.startBattle(evt.enemyTeam[0], {
          locationId: config.currentMapId.value,
          wasSearching: !config.isTraveling.value,
          isTrainer: true,
          enemyTeam: evt.enemyTeam,
          trainerName: evt.trainerName,
          trainerSprite: evt.trainerSprite,
          trainerQuote: evt.quote,
          persistenceMode: config.isTraveling.value ? 'SINGLE' : undefined,
          cannotEscape: true
        })
      } else {
        let wild = evt.wildPokemon
        if (!wild) {
          wild = makePokemon('rattata', 5) as Pokemon
        }

        config.travelLog.value.push(`💥 Iniciando combate de pruebas contra ${wild?.name} (Nivel ${wild?.level})...`)
        config.battleStore.startBattle(wild!, { 
          locationId: config.currentMapId.value, 
          wasSearching: !config.isTraveling.value,
          persistenceMode: config.isTraveling.value ? 'SINGLE' : undefined,
          cannotEscape: config.isTraveling.value
        })
      }
      return
    }

    if (isManualExploration) { 
      activeEvent.value = null
      return 
    }
    config.resumeTravelAfterEvent()
  }

  const triggerExplore = async () => {
    if (config.isTraveling.value) return

    const mapData = config.mapLocationsById.value[config.originMap.value]
    if (!mapData) return

    if (!config.hasHealthyTeam.value) {
      config.travelLog.value.push('⚠️ No puedes explorar: Todos tus Pokémon están debilitados.')
      return
    }

    if (Math.random() < 0.35) {
      const trainerData = await generateTrainerEncounter(mapData)
      activeEvent.value = {
        type: 'combat',
        title: '¡Desafío de Entrenador!',
        desc: `El entrenador ${trainerData.trainerName} te ha visto explorar y te desafía.`,
        resolved: false,
        isTrainer: true,
        trainerName: trainerData.trainerName,
        trainerSprite: trainerData.trainerSprite,
        enemyTeam: trainerData.enemyTeam
      }
      config.travelLog.value.push(`🌿 ¡Comienza un combate contra el entrenador ${trainerData.trainerName}!`)
      return
    }

    const poolData = config.getSpawnPoolForMap(mapData)
    const spawns = [...poolData.generic, ...poolData.specific]

    if (spawns.length === 0) {
      config.travelLog.value.push(`🔍 Buscaste en ${mapData.name}, pero no parece haber Pokémon salvajes aquí.`)
      return
    }

    const randomSpawn = spawns[Math.floor(Math.random() * spawns.length)]!
    const name = randomSpawn.charAt(0).toUpperCase() + randomSpawn.slice(1)

    const minLv = mapData.lv?.[0] || 5
    const maxLv = mapData.lv?.[1] || 10
    const level = Math.floor(Math.random() * (maxLv - minLv + 1)) + minLv

    const wildPoke = makePokemon(randomSpawn, level) as Pokemon

    activeEvent.value = {
      type: 'combat',
      title: '¡Un Pokémon salvaje apareció!',
      desc: `Has encontrado un ${name} salvaje mientras explorabas la zona.`,
      resolved: false,
      wildPokemon: wildPoke
    }
    config.travelLog.value.push(`🌿 ¡Comienza un combate contra ${name} salvaje!`)
  }

  const resolveCombatRouteEvent = (message: string) => {
    if (activeEvent.value?.type !== 'combat') return

    pendingEscapedCombatEvent.value = false
    const team = config.gameStore.state.team || []
    const healthy = team.some((p: Pokemon) => p && p.hp > 0)
    if (!healthy) {
      config.travelLog.value.push('💀 ¡Todo tu equipo ha sido debilitado! Viaje cancelado.')
      config.cancelTravel()
      const originNode = config.originMap.value
      config.mapStore.currentMap = originNode
      config.shopStore.healAllPokemon(0)
      config.travelLog.value.push(`🏥 Regresaste de inmediato a ${FIRE_RED_MAPS.find(m => m.id === originNode)?.name || originNode}. Tu equipo ha sido curado.`)
      activeEvent.value = null
      return
    }

    config.travelLog.value.push(message)
    if (config.isTraveling.value) {
      config.resumeTravelAfterEvent()
    } else {
      activeEvent.value = null
    }
  }

  return {
    activeEvent,
    pendingEscapedCombatEvent,
    triggerRandomEvent,
    resolveEvent,
    triggerExplore,
    resolveCombatRouteEvent
  }
}

import { computed } from 'vue'
import type { Ref } from 'vue'
import { KANTO_NODE_POSITIONS, KANTO_CONNECTIONS } from '../../../test aventura/kantoGraph.ts'
import type { GraphEdge } from '../../../test aventura/kantoGraph.ts'
import type { MapLocation } from '@/types/encounters'


const POKEMON_CENTER_NODES = new Set([
  'route2',          // Ciudad Verde / Plateada
  'route4',          // Centro Mt. Moon
  'route5',          // Ciudad Celeste
  'route6',          // Ciudad Carmín
  'route7',          // Ciudad Azulona
  'pokemon_tower',   // Pueblo Lavanda
  'safari_zone',     // Ciudad Fucsia
  'mansion',         // Isla Canela
  'route10',         // Centro Túnel Roca
  'route23'          // Meseta Añil
])

const CANVAS_W = 6400
const CANVAS_H = 4400
const CARD_W = 320
const CARD_H = 220

export function useAdventureLayout(options: {
  cameraScale: Ref<number>
  calculatedPath: Ref<string[]>
  originMap: Ref<string>
  activeHMs: Ref<Set<string>>
  mapLocationsById: Ref<Record<string, MapLocation>>
}) {
  const nodePositions = computed(() => {
    const result: Record<string, { x: number; y: number; label: string }> = {}
    for (const [id, pos] of Object.entries(KANTO_NODE_POSITIONS)) {
      result[id] = {
        x: (pos.x / 100) * (CANVAS_W - CARD_W),
        y: (pos.y / 100) * (CANVAS_H - CARD_H),
        label: pos.label,
      }
    }
    return result
  })

  const validNodeIds = computed(() => {
    return Object.keys(KANTO_NODE_POSITIONS).filter(id => options.mapLocationsById.value[id])
  })

  const worldOverlayScale = computed(() => 1 / Math.max(options.cameraScale.value, 0.25))

  const pokemonCenterOverlays = computed(() => {
    return validNodeIds.value.flatMap(nodeId => {
      if (!POKEMON_CENTER_NODES.has(nodeId)) return []
      const position = nodePositions.value[nodeId]
      if (!position) return []
      return [{
        id: nodeId,
        label: options.mapLocationsById.value[nodeId]?.name || KANTO_NODE_POSITIONS[nodeId]?.label || nodeId,
        x: position.x + CARD_W - 20,
        y: position.y + 18
      }]
    })
  })

  const adjacentConnections = computed(() => {
    const origin = options.originMap.value
    const originPos = nodePositions.value[origin]
    const connections = KANTO_CONNECTIONS[origin] || []
    const result = {
      top: [] as { target: string, mo?: string, label: string }[],
      bottom: [] as { target: string, mo?: string, label: string }[],
      left: [] as { target: string, mo?: string, label: string }[],
      right: [] as { target: string, mo?: string, label: string }[],
    }

    if (!originPos) return result

    for (const conn of connections) {
      const targetPos = nodePositions.value[conn.target]
      if (!targetPos) continue
      const dx = targetPos.x - originPos.x
      const dy = targetPos.y - originPos.y
      const nodeLabel = targetPos.label
      if (Math.abs(dx) > Math.abs(dy)) {
        if (dx > 0) result.right.push({ ...conn, label: nodeLabel })
        else result.left.push({ ...conn, label: nodeLabel })
      } else {
        if (dy > 0) result.bottom.push({ ...conn, label: nodeLabel })
        else result.top.push({ ...conn, label: nodeLabel })
      }
    }
    return result
  })

  const pathSet = computed(() => new Set(options.calculatedPath.value))
  const pathEdgeSet = computed(() => {
    const set = new Set<string>()
    const path = options.calculatedPath.value
    for (let i = 0; i < path.length - 1; i++) {
      const key = [path[i]!, path[i + 1]!].sort().join('|')
      set.add(key)
    }
    return set
  })

  const getEdgeKey = (from: string, to: string) => [from, to].sort().join('|')
  const isEdgeOnPath = (from: string, to: string) => pathEdgeSet.value.has(getEdgeKey(from, to))

  const isEdgeTraversable = (edge: GraphEdge) => {
    if (!edge.mo) return true
    const requirements = edge.mo.split(',')
    return requirements.every(req => options.activeHMs.value.has(req))
  }

  return {
    nodePositions,
    validNodeIds,
    worldOverlayScale,
    pokemonCenterOverlays,
    adjacentConnections,
    pathSet,
    pathEdgeSet,
    isEdgeOnPath,
    isEdgeTraversable
  }
}

import { ref, computed, onUnmounted, watch, nextTick } from 'vue'
import { gsap } from 'gsap'
import { getGraphEdges } from '../../../test aventura/kantoGraph.ts'
import type { GraphEdge } from '../../../test aventura/kantoGraph.ts'
import { FIRE_RED_MAPS } from '@/data/maps'
import { useMapStore } from '@/stores/map'
import { useShopStore } from '@/stores/shop'
import { useInventoryStore } from '@/stores/inventory'
import { useGameStore } from '@/stores/game'
import { useBattleStore } from '@/stores/battle'
import { getEncounterPool } from '@/logic/encounters/encounters'
import { getRouteWeather } from '@/logic/weather/weatherUtils'
import { useAdventureCamera } from '@/composables/adventure/useAdventureCamera'
import type { MapLocation } from '@/types/encounters'
import { useAdventureMinigames } from './useAdventureMinigames'
import { useAdventureEvents } from './useAdventureEvents'
import { useAdventureRouting } from './useAdventureRouting'
import { useAdventureLayout } from './useAdventureLayout'

const POKEMON_CENTER_NODES = new Set([
  'route2',          // Ciudad Verde / Plateada
  'route4',          // Centro Mt. Moon
  'route5',          // Ciudad Celeste
  'route6',          // Ciudad Carmín
  'route7',          // Ciudad Azulona
  'pokemon_tower',   // Pueblo Lavanda
  'safari_zone',     // Ciudad Fucsia
  'mansion',         // Isla Canela
  'route10',         // Centro Túnel Roca
  'route23'          // Meseta Añil
])

const CANVAS_W = 6400
const CANVAS_H = 4400
const CARD_W = 320
const CARD_H = 220

const ADVENTURE_PASSIVES = {
  flame_body: { id: 'speed_bonus', label: 'Cuerpo Llama', desc: '+15% Vel. Viaje', value: 0.15 },
  magma_armor: { id: 'speed_bonus', label: 'Escudo Magma', desc: '+15% Vel. Viaje', value: 0.15 },
  pickup: { id: 'loot_bonus', label: 'Recogida', desc: '+20% Prob. Botín', value: 0.20 },
  synchronize: { id: 'nature_sync', label: 'Sincronía', desc: 'Sincronizar Naturaleza', value: 0.50 }
}

export function useAdventureSimulation() {
  const mapStore = useMapStore()
  const shopStore = useShopStore()
  const inventoryStore = useInventoryStore()
  const gameStore = useGameStore()
  const battleStore = useBattleStore()

  if (typeof gameStore.enterSandboxMode === 'function') {
    gameStore.enterSandboxMode()
  }

  const travelLog = ref<string[]>([])
  const injectedItems = ref<Set<string>>(new Set())
  const isPaused = ref(false)
  const travelProgress = ref(0)
  const currentSegmentIndex = ref(0)
  const lastStepPct = ref(0)
  const safeStepsRemaining = ref(0)
  const isArrivalEventPending = ref(false)
  const blockedConnections = ref<Set<string>>(new Set())

  let travelTween: gsap.core.Tween | null = null
  let markerTimeline: gsap.core.Timeline | null = null
  let glowPulseTween: gsap.core.Tween | null = null

  const graphEdges = ref<GraphEdge[]>(getGraphEdges())
  const markerX = ref(0)
  const markerY = ref(0)
  const showMarker = ref(false)
  const glowMarkerRef = ref<HTMLElement | null>(null)
  const viewportRef = ref<HTMLElement | null>(null)
  const canvasRef = ref<HTMLElement | null>(null)

  const {
    cameraX,
    cameraY,
    cameraScale,
    isDragging,
    centerOnPoint,
    jumpToPoint,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    zoomIn,
    zoomOut
  } = useAdventureCamera({
    viewportRef,
    canvasRef,
    canvasWidth: CANVAS_W,
    canvasHeight: CANVAS_H,
  })

  const hasHealthyTeam = computed(() => {
    const team = gameStore.state.team || []
    return team.some(p => p && p.hp > 0)
  })

  // Routing composable setup
  const {
    originMap,
    destinationMap,
    activeHMs,
    showPreTravelModal,
    selectedTravelItems,
    pendingManualDestination,
    activeSweetScent,
    isTraveling,
    calculatedPath,
    hasBicycle,
    isBikeActive,
    toggleTravelItem,
    activeTravelModifiers,
    availableActiveMoves,
    useActiveRouteMove,
    startManualTravel,
    cancelPreTravel,
    confirmPreTravel,
    filteredBuffItems,
    toggleHM,
    calculateRoute
  } = useAdventureRouting({
    gameStore,
    mapStore,
    shopStore,
    inventoryStore,
    travelLog,
    hasHealthyTeam,
    startTravel: () => startTravel(),
    cancelTravel: () => cancelTravel()
  })

  // Minigame State
  const {
    showArchaeology,
    showFishing,
    minigamePokemon,
    startMinigame,
    handleMinigameWin,
    handleMinigameFail
  } = useAdventureMinigames({
    inventoryStore,
    injectedItems,
    travelLog,
    triggerExtraLoot,
    resumeTravelAfterEvent
  })

  const mapLocationsById = computed(() => {
    const map: Record<string, MapLocation> = {}
    for (const loc of FIRE_RED_MAPS) {
      map[loc.id] = loc as MapLocation
    }
    return map
  })

  // Layout calculations extraction
  const {
    nodePositions,
    validNodeIds,
    worldOverlayScale,
    pokemonCenterOverlays,
    adjacentConnections,
    pathSet,
    pathEdgeSet,
    isEdgeOnPath,
    isEdgeTraversable
  } = useAdventureLayout({
    cameraScale,
    calculatedPath,
    originMap,
    activeHMs,
    mapLocationsById
  })

  function getSpawnPoolForMap(loc: MapLocation) {
    if (!loc.wild) return { generic: [] as string[], specific: [] as string[], rates: {} as Record<string, number> }

    const activeWeather = getRouteWeather(loc.id, mapStore.currentSeason.id, mapStore.currentEpochHour, mapStore.currentCycle)
    const { pool, rates } = getEncounterPool(loc, mapStore.currentCycle || 'day', activeWeather || 'clear', [])

    const baseWild = loc.wild?.day || []
    const generic: string[] = []
    const specific: string[] = []
    const ratesMap: Record<string, number> = {}

    pool.forEach((id: string, index: number) => {
      ratesMap[id] = rates[index] || 10
      if (baseWild.includes(id)) generic.push(id)
      else specific.push(id)
    })

    if (loc.fishing) {
      loc.fishing.pool.forEach((id: string, index: number) => {
        if (!generic.includes(id) && !specific.includes(id)) {
          generic.push(id)
          ratesMap[id] = loc.fishing!.rates[index] || 10
        }
      })
    }

    return { generic, specific, rates: ratesMap }
  }

  const currentMapId = computed(() => {
    if (calculatedPath.value.length === 0) return originMap.value
    const idx = Math.min(currentSegmentIndex.value, calculatedPath.value.length - 1)
    return calculatedPath.value[idx] || originMap.value
  })

  // Events system extraction
  const {
    activeEvent,
    triggerRandomEvent,
    resolveEvent,
    triggerExplore,
    resolveCombatRouteEvent
  } = useAdventureEvents({
    isTraveling,
    isPaused,
    currentSegmentIndex,
    calculatedPath,
    currentMapId,
    originMap,
    activeHMs,
    travelLog,
    injectedItems,
    activeTravelModifiers,
    activeSweetScent,
    startMinigame,
    triggerExtraLoot,
    resumeTravelAfterEvent,
    cancelTravel,
    hasHealthyTeam,
    mapLocationsById,
    getSpawnPoolForMap,
    getTravelTween: () => travelTween,
    getMarkerTimeline: () => markerTimeline,
    gameStore,
    battleStore,
    inventoryStore,
    shopStore,
    mapStore
  })

  // Watch for battle status completion to resolve adventure event
  watch(() => battleStore.isBattleActive, (isActive, wasActive) => {
    if (!isActive && wasActive && activeEvent.value?.type === 'combat') {
      const active = battleStore.state
      const fled = active?.fled || active?.playerFled || false
      const outcomeMessage = fled ? '💨 Huiste del combate.' : '⚔️ Combate finalizado.'
      resolveCombatRouteEvent(outcomeMessage)
    }
  })

  const activeTeamPassives = computed(() => {
    const team = gameStore.state.team || []
    let speedBonus = 0
    let lootBonus = 0
    let natureSync = false
    const activePassivesList: { label: string; desc: string }[] = []

    team.forEach(pkmn => {
      if (pkmn && pkmn.hp > 0 && pkmn.ability) {
        const abilityKey = pkmn.ability.toLowerCase().replace(/[\s-]/g, '_')
        const passive = ADVENTURE_PASSIVES[abilityKey as keyof typeof ADVENTURE_PASSIVES]
        if (passive) {
          if (passive.id === 'speed_bonus') {
            speedBonus = Math.max(speedBonus, passive.value)
          } else if (passive.id === 'loot_bonus') {
            lootBonus = Math.max(lootBonus, passive.value)
          } else if (passive.id === 'nature_sync') {
            natureSync = true
          }
          if (!activePassivesList.some(p => p.label === passive.label)) {
            activePassivesList.push({ label: passive.label, desc: passive.desc })
          }
        }
      }
    })

    return {
      speedBonus,
      lootBonus,
      natureSync,
      list: activePassivesList
    }
  })

  function triggerExtraLoot(itemId: string, defaultQty: number = 1) {
    const lootBonus = activeTeamPassives.value.lootBonus
    if (lootBonus > 0 && Math.random() < lootBonus) {
      inventoryStore.addItem(itemId, defaultQty)
      injectedItems.value.add(itemId)
      travelLog.value.push(`🌟 ¡Pasiva Recogida activa! Tu Pokémon ha encontrado un objeto extra: +${defaultQty}x ${itemId} obtenido en tu mochila real.`)
    }
  }

  function getWeatherForMap(mapId: string): string {
    return getRouteWeather(mapId, mapStore.currentSeason.id, mapStore.currentEpochHour, mapStore.currentCycle)
  }

  watch(showMarker, async (visible: boolean) => {
    if (glowPulseTween) {
      glowPulseTween.kill()
      glowPulseTween = null
    }
    if (visible) {
      await nextTick()
      if (glowMarkerRef.value) {
        gsap.set(glowMarkerRef.value, { scale: 1, opacity: 0.8 })
        glowPulseTween = gsap.to(glowMarkerRef.value, {
          scale: 2,
          opacity: 0.1,
          duration: 0.8,
          ease: 'sine.inOut',
          yoyo: true,
          repeat: -1
        })
      }
    }
  })

  const startTravel = () => {
    calculateRoute()
    if (calculatedPath.value.length === 0) return

    activeSweetScent.value = false
    isTraveling.value = true
    isPaused.value = false
    travelProgress.value = 0
    currentSegmentIndex.value = 0
    lastStepPct.value = 0
    safeStepsRemaining.value = 0
    isArrivalEventPending.value = false
    blockedConnections.value = new Set()
    activeEvent.value = null
    showArchaeology.value = false
    showFishing.value = false
    minigamePokemon.value = null
    showMarker.value = true

    const originPos = nodePositions.value[originMap.value]
    if (originPos) {
      markerX.value = originPos.x + CARD_W / 2
      markerY.value = originPos.y + CARD_H / 2
      centerOnPoint(markerX.value, markerY.value, 0.5)
    }

    if (POKEMON_CENTER_NODES.has(originMap.value)) {
      shopStore.healAllPokemon(0)
      travelLog.value.push(`🏥 Centro Pokémon inicial: Tu equipo de pruebas ha sido completamente curado.`)
    }

    const baseSpeedMultiplier = 1 + activeTeamPassives.value.speedBonus
    const baseTimePerMap = Math.max(1, (isBikeActive.value ? 2 : 4) / baseSpeedMultiplier)
    const totalDuration = (calculatedPath.value.length - 1 || 1) * baseTimePerMap
    const stateObj = { val: 0 }

    travelLog.value.push(`Iniciando viaje de ${calculatedPath.value.length} tramos...`)

    if (markerTimeline) {
      markerTimeline.kill()
    }
    markerTimeline = gsap.timeline()
    const path = calculatedPath.value
    const segTime = baseTimePerMap
    const markerState = { mx: markerX.value, my: markerY.value }

    for (let i = 1; i < path.length; i++) {
      const targetPos = nodePositions.value[path[i]!]
      if (targetPos) {
        const targetCX = targetPos.x + CARD_W / 2
        const targetCY = targetPos.y + CARD_H / 2
        markerTimeline.to(
          markerState,
          {
            mx: targetCX,
            my: targetCY,
            duration: segTime,
            ease: 'power1.inOut',
            onUpdate() {
              markerX.value = markerState.mx
              markerY.value = markerState.my
              if (!isDragging.value) {
                jumpToPoint(markerState.mx, markerState.my)
              }
            },
          }
        )
      }
    }

    travelTween = gsap.to(stateObj, {
      val: 100,
      duration: totalDuration,
      ease: 'none',
      onUpdate: () => {
        const currentPct = Math.round(stateObj.val)
        travelProgress.value = currentPct
        const segmentProgress = 100 / (calculatedPath.value.length - 1 || 1)
        const nextTransitionVal = (currentSegmentIndex.value + 1) * segmentProgress

        if (stateObj.val >= nextTransitionVal && !isArrivalEventPending.value) {
          isArrivalEventPending.value = true
          const nextNodeId = calculatedPath.value[currentSegmentIndex.value + 1]!
          triggerRandomEvent(nextNodeId)
          return
        }

        if (isArrivalEventPending.value) return

        const segmentVal = stateObj.val - (currentSegmentIndex.value * segmentProgress)
        const currentSegmentPct = (segmentVal / segmentProgress) * 100
        const currentStepVal = Math.floor(currentSegmentPct / 5) * 5
        if (currentStepVal > lastStepPct.value) {
          lastStepPct.value = currentStepVal
          if (currentStepVal < 95) {
            if (safeStepsRemaining.value > 0) {
              safeStepsRemaining.value--
            } else {
              let chance = 0.15
              if (activeTravelModifiers.value.encounterRateMod !== 0) {
                chance = chance * (1 + (activeTravelModifiers.value.encounterRateMod / 100))
              }
              if (activeSweetScent.value) {
                chance += 0.50
              }
              if (Math.random() < chance) {
                safeStepsRemaining.value = 5
                triggerRandomEvent()
              }
            }
          }
        }
      }
    })
  }

  const triggerHeal = () => {
    if (isTraveling.value) return
    shopStore.healAllPokemon(0)
    travelLog.value.push(`🏥 ¡Tu equipo ha sido completamente curado en el Centro Pokémon!`)
  }

  const finishTravelAtNode = (nodeId: string) => {
    if (travelTween) { travelTween.kill(); travelTween = null }
    if (markerTimeline) { markerTimeline.kill(); markerTimeline = null }

    activeEvent.value = null
    isTraveling.value = false
    isPaused.value = false
    showMarker.value = false
    isArrivalEventPending.value = false

    const pos = nodePositions.value[nodeId]
    if (pos) {
      markerX.value = pos.x + CARD_W / 2
      markerY.value = pos.y + CARD_H / 2
      centerOnPoint(markerX.value, markerY.value, 0.6)
    }

    originMap.value = nodeId
    mapStore.currentMap = nodeId
    const nodeName = FIRE_RED_MAPS.find(m => m.id === nodeId)?.name || nodeId
    travelLog.value.push(`📍 Ubicación actual: ${nodeName}. El selector de origen ha sido actualizado.`)
    calculateRoute()
  }

  function resumeTravelAfterEvent() {
    if (!activeEvent.value) return
    travelLog.value.push(`✅ Evento resuelto: ${activeEvent.value.title}`)
    activeEvent.value = null

    if (!isTraveling.value || !travelTween) return

    if (isArrivalEventPending.value) {
      const path = calculatedPath.value
      const nextSegIdx = currentSegmentIndex.value + 1
      if (nextSegIdx < path.length) {
        const nextNodeId = path[nextSegIdx]!
        const nodeName = FIRE_RED_MAPS.find(m => m.id === nextNodeId)?.name || nextNodeId
        travelLog.value.push(`Entrando a: ${nodeName}`)

        if (POKEMON_CENTER_NODES.has(nextNodeId)) {
          shopStore.healAllPokemon(0)
          travelLog.value.push(`🏥 ¡Centro Pokémon visitado en ${nodeName}! Tu equipo de pruebas ha sido completamente curado.`)
        }

        currentSegmentIndex.value = nextSegIdx
        originMap.value = nextNodeId
        mapStore.currentMap = nextNodeId
      }

      lastStepPct.value = 0
      isArrivalEventPending.value = false

      if (currentSegmentIndex.value === path.length - 1) {
        finishTravelAtNode(destinationMap.value)
        travelLog.value.push('🎉 ¡Llegaste a tu destino con éxito!')
      } else {
        isPaused.value = false
        travelTween.resume()
        if (markerTimeline) markerTimeline.resume()
      }
    } else {
      isPaused.value = false
      travelTween.resume()
      if (markerTimeline) markerTimeline.resume()
    }
  }

  function cancelTravel() {
    const currentNodeId = calculatedPath.value[currentSegmentIndex.value] || originMap.value
    if (travelTween) { travelTween.kill(); travelTween = null }
    if (markerTimeline) { markerTimeline.kill(); markerTimeline = null }
    isTraveling.value = false
    isPaused.value = false
    travelProgress.value = 0
    activeEvent.value = null
    showMarker.value = false
    showArchaeology.value = false
    showFishing.value = false
    originMap.value = currentNodeId
    mapStore.currentMap = currentNodeId
    travelLog.value.push('❌ Viaje cancelado por el usuario.')
    travelLog.value.push(`📍 Ubicación actual: ${FIRE_RED_MAPS.find(m => m.id === currentNodeId)?.name || currentNodeId}.`)
    calculateRoute()
  }

  const moLabels: Record<string, string> = {
    surf: '🌊 Surf',
    cut: '✂️ Corte',
    strength: '💪 Fuerza',
    flash: '💡 Flash',
    rock_smash: '🪨 G.Roca',
    waterfall: '🌊 Cascada',
    fly: '🕊️ Vuelo',
  }

  const onModalEnter = (el: Element, done: () => void) => {
    const backdrop = el as HTMLElement
    const card = backdrop.querySelector('.adv-event-modal-card')
    if (!card) {
      done()
      return
    }
    gsap.set(backdrop, { opacity: 0 })
    gsap.set(card, { scale: 0.8, opacity: 0 })
    const tl = gsap.timeline({ onComplete: done })
    tl.to(backdrop, { opacity: 1, duration: 0.25, ease: 'power2.out' })
      .to(card, { scale: 1, opacity: 1, duration: 0.35, ease: 'back.out(1.5)' }, '-=0.1')
  }

  const onModalLeave = (el: Element, done: () => void) => {
    const backdrop = el as HTMLElement
    const card = backdrop.querySelector('.adv-event-modal-card')
    if (!card) {
      done()
      return
    }
    const tl = gsap.timeline({ onComplete: done })
    tl.to(card, { scale: 0.8, opacity: 0, duration: 0.25, ease: 'power2.in' })
      .to(backdrop, { opacity: 0, duration: 0.15, ease: 'power2.in' }, '-=0.1')
  }

  onUnmounted(() => {
    if (typeof gameStore.exitSandboxMode === 'function') {
      gameStore.exitSandboxMode()
    }
    if (battleStore.isBattleActive) {
      battleStore.state = null
      battleStore.fsm.transition('EXIT_BATTLE')
    }
  })

  return {
    originMap,
    destinationMap,
    isBikeActive,
    activeHMs,
    showPreTravelModal,
    selectedTravelItems,
    pendingManualDestination,
    activeSweetScent,
    isTraveling,
    isPaused,
    travelProgress,
    calculatedPath,
    currentSegmentIndex,
    lastStepPct,
    safeStepsRemaining,
    isArrivalEventPending,
    blockedConnections,
    travelLog,
    injectedItems,
    activeEvent,
    showArchaeology,
    showFishing,
    minigamePokemon,
    graphEdges,
    markerX,
    markerY,
    showMarker,
    glowMarkerRef,
    viewportRef,
    canvasRef,
    cameraX,
    cameraY,
    cameraScale,
    isDragging,
    zoomIn,
    zoomOut,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    hasHealthyTeam,
    nodePositions,
    mapLocationsById,
    getSpawnPoolForMap,
    getWeatherForMap,
    validNodeIds,
    worldOverlayScale,
    pokemonCenterOverlays,
    currentMapId,
    adjacentConnections,
    startManualTravel,
    cancelPreTravel,
    confirmPreTravel,
    filteredBuffItems,
    pathSet,
    pathEdgeSet,
    toggleHM,
    calculateRoute,
    resolveEvent,
    triggerExplore,
    triggerHeal,
    handleMinigameWin,
    handleMinigameFail,
    finishTravelAtNode,
    resumeTravelAfterEvent,
    cancelTravel,
    moLabels,
    onModalEnter,
    onModalLeave,
    toggleTravelItem,
    activeTravelModifiers,
    activeTeamPassives,
    availableActiveMoves,
    useActiveRouteMove,
    gameStore,
    mapStore,
    POKEMON_CENTER_NODES,
    CANVAS_W,
    CANVAS_H,
    isEdgeOnPath,
    isEdgeTraversable,
    hasBicycle,
    jumpToPoint
  }
}

import { watch, onMounted, onUnmounted, nextTick, type Ref } from 'vue'
import { gsap } from 'gsap'

export function useMapCardAnimations(options: {
  cardRef: Ref<HTMLElement | null>
  spawnGridRef: Ref<HTMLElement | null>
  isVisible: Ref<boolean>
  isPerformanceMode: Ref<boolean>
  isLowPowerActive: Ref<boolean>
  computedWeather: Ref<string>
  isPlayerWinner: Ref<boolean>
  cardSeed: Ref<number>
  dominanceWinner: Ref<string | undefined>
  hasFishing: Ref<object | null | undefined>
  hasArchaeology: Ref<object | null | undefined>
  spawnGridSlots: Ref<(string | null)[]>
}) {
  let pillContext: gsap.Context | null = null
  let auraContext: gsap.Context | null = null

  const initPillAnimations = () => {
    if (pillContext) {
      pillContext.revert()
      pillContext = null
    }

    if (!options.isVisible.value || options.isPerformanceMode.value || options.isLowPowerActive.value) {
      return
    }

    pillContext = gsap.context((self) => {
      const seed = options.cardSeed.value

      // 1. Weather Tag / Location Tag
      const weatherEl = self.selector!('.location-tag')[0] as HTMLElement | undefined
      if (weatherEl) {
        const weather = options.computedWeather.value
        let type: 'glow' | 'drift' | 'shake' | '' = ''
        if (['clear', 'sun', 'heatwave', 'cold', 'coldwave', 'sandstorm', 'dust_storm', 'intense_sun'].includes(weather)) {
          type = 'glow'
        } else if (['mist', 'fog', 'wind', 'strong_winds'].includes(weather)) {
          type = 'drift'
        } else if (['rain', 'heavy_rain', 'storm', 'thunderstorm', 'hail'].includes(weather)) {
          type = 'shake'
        }

        if (type === 'glow') {
          const tl = gsap.fromTo(weatherEl,
            { filter: 'brightness(1.0)', boxShadow: '0 4px 12px rgba(0, 0, 0, 0.4)' },
            {
              boxShadow: '0 4px 12px rgba(0, 0, 0, 0.4), 0px 0px 8px rgba(255, 204, 0, 0.6)',
              filter: 'brightness(1.2)',
              duration: 1.5,
              yoyo: true,
              repeat: -1,
              ease: 'sine.inOut'
            }
          )
          tl.progress(seed)
        } else if (type === 'drift') {
          const tl = gsap.to(weatherEl, {
            x: 3,
            duration: 2.0,
            yoyo: true,
            repeat: -1,
            ease: 'power1.inOut'
          })
          tl.progress(seed)
        } else if (type === 'shake') {
          const tl = gsap.timeline({ repeat: -1 })
          tl.to(weatherEl, { rotation: 2, duration: 0.125, ease: 'power1.inOut' })
            .to(weatherEl, { rotation: -2, duration: 0.25, ease: 'power1.inOut' })
            .to(weatherEl, { rotation: 0, duration: 0.125, ease: 'power1.inOut' })
          tl.progress(seed)
        }
      }

      // 2. Faction Pill
      const factionEl = self.selector!('.faction-status-pill')[0] as HTMLElement | undefined
      if (factionEl) {
        const winner = options.dominanceWinner.value
        if (winner === 'union') {
          const tl = gsap.fromTo(factionEl,
            { rotation: 0, scale: 1, filter: 'brightness(1.0)' },
            {
              rotation: 10,
              scale: 1.05,
              filter: 'brightness(1.3)',
              duration: 2.5,
              yoyo: true,
              repeat: -1,
              ease: 'sine.inOut'
            }
          )
          tl.progress(seed)
        } else if (winner === 'poder') {
          const tl = gsap.timeline({ repeat: -1 })
          tl.fromTo(factionEl,
            { scale: 1.0 },
            { scale: 1.15, duration: 0.3, ease: 'power1.inOut' }
          )
          .to(factionEl, { scale: 1.0, duration: 0.3, ease: 'power1.inOut' })
          .to(factionEl, { scale: 1.0, duration: 1.4 })
          tl.progress(seed)
        }
      }

      // 3. Fishing Pill
      const fishingEl = self.selector!('.fishing-pill')[0] as HTMLElement | undefined
      if (fishingEl) {
        const tl = gsap.timeline({ repeat: -1 })
        tl.to(fishingEl, { y: -8, rotation: 5, duration: 1.32, ease: 'sine.inOut' })
          .to(fishingEl, { y: 2, rotation: -3, duration: 1.32, ease: 'sine.inOut' })
          .to(fishingEl, { y: 0, rotation: 0, duration: 1.36, ease: 'sine.inOut' })
        tl.progress(seed)
      }

      // 3.1 Archaeology Pill
      const archaeologyEl = self.selector!('.archaeology-pill')[0] as HTMLElement | undefined
      if (archaeologyEl) {
        const pickEl = archaeologyEl.querySelector('.pill-icon')
        if (pickEl) {
          gsap.set(pickEl, { transformOrigin: '80% 80%', display: 'inline-block' })
          const swingTl = gsap.timeline({ repeat: -1 })
          swingTl.to(pickEl, { rotation: 25, duration: 0.8, ease: 'power1.out' })
                 .to(pickEl, { rotation: -15, duration: 0.15, ease: 'power2.in' })
                 .to(pickEl, { rotation: 0, duration: 0.35, ease: 'sine.out' })
          swingTl.progress(seed)
        }
      }

      // 4. Winner Crown
      const crownEl = self.selector!('.dom-badge')[0] as HTMLElement | undefined
      if (crownEl && !options.isLowPowerActive.value) {
        const shineEl = crownEl.querySelector('.crown-shine-aura') as HTMLElement | undefined
        if (shineEl) {
          gsap.to(shineEl, {
            rotation: 360,
            duration: 10,
            repeat: -1,
            ease: 'none'
          })

          const breatheTl = gsap.fromTo(shineEl,
            { scale: 0.8, opacity: 0.35 },
            {
              scale: 1.5,
              opacity: 0.8,
              duration: 1.8,
              yoyo: true,
              repeat: -1,
              ease: 'sine.inOut'
            }
          )
          breatheTl.progress(seed)
        }
      }
    }, options.cardRef.value || undefined)
  }

  const initAuraAnimations = () => {
    if (auraContext) auraContext.revert()
    if (!options.spawnGridRef.value || !options.isVisible.value) return

    auraContext = gsap.context((self: gsap.Context) => {
      const AURA_CYCLE = 2.0
      const wrappers = self.selector!('.sprite-wrapper') as HTMLElement[]

      wrappers.forEach((el) => {
        const isRare = el.classList.contains('rare-spawn')
        const isAtmos = el.classList.contains('atmospheric-spawn')

        if (!isRare && !isAtmos) return

        const seedAttr = el.style.getPropertyValue('--spawn-seed')
        const seed = seedAttr ? parseFloat(seedAttr) : Math.random()
        const baseDelay = (seed % 1) * AURA_CYCLE

        if (!options.isLowPowerActive.value) {
          const scaleMax = isAtmos ? 1.08 : 1.05
          const tl = gsap.timeline({ repeat: -1, delay: baseDelay })
          tl.to(el, { scale: scaleMax, duration: 0.4, ease: 'power2.out' })
            .to(el, { scale: 1, duration: 0.8, ease: 'sine.inOut' })
        }

        const rareAura = el.parentElement?.querySelector('.rare-aura')
        const atmosAura = el.parentElement?.querySelector('.atmospheric-aura')

        if (rareAura || atmosAura) {
          const auraTl = gsap.timeline({
            repeat: -1,
            delay: baseDelay
          })

          const duration = AURA_CYCLE / 2

          if (options.isLowPowerActive.value) {
            if (rareAura) gsap.set(rareAura, { scale: 2.2, rotation: 0 })
            if (atmosAura) gsap.set(atmosAura, { scale: 2.2, rotation: 0 })

            if (rareAura && atmosAura) {
              gsap.set(rareAura, { opacity: 0 })
              gsap.set(atmosAura, { opacity: 0.9 })

              auraTl.to(rareAura, { opacity: 1, duration: duration, ease: 'sine.inOut' }, 0)
              auraTl.to(atmosAura, { opacity: 0, duration: duration, ease: 'sine.inOut' }, 0)
              auraTl.to(rareAura, { opacity: 0, duration: duration, ease: 'sine.inOut' }, duration)
              auraTl.to(atmosAura, { opacity: 0.9, duration: duration, ease: 'sine.inOut' }, duration)
            } else {
              if (rareAura) {
                gsap.set(rareAura, { opacity: 0 })
                auraTl.to(rareAura, { opacity: 1, duration: duration, ease: 'sine.inOut' }, 0)
                auraTl.to(rareAura, { opacity: 0, duration: duration, ease: 'sine.inOut' }, duration)
              }
              if (atmosAura) {
                gsap.set(atmosAura, { opacity: 0 })
                auraTl.to(atmosAura, { opacity: 0.9, duration: duration, ease: 'sine.inOut' }, 0)
                auraTl.to(atmosAura, { opacity: 0, duration: duration, ease: 'sine.inOut' }, duration)
              }
            }
          } else {
            if (rareAura && atmosAura) {
              gsap.set(rareAura, { scale: 0.1, opacity: 0 })
              gsap.set(atmosAura, { scale: 3.375, opacity: 0.9 })

              auraTl.call(() => {
                gsap.set(rareAura, { rotation: Math.random() * 360 })
              }, [], 0)

              auraTl.to(rareAura, {
                scale: 3.375,
                opacity: 1,
                duration: duration,
                ease: 'sine.inOut'
              }, 0)

              auraTl.to(atmosAura, {
                scale: 0.1,
                opacity: 0,
                duration: duration,
                ease: 'sine.inOut'
              }, 0)

              auraTl.call(() => {
                gsap.set(atmosAura, { rotation: Math.random() * 360 })
              }, [], duration)

              auraTl.to(rareAura, {
                scale: 0.1,
                opacity: 0,
                duration: duration,
                ease: 'sine.inOut'
              }, duration)

              auraTl.to(atmosAura, {
                scale: 3.375,
                opacity: 0.9,
                duration: duration,
                ease: 'sine.inOut'
              }, duration)
            } else {
              if (rareAura) {
                gsap.set(rareAura, { scale: 0.1, opacity: 0 })

                auraTl.call(() => {
                  gsap.set(rareAura, { rotation: Math.random() * 360 })
                }, [], 0)

                auraTl.to(rareAura, {
                  scale: 3.375,
                  opacity: 1,
                  duration: duration,
                  ease: 'sine.inOut'
                }, 0)

                auraTl.to(rareAura, {
                  scale: 0.1,
                  opacity: 0,
                  duration: duration,
                  ease: 'sine.inOut'
                }, duration)
              }
              if (atmosAura) {
                gsap.set(atmosAura, { scale: 0.1, opacity: 0 })

                auraTl.call(() => {
                  gsap.set(atmosAura, { rotation: Math.random() * 360 })
                }, [], 0)

                auraTl.to(atmosAura, {
                  scale: 3.375,
                  opacity: 0.9,
                  duration: duration,
                  ease: 'sine.inOut'
                }, 0)

                auraTl.to(atmosAura, {
                  scale: 0.1,
                  opacity: 0,
                  duration: duration,
                  ease: 'sine.inOut'
                }, duration)
              }
            }
          }
        }
      })
    }, options.spawnGridRef.value)
  }

  // Watches for Pill Animations
  watch(
    [
      options.isVisible,
      options.isPerformanceMode,
      options.isLowPowerActive,
      options.computedWeather,
      options.dominanceWinner,
      options.hasFishing,
      options.hasArchaeology,
      options.isPlayerWinner
    ],
    () => {
      nextTick(() => {
        initPillAnimations()
      })
    },
    { flush: 'post' }
  )

  // Watch Visibility for Aura Animations
  watch(
    options.isVisible,
    (visible) => {
      if (visible) {
        gsap.killTweensOf(initAuraAnimations)
        gsap.delayedCall(0.1, initAuraAnimations)
      } else {
        gsap.killTweensOf(initAuraAnimations)
        if (auraContext) {
          auraContext.revert()
          auraContext = null
        }
      }
    }
  )

  // Watch spawn grid slots
  watch(
    () => options.spawnGridSlots.value,
    (newVal, oldVal) => {
      if (oldVal && newVal.length === oldVal.length && newVal.every((val, i) => val === oldVal[i])) {
        return
      }
      if (options.isVisible.value) {
        gsap.killTweensOf(initAuraAnimations)
        gsap.delayedCall(0.05, initAuraAnimations)
      }
    },
    { deep: false }
  )

  // Watch grid ref
  watch(options.spawnGridRef, (newRef) => {
    if (newRef && options.isVisible.value) {
      gsap.killTweensOf(initAuraAnimations)
      gsap.delayedCall(0.05, initAuraAnimations)
    } else if (!newRef) {
      if (auraContext) {
        auraContext.revert()
        auraContext = null
      }
    }
  }, { flush: 'post' })

  onMounted(() => {
    nextTick(() => {
      initPillAnimations()
      initAuraAnimations()
    })
  })

  onUnmounted(() => {
    if (auraContext) auraContext.revert()
    if (pillContext) pillContext.revert()
  })

  return {
    initPillAnimations,
    initAuraAnimations
  }
}

import { ref, watch, onMounted, type Ref } from 'vue'
import { getProcessedSprite, getProcessedAura } from '@/logic/utils/spriteOutliner'

export interface ProcessedSpawn {
  id: string | null
  key: string
  sprite?: string
  isCaught?: boolean
}

export interface ProcessedGuardian {
  id: string
  sprite?: string
  isCaught?: boolean
}

export function useMapCardSprites(
  processedGrid: Ref<ProcessedSpawn[]>,
  processedGuardian: Ref<ProcessedGuardian | null>,
  flare1Url: string,
  flare2Url: string
) {
  const processedSprites = ref<Record<string, string>>({})
  const guardianProcessedSprite = ref<string>('')
  const processedRareAura = ref<string>('')
  const processedAtmosAura = ref<string>('')

  onMounted(() => {
    // Pre-render global auras for spawns
    try {
      getProcessedAura(flare2Url, 'rgba(255, 0, 0, 0.9)', 1.5).then(url => {
        processedRareAura.value = url
      })
      getProcessedAura(flare1Url, 'rgba(0, 255, 255, 0.85)', 1.5).then(url => {
        processedAtmosAura.value = url
      })
    } catch (e) {
      console.warn('[MapCardSprites] Failed to pre-render auras:', e)
    }
  })

  // Watch spawn grid to process and cache outlines
  watch(
    () => processedGrid.value,
    (newGrid) => {
      if (!newGrid) return
      newGrid.forEach(async (item) => {
        if (!item.id || !item.sprite) return
        const key = `${item.key}-${item.isCaught}`
        if (processedSprites.value[key]) return

        const type = !item.isCaught ? 'silhouette' : 'outline'
        try {
          const processed = await getProcessedSprite(item.sprite, type)
          processedSprites.value[key] = processed
        } catch (e) {
          console.warn('[MapCardSprites] Failed to process outline for spawn:', item.id, e)
        }
      })
    },
    { immediate: true, deep: true }
  )

  // Watch guardian to process outline
  watch(
    () => processedGuardian.value,
    async (newGuardian) => {
      if (!newGuardian || !newGuardian.sprite) {
        guardianProcessedSprite.value = ''
        return
      }
      const type = !newGuardian.isCaught ? 'silhouette' : 'outline'
      try {
        const processed = await getProcessedSprite(newGuardian.sprite, type)
        guardianProcessedSprite.value = processed
      } catch (e) {
        console.warn('[MapCardSprites] Failed to process outline for guardian:', newGuardian.id, e)
      }
    },
    { immediate: true }
  )

  return {
    processedSprites,
    guardianProcessedSprite,
    processedRareAura,
    processedAtmosAura
  }
}

import { computed } from 'vue'
import { useGameStore } from '@/stores/game'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import type { MapLocation } from '@/types/encounters'

interface ArchaeologyRewardData {
  name: string
  type: string
  basePercentage: number
  percentage: number
  baseWeight: number
  activeWeight: number
  addedWeight: number
  baseTotalWeight: number
  activeTotalWeight: number
}

export function useRouteSpawnsArchaeology(
  props: { map: MapLocation; weather: string; cycle: string }
) {
  const gameStore = useGameStore()

  const archaeologyRewards = computed(() => {
    if (!props.map.archaeology?.pool) return []

    const pool = props.map.archaeology.pool
    const rates = props.map.archaeology.rates || []
    const totalRates = rates.reduce((sum, r) => sum + r, 0) || 1

    const baseCategoryWeights = {
      fossil: 45,
      stone: 25,
      common: 20,
      rare: 10
    }

    const activeCategoryWeights = { ...baseCategoryWeights }

    const pickaxeType = (gameStore.state.pickaxeSecs || 0) > 0 ? (gameStore.state.pickaxeType || 'standard') : null
    const brushType = (gameStore.state.brushSecs || 0) > 0 ? (gameStore.state.brushType || 'standard') : null

    if (pickaxeType === 'good' || pickaxeType === 'super') {
      const budget = pickaxeType === 'good' ? 500 : 1000
      const affected = [
        { key: 'rare', base: 10 },
        { key: 'common', base: 20 },
        { key: 'stone', base: 25 }
      ]
      let remaining = budget
      for (let i = 0; i < affected.length; i++) {
        const item = affected[i]!
        let added = 0
        if (i === affected.length - 1) {
          added = remaining
        } else {
          added = Math.round(remaining * 0.5)
        }
        activeCategoryWeights[item.key as 'rare' | 'common' | 'stone'] += added
        remaining -= added
      }
    }

    if (brushType === 'good' || brushType === 'super') {
      const budget = brushType === 'good' ? 500 : 1000
      activeCategoryWeights.fossil += budget
    }

    const baseTotal = baseCategoryWeights.fossil + baseCategoryWeights.stone + baseCategoryWeights.common + baseCategoryWeights.rare
    const activeTotal = activeCategoryWeights.fossil + activeCategoryWeights.stone + activeCategoryWeights.common + activeCategoryWeights.rare

    const list: Array<{
      name: string
      type: string
      icon: string
      sprite: string
      percentage: number
      basePercentage: number
      statusClass: string
      description?: string
      baseWeight: number
      activeWeight: number
      addedWeight: number
      baseTotalWeight: number
      activeTotalWeight: number
    }> = []

    pool.forEach((id, index) => {
      const rate = rates[index] !== undefined ? rates[index]! : 10
      const relativeRate = rate / totalRates

      const baseFossilPct = relativeRate * baseCategoryWeights.fossil
      const activeFossilPct = relativeRate * activeCategoryWeights.fossil

      let name = 'Ámbar Viejo'
      let icon = '💎'
      let sprite = getAssetUrl(ASSET_TYPES.ITEM, 'old_amber')

      if (id === 'kabuto') {
        name = 'Fósil Domo'
        icon = '🛡'
        sprite = getAssetUrl(ASSET_TYPES.ITEM, 'dome_fossil')
      } else if (id === 'omanyte') {
        name = 'Fósil Hélix'
        icon = '🐚'
        sprite = getAssetUrl(ASSET_TYPES.ITEM, 'helix_fossil')
      }

      const baseW = relativeRate * baseCategoryWeights.fossil
      const activeW = relativeRate * activeCategoryWeights.fossil

      list.push({
        name,
        type: 'Fósil',
        icon,
        sprite,
        percentage: (activeFossilPct / activeTotal) * 100,
        basePercentage: (baseFossilPct / baseTotal) * 100,
        statusClass: 'common',
        baseWeight: baseW,
        activeWeight: activeW,
        addedWeight: activeW - baseW,
        baseTotalWeight: baseTotal,
        activeTotalWeight: activeTotal
      })
    })

    list.push({
      name: 'Piedras Evolutivas',
      type: 'Evolución',
      icon: '⚡',
      sprite: getAssetUrl(ASSET_TYPES.ITEM, 'fire_stone'),
      percentage: (activeCategoryWeights.stone / activeTotal) * 100,
      basePercentage: (baseCategoryWeights.stone / baseTotal) * 100,
      statusClass: 'visitor',
      description: 'Piedra Fuego, Piedra Agua, Piedra Trueno, Piedra Hoja, Piedra Lunar, Piedra Solar',
      baseWeight: baseCategoryWeights.stone,
      activeWeight: activeCategoryWeights.stone,
      addedWeight: activeCategoryWeights.stone - baseCategoryWeights.stone,
      baseTotalWeight: baseTotal,
      activeTotalWeight: activeTotal
    })

    list.push({
      name: 'Minerales Comunes',
      type: 'Mineral',
      icon: '🪨',
      sprite: getAssetUrl(ASSET_TYPES.ITEM, 'iron_ore'),
      percentage: (activeCategoryWeights.common / activeTotal) * 100,
      basePercentage: (baseCategoryWeights.common / baseTotal) * 100,
      statusClass: 'common',
      description: 'Perla, Polvo Estelar, Carbón, Cobre, Hierro',
      baseWeight: baseCategoryWeights.common,
      activeWeight: activeCategoryWeights.common,
      addedWeight: activeCategoryWeights.common - baseCategoryWeights.common,
      baseTotalWeight: baseTotal,
      activeTotalWeight: activeTotal
    })

    list.push({
      name: 'Gemas y Metales Raros',
      type: 'Valioso',
      icon: '🟡',
      sprite: getAssetUrl(ASSET_TYPES.ITEM, 'diamond_ore'),
      percentage: (activeCategoryWeights.rare / activeTotal) * 100,
      basePercentage: (baseCategoryWeights.rare / baseTotal) * 100,
      statusClass: 'exclusive',
      description: 'Pepita, Perla Grande, Estrella, Plata, Oro, Wolframio, Uranio, Rubí, Zafiro, Esmeralda, Topacio, Diamante',
      baseWeight: baseCategoryWeights.rare,
      activeWeight: activeCategoryWeights.rare,
      addedWeight: activeCategoryWeights.rare - baseCategoryWeights.rare,
      baseTotalWeight: baseTotal,
      activeTotalWeight: activeTotal
    })

    return list
  })

  function getArchaeologySpawnTooltip(reward: ArchaeologyRewardData) {
    const lines: string[] = []

    lines.push(`CÁLCULO DE PROBABILIDAD BASE:`)
    lines.push(`• Peso Base del Grupo: ${reward.baseWeight.toFixed(1)} pts`)
    lines.push(`• Peso Total Base Zona: ${reward.baseTotalWeight.toFixed(1)} pts`)
    lines.push(`• Fórmula Base: (${reward.baseWeight.toFixed(1)} / ${reward.baseTotalWeight.toFixed(1)}) x 100 = ${reward.basePercentage.toFixed(1)}%`)
    lines.push(``)

    lines.push(`CÁLCULO DE PROBABILIDAD REAL:`)
    lines.push(`• Peso Base: ${reward.baseWeight.toFixed(1)} pts`)
    if (reward.addedWeight > 0) {
      lines.push(`• Peso Añadido (Herramienta): +${reward.addedWeight.toFixed(1)} pts`)
    }
    lines.push(`• Peso Total Actual del Grupo: ${reward.activeWeight.toFixed(1)} pts`)
    lines.push(`• Peso Total Acumulado Zona: ${reward.activeTotalWeight.toFixed(1)} pts`)
    lines.push(`• Fórmula Real: (${reward.activeWeight.toFixed(1)} / ${reward.activeTotalWeight.toFixed(1)}) x 100 = ${reward.percentage.toFixed(1)}%`)
    lines.push(``)

    const pickaxeType = gameStore.state.pickaxeSecs > 0 ? gameStore.state.pickaxeType : null
    const brushType = gameStore.state.brushSecs > 0 ? gameStore.state.brushType : null
    if (reward.type === 'Fósil') {
      if (brushType) {
        const names: Record<string, string> = { standard: 'Pincel de excavación', good: 'Pincel Bueno', super: 'Superpincel' }
        const toolName = names[brushType] || 'Pincel de excavación'
        const budget = brushType === 'good' ? 500 : (brushType === 'super' ? 1000 : 0)
        if (budget > 0) {
          lines.push(`• ${toolName} activo: agrega +${budget} pts al peso total de Fósiles.`)
        } else {
          lines.push(`• ${toolName} activo.`)
        }
      }
    } else {
      if (pickaxeType) {
        const names: Record<string, string> = { standard: 'Pico de excavación', good: 'Pico Bueno', super: 'Superpico' }
        const toolName = names[pickaxeType] || 'Pico de excavación'
        const budget = pickaxeType === 'good' ? 500 : (pickaxeType === 'super' ? 1000 : 0)
        if (budget > 0) {
          lines.push(`• ${toolName} activo: agrega +${budget} pts en total (+50% a Raros, +25% a Comunes, +25% a Piedras).`)
        } else {
          lines.push(`• ${toolName} activo.`)
        }
      }
    }
    return {
      title: `DETALLES DE ARQUEOLOGÍA`,
      description: lines.join('\n')
    }
  }

  return {
    archaeologyRewards,
    getArchaeologySpawnTooltip
  }
}

import { computed } from 'vue'
import { getMechanicalWeather, WEATHER_UI_METADATA, WEATHER_VISUAL_METADATA, WEATHER_REGISTRY } from '@/logic/weather/weatherRegistry'
import type { MapLocation } from '@/types/encounters'
import { GAME_RATIOS } from '@/data/constants'
import { useGameStore } from '@/stores/game'
import { useEventStore } from '@/stores/events'

import { useRouteSpawnsWild } from './useRouteSpawnsWild'
import { useRouteSpawnsFishing } from './useRouteSpawnsFishing'
import { useRouteSpawnsArchaeology } from './useRouteSpawnsArchaeology'

interface ExtendedMapLocation extends MapLocation {
  isVolcanic?: boolean
  isSwamp?: boolean
  isArctic?: boolean
  isForest?: boolean
  isCoastal?: boolean
  isMountain?: boolean
  isPlains?: boolean
  isUrban?: boolean
}

export function useRouteSpawnsCalculation(
  props: { map: MapLocation; weather: string; cycle: string }
) {
  const gameStore = useGameStore()
  const eventStore = useEventStore()

  const { wildSpawns, getWildSpawnTooltip } = useRouteSpawnsWild(props)
  const { fishingSpawns, getFishingSpawnTooltip } = useRouteSpawnsFishing(props)
  const { archaeologyRewards, getArchaeologySpawnTooltip } = useRouteSpawnsArchaeology(props)

  const weatherEmoji = computed(() => {
    const visual = WEATHER_VISUAL_METADATA[props.weather]
    if (visual) return visual.icon
    const mech = getMechanicalWeather(props.weather)
    return WEATHER_UI_METADATA[mech]?.icon || ''
  })

  const weatherLabel = computed(() => {
    const visual = WEATHER_VISUAL_METADATA[props.weather]
    if (visual) return visual.label
    const mech = getMechanicalWeather(props.weather)
    return WEATHER_UI_METADATA[mech]?.label || 'Normal'
  })

  const weatherDetails = computed(() => {
    return WEATHER_REGISTRY[props.weather] || null
  })

  const SPANISH_TYPE_MAP: Record<string, string> = {
    'fuego': 'fire',
    'agua': 'water',
    'planta': 'grass',
    'eléctrico': 'electric',
    'hielo': 'ice',
    'tierra': 'ground',
    'roca': 'rock',
    'volador': 'flying',
    'bicho': 'bug',
    'fantasma': 'ghost',
    'siniestro': 'dark',
    'dragón': 'dragon',
    'acero': 'steel',
    'hada': 'fairy',
    'psíquico': 'psychic',
    'veneno': 'poison',
    'normal': 'normal',
    'lucha': 'fighting'
  }

  const parsedDescriptionLines = computed(() => {
    const desc = weatherDetails.value?.description || ''
    if (!desc) return []

    const sentences = desc.split(/\.\s+/).map(s => s.trim()).filter(Boolean)
    const typeWords = Object.keys(SPANISH_TYPE_MAP)
    // fallow-ignore-next-line security-sink
    const regex = new RegExp(`\\b(${typeWords.join('|')})\\b`, 'gi')

    return sentences.map(sentence => {
      const cleanSentence = sentence.endsWith('.') ? sentence : `${sentence}.`
      const lowerSentence = cleanSentence.toLowerCase()

      let typeClass = ''
      let icon = ''
      let label = ''
      let restOfSentence = cleanSentence

      if (lowerSentence.startsWith('potencia')) {
        typeClass = 'boost'
        icon = '▲ '
        label = 'POTENCIA:'
        restOfSentence = cleanSentence.substring(8).trim()
      } else if (lowerSentence.startsWith('debilita')) {
        typeClass = 'debuff'
        icon = '▼ '
        label = 'DEBILITA:'
        restOfSentence = cleanSentence.substring(8).trim()
      } else if (lowerSentence.startsWith('penaliza')) {
        typeClass = 'debuff'
        icon = '▼ '
        label = 'PENALIZA:'
        restOfSentence = cleanSentence.substring(8).trim()
      } else if (lowerSentence.startsWith('bloquea')) {
        typeClass = 'block'
        icon = 'block'
        label = 'BLOQUEA:'
        restOfSentence = cleanSentence.substring(7).trim()
      }

      const parts = restOfSentence.split(regex)
      const segments = parts.filter(Boolean).map(part => {
        const lower = part.toLowerCase()
        const typeKey = SPANISH_TYPE_MAP[lower]
        return {
          text: part,
          isType: !!typeKey,
          type: typeKey || ''
        }
      })

      return {
        segments,
        typeClass,
        icon,
        label
      }
    })
  })

  const getStatusTooltip = (type: string) => {
    const weatherName = weatherLabel.value || 'el clima actual'
    const tooltips: Record<string, { title: string, desc: string }> = {
      'Común': {
        title: 'Común',
        desc: 'Aparición habitual en esta zona durante este ciclo de tiempo.'
      },
      'Visitante': {
        title: 'Visitante Climático',
        desc: `Pokémon que no habita esta zona normalmente, pero es atraído por el clima actual (${weatherName}).`
      },
      'Exclusivo': {
        title: 'Exclusivo Climático',
        desc: `Pokémon que solo puede aparecer en esta zona bajo las condiciones del clima actual (${weatherName}).`
      },
      'Bloqueado': {
        title: 'Bloqueado por Clima',
        desc: `El clima actual (${weatherName}) impide que este Pokémon aparezca en la zona.`
      },
      'Fuera de hora': {
        title: 'Fuera de Hora',
        desc: 'Este Pokémon no está activo en esta ruta durante este ciclo horario.'
      },
      'Potenciado': {
        title: `Potenciado por clima (${weatherName})`,
        desc: `La probabilidad de aparición de este Pokémon ha sido aumentada por el clima actual: ${weatherName}.`
      },
      'Debilitado': {
        title: `Debilitado por clima (${weatherName})`,
        desc: `La probabilidad de aparición de este Pokémon ha sido reducida por el clima actual: ${weatherName}.`
      },
      'Pesca': {
        title: 'Encuentro de Pesca',
        desc: 'Pokémon que solo puede encontrarse pescando en el agua.'
      }
    }
    return tooltips[type] || { title: type, desc: '' }
  }

  const terrainTags = computed(() => {
    const m = props.map as ExtendedMapLocation
    const tags: string[] = []
    if (m.isCrystalCave) tags.push('💎 Cueva de Cristal')
    if (m.isCave) tags.push('🧗 Cueva')
    if (m.isVolcanic) tags.push('🌋 Volcánico')
    if (m.isSwamp) tags.push('🐊 Pantano')
    if (m.isArctic) tags.push('❄️ Ártico')
    if (m.isForest) tags.push('🌲 Bosque')
    if (m.isCoastal) tags.push('🏖️ Costa')
    if (m.isMountain) tags.push('⛰️ Montaña')
    if (m.isPlains) tags.push('🌾 Llanura')
    if (m.isUrban) tags.push('🏙️ Urbano')
    if (m.isIndoors) tags.push('🏠 Interior')

    if (tags.length === 0) tags.push('🌲 Exterior')
    return tags.join(', ')
  })

  const activeWeights = computed(() => {
    const weather = props.weather || 'clear'
    const isRainy = ['rain', 'heavy_rain', 'storm', 'thunderstorm'].includes(weather.toLowerCase())
    const climateFishingMultiplier = isRainy ? 1.20 : 1.0
    const eventFishingBonus = eventStore.globalMultipliers?.fishing || 1
    const fishingBonus = eventFishingBonus * climateFishingMultiplier

    const groundWeight = 100

    let fishingWeight = 0
    if (props.map.fishing) {
      fishingWeight = GAME_RATIOS.encounters.fishing * 100 * fishingBonus
      if ((gameStore.state.fishingRodSecs || 0) > 0) {
        fishingWeight += 600
      }
    }

    let archWeight = 0
    if (props.map.archaeology) {
      const isCave = !!props.map.isCave
      const isMountain = !!props.map.isMountain
      archWeight = isCave ? 10 : (isMountain ? 5 : 0)
      if ((gameStore.state.pickaxeSecs || 0) > 0 || (gameStore.state.brushSecs || 0) > 0) {
        archWeight += 600
      }
    }

    const totalWeight = groundWeight + fishingWeight + archWeight

    let baseFishingWeight = 0
    if (props.map.fishing) {
      baseFishingWeight = GAME_RATIOS.encounters.fishing * 100
    }
    let baseArchWeight = 0
    if (props.map.archaeology) {
      const isCave = !!props.map.isCave
      const isMountain = !!props.map.isMountain
      baseArchWeight = isCave ? 10 : (isMountain ? 5 : 0)
    }
    const baseTotalWeight = groundWeight + baseFishingWeight + baseArchWeight

    return {
      ground: groundWeight,
      fishing: fishingWeight,
      archaeology: archWeight,
      total: totalWeight,
      baseGround: groundWeight,
      baseFishing: baseFishingWeight,
      baseArchaeology: baseArchWeight,
      baseTotal: baseTotalWeight
    }
  })

  const activeFishingChance = computed(() => {
    const w = activeWeights.value
    if (w.total === 0 || !props.map.fishing) return 0
    return Math.round((w.fishing / w.total) * 100)
  })

  const baseFishingChance = computed(() => {
    const w = activeWeights.value
    if (w.baseTotal === 0 || !props.map.fishing) return 0
    return Math.round((w.baseFishing / w.baseTotal) * 100)
  })

  const activeArchaeologyChance = computed(() => {
    const w = activeWeights.value
    if (w.total === 0 || !props.map.archaeology) return 0
    return Math.round((w.archaeology / w.total) * 100)
  })

  const baseArchaeologyChance = computed(() => {
    const w = activeWeights.value
    if (w.baseTotal === 0 || !props.map.archaeology) return 0
    return Math.round((w.baseArchaeology / w.baseTotal) * 100)
  })

  const activeTerrestrialChance = computed(() => {
    const w = activeWeights.value
    if (w.total === 0) return 0
    return Math.round((w.ground / w.total) * 100)
  })

  const baseTerrestrialChance = computed(() => {
    const w = activeWeights.value
    if (w.baseTotal === 0) return 0
    return Math.round((w.baseGround / w.baseTotal) * 100)
  })

  const getProbClass = (active: number, base: number) => {
    if (active > base) return 'bonus-text'
    if (active < base) return 'penalty-text'
    return ''
  }

  const getCategoryTooltip = (type: string) => {
    switch (type) {
      case 'Fósil':
        return { title: 'Fósil Ancestral', desc: 'Fósil desenterrable que puede ser clonado en el Daycare para obtener Pokémon ancestrales.' }
      case 'Evolución':
        return { title: 'Piedra de Evolución', desc: 'Piedras especiales utilizadas para evolucionar ciertas especies de Pokémon.' }
      case 'Mineral':
        return { title: 'Mineral Común', desc: 'Material básico útil para vender en la tienda o refinar.' }
      case 'Valioso':
        return { title: 'Gemas y Metales Raros', desc: 'Objetos y gemas de alta rareza de gran valor comercial.' }
      default:
        return { title: 'Objeto de Arqueología', desc: 'Recompensa obtenible mediante la excavación en zonas de arqueología.' }
    }
  }

  return {
    weatherEmoji,
    weatherLabel,
    weatherDetails,
    parsedDescriptionLines,
    getStatusTooltip,
    wildSpawns,
    fishingSpawns,
    terrainTags,
    activeWeights,
    activeFishingChance,
    baseFishingChance,
    activeArchaeologyChance,
    baseArchaeologyChance,
    activeTerrestrialChance,
    baseTerrestrialChance,
    getProbClass,
    getCategoryTooltip,
    archaeologyRewards,
    getWildSpawnTooltip,
    getFishingSpawnTooltip,
    getArchaeologySpawnTooltip
  }
}

import { computed } from 'vue'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { getWeatherMultiplier } from '@/logic/weather/weatherUtils'
import { useGameStore } from '@/stores/game'
import { useEventStore } from '@/stores/events'
import { useUIStore } from '@/stores/ui'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import { getMechanicalWeather, WEATHER_UI_METADATA, WEATHER_VISUAL_METADATA } from '@/logic/weather/weatherRegistry'
import type { MapLocation } from '@/types/encounters'
import type { EventConfig } from '@/logic/events/eventEngine'

interface FishingSpawnData {
  id: string
  name: string
  basePercentage: number
  percentage: number
  multiplier: number
  spawnType: string
}

export function useRouteSpawnsFishing(
  props: { map: MapLocation; weather: string; cycle: string }
) {
  const gameStore = useGameStore()
  const eventStore = useEventStore()
  const uiStore = useUIStore()

  function translateWeather(w: string): string {
    const visual = WEATHER_VISUAL_METADATA[w]
    if (visual) return visual.label
    const mech = getMechanicalWeather(w)
    return WEATHER_UI_METADATA[mech]?.label || w
  }

  const fishingSpawns = computed(() => {
    if (!props.map.fishing?.pool) return []

    const pool = [...props.map.fishing.pool]
    const rates = [...props.map.fishing.rates]
    while (rates.length < pool.length) rates.push(10)

    const weatherCfg = props.map.weather?.[props.weather]
    if (props.weather && props.weather !== 'clear' && weatherCfg) {
      if (weatherCfg.fishingExclusive) {
        const exclusives = Array.isArray(weatherCfg.fishingExclusive) ? weatherCfg.fishingExclusive : Object.keys(weatherCfg.fishingExclusive)
        exclusives.forEach(id => {
          if (!pool.includes(id)) {
            pool.push(id)
            const weight = Array.isArray(weatherCfg.fishingExclusive) ? 5 : ((weatherCfg.fishingExclusive as Record<string, number>)[id] || 5)
            rates.push(weight)
          }
        })
      }
      if (weatherCfg.fishingVisitors) {
        const visitors = Array.isArray(weatherCfg.fishingVisitors) ? weatherCfg.fishingVisitors : Object.keys(weatherCfg.fishingVisitors)
        visitors.forEach(id => {
          if (!pool.includes(id)) {
            pool.push(id)
            const weight = Array.isArray(weatherCfg.fishingVisitors) ? -10 : -((weatherCfg.fishingVisitors as Record<string, number>)[id] || 10)
            rates.push(weight)
          }
        })
      }
    }

    if (props.weather && props.weather !== 'clear') {
      const visitorIndices = rates.map((r, i) => r < 0 ? i : -1).filter(i => i !== -1)
      const nativeIndices = rates.map((r, i) => r >= 0 ? i : -1).filter(i => i !== -1)
      const exclusives = weatherCfg?.fishingExclusive ? (Array.isArray(weatherCfg.fishingExclusive) ? weatherCfg.fishingExclusive : Object.keys(weatherCfg.fishingExclusive)) : []

      nativeIndices.forEach(idx => {
        const spId = pool[idx]
        if (spId) {
          const isExclusive = exclusives.includes(spId)
          if (!isExclusive) {
            rates[idx] = (rates[idx] || 0) * getWeatherMultiplier(spId, props.weather)
          }
        }
      })

      if (visitorIndices.length > 0) {
        const totalNativeWeight = nativeIndices.reduce((sum, idx) => sum + (rates[idx] || 0), 0)
        const visitorQuota = totalNativeWeight / 9
        const sumRelativeWeights = visitorIndices.reduce((sum, idx) => sum + Math.abs(rates[idx] || 0), 0)
        visitorIndices.forEach(idx => {
          const relativeWeight = Math.abs(rates[idx] || 0) / (sumRelativeWeights || 1)
          rates[idx] = visitorQuota * relativeWeight
        })
      }
    }

    const fishingType = (gameStore.state.fishingRodSecs || 0) > 0 ? (gameStore.state.fishingRodType || 'standard') : 'standard'
    if ((fishingType === 'good' || fishingType === 'super') && pool.length > 0) {
      let budget = fishingType === 'super' ? 1000 : 500
      const indexedPool = pool.map((id, index) => ({ id, index, rate: rates[index] || 10 }))
        .sort((a, b) => a.rate - b.rate)

      for (let i = 0; i < indexedPool.length; i++) {
        const item = indexedPool[i]!
        if (i === indexedPool.length - 1) {
          rates[item.index] = (rates[item.index] || 10) + budget
          budget = 0
        } else {
          const portion = Math.round(budget / 2)
          rates[item.index] = (rates[item.index] || 10) + portion
          budget -= portion
        }
      }
    }

    const totalRate = rates.reduce((sum, r) => sum + r, 0)
    const seenPokedex = gameStore.state.seenPokedex || []
    const caughtPokedex = gameStore.state.pokedex || []

    return pool.map((id, index) => {
      const rateVal = rates[index] || 0
      const percentage = totalRate > 0 ? (rateVal / totalRate) * 100 : 0

      const baseIndex = props.map.fishing!.pool.indexOf(id)
      let baseRate = 0
      let basePercentage = 0
      if (baseIndex !== -1) {
        baseRate = props.map.fishing!.rates[baseIndex] !== undefined ? props.map.fishing!.rates[baseIndex] : 10
        const totalBase = props.map.fishing!.rates.reduce((sum, r) => sum + r, 0)
        basePercentage = totalBase > 0 ? (baseRate / totalBase) * 100 : 0
      }

      const diff = percentage - basePercentage

      let isSeen = seenPokedex.includes(id) || caughtPokedex.includes(id)
      let isCaught = caughtPokedex.includes(id)

      if (uiStore.debugPokedexMode === 'none') {
        isSeen = false
        isCaught = false
      } else if (uiStore.debugPokedexMode === 'caught') {
        isSeen = true
        isCaught = true
      } else if (uiStore.debugPokedexMode === 'seen') {
        isSeen = true
      }
      const data = isSeen ? pokemonDataProvider.getPokemonData(id) : null
      const name = isSeen ? (data?.name || id.toUpperCase()) : 'Desconocido'

      const isVisitor = !!(weatherCfg?.fishingVisitors && (
        (!Array.isArray(weatherCfg.fishingVisitors) && (weatherCfg.fishingVisitors as Record<string, number>)[id]) || 
        (Array.isArray(weatherCfg.fishingVisitors) && weatherCfg.fishingVisitors.includes(id))
      ))
      const isExclusive = !!(weatherCfg?.fishingExclusive && (
        (!Array.isArray(weatherCfg.fishingExclusive) && (weatherCfg.fishingExclusive as Record<string, number>)[id]) || 
        (Array.isArray(weatherCfg.fishingExclusive) && weatherCfg.fishingExclusive.includes(id))
      ))

      const multiplier = getWeatherMultiplier(id, props.weather)
      const isBuffed = !isVisitor && !isExclusive && multiplier > 1.0
      const isDebuffed = !isVisitor && !isExclusive && multiplier < 1.0 && multiplier > 0
      const isBlocked = multiplier === 0

      let spawnType = 'Pesca'
      let statusClass = 'common'
      if (isVisitor) {
        spawnType = 'Visitante'
        statusClass = 'visitor'
      } else if (isExclusive) {
        spawnType = 'Exclusivo'
        statusClass = 'exclusive'
      } else if (isBlocked) {
        spawnType = 'Bloqueado'
        statusClass = 'blocked'
      } else if (isBuffed) {
        spawnType = 'Potenciado'
        statusClass = 'buffed'
      } else if (isDebuffed) {
        spawnType = 'Debilitado'
        statusClass = 'debuffed'
      }

      return {
        id,
        name,
        isSeen,
        isCaught,
        sprite: getAssetUrl(ASSET_TYPES.POKEMON, id),
        percentage,
        baseRate,
        basePercentage,
        diff,
        spawnType,
        statusClass,
        multiplier,
        types: data ? [data.type, data.type2].filter(Boolean) as string[] : [],
        hp: data?.hp || 0,
        atk: data?.atk || 0,
        def: data?.def || 0,
        spa: data?.spa || 0,
        spd: data?.spd || 0,
        spe: data?.spe || 0,
        totalStats: data ? (data.hp + data.atk + data.def + data.spa + data.spd + data.spe) : 0
      }
    }).sort((a, b) => {
      if (a.percentage > 0 && b.percentage === 0) return -1
      if (a.percentage === 0 && b.percentage > 0) return 1
      if (a.percentage > 0 && b.percentage > 0) return b.percentage - a.percentage
      return b.totalStats - a.totalStats
    })
  })

  function getFishingSpawnTooltip(poke: FishingSpawnData) {
    const lines: string[] = []
    lines.push(`Probabilidad Base: ${poke.basePercentage.toFixed(1)}%`)
    const rodType = gameStore.state.fishingRodType
    const rodSecs = gameStore.state.fishingRodSecs || 0
    if (rodType && rodSecs > 0) {
      const names: Record<string, string> = { standard: 'Caña de pescar', good: 'Caña Buena', super: 'Supercaña' }
      const rodName = names[rodType] || 'Caña de pescar'
      if (rodType === 'good') {
        lines.push(`• ${rodName} activa: +500 pts distribuidos (más peso a comunes/raros)`)
      } else if (rodType === 'super') {
        lines.push(`• ${rodName} activa: +1000 pts distribuidos (más peso a comunes/raros) y aumenta la chance de Shiny x1.5`)
      } else {
        lines.push(`• ${rodName} activa.`)
      }
    }
    const weather = props.weather || 'clear'
    const isRainy = ['rain', 'heavy_rain', 'storm', 'thunderstorm'].includes(weather.toLowerCase())
    if (isRainy) {
      lines.push(`• Clima (Lluvia): x1.20 a la tasa de pesca general`)
    }
    if (poke.multiplier !== 1) {
      const change = poke.multiplier > 1 ? 'Aumento por Clima' : 'Reducción por Clima'
      const label = translateWeather(props.weather)
      lines.push(`• ${change} en especie: x${poke.multiplier} (${label})`)
    }
    if (poke.spawnType === 'Visitante') {
      const label = translateWeather(props.weather)
      const diffVal = poke.percentage - poke.basePercentage
      lines.push(`• Pokémon Visitante del clima (${label}): +${diffVal.toFixed(1)}% de probabilidad activa`)
    } else if (poke.spawnType === 'Exclusivo') {
      const label = translateWeather(props.weather)
      const diffVal = poke.percentage - poke.basePercentage
      lines.push(`• Pokémon Exclusivo del clima (${label}): +${diffVal.toFixed(1)}% de probabilidad activa`)
    } else {
      const diffVal = poke.percentage - poke.basePercentage
      if (Math.abs(diffVal) > 0.05) {
        const direction = diffVal > 0 ? 'Aumento' : 'Reducción'
        const detail = diffVal > 0
          ? 'redistribución proporcional al bloquearse, penalizarse o cambiar de hora otros Pokémon'
          : 'redistribución proporcional al inyectarse nuevos Pokémon o potenciarse otros encuentros'
        lines.push(`• ${direction} neto: ${diffVal > 0 ? '+' : ''}${diffVal.toFixed(1)}% (${detail})`)
      }
    }
    const eventFishingBonus = eventStore.globalMultipliers?.fishing || 1
    if (eventFishingBonus !== 1) {
      const activeFishingEvents = eventStore.activeEvents.filter(e => {
        const cfg = (typeof e.config === 'string' ? JSON.parse(e.config) : e.config) as EventConfig | undefined
        return cfg && cfg.fishingMult
      })
      const eventNames = activeFishingEvents.map(e => e.name).join(', ')
      lines.push(`• Evento Semanal (${eventNames}): x${eventFishingBonus.toFixed(1)} de probabilidad general`)
    }

    const globalShiny = eventStore.globalMultipliers?.shiny || 1
    if (globalShiny !== 1) {
      lines.push(`• Evento Shiny Global: x${globalShiny.toFixed(1)} de probabilidad Shiny`)
    }
    const speciesBonuses = eventStore.getSpeciesBonuses(poke.id)
    if (speciesBonuses && speciesBonuses.shiny !== 1) {
      lines.push(`• Evento Shiny Especie: x${speciesBonuses.shiny.toFixed(1)} de probabilidad Shiny`)
    }

    return {
      title: `DETALLES DE PESCA`,
      description: lines.join('\n')
    }
  }

  return {
    fishingSpawns,
    getFishingSpawnTooltip
  }
}

import { computed } from 'vue'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { getEncounterPool } from '@/logic/encounters/encounters'
import { getWeatherMultiplier } from '@/logic/weather/weatherUtils'
import { useGameStore } from '@/stores/game'
import { useEventStore } from '@/stores/events'
import { useUIStore } from '@/stores/ui'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import { getMechanicalWeather, WEATHER_UI_METADATA, WEATHER_VISUAL_METADATA } from '@/logic/weather/weatherRegistry'
import type { MapLocation } from '@/types/encounters'
import type { EventConfig } from '@/logic/events/eventEngine'

interface WildSpawnData {
  id: string
  name: string
  basePercentage: number
  percentage: number
  multiplier: number
  spawnType: string
}

export function useRouteSpawnsWild(
  props: { map: MapLocation; weather: string; cycle: string }
) {
  const gameStore = useGameStore()
  const eventStore = useEventStore()
  const uiStore = useUIStore()

  function translateWeather(w: string): string {
    const visual = WEATHER_VISUAL_METADATA[w]
    if (visual) return visual.label
    const mech = getMechanicalWeather(w)
    return WEATHER_UI_METADATA[mech]?.label || w
  }

  const wildSpawns = computed(() => {
    const activeEvents = eventStore.activeEvents || []
    const allMapSpawns = new Set<string>()
    const cycles = ['morning', 'day', 'dusk', 'night']
    cycles.forEach(c => {
      const list = props.map.wild?.[c] || []
      list.forEach(id => allMapSpawns.add(id))
    })

    const weatherCfg = props.map.weather?.[props.weather]
    if (weatherCfg) {
      if (weatherCfg.visitors) {
        const visitors = Array.isArray(weatherCfg.visitors) ? weatherCfg.visitors : Object.keys(weatherCfg.visitors)
        visitors.forEach(id => allMapSpawns.add(id))
      }
      if (weatherCfg.exclusive) {
        const exclusives = Array.isArray(weatherCfg.exclusive) ? weatherCfg.exclusive : Object.keys(weatherCfg.exclusive)
        exclusives.forEach(id => allMapSpawns.add(id))
      }
    }
    activeEvents.forEach(ev => {
      const cfg = (typeof ev.config === 'string' ? JSON.parse(ev.config) : ev.config) as EventConfig | undefined
      if (ev.active && cfg?.species) {
        cfg.species.split(',').forEach((s: string) => {
          const clean = s.trim().toLowerCase()
          if (clean) allMapSpawns.add(clean)
        })
      }
    })
    const fullPool = Array.from(allMapSpawns)

    const { pool: activePool, rates: rawRates } = getEncounterPool(props.map, props.cycle, props.weather, activeEvents)
    const activeRates = [...rawRates]

    const visitorIndices = activeRates.map((r, i) => r < 0 ? i : -1).filter(i => i !== -1)
    const nativeIndices = activeRates.map((r, i) => r >= 0 ? i : -1).filter(i => i !== -1)

    const exclusives = weatherCfg?.exclusive ? (Array.isArray(weatherCfg.exclusive) ? weatherCfg.exclusive : Object.keys(weatherCfg.exclusive)) : []
    nativeIndices.forEach(idx => {
      const spId = activePool[idx]
      if (spId) {
        const isExclusive = exclusives.includes(spId)
        if (!isExclusive) {
          activeRates[idx] = (activeRates[idx] || 0) * getWeatherMultiplier(spId, props.weather)
        }
      }
    })

    if (visitorIndices.length > 0) {
      const totalNativeWeight = nativeIndices.reduce((sum, idx) => sum + (activeRates[idx] || 0), 0)
      const visitorQuota = totalNativeWeight / 9
      const sumRelativeWeights = visitorIndices.reduce((sum, idx) => sum + Math.abs(activeRates[idx] || 0), 0)

      visitorIndices.forEach(idx => {
        const relativeWeight = Math.abs(activeRates[idx] || 0) / (sumRelativeWeights || 1)
        activeRates[idx] = visitorQuota * relativeWeight
      })
    }

    const totalRate = activeRates.reduce((sum, r) => sum + r, 0)

    const seenPokedex = gameStore.state.seenPokedex || []
    const caughtPokedex = gameStore.state.pokedex || []

    return fullPool.map((id) => {
      const activeIdx = activePool.indexOf(id)
      const rateVal = activeIdx !== -1 ? (activeRates[activeIdx] || 0) : 0
      const percentage = totalRate > 0 ? (rateVal / totalRate) * 100 : 0

      const wildList = props.map.wild?.[props.cycle] || []
      const originalIdx = wildList.indexOf(id)

      const baseRates = props.map.rates?.[props.cycle] || []
      const totalBaseRate = baseRates.reduce((sum, r) => sum + r, 0)

      let baseRate = 0
      let basePercentage = 0
      if (originalIdx !== -1) {
        baseRate = baseRates[originalIdx] !== undefined ? baseRates[originalIdx] : 10
        basePercentage = totalBaseRate > 0 ? (baseRate / totalBaseRate) * 100 : 0
      }

      const diff = percentage - basePercentage

      let isSeen = seenPokedex.includes(id) || caughtPokedex.includes(id)
      let isCaught = caughtPokedex.includes(id)

      if (uiStore.debugPokedexMode === 'none') {
        isSeen = false
        isCaught = false
      } else if (uiStore.debugPokedexMode === 'caught') {
        isSeen = true
        isCaught = true
      } else if (uiStore.debugPokedexMode === 'seen') {
        isSeen = true
      }
      const data = isSeen ? pokemonDataProvider.getPokemonData(id) : null
      const name = isSeen ? (data?.name || id.toUpperCase()) : 'Desconocido'

      const isVisitor = !!(weatherCfg?.visitors && (
        (!Array.isArray(weatherCfg.visitors) && (weatherCfg.visitors as Record<string, number>)[id]) || 
        (Array.isArray(weatherCfg.visitors) && weatherCfg.visitors.includes(id))
      ))
      const isExclusive = !!(weatherCfg?.exclusive && (
        (!Array.isArray(weatherCfg.exclusive) && (weatherCfg.exclusive as Record<string, number>)[id]) || 
        (Array.isArray(weatherCfg.exclusive) && weatherCfg.exclusive.includes(id))
      ))

      const multiplier = getWeatherMultiplier(id, props.weather)
      const isBuffed = !isVisitor && !isExclusive && multiplier > 1.0
      const isDebuffed = !isVisitor && !isExclusive && multiplier < 1.0 && multiplier > 0
      const isBlocked = multiplier === 0

      const isInCurrentCycle = wildList.includes(id)

      let spawnType = 'Común'
      let statusClass = 'common'
      if (isVisitor) {
        spawnType = 'Visitante'
        statusClass = 'visitor'
      } else if (isExclusive) {
        spawnType = 'Exclusivo'
        statusClass = 'exclusive'
      } else if (isBlocked) {
        spawnType = 'Bloqueado'
        statusClass = 'blocked'
      } else if (!isInCurrentCycle) {
        spawnType = 'Fuera de hora'
        statusClass = 'blocked'
      } else if (isBuffed) {
        spawnType = 'Potenciado'
        statusClass = 'buffed'
      } else if (isDebuffed) {
        spawnType = 'Debilitado'
        statusClass = 'debuffed'
      }

      return {
        id,
        name,
        isSeen,
        isCaught,
        sprite: getAssetUrl(ASSET_TYPES.POKEMON, id),
        percentage,
        baseRate,
        basePercentage,
        diff,
        spawnType,
        statusClass,
        multiplier,
        types: data ? [data.type, data.type2].filter(Boolean) as string[] : [],
        hp: data?.hp || 0,
        atk: data?.atk || 0,
        def: data?.def || 0,
        spa: data?.spa || 0,
        spd: data?.spd || 0,
        spe: data?.spe || 0,
        totalStats: data ? (data.hp + data.atk + data.def + data.spa + data.spd + data.spe) : 0
      }
    }).sort((a, b) => {
      if (a.percentage > 0 && b.percentage === 0) return -1
      if (a.percentage === 0 && b.percentage > 0) return 1
      if (a.percentage > 0 && b.percentage > 0) return b.percentage - a.percentage

      const getInactivePriority = (type: string) => {
        if (type === 'Bloqueado' || type === 'Fuera de hora') return 0
        return 1
      }
      const prioA = getInactivePriority(a.spawnType)
      const prioB = getInactivePriority(b.spawnType)
      if (prioA !== prioB) return prioB - prioA

      return b.totalStats - a.totalStats
    })
  })

  function getWildSpawnTooltip(poke: WildSpawnData) {
    const lines: string[] = []
    lines.push(`Probabilidad Base: ${poke.basePercentage.toFixed(1)}%`)
    if (poke.multiplier !== 1) {
      const change = poke.multiplier > 1 ? 'Aumento por Clima' : 'Reducción por Clima'
      const label = translateWeather(props.weather)
      lines.push(`• ${change}: x${poke.multiplier} (${label})`)
    }
    if (poke.spawnType === 'Visitante') {
      const label = translateWeather(props.weather)
      const diffVal = poke.percentage - poke.basePercentage
      lines.push(`• Pokémon Visitante del clima (${label}): +${diffVal.toFixed(1)}% de probabilidad activa`)
    } else if (poke.spawnType === 'Exclusivo') {
      const label = translateWeather(props.weather)
      const diffVal = poke.percentage - poke.basePercentage
      lines.push(`• Pokémon Exclusivo del clima (${label}): +${diffVal.toFixed(1)}% de probabilidad activa`)
    } else {
      const diffVal = poke.percentage - poke.basePercentage
      if (Math.abs(diffVal) > 0.05) {
        const direction = diffVal > 0 ? 'Aumento' : 'Reducción'
        const detail = diffVal > 0
          ? 'redistribución proporcional al bloquearse, penalizarse o cambiar de hora otros Pokémon'
          : 'redistribución proporcional al inyectarse nuevos Pokémon o potenciarse otros encuentros'
        lines.push(`• ${direction} neto: ${diffVal > 0 ? '+' : ''}${diffVal.toFixed(1)}% (${detail})`)
      }
    }
    const speciesEvent = eventStore.activeEvents.find(e => {
      const cfg = (typeof e.config === 'string' ? JSON.parse(e.config) : e.config) as EventConfig | undefined
      if (cfg?.species) {
        return cfg.species.split(',').map((s: string) => s.trim().toLowerCase()).includes(poke.id)
      }
      return false
    })
    if (speciesEvent) {
      const cfg = (typeof speciesEvent.config === 'string' ? JSON.parse(speciesEvent.config) : speciesEvent.config) as EventConfig | undefined
      if (cfg?.speciesRateMult && cfg.speciesRateMult !== 1) {
        lines.push(`• Evento Activo (${speciesEvent.name}): Multiplicador x${cfg.speciesRateMult}`)
      }
    }

    const globalShiny = eventStore.globalMultipliers?.shiny || 1
    if (globalShiny !== 1) {
      lines.push(`• Evento Shiny Global: x${globalShiny.toFixed(1)} de probabilidad Shiny`)
    }
    const speciesBonuses = eventStore.getSpeciesBonuses(poke.id)
    if (speciesBonuses && speciesBonuses.shiny !== 1) {
      lines.push(`• Evento Shiny Especie: x${speciesBonuses.shiny.toFixed(1)} de probabilidad Shiny`)
    }

    return {
      title: `DETALLES DE PROBABILIDAD`,
      description: lines.join('\n')
    }
  }

  return {
    wildSpawns,
    getWildSpawnTooltip
  }
}

import { ref, computed, toValue, type MaybeRefOrGetter } from 'vue'
import { gameBus } from '@/logic/events/gameBus'
import { awaitAnimation, createTimeline } from '@/logic/utils/gsapHelpers'
import type { useBattleStore } from '@/stores/battle'
import type { Pokemon } from '@/types/pokemon'
import { useBattleSeats } from '@/composables/useBattleSeats'
import { useBattleTweenRegistry } from '@/composables/useBattleTweenRegistry'
import { useGameStore } from '@/stores/game'
import { logger } from '@/logic/utils/logger'

interface CatchSparkle {
  id: string;
  side: string;
  tx: number;
  ty: number;
  tf: number;
  scale: number;
  delay: string;
}

export function useBattleCaptureAnimations(
  battleStore: ReturnType<typeof useBattleStore>,
  enemyRef: MaybeRefOrGetter<Pokemon | null | undefined>
) {
  const caughtPokemonSnapshot = ref<Pokemon | null>(null)
  const isFaintInProgress = ref(false)
  const faintedPokemonSnapshot = ref<(Partial<Pokemon> & { side: string }) | null>(null)
  const catchSparkles = ref<CatchSparkle[]>([])

  const {
    seats,
    getSeat,
    getSeatProperty
  } = useBattleSeats()

  const {
    activeTweens,
    pendingTweenResolvers,
    initTweenRegistryListeners,
    cleanupTweenRegistryListeners,
    awaitTween
  } = useBattleTweenRegistry()

  const playerAnimState = computed(() => seats.value.seat1.entry.animState)
  const enemyAnimState = computed(() => seats.value.seat2.entry.animState)
  const playerActivePokeballId = computed(() => seats.value.seat1.entry.ballId)
  const enemyActivePokeballId = computed(() => seats.value.seat2.entry.ballId)
  const playerCaptureActive = computed(() => seats.value.seat1.entry.isCaptureActive)
  const enemyCaptureActive = computed(() => seats.value.seat2.entry.isCaptureActive)
  const playerIsShaking = computed(() => seats.value.seat1.entry.isShaking)
  const playerIsBlinking = computed(() => seats.value.seat1.entry.isBlinking)
  const enemyIsShaking = computed(() => seats.value.seat2.entry.isShaking)
  const enemyIsBlinking = computed(() => seats.value.seat2.entry.isBlinking)

  const isCaptureSequenceActive = computed(() => 
    Object.values(seats.value).some(seat => 
      seat.entry.isCaptureActive || seat.entry.isAnimatingCapture ||
      seat.exit.isCaptureActive || seat.exit.isAnimatingCapture
    )
  )

  // fallow-ignore-next-line complexity
  const fixPokemonBallTagInSave = (pokemonUid: string) => {
    try {
      const gameStore = useGameStore()
      if (!gameStore?.state) return

      let pokemon = gameStore.state.team.find(p => p && p.uid === pokemonUid)
      if (!pokemon && gameStore.state.box) {
        pokemon = gameStore.state.box.find(p => p && p.uid === pokemonUid)
      }

      if (pokemon) {
        if (!pokemon.tags) {
          pokemon.tags = []
        }
        if (!pokemon.tags.some(t => t.startsWith('ball:'))) {
          pokemon.tags.push('ball:pokeball')
          logger.info('useBattleCaptureAnimations', `Fixed missing ball tag for pokemon uid=${pokemonUid} in save data. Added ball:pokeball.`)
          gameStore.scheduleSave()
        }
      }
    } catch (e) {
      logger.error('useBattleCaptureAnimations', `Failed to fix missing ball tag in save for pokemon uid=${pokemonUid}`, e)
    }
  }

  const triggerCatchSparkles = (side: string) => {
    const tl = createTimeline()
    const count = 12

    tl.to({}, {
      duration: 1.5,
      onStart: () => {
        for (let i = 0; i < count; i++) {
          const direction = i % 2 === 0 ? -1 : 1
          const tx = direction * (60 + Math.random() * 120) 
          const ty = -(60 + Math.random() * 40) 
          const tf = ty + (90 + Math.random() * 40) 
          const scale = 0.5 + Math.random() * 0.8

          catchSparkles.value.push({
            id: `sparkle-${side}-${Temporal.Now.instant().epochMilliseconds}-${i}-${Math.random()}`,
            side,
            tx, ty, tf, scale,
            delay: `${Math.random() * 0.3}s`
          })
        }
      },
      onComplete: () => {
        catchSparkles.value = catchSparkles.value.filter(s => s.side !== side)
      }
    })

    return awaitAnimation(tl)
  }

  const initListeners = () => {
    initTweenRegistryListeners()
  }

  const cleanupListeners = () => {
    cleanupTweenRegistryListeners()
  }

  // fallow-ignore-next-line complexity
  const handleReleaseRequest = async (detail: string | { side?: string, pokemon?: Pokemon }) => {
    const side = typeof detail === 'string' ? detail : (detail?.side || 'player')
    const pokemon = typeof detail === 'object' ? detail?.pokemon : null
    const seat = getSeat(side)
    const slot = seat.entry
    const exitSlot = seat.exit

    if (pokemon?.tags) {
      const ballTag = pokemon.tags.find(t => t.startsWith('ball:'))
      if (ballTag) {
        const id = ballTag.split(':')[1]
        if (id) {
          slot.ballId = id
        } else {
          logger.warn('useBattleCaptureAnimations', `Invalid ball tag format on release for pokemon uid=${pokemon.uid}: "${ballTag}". Falling back to pokeball.`)
          slot.ballId = 'pokeball'
          if (pokemon.uid) fixPokemonBallTagInSave(pokemon.uid)
        }
      } else {
        logger.warn('useBattleCaptureAnimations', `Pokemon uid=${pokemon.uid} has no ball: tag in tags on release. Falling back to pokeball.`)
        slot.ballId = 'pokeball'
        if (pokemon.uid) fixPokemonBallTagInSave(pokemon.uid)
      }
    } else {
      slot.ballId = 'pokeball'
      if (pokemon?.uid) fixPokemonBallTagInSave(pokemon.uid)
    }

    const target = pokemon || (side === 'player' ? battleStore.player : toValue(enemyRef))
    const targetUid = pokemon?.uid || target?.uid || null

    if (exitSlot.pokemonUid === targetUid) {
      exitSlot.animState = null
      exitSlot.pokemonUid = null
      exitSlot.isCaptureActive = false
      exitSlot.isAnimatingCapture = false
    }

    slot.pokemonUid = targetUid
    slot.isCaptureActive = false
    slot.animState = 'releasing'
    gameBus.emit('PLAY_SOUND', 'ballHit')

    const animKey = `${side}-${targetUid || 'active'}`
    await awaitTween(animKey)

    slot.animState = null
    slot.pokemonUid = null
  }

  // fallow-ignore-next-line complexity
  const handleCatchRequest = async (detail: string | { side?: string, ballId?: string, pokemon?: Pokemon }) => {
    const side = typeof detail === 'string' ? detail : (detail?.side || 'enemy')
    const pokemon = typeof detail === 'object' ? (detail as { pokemon?: Pokemon })?.pokemon : null
    const slot = getSeat(side).exit

    if (typeof detail === 'object' && detail?.ballId) {
      slot.ballId = detail.ballId
    } else if (pokemon?.tags) {
      const ballTag = pokemon.tags.find(t => t.startsWith('ball:'))
      if (ballTag) {
        const id = ballTag.split(':')[1]
        if (id) {
          slot.ballId = id
        } else {
          logger.warn('useBattleCaptureAnimations', `Invalid ball tag format on pokemon uid=${pokemon.uid}: "${ballTag}". Falling back to pokeball.`)
          slot.ballId = 'pokeball'
          if (pokemon.uid) fixPokemonBallTagInSave(pokemon.uid)
        }
      } else {
        logger.warn('useBattleCaptureAnimations', `Pokemon uid=${pokemon.uid} has no ball: tag in tags. Falling back to pokeball.`)
        slot.ballId = 'pokeball'
        if (pokemon.uid) fixPokemonBallTagInSave(pokemon.uid)
      }
    } else {
      logger.warn('useBattleCaptureAnimations', `handleCatchRequest called with no ballId and no tags for pokemon. Falling back to pokeball.`)
      slot.ballId = 'pokeball'
      if (pokemon?.uid) fixPokemonBallTagInSave(pokemon.uid)
    }

    const target = pokemon || (side === 'player' ? battleStore.player : toValue(enemyRef))
    caughtPokemonSnapshot.value = target ? { ...target } : null

    const targetUid = pokemon?.uid || target?.uid || null
    slot.pokemonUid = targetUid
    slot.animState = 'catching'
    slot.isCaptureActive = false
    slot.isAnimatingCapture = true
    gameBus.emit('PLAY_SOUND', 'ballHit')

    const animKey = `${side}-${targetUid || 'active'}`
    await awaitTween(animKey)

    slot.animState = 'trapped'
  }

  const handleShakeRequest = (detail: string | { side?: string }): Promise<void> => {
    const side = typeof detail === 'string' ? detail : (detail?.side || 'enemy')
    const seat = getSeat(side)
    if (seat) {
      seat.entry.isShaking = true 
      seat.exit.isShaking = true 
      const tl = createTimeline()
      tl.to({}, { duration: 0.60 })
      tl.add(() => { 
        seat.entry.isShaking = false 
        seat.exit.isShaking = false 
      })
      tl.to({}, { duration: 0.40 })
      return awaitAnimation(tl)
    }
    return Promise.resolve()
  }

  const handleBlinkRequest = (detail: string | { side?: string }): Promise<void> => {
    const side = typeof detail === 'string' ? detail : (detail?.side || 'enemy')
    const seat = getSeat(side)
    if (seat) {
      seat.entry.isBlinking = true
      seat.exit.isBlinking = true
      const tl = createTimeline()
      tl.add(() => {
        gameBus.emit('PLAY_SOUND', 'statusDamage')
      })
      tl.to({}, { duration: 0.48 })
      tl.add(() => { 
        seat.entry.isBlinking = false 
        seat.exit.isBlinking = false 
      })
      return awaitAnimation(tl)
    }
    return Promise.resolve()
  }

  const handleHealRequest = async (detail: string | { side?: string }) => {
    const side = typeof detail === 'string' ? detail : (detail?.side || 'player')
    const seat = getSeat(side)
    if (seat) {
      seat.entry.isHealing = true
      seat.exit.isHealing = true
      const tl = createTimeline()
      tl.add(() => {
        gameBus.emit('PLAY_SOUND', 'heal')
      })
      tl.to({}, { duration: 0.6 })
      tl.add(() => {
        seat.entry.isHealing = false
        seat.exit.isHealing = false
      })
      await awaitAnimation(tl)
    }
  }

  // fallow-ignore-next-line complexity
  const handleFaintAnim = (e: string | { side?: string; isFaint?: boolean; pokemon?: Pokemon } | { detail?: string | { side: string; isFaint?: boolean; pokemon?: Pokemon } }) => {
    if (isFaintInProgress.value) return Promise.resolve() 

    const data = typeof e === 'object' 
      ? (e && 'detail' in e ? e.detail : e) 
      : e
    const side = typeof data === 'string' 
      ? data 
      : (data && 'side' in data ? (data as { side: string }).side : 'enemy')

    const hasTrainer = side === 'player' || 
                       !!battleStore.state?.isTrainer || 
                       !!battleStore.state?.isGym

    faintedPokemonSnapshot.value = side === 'enemy' 
      ? (toValue(enemyRef) ? { ...toValue(enemyRef), side: 'enemy' } : { side: 'enemy' })
      : (battleStore.player ? { ...battleStore.player, side: 'player' } : { side: 'player' })

    isFaintInProgress.value = true
    const tl = createTimeline()
    tl.add(() => {
      gameBus.emit('PLAY_SOUND', 'faint')
    })

    if (hasTrainer) {
      const slot = getSeat(side).exit
      slot.animState = 'catching'
      tl.add(() => {
        gameBus.emit('PLAY_SOUND', 'ballHit')
      })

      const pokemon = side === 'player' ? battleStore.player : toValue(enemyRef)
      slot.pokemonUid = pokemon?.uid || null
      if (pokemon?.tags) {
        const ballTag = pokemon.tags.find(t => t.startsWith('ball:'))
        if (ballTag) {
          const id = ballTag.split(':')[1]
          if (id) {
            slot.ballId = id
          } else {
            logger.warn('useBattleCaptureAnimations', `Invalid ball tag format during faint for pokemon uid=${pokemon?.uid}: "${ballTag}". Falling back to pokeball.`)
            slot.ballId = 'pokeball'
            if (pokemon?.uid) fixPokemonBallTagInSave(pokemon.uid)
          }
        } else {
          logger.warn('useBattleCaptureAnimations', `Pokemon uid=${pokemon?.uid} has no ball: tag in its tags during faint animation. Falling back to pokeball.`)
          slot.ballId = 'pokeball'
          if (pokemon?.uid) fixPokemonBallTagInSave(pokemon.uid)
        }
      } else {
        logger.warn('useBattleCaptureAnimations', `handleFaintAnim called with no pokeball tag on pokemon uid=${pokemon?.uid}. Falling back to pokeball.`)
        slot.ballId = 'pokeball'
        if (pokemon?.uid) fixPokemonBallTagInSave(pokemon.uid)
      }

      tl.to({}, {
        duration: 0.5,
        onComplete: () => {
          slot.animState = 'trapped'
        }
      })
      tl.to({}, {
        duration: 0.5,
        onComplete: () => {
          isFaintInProgress.value = false 
          faintedPokemonSnapshot.value = null 
          slot.pokemonUid = null
          slot.animState = null
        }
      })
    } else {
      tl.to({}, {
        duration: 1.3,
        onComplete: () => {
          isFaintInProgress.value = false 
          faintedPokemonSnapshot.value = null 
        }
      })
    }

    return awaitAnimation(tl)
  }

  const playCatchCelebration = (side: string) => {
    const seat = getSeat(side)
    if (seat) {
      seat.entry.isCaptureActive = true
      seat.exit.isCaptureActive = true
    }
    const tl = createTimeline()
    tl.to({}, {
      duration: 1.5,
      onStart: () => {
        gameBus.emit('PLAY_SOUND', 'caught')
        triggerCatchSparkles(side)
      }
    })
    return awaitAnimation(tl)
  }

  const playBallFadeOut = async (side: string) => {
    const seat = getSeat(side)
    if (!seat) return

    seat.entry.isCaptureActive = false 
    seat.exit.isCaptureActive = false 
    seat.entry.animState = null
    seat.exit.animState = null

    await awaitTween(`ball-fadeout-${side}`)

    seat.entry.isAnimatingCapture = false
    seat.exit.isAnimatingCapture = false
    caughtPokemonSnapshot.value = null
  }

  const resetCaptureStates = () => {
    caughtPokemonSnapshot.value = null
    isFaintInProgress.value = false
    faintedPokemonSnapshot.value = null
    activeTweens.clear()
    pendingTweenResolvers.clear()

    Object.keys(seats.value).forEach(side => {
      const seat = seats.value[side]
      if (seat) {
        seat.entry.animState = null
        seat.entry.ballId = 'pokeball'
        seat.entry.isCaptureActive = false
        seat.entry.isAnimatingCapture = false
        seat.entry.isShaking = false
        seat.entry.isBlinking = false

        seat.exit.animState = null
        seat.exit.ballId = 'pokeball'
        seat.exit.isCaptureActive = false
        seat.exit.isAnimatingCapture = false
        seat.exit.isShaking = false
        seat.exit.isBlinking = false
      }
    })
  }

  const getPokemonAnimState = (side: string, pokemon?: Pokemon | null) => getSeatProperty(side, pokemon, 'animState', null, battleStore.player?.uid, battleStore.enemy?.uid)
  const getPokemonBallId = (side: string, pokemon?: Pokemon | null) => getSeatProperty(side, pokemon, 'ballId', 'pokeball', battleStore.player?.uid, battleStore.enemy?.uid)
  const getPokemonCaptureActive = (side: string, pokemon?: Pokemon | null) => getSeatProperty(side, pokemon, 'isCaptureActive', false, battleStore.player?.uid, battleStore.enemy?.uid)
  const getPokemonIsShaking = (side: string, pokemon?: Pokemon | null) => getSeatProperty(side, pokemon, 'isShaking', false, battleStore.player?.uid, battleStore.enemy?.uid)
  const getPokemonIsBlinking = (side: string, pokemon?: Pokemon | null) => getSeatProperty(side, pokemon, 'isBlinking', false, battleStore.player?.uid, battleStore.enemy?.uid)
  const getPokemonIsHealing = (side: string, pokemon?: Pokemon | null) => getSeatProperty(side, pokemon, 'isHealing', false, battleStore.player?.uid, battleStore.enemy?.uid)

  return {
    caughtPokemonSnapshot,
    isFaintInProgress,
    faintedPokemonSnapshot,
    catchSparkles,
    seats,
    playerAnimState,
    enemyAnimState,
    playerActivePokeballId,
    enemyActivePokeballId,
    playerCaptureActive,
    enemyCaptureActive,
    playerIsShaking,
    playerIsBlinking,
    enemyIsShaking,
    enemyIsBlinking,
    isCaptureSequenceActive,
    triggerCatchSparkles,
    handleReleaseRequest,
    handleCatchRequest,
    handleShakeRequest,
    handleBlinkRequest,
    handleHealRequest,
    handleFaintAnim,
    playCatchCelebration,
    playBallFadeOut,
    resetCaptureStates,
    getPokemonAnimState,
    getPokemonBallId,
    getPokemonCaptureActive,
    getPokemonIsShaking,
    getPokemonIsBlinking,
    getPokemonIsHealing,
    awaitTween,
    initListeners,
    cleanupListeners
  }
}

import { ref } from 'vue'
import type { Pokemon } from '@/types/pokemon'

export interface AnimSlotState {
  animState: 'catching' | 'trapped' | 'releasing' | null;
  ballId: string;
  isCaptureActive: boolean;
  isAnimatingCapture: boolean;
  isShaking: boolean;
  isBlinking: boolean;
  isHealing?: boolean;
  pokemonUid?: string | null;
}

export interface SeatState {
  entry: AnimSlotState;
  exit: AnimSlotState;
}

/**
 * Composable dedicated exclusively to managing and querying battle seats.
 * Adheres to the 4-seat architecture defined in the battle mechanics manual.
 */
export function useBattleSeats() {
  const createDefaultSlot = (): AnimSlotState => ({
    animState: null,
    ballId: 'pokeball',
    isCaptureActive: false,
    isAnimatingCapture: false,
    isShaking: false,
    isBlinking: false,
    isHealing: false,
    pokemonUid: null
  })

  const createDefaultSeat = (): SeatState => ({
    entry: createDefaultSlot(),
    exit: createDefaultSlot()
  })

  const seats = ref<{
    seat1: SeatState;
    seat2: SeatState;
    seat3: SeatState;
    seat4: SeatState;
    [key: string]: SeatState;
  }>({
    seat1: createDefaultSeat(),
    seat2: createDefaultSeat(),
    seat3: createDefaultSeat(),
    seat4: createDefaultSeat()
  })

  const resetSeats = () => {
    seats.value.seat1 = createDefaultSeat()
    seats.value.seat2 = createDefaultSeat()
    seats.value.seat3 = createDefaultSeat()
    seats.value.seat4 = createDefaultSeat()
  }

  const getSeatKey = (side: string): string => {
    if (side === 'player') return 'seat1'
    if (side === 'enemy') return 'seat2'
    if (side === 'ally') return 'seat3'
    if (side === 'enemy2') return 'seat4'
    return side
  }

  const getSeat = (side: string): SeatState => {
    const key = getSeatKey(side)
    if (!seats.value[key]) {
      seats.value[key] = createDefaultSeat()
    }
    return seats.value[key]
  }

  const getSeatProperty = <K extends keyof AnimSlotState>(
    side: string,
    pokemon: Pokemon | null | undefined,
    prop: K,
    fallback: AnimSlotState[K],
    activePlayerUid?: string | null,
    activeEnemyUid?: string | null
  ): AnimSlotState[K] => {
    if (!pokemon) return fallback
    const seat = getSeat(side)
    if (pokemon.uid && seat.entry.pokemonUid === pokemon.uid) return seat.entry[prop]
    if (pokemon.uid && seat.exit.pokemonUid === pokemon.uid) return seat.exit[prop]

    const isActive = side === 'player'
      ? (activePlayerUid === pokemon.uid)
      : (activeEnemyUid === pokemon.uid)

    const activeSlot = isActive ? seat.entry : seat.exit
    return activeSlot[prop] !== undefined ? activeSlot[prop] : fallback
  }

  return {
    seats,
    resetSeats,
    getSeatKey,
    getSeat,
    getSeatProperty
  }
}

import { ref, computed, watch, onUnmounted } from 'vue'
import { useCombatShadowStore } from '@/stores/combatShadows'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import { POKEMON_FEET_DATABASE } from '@/data/pokemonFeetDatabase'
import { ANIMATED_SPRITE_DATABASE } from '@/data/animatedSpriteDatabase'

import { WORLD_CONSTANTS } from '@/logic/combat/spatialCoordinator'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import type { Pokemon } from '@/types/pokemon'
import { logger } from '@/logic/utils/logger'

function resolveAnimatedKey(pokemonId: string | number | null | undefined, isBack = false): string | null {
  if (!pokemonId) return null
  const strId = String(pokemonId).toLowerCase()
  const match = strId.match(/^(\d+)(.*)$/)
  if (!match) return null
  const numId = match[1]!
  const suffix = match[2]!
  const backSuffix = isBack ? '_back' : ''

  const cand = `${numId}i${suffix}`
  if (ANIMATED_SPRITE_DATABASE[`${cand}${backSuffix}`]) {
    return `${cand}${backSuffix}`
  }
  if (ANIMATED_SPRITE_DATABASE[cand]) {
    return cand
  }

  // Fallback to check candidates without 'i'
  const rawCand = `${numId}${suffix}`
  if (ANIMATED_SPRITE_DATABASE[`${rawCand}${backSuffix}`]) {
    return `${rawCand}${backSuffix}`
  }
  if (ANIMATED_SPRITE_DATABASE[rawCand]) {
    return rawCand
  }

  return null
}

function checkAnimated(pokemonId: string | null | undefined): boolean {
  if (!pokemonId) return false
  return !!resolveAnimatedKey(pokemonId, false) || !!resolveAnimatedKey(pokemonId, true)
}

function getFinalSpriteUrl(pokemonId: string | number, isShiny: boolean, isBack: boolean): string {
  const isAnim = checkAnimated(String(pokemonId))
  const url = getAssetUrl(ASSET_TYPES.POKEMON, pokemonId, { isShiny, isBack, isAnimated: isAnim })
  if (isAnim && url) {
    return url.replace(/\/(\d+)([^/]*)\.webp$/i, (_: string, num: string, suff: string) => `/${num}i${suff}.webp`)
  }
  return url
}

const { ENTITY_SIZE_PLAYER, ENTITY_SIZE_ENEMY } = WORLD_CONSTANTS

interface Position {
  x: number
  y: number
}

export function isFlying(pokemon: Pokemon | null | undefined): boolean {
  if (!pokemon || !pokemon.id) return false
  const data = pokemonDataProvider.getPokemonData(pokemon.id)
  if (!data) return false
  if (data.isFloating !== undefined) return data.isFloating

  const types: string[] = []
  if (data.type) types.push(data.type.toLowerCase())
  if (data.type2) types.push(data.type2.toLowerCase())
  return types.includes('flying')
}

export function useBattleShadows() {
  const shadowStore = useCombatShadowStore()

  const getShadowWidth = (pokemonId: string | number, isBack: boolean): string => {
    const animKey = resolveAnimatedKey(pokemonId, isBack) || resolveAnimatedKey(pokemonId, !isBack)
    const meta = animKey ? ANIMATED_SPRITE_DATABASE[animKey] : null
    const bodyRadius = meta?.bodyRadius ?? 0.4
    return `${bodyRadius * 250}%` // bodyRadius * 2.5 (representing radius + 25%)
  }


  // Claves únicas para las sombras en el store
  const currentPlayerShadowKey = ref<string | null>(null)
  const currentEnemyShadowKey = ref<string | null>(null)

  const lastEnemyShadowId = ref<string | null>(null)
  const lastPlayerShadowId = ref<string | null>(null)

  // Coordenadas de "suelo" persistentes para evitar saltos
  const stableEnemyGroundY = ref('75%')
  const stablePlayerGroundY = ref('75%')

  const enemyGroundY = computed(() => stableEnemyGroundY.value)
  const playerGroundY = computed(() => stablePlayerGroundY.value)

  function getStableShadowId(pokemon: Pokemon | null, side: string): string | null {
    if (!pokemon) return null
    if (pokemon.uid) return `shadow_${pokemon.uid}`
    return `${side}_${pokemon.id}`
  }





  // Sincronizar visibilidad y posición de la sombra enemiga
  const syncEnemyShadow = async (visible: boolean, data: Pokemon | null, pos: Position, animState: unknown) => {
    const shadowId = getStableShadowId(data, 'enemy')

    // Inicializar coordenadas inmediatamente si el asiento está ocupado por un pokemon
    if (data) {
      const url = getFinalSpriteUrl(data.id, !!data.isShiny, false)
      let dbKey = url || ''
      const base = import.meta.env.BASE_URL || '/'
      if (base !== '/' && dbKey.startsWith(base)) {
        dbKey = dbKey.slice(base.length - 1)
      }
      try {
        dbKey = decodeURIComponent(dbKey)
      } catch (_e) {
        // Fallback to original key if malformed
      }
      const cached = dbKey ? POKEMON_FEET_DATABASE[dbKey] : null
      if (!cached) {
        throw new Error(`[PokemonFeetDatabase] Sprite key "${dbKey}" not found in POKEMON_FEET_DATABASE. Did you forget to compile assets? Run "npm run assets:convert".`)
      }
      stableEnemyGroundY.value = '75%'
    }

    // Limpieza de sombras huérfanas si el ID cambia (evita duplicados al capturar/cambiar)
    if (lastEnemyShadowId.value && lastEnemyShadowId.value !== shadowId) {
      if (lastEnemyShadowId.value) shadowStore.hideShadow(lastEnemyShadowId.value)
    }
    lastEnemyShadowId.value = shadowId
    currentEnemyShadowKey.value = shadowId

    // Ocultar sombra si está en cualquier estado de transición de Poké Ball (energía)
    const isEnergyState = !!animState 
    if (!visible || !data || data.hp <= 0 || isEnergyState) {
      if (shadowId) shadowStore.hideShadow(shadowId)
      return
    }

    if (shadowId) {
      await shadowStore.requestShadow(shadowId, {
        side: 'enemy',
        entityX: pos.x,
        entityY: pos.y,
        entitySize: ENTITY_SIZE_ENEMY,
        isFlying: isFlying(data),
        spriteUrl: data ? getFinalSpriteUrl(data.id, !!data.isShiny, false) : '',
        width: data ? getShadowWidth(data.id, false) : '100%',
        visible: true
      })
    }
  }

  // Sincronizar visibilidad y posición de la sombra del jugador
  const syncPlayerShadow = async (pokemon: Pokemon | null, pos: Position, animState: unknown) => {
    const shadowId = getStableShadowId(pokemon, 'player')

    // Inicializar coordenadas inmediatamente si el asiento está ocupado por un pokemon
    if (pokemon) {
      const url = getFinalSpriteUrl(pokemon.id, !!pokemon.isShiny, true)
      let dbKey = url || ''
      const base = import.meta.env.BASE_URL || '/'
      if (base !== '/' && dbKey.startsWith(base)) {
        dbKey = dbKey.slice(base.length - 1)
      }
      try {
        dbKey = decodeURIComponent(dbKey)
      } catch (_e) {
        // Fallback to original key if malformed
      }
      const cached = dbKey ? POKEMON_FEET_DATABASE[dbKey] : null
      if (!cached) {
        throw new Error(`[PokemonFeetDatabase] Sprite key "${dbKey}" not found in POKEMON_FEET_DATABASE. Did you forget to compile assets? Run "npm run assets:convert".`)
      }
      stablePlayerGroundY.value = '75%'
    }

    // Limpieza de sombras huérfanas
    if (lastPlayerShadowId.value && lastPlayerShadowId.value !== shadowId) {
      if (lastPlayerShadowId.value) shadowStore.hideShadow(lastPlayerShadowId.value)
    }
    lastPlayerShadowId.value = shadowId
    currentPlayerShadowKey.value = shadowId

    // Ocultar sombra durante transiciones de energía
    const isEnergyState = !!animState
    if (!pokemon || pokemon.hp <= 0 || isEnergyState) {
      if (shadowId) shadowStore.hideShadow(shadowId)
      return
    }

    if (shadowId) {
      await shadowStore.requestShadow(shadowId, {
        side: 'player',
        entityX: pos.x,
        entityY: pos.y,
        entitySize: ENTITY_SIZE_PLAYER,
        isFlying: isFlying(pokemon),
        spriteUrl: pokemon ? getFinalSpriteUrl(pokemon.id, !!pokemon.isShiny, true) : '',
        width: getShadowWidth(pokemon.id, true),
        visible: true
      })
    }
  }

  // Ground line is fixed at 75% — watchers based on shadow.feetY were removed because
  // feetY represents the foot position WITHIN the sprite, not the ground line in the entity box.
  watch(currentEnemyShadowKey, (val) => {
    if (!val) stableEnemyGroundY.value = '75%'
  })
  watch(currentPlayerShadowKey, (val) => {
    if (!val) stablePlayerGroundY.value = '75%'
  })

  const preloadTeamFeet = async (team: Pokemon[], side: string) => {
    if (!team || !Array.isArray(team)) return
    const tasks = team.map(p => {
      const isBack = side === 'player'
      const url = getFinalSpriteUrl(p.id, !!p.isShiny, isBack)
      return shadowStore.detectFeetPoints(url)
    })
    return Promise.all(tasks)
  }

  const preloadCombatCoords = async (
    p1Data: Pokemon | null, 
    p2Data: Pokemon | null, 
    p1Position: Position, 
    p2Position: Position, 
    p1Team: Pokemon[], 
    p2Team: Pokemon[]
  ) => {
    const tasks = []

    // Pre-cargar puntos de pies de TODOS los equipos para evitar el lag de la "primera vez"
    if (p1Team) tasks.push(preloadTeamFeet(p1Team, 'player'))
    if (p2Team) tasks.push(preloadTeamFeet(p2Team, 'enemy'))

    if (p1Data) {
      const shadowId = getStableShadowId(p1Data, 'player')
      currentPlayerShadowKey.value = shadowId
      const url = getFinalSpriteUrl(p1Data.id, !!p1Data.isShiny, true)
      if (shadowId) {
        tasks.push(shadowStore.requestShadow(shadowId, {
          side: 'player',
          entityX: p1Position.x,
          entityY: p1Position.y,
          entitySize: ENTITY_SIZE_PLAYER,
          isFlying: isFlying(p1Data),
          spriteUrl: url,
          width: getShadowWidth(p1Data.id, true),
          visible: true
        }))
      }
    }

    if (p2Data) {
      const shadowId = getStableShadowId(p2Data, 'enemy')
      currentEnemyShadowKey.value = shadowId
      const url = getFinalSpriteUrl(p2Data.id, !!p2Data.isShiny, false)
      if (shadowId) {
        tasks.push(shadowStore.requestShadow(shadowId, {
          side: 'enemy',
          entityX: p2Position.x,
          entityY: p2Position.y,
          entitySize: ENTITY_SIZE_ENEMY,
          isFlying: isFlying(p2Data),
          spriteUrl: url,
          width: getShadowWidth(p2Data.id, false),
          visible: true
        }))
      }
    }
    if (tasks.length > 0) {
      await Promise.all(tasks).catch(err => logger.warn('Shadow', `Preloading failed: ${(err as Error).message}`))
    }
  }

  onUnmounted(() => {
    shadowStore.clearAll()
  })

  return {
    currentPlayerShadowKey,
    currentEnemyShadowKey,
    enemyGroundY,
    playerGroundY,
    syncEnemyShadow,
    syncPlayerShadow,
    preloadCombatCoords,
    getStableShadowId
  }
}

import { ref } from 'vue'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'

export function useBattleVisuals() {
  const canvasRef = ref<HTMLCanvasElement | null>(null)
  const containerRef = ref<HTMLElement | null>(null)

  const getHpPct = (cur: number, max: number) => (cur / max) * 100
  const getHpClass = (pct: number) => {
    if (pct > 50) return 'hp-high'
    if (pct > 25) return 'hp-mid'
    return 'hp-low'
  }

  const getHpColor = (pct: number) => {
    if (pct > 50) return '#4ade80'
    if (pct > 20) return '#facc15'
    return '#f87171'
  }

  const getSprite = (id: string, isShiny: boolean, isBack = false) => {
    return getAssetUrl(ASSET_TYPES.POKEMON, id, { isShiny, isBack })
  }

  const redrawBackground = (isBattleActive: boolean, locationId: string, cycle: string) => {
    if (isBattleActive && typeof window.drawBattleBackground === 'function') {
      const arena = containerRef.value
      const canvas = canvasRef.value
      if (arena && canvas) {
        canvas.width = arena.offsetWidth
        canvas.height = arena.offsetHeight
        window.drawBattleBackground(locationId || 'wild', cycle)
      }
    }
  }

  const getStatusIcon = (s: string) => {
    const icons: Record<string, string> = { 
      burn: '🔥', poison: '☠️', paralyze: '⚡', sleep: '💤', freeze: '🧊' 
    }
    return icons[s] || ''
  }

  const getGenderText = (g: string) => {
    const texts: Record<string, string> = { M: '♂', F: '♀' }
    return texts[g] || ''
  }

  const getGenderCls = (g: string) => {
    const classes: Record<string, string> = { M: 'gender-male', F: 'gender-female' }
    return classes[g] || 'gender-none'
  }

  return {
    canvasRef,
    containerRef,
    getHpPct,
    getHpClass,
    getHpColor,
    getSprite,
    redrawBackground,
    getStatusIcon,
    getGenderText,
    getGenderCls
  }
}

import { computed, toValue, type MaybeRefOrGetter } from 'vue'
import type { useBattleStore } from '@/stores/battle'
import { STATUS_TOOLTIP_MAP, STAT_EMOJI_MAP, STATUS_EMOJI_MAP, STATUS_NAME_MAP } from '@/logic/battle/battleUiUtils'
import { getMechanicalWeather, WEATHER_MECHANICAL, WEATHER_UI_METADATA, WEATHER_VISUAL_METADATA, type WeatherMechanical } from '@/logic/weather/weatherRegistry'
import { getDayCycle } from '@/logic/utils/timeUtils'
import { ABILITY_DATA } from '@/data/abilities'
import { getStatMultiplier } from '@/logic/battle/battleEngine'
import type { Pokemon } from '@/types/pokemon'
import { VOLATILE_STATUS_LIST, CYCLE_WEATHER_DEFAULTS } from '@/data/volatileStatusMap'

function formatAbilityDescription(desc: string): string {
  const lines: string[] = []

  const boostRegexes = [
    /aumenta la velocidad/i,
    /aumenta el ataque/i,
    /aumenta la defensa/i,
    /aumenta la precisión/i,
    /potencia el/i,
    /sube el/i,
    /potencia los/i,
    /aumenta.*un\s*\d+%/i
  ]

  const debuffRegexes = [
    /reduce/i,
    /baja/i,
    /debilita/i,
    /pierde hp/i
  ]

  const blockRegexes = [
    /evita/i,
    /inmunidad/i,
    /impide/i,
    /protege/i
  ]

  if (/[▲▼⚡🚫•]/u.test(desc)) {
    return desc
  }

  const sentences = desc.split(/(?<=[.!?])\s+/)
  for (const sentence of sentences) {
    const trimmed = sentence.trim()
    if (!trimmed) continue

    let matched = false
    for (const rx of blockRegexes) {
      if (rx.test(trimmed)) {
        lines.push(`🚫 ${trimmed}`)
        matched = true
        break
      }
    }
    if (matched) continue

    for (const rx of boostRegexes) {
      if (rx.test(trimmed)) {
        lines.push(`▲ ${trimmed}`)
        matched = true
        break
      }
    }
    if (matched) continue

    for (const rx of debuffRegexes) {
      if (rx.test(trimmed)) {
        lines.push(`▼ ${trimmed}`)
        matched = true
        break
      }
    }
    if (matched) continue

    lines.push(`• ${trimmed}`)
  }

  return lines.join('\n')
}

export interface UnifiedStatus {
  id: string
  emoji: string
  title: string
  description: string
  count?: number | string
  class: string
  isBoosted?: boolean
  stageValue?: number
}

export function useCombatantStatus(
  pokemonRef: MaybeRefOrGetter<Pokemon | null | undefined>,
  battleStore: ReturnType<typeof useBattleStore>,
  isPlayer: MaybeRefOrGetter<boolean>
) {
  const p = computed(() => toValue(pokemonRef))
  const isPlayerVal = computed(() => toValue(isPlayer))

  const activeStages = computed(() => {
    const s = isPlayerVal.value ? battleStore.playerStages : battleStore.enemyStages
    if (!s) return []

    const results = []
    const keys = ['atk', 'def', 'spa', 'spd', 'spe', 'acc', 'eva']

    for (const key of keys) {
      const val = (s as Record<string, number | undefined>)[key] || 0
      if (val !== 0) {
        const config = (STAT_EMOJI_MAP as Record<string, { icon: string; name: string }>)[key] || { icon: '❓', name: key }
        const mult = getStatMultiplier(val || 0)
        const pct = Math.round((mult - 1) * 100)
        const pctText = pct > 0 ? `+${pct}%` : `${pct}%`

        results.push({
          key,
          val,
          icon: config.icon,
          text: `${config.name} ${val > 0 ? '↑' : '↓'}${Math.abs(val)} (${pctText})`
        })
      }
    }

    return results
  })

  const volatileStatuses = computed(() => {
    const list = []
    const target = p.value
    if (!target) return []

    // 0. Habilidad Base (MANDATORIA)
    if (target.ability) {
      const ab = target.ability
      const weather = battleStore.state?.weather?.type
      const mechWeather = getMechanicalWeather(weather)
      const cycle = getDayCycle()

      let isAbBoosted = false
      const abEntry = (ABILITY_DATA as Record<string, { desc: string }>)[ab] || Object.entries(ABILITY_DATA).find(([k]) => k.toLowerCase() === ab.toLowerCase())?.[1]
      const abDescription = abEntry?.desc || 'Sin descripción disponible.'

      const isSunActive = mechWeather === WEATHER_MECHANICAL.SUN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'day' || cycle === 'morning'))
      const isRainActive = mechWeather === WEATHER_MECHANICAL.RAIN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'night' || cycle === 'dusk'))

      let statusMsg = ''
      if (ab === 'Clorofila' && isSunActive) { isAbBoosted = true; statusMsg = ' (Activa por Sol/Día)' }
      if (ab === 'Nado rápido' && isRainActive) { isAbBoosted = true; statusMsg = ' (Activa por Lluvia/Noche)' }
      if (ab === 'Ímpetu arena' && mechWeather === WEATHER_MECHANICAL.SANDSTORM) { isAbBoosted = true; statusMsg = ' (Activa por Arena)' }
      if (ab === 'Quitanieves' && (mechWeather === WEATHER_MECHANICAL.SNOW || mechWeather === WEATHER_MECHANICAL.HAIL)) { isAbBoosted = true; statusMsg = ' (Activa por Nieve)' }

      let formattedDesc = abDescription
      const lowerAb = ab.toLowerCase()
      if (lowerAb === 'espesura') {
        formattedDesc = '▲ Potencia Planta (+50%) a 1/3 HP o menos'
      } else if (lowerAb === 'mar llamas') {
        formattedDesc = '▲ Potencia Fuego (+50%) a 1/3 HP o menos'
      } else if (lowerAb === 'torrente') {
        formattedDesc = '▲ Potencia Agua (+50%) a 1/3 HP o menos'
      } else if (lowerAb === 'enjambre') {
        formattedDesc = '▲ Potencia Bicho (+50%) a 1/3 HP o menos'
      } else if (lowerAb === 'clorofila') {
        formattedDesc = `▲ Velocidad duplica (x2.0) bajo Sol${statusMsg}`
      } else if (lowerAb === 'nado rápido') {
        formattedDesc = `▲ Velocidad duplica (x2.0) bajo Lluvia${statusMsg}`
      } else if (lowerAb === 'lluvia ligera') {
        formattedDesc = `▲ Velocidad duplica (x2.0) bajo Lluvia/Noche${statusMsg}`
      } else if (lowerAb === 'ráfaga') {
        formattedDesc = '▲ Velocidad triplica (x3.0) a 1/3 HP o menos'
      } else if (lowerAb === 'poder solar') {
        formattedDesc = '▲ At. Especial sube (+50%) bajo Sol\n▼ Pierde HP por turno bajo Sol'
      } else if (lowerAb === 'gloria' || lowerAb === 'agallas') {
        formattedDesc = '▲ Ataque sube (+50%) con problema de estado'
      } else if (lowerAb === 'levitación') {
        formattedDesc = '🚫 Inmune a ataques tipo Tierra'
      } else if (lowerAb === 'absorbe fuego') {
        formattedDesc = '🚫 Inmune a ataques tipo Fuego\n▲ Potencia ataques de Fuego al recibir uno'
      } else if (lowerAb === 'absorbe agua') {
        formattedDesc = '🚫 Inmune a ataques tipo Agua\n▲ Recupera 25% HP al recibir uno'
      } else if (lowerAb === 'absorbe voltio') {
        formattedDesc = '🚫 Inmune a ataques tipo Eléctrico\n▲ Recupera 25% HP al recibir uno'
      } else {
        formattedDesc = formatAbilityDescription(abDescription)
      }

      const abText = `HABILIDAD - ${ab.toUpperCase()}:\n${formattedDesc}`

      list.push({ 
        icon: '🧠', 
        text: abText,
        isBoosted: isAbBoosted
      })
    }

    // 1. Estados Propios del Pokémon
    for (const def of VOLATILE_STATUS_LIST) {
      const val = target[def.prop as keyof Pokemon];
      if (!val) continue;

      if (def.isCounter) {
        const num = Number(val);
        if (num > 0) {
          let customText = `${def.text} (${num}t).`;
          if (def.prop === 'substitute') {
            customText = `SUSTITUTO: Un señuelo de ${num} HP recibe el daño.`;
          } else if (def.prop === 'perishSongCount') {
            customText = `CANTO MORTAL: El Pokémon caerá en ${num} turnos.`;
          }
          list.push({ icon: def.icon, text: customText });
        }
      } else {
        list.push({ icon: def.icon, text: def.text });
      }
    }


    // 2. Efectos de Campo (Side-based)
    const stages = isPlayerVal.value ? battleStore.playerStages : battleStore.enemyStages
    if (stages) {
      if (stages.reflect > 0) list.push({ icon: '🪞', text: `REFLEJO: Reduce el daño físico (${stages.reflect}t).` })
      if (stages.lightScreen > 0) list.push({ icon: '💡', text: `PANTALLA LUZ: Reduce el daño especial (${stages.lightScreen}t).` })
      if (stages.safeguard > 0) list.push({ icon: '🛡️', text: `VELO SAGRADO: Protege contra estados (${stages.safeguard}t).` })
      if (stages.mist > 0) list.push({ icon: '🌫️', text: `NEBLINA: Protege contra reducción de stats (${stages.mist}t).` })
      if (stages.spikes > 0) list.push({ icon: '📍', text: `PÚAS: Daña a los Pokémon que entran al campo (${stages.spikes} capas).` })
    }

    // 3. Clima y Ciclo
    const weather = battleStore.state?.weather
    const types: string[] = []
    if (target.type) types.push(target.type.toLowerCase())
    if (target.type2) types.push(target.type2.toLowerCase())
    const moveTypes = (target.moves || []).map((m) => (m?.type || '').toLowerCase())
    const moveNames = (target.moves || []).map((m) => (m?.name || '').toLowerCase())
    const cycle = getDayCycle()

    let weatherAffects = false
    if (weather && weather.type !== 'clear') {
      const mechWeather = getMechanicalWeather(weather.type)
      const visualWeather = weather.type

      if (['sandstorm', 'hail', 'fog'].includes(mechWeather)) weatherAffects = true
      if (['blizzard', 'coldwave', 'fog'].includes(visualWeather)) weatherAffects = true

      if (mechWeather === 'sun' && (types.includes('fire') || types.includes('water') || types.includes('grass'))) weatherAffects = true
      if (mechWeather === 'rain' && (types.includes('fire') || types.includes('water') || types.includes('electric'))) weatherAffects = true
      if (mechWeather === 'snow' && types.includes('ice')) weatherAffects = true
      if ((mechWeather === 'wind' || visualWeather === 'strong_winds') && (types.includes('flying') || target.isFloating)) weatherAffects = true

      const sunMoves = ['synthesis', 'síntesis', 'morning sun', 'sol beam', 'rayo solar', 'solar beam', 'solar blade', 'cuchilla solar']
      const rainMoves = ['thunder', 'trueno', 'hurricane', 'vendaval', 'weather ball']
      const snowMoves = ['blizzard', 'ventisca', 'aurora veil', 'velo aurora', 'cold-snap']

      if (!weatherAffects) {
        if (mechWeather === 'sun' && moveNames.some(n => sunMoves.includes(n))) weatherAffects = true
        if (mechWeather === 'rain' && moveNames.some(n => rainMoves.includes(n))) weatherAffects = true
        if (mechWeather === 'snow' && moveNames.some(n => snowMoves.includes(n))) weatherAffects = true
      }
    }

    let cycleAffects = false
    if (cycle === 'morning' || cycle === 'day') {
      const sunMoves = ['synthesis', 'síntesis', 'morning sun', 'sol beam', 'rayo solar', 'solar beam', 'solar blade', 'cuchilla solar']
      if (types.includes('fire') || types.includes('water') || moveTypes.includes('fire') || moveTypes.includes('water') || moveNames.some((n) => sunMoves.includes(n))) {
        cycleAffects = true
      }
    } else if (cycle === 'dusk' || cycle === 'night') {
      if (types.includes('water') || moveTypes.includes('water')) {
        cycleAffects = true
      }
    }

    if (battleStore.state?.isGym) {
      return list
    }

    if (weather && weather.type !== 'clear' && weatherAffects) {
      const visualType = weather.visual || weather.type
      const mechType = getMechanicalWeather(weather.type)
      const config = WEATHER_VISUAL_METADATA[visualType] || WEATHER_UI_METADATA[mechType as WeatherMechanical]
      if (config) {
        list.push({ icon: config.icon, text: `${config.label}: ${config.description}` })
      }
    } else if (cycleAffects) {
      const cycleData = (CYCLE_WEATHER_DEFAULTS as Record<string, { icon: string; label: string; desc: string }>)[cycle]
      if (cycleData) {
        list.push({ icon: cycleData.icon, text: `HORARIO (${cycleData.label}): ${cycleData.desc}` })
      }
    }

    return list
  })

  const unifiedStatuses = computed<UnifiedStatus[]>(() => {
    const list: UnifiedStatus[] = []
    const target = p.value
    if (!target) return []

    // 1. Estado Primario
    if (target.status) {
      const s = target.status.toLowerCase()
      const emoji = (STATUS_EMOJI_MAP as Record<string, string>)[s]
      const title = (STATUS_NAME_MAP as Record<string, string>)[s]
      const description = (STATUS_TOOLTIP_MAP as Record<string, string>)[s]

      if (!emoji || !title || !description) {
        throw new Error(
          `[STATUS MATCH ERROR] Missing mapping for status "${s}". Emoji: ${emoji}, Title: ${title}, Description: ${description}`
        )
      }

      list.push({
        id: `primary-${s}`,
        emoji,
        title,
        description,
        count: s === 'sleep' ? target.sleepTurns : undefined,
        class: s
      })
    }

    // 2. Estados Volátiles
    volatileStatuses.value.forEach((vs, idx) => {
      const text = vs.text || ''
      const firstColonIndex = text.indexOf(':')
      const title = firstColonIndex !== -1 ? text.slice(0, firstColonIndex).trim() : ''
      const description = firstColonIndex !== -1 ? text.slice(firstColonIndex + 1).trim() : text
      list.push({
        id: `volatile-${idx}`,
        emoji: vs.icon,
        title: title || '',
        description: description || text || '',
        class: 'volatile',
        isBoosted: vs.isBoosted
      })
    })

    // 3. Stages
    activeStages.value.forEach((s) => {
      list.push({
        id: `stage-${s.key}`,
        emoji: s.icon,
        title: s.text?.split('(')[0]?.trim() || '',
        description: `Multiplicador actual: ${s.text?.match(/\(([^)]+)\)/)?.[1] || '100%'}`,
        class: `stage ${(s.val || 0) > 0 ? 'is-up' : 'is-down'}`,
        stageValue: s.val
      })
    })

    return list
  })

  return {
    activeStages,
    volatileStatuses,
    unifiedStatuses
  }
}

import { computed } from 'vue'
import { getMechanicalWeather, WEATHER_MECHANICAL } from '@/logic/weather/weatherRegistry'
import { getDayCycle } from '@/logic/utils/timeUtils'
import { MOVE_DATA } from '@/data/moves'
import { useBattleStore } from '@/stores/battle'
import type { Pokemon, Move } from '@/types/pokemon'

export function useMoveSlotData(
  moveRef: () => Move | null,
  playerInfoRef: () => Pokemon | null
) {
  const battleStore = useBattleStore()

  const moveData = computed(() => {
    const move = moveRef()
    if (!move) return null
    const md = (MOVE_DATA as Record<string, { type?: string; power?: number; acc?: number; cat?: string }>)[move.name] || {}
    return {
      ...move,
      type: move.type || md.type || 'normal',
      power: move.power !== undefined ? move.power : md.power,
      acc: move.acc !== undefined ? move.acc : md.acc,
      cat: move.cat || md.cat || 'physical'
    }
  })

  const finalPower = computed(() => {
    const md = moveData.value
    if (!md || md.power === undefined || md.power === 0) return md?.power || 0

    let power = md.power
    const attacker = playerInfoRef()
    const defender = battleStore.state?.enemy
    const isGym = !!battleStore.state?.isGym
    const weather = isGym ? null : battleStore.state?.weather
    const mechWeather = isGym ? WEATHER_MECHANICAL.CLEAR : getMechanicalWeather(weather?.type)
    const cycle = getDayCycle()

    if (!attacker) return power

    // 1. STAB
    const moveType = md.type.toLowerCase()
    let stab = (moveType === attacker.type?.toLowerCase() || moveType === attacker.type2?.toLowerCase()) ? 1.5 : 1
    if (attacker.ability === 'Adaptable' && stab > 1) stab = 2
    power *= stab

    // 2. Weather
    let weatherMult = 1
    if (weather && weather.turns !== 0) {
      const wType = (weather.visual || weather.type).toLowerCase()
      if (mechWeather === WEATHER_MECHANICAL.SUN) {
        if (moveType === 'fire') weatherMult = 1.5
        if (moveType === 'water') weatherMult = (wType === 'heatwave') ? 0 : 0.5
      } else if (mechWeather === WEATHER_MECHANICAL.RAIN) {
        if (moveType === 'water') weatherMult = 1.5
        if (moveType === 'fire') weatherMult = (wType === 'storm' || wType === 'heavy_rain') ? 0 : 0.5
        if (moveType === 'electric' || moveType === 'dragon') weatherMult = 1.5
      } else if (wType === 'thunderstorm') {
        if (moveType === 'electric' || moveType === 'dragon') weatherMult = 1.5
      }
    }

    // Solar Beam
    if (md.id === 'solar_beam' && weather && weather.turns !== 0) {
      const isSun = mechWeather === WEATHER_MECHANICAL.SUN
      const isClear = mechWeather === WEATHER_MECHANICAL.CLEAR && weather.type !== 'thunderstorm'
      if (!isSun && !isClear) {
        weatherMult *= 0.5
      }
    }

    // Day cycle
    if (weatherMult === 1 && (mechWeather === WEATHER_MECHANICAL.CLEAR || !weather)) {
      if ((cycle === 'day' || cycle === 'morning') && moveType === 'fire') weatherMult = 1.2
      if ((cycle === 'night' || cycle === 'dusk') && moveType === 'water') weatherMult = 1.2
    }

    power *= weatherMult

    // 3. Ability
    let abilMult = 1
    const isLowHp = attacker.hp <= (attacker.maxHp / 3)
    if (isLowHp) {
      if (attacker.ability === 'Mar llamas' && moveType === 'fire') abilMult = 1.5
      if (attacker.ability === 'Torrente' && moveType === 'water') abilMult = 1.5
      if (attacker.ability === 'Espesura' && moveType === 'grass') abilMult = 1.5
      if (attacker.ability === 'Enjambre' && moveType === 'bug') abilMult = 1.5
    }
    if (attacker.ability === 'Experto' && md.power <= 60) {
      abilMult *= 1.5
    }
    if (weather && weather.turns !== 0 && attacker.ability === 'Fuerza arena' && mechWeather === WEATHER_MECHANICAL.SANDSTORM) {
      if (moveType === 'ground' || moveType === 'rock' || moveType === 'steel') {
        abilMult *= 1.3
      }
    }
    power *= abilMult

    // 4. Defender Ability
    if (defender && defender.ability === 'Sebo' && (moveType === 'fire' || moveType === 'ice')) {
      power *= 0.5
    }

    // 5. Item
    let itemMult = 1
    if (attacker.heldItem) {
      const h = attacker.heldItem
      const typeBoosters: Record<string, string> = {
        charcoal: 'fire',
        magnet: 'electric',
        mystic_water: 'water',
        miracle_seed: 'grass',
        black_belt: 'fighting',
        twisted_spoon: 'psychic',
        spell_tag: 'ghost',
        silver_powder: 'bug',
        poison_barb: 'poison'
      }
      if (typeBoosters[h] === moveType) itemMult = 1.2
      if (h === 'choice_band' && md.cat === 'physical') itemMult = 1.5
    }
    power *= itemMult

    return Math.max(1, Math.round(power))
  })

  const finalAccuracy = computed(() => {
    const md = moveData.value
    if (!md || md.acc === undefined || md.acc === 1000) return md?.acc || 0

    let acc = md.acc
    const isGym = !!battleStore.state?.isGym
    const weather = isGym ? null : battleStore.state?.weather?.type
    const mechWeather = isGym ? WEATHER_MECHANICAL.CLEAR : getMechanicalWeather(weather)
    const cycle = getDayCycle()
    const isSunActive = !isGym && (mechWeather === WEATHER_MECHANICAL.SUN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'day' || cycle === 'morning')))
    const isRainActive = !isGym && (mechWeather === WEATHER_MECHANICAL.RAIN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'night' || cycle === 'dusk')))

    const isThunderstorm = weather === 'thunderstorm'
    if ((isRainActive || isThunderstorm) && (md.id === 'thunder' || md.id === 'hurricane')) {
      acc = 100
    } else if (isSunActive && (md.id === 'thunder' || md.id === 'hurricane')) {
      acc = 50
    } else if ((mechWeather === WEATHER_MECHANICAL.HAIL || mechWeather === WEATHER_MECHANICAL.SNOW) && md.id === 'blizzard') {
      acc = 100
    } else if (mechWeather === WEATHER_MECHANICAL.FOG) {
      const isMist = weather === "mist" || weather === "mist_visual"
      acc = Math.floor(md.acc * (isMist ? 0.8 : 0.6))
    }

    const accStage = battleStore.playerStages?.acc || 0
    const evaStage = battleStore.enemyStages?.eva || 0

    acc = acc * (1 + (0.33 * accStage)) * (1 - (0.33 * evaStage))
    return Math.max(0, Math.min(100, Math.round(acc)))
  })

  const moveModifier = computed(() => {
    const md = moveData.value
    if (!md || !battleStore.isBattleActive) return null

    const isGym = !!battleStore.state?.isGym
    const weather = isGym ? null : battleStore.state?.weather
    const mechWeather = isGym ? WEATHER_MECHANICAL.CLEAR : getMechanicalWeather(weather?.type)
    const cycle = getDayCycle()

    const isRaining = !isGym && mechWeather === WEATHER_MECHANICAL.RAIN
    const isSunny = !isGym && mechWeather === WEATHER_MECHANICAL.SUN
    const isSnowing = !isGym && (mechWeather === WEATHER_MECHANICAL.SNOW || mechWeather === WEATHER_MECHANICAL.HAIL)
    const isDayTime = cycle === 'day' || cycle === 'morning'
    const isNightTime = cycle === 'night' || cycle === 'dusk'

    const isSunActive = !isGym && (isSunny || (mechWeather === WEATHER_MECHANICAL.CLEAR && isDayTime))
    const isRainActive = !isGym && (isRaining || (mechWeather === WEATHER_MECHANICAL.CLEAR && isNightTime))

    const moveName = (md.name || '').toLowerCase()

    // 1. Accuracy Boosted
    if (moveName === 'trueno' || moveName === 'thunder' || moveName === 'vendaval' || moveName === 'hurricane') {
      if (isSunny) return 'penalized'
      if (isRaining) return 'boosted'
    }

    if (moveName === 'ventisca' || moveName === 'blizzard') {
      if (isSnowing) return 'boosted'
    }

    // 2. Solar Moves
    if (moveName === 'rayo solar' || moveName === 'solar beam' || moveName === 'cuchilla solar' || moveName === 'solar blade') {
      if (mechWeather !== WEATHER_MECHANICAL.CLEAR && !isSunActive) return 'penalized'
      if (isSunActive) return 'boosted'
    }

    // 3. Weather Ball
    if (moveName === 'meteorobola' || moveName === 'weather ball') {
      if (mechWeather !== WEATHER_MECHANICAL.CLEAR) return 'boosted'
    }

    // 4. Accuracy Penalties (Fog)
    if (mechWeather === WEATHER_MECHANICAL.FOG) {
      return 'penalized'
    }

    if (md.cat === 'status') return null

    // 5. Elemental
    if (md.type === 'fire') {
      if (isRaining) return 'penalized'
      if (isSunActive) return 'boosted'
    }
    if (md.type === 'water') {
      if (isSunny) return 'penalized'
      if (isRainActive) return 'boosted'
    }

    return null
  })

  return {
    moveData,
    finalPower,
    finalAccuracy,
    moveModifier
  }
}

import { computed, toValue } from 'vue';
import type { MaybeRefOrGetter } from 'vue';
import type { Move } from '@/types/pokemon';
import { useBattleStore } from '@/stores/battle';
import { getMechanicalWeather } from '@/logic/weather/weatherRegistry';
import { getDayCycle } from '@/logic/utils/timeUtils';
import { getMoveDescription } from '@/logic/pokemon/pokemonUtils';
import { MOVE_DATA } from '@/data/moves';
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';
import type { PurePokemon } from '@/logic/battle/battleMath';

import {
  calculateMoveModifierInfo,
  calculateMovePower,
  calculateMoveAccuracy,
  calculateCritChance,
  calculateMoveEffectivenessAndDamage,
  parseStatusEffectInfo
} from '@/logic/battle/moveTooltipMath';

export function useMoveTooltip(moveInput: MaybeRefOrGetter<Move>) {
  const battleStore = useBattleStore();

  const modifierInfo = computed(() => {
    if (!battleStore.isBattleActive) return null;
    const move = toValue(moveInput);
    const isGym = !!battleStore.state?.isGym;
    const weather = isGym ? undefined : battleStore.state?.weather?.type;
    const cycle = getDayCycle();
    const attacker = battleStore.state?.player;

    let info = calculateMoveModifierInfo(move, weather, cycle);

    if (attacker && attacker.heldItem === 'choice_band') {
      const moveIdLookup = move.id || (move.name ? pokemonDataProvider.resolveMoveId(move.name) : '');
      const md = (MOVE_DATA as Record<string, { cat?: string }>)[moveIdLookup] || {};
      const category = move.cat || md.cat || 'physical';
      const isPhysical = category === 'physical';

      if (attacker.choiceMove && attacker.choiceMove !== move.name) {
        info = { type: 'penalized', text: `Bloqueado por Cinta Elegida (Elegiste: ${attacker.choiceMove}).` };
      } else if (isPhysical) {
        if (!info) {
          info = { type: 'boosted', text: 'Objeto: Cinta Elegida (+50% Potencia Física, bloquea movimiento).' };
        } else {
          info = { ...info, text: `${info.text} | Cinta Elegida (+50% Potencia, bloqueo)` };
        }
      } else {
        if (!info) {
          info = { type: 'boosted', text: 'Objeto: Cinta Elegida (Bloquea a este movimiento si se selecciona).' };
        } else {
          info = { ...info, text: `${info.text} | Cinta Elegida (Bloqueo)` };
        }
      }
    }

    return info;
  });

  const activeDetails = computed(() => {
    if (!battleStore.isBattleActive) return null;

    const move = toValue(moveInput);
    const attacker = battleStore.state?.player;
    const defender = battleStore.state?.enemy;
    const isGym = !!battleStore.state?.isGym;
    const weather = isGym ? null : battleStore.state?.weather;
    const mechWeather = getMechanicalWeather(weather?.type);
    const cycle = getDayCycle();

    if (!attacker) return null;

    const moveIdLookup = move.id || (move.name ? pokemonDataProvider.resolveMoveId(move.name) : '');
    const md = (MOVE_DATA as Record<string, { power?: number; acc?: number; cat?: string; type?: string }>)[moveIdLookup] || {};
    const basePower = move.power !== undefined ? move.power : md.power || 0;
    const isStatus = move.cat === 'status' || md.cat === 'status';
    const moveType = (move.type || md.type || 'normal').toLowerCase();

    // 1. Power details
    const power = calculateMovePower(
      move,
      attacker as unknown as PurePokemon,
      defender as unknown as PurePokemon | null,
      weather ? { type: weather.type, turns: weather.turns } : null,
      mechWeather,
      cycle,
      basePower,
      moveType
    );

    // 2. Accuracy details
    const baseAcc = move.acc !== undefined ? move.acc : md.acc || 0;
    const accStage = battleStore.playerStages?.acc || 0;
    const evaStage = battleStore.enemyStages?.eva || 0;
    const accuracy = calculateMoveAccuracy(
      move,
      weather ? { type: weather.type, turns: weather.turns } : null,
      mechWeather,
      cycle,
      baseAcc,
      accStage,
      evaStage
    );

    // 3. Crit Chance
    const critChance = calculateCritChance(
      attacker as unknown as PurePokemon,
      defender as unknown as PurePokemon | null
    );

    // 4. Effectiveness and Damage range
    const playerStages = battleStore.playerStages ? { atk: battleStore.playerStages.atk } : null;
    const enemyStages = battleStore.enemyStages ? { def: battleStore.enemyStages.def } : null;
    const { effectiveness, damageRange } = calculateMoveEffectivenessAndDamage(
      move,
      md,
      attacker as unknown as PurePokemon,
      defender as unknown as PurePokemon | null,
      weather ? { type: weather.type, turns: weather.turns } : null,
      cycle,
      isStatus,
      basePower,
      playerStages,
      enemyStages
    );

    return {
      isStatus,
      power: {
        ...power,
        final: isStatus ? '-' : power.final
      },
      accuracy,
      effectiveness,
      critChance,
      damageRange
    };
  });

  const parsedStatusEffect = computed(() => {
    if (!battleStore.isBattleActive) return null;

    const move = toValue(moveInput);
    const attacker = battleStore.state?.player;
    const defender = battleStore.state?.enemy;
    if (!attacker) return null;

    return parseStatusEffectInfo(
      move,
      attacker as unknown as PurePokemon,
      defender as unknown as PurePokemon | null,
      battleStore.playerStages,
      battleStore.enemyStages
    );
  });

  const moveDescriptionText = computed(() => {
    const move = toValue(moveInput);
    const moveId = move.id || (move.name ? pokemonDataProvider.resolveMoveId(move.name) : '');
    const moveDataObj = MOVE_DATA[moveId];
    return getMoveDescription(move.name, moveDataObj);
  });

  return {
    modifierInfo,
    activeDetails,
    parsedStatusEffect,
    moveDescriptionText
  };
}

import { ref, computed, type Ref } from 'vue'
import { useUIStore } from '@/stores/ui'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { POKEMON_SPRITE_IDS } from '@/logic/constants/pokedexConstants'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import type { GameState, PokedexItem } from '@/types/game'

export function usePokedex(gs: Ref<GameState>, currentOrder: Ref<string[]>, _currentGen: Ref<number>) {
  const uiStore = useUIStore()
  const searchQuery = ref('')
  const sortBy = ref('number') // 'number' | 'name'

  const pokemonList = computed<PokedexItem[]>(() => {
    let caught = gs.value.pokedex || []
    let seen = gs.value.seenPokedex || []

    // Debug Overrides (Temporary)
    if (uiStore.debugPokedexMode === 'none') {
      caught = []
      seen = []
    } else if (uiStore.debugPokedexMode === 'caught') {
      caught = [...currentOrder.value]
      seen = [...currentOrder.value]
    } else if (uiStore.debugPokedexMode === 'seen') {
      seen = [...currentOrder.value]
    }


    // 1. Prepare raw list with proper numbers
    const list: PokedexItem[] = currentOrder.value.map((id) => {
      const isCaught = caught.includes(id)
      const isSeen = seen.includes(id) || isCaught
      const data = pokemonDataProvider.getPokemonData(id) || { name: id }

      // Use POKEMON_SPRITE_IDS as the authority for the national number
      const nationalNum = POKEMON_SPRITE_IDS[id] || 0

      return {
        id,
        dexNum: String(nationalNum).padStart(3, '0'),
        rawDexNum: nationalNum,
        name: isSeen ? data.name : 'Desconocido',
        isSeen,
        isCaught,
        spriteUrl: isSeen ? getAssetUrl(ASSET_TYPES.POKEMON, id) : null
      }
    })

    // 2. Filter
    const filtered = list.filter(p => {
      if (!searchQuery.value) return true
      const query = searchQuery.value.toLowerCase()
      // If unseen, we can only search by #number
      if (!p.isSeen) return p.dexNum.includes(query)
      return p.name.toLowerCase().includes(query) || p.dexNum.includes(query)
    })

    // 3. Sort
    return filtered.sort((a, b) => {
      if (sortBy.value === 'name') {
        // Unseen pokes at bottom when sorting by name? or by ID?
        // Usually, original Dexter keeps them in place. 
        // But if user asks to sort by name, they expect alphabetical.
        if (a.name === 'Desconocido' && b.name !== 'Desconocido') return 1
        if (a.name !== 'Desconocido' && b.name === 'Desconocido') return -1
        return a.name.localeCompare(b.name)
      }
      return a.rawDexNum - b.rawDexNum
    })
  })

  return {
    searchQuery,
    sortBy,
    pokemonList
  }
}

import { computed, toValue } from 'vue'
import type { MaybeRefOrGetter } from 'vue'
import { useGameStore } from '@/stores/game'
import { useModalStore } from '@/stores/modals'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { POKEMON_SPRITE_IDS } from '@/logic/constants/pokedexConstants'
import { MOVE_DATA } from '@/data/moves'
import { EVOLUTION_TABLE, STONE_EVOLUTIONS, TRADE_EVOLUTIONS } from '@/data/evolutionData'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'
import type { Pokemon } from '@/types/pokemon'
import type { MoveBaseData } from '@/types/database'
import { GAME_TIMEZONE } from '@/logic/utils/timeUtils'

interface EvolutionEntry {
  type: 'level' | 'stone' | 'trade';
  requirement: string;
  to: string;
  isSeen: boolean;
  isCaught: boolean;
}

export function usePokemonDetail(propsRefs: Record<string, MaybeRefOrGetter<unknown>>) {
  const gameStore = useGameStore()
  const modalStore = useModalStore()

  // Normalize inputs (props are passed as a reactive object or refs)
  const getProp = <T,>(key: string): T | undefined => toValue(propsRefs[key]) as T | undefined

  const uiData = computed(() => {
    const modal = modalStore.stack.find(m => m.name === 'PokemonDetail')
    return (modal?.props || {}) as { pokemon?: Pokemon, index?: number, context?: string }
  })

  const finalIndex = computed(() => {
    const pIdx = getProp<number>('index') ?? -1
    return pIdx !== -1 ? pIdx : (uiData.value.index ?? -1)
  })

  const finalContext = computed(() => {
    const pCtx = getProp<string>('context')
    return (pCtx && pCtx !== 'pokedex') ? pCtx : (uiData.value.context || 'pokedex')
  })

  const targetPokemon = computed(() => {
    if (finalIndex.value > -1) {
      if (finalContext.value === 'team') return gameStore.state.team[finalIndex.value]
      if (finalContext.value === 'box') return gameStore.state.box[finalIndex.value]
    }
    return getProp<Pokemon>('pokemon') || uiData.value.pokemon
  })

  const isInstance = computed(() => !!targetPokemon.value)

  const targetSpeciesId = computed(() => {
    const id = isInstance.value ? targetPokemon.value?.id : getProp<string>('speciesId')
    return String(id || '').toLowerCase()
  })

  const speciesRaw = computed(() => pokemonDataProvider.getPokemonData(targetSpeciesId.value))

  const species = computed(() => {
    if (!speciesRaw.value) return null
    const s = speciesRaw.value
    const types = Array.isArray(s.type) ? s.type : [s.type]
    const nationalId = POKEMON_SPRITE_IDS[targetSpeciesId.value] || 0

    return {
      ...s,
      nationalId: nationalId.toString(),
      type: types,
      stats: {
        hp: s.hp || 0,
        atk: s.atk || 0,
        def: s.def || 0,
        spa: s.spa || 0,
        spd: s.spd || 0,
        spe: s.spe || 0
      }
    }
  })

  const cleanCategory = computed(() => {
    if (!species.value?.category) return 'Desconocido'
    return species.value.category.replace(/^Pokémon\s+/i, '')
  })

  const evolutions = computed(() => {
    const list = []
    const id = targetSpeciesId.value
    const caught = gameStore.state.pokedex || []
    const seen = gameStore.state.seenPokedex || []

    const enrichEvo = (evo: { type: 'level' | 'stone' | 'trade', requirement: string, to: string }): EvolutionEntry => {
      const toId = evo.to.toLowerCase()
      const isCaught = caught.includes(toId)
      const isSeen = isCaught || seen.includes(toId)
      return { ...evo, isSeen, isCaught }
    }

    const evoTable = EVOLUTION_TABLE as Record<string, { level: number, to: string } | undefined>
    if (evoTable[id]) {
      const ev = evoTable[id]!
      list.push(enrichEvo({ type: 'level', requirement: `Nv. ${ev.level}`, to: ev.to }))
    }

    const stoneTable = STONE_EVOLUTIONS as Record<string, { stone: string, to: string } | undefined>
    Object.keys(stoneTable).forEach(key => {
      if (key === id || key.startsWith(`${id}_`)) {
        const ev = stoneTable[key]!
        list.push(enrichEvo({ type: 'stone', requirement: ev.stone, to: ev.to }))
      }
    })

    const tradeTable = TRADE_EVOLUTIONS as Record<string, string | undefined>
    if (tradeTable[id]) {
      list.push(enrichEvo({ type: 'trade', requirement: 'Intercambio', to: tradeTable[id]! }))
    }
    return list
  })

  const displayStats = computed(() => {
    if (!species.value) return []
    const labels: Record<string, string> = { hp: 'HP', atk: 'ATK', def: 'DEF', spa: 'SPA', spd: 'SPD', spe: 'SPE' }
    const colors: Record<string, string> = { 
      hp: 'Rgba(255, 89, 89, 1)', 
      atk: 'Rgba(245, 172, 120, 1)', 
      def: 'Rgba(250, 224, 120, 1)', 
      spa: 'Rgba(157, 183, 245, 1)', 
      spd: 'Rgba(167, 219, 141, 1)', 
      spe: 'Rgba(250, 146, 178, 1)' 
    }
    return Object.keys(species.value.stats).map(key => {
      const base = (species.value?.stats as Record<string, number>)[key] || 0
      const current = isInstance.value ? (((targetPokemon.value as unknown as Record<string, number>)[key]) || base) : base
      return {
        id: key,
        label: labels[key] || key.toUpperCase(),
        value: current,
        baseValue: base,
        max: 255,
        color: colors[key] || '#888',
        iv: isInstance.value ? (targetPokemon.value?.ivs as Record<string, number> | undefined)?.[key] || 0 : 0
      }
    })
  })

  const moveDetails = computed(() => {
    if (!species.value || !species.value.learnset) return []
    return species.value.learnset.map(m => {
      const resolvedId = pokemonDataProvider.resolveMoveId(m.name)
      const data = (MOVE_DATA as Record<string, MoveBaseData | undefined>)[resolvedId]
      const basePP = data?.pp || 35
      return {
        level: m.lv,
        name: m.name,
        type: data?.type || 'normal',
        cat: data?.cat || 'physical',
        power: data?.power ?? 0,
        acc: data?.acc ?? 100,
        pp: basePP,
        maxPP: basePP
      }
    }).sort((a, b) => a.level - b.level)
  })

  const currentMoves = computed(() => {
    if (!isInstance.value || !targetPokemon.value?.moves) return []
    return targetPokemon.value.moves.map((m: Pokemon['moves'][number]) => {
      if (!m) return null
      const resolvedId = pokemonDataProvider.resolveMoveId(m.name)
      const data = (MOVE_DATA as Record<string, MoveBaseData | undefined>)[resolvedId]
      return { ...m, ...(data || {}) }
    }).filter((m: unknown): m is (Pokemon['moves'][number] & Partial<MoveBaseData>) => m !== null)
  })

  const canStoneEvolve = computed(() => {
    const id = targetSpeciesId.value
    return Object.keys(STONE_EVOLUTIONS).some(key => key === id || key.startsWith(`${id}_`))
  })

  const instancePhysicalData = computed(() => {
    const p = targetPokemon.value as (Pokemon & { height?: number, weight?: number }) | undefined
    if (!isInstance.value || !p || !species.value) return null
    const uid = p.uid || 'def'
    const getRand = (seed: string, range: number | [number, number] | null) => {
      if (!range) return '0.0'
      const min = Array.isArray(range) ? range[0] : range * 0.85
      const max = Array.isArray(range) ? range[1] : range * 1.15
      let hash = 0
      for (let i = 0; i < seed.length; i++) hash = seed.charCodeAt(i) + ((hash << 5) - hash)
      const normalized = (Math.abs(hash) % 100) / 100
      return (min + normalized * (max - min)).toFixed(1)
    }
    return {
      height: p.height || getRand(uid + 'h', species.value.height),
      weight: p.weight || getRand(uid + 'w', species.value.weight)
    }
  })

  const captureDateFormatted = computed(() => {
    const p = targetPokemon.value as (Pokemon & { captureDate?: string, timestamp?: number, date?: string, created_at?: string }) | undefined
    if (!p) return null
    const dateVal = p.captureDate || p.timestamp || p.date || p.created_at || p.obtainedAt
    if (!dateVal) return isInstance.value ? 'SIN FECHA' : null

    try {
      return (typeof dateVal === 'string' ? Temporal.Instant.from(dateVal) : Temporal.Instant.fromEpochMilliseconds(Number(dateVal)))
        .toZonedDateTimeISO(GAME_TIMEZONE)
        .toLocaleString('es-ES', { 
          year: 'numeric', month: 'long', day: 'numeric',
          hour: '2-digit', minute: '2-digit',
          hour12: false
        })
    } catch (_) {
      return null
    }
  })

  const getSprite = (id: string, isShiny: boolean = false) => getAssetUrl(ASSET_TYPES.POKEMON, id, { isShiny })

  return {
    targetPokemon,
    isInstance,
    targetSpeciesId,
    species,
    cleanCategory,
    evolutions,
    displayStats,
    moveDetails,
    currentMoves,
    canStoneEvolve,
    instancePhysicalData,
    captureDateFormatted,
    getSprite,
    finalIndex,
    finalContext
  }
}

import { gsap } from 'gsap'

interface StatHoverClassMap {
  pvp?: { border: string; background: string }
  'highlight-war-points'?: { border: string; background: string }
  'highlight-war-coins'?: { border: string; background: string }
}

const DEFAULT_CLASSES: StatHoverClassMap = {
  pvp: {
    border: 'rgba(236, 72, 153, 0.2)',
    background: 'linear-gradient(135deg, rgba(236, 72, 153, 0.05) 0%, rgba(15, 23, 42, 0.4) 100%)'
  },
  'highlight-war-points': {
    border: 'rgba(59, 130, 246, 0.2)',
    background: 'linear-gradient(135deg, rgba(59, 130, 246, 0.05) 0%, rgba(15, 23, 42, 0.4) 100%)'
  },
  'highlight-war-coins': {
    border: 'rgba(251, 191, 36, 0.2)',
    background: 'linear-gradient(135deg, rgba(251, 191, 36, 0.05) 0%, rgba(15, 23, 42, 0.4) 100%)'
  }
}

export function useStatHover(classMap: StatHoverClassMap = DEFAULT_CLASSES) {
  const handleStatEnter = (e: MouseEvent) => {
    gsap.to(e.currentTarget, {
      y: -2,
      backgroundColor: 'rgba(30, 41, 59, 0.5)',
      borderColor: 'rgba(255, 214, 10, 0.2)',
      boxShadow: '0 0 0 1px rgba(255, 214, 10, 0.2)',
      duration: 0.2,
      ease: 'power2.out'
    })
  }

  const handleStatLeave = (e: MouseEvent) => {
    const el = e.currentTarget as HTMLElement
    let baseBorderColor = 'rgba(255, 255, 255, 0.05)'
    let baseBackground = 'rgba(15, 23, 42, 0.95)'

    const keys = Object.keys(classMap) as Array<keyof StatHoverClassMap>
    for (const cls of keys) {
      if (el.classList.contains(cls)) {
        baseBorderColor = classMap[cls]!.border
        baseBackground = classMap[cls]!.background
        break
      }
    }

    gsap.to(el, {
      y: 0,
      background: baseBackground,
      borderColor: baseBorderColor,
      boxShadow: 'none',
      duration: 0.2,
      ease: 'power2.out',
      clearProps: 'y,background,borderColor,boxShadow'
    })
  }

  return { handleStatEnter, handleStatLeave }
}

/**
 * fx-configs.ts
 * Centraliza las reglas visuales para todos los efectos de partículas.
 * MIGRACIÓN 1:1 DESDE PVSPRITEFX.VUE
 */

export interface ParticleArea {
  x: [number, number]
  y?: [number, number]
}

export interface WobbleConfig {
  x: number
  rotation: number
  duration: number
  yoyo?: boolean
  ease?: string
}

export interface EffectSettings {
  shape: 'circle' | 'rect'
  area: ParticleArea
  offset: { x: number; y: number }
  activeRange: [number, number]
  mult: number
  useFade: boolean
  wobble: WobbleConfig | boolean
  stagger: number
  duration?: number
  targetOpacity?: number
  randomizeVars?: boolean | { min: number, max: number }
  growDuration?: number
  rotation?: number
}

export const resolveEffectSettings = (typeKey: string, ar: number, options: { isField?: boolean, isSimplified?: boolean, isBattle?: boolean, spriteScale?: number } = {}): EffectSettings => {
  const isField = options.isField || ['reflect', 'lightscreen', 'safeguard', 'mist', 'spikes'].includes(typeKey)
  const isFeetEffect = ['seed', 'trapped', 'bound', 'ingrain', 'seeded'].includes(typeKey)
  const isHeadEffect = ['sleep', 'confusion', 'attract', 'confused'].includes(typeKey)

  // 1. Helper para rango dinámico basado en radio
  const getDynamicRange = (base: [number, number]) => {
    const baseRadius = options.isBattle ? ar / 1.5 : ar
    const ratio = baseRadius / 40
    let scaleFactor = Math.max(0.15, Math.min(2.5, Math.pow(ratio, 2)))

    if (options.spriteScale !== undefined) {
      scaleFactor *= options.spriteScale
    }

    // Reducción extra para miniaturas (fuera de batalla o modo simplificado)
    if (typeKey === 'shiny' && (options.isSimplified || !options.isBattle)) {
      scaleFactor *= 0.3
    }

    return [
      Math.max(1, Math.round(base[0] * scaleFactor)),
      Math.max(1, Math.round(base[1] * scaleFactor))
    ] as [number, number]
  }

  // 2. CONFIGURACIÓN CENTRALIZADA E INDEPENDIENTE
  const configs: Record<string, Partial<EffectSettings>> = {
    burn: { mult: 1.0, activeRange: getDynamicRange([12, 18]), useFade: false, duration: 1.2, randomizeVars: { min: 0.6, max: 2.0 } },
    freeze: { mult: 0.4, activeRange: getDynamicRange([1, 2]), useFade: false, duration: 3.0 , randomizeVars: { min: 1.0, max: 2.0 } },
    sleep: { mult: 1.0, activeRange: getDynamicRange([1, 2]), useFade: true, duration: 3.0, randomizeVars: { min: 1.0, max: 2.0 } },
    paralysis: { mult: 1.0, activeRange: getDynamicRange([6, 10]), useFade: true, duration: 0.3, randomizeVars: { min: 1.0, max: 2.0 } },
    poison: { mult: 0.8, activeRange: getDynamicRange([1, 2]), useFade: true, duration: 3.0, randomizeVars: { min: 1.0, max: 2.0 } },
    toxic: { mult: 0.8, activeRange: getDynamicRange([1, 2]), useFade: true, duration: 3.0 },
    confusion: { mult: 0.8, activeRange: getDynamicRange([1, 2]), useFade: true, wobble: true, duration: 6.0 },
    confused: { mult: 0.8, activeRange: getDynamicRange([1, 2]), useFade: true, wobble: true, duration: 6.0 },
    attracted: { mult: 0.8, activeRange: getDynamicRange([4, 6]), useFade: true, duration: 4.0, randomizeVars: { min: 1.0, max: 2.0 } },
    cursed: { mult: 0.8, activeRange: getDynamicRange([2, 3]), useFade: true, duration: 3.0 },
    seeded: { mult: 0.8, activeRange: getDynamicRange([6, 10]), useFade: true, duration: 5.0, randomizeVars: true },
    seed: { mult: 0.8, activeRange: getDynamicRange([6, 10]), useFade: true, duration: 5.0, randomizeVars: true },
    trapped: { mult: 1.4, activeRange: getDynamicRange([6, 10]), useFade: true, duration: 5.0, growDuration: 0.5, randomizeVars: true },
    ingrained: { mult: 0.8, activeRange: getDynamicRange([6, 10]), useFade: true, duration: 1.5, randomizeVars: true },

    // Tactical
    protected: { mult: 1.0, activeRange: getDynamicRange([4, 6]), useFade: true, duration: 1.5 },
    enduring: { mult: 1.6, activeRange: getDynamicRange([1, 1]), useFade: false, duration: 1.2, growDuration: 0.3 },
    focus: { mult: 1.0, activeRange: getDynamicRange([1, 1]), useFade: false, duration: 0.8, growDuration: 0.2 },
    lockon: { mult: 1.0, activeRange: getDynamicRange([1, 1]), useFade: false, duration: 1.0, growDuration: 0.25 },

    // Field
    reflect: { mult: 1.5, activeRange: getDynamicRange([1, 1]), useFade: true, duration: 4.0, targetOpacity: 1.0 },
    safeguard: { mult: 0.5, activeRange: getDynamicRange([1, 3]), useFade: true, duration: 3.0 , targetOpacity: 1.0 },
    lightscreen: { mult: 1.5, activeRange: getDynamicRange([1, 1]), useFade: true, duration: 3.0, targetOpacity: 1.0 },
    mist: { mult: 1.5, activeRange: getDynamicRange([14, 20]), useFade: true, duration: 5.0, randomizeVars: { min: 0.6, max: 2.5 }, targetOpacity: 0.9 },
    spikes: { mult: 0.5, activeRange: getDynamicRange([4, 8]), useFade: true, duration: 2.5 },

    // Shiny - chispas doradas orbitales (técnica wobble)
    shiny: { mult: 0.2, activeRange: getDynamicRange([10, 16]), useFade: false, duration: 1.4, randomizeVars: { min: 0.6, max: 1.5 }, targetOpacity: 1.0, wobble: true }
  }

  const base = configs[typeKey] || { 
    mult: 0.5, 
    activeRange: getDynamicRange([2, 4]), 
    useFade: true, 
    duration: isField ? 3.0 : 1.5 
  }

  // 3. Parámetros de Wobble exactos
  let wobbleConfig: WobbleConfig | boolean = false
  if (typeKey === 'confusion' || typeKey === 'confused') {
    wobbleConfig = { x: 30, rotation: 10, duration: 0.12 }
  } else if (typeKey === 'attract' || typeKey === 'attraction') {
    wobbleConfig = { x: 15, rotation: 5, duration: 0.4 }
  } else if (typeKey === 'trapped') {
    wobbleConfig = { x: 5, rotation: 0, duration: 0.2 }
  } else if (typeKey === 'shiny') {
    wobbleConfig = { x: 0, rotation: 360, duration: 1.5, yoyo: false, ease: 'none' }
  }

  // 4. Área de dispersión
  const factor = (typeKey === 'paralysis') ? 1.3 : (isHeadEffect ? 0.4 : 1.0)
  const maxRadius = isField ? (typeKey === 'mist' ? 25 : 45) : ar * factor

  const area: ParticleArea = (isFeetEffect) 
    ? { x: [-40, 40], y: [0, 15] }
    : { x: [maxRadius * 0.2, maxRadius] }

  // 4. Offset dinámico exacto
  let offset: { x: number; y: number } = { x: 0, y: 0 }
  if (isHeadEffect) offset = { x: 0, y: -ar * 0.75 }
  else if (isFeetEffect) offset = { x: 0, y: ar * 0.35 }

  const isPrimary = ['burn', 'freeze', 'sleep', 'paralysis', 'poison', 'toxic'].includes(typeKey)
  const isTactical = ['protected', 'enduring', 'focus', 'lockon'].includes(typeKey)

  const targetOpacity = base.targetOpacity ?? (isField ? 0.6 : (isTactical ? 1.0 : 1.0))
  const duration = base.duration || (isField ? 2.0 : (isTactical ? 1.2 : 0.8))

  const result: EffectSettings = {
    shape: isFeetEffect ? 'rect' : 'circle',
    area,
    offset,
    activeRange: base.activeRange || [2, 4],
    mult: base.mult || 0.5,
    useFade: base.useFade ?? true,
    wobble: wobbleConfig,
    stagger: base.stagger || 0,
    duration,
    targetOpacity,
    randomizeVars: base.randomizeVars ?? isPrimary,
    growDuration: base.growDuration
  }

  // Ajustes finales dinámicos para Shiny
  if (typeKey === 'shiny' && (options.isSimplified || !options.isBattle)) {
    result.mult = 0.35
  } else if (typeKey === 'shiny') {
    result.mult = 0.45
  }

  return result
}

