/**
 * Validates the state before saving to prevent cache hacking or data corruption.
 */
export function validateAndSanitize(data: SaveData): { valid: boolean, data: SaveData, hadDuplicates?: boolean, issues: string[], error?: string } {
  if (!data) return { valid: false, data: {} as SaveData, issues: [], error: 'No data' };

  const issues: string[] = [];

  // 1. Basic numeric validation
  if (data.money < 0) { data.money = 0; issues.push('Dinero negativo corregido'); }
  if (data.battleCoins < 0) { data.battleCoins = 0; issues.push('BattleCoins negativos corregidos'); }
  if (data.trainerLevel < 1) { data.trainerLevel = 1; issues.push('Nivel inválido corregido'); }

  // 2. Inventory sanity
  if (data.inventory) {
    Object.keys(data.inventory).forEach(item => {
      const qty = data.inventory[item]
      if (typeof qty === 'number' && qty < 0) {
        data.inventory[item] = 0;
        issues.push(`Cantidad negativa de ${item} corregida`);
      }
    });
  }

  // 3. Unique ID (UID) integrity for Pokemon
  const uids = new Set<string>();
  const duplicateUids = new Set<string>();

  const checkPoke = (p: Pokemon, listName: string) => {
    if (!p || !p.uid) return;
    if (uids.has(p.uid)) {
      duplicateUids.add(p.uid);
      issues.push(`Duplicado de UID detectado: ${p.uid} (${p.name}) en ${listName}`);
    }
    uids.add(p.uid);
  };

  const sanitizeMoves = (p: Pokemon) => {
    if (p && Array.isArray(p.moves)) {
      p.moves.forEach((m) => {
        if (m && m.name) {
          const resolvedId = pokemonDataProvider.resolveMoveId(m.name);
          if (resolvedId) {
            m.id = resolvedId;
            const dbMove = pokemonDataProvider.getMoveData(resolvedId);
            if (dbMove) {
              m.name = dbMove.name;
            }
          }
        }
      });
    }
  };

  if (data.team) {
    data.team.forEach((p) => {
      checkPoke(p, 'equipo');
      sanitizeMoves(p);
      sanitizePokemon(p);
    });
  }
  if (data.box) {
    data.box.forEach((p) => {
      checkPoke(p, 'caja');
      sanitizeMoves(p);
      sanitizePokemon(p);
    });
  }

  if (duplicateUids.size > 0) {
    // We sanitize by removing subsequent duplicates
    const finalUids = new Set<string>();
    if (Array.isArray(data.team)) {
      data.team = data.team.filter((p) => {
        if (!p.uid) return true;
        if (finalUids.has(p.uid)) return false;
        finalUids.add(p.uid);
        return true;
      });
    }
    if (Array.isArray(data.box)) {
      data.box = data.box.filter((p) => {
        if (!p.uid) return true;
        if (finalUids.has(p.uid)) return false;
        finalUids.add(p.uid);
        return true;
      });
    }
  }

  return { 
    valid: true, 
    data, 
    hadDuplicates: duplicateUids.size > 0,
    issues 
  };
}

export function isValidState(data: SaveData): boolean {
  return validateAndSanitize(data).valid;
}

/**
 * Saves the game to localStorage and the database.
 */
let _isSaving = false;

interface SaveOptions {
  showNotif?: boolean
  notifyFn?: (msg: string, icon?: string) => void
  db?: DBRouter
  userVersion?: number
  lastSaveId?: string
  skipRemote?: boolean
}

export async function saveGame(state: GameState, user: AuthUser, options: SaveOptions = {}): Promise<SaveResult | null> {
  const { showNotif = true, notifyFn, db } = options;
  if (!user || _isSaving) return null;

  _isSaving = true;
  try {
    const raw_data = serializeState(state);
    const { data: save_data, hadDuplicates, issues } = validateAndSanitize(raw_data);

    // VERSIONED SECURITY LOGIC
    const currentVersion = options.userVersion || 1;
    const isLegacy = currentVersion < 3;

    // IF Duplicates found AND we are ONLINE AND NOT LEGACY -> Protocol ROLLBACK
    // Legacy accounts (v1/v2) get a "graceful cleanup" on their first save
    if (hadDuplicates && db && db.mode === 'online' && !isLegacy) {
      logger.error('SAVE', 'Duplicados críticos detectados en v2+. Iniciando ROLLBACK.', issues);
      try {
        const { data } = await db.from('game_saves').select('save_data').eq('user_id', user.id).single();
        const serverSave = data as { save_data: GameState } | null;
        if (serverSave?.save_data) {
          return { rollback: true, serverData: serverSave.save_data };
        }
      } catch(e) {
        logger.error('SAVE', `Error durante rollback: ${(e as Error).message}`);
      }
      return { rollback: true, error: 'Inconsistencia detectada. Recarga la página.' };
    }

    (save_data as { _last_updated?: number })._last_updated = Temporal.Now.instant().epochMilliseconds;

    // 1. Local Persistence (Legacy LocalStorage + Modern OPFS GZIP)
    try {
      const json = JSON.stringify(save_data);
      localStorage.setItem('pokemon_local_save_' + user.id, json);

      // Modern High-Fidelity Binary Storage (OPFS)
      const compressed = await compress(json);
      await writeOpfsFile(`save_${user.id}.gz`, compressed);
    } catch (e) {
      logger.warn('SAVE', `Error en persistencia local (LS/OPFS): ${(e as Error).message}`);
    }

    const isOnlineLocalUser = db && db.mode === 'online' && (user.id === 'local_user' || user.id.startsWith('local_'));

    // 2. Database
    if (!db || options.skipRemote || isOnlineLocalUser) {
      if (options.skipRemote || isOnlineLocalUser) {
        logger.info('SAVE', `Database save skipped (${isOnlineLocalUser ? 'Local User in Online Mode' : 'Session Locked'}). Local storage only.`);
      } else {
        logger.warn('SAVE', 'No DBRouter instance provided. Skipping DB save.');
      }

      if (showNotif && notifyFn && (options.skipRemote || isOnlineLocalUser) && user.id !== 'local_user' && !user.id.startsWith('local_')) {
        notifyFn('Progreso guardado localmente (Sesión Bloqueada)', '🟠');
      }

      return { success: true, remote: false };
    }

    try {
      const { data: res, error } = await db.rpc('save_game_trusted', {
        p_save_data: save_data,
        p_expected_id: options.lastSaveId || null
      });

      if (error) throw error;

      const resData = res as { success: boolean; error: string; last_save_id: string } | null;
      if (resData && resData.success === false && resData.error === 'OUT_OF_SYNC') {
        logger.warn('SAVE', 'Concurrencia detectada. El servidor tiene una versión más nueva.');
        return { rollback: true, outOfSync: true };
      }

      // Sincronizar campos principales en la tabla profiles para mantener consistencia
      try {
        const { data: existingProf } = await db.from('profiles').select('id').eq('id', user.id).maybeSingle();
        const finalUsername = save_data.trainer || user.user_metadata?.username || 'Entrenador';

        const profileValidation = validateUserProfile({
          id: user.id,
          username: finalUsername,
          level: save_data.trainerLevel,
          is_banned: false,
          coins: save_data.money
        });

        if (!profileValidation.success) {
          logger.warn('SAVE', 'Sincronización de perfil abortada por validación de esquema fallida:', profileValidation.issues);
          throw new Error('Datos del perfil inválidos: ' + (profileValidation.issues[0]?.message || 'Esquema incorrecto'));
        }

        const shinyCount = ((save_data.team || []).filter(p => p.isShiny).length) + ((save_data.box || []).filter(p => p.isShiny).length);
        const statsRecord = (save_data.stats || {}) as Record<string, unknown>;
        const maxDamage = Number(statsRecord.maxDamage) || 0;
        const totalBattles = Number(statsRecord.totalBattles) || 0;
        const tradeVolume = Number(statsRecord.tradeVolume) || 0;
        const captureAttempts = Number(statsRecord.captureAttempts) || 0;
        const captureSuccesses = Number(statsRecord.captureSuccesses) || 0;

        if (existingProf) {
          await db.from('profiles').update({
            username: finalUsername,
            trainer_level: save_data.trainerLevel,
            player_class: save_data.playerClass,
            faction: save_data.faction,
            avatar_style: save_data.avatar_style,
            nick_style: save_data.nick_style,
            badges: save_data.badges || 0,
            gender: save_data.gender || 'h',
            playtime: save_data.playtime || 0,
            last_played_at: Temporal.Now.instant().toString(),
            ranked_max_elo: save_data.rankedMaxElo || 1000,
            class_level: save_data.classLevel || 1,
            box_count: (save_data.box || []).length,
            pvp_draws: save_data.pvpStats?.draws || 0,
            longest_streak: save_data.classData?.longestStreak || 0,
            shiny_count: shinyCount,
            max_damage: maxDamage,
            total_battles: totalBattles,
            trade_volume: tradeVolume,
            capture_attempts: captureAttempts,
            capture_successes: captureSuccesses
          }).eq('id', user.id);
        } else {
          await db.from('profiles').insert({
            id: user.id,
            username: finalUsername,
            email: user.email || `${user.id}@local`,
            trainer_level: save_data.trainerLevel || 1,
            player_class: save_data.playerClass || 'entrenador',
            faction: save_data.faction || null,
            avatar_style: save_data.avatar_style || '',
            nick_style: save_data.nick_style || '',
            badges: save_data.badges || 0,
            role: 'user',
            gender: save_data.gender || 'h',
            playtime: save_data.playtime || 0,
            created_at: Temporal.Now.instant().toString(),
            last_played_at: Temporal.Now.instant().toString(),
            ranked_max_elo: save_data.rankedMaxElo || 1000,
            class_level: save_data.classLevel || 1,
            box_count: (save_data.box || []).length,
            pvp_draws: save_data.pvpStats?.draws || 0,
            longest_streak: save_data.classData?.longestStreak || 0,
            shiny_count: shinyCount,
            max_damage: maxDamage,
            total_battles: totalBattles,
            trade_volume: tradeVolume,
            capture_attempts: captureAttempts,
            capture_successes: captureSuccesses,
            db_version: 3
          });
        }
        user.db_version = 3;
        logger.success('SAVE', 'Campos de perfil sincronizados en la base de datos.');
      } catch (e) {
        logger.warn('SAVE', `Error al sincronizar campos del perfil: ${(e as Error).message}`);
      }

      // IF successful migration save, we MUST update the user's version to v3
      let migrated = false;
      if (isLegacy) {
        try {
          await db.from('profiles').update({ db_version: 3 }).eq('id', user.id);
          user.db_version = 3;
          migrated = true;
          logger.success('SAVE', 'Account migrated to db_version v3');
        } catch(e) {
          logger.warn('SAVE', `Migration update failed: ${(e as Error).message}`);
        }
      }

      if (showNotif && notifyFn) {
        if (migrated) notifyFn('¡Cuenta migrada a Seguridad v3!', '✨');
        else if (hadDuplicates) notifyFn('Cache saneada (duplicados eliminados)', '🛡️');
        else notifyFn('Juego Guardado', '💾');
      }

      return { 
        success: true, 
        sanitized: hadDuplicates, 
        migrated,
        lastSaveId: resData?.last_save_id 
      };
    } catch (e: unknown) {
      const errMsg = e instanceof Error ? e.message : 'Unknown error';
      logger.warn('SAVE', `Error en DB Persistente: ${errMsg}`);
      return { success: false, error: errMsg };
    }
  } finally {
    _isSaving = false;
  }
}

import type { Pokemon } from '@/types/pokemon';
import type { BattleStages, LogFn } from '@/types/battle';
import { STAT_ACTIONS } from './statActions.ts';
import { STATUS_ACTIONS } from './statusActions.ts';
import { HEALING_ACTIONS } from './healingActions.ts';
import { WEATHER_ACTIONS } from './weatherActions.ts';
import { FIELD_ACTIONS } from './fieldActions.ts';
import { SPECIAL_ACTIONS } from './specialActions.ts';
import { logger } from '@/logic/utils/logger';
import type { BattleContext } from '@/types/battleContext';

/**
 * Registro Central de Acciones y Efectos
 * Despacha efectos de movimientos de forma modular.
 */

type BattleAction = (
  src: Pokemon, 
  tgt: Pokemon, 
  srcStages: BattleStages, 
  tgtStages: BattleStages, 
  addLogFn: LogFn, 
  battleCtx: BattleContext
) => Promise<void> | void;

const ALL_ACTIONS: Record<string, BattleAction> = {
  ...STAT_ACTIONS,
  ...STATUS_ACTIONS,
  ...HEALING_ACTIONS,
  ...WEATHER_ACTIONS,
  ...FIELD_ACTIONS,
  ...SPECIAL_ACTIONS
};

/**
 * Despacha un efecto de movimiento a la función correspondiente.
 * Maneja la probabilidad de activación (ej: burn_10).
 */
export async function dispatchMoveEffect(
  effect: string | null, 
  src: Pokemon, 
  tgt: Pokemon, 
  srcStages: BattleStages, 
  tgtStages: BattleStages, 
  addLogFn: LogFn, 
  battleCtx: BattleContext
) {
  if (!effect) return;

  // 1. Parshear probabilidad (ej: burn_10 -> 10% de chance, efecto base 'burn')
  let chance = 100;
  let effectBase = effect;

  if (/_(\d+)$/.test(effect) && !effect.startsWith('heal_') && !effect.includes('self_atk_2')) {
    const match = effect.match(/_(\d+)$/);
    if (match) {
      const val = parseInt(match[1] as string);
      // Evitar parshear niveles de stat (_2) como probabilidad
      if (val > 2) {
        chance = val;
        effectBase = effect.replace(/_\d+$/, '');
      }
    }
  }

  const roll = Math.random() * 100;
  if (roll > chance) return; // No se activó el efecto secundario

  // 2. Comprobar inmunidades generales (Shield Dust / Polvo Escudo)
  if (tgt.ability === 'Polvo escudo' && chance < 100) {
    if (effectBase !== 'leech_seed' && effectBase !== 'metronome') {
      addLogFn(`¡El Polvo escudo de ${tgt.name} evitó los efectos secundarios!`, 'log-info', tgt);
      return;
    }
  }

  // 3. Buscar y ejecutar la acción
  // Prioridad al efecto completo (ej: stat_up_self_atk_2)
  const actionFn = ALL_ACTIONS[effect] || ALL_ACTIONS[effectBase];

  logger.debug('ActionRegistry', `Dispatching: ${effect} (Base: ${effectBase}) -> Found: ${!!actionFn}`);

  if (actionFn) {
    try {
      // Snatch (Robo) Logic: Intercept beneficial status moves
      const snatchablePrefixes = ['stat_up_self', 'heal_50', 'heal_weather', 'rest', 'reflect', 'light_screen', 'safeguard', 'focus_energy'];
      const isSnatchable = snatchablePrefixes.some((p) => effect.startsWith(p));

      if (isSnatchable && tgt.snatching) {
        addLogFn(`¡${tgt.name} robó el efecto con Robo!`, 'log-info', tgt);
        tgt.snatching = false;
        // Execute action with swapped src/tgt
        await actionFn(tgt, src, tgtStages, srcStages, addLogFn, battleCtx);
        return;
      }

      await actionFn(src, tgt, srcStages, tgtStages, addLogFn, battleCtx);
    } catch (e) {
      logger.error('ActionRegistry', `Error executing ${effect}: ${(e as Error).message}`);
    }
  } else {
    // Casos especiales no modulares aún o logs de depuración
    logger.warn('ActionRegistry', `No se encontró acción para el efecto: ${effect} (${effectBase})`);
  }
}

import { calculateDamage } from '@/logic/battle/battleEngine'
import { recalcPokemonStats } from '@/logic/pokemon/pokemonFactory'
import { canAttack } from '@/logic/battle/battleFlow'
import { dispatchMoveEffect } from './actionRegistry.ts'
import { gameBus } from '@/logic/events/gameBus'
import { getMechanicalWeather, WEATHER_MECHANICAL } from '@/logic/weather/weatherRegistry'
import { getDayCycle } from '@/logic/utils/timeUtils'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { MOVE_DATA } from '@/data/moves'
import type { BattleContext } from '@/types/battleContext'
import type { Move } from '@/types/pokemon'
import { logger } from '@/logic/utils/logger'

export async function executeMoveAction(
  store: BattleContext,
  side: 'player' | 'enemy',
  move: Move
) {
  const p = store.activeBattle.value?.player
  const e = store.activeBattle.value?.enemy
  if (!p || !e) return

  const attacker = side === 'player' ? p : e
  const defender = side === 'player' ? e : p
  const attackerStages = side === 'player' ? store.playerStages.value : store.enemyStages.value
  const defenderStages = side === 'player' ? store.enemyStages.value : store.playerStages.value
  const logStyle = side === 'player' ? 'log-player' : 'log-enemy'

  if (attacker.tauntTurns && attacker.tauntTurns > 0 && move.cat === 'status') {
    store.addLog(`¡La mofa impide a ${attacker.name} usar ${move.name}!`, 'log-info', attacker)
    return
  }
  if (attacker.disabledMove && move.id === attacker.disabledMove.id) {
    store.addLog(`¡${move.name} está desactivado!`, 'log-info', attacker)
    return
  }

  if (!await canAttack(attacker, store)) return

  if (attacker.furyCutterCount && move.effect !== 'fury_cutter') attacker.furyCutterCount = 0
  attacker.destinyBond = false
  attacker.snatching = false
  if (attacker.heldItem === 'choice_band') {
    attacker.choiceMove = move.name
  }
  attacker.lastMove = move
  store.attackerSide.value = side

  try {
    if (side === 'player') {
      move.pp--
    }
    store.addLog(`¡${attacker.name} usó ${move.name}!`, logStyle, attacker)

    let executableMove: Move = { ...move }

    // Charging moves logic (Solar Beam)
    const weather = store.activeBattle.value?.weather?.type
    const mechWeather = getMechanicalWeather(weather)
    const isSunny = mechWeather === WEATHER_MECHANICAL.SUN

    if (attacker.chargingMove) {
      executableMove = { ...attacker.chargingMove }
      attacker.chargingMove = null
      store.addLog(`¡${attacker.name} lanzó el ataque cargado!`, 'log-info', attacker)
    } else if (executableMove.id === 'solar_beam' && !isSunny) {
      attacker.chargingMove = { ...executableMove }
      store.addLog(`¡${attacker.name} está reuniendo luz solar!`, 'log-info', attacker)
      return
    }

    if (move.effect === 'metronome') {
      const moveNames = Object.keys(MOVE_DATA).filter(n => n !== 'Metrónomo')
      const randomName = moveNames[Math.floor(Math.random() * moveNames.length)] || 'Combate'
      const rawMoveData = (MOVE_DATA as Record<string, Partial<Move>>)[randomName] || {}
      executableMove = { ...rawMoveData, name: randomName, id: randomName.toLowerCase().replace(/\s/g, '_'), pp: 5, maxPP: 5 } as Move
      store.addLog(`¡El Metrónomo escogió ${randomName}!`, 'log-info', attacker)
    } else if (move.effect === 'mirror_move') {
      if (defender.lastMove) {
        executableMove = { ...defender.lastMove }
        store.addLog(`¡Espejo copió ${executableMove.name}!`, 'log-info', attacker)
      } else {
        store.addLog("¡Pero falló!", 'log-info', attacker)
        return
      }
    }

    const normalizeCat = (c: string | number | undefined): 'status' | 'special' | 'physical' => {
      if (c === 'Estado' || c === 'status' || c === 3) return 'status'
      if (c === 'Especial' || c === 'special' || c === 2) return 'special'
      return 'physical'
    }

    store.activeMove.value = { ...executableMove, side }
    gameBus.emit('PLAY_ATTACK_ANIM', { side, cat: normalizeCat(executableMove.cat) })

    // Sanity check
    if (!attacker.atk || !attacker.maxHp || executableMove.power === undefined) recalcPokemonStats(attacker)
    if (!defender.atk || !defender.maxHp) recalcPokemonStats(defender)

    if (!attacker.level) attacker.level = 5

    if (!attacker.atk || !defender.def || (executableMove.power === undefined && executableMove.cat !== 'status')) {
      store.addLog(`[Error] Datos faltantes: Atk:${attacker.atk} Def:${defender.def} Pwr:${executableMove.power}`, 'log-error', attacker)
    }
    if (store.activeBattle.value && !store.activeBattle.value.participants.includes(attacker.uid)) {
      store.activeBattle.value.participants.push(attacker.uid)
    }

    // Precision Check
    const moveAcc = executableMove.acc || 100
    if (moveAcc < 100 && !attacker.lockOn) {
      const accStage = attackerStages.acc || 0
      const evaStage = defenderStages.eva || 0
      const weather = store.activeBattle.value?.weather?.type
      const mechWeather = getMechanicalWeather(weather)
      const cycle = store.activeBattle.value?.isGym ? 'day' : getDayCycle()
      const isRaining = mechWeather === WEATHER_MECHANICAL.RAIN
      const isSunnyActive = mechWeather === WEATHER_MECHANICAL.SUN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'day' || cycle === 'morning'))
      const isRainActive = isRaining || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'night' || cycle === 'dusk'))
      let finalAcc = moveAcc

      const isThunderstorm = weather === 'thunderstorm'
      if ((isRainActive || isThunderstorm) && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 100
      else if (isSunnyActive && (executableMove.id === 'thunder' || executableMove.id === 'hurricane')) finalAcc = 50
      else if ((mechWeather === WEATHER_MECHANICAL.HAIL || mechWeather === WEATHER_MECHANICAL.SNOW) && executableMove.id === 'blizzard') finalAcc = 100
      else if (mechWeather === WEATHER_MECHANICAL.FOG) {
        const isMist = weather === "mist" || weather === "mist_visual"
        finalAcc = Math.floor(moveAcc * (isMist ? 0.8 : 0.6))
      }

      finalAcc = finalAcc * (1 + (0.33 * accStage)) * (1 - (0.33 * evaStage))
      if (Math.random() * 100 > finalAcc) {
        store.addLog(`¡El ataque de ${attacker.name} falló!`, 'log-info', attacker)
        return
      }
    }
    if (attacker.lockOn) attacker.lockOn = false

    if (executableMove && (executableMove.effect === undefined || executableMove.effect === null)) {
      const freshMoveData = pokemonDataProvider.getMoveData(executableMove.name)
      if (freshMoveData && freshMoveData.effect) {
        executableMove.effect = freshMoveData.effect
      }
    }

    let totalHits = 1
    if (executableMove.hits) {
      if (typeof executableMove.hits === 'number') totalHits = executableMove.hits
      else if (executableMove.hits === '2-5') {
        const rolls = [2, 2, 2, 3, 3, 3, 4, 5]
        totalHits = (rolls[Math.floor(Math.random() * rolls.length)] as number)
      }
    }

    let hitsDealt = 0
    let totalDamageDealt = 0

    for (let i = 0; i < totalHits; i++) {
      if (defender.hp <= 0) break

      const result = calculateDamage(attacker, defender, executableMove, {
        atkStages: attackerStages.atk,
        defStages: defenderStages.def,
        weather: store.activeBattle.value?.weather,
        cycle: store.activeBattle.value?.isGym ? 'day' : undefined
      })

      if (result.isNoEffect) {
        store.addLog('¡No afecta!', side === 'player' ? 'log-enemy' : 'log-player', defender)
        break
      } else {
        const damage = Math.floor(result.dmg || 0)

        if (executableMove.cat !== 'status') {
          if (totalHits === 1) store.addLog(`¡${defender.name} recibió ${damage} de daño!`, 'log-info', defender)
          totalDamageDealt += damage
        }

        if (result.isCrit && i === 0) store.addLog('¡Un golpe crítico!', logStyle, attacker)
        if (result.isNotVeryEffective && i === 0) store.addLog('No es muy eficaz...', logStyle, attacker)
        if (result.isSuperEffective && i === 0) store.addLog('¡Es muy eficaz!', logStyle, attacker)

        if (executableMove.effect === 'magnitude' && result.power) {
          const magMap: Record<number, number> = { 10: 4, 30: 5, 50: 6, 70: 7, 90: 8, 110: 9, 150: 10 }
          const mag = magMap[result.power] || 7
          store.addLog(`¡Magnitud ${mag}!`, 'log-info', defender)
        }

        defender.hp = Math.max(0, defender.hp - damage)
        if (store.activeBattle.value) store.activeBattle.value.lastDamage = damage
        hitsDealt++

        if (defender.hp <= 0) break

        if (defender.rageActive && damage > 0 && defender.hp > 0) {
          defenderStages.atk = Math.min(6, (defenderStages.atk || 0) + 1)
          store.addLog(`¡La furia de ${defender.name} está creciendo!`, 'log-info', defender)
        }

        if (executableMove.cat !== 'status' && store.animations?.handleShakeRequest) {
          await store.animations.handleShakeRequest({ side: side === 'player' ? 'enemy' : 'player' })
        }
      }
    }

    if (totalHits > 1 && hitsDealt > 0) {
      store.addLog(`¡Golpeó ${hitsDealt} veces!`, 'log-info', defender)
    }

    if (totalDamageDealt > 0) {
      if (side === 'player') {
        if (!store.gs.state.stats) {
          store.gs.state.stats = {}
        }
        const currentMax = Number(store.gs.state.stats.maxDamage) || 0
        if (totalDamageDealt > currentMax) {
          store.gs.state.stats.maxDamage = totalDamageDealt
        }
      }

      if (executableMove.recoil) {
        const recoilDiv = typeof executableMove.recoil === 'number' ? executableMove.recoil : 2
        const recoilDmg = Math.floor(totalDamageDealt / recoilDiv)
        if (recoilDmg > 0) {
          attacker.hp = Math.max(0, attacker.hp - recoilDmg)
          store.addLog(`¡${attacker.name} recibió daño por retroceso!`, 'log-info', attacker)
        }
      }
      if (executableMove.drain) {
        const heal = Math.floor(totalDamageDealt / 2)
        if (heal > 0) {
          attacker.hp = Math.min(attacker.maxHp, attacker.hp + heal)
          store.addLog(`¡${attacker.name} absorbió energía!`, 'log-info', attacker)
        }
      }
    }

    if (executableMove.selfKO) {
      attacker.hp = 0
      store.addLog(`¡${attacker.name} se sacrificó!`, 'log-info', attacker)
    }

    if (executableMove.effect && hitsDealt > 0 && store.activeBattle.value) {
      await dispatchMoveEffect(
        executableMove.effect as string,
        attacker,
        defender,
        attackerStages,
        defenderStages,
        store.addLog,
        store
      )
    }
  } catch (err) {
    logger.error('Battle', `Error in executeMoveAction: ${(err as Error).message}`)
    store.addLog(
      side === 'player' ? '¡Error en el turno del jugador!' : '¡Error en el turno del oponente!',
      'log-error',
      attacker
    )
  } finally {
    if (store.animations?.awaitTween) {
      await store.animations.awaitTween(side === 'player' ? 'attack-player' : 'attack-enemy')
    }
    store.attackerSide.value = null
    store.activeMove.value = null
  }
}

import type { MoveAction, LogFn } from '@/types/battle';
import type { BattleContext } from '@/types/battleContext';
import type { Pokemon } from '@/types/pokemon';
import { STATUS_ACTIONS } from './statusActions.ts';
import { logger } from '@/logic/utils/logger';
import { gameBus } from '@/logic/events/gameBus';
import { getItemById } from '@/data/items';

/**
 * Helper to transition and execute the release sequence when a Pokemon is sent into battle.
 */
async function callPokemonToBattle(
  side: 'player' | 'enemy',
  pokemon: Pokemon,
  logMsg: string,
  logTarget: Pokemon | string | null,
  addLogFn: LogFn,
  battleCtx: BattleContext
) {
  const fsm = battleCtx.fsm;
  const { BATTLE_STATES, BATTLE_SUBSTATES } = battleCtx;
  addLogFn(logMsg, 'log-info', logTarget);
  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_CALL);
  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.OCCUPY_SEAT);
  if (battleCtx.animations?.handleReleaseRequest) {
    await battleCtx.animations.handleReleaseRequest({ side, pokemon });
  } else {
    gameBus.emit('PLAY_SEND_OUT', { side, pokemon });
    const { gsapSleep } = await import('@/logic/utils/gsapHelpers');
    await gsapSleep(800);
  }
}

/**
 * Special Actions Dictionary.
 * Handles moves with unique logic that doesn't fit into standard stat/status/healing categories.
 */

export const SPECIAL_ACTIONS: Record<string, MoveAction> = {
  'leech_seed': (_src, tgt, _srcStages, _tgtStages, addLogFn) => {
    if (tgt.type === 'grass' || tgt.type2 === 'grass') {
      addLogFn(`¡No afecta a ${tgt.name}!`, 'log-info', tgt);
    } else if (!tgt.seeded) {
      tgt.seeded = true;
      addLogFn(`¡${tgt.name} fue infectado por drenadoras!`, 'log-info', tgt);
    } else {
      addLogFn(`¡${tgt.name} ya está infectado!`, 'log-info', tgt);
    }
  },
  'roar': async (src, tgt, _srcStages, tgtStages, addLogFn, battleCtx) => {
    const b = battleCtx?.activeBattle.value;
    if (!b) return;

    if (tgt.ability === 'Succión' || tgt.ability === 'Ventosa') {
      addLogFn(`¡La ${tgt.ability} de ${tgt.name} impidió ser arrastrado!`, 'log-info', tgt);
      return;
    }

    const isPlayerAttacking = (src.uid === b.player?.uid);
    const fsm = battleCtx.fsm;
    const { BATTLE_STATES, BATTLE_SUBSTATES } = battleCtx;

    if (isPlayerAttacking) {
      if (!b.isTrainer && !b.isGym) {
        addLogFn(`¡El ${tgt.name} salvaje huyó asustado!`, 'log-player', tgt);
        gameBus.emit('PLAY_ESCAPE_ANIM', { side: 'enemy', type: 'flee' });
        b.fled = true;
        b.over = true;
      } else {
        const team = b.enemyTeam || [];
        const aliveOthers = team.filter((p) => p.uid !== tgt.uid && p.hp > 0);
        if (aliveOthers.length === 0) {
          addLogFn('¡Pero no hay nadie para sustituirle!', 'log-info', tgt);
          return;
        }
        const randomPick = aliveOthers[Math.floor(Math.random() * aliveOthers.length)] || null;
        addLogFn(`¡${tgt.name} fue expulsado del campo!`, 'log-player', 'player');

        battleCtx.exitingEnemy.value = tgt;
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL);

        const withdrawPromise = battleCtx.animations?.handleCatchRequest
          ? battleCtx.animations.handleCatchRequest({ side: 'enemy', pokemon: tgt })
          : Promise.resolve();

        b.enemy = randomPick;
        Object.keys(tgtStages).forEach(k => {
          tgtStages[k] = 0;
        });

        await withdrawPromise;

        if (randomPick && battleCtx) {
          await callPokemonToBattle(
            'enemy',
            randomPick,
            `¡${randomPick.name} entra al combate!`,
            'enemy_trainer',
            addLogFn,
            battleCtx
          );
        }
        battleCtx.exitingEnemy.value = null;
      }
    } else {
      if (!b.isTrainer && !b.isGym) {
        addLogFn(`¡${src.name} expulsó a ${tgt.name} del combate!`, 'log-enemy', src);
        gameBus.emit('PLAY_ESCAPE_ANIM', { side: 'player', type: 'flee' });
        b.fled = true;
        b.over = true;
      } else {
        const team = b.playerTeam || [];
        const aliveOthers = team.filter((p) => p.uid !== tgt.uid && p.hp > 0);
        if (aliveOthers.length === 0) {
          addLogFn('¡Pero no surtió efecto!', 'log-enemy', src);
          return;
        }
        const randomPick = aliveOthers[Math.floor(Math.random() * aliveOthers.length)] || null;
        addLogFn(`¡${tgt.name} fue expulsado del campo!`, 'log-enemy', 'enemy_trainer');

        battleCtx.exitingPlayer.value = tgt;
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL);

        const withdrawPromise = battleCtx.animations?.handleCatchRequest
          ? battleCtx.animations.handleCatchRequest({ side: 'player', pokemon: tgt })
          : Promise.resolve();

        b.player = randomPick;
        if (randomPick) {
          b.playerTeamIndex = b.playerTeam?.findIndex(p => p.uid === randomPick.uid) ?? b.playerTeamIndex;
        }
        Object.keys(tgtStages).forEach(k => {
          tgtStages[k] = 0;
        });

        await withdrawPromise;

        if (randomPick && battleCtx) {
          await callPokemonToBattle(
            'player',
            randomPick,
            `¡Envía a ${randomPick.name}!`,
            'player',
            addLogFn,
            battleCtx
          );
        }
        battleCtx.exitingPlayer.value = null;
      }
    }
  },
  'curse': (src, tgt, srcStages, _tgtStages, addLogFn) => {
    if (src.type === 'ghost' || src.type2 === 'ghost') {
      const cost = Math.floor(src.maxHp / 2);
      src.hp = Math.max(0, src.hp - cost);
      tgt.cursed = true;
      addLogFn(`¡${src.name} sacrificó PS para maldecir a ${tgt.name}!`, 'log-info', src);
    } else {
      srcStages.atk = Math.min(6, (srcStages.atk || 0) + 1);
      srcStages.def = Math.min(6, (srcStages.def || 0) + 1);
      srcStages.spe = Math.max(-6, (srcStages.spe || 0) - 1);
      addLogFn(`¡${src.name} redujo su Velocidad pero subió su Ataque y Defensa!`, 'log-info', src);
    }
  },
  'destiny_bond': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    src.destinyBond = true;
    addLogFn(`¡${src.name} intenta llevarse a su rival al destino común!`, 'log-info', src);
  },
  'perish_song': (src, tgt, _srcStages, _tgtStages, addLogFn) => {
    if (src.perishSongCount === undefined) src.perishSongCount = 3;
    if (tgt.perishSongCount === undefined) tgt.perishSongCount = 3;
    addLogFn('¡Todos los que escucharon el canto morirán en 3 turnos!', 'log-info', src);
  },
  'transform': (src, tgt, _srcStages, _tgtStages, addLogFn) => {
    const originalName = src.name;
    if (!src.originalDitto) {
      src.originalDitto = {
        id: src.id,
        name: src.name,
        type: src.type,
        type2: src.type2,
        atk: src.atk,
        def: src.def,
        spa: src.spa,
        spd: src.spd,
        spe: src.spe,
        moves: src.moves ? src.moves.map(m => m ? { ...m } : null) : [],
        ivs: src.ivs ? { ...src.ivs } : undefined,
        isShiny: src.isShiny,
        level: src.level,
        nature: src.nature,
        ability: src.ability,
        hp: src.hp,
        maxHp: src.maxHp
      };
    }
    src.id = tgt.id;
    src.name = tgt.name;
    src.type = tgt.type;
    src.type2 = tgt.type2;
    src.atk = tgt.atk;
    src.def = tgt.def;
    src.spa = tgt.spa;
    src.spd = tgt.spd;
    src.spe = tgt.spe;
    src.isTransformed = true;
    // Copy moves but with 5 PP
    src.moves = tgt.moves.map(m => {
      if (!m) return null;
      const newM = { ...m };
      newM.pp = 5;
      newM.maxPP = 5;
      return newM;
    });
    addLogFn(`¡${originalName} se transformó en ${tgt.name}!`, 'log-info', src);
  },
  'tri_attack': (src, tgt, srcStages, tgtStages, addLogFn) => {
    const roll = Math.random();
    if (roll < 0.066) STATUS_ACTIONS.burn?.(src, tgt, srcStages, tgtStages, addLogFn);
    else if (roll < 0.132) STATUS_ACTIONS.paralyze?.(src, tgt, srcStages, tgtStages, addLogFn);
    else if (roll < 0.20) STATUS_ACTIONS.freeze?.(src, tgt, srcStages, tgtStages, addLogFn);
  },
  'focus_energy': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    src.focusEnergy = true;
    addLogFn(`¡${src.name} se está concentrando!`, 'log-info', src);
  },
  'lock_on': (src, tgt, _srcStages, _tgtStages, addLogFn) => {
    src.lockOn = true;
    addLogFn(`¡${src.name} fijó el blanco en ${tgt.name}!`, 'log-info', src);
  },
  'mirror_move': (src, tgt, _srcStages, _tgtStages, addLogFn) => {
    if (tgt.lastMove && tgt.lastMove.name !== 'Movimiento Espejo') {
      const move = tgt.lastMove;
      addLogFn(`¡Movimiento Espejo copió ${move.name}!`, 'log-info', src);
      if (move.effect) {
        logger.debug('MirrorMove', `Triggering: ${move.effect}`);
      }
    } else {
      addLogFn("¡Pero falló!", 'log-info', src);
    }
  },
  'thrash': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    if (!src.thrashTurns) {
      src.thrashTurns = 2 + Math.floor(Math.random() * 2);
      addLogFn(`¡${src.name} está entrando en un frenesí!`, 'log-info', src);
    }
  },
  'false_swipe': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    addLogFn(`¡Un ataque contenido!`, 'log-info', src);
  },
  'trap': (_src, tgt, _srcStages, _tgtStages, addLogFn) => {
    tgt.trapped = true;
    addLogFn(`¡${tgt.name} no puede escapar!`, 'log-info', tgt);
  },
  'ingrain': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    src.ingrain = true;
    addLogFn(`¡${src.name} echó raíces!`, 'log-info', src);
  },
  'endure': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    src.endure = true;
    addLogFn(`¡${src.name} aguantará el próximo golpe!`, 'log-info', src);
  },
  'protect': (src, _tgt, _srcStages, _tgtStages, addLogFn) => {
    src.protect = true;
    addLogFn(`¡${src.name} se protegió!`, 'log-info', src);
  },
  'belly_drum': (src, _tgt, srcStages, _tgtStages, addLogFn) => {
    const cost = Math.floor(src.maxHp / 2);
    if (src.hp > cost && srcStages.atk < 6) {
      src.hp -= cost;
      srcStages.atk = 6;
      addLogFn(`¡${src.name} redujo su HP y maximizó su Ataque!`, 'log-info', src);
    } else {
      addLogFn("¡Pero falló!", 'log-info', src);
    }
  },
  'teleport': async (src, _tgt, _srcStages, _tgtStages, addLogFn, battleCtx) => {
    const b = battleCtx?.activeBattle.value;
    if (!b) return;
    const isWild = !b.isTrainer && !b.isGym;

    if (isWild) {
      addLogFn(`¡${src.name} se teletransportó fuera del combate!`, 'log-info', src);
      gameBus.emit('PLAY_ESCAPE_ANIM', { side: 'enemy', type: 'teleport' });
      b.fled = true;
      b.over = true;
    } else {
      const isPlayer = (src.uid === b.player?.uid);
      const team = isPlayer ? b.playerTeam : b.enemyTeam;
      const aliveOthers = (team || []).filter((p) => p.uid !== src.uid && p.hp > 0);

      if (aliveOthers.length === 0) {
        addLogFn(`¡${src.name} intentó teletransportarse!`, 'log-info', src);
        addLogFn("¡Pero no hay nadie para sustituirle!", 'log-info', src);
      } else {
        addLogFn(`¡${src.name} se teletransportó!`, 'log-info', src);
        const fsm = battleCtx.fsm;
        const { BATTLE_STATES, BATTLE_SUBSTATES } = battleCtx;

        if (!isPlayer) {
          const randomPick = aliveOthers[Math.floor(Math.random() * aliveOthers.length)] || null;
          battleCtx.exitingEnemy.value = src;

          await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL);
          const withdrawPromise = battleCtx.animations?.handleCatchRequest
            ? battleCtx.animations.handleCatchRequest({ side: 'enemy', pokemon: src })
            : Promise.resolve();

          b.enemy = randomPick;
          await withdrawPromise;

          if (randomPick && battleCtx) {
            await callPokemonToBattle(
              'enemy',
              randomPick,
              `¡${randomPick.name} entra al combate!`,
              randomPick,
              addLogFn,
              battleCtx
            );
          }
          battleCtx.exitingEnemy.value = null;
        } else {
          battleCtx.exitingPlayer.value = src;

          await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL);
          const withdrawPromise = battleCtx.animations?.handleCatchRequest
            ? battleCtx.animations.handleCatchRequest({ side: 'player', pokemon: src })
            : Promise.resolve();

          const keys = Object.keys(battleCtx.playerStages.value) as (keyof typeof battleCtx.playerStages.value)[];
          keys.forEach(k => {
            battleCtx.playerStages.value[k] = 0;
          });

          await withdrawPromise;
          battleCtx.exitingPlayer.value = null;
          b.player = null;

          battleCtx.uiStore.isBattleSwitchForced = true;
          await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.SWITCH_MENU);
        }
      }
    }
  },
  'rapid_spin': (src, _tgt, srcStages, _tgtStages, addLogFn) => {
    let cleared = false;
    if (src.seeded) { src.seeded = false; cleared = true; }
    if (src.bound) { src.bound = 0; cleared = true; }
    if (srcStages.spikes) { srcStages.spikes = 0; cleared = true; }

    if (cleared) {
      addLogFn(`¡${src.name} se libró de las trampas girando!`, 'log-info', src);
