import { sleep } from '@/logic/utils/timeUtils'
import { gameBus } from '@/logic/events/gameBus'
import { clearVolatileStatus } from '../battleStatus.ts'
import { handleEntryAbilities } from '../battleFlow.ts'
import { runEnemyAction } from '../battleTurn.ts'
import type { BattleContext } from '@/types/battleContext'

export async function executeSwitch(ctx: BattleContext, teamIndex: number, isForced = false) {
  const { gs, activeBattle, fsm, BATTLE_STATES, BATTLE_SUBSTATES, addLog, exitingPlayer, animations, playerStages, enemyStages, persistBattle, handleFaint } = ctx

  await fsm.transition(BATTLE_STATES.REORDER_TEAM)
  await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.FIND_HEALTHY)

  const newPoke = gs.state.team[teamIndex]
  if (!newPoke || newPoke.hp <= 0) return

  await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.CHECK_ACTIVE_SEAT)
  if (!activeBattle.value) return
  const oldPoke = activeBattle.value.player

  if (oldPoke && oldPoke.uid === newPoke.uid) {
    return
  }

  if (oldPoke && oldPoke.hp > 0) {
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.SWITCHING)
    addLog(`¡Bien hecho, ${oldPoke.name}! ¡Regresa!`, 'log-info', 'player')
    addLog(`¡Envía a ${newPoke.name}!`, 'log-info', newPoke)

    exitingPlayer.value = oldPoke
    activeBattle.value.player = newPoke
    activeBattle.value.playerTeamIndex = teamIndex
    clearVolatileStatus(oldPoke)

    if (!activeBattle.value.participants.includes(newPoke.uid)) {
      activeBattle.value.participants.push(newPoke.uid)
    }

    const withdrawPromise = animations?.handleCatchRequest
      ? animations.handleCatchRequest({ side: 'player', pokemon: oldPoke })
      : Promise.resolve()

    const sendOutPromise = animations?.handleReleaseRequest
      ? animations.handleReleaseRequest({ side: 'player', pokemon: newPoke })
      : Promise.resolve()

    await Promise.all([withdrawPromise, sendOutPromise])
    exitingPlayer.value = null
  } else {
    await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_CALL)
    activeBattle.value.player = newPoke
    activeBattle.value.playerTeamIndex = teamIndex

    if (animations?.handleReleaseRequest) {
      await animations.handleReleaseRequest({ side: 'player', pokemon: newPoke })
    } else {
      await sleep(800)
    }
  }

  if (!activeBattle.value.participants.includes(newPoke.uid)) {
    activeBattle.value.participants.push(newPoke.uid)
  }

  const s = playerStages.value
  playerStages.value = { 
    ...s,
    atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0
  }

  addLog(`¡Adelante, ${newPoke.name}!`, 'log-player', newPoke)
  await sleep(400)

  if (playerStages.value.spikes > 0 && newPoke.type !== 'flying' && newPoke.type2 !== 'flying' && newPoke.ability !== 'Levitación') {
    const dmg = Math.floor(newPoke.maxHp * (playerStages.value.spikes / 8))
    newPoke.hp = Math.max(0, newPoke.hp - dmg)
    addLog(`¡${newPoke.name} recibió daño por las púas!`, 'log-info', newPoke)
    gameBus.emit('PLAY_SOUND', 'statusDamage')
  }

  if (activeBattle.value && activeBattle.value.enemy) {
    handleEntryAbilities(newPoke, activeBattle.value.enemy, playerStages.value, enemyStages.value, addLog)
  }
  persistBattle()

  if (typeof isForced !== 'undefined' && !isForced) {
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.APPLY_MOVE)
    await runEnemyAction(ctx)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EVAL_HP)

    if (activeBattle.value?.player && activeBattle.value.player.hp <= 0) {
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAYER_FAINT_SEQ)
      await handleFaint('player')
      return
    }
    if (activeBattle.value?.enemy && activeBattle.value.enemy.hp <= 0) {
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_REPLACEMENT_SEQ)
      await handleFaint('enemy')
      return
    }
  }

  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT)
}

import type { BattleContext } from '@/types/battleContext';
import { gameBus } from '@/logic/events/gameBus';

/**
 * Handles switching the active enemy Pokemon with GSAP animation.
 */
export async function executeEnemySwitch(store: BattleContext, newPokeIndex: number) {
  const b = store.activeBattle.value;
  if (!b || !b.enemyTeam || newPokeIndex === -1) return;
  const currentEnemy = b.enemy;
  if (!currentEnemy) return;

  const newPoke = b.enemyTeam[newPokeIndex];
  if (!newPoke) return;

  const fsm = store.fsm;
  const { BATTLE_STATES, BATTLE_SUBSTATES } = store;

  store.addLog(`¡${b.trainerName || 'El entrenador'} retira a ${currentEnemy.name}!`, 'log-enemy', 'enemy_trainer');

  if (store.exitingEnemy) store.exitingEnemy.value = currentEnemy;

  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL);

  const withdrawPromise = store.animations?.handleCatchRequest
    ? store.animations.handleCatchRequest({ side: 'enemy', pokemon: currentEnemy })
    : Promise.resolve();

  await withdrawPromise;

  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT);

  b.enemy = newPoke;

  // Clear stages on switch
  store.enemyStages.value = {
    atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0,
    reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0
  };

  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_CALL);
  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.OCCUPY_SEAT);
  store.addLog(`¡Envía a ${newPoke.name}!`, 'log-enemy', newPoke);

  const releasePromise = store.animations?.handleReleaseRequest
    ? store.animations.handleReleaseRequest({ side: 'enemy', pokemon: newPoke })
    : Promise.resolve();

  await releasePromise;
  if (store.exitingEnemy) store.exitingEnemy.value = null;

  // Entry hazard damage (Spikes)
  if (store.enemyStages.value.spikes && store.enemyStages.value.spikes > 0 && 
      newPoke.type !== 'flying' && newPoke.type2 !== 'flying' && newPoke.ability !== 'Levitación') {
    const dmg = Math.floor(newPoke.maxHp * (store.enemyStages.value.spikes / 8));
    newPoke.hp = Math.max(0, newPoke.hp - dmg);
    store.addLog(`¡${newPoke.name} recibió daño por las púas!`, 'log-info', newPoke);
    gameBus.emit('PLAY_SOUND', 'statusDamage');
  }
}

import { logger } from '@/logic/utils/logger'
import { useDebugStore } from '@/stores/debug'
import type { BattleContext } from '@/types/battleContext'
import type { Pokemon } from '@/types/pokemon'
import type { BattleStages } from '@/types/battle'

export function setupBattleDebug(ctx: BattleContext) {
  if (typeof window === 'undefined') return

  const debugStore = useDebugStore()
  if (!debugStore.canAccess) return

  const win = window as unknown as { 
    __VITE_DEBUG__: Record<string, unknown>;
    __VITE_DEBUG_STORE_RESOLVER__?: () => unknown;
  }

  win.__VITE_DEBUG__ = win.__VITE_DEBUG__ || {}
  win.__VITE_DEBUG__.forceFlee = async () => {
    logger.warn('DEBUG', 'Forzando huida del combate...')
    ctx.fsm.transition(ctx.BATTLE_STATES.ACTIVE_BATTLE, ctx.BATTLE_SUBSTATES.FLEE_ATTEMPT)
    await ctx.endBattle(false, true)
  }

  win.__VITE_DEBUG__.battle = {
    setPlayerStatus: (s: Pokemon['status']) => {
      const active = ctx.activeBattle.value
      if (active && active.player) {
        active.player.status = s
        active.player = { ...active.player }
        ctx.activeBattle.value = { ...active }
        logger.info('DEBUG', `Status de jugador cambiado a: ${s}`)
      }
    },
    setEnemyStatus: (s: Pokemon['status']) => {
      const active = ctx.activeBattle.value
      if (active && active.enemy) {
        active.enemy.status = s
        active.enemy = { ...active.enemy }
        ctx.activeBattle.value = { ...active }
        logger.info('DEBUG', `Status de enemigo cambiado a: ${s}`)
      }
    },
    setPlayerStage: (stat: keyof BattleStages, val: number) => { 
      ctx.playerStages.value[stat] = val 
      logger.info('DEBUG', `Stage de jugador ${stat} cambiado a: ${val}`)
    },
    setEnemyStage: (stat: keyof BattleStages, val: number) => { 
      ctx.enemyStages.value[stat] = val 
      logger.info('DEBUG', `Stage de enemigo ${stat} cambiado a: ${val}`)
    },
    setWeather: (w: string) => { 
      const active = ctx.activeBattle.value
      if (active) {
        active.weather = { type: w, turns: 5 }
        ctx.activeBattle.value = { ...active }
        logger.info('DEBUG', `Clima cambiado a: ${w}`)
      }
    },
    fullHeal: () => {
      const active = ctx.activeBattle.value
      if (active && active.player) {
        active.player.hp = active.player.maxHp
        active.player.status = null;
        (active.player as Pokemon & { confused?: number; seeded?: boolean }).confused = 0;
        (active.player as Pokemon & { confused?: number; seeded?: boolean }).seeded = false

        // Sincronizar el HP del equipo en el gameStore
        const team = ctx.gs.state.team
        if (team && team[active.playerTeamIndex]) {
          const tp = team[active.playerTeamIndex]
          if (tp) {
            tp.hp = active.player.maxHp
            tp.status = null
          }
        }

        // Forzar reactividad reasignando referencias
        active.player = { ...active.player }
        ctx.activeBattle.value = { ...active }

        logger.info('DEBUG', '¡Curación completa aplicada reactivamente al jugador!')
      }
    },
    killEnemy: async () => {
      const active = ctx.activeBattle.value
      if (active && active.enemy) {
        active.enemy.hp = 0
        // Forzar reactividad
        active.enemy = { ...active.enemy }
        ctx.activeBattle.value = { ...active }

        logger.warn('DEBUG', 'Enemigo fulminado (HP = 0), iniciando secuencia de debilitamiento/faint...')
        await ctx.handleFaint('enemy')
      }
    },
    animations: () => ctx.animations,
    store: () => {
      return win.__VITE_DEBUG_STORE_RESOLVER__?.()
    }
  }
}

import { getMechanicalWeather, WEATHER_MECHANICAL, WEATHER_REGISTRY } from '../weather/weatherRegistry.ts'
import type { Pokemon } from '@/types/pokemon'
import type { BattleStages, LogFn, BattleWeather } from '@/types/battle'
import { tickStatus, tickLeechSeed } from './battleStatus.ts'
import type { BattleContext } from '@/types/battleContext'

export function handleEntryAbilities(playerPoke: Pokemon, enemyPoke: Pokemon, playerStages: BattleStages, enemyStages: BattleStages, addLog: LogFn) {
  if (!playerPoke || !enemyPoke) return // GUARDIA CRÍTICA

  if (playerPoke.ability === 'Intimidación') {
    enemyStages.atk = Math.max(-6, enemyStages.atk - 1)
    addLog(`¡La Intimidación de ${playerPoke.name} bajó el ataque de ${enemyPoke.name}!`, 'log-info', playerPoke)
  }
  if (enemyPoke.ability === 'Intimidación') {
    playerStages.atk = Math.max(-6, playerStages.atk - 1)
    addLog(`¡La Intimidación de ${enemyPoke.name} bajó el ataque de ${playerPoke.name}!`, 'log-info', enemyPoke)
  }
}

export async function canAttack(pokemon: Pokemon, ctx: BattleContext) {
  const addLog = ctx.addLog
  if (pokemon.mustRecharge) {
    addLog(`¡${pokemon.name} tiene que recargar!`, 'log-info', pokemon)
    pokemon.mustRecharge = false
    return false
  }
  if (pokemon.flinched) {
    addLog(`¡${pokemon.name} retrocedió!`, 'log-info', pokemon)
    pokemon.flinched = false
    return false
  }
  if (pokemon.status === 'sleep') {
    if ((pokemon.sleepTurns || 0) > 0) {
      pokemon.sleepTurns = (pokemon.sleepTurns || 0) - 1
      addLog(`¡${pokemon.name} está profundamente dormido!`, 'log-info', pokemon)
      return false
    } else {
      pokemon.status = null
      addLog(`¡${pokemon.name} se despertó!`, 'log-info', pokemon)
    }
  }
  if (pokemon.status === 'freeze') {
    if (Math.random() < 0.8) {
      addLog(`¡${pokemon.name} está congelado!`, 'log-info', pokemon)
      return false
    } else {
      pokemon.status = null
      addLog(`¡${pokemon.name} se descongeló!`, 'log-info', pokemon)
    }
  }
  if (pokemon.status === 'paralysis') {
    if (Math.random() < 0.25) {
      addLog(`¡${pokemon.name} está paralizado! ¡No puede moverse!`, 'log-info', pokemon)
      return false
    }
  }
  if ((pokemon.confused || 0) > 0) {
    pokemon.confused = (pokemon.confused || 0) - 1
    if ((pokemon.confused || 0) <= 0) {
      addLog(`¡${pokemon.name} ya no está confundido!`, 'log-info', pokemon)
    } else {
      addLog(`¡${pokemon.name} está confundido!`, 'log-info', pokemon)
      if (Math.random() < 0.5) {
        const selfDmg = Math.max(1, Math.floor(((2 * pokemon.level / 5 + 2) * 40 * (pokemon.atk || 10) / (pokemon.def || 10)) / 50) + 2)
        pokemon.hp = Math.max(0, pokemon.hp - selfDmg)
        addLog(`¡Tan confundido que se hirió a sí mismo! (-${selfDmg} HP)`, 'log-info', pokemon)

        const side = pokemon.uid === ctx.activeBattle.value?.player?.uid ? 'player' : 'enemy'
        if (ctx.animations?.handleBlinkRequest) {
          await ctx.animations.handleBlinkRequest({ side })
        }
        return false
      }
    }
  }
  if (pokemon.attracted) {
    addLog(`¡${pokemon.name} está enamorado!`, 'log-info', pokemon)
    if (Math.random() < 0.5) {
      addLog(`¡La atracción le impide atacar!`, 'log-info', pokemon)
      return false
    }
  }
  return true
}

async function applyEndTurnWeather(p: Pokemon, e: Pokemon, weather: BattleWeather | null, ctx: BattleContext) {
  const mechWeather = getMechanicalWeather(weather?.type);
  const wType = (weather?.visual || weather?.type || '').toLowerCase();
  const weatherLabel = WEATHER_REGISTRY[wType]?.label || 'CLIMA';
  const promises: Promise<void>[] = []

  if (mechWeather === WEATHER_MECHANICAL.SANDSTORM) {
    const isSandImmune = (poke: Pokemon) => ['rock', 'ground', 'steel'].includes(poke.type) || ['rock', 'ground', 'steel'].includes(poke.type2 || '')
    if (!isSandImmune(p)) {
      const dmg = Math.max(1, Math.floor(p.maxHp / 16))
      p.hp = Math.max(0, p.hp - dmg)
      ctx.addLog(`¡El efecto de ${weatherLabel} daña a ${p.name}! (-${dmg} HP)`, 'log-player', p)
      if (ctx.animations?.handleBlinkRequest) {
        promises.push(ctx.animations.handleBlinkRequest({ side: 'player' }))
      }
    }
    if (!isSandImmune(e)) {
      const dmg = Math.max(1, Math.floor(e.maxHp / 16))
      e.hp = Math.max(0, e.hp - dmg)
      ctx.addLog(`¡El efecto de ${weatherLabel} daña a ${e.name}! (-${dmg} HP)`, 'log-enemy', e)
      if (ctx.animations?.handleBlinkRequest) {
        promises.push(ctx.animations.handleBlinkRequest({ side: 'enemy' }))
      }
    }
  }

  if (mechWeather === WEATHER_MECHANICAL.HAIL) {
    const isHailImmune = (poke: Pokemon) => poke.type === 'ice' || poke.type2 === 'ice'
    if (!isHailImmune(p)) {
      const dmg = Math.max(1, Math.floor(p.maxHp / 16))
      p.hp = Math.max(0, p.hp - dmg)
      ctx.addLog(`¡El efecto de ${weatherLabel} daña a ${p.name}! (-${dmg} HP)`, 'log-player', p)
      if (ctx.animations?.handleBlinkRequest) {
        promises.push(ctx.animations.handleBlinkRequest({ side: 'player' }))
      }
    }
    if (!isHailImmune(e)) {
      const dmg = Math.max(1, Math.floor(e.maxHp / 16))
      e.hp = Math.max(0, e.hp - dmg)
      ctx.addLog(`¡El efecto de ${weatherLabel} daña a ${e.name}! (-${dmg} HP)`, 'log-enemy', e)
      if (ctx.animations?.handleBlinkRequest) {
        promises.push(ctx.animations.handleBlinkRequest({ side: 'enemy' }))
      }
    }
  }

  // Poder Solar (Solar Power) Recoil
  if (mechWeather === WEATHER_MECHANICAL.SUN) {
    [p, e].forEach(poke => {
      if (poke.ability === 'Poder solar' && poke.hp > 0) {
        const dmg = Math.max(1, Math.floor(poke.maxHp / 8));
        poke.hp = Math.max(0, poke.hp - dmg);
        ctx.addLog(`¡${poke.name} sufre por el sol ardiente! (-${dmg} HP)`, 'log-info', poke);

        const side = poke.uid === ctx.activeBattle.value?.player?.uid ? 'player' : 'enemy'
        if (ctx.animations?.handleBlinkRequest) {
          promises.push(ctx.animations.handleBlinkRequest({ side }))
        }
      }
    });
  }

  if (promises.length > 0) {
    await Promise.all(promises)
  }
}

export async function applyEndTurnEffects(ctx: BattleContext) {
  const active = ctx.activeBattle.value
  const p = active?.player
  const e = active?.enemy
  if (!p || !e || !active || ctx.fsm.currentState.value !== 'ACTIVE_BATTLE') return

  const { useMapStore } = await import('@/stores/map.ts')
  const mapStore = useMapStore()

  if (active.futureSightTurns && active.futureSightTurns > 0) {
    active.futureSightTurns--
    if (active.futureSightTurns === 0) {
      const fsTarget = active.futureSightTarget
      if (fsTarget && fsTarget.hp > 0) {
        const dmg = Math.max(10, Math.floor(fsTarget.maxHp * 0.15))
        fsTarget.hp = Math.max(0, fsTarget.hp - dmg)
        ctx.addLog(`¡Se cumplió la premonición! ${fsTarget.name} recibió daño.`, 'log-info', fsTarget)

        const side = fsTarget.uid === ctx.activeBattle.value?.player?.uid ? 'player' : 'enemy'
        if (ctx.animations?.handleBlinkRequest) {
          await ctx.animations.handleBlinkRequest({ side })
        }
      }
    }
  }

  await tickStatus(p, ctx, 'player')
  await tickStatus(e, ctx, 'enemy')
  await tickLeechSeed(p, e, ctx)
  await tickLeechSeed(e, p, ctx)

  const w = active.weather
  if (w && w.turns > 0) {
    w.turns--
    if (w.turns === 0) {
      ctx.addLog(`¡El efecto de ${w.type} se desvaneció!`, 'log-info')
      w.type = mapStore.currentWeather || 'clear'
      w.turns = -1
    }
  }

  const fieldEffects = ['reflect', 'lightScreen', 'safeguard', 'mist'] as const
  const sides = [
    { stages: ctx.playerStages, name: 'Jugador', log: 'log-player' as const },
    { stages: ctx.enemyStages, name: 'Enemigo', log: 'log-enemy' as const }
  ]
  sides.forEach(side => {
    fieldEffects.forEach(effect => {
      const stages = side.stages.value
      if (stages[effect] > 0) {
        stages[effect]--
        if (stages[effect] === 0) {
          const effectLabel = effect === 'reflect' ? 'Reflejo' : effect === 'lightScreen' ? 'Pantalla Luz' : effect
          ctx.addLog(`¡El efecto de ${effectLabel} del ${side.name} se desvaneció!`, side.log)
        }
      }
    })
  })

  await applyEndTurnWeather(p, e, active.weather, ctx)

  if (p.hp <= 0) await ctx.handleFaint('player')
  if (ctx.isBattleActive.value && e.hp <= 0) await ctx.handleFaint('enemy')

  ctx.persistBattle()
  if (active && !active.over) {
    active.turnCount++
  }
}

/**
 * Battle Formulas Central Manager
 * Bridges the UI-friendly types with the Pure Math Core (battleMath.ts).
 * 
 * Refer to `@/project-standards/references/core/game_formulas_manual.md` for logic details.
 */

import { 
  getEffectiveStat as pureGetEffectiveStat,
  calculateDamagePure,
  calculateCatchRate as pureCalculateCatchRate,
  calculateEscapeChance as pureCalculateEscapeChance,
  type PurePokemon,
  type PureMove,
  type PureBattleWeather,
  type PureBattleStages
} from './battleMath.ts';
import { getDayCycle } from '../utils/timeUtils.ts';
import type { Pokemon, Move } from '@/types/pokemon';
import type { BattleStages, BattleWeather } from '@/types/battle';
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';

import { useBattleStore } from '@/stores/battle';

import type { DayPhase } from '@/logic/utils/timeUtils';

export interface DamageOptions {
  atkStages?: number;
  defStages?: number;
  weather?: BattleWeather | null;
  magnitudeSet?: boolean;
  cycle?: DayPhase;
  isGym?: boolean;
}

export interface CatchOptions {
  weather?: BattleWeather | null;
  turnCount?: number;
  cycle?: DayPhase;
  isCave?: boolean;
}

export interface EscapeOptions {
  playerStages?: Partial<BattleStages>;
  enemyStages?: Partial<BattleStages>;
  weather?: BattleWeather | null;
}

// ── Bridge Helpers ──────────────────────────────────────────────────────────

function toPurePoke(p: Pokemon): PurePokemon {
  return p as unknown as PurePokemon; // Structurally compatible
}

function toPureMove(m: Partial<Move>): PureMove {
  const resolvedId = m.id || (m.name ? pokemonDataProvider.resolveMoveId(m.name) : '');
  return {
    id: resolvedId,
    type: m.type || 'normal',
    power: m.power || 0,
    cat: m.cat || 'physical'
  };
}

function toPureWeather(w: BattleWeather | null | undefined): PureBattleWeather | null {
  if (!w) return null;
  return { type: w.type, turns: w.turns };
}

// ── Exported Functions ───────────────────────────────────────────────────────

export function getEffectiveStat(pokemon: Pokemon, statKey: keyof Pokemon, stages: Partial<BattleStages>, weather: BattleWeather | null) {
  let activeWeather = weather;
  let isGym = false;
  try {
    const battleStore = useBattleStore();
    if (battleStore.state?.isGym) {
      activeWeather = null;
      isGym = true;
    }
  } catch (e) {
    // Pinia not initialized or similar
  }

  return pureGetEffectiveStat(
    toPurePoke(pokemon),
    statKey as keyof PurePokemon,
    stages as PureBattleStages,
    toPureWeather(activeWeather),
    getDayCycle(),
    isGym
  );
}

export function getStatBreakdown(pokemon: Pokemon, statKey: keyof Pokemon, stages: Partial<BattleStages>, weather: BattleWeather | null) {
  let activeWeather = weather;
  let isGym = false;
  try {
    const battleStore = useBattleStore();
    if (battleStore.state?.isGym) {
      activeWeather = null;
      isGym = true;
    }
  } catch (e) {
    // Pinia not initialized
  }

  const final = getEffectiveStat(pokemon, statKey, stages, activeWeather);

  let base = (pokemon[statKey] as number) || 10;
  if (statKey === 'spa' && !pokemon.spa) base = pokemon.atk ?? 10;
  if (statKey === 'spd' && !pokemon.spd) base = pokemon.def ?? 10;

  const wType = activeWeather?.type ? activeWeather.type.toLowerCase() : 'clear';
  const pTypes = [pokemon.type?.toLowerCase(), pokemon.type2?.toLowerCase()];

  const WEATHER_MAP: Record<string, string> = {
    sun: 'sun', heatwave: 'sun', intense_sun: 'sun',
    rain: 'rain', storm: 'rain', heavy_rain: 'rain',
    sandstorm: 'sandstorm', dust_storm: 'sandstorm',
    snow: 'snow', hail: 'hail', blizzard: 'hail',
    fog: 'fog', mist: 'fog',
    wind: 'wind', strong_winds: 'wind',
    clear: 'clear', thunderstorm: 'clear'
  };
  const mechWeather = WEATHER_MAP[wType] || 'clear';

  let weatherMult = 1;
  if (statKey === 'def') {
    if ((mechWeather === 'snow' || mechWeather === 'hail') && pTypes.includes('ice')) {
      weatherMult = 1.5;
    }
  }
  if (statKey === 'spd') {
    if (mechWeather === 'sandstorm' && pTypes.includes('rock')) {
      weatherMult = 1.5;
    }
  }
  if (statKey === 'spe') {
    if (wType === 'coldwave' && !pTypes.includes('ice')) {
      weatherMult = 0.5;
    }
  }

  const stage = Math.max(-6, Math.min(6, (stages[statKey as keyof BattleStages] as number) || 0));
  const stageMult = stage >= 0 ? (2 + stage) / 2 : 2 / (2 - stage);

  let abilityMult = 1;
  const ab = pokemon.ability;
  const activeCycle = getDayCycle();
  const isSun = !isGym && (mechWeather === 'sun' || (mechWeather === 'clear' && (activeCycle === 'day' || activeCycle === 'morning')));
  const isRain = !isGym && (mechWeather === 'rain' || (mechWeather === 'clear' && (activeCycle === 'night' || activeCycle === 'dusk')));

  if (statKey === 'atk') {
    if (ab === 'Potencia' || ab === 'Energía pura') abilityMult = 2;
    else if (ab === 'Agallas' && pokemon.status) abilityMult = 1.5;
  }
  if (statKey === 'def') {
    if (ab === 'Escama especial' && pokemon.status) abilityMult = 1.5;
  }
  if (statKey === 'spa') {
    if (ab === 'Poder solar' && isSun) abilityMult = 1.5;
  }
  if (statKey === 'spe') {
    if (ab === 'Clorofila' && isSun) abilityMult = 2;
    else if (ab === 'Nado rápido' && isRain) abilityMult = 2;
    else if (ab === 'Ímpetu arena' && mechWeather === 'sandstorm') abilityMult = 2;
    else if (ab === 'Quitanieves' && (mechWeather === 'snow' || mechWeather === 'hail')) abilityMult = 2;
  }

  let statusMult = 1;
  if (statKey === 'spe' && pokemon.status === 'paralysis') {
    statusMult = 0.5;
  }
  if (statKey === 'atk' && pokemon.status === 'burn' && ab !== 'Agallas') {
    statusMult = 0.5;
  }

  return {
    base,
    final,
    weatherMult,
    stageMult,
    statusMult,
    abilityMult
  };
}

export function calculateDamage(attacker: Pokemon, defender: Pokemon, move: Partial<Move>, ctx: DamageOptions = {}) {
  let activeWeather = ctx.weather;
  let isGym = false;
  try {
    const battleStore = useBattleStore();
    if (battleStore.state?.isGym) {
      activeWeather = null;
      isGym = true;
    }
  } catch (e) {
    // Pinia not initialized
  }

  const pureRes = calculateDamagePure(
    toPurePoke(attacker),
    toPurePoke(defender),
    toPureMove(move),
    { 
      weather: toPureWeather(activeWeather),
      atkStages: ctx.atkStages,
      defStages: ctx.defStages,
      isGym
    },
    ctx.cycle || getDayCycle()
  );

  return {
    ...pureRes,
    dmg: pureRes.dmg,
    isNoEffect: pureRes.eff === 0
  };
}

export function calculateCatchRate(pokemon: Pokemon, rawBallType = 'poke-ball', eventCatchMult = 1, ctx: CatchOptions = {}) {
  let activeWeather = ctx.weather;
  try {
    const battleStore = useBattleStore();
    if (battleStore.state?.isGym) {
      activeWeather = null;
    }
  } catch (e) {
    // Pinia not initialized
  }

  return pureCalculateCatchRate(
    toPurePoke(pokemon),
    rawBallType,
    eventCatchMult,
    { 
      weather: toPureWeather(activeWeather),
      turnCount: ctx.turnCount,
      cycle: ctx.cycle || getDayCycle(),
      isCave: ctx.isCave
    }
  );
}

export function calculateEscapeChance(playerPoke: Pokemon, wildPoke: Pokemon, attempts: number, ctx: EscapeOptions = {}) {
  let activeWeather = ctx.weather;
  try {
    const battleStore = useBattleStore();
    if (battleStore.state?.isGym) {
      activeWeather = null;
    }
  } catch (e) {
    // Pinia not initialized
  }

  return pureCalculateEscapeChance(
    toPurePoke(playerPoke),
    toPurePoke(wildPoke),
    attempts,
    toPureWeather(activeWeather)
  );
}

