import { gsapSleep as sleep } from '@/logic/utils/gsapHelpers'
import { getEffectiveSpeed } from './battleEngine.ts'
import { decideEnemyMove, shouldEnemySwitch, findBestSwitchIndex } from './ai/battleAI.ts'
import type { BattleContext } from '@/types/battleContext'
import { logger } from '../utils/logger.ts'
import { executeMoveAction } from './actions/moveExecutor.ts'

/**
 * Handles the turn logic for a single move execution.
 */
export async function executeTurn(store: BattleContext, moveIndex: number) {
  const p = store.activeBattle.value?.player
  const e = store.activeBattle.value?.enemy

  if (!p || !e) {
    logger.warn('BattleTurn', 'Aborting turn: Player or Enemy is null', { p, e })
    return
  }

  const fsm = store.fsm
  const { BATTLE_STATES, BATTLE_SUBSTATES } = store

  // Thrash check
  if (p.thrashTurns && p.thrashTurns > 0) {
    const forcedIdx = p.moves.findIndex((m) => m?.effect === 'thrash');
    if (forcedIdx !== -1) moveIndex = forcedIdx;
  } else if (p.encoreTurns && p.encoreTurns > 0 && p.encoreMove) {
    const forcedIdx = p.moves.findIndex((m) => m?.id === p.encoreMove?.id);
    if (forcedIdx !== -1) moveIndex = forcedIdx;
  }

  const move = p.moves[moveIndex]
  if (!move || move.pp <= 0) {
    store.addLog(`¡No queda PP para ${move?.name || 'este movimiento'}!`, 'log-info', p)
    return
  }

  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.BUILD_QUEUE)

  // Determine Turn Order (Consider Priority)
  const isWild = !store.activeBattle.value?.isTrainer && !store.activeBattle.value?.isGym
  const eMove = decideEnemyMove(e, p, store.enemyStages.value, isWild)

  const pPrio = move.priority || 0
  const ePrio = eMove?.priority || 0

  const pSpe = getEffectiveSpeed(p, store.playerStages.value, { weather: store.activeBattle.value?.weather })
  const eSpe = getEffectiveSpeed(e, store.enemyStages.value, { weather: store.activeBattle.value?.weather })

  let playerFirst = true
  if (pPrio > ePrio) playerFirst = true
  else if (ePrio > pPrio) playerFirst = false
  else playerFirst = pSpe >= eSpe

  const queue: { source: 'player' | 'enemy'; action: () => Promise<void> }[] = []
  if (playerFirst) {
    queue.push({ source: 'player', action: () => runPlayerAction(store, moveIndex) })
    if (eMove) queue.push({ source: 'enemy', action: () => runEnemyAction(store) })
  } else {
    if (eMove) queue.push({ source: 'enemy', action: () => runEnemyAction(store) })
    queue.push({ source: 'player', action: () => runPlayerAction(store, moveIndex) })
  }

  console.log('[executeTurn] Queue initialized:', queue.map(q => q.source))
  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.BUILD_QUEUE)

  while (queue.length > 0) {
    console.log('[executeTurn] Loop iteration start, queue length:', queue.length)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POP_ACTION)
    const currentAction = queue.shift()
    if (!currentAction) {
      console.log('[executeTurn] No current action, breaking')
      break
    }

    console.log('[executeTurn] Running action:', currentAction.source)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.APPLY_MOVE)
    try {
      await currentAction.action()
      console.log('[executeTurn] Action completed successfully:', currentAction.source)
    } catch (e) {
      console.error('[executeTurn] Error running action:', currentAction.source, e)
    }

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EVAL_HP)

    const playerFainted = store.activeBattle.value?.player && store.activeBattle.value.player.hp <= 0
    const enemyFainted = store.activeBattle.value?.enemy && store.activeBattle.value.enemy.hp <= 0

    if (playerFainted || enemyFainted) {
      if (playerFainted && enemyFainted) {
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAYER_FAINT_SEQ)
        await store.handleFaint('player')

        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_REPLACEMENT_SEQ)
        await store.handleFaint('enemy')
      } else if (playerFainted) {
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAYER_FAINT_SEQ)
        await store.handleFaint('player')
      } else {
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_REPLACEMENT_SEQ)
        await store.handleFaint('enemy')
      }
      break;
    }

    if (store.activeBattle.value?.over) {
      console.log('[executeTurn] Battle is over, breaking')
      break;
    }

    if (queue.length > 0) {
      console.log('[executeTurn] Queue has more items, transitioning to EVAL_CONTINUE')
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EVAL_CONTINUE)
      await sleep(400)
    } else {
      console.log('[executeTurn] Queue is empty, finishing loop')
    }
  }

  if (store.activeBattle.value?.over) {
    if (store.activeBattle.value.fled) {
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAY_ESCAPE_ANIM)
      if (store.animations?.awaitTween) {
        await store.animations.awaitTween('escape-enemy')
      } else {
        await sleep(800)
      }
      await store.endBattle(false, true)
    }
    return
  }

  if (store.persistBattle) store.persistBattle()
}

export async function runPlayerAction(store: BattleContext, moveIndex: number) {
  const p = store.activeBattle.value?.player
  if (!p) return

  const move = p.moves[moveIndex]
  if (!move) return

  await executeMoveAction(store, 'player', move)
}

export async function runEnemyAction(store: BattleContext) {
  const p = store.activeBattle.value?.player
  const e = store.activeBattle.value?.enemy
  if (!p || !e || e.hp <= 0) return

  const isWild = !store.activeBattle.value?.isTrainer && !store.activeBattle.value?.isGym

  if (!isWild && store.activeBattle.value && shouldEnemySwitch(e, p, store.activeBattle.value.enemyTeam)) {
    const bestIdx = findBestSwitchIndex(store.activeBattle.value.enemyTeam || [], p, e.uid)
    if (store.activeBattle.value.enemyTeam && bestIdx !== -1) {
      const { executeEnemySwitch } = await import('./actions/switchActions.ts')
      await executeEnemySwitch(store, bestIdx)
      return
    }
  }

  if ((store.activeBattle.value?.isGym) && e.hp < (e.maxHp * 0.25) && !store.activeBattle.value.enemyUsedItem) {
    store.activeBattle.value.enemyUsedItem = true
    const heal = Math.floor(e.maxHp * 0.5)
    e.hp = Math.min(e.maxHp, e.hp + heal)
    store.addLog(`¡El Líder usó una Hiper Poción!`, 'log-enemy', 'enemy_trainer')
    store.addLog(`¡${e.name} recuperó salud!`, 'log-info', e, 'enemy')
    return
  }

  const enemyMove = decideEnemyMove(e, p, store.playerStages.value, isWild)
  if (!enemyMove) {
    store.addLog(`¡${e.name} no tiene más PP y usa Forcejeo!`, 'log-enemy', e)
    return
  }

  await executeMoveAction(store, 'enemy', enemyMove)
}

import { FIRE_RED_MAPS } from '@/data/maps';

/**
 * Resolves the active biome and tags for a given location ID.
 */
export function getMapBiomeAndTags(locationId: string): { activeBiome: string; mapTags: string[] } {
  const map = FIRE_RED_MAPS.find(m => m.id === locationId);
  let activeBiome = 'isPlains';
  const mapTags: string[] = [];
  if (map) {
    const hierarchy = [
      'isArctic', 'isIndoors', 'isUrban', 'isVolcanic', 'isCrystalCave', 'isCave',
      'isDesert', 'isSwamp', 'isMountain',
      'isCoastal', 'isForest', 'isPlains'
    ];
    for (const key of hierarchy) {
      if ((map as Record<string, unknown>)[key]) {
        activeBiome = key;
        break;
      }
    }
    for (const key of hierarchy) {
      if ((map as Record<string, unknown>)[key]) {
        mapTags.push(key);
      }
    }
  }
  return { activeBiome, mapTags };
}

import type {
  PurePokemon,
  PureMove,
  PureBattleWeather,
  PureBattleStages,
  PureDamageOptions,
  PureDamageResult
} from './battleMathTypes.ts';
import { TYPE_CHART, type PokemonType } from '../../data/types.ts';

export const CURRENT_GENERATION = 2;
export const ACTIVE_RULE_SET = 2;

export const STAGE_MULTIPLIERS_STAT: Record<string, number> = {
  '-6': 0.25, '-5': 0.28, '-4': 0.33, '-3': 0.40, '-2': 0.50, '-1': 0.66,
  '0': 1.0, '1': 1.5, '2': 2.0, '3': 2.5, '4': 3.0, '5': 3.5, '6': 4.0
};

export const STAGE_MULTIPLIERS_ACC: Record<string, number> = {
  '-6': 0.33, '-5': 0.37, '-4': 0.43, '-3': 0.50, '-2': 0.60, '-1': 0.75,
  '0': 1.0, '1': 1.33, '2': 1.66, '3': 2.0, '4': 2.33, '5': 2.66, '6': 3.0
};


const WEATHER_KEYS = { SUN: 'sun', RAIN: 'rain', SANDSTORM: 'sandstorm', SNOW: 'snow', HAIL: 'hail', FOG: 'fog', WIND: 'wind', CLEAR: 'clear' } as const;

const WEATHER_MAP: Record<string, string> = {
  sun: 'sun', heatwave: 'sun', intense_sun: 'sun',
  rain: 'rain', storm: 'rain', heavy_rain: 'rain',
  sandstorm: 'sandstorm', dust_storm: 'sandstorm',
  snow: 'snow', hail: 'hail', blizzard: 'hail',
  fog: 'fog', mist: 'fog',
  wind: 'wind', strong_winds: 'wind',
  clear: 'clear', thunderstorm: 'clear'
};

// ── Pure Helper Functions ──────────────────────────────────────────────────────

function getMechWeather(type: string | null | undefined): string {
  if (!type || type === 'clear' || type === 'null') return WEATHER_KEYS.CLEAR;
  return WEATHER_MAP[type.toLowerCase()] ?? 'unknown';
}

function getTypeEff(moveType: string | undefined, defType: string | undefined, scrapy = false): number {
  if (!moveType || !defType) return 1;
  if (scrapy && defType === 'ghost' && (moveType === 'normal' || moveType === 'fighting')) return 1;
  const row = TYPE_CHART[moveType.toLowerCase() as PokemonType];
  return row ? (row[defType.toLowerCase() as PokemonType] ?? 1) : 1;
}

function getCombinedEff(moveType: string, defender: PurePokemon, attacker: PurePokemon | null = null, weather: string | null = null): number {
  const scrapy = attacker?.ability === 'Intrépido';
  let eff = getTypeEff(moveType, defender.type, scrapy);
  if (defender.type2) eff *= getTypeEff(moveType, defender.type2, scrapy);

  // Delta Stream (Strong Winds): Remove Flying-type weaknesses
  const mechWeather = getMechWeather(weather);
  if (mechWeather === 'wind' && (defender.type === 'flying' || defender.type2 === 'flying')) {
    const isSuperEffectiveAgainstFlying = (t: string) => ['electric', 'ice', 'rock'].includes(t.toLowerCase());
    if (isSuperEffectiveAgainstFlying(moveType) && eff > 1) {
      eff = 1; // Neutralize super-effective hits against flying types
    }
  }

  return eff;
}

// ── Exported Pure Functions ────────────────────────────────────────────────────

/**
 * Determines the category of a move based on Generation rules.
 */
export function getMoveCategory(move: PureMove): 'status' | 'physical' | 'special' {
  if (ACTIVE_RULE_SET === 2) {
    const physicalTypes = ['normal', 'fighting', 'flying', 'poison', 'ground', 'rock', 'bug', 'ghost', 'steel'];
    const specialTypes  = ['fire', 'water', 'grass', 'electric', 'psychic', 'ice', 'dragon', 'dark'];
    if (move.cat === 'status') return 'status';
    if (move.type && physicalTypes.includes(move.type)) return 'physical';
    if (move.type && specialTypes.includes(move.type))  return 'special';
  }
  return move.cat ?? 'physical';
}

/**
 * Returns ability multiplier for offensive calculations.
 */
export function getAbilityMultiplier(attacker: PurePokemon, move: PureMove, weather?: PureBattleWeather | null): { mult: number; triggeredAbility: string | null } {
  let mult = 1;
  let triggeredAbility: string | null = null;
  const ab = attacker.ability;
  const power = move.power ?? 0;
  const moveType = move.type ?? 'normal';

  const isLowHp = (attacker.hp ?? 0) <= ((attacker.maxHp ?? 1) / 3);
  if (isLowHp) {
    if (ab === 'Mar llamas' && moveType === 'fire')  { mult *= 1.5; triggeredAbility = ab; }
    if (ab === 'Torrente'   && moveType === 'water') { mult *= 1.5; triggeredAbility = ab; }
    if (ab === 'Espesura'   && moveType === 'grass') { mult *= 1.5; triggeredAbility = ab; }
    if (ab === 'Enjambre'   && moveType === 'bug')   { mult *= 1.5; triggeredAbility = ab; }
  }
  if (ab === 'Agallas' && attacker.status && getMoveCategory(move) === 'physical') {
    mult *= 1.5; triggeredAbility = ab;
  }
  if (ab === 'Experto' && power > 0 && power <= 60) {
    mult *= 1.5; triggeredAbility = ab;
  }

  // Weather-dependent abilities
  if (weather && weather.turns !== 0) {
    const mech = getMechWeather(weather.type);
    if (ab === 'Fuerza arena' && mech === WEATHER_KEYS.SANDSTORM) {
      if (moveType === 'ground' || moveType === 'rock' || moveType === 'steel') {
        mult *= 1.3; triggeredAbility = ab;
      }
    }
  }

  return { mult, triggeredAbility };
}

/**
 * Returns the effective stat of a pokemon considering stages, weather, status, and abilities.
 */
export function getEffectiveStat(
  pokemon: PurePokemon,
  statKey: keyof PurePokemon,
  stages: PureBattleStages,
  weather: PureBattleWeather | null,
  dayCycle: 'morning' | 'day' | 'dusk' | 'night' = 'day',
  isGym: boolean = false
): number {
  const mechWeather = isGym ? 'clear' : getMechWeather(weather?.type);

  let baseVal = (pokemon[statKey] as number) || 10;
  if (statKey === 'spa' && !pokemon.spa) baseVal = pokemon.atk ?? 10;
  if (statKey === 'spd' && !pokemon.spd) baseVal = pokemon.def ?? 10;

  // Weather modifiers on base stat
  if (statKey === 'def') {
    if ((mechWeather === WEATHER_KEYS.SNOW || mechWeather === WEATHER_KEYS.HAIL) && (pokemon.type === 'ice' || pokemon.type2 === 'ice')) {
      baseVal = Math.floor(baseVal * 1.5);
    }
  }
  if (statKey === 'spd') {
    if (mechWeather === WEATHER_KEYS.SANDSTORM && (pokemon.type === 'rock' || pokemon.type2 === 'rock')) {
      baseVal = Math.floor(baseVal * 1.5);
    }
  }

  // Stage multiplier
  const stage = Math.max(-6, Math.min(6, (stages[statKey as keyof PureBattleStages] as number) || 0));
  const stageMult = (STAGE_MULTIPLIERS_STAT[String(stage)] as number) ?? 1.0;
  let val = Math.floor(baseVal * stageMult);

  // Weather: Coldwave speed reduction (50% for non-ice)
  if (!isGym && statKey === "spe" && weather?.type === "coldwave" && pokemon.type !== "ice" && pokemon.type2 !== "ice") {
    val = Math.floor(val * 0.5);
  }

  // Ability + status modifiers
  const ab = pokemon.ability;
  const isSun  = !isGym && (mechWeather === WEATHER_KEYS.SUN  || (mechWeather === WEATHER_KEYS.CLEAR && (dayCycle === 'day' || dayCycle === 'morning')));
  const isRain  = !isGym && (mechWeather === WEATHER_KEYS.RAIN || (mechWeather === WEATHER_KEYS.CLEAR && (dayCycle === 'night' || dayCycle === 'dusk')));

  if (statKey === 'atk') {
    let abilMult = 1;
    if (ab === 'Potencia' || ab === 'Energía pura') abilMult *= 2;
    if (ab === 'Agallas' && pokemon.status) abilMult *= 1.5;
    val = Math.floor(val * abilMult);
    if (pokemon.status === 'burn' && ab !== 'Agallas') val = Math.floor(val * 0.5);
  }
  if (statKey === 'def') {
    if (ab === 'Escama especial' && pokemon.status) val = Math.floor(val * 1.5);
  }
  if (statKey === 'spa') {
    if (ab === 'Poder solar' && isSun) val = Math.floor(val * 1.5);
  }
  if (statKey === 'spe') {
    let abilMult = 1;
    if (ab === 'Clorofila'   && isSun)  abilMult *= 2;
    if (ab === 'Nado rápido' && isRain) abilMult *= 2;
    if (ab === 'Ímpetu arena' && mechWeather === WEATHER_KEYS.SANDSTORM) abilMult *= 2;
    if (ab === 'Quitanieves'  && (mechWeather === WEATHER_KEYS.SNOW || mechWeather === WEATHER_KEYS.HAIL)) abilMult *= 2;
    val = Math.floor(val * abilMult);
    if (pokemon.status === 'paralysis') val = Math.floor(val * 0.5);
  }

  return Math.max(1, val);
}

/**
 * Central Damage Formula (pure, no external deps).
 * NOTE: move.power and move.type MUST be provided; this function does NOT
 * call any data provider. Callers are responsible for resolving move data.
 */
export function calculateDamagePure(
  attacker: PurePokemon,
  defender: PurePokemon,
  move: PureMove,
  ctx: PureDamageOptions = {},
  dayCycle: 'morning' | 'day' | 'dusk' | 'night' = 'day',
  randomFactor?: number,
  forceCrit?: boolean
): PureDamageResult {
  const { atkStages = 0, defStages = 0, weather = null } = ctx;

  const power    = move.power ?? 0;
  const moveType = move.type  ?? 'normal';
  const moveCat  = getMoveCategory({ ...move, type: moveType });

  if (move.fixedDmg !== undefined) return { dmg: move.fixedDmg, eff: 1, isNoEffect: false };
  if (move.levelDmg)               return { dmg: attacker.level, eff: 1, isNoEffect: false };
  if (move.halfHP) {
    const dmg = Math.max(1, Math.floor((defender.hp ?? 1) / 2));
    return { dmg, eff: 1, isNoEffect: false };
  }

  const eff = getCombinedEff(moveType, defender, attacker, weather?.type);

  if (power === 0) return { dmg: 0, eff, isNoEffect: eff === 0 };

  const mechWeather = getMechWeather(weather?.type);
  const isPhysical = moveCat === 'physical';

  // Stages per stat
  const aStages: PureBattleStages = { [isPhysical ? 'atk' : 'spa']: atkStages };
  const dStages: PureBattleStages = { [isPhysical ? 'def' : 'spd']: defStages };

  // Critical hit
  let critRate = ACTIVE_RULE_SET === 2 ? 0.0625 : (attacker.heldItem === 'scope_lens' ? 0.12 : 0.06);
  if (attacker.focusEnergy) critRate = 0.25;
  let isCrit = forceCrit !== undefined ? forceCrit : (Math.random() < critRate);
  if (defender.ability === 'Caparazón' || defender.ability === 'Armadura Batalla') isCrit = false;

  if (isCrit) {
    const aKey = isPhysical ? 'atk' : 'spa';
    const dKey = isPhysical ? 'def' : 'spd';
    if ((aStages[aKey as keyof PureBattleStages] ?? 0) < 0) aStages[aKey as keyof PureBattleStages] = 0;
    if ((dStages[dKey as keyof PureBattleStages] ?? 0) > 0) dStages[dKey as keyof PureBattleStages] = 0;
  }

  const critMult = isCrit ? (ACTIVE_RULE_SET === 2 ? 2.0 : 1.5) : 1;

  const isGym = ctx.isGym || false;
  const A = getEffectiveStat(attacker, isPhysical ? 'atk' : 'spa', aStages, weather, dayCycle, isGym);
  const D = getEffectiveStat(defender, isPhysical ? 'def' : 'spd', dStages, weather, dayCycle, isGym);

  const baseDamage = Math.floor(((2 * attacker.level / 5 + 2) * power * A / D) / 50) + 2;

  // Ability multiplier (attacker)
  let { mult: finalAbilityMult, triggeredAbility } = getAbilityMultiplier(attacker, { ...move, type: moveType, power, cat: moveCat }, weather);

  // Defender: Sebo
  if (defender.ability === 'Sebo' && (moveType === 'fire' || moveType === 'ice')) {
    finalAbilityMult *= 0.5;
    triggeredAbility = 'Sebo';
  }

  // Item boost
  let itemMult = 1;
  if (attacker.heldItem) {
    const h = attacker.heldItem;
    const typeBoosters: Record<string, string> = {
      charcoal: 'fire',
      magnet: 'electric',
      mystic_water: 'water',
      miracle_seed: 'grass',
      black_belt: 'fighting',
      twisted_spoon: 'psychic',
      spell_tag: 'ghost',
      silver_powder: 'bug',
      poison_barb: 'poison'
    };
    if (typeBoosters[h] === moveType) itemMult = 1.2;
    if (h === 'choice_band' && moveCat === 'physical') itemMult = 1.5;
  }

  // STAB
  let stab = (moveType === attacker.type || moveType === attacker.type2) ? 1.5 : 1;
  if (attacker.ability === 'Adaptable' && stab > 1) stab = 2;

  // Weather multiplier
  let weatherMult = 1;
  if (!isGym && weather && weather.turns !== 0) {
    const wType = (weather.visual || weather.type).toLowerCase();
    if (mechWeather === WEATHER_KEYS.SUN) {
      if (moveType === 'fire')  weatherMult = 1.5;
      if (moveType === 'water') weatherMult = (wType === 'heatwave') ? 0 : 0.5; // Heatwave evaporates water
    } else if (mechWeather === WEATHER_KEYS.RAIN) {
      if (moveType === 'water') weatherMult = 1.5;
      if (moveType === 'fire')  weatherMult = (wType === 'storm' || wType === 'heavy_rain') ? 0 : 0.5; // Extreme rain extinguishes fire
    } else if (wType === 'thunderstorm') {
      if (moveType === 'electric' || moveType === 'dragon') weatherMult = 1.5;
    }
  }

  // Solar Beam power reduction (Sandstorm, Snow, Hail, Fog, Rain, Thunderstorm)
  if (move.id === 'solar_beam' && weather && weather.turns !== 0) {
    const isSun = mechWeather === WEATHER_KEYS.SUN;
    const isClear = mechWeather === WEATHER_KEYS.CLEAR && weather.type !== 'thunderstorm';
    if (!isGym && !isSun && !isClear) {
      weatherMult *= 0.5;
    }
  }

  // Day cycle bonus on clear weather
  if (!isGym && weatherMult === 1 && (mechWeather === WEATHER_KEYS.CLEAR || !weather)) {
    if ((dayCycle === 'day' || dayCycle === 'morning') && moveType === 'fire')  weatherMult = 1.2;
    if ((dayCycle === 'night' || dayCycle === 'dusk')  && moveType === 'water') weatherMult = 1.2;
  }

  const random = randomFactor ?? (0.85 + Math.random() * 0.15);

  const finalDmg = (eff > 0 && weatherMult > 0)
    ? Math.max(1, Math.floor(baseDamage * stab * finalAbilityMult * eff * random * critMult * weatherMult * itemMult))
    : 0;

  return {
    dmg: finalDmg, eff, stab, power, isCrit,
    isSuperEffective:    eff > 1,
    isNotVeryEffective:  eff < 1 && eff > 0,
    isNoEffect:          eff === 0,
    triggeredAbility
  };
}

import { MOVE_DATA } from '@/data/moves';
import { getMechanicalWeather, WEATHER_MECHANICAL } from '@/logic/weather/weatherRegistry';
import { calculateDamagePure, type PurePokemon, type PureMove } from '@/logic/battle/battleMath';
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';
import type { Move } from '@/types/pokemon';

/**
 * Gets modifier info for a move based on weather and cycle.
 */
export function calculateMoveModifierInfo(
  move: Move,
  weather: string | undefined,
  cycle: string
): { type: string; text: string } | null {
  const m = move;
  const mechWeather = getMechanicalWeather(weather);

  const isRaining = mechWeather === WEATHER_MECHANICAL.RAIN;
  const isSunny = mechWeather === WEATHER_MECHANICAL.SUN;
  const isSnowing = mechWeather === WEATHER_MECHANICAL.SNOW || mechWeather === WEATHER_MECHANICAL.HAIL;
  const isDayTime = cycle === 'day' || cycle === 'morning';
  const isNightTime = cycle === 'night' || cycle === 'dusk';

  const isSunActive = isSunny || (mechWeather === WEATHER_MECHANICAL.CLEAR && isDayTime);
  const isRainActive = isRaining || (mechWeather === WEATHER_MECHANICAL.CLEAR && isNightTime);

  const moveId = m.id || (m.name ? pokemonDataProvider.resolveMoveId(m.name) : '');

  if (moveId === 'thunder' || moveId === 'hurricane') {
    const isThunderstorm = weather?.toLowerCase() === 'thunderstorm';
    if (isSunny) return { type: 'penalized', text: 'Penalizado por Clima Soleado (Precisión 50%)' };
    if (isRaining || isThunderstorm) return { type: 'boosted', text: `Potenciado por ${isThunderstorm ? 'Tormenta Eléctrica' : 'Lluvia'} (¡No falla!)` };
  }

  if (moveId === 'blizzard') {
    if (isSnowing) return { type: 'boosted', text: 'Potenciado por Granizo/Ventisca (¡No falla!)' };
  }

  // Charging Moves
  if (moveId === 'solar_beam' || moveId === 'solar_blade') {
    if (mechWeather !== WEATHER_MECHANICAL.CLEAR && !isSunActive) return { type: 'penalized', text: 'Penalizado por clima adverso (0.5x y requiere carga)' };
    if (isSunActive) return { type: 'boosted', text: 'Carga instantánea por Sol/Horario.' };
  }

  // Weather Ball
  if (moveId === 'weather_ball') {
    if (mechWeather !== WEATHER_MECHANICAL.CLEAR) return { type: 'boosted', text: 'Tipo y potencia adaptados al clima (100 BP).' };
  }

  // General Accuracy Warning (Fog)
  if (mechWeather === WEATHER_MECHANICAL.FOG) {
    const isMist = weather?.toLowerCase() === 'mist';
    const label = isMist ? 'Bruma' : 'Niebla';
    const penalty = isMist ? '80%' : '60%' ;
    return { type: 'penalized', text: `Precisión reducida al ${penalty} por ${label}.` };
  }

  if (m.cat === 'status') return null;

  // Elemental Multipliers
  if (m.type === 'fire') {
    const isExtreme = weather?.toLowerCase() === 'storm' || weather?.toLowerCase() === 'thunderstorm' || weather?.toLowerCase() === 'heavy_rain';
    if (isRaining) return { type: 'penalized', text: `Penalizado por ${isExtreme ? 'Tormenta' : 'Lluvia'} (${isExtreme ? 'x0' : '0.5x'})` };
    if (isSunActive) return { type: 'boosted', text: `Potenciado por ${isSunny ? 'Sol' : 'Horario'} (1.5x/1.2x)` };
  }
  if (m.type === 'water') {
    const isExtreme = weather?.toLowerCase() === 'heatwave' || weather?.toLowerCase() === 'intense_sun';
    if (isSunny) return { type: 'penalized', text: `Penalizado por ${isExtreme ? 'Calor Extremo' : 'Sol'} (${isExtreme ? 'x0' : '0.5x'})` };
    if (isRainActive) return { type: 'boosted', text: `Potenciado por ${isRaining ? 'Lluvia' : 'Horario'} (1.5x/1.2x)` };
  }
  return null;
}

/**
 * Calculates move power details.
 */
export function calculateMovePower(
  move: Move,
  attacker: PurePokemon,
  defender: PurePokemon | null,
  weather: { type: string; turns: number } | null,
  mechWeather: string,
  cycle: 'morning' | 'day' | 'dusk' | 'night' | undefined,
  basePower: number,
  moveType: string
): { base: number; final: number; list: { label: string; mult: number }[]; class: string } {
  let currentPower = basePower;
  const powerList: { label: string; mult: number }[] = [];

  if (basePower > 0) {
    // STAB
    if (moveType === attacker.type?.toLowerCase() || moveType === attacker.type2?.toLowerCase()) {
      const stab = attacker.ability === 'Adaptable' ? 2.0 : 1.5;
      powerList.push({ label: `STAB (${move.type})`, mult: stab });
      currentPower *= stab;
    }

    // Weather
    if (weather && weather.turns !== 0) {
      const wType = weather.type.toLowerCase();
      let weatherMult = 1;
      if (mechWeather === WEATHER_MECHANICAL.SUN) {
        if (moveType === 'fire') weatherMult = 1.5;
        if (moveType === 'water') weatherMult = (wType === 'heatwave') ? 0 : 0.5;
      } else if (mechWeather === WEATHER_MECHANICAL.RAIN) {
        if (moveType === 'water') weatherMult = 1.5;
        if (moveType === 'fire') weatherMult = (wType === 'storm' || wType === 'heavy_rain') ? 0 : 0.5;
        if (moveType === 'electric' || moveType === 'dragon') weatherMult = 1.5;
      } else if (wType === 'thunderstorm') {
        if (moveType === 'electric' || moveType === 'dragon') weatherMult = 1.5;
      }

      if (weatherMult !== 1) {
        powerList.push({ label: `Clima (${weather.type})`, mult: weatherMult });
        currentPower *= weatherMult;
      }
    }

    // Solar Beam
    if (move.id === 'solar_beam' && weather && weather.turns !== 0) {
      const isSun = mechWeather === WEATHER_MECHANICAL.SUN;
      const isClear = mechWeather === WEATHER_MECHANICAL.CLEAR && weather.type !== 'thunderstorm';
      if (!isSun && !isClear) {
        powerList.push({ label: 'Rayo Solar Clima', mult: 0.5 });
        currentPower *= 0.5;
      }
    }

    // Day cycle
    if (weather && (mechWeather === WEATHER_MECHANICAL.CLEAR || !weather)) {
      let cycleMult = 1;
      if ((cycle === 'day' || cycle === 'morning') && moveType === 'fire') cycleMult = 1.2;
      if ((cycle === 'night' || cycle === 'dusk') && moveType === 'water') cycleMult = 1.2;
      if (cycleMult !== 1) {
        powerList.push({ label: `Horario (${cycle})`, mult: cycleMult });
        currentPower *= cycleMult;
      }
    }

    // Attacker Ability
    let abilMult = 1;
    const isLowHp = (attacker.hp ?? 0) <= ((attacker.maxHp ?? 1) / 3);
    if (isLowHp) {
      if (attacker.ability === 'Mar llamas' && moveType === 'fire') abilMult = 1.5;
      if (attacker.ability === 'Torrente' && moveType === 'water') abilMult = 1.5;
      if (attacker.ability === 'Espesura' && moveType === 'grass') abilMult = 1.5;
      if (attacker.ability === 'Enjambre' && moveType === 'bug') abilMult = 1.5;
    }
    if (attacker.ability === 'Experto' && basePower <= 60) {
      abilMult *= 1.5;
    }
    if (weather && weather.turns !== 0 && attacker.ability === 'Fuerza arena' && mechWeather === WEATHER_MECHANICAL.SANDSTORM) {
      if (moveType === 'ground' || moveType === 'rock' || moveType === 'steel') {
        abilMult *= 1.3;
      }
    }
    if (abilMult !== 1) {
      powerList.push({ label: `Habilidad (${attacker.ability})`, mult: abilMult });
      currentPower *= abilMult;
    }

    // Defender Ability
    if (defender && defender.ability === 'Sebo' && (moveType === 'fire' || moveType === 'ice')) {
      powerList.push({ label: 'Habilidad Rival (Sebo)', mult: 0.5 });
      currentPower *= 0.5;
    }

    // Held Item
    if (attacker.heldItem) {
      const h = attacker.heldItem;
      const typeBoosters: Record<string, string> = {
        charcoal: 'fire',
        magnet: 'electric',
        mystic_water: 'water',
        miracle_seed: 'grass',
        black_belt: 'fighting',
        twisted_spoon: 'psychic',
        spell_tag: 'ghost',
        silver_powder: 'bug',
        poison_barb: 'poison'
      };
      let itemMult = 1;
      if (typeBoosters[h] === moveType) itemMult = 1.2;

      if (h === 'choice_band') {
        if (move.cat === 'physical') {
          itemMult = 1.5;
        } else {
          powerList.push({ label: 'Objeto (choice_band - Solo Físico)', mult: 1.0 });
        }
      }

      if (itemMult !== 1) {
        powerList.push({ label: `Objeto (${h})`, mult: itemMult });
        currentPower *= itemMult;
      }
    }
  }

  const finalPower = Math.max(1, Math.round(currentPower));
  return {
    base: basePower,
    final: finalPower,
    list: powerList,
    class: finalPower > basePower ? 'boosted' : (finalPower < basePower ? 'penalized' : '')
  };
}

/**
 * Calculates move accuracy details.
 */
export function calculateMoveAccuracy(
  move: Move,
  weather: { type: string; turns: number } | null,
  mechWeather: string,
  cycle: 'morning' | 'day' | 'dusk' | 'night' | undefined,
  baseAcc: number,
  accStage: number,
  evaStage: number
): { base: number; final: number; list: { label: string; mult: number | string }[]; class: string } {
  let currentAcc = baseAcc;
  const accList: { label: string; mult: number | string }[] = [];

  if (baseAcc > 0 && baseAcc < 1000) {
    const isSunActive = mechWeather === WEATHER_MECHANICAL.SUN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'day' || cycle === 'morning'));
    const isRainActive = mechWeather === WEATHER_MECHANICAL.RAIN || (mechWeather === WEATHER_MECHANICAL.CLEAR && (cycle === 'night' || cycle === 'dusk'));
    const isThunderstorm = weather?.type === 'thunderstorm';

    if ((isRainActive || isThunderstorm) && (move.id === 'thunder' || move.id === 'hurricane')) {
      currentAcc = 100;
      accList.push({ label: 'Lluvia (¡No falla!)', mult: '100%' });
    } else if (isSunActive && (move.id === 'thunder' || move.id === 'hurricane')) {
      currentAcc = 50;
      accList.push({ label: 'Sol (Precisión 50%)', mult: '0.5' });
    } else if ((mechWeather === WEATHER_MECHANICAL.HAIL || mechWeather === WEATHER_MECHANICAL.SNOW) && move.id === 'blizzard') {
      currentAcc = 100;
      accList.push({ label: 'Nieve (¡No falla!)', mult: '100%' });
    } else if (mechWeather === WEATHER_MECHANICAL.FOG) {
      const isMist = weather?.type === "mist" || weather?.type === "mist_visual";
      const factor = isMist ? 0.8 : 0.6;
      currentAcc = Math.floor(baseAcc * factor);
      accList.push({ label: `Niebla/Bruma`, mult: factor });
    }

    if (accStage !== 0) {
      const factor = 1 + (0.33 * accStage);
      accList.push({ label: `Rango Prec. (${accStage > 0 ? '+' : ''}${accStage})`, mult: factor });
      currentAcc *= factor;
    }

    if (evaStage !== 0) {
      const factor = 1 - (0.33 * evaStage);
      accList.push({ label: `Rango Eva. Rival (${evaStage > 0 ? '+' : ''}${evaStage})`, mult: factor });
      currentAcc *= factor;
    }
  }

  const finalAccuracy = Math.max(0, Math.min(100, Math.round(currentAcc)));
  return {
    base: baseAcc,
    final: baseAcc === 1000 ? 1000 : finalAccuracy,
    list: accList,
    class: baseAcc === 1000 ? '' : (finalAccuracy > baseAcc ? 'boosted' : (finalAccuracy < baseAcc ? 'penalized' : ''))
  };
}

/**
 * Calculates crit chance.
 */
export function calculateCritChance(
  attacker: PurePokemon,
  defender: PurePokemon | null
): { value: string; class: string } {
  let critRate = 0.0625;
  if (attacker.heldItem === 'scope_lens') critRate = 0.12;
  if (attacker.focusEnergy) critRate = 0.25;
  if (defender && (defender.ability === 'Caparazón' || defender.ability === 'Armadura Batalla')) {
    critRate = 0;
  }

  const critVal = (critRate * 100).toFixed(2).replace('.00', '');
  const critClass = critRate > 0.0625 ? 'boosted' : (critRate === 0 ? 'penalized' : 'neutral');

  return {
    value: critVal,
    class: critClass
  };
}

/**
 * Calculates effectiveness and estimated damage range.
 */
export function calculateMoveEffectivenessAndDamage(
  move: Move,
  md: { type?: string; cat?: string; power?: number; acc?: number },
  attacker: PurePokemon,
  defender: PurePokemon | null,
  weather: { type: string; turns: number } | null,
  cycle: 'morning' | 'day' | 'dusk' | 'night' | undefined,
  isStatus: boolean,
  basePower: number,
  playerStages: { atk?: number } | null,
  enemyStages: { def?: number } | null
) {
  let effectiveness = null;
  let damageRange = null;

  if (defender) {
    const pureMove: PureMove = {
      id: move.id,
      name: move.name,
      type: move.type || md.type || 'normal',
      power: basePower,
      cat: (move.cat || md.cat || 'physical') as PureMove['cat'],
      effect: typeof move.effect === 'string' ? move.effect : undefined
    };

    const pureCtx = {
      atkStages: playerStages?.atk || 0,
      defStages: enemyStages?.def || 0,
      weather: weather ? { type: weather.type, turns: weather.turns } : null
    };

    const sim = calculateDamagePure(attacker, defender, pureMove, pureCtx, cycle, 1.0, false);
    const eff = sim.eff;
    let effLabel = 'Neutro';
    let effClass = 'neutral';
    if (eff > 1) {
      effLabel = 'Súper eficaz';
      effClass = 'boosted';
    } else if (eff < 1 && eff > 0) {
      effLabel = 'Poco eficaz';
      effClass = 'penalized';
    } else if (eff === 0) {
      effLabel = 'Inmune';
      effClass = 'penalized';
    }

    effectiveness = {
      value: eff,
      label: effLabel,
      class: effClass
    };

    if (!isStatus && basePower > 0) {
      const normalMin = calculateDamagePure(attacker, defender, pureMove, pureCtx, cycle, 0.85, false).dmg;
      const normalMax = calculateDamagePure(attacker, defender, pureMove, pureCtx, cycle, 1.0, false).dmg;

      const critMin = calculateDamagePure(attacker, defender, pureMove, pureCtx, cycle, 0.85, true).dmg;
      const critMax = calculateDamagePure(attacker, defender, pureMove, pureCtx, cycle, 1.0, true).dmg;

      const rivalMaxHp = defender.maxHp || 100;
      const normalPctMin = Math.round((normalMin / rivalMaxHp) * 100);
      const normalPctMax = Math.round((normalMax / rivalMaxHp) * 100);
      const critPctMin = Math.round((critMin / rivalMaxHp) * 100);
      const critPctMax = Math.round((critMax / rivalMaxHp) * 100);

      damageRange = {
        normalMin,
        normalMax,
        normalPctMin,
        normalPctMax,
        critMin,
        critMax,
        critPctMin,
        critPctMax
      };
    }
  }

  return { effectiveness, damageRange };
}

/**
 * Parses status effect description details.
 */
export function parseStatusEffectInfo(
  move: Move,
  attacker: PurePokemon,
  defender: PurePokemon | null,
  playerStages: Record<string, number | undefined> | null | undefined,
  enemyStages: Record<string, number | undefined> | null | undefined
) {
  const moveIdLookup = move.id || (move.name ? pokemonDataProvider.resolveMoveId(move.name) : '');
  const md = (MOVE_DATA as Record<string, { effect?: string; cat?: string }>)[moveIdLookup] || {};
  const effectStr = (move.effect || md.effect) as string | undefined;

  if (!effectStr || typeof effectStr !== 'string') return null;

  // 1. Mapear efectos tipo stat_up/stat_down
  const statMatch = effectStr.match(/stat_(up|down)_(self|enemy)_([a-z0-9_]+)/);
  if (statMatch) {
    const [, direction, target, statKey] = statMatch;
    if (!direction || !target || !statKey) return null;

    const isUp = direction === 'up';
    const isSelf = target === 'self';

    let stat = statKey;
    let amount = 1;
    if (statKey.endsWith('_2')) {
      stat = statKey.substring(0, statKey.length - 2);
      amount = 2;
    } else if (statKey.endsWith('_3')) {
      stat = statKey.substring(0, statKey.length - 2);
      amount = 3;
    }

    if (stat.endsWith('_10')) stat = stat.substring(0, stat.length - 3);
    if (stat.endsWith('_20')) stat = stat.substring(0, stat.length - 3);
    if (stat.endsWith('_30')) stat = stat.substring(0, stat.length - 3);
    if (stat.endsWith('_50')) stat = stat.substring(0, stat.length - 3);

    const statNames: Record<string, string> = {
      atk: 'Ataque',
      def: 'Defensa',
      spa: 'At. Especial',
      spd: 'Def. Especial',
      spe: 'Velocidad',
      acc: 'Precisión',
      eva: 'Evasión',
      all: 'Todos los Stats'
    };
    const statName = statNames[stat] || stat.toUpperCase();

    const targetPokemon = isSelf ? attacker : defender;
    const targetStages = isSelf ? playerStages : enemyStages;

    if (!targetPokemon) return null;

    const currentStage = targetStages ? (targetStages[stat as keyof typeof targetStages] || 0) as number : 0;
    const finalStage = Math.max(-6, Math.min(6, currentStage + (isUp ? amount : -amount)));

    const getStageMultiplier = (stage: number) => {
      if (stat === 'acc' || stat === 'eva') {
        if (stage >= 0) return (3 + stage) / 3;
        return 3 / (3 - stage);
      }
      if (stage >= 0) return (2 + stage) / 2;
      return 2 / (2 - stage);
    };

    const baseStatVal = (stat === 'acc' || stat === 'eva') ? 100 : ((targetPokemon as unknown as Record<string, number>)[stat] || 100);
    const initialStatVal = Math.round(baseStatVal * getStageMultiplier(currentStage));
    const finalStatVal = Math.round(baseStatVal * getStageMultiplier(finalStage));
    const suffix = (stat === 'acc' || stat === 'eva') ? '%' : '';

    return {
      isCondition: false,
      isSelf,
      direction,
      stat,
      statName,
      amount,
      targetName: isSelf ? 'Usuario (Tú)' : 'Rival',
      currentStage,
      finalStage,
      initialStatVal: initialStatVal + suffix,
      finalStatVal: finalStatVal + suffix,
      label: `${isUp ? 'Aumenta' : 'Reduce'} ${statName} en ${amount} ${amount === 1 ? 'nivel' : 'niveles'}`,
      effect: undefined,
      details: undefined
    };
  }

  // 2. Mapear efectos tipo status condition / condiciones de combate específicas
  const conditionDescriptions: Record<string, { label: string; effect: string; details: string; isSelf: boolean }> = {
    'poison': {
      label: 'Envenenamiento',
      effect: 'Estado Alterado (PSN)',
      details: 'El objetivo pierde 1/8 (12.5%) de sus PS máximos al final de cada turno.',
      isSelf: false
    },
    'bad_poison': {
      label: 'Envenenamiento Grave',
      effect: 'Estado Alterado (TÓXICO)',
      details: 'El objetivo pierde PS progresivamente: empieza en 1/16 y aumenta en 1/16 cada turno consecutivo.',
      isSelf: false
    },
    'burn': {
      label: 'Quemadura',
      effect: 'Estado Alterado (BRN)',
      details: 'El objetivo pierde 1/8 (12.5%) de sus PS máximos al final de cada turno. Además, reduce a la mitad (x0.5) su Ataque Físico.',
      isSelf: false
    },
    'paralyze': {
      label: 'Parálisis',
      effect: 'Estado Alterado (PAR)',
      details: 'Reduce la Velocidad del objetivo al 50% (x0.5) y otorga un 25% de probabilidad de no atacar en cada turno.',
      isSelf: false
    },
    'sleep': {
      label: 'Sueño',
      effect: 'Estado Alterado (SLP)',
      details: 'El objetivo se duerme durante 1 a 3 turnos, impidiéndole atacar por completo.',
      isSelf: false
    },
    'freeze': {
      label: 'Congelación',
      effect: 'Estado Alterado (FRZ)',
      details: 'El objetivo queda congelado e incapaz de moverse. Cada turno tiene un 20% de probabilidad de descongelarse.',
      isSelf: false
    },
    'confuse': {
      label: 'Confusión',
      effect: 'Estado Volátil',
      details: 'El objetivo se confunde durante 1 a 4 turnos. En cada turno, tiene una probabilidad del 33% de golpearse a sí mismo (daño físico de potencia 40).',
      isSelf: false
    },
    'leech_seed': {
      label: 'Semilla Drenadora',
      effect: 'Efecto de Campo Volátil',
      details: 'Al final de cada turno, el objetivo pierde 1/8 (12.5%) de sus PS máximos y se los transfiere al usuario.',
      isSelf: false
    },
    'heal_50': {
      label: 'Recuperación de Salud',
      effect: 'Efecto de Curación',
      details: 'Restaura el 50% de los PS máximos del usuario de forma inmediata.',
      isSelf: true
    },
    'reset_stats': {
      label: 'Niebla / Reinicio',
      effect: 'Efecto de Limpieza',
      details: 'Elimina todos los cambios en los rangos de estadísticas (ataque, defensa, velocidad, etc.) de todos los Pokémon activos y los devuelve a +0.',
      isSelf: true
    }
  };

  const cond = conditionDescriptions[effectStr];
  if (cond) {
    return {
      isCondition: true,
      isSelf: cond.isSelf,
      direction: cond.isSelf ? 'up' : 'down',
      targetName: cond.isSelf ? 'Usuario (Tú)' : 'Rival',
      label: cond.label,
      effect: cond.effect,
      details: cond.details,
      stat: undefined,
      statName: undefined,
      amount: undefined,
      currentStage: undefined,
      finalStage: undefined,
      initialStatVal: undefined,
      finalStatVal: undefined
    };
  }

  return null;
}

// fallow-ignore-file circular-dependencies
import { gsapSleep as sleep } from '@/logic/utils/gsapHelpers'
import { nextTick } from 'vue'

import { handleEntryAbilities } from './battleFlow.ts'
import { getMechanicalWeather } from '../weather/weatherRegistry.ts'
import { getMapBiomeAndTags } from './biomeHelper.ts'
import { FIRE_RED_MAPS } from '@/data/maps'
import { logger } from '../utils/logger.ts'
import type { BattleContext } from '@/types/battleContext'
import type { Pokemon } from '@/types/pokemon'
import type { BattleState, BattleStages, BattleLog } from '@/types/battle'
import type { UIStore, MapStore } from '@/types/stores'

export interface BattleOptions {
  isGym?: boolean;
  gymId?: string;
  locationId?: string;
  isTrainer?: boolean;
  enemyTeam?: Pokemon[];
  trainerName?: string;
  battleOptions?: Record<string, unknown>;
  isFishing?: boolean;
  isArchaeology?: boolean;
  wasSearching?: boolean;
  isDebug?: boolean;
  over?: boolean;
  turn?: 'player' | 'enemy' | null;
  trainerSprite?: string;
  trainerArchetype?: string;
  isRival?: boolean;
  difficulty?: string;
  rewardTM?: string;
  cannotEscape?: boolean;
  persistenceMode?: string;
  trainerQuote?: string;
}

/**
 * Orchestrates the start of a battle.
 * @param {BattleContext} ctx - The battle store context (refs, state, etc)
 */
export async function startBattleSequence(ctx: BattleContext, enemyPoke: Pokemon, options: BattleOptions = {}) {
  const { 
    isGym = false, gymId = undefined, locationId = 'plains', 
    isTrainer = false, enemyTeam = undefined, trainerName = 'Entrenador',
    battleOptions = {}, isFishing = false, isArchaeology = false, wasSearching: wasSearchingOpt = null,
    trainerSprite = undefined, trainerArchetype = undefined, isRival = false,
    difficulty = undefined, rewardTM = undefined, cannotEscape = false,
    trainerQuote = undefined
  } = options

  const { activeBiome, mapTags } = getMapBiomeAndTags(locationId)
  const tagsStr = mapTags.join(', ') || 'ninguno'
  logger.info('Orchestrator', `startBattleSequence starting... Biome: ${activeBiome} (Tags: ${tagsStr}) for location: ${locationId}`, { isTrainer, isGym, wasSearchingOpt })

  const playerPoke = ctx.gs.state.team.find((p) => p.hp > 0 && !p.onMission && !p.onDefense)
  if (!playerPoke) {
    const { useUIStore } = await import('@/stores/ui')
    ;(useUIStore() as unknown as UIStore).notify('No tienes Pokémon sanos para combatir', '❌')
    return
  }

  // Si hay un combate activo pero NO está en fase de finalización, forzamos huida.
  if (ctx.isBattleActive.value && !ctx.isFinishing.value && !ctx.activeBattle.value?.over && !ctx.isSearching.value) {
    logger.warn('BATTLE', 'Combate en curso detectado. Forzando huida del anterior.')
    await ctx.endBattle(false, true)
  }

  const wasSearching = wasSearchingOpt !== null ? wasSearchingOpt : true
  logger.info('Orchestrator', `wasSearching evaluated: ${wasSearching} (wasSearchingOpt: ${wasSearchingOpt})`)

  const { sanitizePokemon } = await import('@/logic/pokemon/pokemonFactory')
  const { useMapStore } = await import('@/stores/map')
  const mapStore = useMapStore() as unknown as MapStore
  const finalEnemyPoke = enemyPoke

  sanitizePokemon(playerPoke)
  sanitizePokemon(finalEnemyPoke)

  // LIMPIEZA DE ESTADOS VOLÁTILES
  ctx.clearVolatileStatus(playerPoke)
  ctx.clearVolatileStatus(finalEnemyPoke)

  // Initial context values
  let rarity = 50

  ctx.activeBattle.value = {
    enemy: null, 
    player: null, 
    _initialEnemy: finalEnemyPoke,
    _initialPlayer: playerPoke,
    _rewardCombatants: [],
    isGym, gymId, isTrainer, enemyTeam, difficulty: difficulty as 'easy' | 'normal' | 'hard' | undefined, rewardTM,
    trainerSprite: trainerSprite || (battleOptions.trainerSprite as string) || undefined,
    trainerArchetype: trainerArchetype || (battleOptions.trainerArchetype as string) || undefined,
    isRival: isRival || (battleOptions.isRival as boolean) || false,
    playerTeam: ctx.gs.state.team,
    trainerName, locationId,
    quote: trainerQuote || (battleOptions.quote as string) || undefined,
    isCave: FIRE_RED_MAPS.find(m => m.id === locationId)?.isCave || false,
    isIndoors: FIRE_RED_MAPS.find(m => m.id === locationId)?.isIndoors || false,
    isCrystalCave: FIRE_RED_MAPS.find(m => m.id === locationId)?.isCrystalCave || false,
    turn: 'player', turnCount: 1, over: false,
    isFishing, isArchaeology, rarity,
    wasSearching,
    cannotEscape: cannotEscape || (battleOptions.cannotEscape as boolean) || false,
    weather: { 
      type: isGym ? 'clear' : getMechanicalWeather(mapStore.currentWeather), 
      visual: isGym ? 'clear' : mapStore.currentWeather, 
      turns: -1 
    },
    playerTeamIndex: ctx.gs.state.team.indexOf(playerPoke),
    participants: [playerPoke.uid], learnQueue: [], ...battleOptions,
    escapeAttempts: 0
  }

  if (battleOptions.isDebug) {
    ctx.debugLoopPokemon.value = JSON.parse(JSON.stringify(enemyPoke))
    if (!wasSearching) ctx.debugLoopPokemon.value = null
  }

  ctx.gs.registerPokedex(enemyPoke.id)
  if (isTrainer && enemyTeam) enemyTeam.forEach((p: Pokemon) => ctx.gs.registerPokedex(p.id))
  ctx.persistBattle()

  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  ctx.isIntroAnimating.value = true

  // PROTOCOLO DE ASIENTOS
  if (ctx.activeBattle.value) {
    // Si es combate salvaje, el Pokémon enemigo ya ocupa el asiento desde el inicio.
    // Si es entrenador o gimnasio, el asiento inicia vacío hasta el envío visual (POKEMON_CALL).
    ctx.activeBattle.value.enemy = (!isTrainer && !isGym) ? finalEnemyPoke : null 

    const currentP = ctx.activeBattle.value.player
    const team = (ctx.gs.state.team as Pokemon[]) || []
    const firstAlive = team.find(p => p && p.hp > 0)
    if (!currentP || !firstAlive || currentP.uid !== (firstAlive?.uid)) {
      ctx.activeBattle.value.player = null
    }
  }

  ctx.clearLogs()

  logger.debug('Orchestrator', 'Transitions starting...');
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.RECEIVE_CONFIG)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.APPLY_ITEM_MODIFIERS)

  // Weight Calculation
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.WEIGHT_CALCULATION)
  if (isFishing) {
    const loc = FIRE_RED_MAPS.find(l => l.id === locationId)
    if (loc && loc.fishing) {
      const pool = loc.fishing.pool
      const rates = loc.fishing.rates
      const idx = pool.indexOf(finalEnemyPoke.id)
      if (idx !== -1) {
        const totalRate = rates.reduce((a, b) => a + b, 0)
        const rateVal = rates[idx]
        rarity = ((rateVal !== undefined ? rateVal : 0) / totalRate) * 100
      }
    }
  }
  if (ctx.activeBattle.value) ctx.activeBattle.value.rarity = rarity

  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.INJECT_FILTERS)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.READY_FOR_GEN)
  await fsm.transition(BATTLE_STATES.CONTEXT_SETUP, BATTLE_SUBSTATES.VACATE_ALL_SEATS)

  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.CHECK_CONTEXT)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.ASYNC_THREAD)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.GEN_TEAMS)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.MARK_EVENT)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PRELOAD_FINAL_COORDS, 0)
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.SET_SEARCH_FLAG)
  logger.info('Orchestrator', `reached after SET_SEARCH_FLAG transition. wasSearching = ${wasSearching}`)

  if (wasSearching) {

    if (isFishing || isArchaeology) {
      ctx.isIntroAnimating.value = false
      if (ctx.activeBattle.value) {
        ctx.activeBattle.value.enemy = finalEnemyPoke
        ctx.activeBattle.value.isFishing = isFishing
        ctx.activeBattle.value.isArchaeology = isArchaeology
      }
      await fsm.transition(BATTLE_STATES.INITIALIZING)
      await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.MINIGAME_CHECK)
      return
    }

    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.PREPARATION)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.AUTO_BATTLE_CHECK)

    const { useUIStore } = await import('@/stores/ui')
    const uiStore = useUIStore() as unknown as UIStore
    const autoBattle = uiStore.autoBattle && !isTrainer

    if (!autoBattle) {
      await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.UPDATE_BUTTON)
    }

    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.ENTRY_ANIM)
    if (isTrainer || isGym) {
      if (ctx.animations?.triggerTrainerEntry) {
        await ctx.animations.triggerTrainerEntry()
      }
    }
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.REORDER_TEAM)

    if (ctx.activeBattle.value?.trainerArchetype === 'policeman') {
      ctx.audio.siren()
    }

    if (!autoBattle) {
      await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.COMBAT_OR_FLEE)
    } else {
      await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.COMBAT_OR_FLEE)
      if (ctx.activeBattle.value) {
        ctx.activeBattle.value.enemy = finalEnemyPoke
        ctx.activeBattle.value.isFishing = isFishing
        ctx.activeBattle.value.isArchaeology = isArchaeology
      }
      const { startEncounter } = await import('./searchLoop.ts')
      await nextTick()
      await startEncounter(ctx)
      return
    }

    if (ctx.activeBattle.value) {
      ctx.activeBattle.value.enemy = finalEnemyPoke
      ctx.activeBattle.value.isFishing = isFishing
      ctx.activeBattle.value.isArchaeology = isArchaeology
    }
    return 
  }

  // Si wasSearching es false, llamamos primero a initBattleSequence (que maneja el PRELOAD_FINAL_COORDS en INITIALIZING)
  // antes de avanzar al flujo visual de FIRST_INTRO.
  logger.info('Orchestrator', 'Calling initBattleSequence...');
  await initBattleSequence(ctx, { 
    locationId, isTrainer, trainerName, isGym, gymId, wasSearching,
    initialEnemy: finalEnemyPoke,
    initialPlayer: playerPoke
  })
}

/**
 * Visual initialization and first turn setup.
 */
export async function initBattleSequence(ctx: BattleContext, options: BattleOptions & { initialEnemy: Pokemon | null, initialPlayer: Pokemon | null }) {
  const { initialEnemy, initialPlayer } = options
  if (!initialPlayer || !initialEnemy) return;
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  // Leemos TODA la configuración del combate estrictamente del estado inyectado en CONTEXT_SETUP
  const battleState = ctx.activeBattle.value
  const locationId = battleState?.locationId || 'plains'
  const isTrainer = !!battleState?.isTrainer
  const isGym = !!battleState?.isGym
  const wasSearching = !!battleState?.wasSearching
  const trainerName = battleState?.trainerName

  // Reset activeBattle state fields if reusing object
  if (ctx.activeBattle.value) {
    ctx.activeBattle.value.over = false
    ctx.activeBattle.value.turnCount = 1
    ctx.activeBattle.value.turn = 'player'
    ctx.activeBattle.value.isCapture = false
    ctx.activeBattle.value.escapeAttempts = 0
    ctx.activeBattle.value.participants = [initialPlayer.uid]
    ctx.activeBattle.value.lastDamage = undefined
    ctx.activeBattle.value.enemyUsedItem = false
    ctx.activeBattle.value.futureSightTurns = undefined
    ctx.activeBattle.value.futureSightTarget = null
    ctx.activeBattle.value.isFishing = false
    ctx.activeBattle.value.isArchaeology = false
    ctx.activeBattle.value.rewardsProcessed = false
    ctx.activeBattle.value._rewardCombatants = []
  }

  // Reset stage variables, fainted sides and logs to prevent state leakages
  ctx.playerStages.value = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 }
  ctx.enemyStages.value = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, reflect: 0, lightScreen: 0, safeguard: 0, mist: 0, spikes: 0 }
  ctx.faintedSides.value.clear()
  ctx.clearLogs()

  // Clear volatile status on all player team members and the initial enemy
  ctx.gs.state.team.forEach((p: Pokemon) => {
    if (p) ctx.clearVolatileStatus(p)
  })
  if (initialEnemy) {
    ctx.clearVolatileStatus(initialEnemy)
  }

  ctx.isIntroAnimating.value = true
  await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PRELOAD_FINAL_COORDS)

  // Si wasSearching es false, transicionamos explícitamente a FIRST_INTRO en la máquina de estados 
  // para cumplir con la secuencia jerárquica del manual antes de ejecutar animaciones
  if (!wasSearching) {
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENTRY_ANIM)
  }

  // Esperar a que la vista (BattleArenaView) se monte y registre las funciones de animación
  for (let i = 0; i < 40; i++) {
    if (ctx.animations) break
    await sleep(50)
  }

  const currentPlayer = ctx.activeBattle.value?.player
  const needsCall = !currentPlayer || (currentPlayer.uid !== initialPlayer.uid)

  if (isTrainer || isGym) {
    if (wasSearching) {
      // Dialogue bubble fades out and trainer retreats in parallel during RETREAT_AND_FADEOUT
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.TRAINER_ENCOUNTER)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.RETREAT_AND_FADEOUT)

      if (ctx.animations?.triggerTrainerRetreat) {
        await ctx.animations.triggerTrainerRetreat()
      }
    } else {
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENCOUNTER_TYPE_CHECK)

      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.TRAINER_ENTRY)
      if (ctx.animations?.triggerTrainerEntry) {
        await ctx.animations.triggerTrainerEntry()
      }

      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.SHOW_DIALOGS)
      if (battleState?.trainerArchetype === 'policeman') {
        ctx.audio.siren()
      }

      if (ctx.animations?.triggerTrainerDialogs) {
        await ctx.animations.triggerTrainerDialogs()
      }

      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.TRAINER_ENCOUNTER)
      await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.RETREAT_AND_FADEOUT)

      if (ctx.animations?.triggerTrainerRetreat) {
        await ctx.animations.triggerTrainerRetreat()
      }
    }

    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.POKEMON_CALL)
    if (ctx.activeBattle.value) {
      ctx.activeBattle.value.enemy = initialEnemy
    }

    const enemySendOutPromise = ctx.animations?.handleReleaseRequest
      ? ctx.animations.handleReleaseRequest({ side: 'enemy', pokemon: initialEnemy })
      : Promise.resolve()
    await enemySendOutPromise

    if (needsCall && ctx.activeBattle.value) {
      const oldPoke = ctx.activeBattle.value.player
      if (oldPoke && oldPoke.uid !== initialPlayer.uid) {
        ctx.exitingPlayer.value = oldPoke
      }

      ctx.activeBattle.value.player = initialPlayer

      const withdrawPromise = oldPoke && oldPoke.uid !== initialPlayer.uid && ctx.animations?.handleCatchRequest
        ? ctx.animations.handleCatchRequest({ side: 'player', pokemon: oldPoke })
        : Promise.resolve()

      const sendOutPromise = ctx.animations?.handleReleaseRequest
        ? ctx.animations.handleReleaseRequest({ side: 'player', pokemon: initialPlayer })
        : Promise.resolve()

      await Promise.all([withdrawPromise, sendOutPromise])
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_CALL)
      ctx.exitingPlayer.value = null
    }
  } else if (wasSearching) {
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENCOUNTER_TYPE_CHECK)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.WILD_ENCOUNTER)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.CHECK_BINOCULARS)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.PARALLEL_JUMP)

    const inventoryBinoculars = ctx.gs.state.inventory['binoculars'] || 0
    const hasBinoculars = ctx.debugBinoculars.value || (inventoryBinoculars > 0)

    // Capture current (wrong-order) pokemon BEFORE overwriting activeBattle.player
    const oldPlayerBeforeSearch = needsCall ? ctx.activeBattle.value?.player ?? null : null
    const hasRealSwap = oldPlayerBeforeSearch && oldPlayerBeforeSearch.uid !== initialPlayer.uid

    if (needsCall && ctx.activeBattle.value) {
      if (hasRealSwap) ctx.exitingPlayer.value = oldPlayerBeforeSearch
      ctx.activeBattle.value.player = initialPlayer
    }

    const promises: Promise<void>[] = []
    if (!hasBinoculars) {
      if (ctx.animations?.triggerSearchEncounter) {
        fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.JUMP_SHADOW)
        promises.push(ctx.animations.triggerSearchEncounter())
      } else {
        promises.push(fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.REVEAL_COLORS, 0))
      }
    }

    if (needsCall && ctx.animations?.handleReleaseRequest) {
      // Run recall of wrong-order pokemon + sendout of correct pokemon in parallel
      if (hasRealSwap && ctx.animations.handleCatchRequest) {
        promises.push(ctx.animations.handleCatchRequest({ side: 'player', pokemon: oldPlayerBeforeSearch }))
      }
      promises.push(ctx.animations.handleReleaseRequest({ side: 'player', pokemon: initialPlayer }))
    }

    if (promises.length > 0) {
      await Promise.all(promises)
    }
    if (hasRealSwap) ctx.exitingPlayer.value = null
  } else {
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.ENCOUNTER_TYPE_CHECK)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.WILD_ENTRY)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.PARALLEL_PREP, 0)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.BUSH_VISIBLE)
    await fsm.transition(BATTLE_STATES.FIRST_INTRO, BATTLE_SUBSTATES.SILHOUETTE_MODE)

    if (ctx.activeBattle.value) {
      ctx.activeBattle.value.enemy = initialEnemy
    }

    if (needsCall && ctx.activeBattle.value) {
      const oldPoke = ctx.activeBattle.value.player
      if (oldPoke && oldPoke.uid !== initialPlayer.uid) {
        ctx.exitingPlayer.value = oldPoke
      }

      ctx.activeBattle.value.player = initialPlayer

      const withdrawPromise = oldPoke && oldPoke.uid !== initialPlayer.uid && ctx.animations?.handleCatchRequest
        ? ctx.animations.handleCatchRequest({ side: 'player', pokemon: oldPoke })
        : Promise.resolve()

      const sendOutPromise = ctx.animations?.handleReleaseRequest
        ? ctx.animations.handleReleaseRequest({ side: 'player', pokemon: initialPlayer })
        : Promise.resolve()

      await Promise.all([withdrawPromise, sendOutPromise])
      await fsm.transition(BATTLE_STATES.REORDER_TEAM, BATTLE_SUBSTATES.POKEMON_CALL)
      ctx.exitingPlayer.value = null
    }
  }

  await fsm.transition(BATTLE_STATES.REORDER_TEAM, null)

  window.dispatchEvent(new Event('resize'))

  ctx.attackerSide.value = null
  ctx.activeMove.value = null

  const { activeBiome, mapTags } = getMapBiomeAndTags(locationId)
  const startMsg = isTrainer || isGym 
    ? `¡${trainerName} te desafía!` 
    : `¡Un ${initialEnemy.name} salvaje apareció!`

  ctx.addLog(startMsg, 'log-info', initialEnemy)
  logger.info('Orchestrator', `Combat started in biome: ${activeBiome} (Tags: ${mapTags.join(', ') || 'ninguno'}) for location: ${locationId}`)

  handleEntryAbilities(initialPlayer, initialEnemy, ctx.playerStages.value, ctx.enemyStages.value, ctx.addLog)

  if (isTrainer || isGym) await ctx.gs.scheduleSave()

  // Team Rocket: Robo Rápido
  if (ctx.gs.state.playerClass === 'rocket' && isTrainer && !isGym) {
    const { calculateQuickStealChance } = await import('@/logic/player/classMath');
    const level = ctx.classStore.classLevel;
    const stealChance = calculateQuickStealChance(level);
    if (Math.random() < stealChance) {
      // Intentar robar
      const criminalItems = ['potion', 'super_potion', 'revive', 'full_heal', 'pokeball', 'great_ball'];
      const stolenItem = criminalItems[Math.floor(Math.random() * criminalItems.length)];
      if (stolenItem) {

        // Agregar al inventario
        if (!ctx.gs.state.inventory) ctx.gs.state.inventory = {};
        ctx.gs.state.inventory[stolenItem] = (ctx.gs.state.inventory[stolenItem] || 0) + 1;

        // Criminalidad +10
        ctx.classStore.addCriminality(10);

        const { getItemById } = await import('@/data/items');
        const itemDef = getItemById(stolenItem);
        const itemName = itemDef?.name || stolenItem;

        // Mensaje y Notificación
        ctx.addLog(`¡Robo Rápido exitoso! Le robaste un ${itemName} a tu oponente.`, 'log-success', 'player');
        ctx.uiStore.notify(`¡Robaste un ${itemName}! (+10 criminalidad)`, '🏴‍☠️');

        // Sonido retro de robo
        ctx.audio.steal();
      }
    }
  }

  // Team Rocket ENEMIGO: Robo al jugador
  if (isTrainer && !isGym && battleState?.trainerSprite) {
    const { classifyNpcArchetype } = await import('@/logic/utils/npcSpriteRouter');
    const npcArchetype = classifyNpcArchetype(battleState.trainerSprite || trainerName || '');
    if (npcArchetype === 'rocket') {
      const enemyTeam = ctx.activeBattle.value?.enemyTeam || [];
      const avgLevel = enemyTeam.length > 0 
        ? Math.round(enemyTeam.reduce((acc, pl) => acc + (pl.level || 5), 0) / enemyTeam.length)
        : 5;

      const { calculateQuickStealChance, calculateMaxNpcRobberyLimit } = await import('@/logic/player/classMath');
      const stealChance = calculateQuickStealChance(avgLevel); // Utiliza el mismo rango de probabilidad (15-30%)
      if (Math.random() < stealChance) {
        const maxLimit = calculateMaxNpcRobberyLimit(avgLevel);
        const playerInventory = ctx.gs.state.inventory || {};

        const { getItemByName, getItemById } = await import('@/data/items');

        const availableItems = Object.keys(playerInventory).filter(k => {
          if ((playerInventory[k] || 0) <= 0) return false;
          const itemDef = getItemByName(k) || getItemById(k);
          return itemDef && (itemDef.cat === 'potions' || itemDef.cat === 'pokeballs');
        });

        const itemsLimit = maxLimit * 0.5;
        let stolenTotalCost = 0;
        const stolenItems: Record<string, number> = {};

        if (availableItems.length > 0) {
          const shuffledItems = [...availableItems].sort(() => Math.random() - 0.5);
          for (const itemId of shuffledItems) {
            if (stolenTotalCost >= itemsLimit) break;

            const itemDef = getItemByName(itemId) || getItemById(itemId);
            const itemPrice = itemDef?.price || 100;
            const availableQty = playerInventory[itemId] || 0;

            const remainingItemsBudget = itemsLimit - stolenTotalCost;
            const maxQtyToStealBasedOnBudget = Math.floor(remainingItemsBudget / itemPrice);

            if (maxQtyToStealBasedOnBudget >= 1 && availableQty > 0) {
              const maxQtyAllowed = Math.min(availableQty, maxQtyToStealBasedOnBudget);
              const qtyToSteal = Math.floor(Math.random() * maxQtyAllowed) + 1;

              playerInventory[itemId] = availableQty - qtyToSteal;
              stolenItems[itemId] = (stolenItems[itemId] || 0) + qtyToSteal;
              stolenTotalCost += qtyToSteal * itemPrice;
            }
          }
        }

        const remainingLimit = maxLimit - stolenTotalCost;
        const playerMoney = ctx.gs.state.money || 0;
        const moneyToSteal = Math.min(playerMoney, remainingLimit);

        if (moneyToSteal > 0) {
          ctx.gs.state.money = playerMoney - moneyToSteal;
          stolenTotalCost += moneyToSteal;
        }

        if (stolenTotalCost > 0) {
          if (ctx.activeBattle.value) {
            ctx.activeBattle.value.stolenResources = {
              money: moneyToSteal,
              items: stolenItems
            };
          }

          ctx.addLog(`¡El Team Rocket te ha emboscado! Te robaron recursos por valor de ₽${stolenTotalCost.toLocaleString()}.`, 'log-error', 'enemy');

          if (moneyToSteal > 0) {
            ctx.uiStore.notify(`¡Te robaron ₽${moneyToSteal}!`, '💸');
          }

          for (const [itemId, qty] of Object.entries(stolenItems)) {
            const itemDef = getItemByName(itemId) || getItemById(itemId);
            const displayName = itemDef?.name || itemId;
            ctx.uiStore.notify(`¡Te robaron ${qty}x ${displayName}!`, '🎒');
          }

          ctx.audio.steal();
        }
      }
    }
  }

  ctx.isIntroAnimating.value = false
  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT)
  ctx.isIntroAnimating.value = false
}

/**
 * Restores a battle state from saved data.
 */
export function restoreBattleState(ctx: BattleContext, battleData: unknown) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  if (!battleData) {
    ctx.activeBattle.value = null
    ctx.fsm.transition(BATTLE_STATES.EXIT_BATTLE)
    return
  }
  const d = battleData as Partial<BattleState & { playerStages: BattleStages, enemyStages: BattleStages, battleLogs: BattleLog[] }>;
  ctx.activeBattle.value = d as BattleState
  if (d.playerStages) ctx.playerStages.value = d.playerStages
  if (d.enemyStages) ctx.enemyStages.value = d.enemyStages
  if (d.battleLogs) ctx.battleLogs.value = d.battleLogs

  if (!d.over) {
    ctx.fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT)
  } else {
    ctx.fsm.transition(BATTLE_STATES.EXIT_BATTLE)
  }
}

// fallow-ignore-file circular-dependencies
import { gsapSleep as sleep } from '@/logic/utils/gsapHelpers'
import { gameBus } from '@/logic/events/gameBus'
import type { BattleContext } from '@/types/battleContext'
import type { Pokemon } from '@/types/pokemon'
import { useBreedingStore } from '@/stores/breeding'
import { useUIStore } from '@/stores/ui'
import { calculateBattleRewards, registerRewardCombatant } from './rewardsDistributor.ts'
import { clearVolatileStatus } from './battleStatus'
export { awardDebugExp } from './rewardsDistributor.ts'

/**
 * Handles the fainting of a Pokémon.
 */
export async function processFaint(ctx: BattleContext, side: 'player' | 'enemy') {
  const active = ctx.activeBattle.value;
  if (!active || active.over || ['SEARCH_PHASE', 'REWARDS_PHASE'].includes(ctx.fsm.currentState.value)) return;

  const isPlayer = side === 'player'
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, isPlayer ? BATTLE_SUBSTATES.PLAYER_FAINT_SEQ : BATTLE_SUBSTATES.ENEMY_REPLACEMENT_SEQ)

  if (ctx.faintedSides.value.has(side)) return
  ctx.faintedSides.value.add(side)

  const pokemon = isPlayer ? active.player : active.enemy
  const opponent = isPlayer ? active.enemy : active.player

  if (pokemon?.destinyBond && opponent && opponent.hp > 0) {
    ctx.addLog(`¡${pokemon.name} se llevó a ${opponent.name} con él!`, 'log-info', pokemon)
    opponent.hp = 0
    await sleep(500)
    await processFaint(ctx, isPlayer ? 'enemy' : 'player')
  }

  if (isPlayer && pokemon) {
    ctx.addLog(`¡${pokemon.name} se ha debilitado!`, 'log-player', pokemon)

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAYER_FAINT_SEQ)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.RECALL_FLOW)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.RENDER_BALL)
    if (ctx.animations?.handleFaintAnim) {
      await ctx.animations.handleFaintAnim({ side: 'player', isFaint: true })
    } else {
      await sleep(1300)
    }

    // Sincronizamos antes de vaciar el asiento para no perder la referencia
    syncTeamHP(ctx)
    if (active) active._lastActivePlayer = pokemon; // Guardamos referencia por si acaso

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.FADEOUT_BALL)
    if (ctx.animations?.playBallFadeOut) {
      await ctx.animations.playBallFadeOut('player')
    }
    active.player = null 

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.CHECK_TEAM)
    const nextPoke = ctx.gs.state.team.find((p: Pokemon) => p && p.hp > 0)

    if (!nextPoke) {
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ALL_FAINTED)
      active.over = true
      ctx.addLog('¡No te quedan Pokémon sanos!', 'log-error', 'player')
      await sleep(1500)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.DEFEAT_SCREEN)
      await terminateBattle(ctx, false)
    } else {
      const isWild = !active.isTrainer && !active.isGym && !active.isPvP
      const enemyHasHealthy = active.enemyTeam && active.enemyTeam.some((p: Pokemon) => p.hp > 0)
      const enemyFaintedAndBattleEnds = active.enemy && active.enemy.hp <= 0 && (isWild || !enemyHasHealthy)

      if (enemyFaintedAndBattleEnds) {
        ctx.faintedSides.value.delete('player')
        // En Double KO no forzamos cambio ni abrimos menú de cambio, ya que la batalla termina y terminateBattle reordenará el equipo
      } else {
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.HAS_HEALTHY)
        ctx.addLog('¡Elige a tu próximo Pokémon!', 'log-info', 'player')
        ctx.faintedSides.value.delete('player')
        ctx.uiStore.isBattleSwitchForced = true
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.SWITCH_MENU)
      }
    }
  } else if (pokemon) {
    const isTr = active.isTrainer || active.isGym || active.isPvP
    const enemyName = isTr ? pokemon.name : `¡${pokemon.name} salvaje`
    ctx.addLog(`${enemyName} fue derrotado!`, 'log-enemy', pokemon)

    // ENEMY_REPLACEMENT_SEQ Starts
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_REPLACEMENT_SEQ)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.TYPE_CHECK)

    if (!isTr) {
      // isWild: Defeat animation
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_DEFEAT)
      if (ctx.animations?.handleFaintAnim) {
        await ctx.animations.handleFaintAnim({ side: 'enemy' })
      } else {
        await sleep(1300)
      }
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAY_ENEMY_FAINT)
    } else {
      // isTrainer / isNpc: Recall animation
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_RECALL)
      if (ctx.animations?.handleCatchRequest) {
        await ctx.animations.handleCatchRequest({ side: 'enemy', pokemon })
      } else {
        gameBus.emit('PLAY_WITHDRAW', { side: 'enemy' })
        await sleep(800)
      }
    }

    // CLEANUP_MEMORY
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.CLEANUP_MEMORY)
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT)
    if (active) {
      registerRewardCombatant(active)
      syncTeamHP(ctx)
      if (isTr && ctx.animations?.playBallFadeOut) {
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.FADEOUT_BALL)
        await ctx.animations.playBallFadeOut('enemy')
      }
      active.enemy = null
      if (!isTr || !active.enemyTeam || !active.enemyTeam.some(p => p.hp > 0)) {
        active._initialEnemy = null
      }
    }

    // CHECK_REMAINING
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.CHECK_REMAINING)
    const nextEnemy = isTr && active.enemyTeam ? active.enemyTeam.find((p: Pokemon) => p.hp > 0) : null

    if (nextEnemy) {
      // STABILIZE_STAGE
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.STABILIZE_STAGE)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EMPTY_WAIT)
      await sleep(200) // organic sleep

      const s = ctx.enemyStages.value
      ctx.enemyStages.value = { atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0, 
        reflect: s.reflect || 0, lightScreen: s.lightScreen || 0, safeguard: s.safeguard || 0, mist: s.mist || 0, spikes: s.spikes || 0 }

      // AI_NEXT_PICK
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.AI_NEXT_PICK)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.SELECT_COUNTER)

      // NEXT_PICK_TYPE -> POKEMON_CALL
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.NEXT_PICK_TYPE)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.POKEMON_CALL)
      await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.OCCUPY_SEAT)

      active.enemy = nextEnemy
      ctx.faintedSides.value.delete('enemy')
      ctx.addLog(`¡Entrenador envía a ${nextEnemy.name}!`, 'log-enemy', 'enemy_trainer')

      if (ctx.animations?.handleReleaseRequest) {
        await ctx.animations.handleReleaseRequest({ side: 'enemy', pokemon: nextEnemy })
      } else {
        gameBus.emit('PLAY_SEND_OUT', { side: 'enemy', pokemon: nextEnemy })
      }
      return
    }

    // No remaining / isWild -> End battle
    if (active) {
      active.over = true;
      registerRewardCombatant(active)
      active.enemy = null;
      active._initialEnemy = null;
    }
    ctx.faintedSides.value.add('enemy')
    await terminateBattle(ctx, true)
  }
}

/**
 * Terminates the battle and processes results.
 */
export async function terminateBattle(ctx: BattleContext, win: boolean, fled = false) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm
  const active = ctx.activeBattle.value;

  if (!active) {
    await fsm.transition(BATTLE_STATES.EXIT_BATTLE)
    return
  }

  active.over = true
  ctx.faintedSides.value.clear()

  // Limpiar todos los estados volátiles del equipo al terminar la batalla
  if (ctx.gs.state.team) {
    ctx.gs.state.team.forEach((p: Pokemon | null) => {
      if (p) clearVolatileStatus(p)
    })
  }

  if (!ctx.gs.state.stats) {
    ctx.gs.state.stats = {}
  }
  ctx.gs.state.stats.totalBattles = (Number(ctx.gs.state.stats.totalBattles) || 0) + 1

  const uiStore = useUIStore()
  uiStore.isBattleSwitchForced = false

  // Reset criminality & apply bail if fighting police officer
  if (active.trainerName === 'Oficial de Policía') {
    if (ctx.gs.state.playerClass === 'rocket' && ctx.gs.state.classData) {
      const criminality = ctx.gs.state.classData.criminality || 0

      // Si el jugador pierde contra la policía (derrota), se le cobra fianza
      if (!win && !fled) {
        const classLevel = ctx.gs.state.classLevel || 1
        const bailAmount = Math.floor(Math.pow(classLevel, 2) * 80 * (criminality / 100))

        if (bailAmount > 0) {
          const prevMoney = ctx.gs.state.money || 0
          ctx.gs.state.money = Math.max(0, prevMoney - bailAmount)
          const moneyPaid = prevMoney - ctx.gs.state.money

          ctx.addLog(`¡Bajo arresto! Pagaste ₽${moneyPaid} de fianza.`, 'log-error', 'player')
          uiStore.notify(`Fianza pagada: ₽${moneyPaid}`, '🚨')
        }
      } else if (win && !fled) {
        // Al ganarle al Oficial, 5% de chance de robar uno de sus Pokémon
        if (Math.random() < 0.05) {
          const pool = active.enemyTeam || [];
          if (pool.length > 0) {
            const stolen = pool[Math.floor(Math.random() * pool.length)];
            if (stolen) {
              const { makePokemon } = await import('@/logic/pokemon/pokemonFactory');
              const clone = makePokemon(stolen.id || stolen.name, stolen.level || 5);
              if (clone) {
                clone.caught = true;
                ctx.gs.state.box.push(clone);

                ctx.addLog(`¡Robaste el ${clone.name} del Oficial de Policía!`, 'log-success', 'player');
                uiStore.notify(`¡Robaste un ${clone.name}!`, '🏴‍☠️');

                // Disparar sonido retro de robo
                const audioStore = await import('@/stores/audio').then(m => m.useAudioStore());
                audioStore.steal();
              }
            }
          }
        }
      }

      ctx.gs.state.classData.criminality = 0
      uiStore.notify("Tu nivel de criminalidad ha vuelto a cero.", "🚔")
    }
  }

  const persistenceMode = active.persistenceMode as string || 'PERSISTENT'
  const isSingle = persistenceMode === 'SINGLE' || active.isGym || active.isPvP

  syncAndPersist(ctx)

  // 1. Ejecutamos animaciones de salida en paralelo para el jugador y el enemigo si siguen activos
  if (fsm.currentState.value === BATTLE_STATES.ACTIVE_BATTLE) {
    const isTrainerOrGym = active.isTrainer || active.isGym || active.isPvP
    // El jugador NUNCA se retira de su asiento en una victoria — permanece visible
    // hasta que el usuario haga clic en "Volver al Mapa/Gimnasios".
    // Solo en derrota (!win && !fled) con un Pokémon vivo se ejecuta la animación de derrota.
    const playerExited: Promise<void> = Promise.resolve()

    let enemyExited: Promise<void> = Promise.resolve()
    if (active.enemy && active.enemy.hp > 0 && !fled && !active.isCapture) {
      if (isTrainerOrGym) {
        enemyExited = ctx.animations?.handleCatchRequest
          ? ctx.animations.handleCatchRequest({ side: 'enemy', pokemon: active.enemy })
          : Promise.resolve()
      } else {
        if (win) {
          enemyExited = ctx.animations?.handleFaintAnim
            ? ctx.animations.handleFaintAnim({ side: 'enemy', pokemon: active.enemy })
            : Promise.resolve()
        } else {
          gameBus.emit('PLAY_ESCAPE_ANIM', { side: 'enemy', type: 'flee' })
          enemyExited = sleep(1000)
        }
      }
    }

    await Promise.all([playerExited, enemyExited])
  }

  // 2. Desvanecer la Poké Ball y vaciar el asiento del enemigo bajo ACTIVE_BATTLE
  if (fsm.currentState.value === BATTLE_STATES.ACTIVE_BATTLE) {
    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.FADEOUT_BALL)
    if (active.isCapture && ctx.animations?.playBallFadeOut) {
      await ctx.animations.playBallFadeOut('enemy')
    }

    await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.VACATE_SEAT)
    if (active) {
      registerRewardCombatant(active)
      active.enemy = null
      active._initialEnemy = null
    }
  } else {
    if (active) {
      registerRewardCombatant(active)
      active.enemy = null
      active._initialEnemy = null
    }
  }

  // 3. Procesar recompensas (Transición a REWARDS_PHASE)
  if (win && !fled && !active.rewardsProcessed) {
    active.rewardsProcessed = true
    const isWild = !active.isTrainer && !active.isGym && !active.isPvP
    if (!isWild) {
      ctx.audio.victoryTrainer()
    }
    await calculateBattleRewards(ctx)

    // Recuperar recursos robados por el Team Rocket
    if (active.stolenResources) {
      const stolen = active.stolenResources;
      if (stolen.money && stolen.money > 0) {
        ctx.gs.state.money = (ctx.gs.state.money || 0) + stolen.money;
        ctx.addLog(`¡Recuperaste tu dinero robado! +₽${stolen.money}`, 'log-success', 'player');
        uiStore.notify(`¡Recuperaste ₽${stolen.money}!`, '💰');
      }
      if (stolen.items) {
        const { getItemByName, getItemById } = await import('@/data/items');
        for (const [itemId, qty] of Object.entries(stolen.items)) {
          if (qty && (qty as number) > 0) {
            if (!ctx.gs.state.inventory) ctx.gs.state.inventory = {};
            ctx.gs.state.inventory[itemId] = (ctx.gs.state.inventory[itemId] || 0) + (qty as number);

            const itemDef = getItemByName(itemId) || getItemById(itemId);
            const displayName = itemDef?.name || itemId;
            ctx.addLog(`¡Recuperaste tu objeto robado: ${displayName}!`, 'log-success', 'player');
            uiStore.notify(`¡Recuperaste ${qty}x ${displayName}!`, '🎒');
          }
        }
      }
      delete active.stolenResources;
    }

    try {
      const breedingStore = useBreedingStore()
      if (active.isGym) {
        breedingStore.reduceHatchTimers('gym')
      } else if (active.isCapture) {
        breedingStore.reduceHatchTimers('capture')
      } else {
        breedingStore.reduceHatchTimers('battle')
      }
    } catch (e) {
      console.error('Failed to reduce hatch timers:', e)
    }
  }

  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.CHECK_OUTCOME)

  if (!win && !fled) {
    await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT)
    await sleep(200)
    await ctx.gs.save(false)

    ctx.audio.defeat()

    await fsm.transition(BATTLE_STATES.EXIT_BATTLE)
    await fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.ENTRY_CHECK)
    await fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.DEFEAT_SCREEN)
    await fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.DEFEAT_WAIT)
    return
  }

  if (fled) {
    if (active) active._initialEnemy = null
    await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.WAIT_LOG_QUEUE_ONLY)
    await ctx.waitForLogs()

    const playerFled = active.playerFled || false
    if (isSingle || playerFled) {
      await fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.ENTRY_CHECK)
      await fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.EXECUTE_CLEANUP)
      await fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.CLEAR_UI)
      await fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.TRIGGER_CLOSE)
      await fsm.transition(BATTLE_STATES.EXIT_BATTLE, BATTLE_SUBSTATES.RESET_FLAGS)
      await ctx.completeBattleFlow('map')
    } else {
      await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT)
      await sleep(200)
      await ctx.completeBattleFlow('search')
    }
    return
  }

  await ctx.gs.save(false)
  await ctx.waitForLogs()

  // Esperar a que el jugador termine de aprender técnicas en el modal
  while (uiStore.learnQueue.length > 0 || uiStore.currentMoveToLearn) {
    await sleep(100)
  }

  syncTeamHP(ctx)

  if (active) active._initialEnemy = null

  if (isSingle) {
    // Para combates isSingle (Gym, PvP), NO se realiza reordenamiento animado.
    // El FSM queda en EMPTY_WAIT con el overlay visible ("VOLVER A GIMNASIOS" / "VOLVER AL MAPA").
    // El cierre lo dispara el usuario al hacer clic en el botón, que llama completeBattleFlow('map').
    await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.CHECK_PERSISTENCE)
    await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT)
    return
  }

  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT)
  await sleep(200) // Pausa de limpieza orgánica reducida a 200ms

  // Reordenamiento animado: recall del incorrecto + release del correcto en paralelo
  const firstHealthy = ctx.gs.state.team.find((p: Pokemon) => p && p.hp > 0)
  const oldPlayer = active.player
  const needsSwap = firstHealthy && (!oldPlayer || oldPlayer.uid !== firstHealthy.uid)

  if (needsSwap && firstHealthy) {
    // Set exitingPlayer so BattleArenaView renders both combatants simultaneously
    if (oldPlayer && oldPlayer.hp > 0) ctx.exitingPlayer.value = oldPlayer
    active.player = firstHealthy
    active.playerTeamIndex = ctx.gs.state.team.findIndex((p: Pokemon) => p.uid === firstHealthy.uid)

    const withdrawPromise = oldPlayer && oldPlayer.hp > 0 && ctx.animations?.handleCatchRequest
      ? ctx.animations.handleCatchRequest({ side: 'player', pokemon: oldPlayer })
      : Promise.resolve()

    const sendOutPromise = ctx.animations?.handleReleaseRequest
      ? ctx.animations.handleReleaseRequest({ side: 'player', pokemon: firstHealthy })
      : Promise.resolve()

    await Promise.all([withdrawPromise, sendOutPromise])
    ctx.exitingPlayer.value = null
  } else if (firstHealthy && !oldPlayer) {
    // No old player (first battle start) — just the release animation
    active.player = firstHealthy
    active.playerTeamIndex = ctx.gs.state.team.findIndex((p: Pokemon) => p.uid === firstHealthy.uid)
    if (ctx.animations?.handleReleaseRequest) {
      await ctx.animations.handleReleaseRequest({ side: 'player', pokemon: firstHealthy })
    }
  }

  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.CHECK_PERSISTENCE)

  if (active.wasSearching !== false) {
    await ctx.completeBattleFlow('search')
  } else {
    await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT)
    await ctx.completeBattleFlow('map')
  }
}



/**
 * Syncs team HP to GameStore.
 */
function syncTeamHP(ctx: BattleContext) {
  const active = ctx.activeBattle.value;
  if (!active) return;

  // Si tenemos un pokemon activo, lo sincronizamos.
  if (active.player) {
    const currentIdx = active.playerTeamIndex ?? ctx.gs.state.team.findIndex((p: Pokemon) => p && p.uid === active.player?.uid);
    if (currentIdx !== -1) {
      const teamPoke = ctx.gs.state.team[currentIdx];
      if (teamPoke) {
        teamPoke.hp = active.player.hp;
        teamPoke.status = active.player.status;
      }
    }
  } else if (active._lastActivePlayer) {
    // Si el asiento está vacío, intentamos sincronizar el último que estuvo (fainted)
    const last = active._lastActivePlayer as Pokemon;
    const currentIdx = ctx.gs.state.team.findIndex((p: Pokemon) => p && p.uid === last.uid);
    if (currentIdx !== -1) {
      const teamPoke = ctx.gs.state.team[currentIdx];
      if (teamPoke) {
        teamPoke.hp = last.hp;
        teamPoke.status = last.status;
      }
    }
  }

  // Sincronizar el HP/estado del enemigo activo con su equipo (Entrenador/Gimnasio/PvP)
  if (active.isTrainer || active.isGym || active.isPvP) {
    if (active.enemy && active.enemyTeam) {
      const enemyIdx = active.enemyTeam.findIndex((p: Pokemon) => p && p.uid === active.enemy?.uid);
      if (enemyIdx !== -1) {
        const teamPoke = active.enemyTeam[enemyIdx];
        if (teamPoke) {
          teamPoke.hp = active.enemy.hp;
          teamPoke.status = active.enemy.status;
        }
      }
      // Reasignar el array para forzar reactividad en el computed de Vue
      active.enemyTeam = [...active.enemyTeam];
    }
  }
}

/**
 * Persists battle state to GameStore.
 */
export function syncAndPersist(ctx: BattleContext) {
  const active = ctx.activeBattle.value;
  if (!active || active.over) {
    ctx.gs.state.activeBattle = null
    return
  }
  ctx.gs.state.activeBattle = {
    ...active,
    playerStages: ctx.playerStages.value,
    enemyStages: ctx.enemyStages.value,
    battleLogs: ctx.battleLogs.value.slice(-10)
  }
  ctx.gs.save(false)
}

import { gsapSleep as sleep } from '@/logic/utils/gsapHelpers'
import { calculateBaseExp, processExpGain, calculateMoneyGain } from './battleRewards.ts'
import { getBattleRewardModifiers } from '@/logic/war/bonusEngine'
import type { BattleContext } from '@/types/battleContext'
import type { Pokemon, PokemonMove } from '@/types/pokemon'
import { useUIStore } from '@/stores/ui'
import { getItemByName, getItemById } from '@/data/items'

import type { BattleState } from '@/types/battle.ts'

export function registerRewardCombatant(active: BattleState | null) {
  if (!active) return
  if (!active._rewardCombatants) {
    active._rewardCombatants = []
  }
  const e = active.enemy || active._initialEnemy
  if (e && !active._rewardCombatants.some((p: Pokemon) => p.uid === e.uid)) {
    active._rewardCombatants.push(e)
  }
}

/**
 * Calculates and distributes XP and money rewards.
 */
export async function calculateBattleRewards(ctx: BattleContext) {
  const active = ctx.activeBattle.value;
  if (!active) return;

  const combatants = active._rewardCombatants && active._rewardCombatants.length > 0 
    ? active._rewardCombatants 
    : (active.enemy || active._initialEnemy ? [active.enemy || active._initialEnemy] : []).filter(Boolean) as Pokemon[]

  if (combatants.length === 0) return;

  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  await fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.DISTRIBUTE_XP)
  // fsm.transition(BATTLE_STATES.REWARDS_PHASE, BATTLE_SUBSTATES.EMPTY_WAIT)

  const isTr = active.isTrainer || active.isGym || active.isPvP
  const locId = active.locationId

  // Update statistics
  if (!ctx.gs.state.stats) {
    ctx.gs.state.stats = {}
  }
  if (isTr) {
    ctx.gs.state.stats.trainersDefeated = (Number(ctx.gs.state.stats.trainersDefeated) || 0) + 1
  } else {
    ctx.gs.state.stats.wins = (Number(ctx.gs.state.stats.wins) || 0) + 1
  }

  // Faction points using the primary opponent
  const primaryEnemy = combatants[0]
  if (primaryEnemy?.isGuardian) await ctx.warStore.addPoints(locId, 'guardian', true)
  else await ctx.warStore.addPoints(locId, isTr ? 'trainer_win' : 'wild_win', true)

  if (active.isGym && active.gymId) {
    const gid = active.gymId
    const diff = active.difficulty || 'easy'
    const isFirstTimeGym = !ctx.gs.state.defeatedGyms.includes(gid)

    // Registrar victoria global (Medalla)
    if (isFirstTimeGym) {
      ctx.gs.state.defeatedGyms.push(gid); ctx.gs.state.badges++
      if (active.rewardTM) { 
        const tm = active.rewardTM
        const itemObj = getItemByName(tm) || getItemById(tm)
        const tmId = itemObj ? itemObj.id : tm.toLowerCase().replace(/\s+/g, '_')
        ctx.gs.state.inventory[tmId] = (ctx.gs.state.inventory[tmId] || 0) + 1
        ctx.addLog(`¡Recibiste la ${itemObj?.name || tm}!`, 'log-info', tmId) 
        ctx.uiStore.notify(`¡Obtuviste ${itemObj?.name || tm}!`, '🎒')
      }
      ctx.uiStore.notify(`¡Ganaste la medalla del Gimnasio ${gid}!`, '🏆')
    } else {
      // Rematch TM chance
      const { useGymsStore } = await import('@/stores/gyms')
      const gymsStore = useGymsStore()
      const gym = gymsStore.gyms.find(g => g.id === gid)
      if (gym && gym.rewardTM) {
        const tmReward = gym.rewardTM
        const key = diff as 'easy' | 'normal' | 'hard'
        let tmChance = 0
        if (key === 'normal') tmChance = 0.03
        else if (key === 'hard') tmChance = 0.05

        if (tmChance > 0 && Math.random() < tmChance) {
          const itemObj = getItemByName(tmReward) || getItemById(tmReward)
          const tmId = itemObj ? itemObj.id : tmReward.toLowerCase().replace(/\s+/g, '_')
          ctx.gs.state.inventory[tmId] = (ctx.gs.state.inventory[tmId] || 0) + 1
          ctx.addLog(`¡Bono de Gimnasio (Rematch): Recibiste la ${itemObj?.name || tmReward}!`, 'log-success', tmId)
          ctx.uiStore.notify(`¡Obtuviste ${itemObj?.name || tmReward}!`, '🎒')
        }
      }
    }

    // Registrar progreso específico por dificultad
    if (!ctx.gs.state.gymProgress[gid] || typeof ctx.gs.state.gymProgress[gid] !== 'object') {
      ctx.gs.state.gymProgress[gid] = { easy: false, normal: false, hard: false, attempts: 0 }
    }
    const prog = ctx.gs.state.gymProgress[gid]
    if (prog) {
      const key = diff as 'easy' | 'normal' | 'hard'
      if (!prog[key]) {
        prog[key] = true
        ctx.addLog(`¡Superaste el gimnasio en dificultad ${diff.toUpperCase()}!`, 'log-success', '🏆')

        // Award Gym Difficulty-Specific rewards dynamically (Bulk Money and EXP only, NO unconditional TM)
        const { useGymsStore } = await import('@/stores/gyms')
        const gymsStore = useGymsStore()
        const gym = gymsStore.gyms.find(g => g.id === gid)
        if (gym && gym.difficulties) {
          const diffData = gym.difficulties[key]
          if (diffData && diffData.levels) {
            const avgLevel = diffData.levels.reduce((a: number, b: number) => a + b, 0) / diffData.levels.length

            const mults: Record<string, number> = { easy: 1, normal: 2.2, hard: 4.5 }
            const mult = mults[key] || 1

            const expReward = Math.floor(avgLevel * 180 * mult)
            const moneyReward = Math.floor(avgLevel * 30 * mult)

            // 1. Award Money
            ctx.gs.state.money += moneyReward
            ctx.addLog(`¡Bono de Gimnasio: Recibiste ₽${moneyReward}!`, 'log-success', 'player')
            ctx.uiStore.notify(`¡Obtuviste ₽${moneyReward}!`, '💰')

            // 2. Award EXP (distributed)
            const team = ctx.gs.state.team || []
            if (team.length > 0) {
              const expPerPoke = Math.floor(expReward / team.length)
              const { getExpNeeded, levelUpPokemon } = await import('@/logic/pokemon/pokemonFactory')
              for (const p of team) {
                if (p.level >= 100) continue
                p.exp += expPerPoke

                let leveledUp = false
                let tempLevel = p.level
                let tempExpNeeded = p.expNeeded || getExpNeeded(tempLevel)

                while (p.exp >= tempExpNeeded && tempLevel < 100) {
                  p.exp -= tempExpNeeded
                  leveledUp = true
                  tempLevel++
                  tempExpNeeded = getExpNeeded(tempLevel)
                }

                if (leveledUp) {
                  const diffLevels = tempLevel - p.level
                  p.level = tempLevel
                  p.expNeeded = tempLevel >= 100 ? Infinity : tempExpNeeded
                  for (let i = 0; i < diffLevels; i++) {
                    levelUpPokemon(p)
                  }
                  ctx.addLog(`¡Bono de Gimnasio: ${p.name} subió al nivel ${p.level}!`, 'log-success', p)
                }
                ctx.addLog(`¡Bono de Gimnasio: ${p.name} ganó ${expPerPoke} EXP!`, 'log-success', p)
              }
              ctx.uiStore.notify(`¡Tu equipo ganó ${expReward} EXP de bono!`, '✨')
            }
          }
        }
      }
      prog.attempts++
    }

    await ctx.gs.save(false)
  }

  const warMods = getBattleRewardModifiers(active.locationId, ctx.gs.state.faction, ctx.warStore.mapDominance)
  let totalExpMult = warMods.expMult + ((ctx.eventStore.globalMultipliers?.exp || 1) - 1)

  if ((ctx.gs.state.luckyEggSecs || 0) > 0) {
    totalExpMult *= 1.5
  }

  const classMult = ctx.classStore.getModifier('expMult', { isTrainer: active.isTrainer })
  const participantsSet = new Set(active.participants)

  const expGainedMap = new Map<string, number>()
  const levelUpMap = new Map<string, { levelsGained: number; moves: PokemonMove[] }>()
  let totalMoneyGained = 0
  let totalCoinsGained = 0
  let totalTrainerExpGained = 0

  const isGymRematch = active.isGym && active.gymId && ctx.gs.state.defeatedGyms.includes(active.gymId)

  for (const e of combatants) {
    if (active.isCapture) await ctx.eventStore.submitCompetitionEntry(e, 'hourly_competition')

    const baseExp = calculateBaseExp(e)
    for (const p of ctx.gs.state.team) {
      const reward = processExpGain(p, baseExp, participantsSet, {
        isActive: p.uid === active.player?.uid,
        classMult,
        totalExpMult,
        participantsSet
      })
      if (!reward) continue

      expGainedMap.set(p.uid, (expGainedMap.get(p.uid) || 0) + reward.gained)

      if (reward.levelUp) {
        if (!levelUpMap.has(p.uid)) {
          levelUpMap.set(p.uid, { levelsGained: 0, moves: [] })
        }
        const lvlData = levelUpMap.get(p.uid)!
        lvlData.levelsGained += reward.levelsGained

        const { levelUpPokemon } = await import('@/logic/pokemon/pokemonFactory')
        for (let i = 0; i < reward.levelsGained; i++) {
          const pendingMoves = levelUpPokemon(p)
          if (pendingMoves) {
            lvlData.moves.push(...pendingMoves)
          }
        }
      }
    }

    let moneyGained = calculateMoneyGain(e, { 
      bcMult: ctx.classStore.getModifier('bcMult', { isGym: active.isGym }), 
      totalMoneyMult: warMods.moneyMult + ((ctx.eventStore.globalMultipliers?.money || 1) - 1),
      isTrainer: active.isTrainer,
      isGym: active.isGym
    })

    if ((ctx.gs.state.amuletCoinSecs || 0) > 0) {
      moneyGained *= 2
    }

    totalMoneyGained += moneyGained

    if ((active.isTrainer || active.isGym) && !isGymRematch) {
      let coins = Math.floor(e.level * 2)
      const bcMult = ctx.classStore.getModifier('bcMult', { isGym: active.isGym })
      coins = Math.floor(coins * bcMult)
      const eventMult = ctx.eventStore.globalMultipliers?.bc || 1
      coins = Math.floor(coins * eventMult)
      totalCoinsGained += coins
    }

    // Trainer experience formula: isGym ? level * 5 : level * 2
    const trainerExpGain = active.isGym ? (e.level * 5) : (e.level * 2)
    totalTrainerExpGained += trainerExpGain
  }

  // Multiplicador de extorsión del Team Rocket (x1.5 ₽ en ruta extorsionada)
  if (ctx.gs.state.playerClass === 'rocket' && ctx.gs.state.classData?.extortedRouteId === active.locationId) {
    const extTimestamp = Number(ctx.gs.state.classData?.extortedRouteTimestamp || 0)
    const now = Temporal.Now.instant().epochMilliseconds
    if (now - extTimestamp <= 24 * 3600 * 1000) {
      const bonusMoney = Math.floor(totalMoneyGained * 0.5)
      totalMoneyGained += bonusMoney
      ctx.addLog(`¡Extorsión activa (+50% ₽)! +₽${bonusMoney}`, 'log-info', 'player')
    }
  }

  // Lógica de Ruta Oficial del Entrenador (+1 Reputación por combate ganado durante 30 mins)
  if (ctx.gs.state.playerClass === 'entrenador' && ctx.gs.state.classData?.officialRouteId === active.locationId) {
    const offTimestamp = Number(ctx.gs.state.classData?.officialRouteTimestamp || 0)
    const now = Temporal.Now.instant().epochMilliseconds
    if (now - offTimestamp <= 30 * 60 * 1000) {
      if (!ctx.gs.state.classData) {
        ctx.gs.state.classData = {
          captureStreak: 0,
          longestStreak: 0,
          reputation: 0,
          blackMarketSales: 0,
          criminality: 0,
          blackMarketDaily: { date: '', items: [], purchased: [] }
        }
      }
      ctx.gs.state.classData.reputation = (Number(ctx.gs.state.classData.reputation) || 0) + 1
      ctx.addLog('¡Ruta Oficial activa! Ganaste +1 de Reputación.', 'log-success', 'player')
    }
  }

  // Award consolidated rewards
  ctx.gs.state.money += totalMoneyGained
  if ((ctx.gs.state.amuletCoinSecs || 0) > 0) {
    ctx.addLog('¡Moneda Amuleto duplicó el dinero obtenido!', 'log-success', 'player')
  }
  if ((ctx.gs.state.luckyEggSecs || 0) > 0) {
    ctx.addLog('¡Huevo Suerte aumentó un 50% la EXP obtenida!', 'log-success', 'player')
  }
  ctx.addLog(`¡Ganaste ₽${totalMoneyGained} en total!`, 'log-info', 'player')

  if (totalCoinsGained > 0) {
    ctx.gs.state.battleCoins = (ctx.gs.state.battleCoins || 0) + totalCoinsGained
    ctx.addLog(`¡Obtuviste ${totalCoinsGained} Battle Coins en total!`, 'log-info', 'player')
  }

  if (totalTrainerExpGained > 0) {
    ctx.gs.addTrainerExp(totalTrainerExpGained)
    ctx.addLog(`¡Ganaste ${totalTrainerExpGained} EXP de entrenador!`, 'log-info', 'player')
  }

  // Print consolidated EXP and trigger Level Ups
  for (const p of ctx.gs.state.team) {
    const gained = expGainedMap.get(p.uid) || 0
    if (gained > 0) {
      ctx.addLog(`${p.name} ganó ${gained} EXP.`, 'log-player', p)
    }

    const lvlData = levelUpMap.get(p.uid)
    if (lvlData) {
      await fsm.transition(BATTLE_STATES.LEVEL_UP_MODAL, BATTLE_SUBSTATES.CHECK_PENDING)
      ctx.addLog(`¡${p.name} subió al nivel ${p.level}!`, 'log-info', p)

      if (lvlData.moves.length > 0) {
        await fsm.transition(BATTLE_STATES.LEVEL_UP_MODAL, BATTLE_SUBSTATES.SHOW_CHOICE)
        p.pendingMoves = lvlData.moves

        const uiStore = useUIStore()
        uiStore.addToLearnQueue(lvlData.moves.map(m => ({ pokemon: p, move: m })))
      }

      // Sincronizar evolución por nivel
      if (p.heldItem === 'everstone') {
        ctx.addLog(`${p.name} evitó evolucionar debido a la Piedra Eterna.`, 'log-info', p)
      } else {
        const { checkLevelUpEvolution } = await import('../evolution/evolutionLogic.ts')
        const targetId = checkLevelUpEvolution(p)
        if (targetId) {
          const uiStore = useUIStore()
          uiStore.startEvolution(p, targetId, '')
          // Esperar síncronamente mientras el modal de evolución esté abierto
          while (uiStore.isEvolutionOpen) {
            await sleep(100)
          }
        }
      }
    }
  }

  if (active.player) {
    const teamPoke = ctx.gs.state.team.find((tp: Pokemon) => tp && tp.uid === active.player?.uid)
    if (teamPoke) {
      active.player.level = teamPoke.level
      active.player.exp = teamPoke.exp
      active.player.expNeeded = teamPoke.expNeeded
      active.player.maxHp = teamPoke.maxHp
      active.player.hp = teamPoke.hp
      active.player.atk = teamPoke.atk
      active.player.def = teamPoke.def
      active.player.spa = teamPoke.spa
      active.player.spd = teamPoke.spd
      active.player.spe = teamPoke.spe
      active.player.moves = teamPoke.moves ? teamPoke.moves.map(m => m ? ({ ...m }) : null) : []
    }
  }
}

/**
 * Simulates a standard experience reward in battle for testing purposes.
 */
export async function awardDebugExp(ctx: BattleContext) {
  const active = ctx.activeBattle.value
  if (!active || !active.player) return

  const p = active.player
  const teamPoke = ctx.gs.state.team.find((tp: Pokemon) => tp && tp.uid === p.uid)
  if (!teamPoke) return

  const needed = teamPoke.expNeeded - teamPoke.exp
  if (needed <= 0) return

  ctx.addLog(`DEBUG: Añadiendo ${needed} EXP para subir de nivel...`, 'log-info', p)

  const participantsSet = new Set([p.uid])
  const reward = processExpGain(teamPoke, needed, participantsSet, {
    isActive: true,
    classMult: 1,
    totalExpMult: 1,
    participantsSet
  })

  if (reward) {
    ctx.addLog(`${teamPoke.name} ganó ${reward.gained} EXP.`, 'log-player', teamPoke)

    if (reward.levelUp) {
      const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
      const fsm = ctx.fsm
      const prevState = fsm.currentState.value
      const prevSubState = fsm.currentSubState.value

      await fsm.transition(BATTLE_STATES.LEVEL_UP_MODAL, BATTLE_SUBSTATES.CHECK_PENDING)

      const allPendingMoves: PokemonMove[] = []
      const { levelUpPokemon } = await import('@/logic/pokemon/pokemonFactory')
      for (let i = 0; i < reward.levelsGained; i++) {
        const pendingMoves = levelUpPokemon(teamPoke)
        if (pendingMoves) {
          allPendingMoves.push(...pendingMoves)
        }
      }

      ctx.addLog(`¡${teamPoke.name} subió al nivel ${teamPoke.level}!`, 'log-info', teamPoke)

      // Sync active player copy stats
      p.level = teamPoke.level
      p.exp = teamPoke.exp
      p.expNeeded = teamPoke.expNeeded
      p.maxHp = teamPoke.maxHp
      p.hp = teamPoke.hp
      p.atk = teamPoke.atk
      p.def = teamPoke.def
      p.spa = teamPoke.spa
      p.spd = teamPoke.spd
      p.spe = teamPoke.spe
      p.moves = teamPoke.moves ? teamPoke.moves.map(m => m ? ({ ...m }) : null) : []

      if (allPendingMoves.length > 0) {
        await fsm.transition(BATTLE_STATES.LEVEL_UP_MODAL, BATTLE_SUBSTATES.SHOW_CHOICE)
        teamPoke.pendingMoves = allPendingMoves

        const uiStore = useUIStore()
        uiStore.addToLearnQueue(allPendingMoves.map(m => ({ pokemon: teamPoke, move: m })))

        while (uiStore.learnQueue.length > 0 || uiStore.currentMoveToLearn) {
          await sleep(100)
        }
      }

      // Sincronizar evolución por nivel en debug
      if (teamPoke.heldItem === 'everstone') {
        ctx.addLog(`${teamPoke.name} evitó evolucionar debido a la Piedra Eterna.`, 'log-info', teamPoke)
      } else {
        const { checkLevelUpEvolution } = await import('../evolution/evolutionLogic.ts')
        const targetId = checkLevelUpEvolution(teamPoke)
        if (targetId) {
          const uiStore = useUIStore()
          uiStore.startEvolution(teamPoke, targetId, '')
          // Esperar síncronamente mientras el modal de evolución esté abierto
          while (uiStore.isEvolutionOpen) {
            await sleep(100)
          }
        }
      }

      // Sync active player copy stats (including newly learned/replaced moves & evolution stats)
      p.level = teamPoke.level
      p.exp = teamPoke.exp
      p.expNeeded = teamPoke.expNeeded
      p.maxHp = teamPoke.maxHp
      p.hp = teamPoke.hp
      p.atk = teamPoke.atk
      p.def = teamPoke.def
      p.spa = teamPoke.spa
      p.spd = teamPoke.spd
      p.spe = teamPoke.spe
      p.moves = teamPoke.moves ? teamPoke.moves.map(m => m ? ({ ...m }) : null) : []

      await fsm.transition(prevState, prevSubState)
    }
  }
}

import { TRAINER_TYPES } from '@/data/trainerTypes'
import { generateEncounter } from '@/logic/encounters/encounters'
import { useUIStore } from '@/stores/ui'
import { useMapStore } from '@/stores/map'
import { getRandomQuoteForTrainer } from '@/data/trainerPhrases.ts'
import { useEventStore } from '@/stores/events'
import { useWarStore } from '@/stores/war'
import type { BattleContext } from '@/types/battleContext'
import type { UIStore, MapStore, EventStore, WarStore } from '@/types/stores'
import type { MapLocation } from '@/types/encounters'
import { logger } from '../utils/logger.ts'
import type { Pokemon } from '@/types/pokemon'
import { nextTick } from 'vue'
import { getSpritesForArchetype } from '@/logic/utils/npcSpriteRouter'

/**
 * Handles the completion of a battle flow (either going to map or search loop).
 */
export async function handleBattleFlowCompletion(ctx: BattleContext, option = 'map') {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm
  const uiStore = useUIStore() as unknown as UIStore

  if (option === 'search' && ctx.activeBattle.value) {
    ctx.isProcessing.value = true

    // 1. Limpiar el enemigo anterior y restaurar estados de animación
    ctx.activeBattle.value.enemy = null
    ctx.activeBattle.value._initialEnemy = null

    if (ctx.animations?.resetAll) {
      ctx.animations.resetAll()
    }

    // Restablecer flags de minijuegos para la fase de búsqueda
    ctx.activeBattle.value.isFishing = false
    ctx.activeBattle.value.isArchaeology = false
    ctx.activeBattle.value.rewardsProcessed = false
    ctx.activeBattle.value.over = false
    ctx.activeBattle.value.fled = false
    ctx.activeBattle.value.playerFled = false
    ctx.activeBattle.value._rewardCombatants = []

    // Restablecer flags de entrenador y gimnasio de inmediato
    ctx.activeBattle.value.isGym = false
    ctx.activeBattle.value.gymId = undefined
    ctx.activeBattle.value.difficulty = undefined
    ctx.activeBattle.value.rewardTM = undefined
    ctx.activeBattle.value.isTrainer = false
    ctx.activeBattle.value.enemyTeam = undefined
    ctx.activeBattle.value.trainerName = undefined
    ctx.activeBattle.value.trainerSprite = undefined
    ctx.activeBattle.value.trainerArchetype = undefined
    ctx.activeBattle.value.isRival = false
    ctx.activeBattle.value.cannotEscape = false

    await nextTick()

    // FASE: INITIALIZING
    await fsm.transition(BATTLE_STATES.INITIALIZING)

    const locId = ctx.activeBattle.value.locationId || ''

    // Generar el encuentro en segundo plano
    const mapStore = useMapStore() as unknown as MapStore
    const eventStore = useEventStore() as unknown as EventStore
    const warStore = useWarStore() as unknown as WarStore
    const win = (typeof window !== 'undefined' ? window : null) as unknown as Record<string, unknown>
    const debug = win?.__VITE_DEBUG__ as Record<string, unknown> | undefined
    const debugMults = (debug?.multipliers as Record<string, number> | undefined) || {}

    const encounterOptions = {
      activeEvents: mapStore.activeEvents,
      dominanceData: warStore.mapDominance,
      shinyMultiplier: (eventStore.globalMultipliers?.shiny || 1) * (debugMults.shiny || 1),
      eventTrainerBonus: (eventStore.globalMultipliers?.trainer || 1) * (debugMults.trainer || 1),
      eventFishingBonus: (eventStore.globalMultipliers?.fishing || 1) * (debugMults.fishing || 1),
      eventRivalBonus: (eventStore.globalMultipliers?.rival || 1) * (debugMults.rival || 1)
    }

    let encounter = null

    // Cazabichos: Aroma Atractivo (0.5% chance for Scyther/Pinsir spawn)
    if (ctx.gs.state.playerClass === 'cazabichos' && Math.random() < 0.005) {
      const { makePokemon } = await import('@/logic/pokemon/pokemonFactory')
      const { pokemonDataProvider } = await import('@/logic/providers/pokemonDataProvider')
      const mapsList = pokemonDataProvider.getMaps() as unknown as MapLocation[]
      const currentMapData = mapsList.find(m => m.id === (locId || ''))
      const minLv = currentMapData?.lv?.[0] || 5
      const maxLv = currentMapData?.lv?.[1] || minLv
      const level = Math.floor(Math.random() * (maxLv - minLv + 1)) + minLv
      const bugs = ['scyther', 'pinsir']
      const chosenBug = bugs[Math.floor(Math.random() * bugs.length)]
      const generatedBug = makePokemon(chosenBug || '', level)
      if (generatedBug) {
        encounter = { type: 'wild', pokemon: generatedBug }
        ctx.uiStore.notify(`¡Aroma Atractivo atrajo a un ${generatedBug.name} salvaje!`, '🐝')
      }
    }

    if (!encounter) {
      encounter = await generateEncounter(locId || '', ctx.gs.state, encounterOptions)
    }

    let isFishing = false
    let isArchaeology = false
    let generatedPoke: Pokemon | null = null

    if (encounter) {
      if (encounter.type === 'trainer') {
        ctx.gs.state.trainerChance = 5

        const { buildTrainerTeam } = await import('./trainerFactory')
        const { pokemonDataProvider } = await import('@/logic/providers/pokemonDataProvider')

        const isMaxCriminality = (ctx.gs.state.playerClass === 'rocket' && (ctx.gs.state.classData?.criminality ?? 0) >= 100)
        const mapsList = pokemonDataProvider.getMaps() as unknown as MapLocation[]
        const currentMapData = mapsList.find(m => m.id === (locId || ''))
        const baseLv = currentMapData?.lv?.[0] || 5

        let tName = 'Entrenador'
        let tSprite = 'youngster'
        const enemyTeam: Pokemon[] = []

        let tQuote = '¡Prepárate para combatir! ¡No te lo pondré fácil!'
        let typeKey: keyof typeof TRAINER_TYPES = 'default'
        if (isMaxCriminality) {
          const t = TRAINER_TYPES['policeman']
          tName = t.name
          const availableSprites = getSpritesForArchetype('policeman')
          const chosenSprite = availableSprites[Math.floor(Math.random() * availableSprites.length)]
          tSprite = chosenSprite || t.sprite
          tQuote = getRandomQuoteForTrainer('policeman')

          const criminality = ctx.gs.state.classData?.criminality || 100
          const excess = Math.max(0, criminality - 100)
          const bonusLv = Math.floor(excess / 50)
          const trainerLv = baseLv + 5 + bonusLv
          const teamSize = Math.floor(Math.random() * 2) + 3

          const team = await buildTrainerTeam(t.pool, trainerLv, teamSize)
          enemyTeam.push(...team)
        } else {
          const keys = Object.keys(TRAINER_TYPES) as Array<keyof typeof TRAINER_TYPES>
          typeKey = keys[Math.floor(Math.random() * keys.length)] || 'caza_bichos'
          const t = TRAINER_TYPES[typeKey]
          tName = t.name
          const availableSprites = getSpritesForArchetype(typeKey)
          const chosenSprite = availableSprites[Math.floor(Math.random() * availableSprites.length)]
          if (!chosenSprite) {
            throw new Error(`[searchLoop] Failed to find sprites for archetype: ${typeKey}`)
          }
          tSprite = chosenSprite
          tQuote = getRandomQuoteForTrainer(typeKey)
          const trainerLv = baseLv + 2
          const teamSize = Math.floor(Math.random() * 3) + 1

          const { buildTrainerTeam } = await import('./trainerFactory')
          const team = await buildTrainerTeam(t.pool, trainerLv, teamSize)
          enemyTeam.push(...team)
        }

        if (enemyTeam.length > 0 && enemyTeam[0]) {
          generatedPoke = enemyTeam[0]
          ctx.activeBattle.value.isTrainer = true
          ctx.activeBattle.value.enemyTeam = enemyTeam
          ctx.activeBattle.value.trainerName = tName
          ctx.activeBattle.value.trainerSprite = tSprite
          ctx.activeBattle.value.trainerArchetype = isMaxCriminality ? 'policeman' : TRAINER_TYPES[typeKey].archetype
          ctx.activeBattle.value.quote = tQuote
          ctx.activeBattle.value.isRival = false
        }
      } else if (encounter.type === 'rival') {
        const { getEvolvedForm } = await import('@/logic/evolution/evolutionLogic')
        const { makePokemon } = await import('@/logic/pokemon/pokemonFactory')

        const trainerNameVal = 'Rival Azul'
        const trainerSpriteVal = 'blue'

        const teamSize = Math.max(3, ctx.gs.state.team.length || 1)
        const avgLevel = ctx.gs.state.team.reduce((sum, p) => sum + p.level, 0) / (ctx.gs.state.team.length || 1)
        const rivalLevel = Math.floor(avgLevel) + 2

        const rivalPoolBase = ['pidgeot', 'alakazam', 'gyarados', 'arcanine', 'exeggutor', 'charizard']
        const shuffledPool = [...rivalPoolBase].sort(() => Math.random() - 0.5).slice(0, teamSize)

        const enemyTeam: Pokemon[] = shuffledPool.map(id => {
          const species = getEvolvedForm(id, rivalLevel)
          const p = makePokemon(species, rivalLevel) as Pokemon
          if (p) (p as Pokemon & { _revealed?: boolean })._revealed = true
          return p
        }).filter((p): p is Pokemon => !!p)

        if (enemyTeam.length > 0 && enemyTeam[0]) {
          generatedPoke = enemyTeam[0]
          ctx.activeBattle.value.isTrainer = true
          ctx.activeBattle.value.enemyTeam = enemyTeam
          ctx.activeBattle.value.trainerName = trainerNameVal
          ctx.activeBattle.value.trainerSprite = trainerSpriteVal
          ctx.activeBattle.value.trainerArchetype = 'trainers'
          ctx.activeBattle.value.isRival = true
        }
      } else {
        // Limpiar parámetros de entrenador y gimnasio
        ctx.activeBattle.value.isTrainer = false
        ctx.activeBattle.value.enemyTeam = undefined
        ctx.activeBattle.value.trainerName = undefined
        ctx.activeBattle.value.trainerSprite = undefined
        ctx.activeBattle.value.isRival = false
        ctx.activeBattle.value.isGym = false
        ctx.activeBattle.value.gymId = undefined
        ctx.activeBattle.value.difficulty = undefined
        ctx.activeBattle.value.rewardTM = undefined

        if (encounter.pokemon) {
          generatedPoke = encounter.pokemon
          if (encounter.type === 'guardian') {
            generatedPoke.isGuardian = true
          }
          isFishing = encounter.type === 'fishing'
          isArchaeology = encounter.type === 'archaeology'
        }
      }
    }

    if (generatedPoke) {
      ctx.activeBattle.value._initialEnemy = generatedPoke
      ctx.activeBattle.value.enemy = generatedPoke
    }

    // Si el encuentro generado es un minijuego, lo jugamos de inmediato
    if (isFishing || isArchaeology) {
      ctx.activeBattle.value.isFishing = isFishing
      ctx.activeBattle.value.isArchaeology = isArchaeology
      ctx.isProcessing.value = false
      await fsm.transition(BATTLE_STATES.INITIALIZING)
      await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.MINIGAME_CHECK)
      return
    }

    await fsm.transition(BATTLE_STATES.INITIALIZING)
    await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.PRELOAD_COORDS, 100)

    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.PREPARATION)
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.AUTO_BATTLE_CHECK)

    const isTrainer = ctx.activeBattle.value?.isTrainer || ctx.activeBattle.value?.isGym || false
    const uiStore = useUIStore() as unknown as UIStore
    const autoBattle = uiStore.autoBattle && !isTrainer

    if (!autoBattle) {
      await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.UPDATE_BUTTON)
    }

    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.ENTRY_ANIM)
    if (isTrainer) {
      if (ctx.animations?.triggerTrainerEntry) {
        await ctx.animations.triggerTrainerEntry()
      }
    }
    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.REORDER_TEAM)

    if (ctx.activeBattle.value?.trainerArchetype === 'policeman') {
      ctx.audio.siren()
    }

    await fsm.transition(BATTLE_STATES.SEARCH_PHASE, BATTLE_SUBSTATES.COMBAT_OR_FLEE)
    ctx.isProcessing.value = false

    if (autoBattle) {
      await nextTick()
      await startEncounter(ctx)
    }

    return
  }

  const isGym = ctx.activeBattle.value?.isGym || false

  fsm.transition(BATTLE_STATES.EXIT_BATTLE)
  ctx.activeBattle.value = null
  ctx.isProcessing.value = false
  ctx.clearLogs() 

  if (option === 'map') {
    uiStore.activeTab = isGym ? 'gyms' : 'map'
  }
}

/**
 * Triggers an encounter from the search loop.
 */
export async function triggerNextEncounter(ctx: BattleContext) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  ctx.isProcessing.value = false
  const locId = ctx.activeBattle.value?.locationId
  const enemyPoke = ctx.activeBattle.value?.enemy
  if (!enemyPoke || !locId) {
    logger.warn('Battle', 'triggerNextEncounter: sin enemy o locationId.')
    return
  }

  await fsm.transition(BATTLE_STATES.INITIALIZING)
  const isMinigame = ctx.activeBattle.value?.isFishing || ctx.activeBattle.value?.isArchaeology
  if (isMinigame) {
    await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.MINIGAME_CHECK)
  }

  await ctx._startBattle(enemyPoke, {
    locationId: locId,
    wasSearching: true,
    isDebug: !!ctx.debugLoopPokemon.value,
    isFishing: ctx.activeBattle.value?.isFishing,
    isArchaeology: ctx.activeBattle.value?.isArchaeology
  })
}

export async function startEncounter(ctx: BattleContext) {
  const { BATTLE_STATES, BATTLE_SUBSTATES } = ctx
  const fsm = ctx.fsm

  const isMinigame = ctx.activeBattle.value?.isFishing || ctx.activeBattle.value?.isArchaeology
  const enemyPoke = ctx.activeBattle.value?.enemy || ctx.activeBattle.value?._initialEnemy

  if (isMinigame) {
    if (ctx.activeBattle.value && enemyPoke) {
      ctx.activeBattle.value.enemy = { ...enemyPoke }
      ctx.activeBattle.value._initialEnemy = { ...enemyPoke }
    }
    await fsm.transition(BATTLE_STATES.INITIALIZING)
    await fsm.transition(BATTLE_STATES.INITIALIZING, BATTLE_SUBSTATES.MINIGAME_CHECK)
    return
  }

  ctx.isIntroAnimating.value = true

  await ctx.initBattle();

  ctx.isIntroAnimating.value = false
}

import { EGG_GROUPS, BABY_MAP, EGG_MOVES_DB, BREEDING_CONSTANTS } from './breedingData.ts'
import { getFirstEvolution } from '@/logic/pokemon/evolutionEngine'
import type { Pokemon, PokemonIVs, BreedingCompatibility } from '@/types/pokemon'

/**
 * breedingEngine.ts
 * Motor lógico de crianza: compatibilidad, herencia y generación de especies.
 */

/**
 * Retorna el ID base de un Pokémon (remueve sufijos de género si existen).
 */
export function getBreedingBaseId(id: string): string {
  if (!id) return id
  if (id === 'nidoran_f' || id === 'nidoran_m') return id
  return id.endsWith('_m') || id.endsWith('_f') ? id.slice(0, -2) : id
}

export { getFirstEvolution };

/**
 * Determina qué especie nacerá de un huevo.
 * Considera si la forma base tiene una forma "Bebé".
 */
export function getEggSpecies(motherId: string): string {
  const firstEvo = getFirstEvolution(motherId)
  return BABY_MAP[firstEvo] || firstEvo
}

/**
 * Evalúa la compatibilidad entre dos Pokémon.
 */
export function checkCompatibility(pA: Pokemon, pB: Pokemon): BreedingCompatibility {
  const idA = getBreedingBaseId(pA.id)
  const idB = getBreedingBaseId(pB.id)
  const gA = EGG_GROUPS[idA] || []
  const gB = EGG_GROUPS[idB] || []

  const shared = gA.filter(g => gB.includes(g) && g !== 'ditto')

  // Validar "no-eggs" (Babies, Legendaries)
  if (gA.includes('no-eggs') || gB.includes('no-eggs')) {
    return { level: 0, reason: 'Uno de los Pokémon no puede criar', sharedGroups: [] }
  }

  const aDitto = idA === 'ditto'
  const bDitto = idB === 'ditto'

  if (aDitto && bDitto) return { level: 0, reason: 'Dos Ditto no pueden criar', sharedGroups: [] }

  // Caso Ditto + cualquier otro
  if (aDitto || bDitto) {
    const other = aDitto ? pB : pA
    const species = getEggSpecies(other.id)
    return { level: 2, eggSpecies: species, reason: 'OK', sharedGroups: [] }
  }

  // Géneros opuestos obligatorios
  if (!pA.gender || !pB.gender || pA.gender === pB.gender) {
    return { level: 0, reason: 'Se requiere macho y hembra', sharedGroups: [] }
  }

  // Grupos compatibles
  if (shared.length > 0) {
    const mother = pA.gender === 'F' ? pA : pB
    const species = getEggSpecies(mother.id)
    const level = (idA === idB) ? 3 : 2
    return { level, eggSpecies: species, reason: 'OK', sharedGroups: shared }
  }

  return { level: 0, reason: 'Sin grupo huevo común', sharedGroups: [] }
}

/**
 * Calcula la herencia de IVs de la cría.
 * Soporta Objetos Recios (force stat) y Lazo Destino (hereda 5 stats).
 */
export function calculateInheritance(pA: Pokemon, pB: Pokemon, itemA: string, itemB: string, playerClass: string = ''): PokemonIVs {
  const STATS: (keyof PokemonIVs)[] = ['hp', 'atk', 'def', 'spa', 'spd', 'spe']
  const ivs: PokemonIVs = { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 }
  STATS.forEach(s => ivs[s] = Math.floor(Math.random() * 32))

  const powerMap: Record<string, keyof PokemonIVs> = {
    power_weight: 'hp',
    power_bracer: 'atk',
    power_belt: 'def',
    power_lens: 'spa',
    power_band: 'spd',
    power_anklet: 'spe'
  }

  const forcedA = powerMap[itemA]
  const forcedB = powerMap[itemB]

  if (forcedA) ivs[forcedA] = pA.ivs[forcedA]
  if (forcedB && forcedB !== forcedA) ivs[forcedB] = pB.ivs[forcedB]
  else if (forcedB && forcedB === forcedA) {
    ivs[forcedB] = Math.random() < 0.5 ? pA.ivs[forcedB] : pB.ivs[forcedB]
  }

  const hasDestinyKnot = itemA === 'destiny_knot' || itemB === 'destiny_knot'
  const forcedCount = (forcedA && forcedB && forcedA !== forcedB) ? 2 : ((forcedA || forcedB) ? 1 : 0)

  // Criador hereda +1 stat adicional base
  let baseInheritCount = hasDestinyKnot ? BREEDING_CONSTANTS.IV_INHERIT_DESTINY_KNOT : BREEDING_CONSTANTS.IV_INHERIT_DEFAULT
  if (playerClass === 'criador') baseInheritCount++

  const countToInherit = Math.max(0, baseInheritCount - forcedCount)

  const remainingStats = STATS.filter(s => s !== forcedA && s !== forcedB)
    .sort(() => Math.random() - 0.5)
    .slice(0, countToInherit)

  remainingStats.forEach(s => {
    ivs[s] = Math.random() < 0.5 ? pA.ivs[s] : pB.ivs[s]
  })

  return ivs
}

/**
 * Calcula la herencia de movimientos.
 * Prioridad: Egg Moves > TMs learned by parents > Level-up moves shared.
 */
export function inheritMoves(pA: Pokemon, pB: Pokemon, eggSpeciesId: string): string[] {
  const babyId = getBreedingBaseId(eggSpeciesId)
  const possibleEggMoves = EGG_MOVES_DB[babyId] || []
  const inheritedMoves: string[] = []

  // 1. Egg Moves (si el padre o la madre lo conocen Y está en la DB de posibles egg moves)
  const parentsMoves = [...(pA.moves || []), ...(pB.moves || [])]
  possibleEggMoves.forEach(moveId => {
    if (parentsMoves.some(m => m && m.name === moveId)) {
      if (!inheritedMoves.includes(moveId)) inheritedMoves.push(moveId)
    }
  })

  // 2. TMs: Si ambos padres conocen una MT que la cría puede aprender (simplificación legacy)
  const sharedMoves = (pA.moves || []).filter(ma => ma && (pB.moves || []).some(mb => mb && mb.name === ma.name))
  sharedMoves.forEach(m => {
    if (m && !inheritedMoves.includes(m.name) && inheritedMoves.length < 4) {
      inheritedMoves.push(m.name)
    }
  })

  // Limitamos a los últimos 4 movimientos encontrados
  return inheritedMoves.slice(-4)
}

/**
 * Determina la habilidad heredada.
 * La madre tiene 60% de probabilidad de pasar su habilidad (incluyendo Ocultas).
 * Si hay un Ditto, el otro padre actúa como "madre".
 */
export function inheritAbility(pA: Pokemon, pB: Pokemon): string | null {
  const isADitto = getBreedingBaseId(pA.id) === 'ditto'
  const isBDitto = getBreedingBaseId(pB.id) === 'ditto'

  let source: Pokemon | null;
  if (isADitto) source = pB
  else if (isBDitto) source = pA
  else source = pA.gender === 'F' ? pA : pB // La madre manda

  if (!source) return null

  if (Math.random() < BREEDING_CONSTANTS.HIDDEN_ABILITY_CHANCE) {
    return source.ability || null
  }

  return null // Habilidad aleatoria (slot 1 o 2 estándar)
}

/**
 * Calcula la probabilidad de Shiny considerando el Método Masuda y eventos.
 * standardRate suele ser 1/8192 o 1/4096.
 */
export function calculateShinyChance(pA: Pokemon, pB: Pokemon, standardRate: number = 1/4096, eventShinyMult: number = 1): number {
  const isForeign = pA.region !== pB.region || pA.ot_id !== pB.ot_id // Simplificación Método Masuda
  const masudaBonus = isForeign ? (BREEDING_CONSTANTS.MASUDA_MULTIPLIER - 1) : 0
  const eventBonus = eventShinyMult - 1

  const totalMult = 1 + masudaBonus + eventBonus // Additive stacking
  return standardRate * totalMult
}

/**
 * Determina la naturaleza heredada (Piedra Eterna).
 */
export function inheritNature(pA: Pokemon, pB: Pokemon, itemA: string, itemB: string): string | null {
  if (itemA === 'everstone' && itemB === 'everstone') {
    return Math.random() < 0.5 ? pA.nature : pB.nature
  }
  if (itemA === 'everstone') return pA.nature
  if (itemB === 'everstone') return pB.nature

  // Si no hay piedra, la naturaleza será aleatoria (se manejará al crear el objeto Pokémon)
  return null
}

export interface GeneticsForecast {
  natureGuaranteed: boolean;
  ivsInherited: number;
  masudaActive: boolean;
  eggMovesCount: number;
  shinyMultiplier: number;
  hiddenAbilityChance: number;
}

/**
 * Retorna un resumen de probabilidades para la UI.
 * No revela el resultado final, solo las reglas actuales aplicadas.
 */
export function getGeneticsForecast(pA: Pokemon, pB: Pokemon, playerClass: string = ''): GeneticsForecast {
  const itemA = pA.heldItem || ''
  const itemB = pB.heldItem || ''

  const hasEverstone = itemA === 'everstone' || itemB === 'everstone'
  const hasDestinyKnot = itemA === 'destiny_knot' || itemB === 'destiny_knot'
  const isForeign = pA.region !== pB.region || pA.ot_id !== pB.ot_id

  const ivCount = (hasDestinyKnot ? BREEDING_CONSTANTS.IV_INHERIT_DESTINY_KNOT : BREEDING_CONSTANTS.IV_INHERIT_DEFAULT) + (playerClass === 'criador' ? 1 : 0)

  // Calcular si hay posibles Egg Moves
  const babyId = getBreedingBaseId(getEggSpecies(pA.id))
  const possibleEggMoves = EGG_MOVES_DB[babyId] || []
  const parentsMoves = [...(pA.moves || []), ...(pB.moves || [])]
  const eggMovesDetected = possibleEggMoves.filter(moveId => parentsMoves.some(m => m && m.name === moveId))

  return {
    natureGuaranteed: hasEverstone,
    ivsInherited: ivCount,
    masudaActive: isForeign,
    eggMovesCount: eggMovesDetected.length,
    shinyMultiplier: isForeign ? BREEDING_CONSTANTS.MASUDA_MULTIPLIER : 1,
    hiddenAbilityChance: 60 // Porcentaje fijo
  }
}

