import { initSQLite, queryLocal, persistSQLite } from './sqliteEngine.ts';
import type { DBRouter } from './dbRouter.ts';
import type { DBResponse, ProxyQueryChainItem } from '@/types/database';
import { logger } from '../utils/logger.ts';

/**
 * Chainable Query Builder for SQLite that mimics Supabase/PostgREST API.
 */

export class ProxyQuery {
  router: DBRouter;
  table: string;
  chain: ProxyQueryChainItem[];
  action: 'select' | 'upsert' | 'update' | 'delete' | 'insert';
  actionData: unknown;
  actionOpts: unknown;

  constructor(router: DBRouter, table: string) {
    this.router = router;
    this.table = table;
    this.chain = [];
    this.action = 'select'; // select, upsert, update, delete
    this.actionData = null;
    this.actionOpts = null;
  }

  select(cols: string = '*', opts: { count?: 'exact' | 'planned' | 'estimated' | null, head?: boolean } = {}) { 
    this.chain.push({ type: 'select', args: [cols, opts] }); 
    return this; 
  }
  eq(c: string, v: unknown) { this.chain.push({ type: 'eq', args: [c, v] }); return this; }
  neq(c: string, v: unknown) { this.chain.push({ type: 'neq', args: [c, v] }); return this; }
  gt(c: string, v: unknown) { this.chain.push({ type: 'gt', args: [c, v] }); return this; }
  lt(c: string, v: unknown) { this.chain.push({ type: 'lt', args: [c, v] }); return this; }
  gte(c: string, v: unknown) { this.chain.push({ type: 'gte', args: [c, v] }); return this; }
  lte(c: string, v: unknown) { this.chain.push({ type: 'lte', args: [c, v] }); return this; }
  in(c: string, arr: unknown[]) { this.chain.push({ type: 'in', args: [c, arr] }); return this; }
  is(c: string, v: unknown) { this.chain.push({ type: 'is', args: [c, v] }); return this; }
  not(c: string, op: string, v: unknown) { this.chain.push({ type: 'not', args: [c, op, v] }); return this; }
  or(c: string) { this.chain.push({ type: 'or', args: [c] }); return this; }
  order(c: string, opts: { ascending?: boolean } = {}) { this.chain.push({ type: 'order', args: [c, opts] }); return this; }
  limit(n: number) { this.chain.push({ type: 'limit', args: [n] }); return this; }
  match(obj: Record<string, unknown>) { this.chain.push({ type: 'match', args: [obj] }); return this; }
  ilike(c: string, v: string) { this.chain.push({ type: 'ilike', args: [c, v] }); return this; }

  upsert(data: unknown, opts?: unknown) {
    this.action = 'upsert';
    this.actionData = data;
    this.actionOpts = opts;
    return this;
  }

  insert(data: unknown) {
    this.action = 'insert';
    this.actionData = data;
    return this;
  }

  update(data: unknown) {
    this.action = 'update';
    this.actionData = data;
    return this;
  }

  delete() {
    this.action = 'delete';
    return this;
  }

  async maybeSingle(): Promise<DBResponse> { return this.execute('maybeSingle'); }
  async single(): Promise<DBResponse> { return this.execute('single'); }

  // compatibility with 'await q'
  async then<T = DBResponse>(onFulfilled?: (value: DBResponse) => T | Promise<T>, onRejected?: (reason: unknown) => T | Promise<T>): Promise<T | DBResponse> {
    try {
      const res = await this.execute();
      return onFulfilled ? onFulfilled(res) : res;
    } catch (err) {
      if (onRejected) return onRejected(err);
      throw err;
    }
  }

  async execute(final: 'single' | 'maybeSingle' | null = null): Promise<DBResponse> {
    // If router is Online, use Supabase
    if (this.router.mode === 'online') {
      const client = this.router.realClient;
      if (!client) throw new Error('[DBRouter] Online client not available.');

      try {
        const q = client.from(this.table) as unknown as Record<string, (...args: unknown[]) => Promise<DBResponse>>;

        if (this.action === 'upsert') return await q.upsert!(this.actionData, this.actionOpts);
        if (this.action === 'insert') return await q.insert!(this.actionData);

        if (this.action === 'update') {
          let updQ = (q as unknown as Record<string, (d: unknown) => unknown>).update!(this.actionData) as Record<string, (...args: unknown[]) => unknown>;
          this.chain.forEach(s => { updQ = updQ[s.type]!(...s.args) as Record<string, (...args: unknown[]) => unknown>; });
          return await (updQ as unknown as Promise<DBResponse>);
        }

        if (this.action === 'delete') {
          let delQ = (q as unknown as Record<string, () => unknown>).delete!() as Record<string, (...args: unknown[]) => unknown>;
          this.chain.forEach(s => { delQ = delQ[s.type]!(...s.args) as Record<string, (...args: unknown[]) => unknown>; });
          return await (delQ as unknown as Promise<DBResponse>);
        }

        // Default: select
        let selQ = q as Record<string, (...args: unknown[]) => unknown>;
        this.chain.forEach(s => { 
          selQ = selQ[s.type]!(...s.args) as Record<string, (...args: unknown[]) => unknown>; 
        });
        return final ? await (selQ as unknown as Record<string, () => Promise<DBResponse>>)[final]!() : await (selQ as unknown as Promise<DBResponse>);
      } catch (err: unknown) {
        logger.error('DBRouter', `Online query failed for table ${this.table}: ${(err as Error).message}`);

        // Detect network errors (fetch failures)
        const errMsg = (err instanceof Error ? err.message : String(err)).toLowerCase();
        if (errMsg.includes('fetch') || errMsg.includes('network') || errMsg.includes('failed to fetch')) {
          if (typeof window !== 'undefined') {
            window.dispatchEvent(new CustomEvent('db-connection-error'));
          }
        }

        throw err;
      }
    }

    // Otherwise, use SQLite
    return this.executeLocal(final);
  }

  async executeLocal(final: 'single' | 'maybeSingle' | null = null): Promise<DBResponse> {
    try {
      const sqliteDb = await initSQLite();
      if (!sqliteDb) return { data: null, error: 'Database not initialized' };

      if (this.action === 'upsert') return await this._executeLocalUpsert(sqliteDb);
      if (this.action === 'insert') return await this._executeLocalUpsert(sqliteDb); // Reusing upsert for simplicity in local mode
      if (this.action === 'update') return await this._executeLocalUpdate(sqliteDb);
      if (this.action === 'delete') return await this._executeLocalDelete(sqliteDb);

      // Default: select
      let sql = `SELECT * FROM ${this.table}`; // Simplistic, cols not used yet
      const where: string[] = [];
      const params: unknown[] = [];

      this.chain.forEach(s => {
        if (s.type === 'eq') { where.push(`${s.args[0]} = ?`); params.push(s.args[1]); }
        if (s.type === 'neq') { where.push(`${s.args[0]} != ?`); params.push(s.args[1]); }
        if (s.type === 'gt') { where.push(`${s.args[0]} > ?`); params.push(s.args[1]); }
        if (s.type === 'lt') { where.push(`${s.args[0]} < ?`); params.push(s.args[1]); }
        if (s.type === 'gte') { where.push(`${s.args[0]} >= ?`); params.push(s.args[1]); }
        if (s.type === 'lte') { where.push(`${s.args[0]} <= ?`); params.push(s.args[1]); }
        if (s.type === 'in') {
          const arr = (s.args[1] as unknown[]) || [];
          const marks = arr.map(() => '?').join(',');
          where.push(`${s.args[0]} IN (${marks})`);
          params.push(...arr);
        }
        if (s.type === 'is') {
          if (s.args[1] === null) where.push(`${s.args[0]} IS NULL`);
          else { where.push(`${s.args[0]} IS ?`); params.push(s.args[1]); }
        }
        if (s.type === 'not') {
          const [colNot, opNot, valNot] = s.args as [string, string, unknown];
          if (opNot === 'eq') {
            where.push(`${colNot} <> ?`);
            params.push(valNot);
          } else if (opNot === 'is' && valNot === null) {
            where.push(`${colNot} IS NOT NULL`);
          }
        }
        if (s.type === 'match') {
          Object.entries(s.args[0] as Record<string, unknown>).forEach(([k, v]) => {
            where.push(`${k} = ?`);
            params.push(v);
          });
        }
        if (s.type === 'ilike') {
          where.push(`${s.args[0]} LIKE ?`);
          params.push((s.args[1] as string).replace(/\*/g, '%'));
        }
        if (s.type === 'or') {
          const filterStr = s.args[0] as string;
          if (filterStr.includes('and(')) {
            const clauses = filterStr.split(/\),?/);
            const orClauses: string[] = [];
            clauses.forEach(clause => {
              const cleanClause = clause.replace(/and\(/g, '').trim();
              if (!cleanClause) return;
              const subFilters = cleanClause.split(',');
              const andClauses: string[] = [];
              subFilters.forEach(f => {
                const parts = f.split('.');
                if (parts.length >= 3) {
                  const col = parts[0];
                  const op = parts[1];
                  const val = parts.slice(2).join('.');
                  if (op === 'eq') {
                    andClauses.push(`${col} = ?`);
                    params.push(val);
                  }
                }
              });
              if (andClauses.length > 0) {
                orClauses.push(`(${andClauses.join(' AND ')})`);
              }
            });
            if (orClauses.length > 0) {
              where.push(`(${orClauses.join(' OR ')})`);
            }
          } else {
            const subFilters = filterStr.split(',');
            const subClauses: string[] = [];
            subFilters.forEach(f => {
              const parts = f.split('.');
              if (parts.length >= 3) {
                const col = parts[0];
                const op = parts[1];
                const val = parts.slice(2).join('.');
                if (op === 'eq') {
                  subClauses.push(`${col} = ?`);
                  params.push(val);
                } else if (op === 'neq') {
                  subClauses.push(`${col} != ?`);
                  params.push(val);
                }
              }
            });
            if (subClauses.length > 0) {
              where.push(`(${subClauses.join(' OR ')})`);
            }
          }
        }
      });

      if (where.length > 0) sql += ` WHERE ${where.join(' AND ')}`;

      // Order and Limit
      this.chain.forEach(s => {
        if (s.type === 'order') {
          const opts = s.args[1] as { ascending?: boolean };
          sql += ` ORDER BY ${s.args[0]} ${opts.ascending ? 'ASC' : 'DESC'}`;
        }
        if (s.type === 'limit') sql += ` LIMIT ${s.args[0]}`;
      });

      let count: number | undefined = undefined;
      const selectItem = this.chain.find(s => s.type === 'select');
      const selectOpts = (selectItem?.args[1] as { count?: string, head?: boolean }) || {};

      if (selectOpts.count) {
        let countSql = `SELECT COUNT(*) as total FROM ${this.table}`;
        if (where.length > 0) countSql += ` WHERE ${where.join(' AND ')}`;
        const countRes = await queryLocal(countSql, params);
        count = (countRes[0] as { total: number })?.total || 0;
      }

      if (selectOpts.head) {
        return { data: [], error: null, count };
      }

      const data = await queryLocal(sql, params);

      // Auto-parse JSON fields (known to be JSON in this project)
      data.forEach((row: Record<string, unknown>) => {
        if (row.save_data && typeof row.save_data === 'string') try { row.save_data = JSON.parse(row.save_data); } catch(_e){ /* ignore */ }
        if (row.team_data && typeof row.team_data === 'string') try { row.team_data = JSON.parse(row.team_data); } catch(_e){ /* ignore */ }
        if (row.data && typeof row.data === 'string') try { row.data = JSON.parse(row.data); } catch(_e){ /* ignore */ }
        if (row.config && typeof row.config === 'string') try { row.config = JSON.parse(row.config); } catch(_e){ /* ignore */ }
        if (row.schedule && typeof row.schedule === 'string') try { row.schedule = JSON.parse(row.schedule); } catch(_e){ /* ignore */ }
        if (row.asset_data && typeof row.asset_data === 'string') try { row.asset_data = JSON.parse(row.asset_data); } catch(_e){ /* ignore */ }
      });

      if (final === 'single') return { data: data[0] || null, error: data.length === 0 ? { message: 'Not found' } : null, count };
      if (final === 'maybeSingle') return { data: data[0] || null, error: null, count };
      return { data, error: null, count };
    } catch (e: unknown) {
      logger.error('ProxyQuery', `executeLocal critical failure: ${(e as Error).message}`);
      return { data: null, error: e };
    }
  }

  async _executeLocalUpsert(sqliteDb: { run: (sql: string, params: unknown[]) => void }): Promise<DBResponse> {
    try {
      const values = Array.isArray(this.actionData) ? this.actionData : [this.actionData];
      for (const row of values) {
        if (typeof row !== 'object' || row === null) continue;
        const r = row as Record<string, unknown>;
        const cols = Object.keys(r);
        const marks = cols.map(() => '?').join(',');
        const vals = cols.map(c => typeof r[c] === 'object' ? JSON.stringify(r[c]) : r[c]);
        sqliteDb.run(`INSERT OR REPLACE INTO ${this.table} (${cols.join(',')}) VALUES (${marks})`, vals);
      }
      await persistSQLite();
      return { data: this.actionData, error: null };
    } catch (e: unknown) {
      logger.error('ProxyQuery', `Upsert/Insert failed for ${this.table}: ${(e as Error).message}`);
      return { data: null, error: e };
    }
  }

  async _executeLocalUpdate(sqliteDb: { run: (sql: string, params: unknown[]) => void }): Promise<DBResponse> {
    try {
      const data = this.actionData as Record<string, unknown>;
      const setClause = Object.keys(data).map(k => `${k} = ?`).join(',');
      const params: unknown[] = Object.values(data).map(v => typeof v === 'object' ? JSON.stringify(v) : v);

      const where: string[] = [];
      this.chain.forEach(s => {
        if (s.type === 'eq') { where.push(`${s.args[0]} = ?`); params.push(s.args[1]); }
        if (s.type === 'match') {
          Object.entries(s.args[0] as Record<string, unknown>).forEach(([k, v]) => {
            where.push(`${k} = ?`); params.push(v);
          });
        }
      });

      let sql = `UPDATE ${this.table} SET ${setClause}`;
      if (where.length > 0) sql += ` WHERE ${where.join(' AND ')}`;
      sqliteDb.run(sql, params);
      await persistSQLite();
      return { data: this.actionData, error: null };
    } catch (e: unknown) {
      logger.error('ProxyQuery', `Update failed for ${this.table}: ${(e as Error).message}`);
      return { data: null, error: e };
    }
  }

  async _executeLocalDelete(sqliteDb: { run: (sql: string, params: unknown[]) => void }): Promise<DBResponse> {
    try {
      const params: unknown[] = [];
      const where: string[] = [];
      this.chain.forEach(s => {
        if (s.type === 'eq') { where.push(`${s.args[0]} = ?`); params.push(s.args[1]); }
      });

      let sql = `DELETE FROM ${this.table}`;
      if (where.length > 0) sql += ` WHERE ${where.join(' AND ')}`;
      sqliteDb.run(sql, params);
      await persistSQLite();
      return { data: null, error: null };
    } catch (e: unknown) {
      logger.error('ProxyQuery', `Delete failed for ${this.table}: ${(e as Error).message}`);
      return { data: null, error: e };
    }
  }
}

import { queryLocal, persistSQLite } from '../sqliteEngine.ts';
import type { SQLiteDatabase } from '../sqliteEngine.ts';
import type { DBResponse } from '@/types/database';

interface OfflineSaveData {
  box?: Record<string, unknown>[];
  team?: Record<string, unknown>[];
  inventory?: Record<string, number>;
  money?: number;
  [key: string]: unknown;
}

interface ClaimAssetPayload {
  type: 'pokemon' | 'money' | 'item';
  data: Record<string, unknown> | number | string;
}

export async function emulatePublishListing(
  sqliteDb: SQLiteDatabase,
  params: Record<string, unknown>,
  context: { userId: string; username: string }
): Promise<DBResponse> {
  const { p_listing_type, p_asset_data, p_price } = params as { p_listing_type: 'pokemon' | 'item', p_asset_data: Record<string, unknown>, p_price: number };
  const { userId, username } = context;

  const saves = await queryLocal("SELECT save_data FROM game_saves WHERE user_id = ?", [userId]);
  if (saves.length === 0) return { data: null, error: { message: 'Save not found' } };
  const saveObj = (typeof saves[0]!.save_data === 'string' ? JSON.parse(saves[0]!.save_data as string) : saves[0]!.save_data) as OfflineSaveData;

  if (p_listing_type === 'pokemon') {
    const uid = p_asset_data.uid as string;
    const boxLenBefore = saveObj.box?.length || 0;
    saveObj.box = (saveObj.box || []).filter((p) => p.uid !== uid);
    if (saveObj.box.length === boxLenBefore) {
      const teamLenBefore = saveObj.team?.length || 0;
      saveObj.team = (saveObj.team || []).filter((p) => p.uid !== uid);
      if (saveObj.team.length === teamLenBefore) {
        return { data: null, error: { message: 'Pokémon no encontrado en tu inventario.' } };
      }
    }
  } else {
    const itemName = p_asset_data.name as string;
    const qty = (p_asset_data.qty as number) || 1;
    saveObj.inventory = saveObj.inventory || {};
    const currentQty = saveObj.inventory[itemName] || 0;
    if (currentQty < qty) {
      return { data: null, error: { message: 'Cantidad insuficiente de objetos.' } };
    }
    saveObj.inventory[itemName] = currentQty - qty;
    if (saveObj.inventory[itemName]! <= 0) {
      delete saveObj.inventory[itemName];
    }
  }

  sqliteDb.run(
    "UPDATE game_saves SET save_data = ?, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE user_id = ?",
    [JSON.stringify(saveObj), userId]
  );

  sqliteDb.run(
    "INSERT INTO market_listings (seller_id, seller_name, listing_type, data, price, status) VALUES (?, ?, ?, ?, ?, 'active')",
    [userId, username, p_listing_type, JSON.stringify(p_asset_data), p_price]
  );

  await persistSQLite();
  return { data: 'list_' + Math.random().toString(36).substring(2, 11), error: null };
}

export async function emulateBuyListing(
  sqliteDb: SQLiteDatabase,
  params: Record<string, unknown>,
  context: { userId: string }
): Promise<DBResponse> {
  const { p_listing_id } = params;
  const { userId } = context;

  const listings = await queryLocal("SELECT * FROM market_listings WHERE id = ? AND status = 'active'", [p_listing_id]);
  if (listings.length === 0) return { data: null, error: { message: 'La publicación ya no está disponible o fue vendida.' } };
  const listing = listings[0] as { id: string | number; seller_id: string; listing_type: 'pokemon' | 'item'; price: number; data: string | Record<string, unknown> };
  if (listing.seller_id === userId) return { data: null, error: { message: 'No puedes comprar tu propia oferta.' } };

  const buyerSaves = await queryLocal("SELECT save_data FROM game_saves WHERE user_id = ?", [userId]);
  if (buyerSaves.length === 0) return { data: null, error: { message: 'Save not found' } };
  const buyerSave = (typeof buyerSaves[0]!.save_data === 'string' ? JSON.parse(buyerSaves[0]!.save_data as string) : buyerSaves[0]!.save_data) as OfflineSaveData;

  const price = Number(listing.price);
  if ((buyerSave.money || 0) < price) {
    return { data: null, error: { message: 'Fondos insuficientes.' } };
  }

  buyerSave.money = (buyerSave.money || 0) - price;
  sqliteDb.run(
    "UPDATE game_saves SET save_data = ?, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE user_id = ?",
    [JSON.stringify(buyerSave), userId]
  );

  let assetDataObj = listing.data;
  if (typeof assetDataObj === 'string') {
    try {
      assetDataObj = JSON.parse(assetDataObj) as Record<string, unknown>;
    } catch (_e) {
      void 0;
    }
  }

  const claimIdBuyer = 'claim_' + Math.random().toString(36).substring(2, 11);
  const buyerAssetPayload = {
    type: listing.listing_type === 'pokemon' ? 'pokemon' : 'item',
    data: assetDataObj
  };
  sqliteDb.run(
    "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'gts', ?, ?)",
    [claimIdBuyer, userId, p_listing_id, JSON.stringify(buyerAssetPayload)]
  );

  const claimIdSeller = 'claim_' + Math.random().toString(36).substring(2, 11);
  const finalPayment = Math.floor(price * 0.95);
  const sellerAssetPayload = {
    type: 'money',
    data: finalPayment
  };
  sqliteDb.run(
    "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'gts', ?, ?)",
    [claimIdSeller, listing.seller_id, p_listing_id, JSON.stringify(sellerAssetPayload)]
  );

  sqliteDb.run(
    "UPDATE market_listings SET status = 'sold', buyer_id = ?, created_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = ?",
    [userId, p_listing_id]
  );

  await persistSQLite();
  return { data: buyerSave, error: null };
}

export async function emulateCancelListing(
  sqliteDb: SQLiteDatabase,
  params: Record<string, unknown>,
  context: { userId: string }
): Promise<DBResponse> {
  const { p_listing_id } = params;
  const { userId } = context;

  const listings = await queryLocal("SELECT * FROM market_listings WHERE id = ? AND status = 'active'", [p_listing_id]);
  if (listings.length === 0) return { data: null, error: { message: 'Publicación no encontrada o procesada.' } };
  const listing = listings[0] as { id: string | number; seller_id: string; listing_type: 'pokemon' | 'item'; data: string | Record<string, unknown> };
  if (listing.seller_id !== userId) return { data: null, error: { message: 'No autorizado.' } };

  let assetDataObj = listing.data;
  if (typeof assetDataObj === 'string') {
    try {
      assetDataObj = JSON.parse(assetDataObj) as Record<string, unknown>;
    } catch (_e) {
      void 0;
    }
  }

  const saves = await queryLocal("SELECT save_data FROM game_saves WHERE user_id = ?", [userId]);
  if (saves.length === 0) return { data: null, error: { message: 'Save not found' } };
  const saveObj = (typeof saves[0]!.save_data === 'string' ? JSON.parse(saves[0]!.save_data as string) : saves[0]!.save_data) as OfflineSaveData;

  if (listing.listing_type === 'pokemon') {
    saveObj.box = saveObj.box || [];
    saveObj.box.push(assetDataObj as Record<string, unknown>);
  } else {
    saveObj.inventory = saveObj.inventory || {};
    const itemName = (assetDataObj as { name: string }).name;
    const qty = Number((assetDataObj as { qty?: number }).qty || 1);
    saveObj.inventory[itemName] = (saveObj.inventory[itemName] || 0) + qty;
  }

  sqliteDb.run(
    "UPDATE game_saves SET save_data = ?, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE user_id = ?",
    [JSON.stringify(saveObj), userId]
  );

  sqliteDb.run(
    "UPDATE market_listings SET status = 'cancelled', created_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = ?",
    [p_listing_id]
  );

  await persistSQLite();
  return { data: saveObj, error: null };
}

export async function emulateClaimAsset(
  sqliteDb: SQLiteDatabase,
  params: Record<string, unknown>,
  context: { userId: string }
): Promise<DBResponse> {
  const { p_claim_id } = params;
  const { userId } = context;

  const claims = await queryLocal("SELECT * FROM claim_queue WHERE id = ?", [p_claim_id]);
  if (claims.length === 0) return { data: null, error: { message: 'Reclamo no encontrado.' } };
  const claim = claims[0] as { user_id: string; asset_data: string | ClaimAssetPayload };
  if (claim.user_id !== userId) return { data: null, error: { message: 'No autorizado.' } };

  const userSaves = await queryLocal("SELECT save_data FROM game_saves WHERE user_id = ?", [userId]);
  if (userSaves.length === 0) return { data: null, error: { message: 'Save not found' } };
  const userSave = (typeof userSaves[0]!.save_data === 'string' ? JSON.parse(userSaves[0]!.save_data as string) : userSaves[0]!.save_data) as OfflineSaveData;

  let assetPayload: ClaimAssetPayload;
  if (typeof claim.asset_data === 'string') {
    assetPayload = JSON.parse(claim.asset_data) as ClaimAssetPayload;
  } else {
    assetPayload = claim.asset_data as ClaimAssetPayload;
  }

  if (assetPayload.type === 'pokemon') {
    userSave.team = userSave.team || [];
    if (userSave.team.length < 6) {
      userSave.team.push(assetPayload.data as Record<string, unknown>);
    } else {
      userSave.box = userSave.box || [];
      userSave.box.push(assetPayload.data as Record<string, unknown>);
    }
  } else if (assetPayload.type === 'money') {
    userSave.money = (userSave.money || 0) + Number(assetPayload.data);
  } else if (assetPayload.type === 'item') {
    userSave.inventory = userSave.inventory || {};
    const itemData = assetPayload.data as { name: string; qty?: number };
    const itemName = itemData.name;
    const qty = Number(itemData.qty || 1);
    userSave.inventory[itemName] = (userSave.inventory[itemName] || 0) + qty;
  }

  sqliteDb.run(
    "UPDATE game_saves SET save_data = ?, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE user_id = ?",
    [JSON.stringify(userSave), userId]
  );

  sqliteDb.run("DELETE FROM claim_queue WHERE id = ?", [p_claim_id]);

  await persistSQLite();
  return { data: userSave, error: null };
}

import { queryLocal, persistSQLite } from '../sqliteEngine.ts';
import type { SQLiteDatabase } from '../sqliteEngine.ts';
import type { DBResponse } from '@/types/database';

interface OfflineSaveData {
  box?: Record<string, unknown>[];
  team?: Record<string, unknown>[];
  inventory?: Record<string, number>;
  money?: number;
  [key: string]: unknown;
}

export async function emulateSendTradeOffer(
  sqliteDb: SQLiteDatabase,
  params: Record<string, unknown>,
  context: { userId: string }
): Promise<DBResponse> {
  const {
    p_receiver_id,
    p_offer_pokemon,
    p_offer_items,
    p_offer_money,
    p_request_pokemon,
    p_request_items,
    p_request_money,
    p_message
  } = params as {
    p_receiver_id: string;
    p_offer_pokemon: Record<string, unknown> | null;
    p_offer_items: Record<string, number> | null;
    p_offer_money: number;
    p_request_pokemon: Record<string, unknown> | null;
    p_request_items: Record<string, number> | null;
    p_request_money: number;
    p_message: string;
  };
  const { userId } = context;

  const senderSaves = await queryLocal("SELECT save_data FROM game_saves WHERE user_id = ?", [userId]);
  if (senderSaves.length === 0) return { data: null, error: { message: 'Save not found' } };
  const senderSave = (typeof senderSaves[0]!.save_data === 'string' ? JSON.parse(senderSaves[0]!.save_data as string) : senderSaves[0]!.save_data) as OfflineSaveData;

  // 1. Quitar Pokemon Ofrecido
  if (p_offer_pokemon) {
    const uid = p_offer_pokemon.uid as string;
    const teamLenBefore = senderSave.team?.length || 0;
    senderSave.team = (senderSave.team || []).filter((p) => p.uid !== uid);
    if (senderSave.team.length === teamLenBefore) {
      const boxLenBefore = senderSave.box?.length || 0;
      senderSave.box = (senderSave.box || []).filter((p) => p.uid !== uid);
      if (senderSave.box.length === boxLenBefore) {
        return { data: null, error: { message: 'Pokémon no encontrado en tu inventario.' } };
      }
    }
  }

  // 2. Quitar Items Ofrecidos
  if (p_offer_items) {
    senderSave.inventory = senderSave.inventory || {};
    for (const [itemName, qty] of Object.entries(p_offer_items)) {
      const currentQty = senderSave.inventory[itemName] || 0;
      if (currentQty < qty) {
        return { data: null, error: { message: `Cantidad insuficiente de ${itemName}.` } };
      }
      senderSave.inventory[itemName] = currentQty - qty;
      if (senderSave.inventory[itemName]! <= 0) {
        delete senderSave.inventory[itemName];
      }
    }
  }

  // 3. Quitar Dinero Ofrecido
  if (p_offer_money > 0) {
    const currentMoney = senderSave.money || 0;
    if (currentMoney < p_offer_money) {
      return { data: null, error: { message: 'Dinero insuficiente.' } };
    }
    senderSave.money = currentMoney - p_offer_money;
  }

  sqliteDb.run(
    "UPDATE game_saves SET save_data = ?, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE user_id = ?",
    [JSON.stringify(senderSave), userId]
  );

  const generatedId = crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 11) + Temporal.Now.instant().epochMilliseconds.toString(36);

  sqliteDb.run(
    "INSERT INTO trade_offers (id, sender_id, receiver_id, offer_pokemon, offer_items, offer_money, request_pokemon, request_items, request_money, message, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending')",
    [
      generatedId,
      userId,
      p_receiver_id,
      p_offer_pokemon ? JSON.stringify(p_offer_pokemon) : null,
      p_offer_items ? JSON.stringify(p_offer_items) : null,
      p_offer_money,
      p_request_pokemon ? JSON.stringify(p_request_pokemon) : null,
      p_request_items ? JSON.stringify(p_request_items) : null,
      p_request_money,
      p_message || '',
    ]
  );

  await persistSQLite();
  return { data: generatedId, error: null };
}

export async function emulateAcceptTrade(
  sqliteDb: SQLiteDatabase,
  params: Record<string, unknown>,
  context: { userId: string }
): Promise<DBResponse> {
  const { p_trade_id } = params as { p_trade_id: string | number };
  const { userId } = context;

  const trades = await queryLocal("SELECT * FROM trade_offers WHERE id = ?", [p_trade_id]);
  if (trades.length === 0) return { data: null, error: { message: 'Oferta no válida o ya procesada.' } };
  const trade = trades[0] as {
    id: number;
    sender_id: string;
    receiver_id: string;
    offer_pokemon: string | null;
    offer_items: string | null;
    offer_money: number;
    request_pokemon: string | null;
    request_items: string | null;
    request_money: number;
    status: string;
  };

  if (trade.status !== 'pending') {
    return { data: null, error: { message: 'Oferta no válida o ya procesada.' } };
  }
  if (trade.receiver_id !== userId) {
    return { data: null, error: { message: 'No autorizado.' } };
  }

  const receiverSaves = await queryLocal("SELECT save_data FROM game_saves WHERE user_id = ?", [userId]);
  if (receiverSaves.length === 0) return { data: null, error: { message: 'Save not found' } };
  const receiverSave = (typeof receiverSaves[0]!.save_data === 'string' ? JSON.parse(receiverSaves[0]!.save_data as string) : receiverSaves[0]!.save_data) as OfflineSaveData;

  // Parse columns since SQLite stores objects as strings/JSON strings
  const offerPokeObj = trade.offer_pokemon ? (typeof trade.offer_pokemon === 'string' ? JSON.parse(trade.offer_pokemon) : trade.offer_pokemon) : null;
  const offerItemsObj = trade.offer_items ? (typeof trade.offer_items === 'string' ? JSON.parse(trade.offer_items) : trade.offer_items) : null;
  const requestPokeObj = trade.request_pokemon ? (typeof trade.request_pokemon === 'string' ? JSON.parse(trade.request_pokemon) : trade.request_pokemon) : null;
  const requestItemsObj = trade.request_items ? (typeof trade.request_items === 'string' ? JSON.parse(trade.request_items) : trade.request_items) : null;

  // 1. Validar y Quitar lo que el receptor ofrece (request del trade)
  // 1a. Pokémon
  if (requestPokeObj) {
    const uid = requestPokeObj.uid as string;
    const teamLenBefore = receiverSave.team?.length || 0;
    receiverSave.team = (receiverSave.team || []).filter((p) => p.uid !== uid);
    if (receiverSave.team.length === teamLenBefore) {
      const boxLenBefore = receiverSave.box?.length || 0;
      receiverSave.box = (receiverSave.box || []).filter((p) => p.uid !== uid);
      if (receiverSave.box.length === boxLenBefore) {
        return { data: null, error: { message: 'Pokémon solicitado no encontrado en tu inventario.' } };
      }
    }
  }

  // 1b. Dinero
  if (trade.request_money > 0) {
    const currentMoney = receiverSave.money || 0;
    if (currentMoney < trade.request_money) {
      return { data: null, error: { message: 'Dinero insuficiente para aceptar el intercambio.' } };
    }
    receiverSave.money = currentMoney - trade.request_money;
  }

  // 1c. Items
  if (requestItemsObj) {
    receiverSave.inventory = receiverSave.inventory || {};
    for (const [itemName, qty] of Object.entries(requestItemsObj as Record<string, number>)) {
      const currentQty = receiverSave.inventory[itemName] || 0;
      if (currentQty < qty) {
        return { data: null, error: { message: `Cantidad insuficiente de ${itemName}.` } };
      }
      receiverSave.inventory[itemName] = currentQty - qty;
      if (receiverSave.inventory[itemName]! <= 0) {
        delete receiverSave.inventory[itemName];
      }
    }
  }

  // 2. Persistir cambio en save del receptor
  sqliteDb.run(
    "UPDATE game_saves SET save_data = ?, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE user_id = ?",
    [JSON.stringify(receiverSave), userId]
  );

  // 3. Mover activos a la COLA DE RECLAMO
  // Lo que el emisor ofreció va al receptor (userId)
  if (offerPokeObj) {
    const claimId = 'claim_' + Math.random().toString(36).substring(2, 11);
    sqliteDb.run(
      "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'trade', ?, ?)",
      [claimId, userId, String(p_trade_id), JSON.stringify({ type: 'pokemon', data: offerPokeObj })]
    );
  }
  if (trade.offer_money > 0) {
    const claimId = 'claim_' + Math.random().toString(36).substring(2, 11);
    sqliteDb.run(
      "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'trade', ?, ?)",
      [claimId, userId, String(p_trade_id), JSON.stringify({ type: 'money', data: trade.offer_money })]
    );
  }
  if (offerItemsObj) {
    for (const [itemName, qty] of Object.entries(offerItemsObj as Record<string, number>)) {
      if (qty > 0) {
        const claimId = 'claim_' + Math.random().toString(36).substring(2, 11);
        sqliteDb.run(
          "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'trade', ?, ?)",
          [claimId, userId, String(p_trade_id), JSON.stringify({ type: 'item', data: { name: itemName, qty } })]
        );
      }
    }
  }

  // Lo que el receptor ofreció va al emisor (trade.sender_id)
  if (requestPokeObj) {
    const claimId = 'claim_' + Math.random().toString(36).substring(2, 11);
    sqliteDb.run(
      "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'trade', ?, ?)",
      [claimId, trade.sender_id, String(p_trade_id), JSON.stringify({ type: 'pokemon', data: requestPokeObj })]
    );
  }
  if (trade.request_money > 0) {
    const claimId = 'claim_' + Math.random().toString(36).substring(2, 11);
    sqliteDb.run(
      "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'trade', ?, ?)",
      [claimId, trade.sender_id, String(p_trade_id), JSON.stringify({ type: 'money', data: trade.request_money })]
    );
  }
  if (requestItemsObj) {
    for (const [itemName, qty] of Object.entries(requestItemsObj as Record<string, number>)) {
      if (qty > 0) {
        const claimId = 'claim_' + Math.random().toString(36).substring(2, 11);
        sqliteDb.run(
          "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'trade', ?, ?)",
          [claimId, trade.sender_id, String(p_trade_id), JSON.stringify({ type: 'item', data: { name: itemName, qty } })]
        );
      }
    }
  }

  // 4. Finalizar trade
  sqliteDb.run(
    "UPDATE trade_offers SET status = 'accepted', created_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = ?",
    [p_trade_id]
  );

  await persistSQLite();
  return { data: true, error: null };
}

export async function emulateRejectTrade(
  sqliteDb: SQLiteDatabase,
  params: Record<string, unknown>,
  context: { userId: string }
): Promise<DBResponse> {
  const { p_trade_id } = params as { p_trade_id: string | number };
  const { userId } = context;

  const trades = await queryLocal("SELECT * FROM trade_offers WHERE id = ?", [p_trade_id]);
  if (trades.length === 0) return { data: null, error: { message: 'Oferta no encontrada.' } };
  const trade = trades[0] as {
    id: number;
    sender_id: string;
    receiver_id: string;
    offer_pokemon: string | null;
    offer_items: string | null;
    offer_money: number;
    status: string;
  };

  if (trade.status !== 'pending') {
    return { data: null, error: { message: 'Solo se pueden rechazar u ocultar ofertas pendientes.' } };
  }
  if (trade.sender_id !== userId && trade.receiver_id !== userId) {
    return { data: null, error: { message: 'No autorizado.' } };
  }

  // Devolver activos al emisor (trade.sender_id) en su claim_queue
  const offerPokeObj = trade.offer_pokemon ? (typeof trade.offer_pokemon === 'string' ? JSON.parse(trade.offer_pokemon) : trade.offer_pokemon) : null;
  const offerItemsObj = trade.offer_items ? (typeof trade.offer_items === 'string' ? JSON.parse(trade.offer_items) : trade.offer_items) : null;

  if (offerPokeObj) {
    const claimId = 'claim_' + Math.random().toString(36).substring(2, 11);
    sqliteDb.run(
      "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'trade_refund', ?, ?)",
      [claimId, trade.sender_id, String(p_trade_id), JSON.stringify({ type: 'pokemon', data: offerPokeObj })]
    );
  }
  if (trade.offer_money > 0) {
    const claimId = 'claim_' + Math.random().toString(36).substring(2, 11);
    sqliteDb.run(
      "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'trade_refund', ?, ?)",
      [claimId, trade.sender_id, String(p_trade_id), JSON.stringify({ type: 'money', data: trade.offer_money })]
    );
  }
  if (offerItemsObj) {
    for (const [itemName, qty] of Object.entries(offerItemsObj as Record<string, number>)) {
      if (qty > 0) {
        const claimId = 'claim_' + Math.random().toString(36).substring(2, 11);
        sqliteDb.run(
          "INSERT INTO claim_queue (id, user_id, source_type, source_id, asset_data) VALUES (?, ?, 'trade_refund', ?, ?)",
          [claimId, trade.sender_id, String(p_trade_id), JSON.stringify({ type: 'item', data: { name: itemName, qty } })]
        );
      }
    }
  }

  // Marcar como rechazado
  sqliteDb.run(
    "UPDATE trade_offers SET status = 'rejected', created_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = ?",
    [p_trade_id]
  );

  await persistSQLite();
  return { data: true, error: null };
}

/**
 * src/logic/db/sqlTranslator.ts
 * Unified SQL translation logic for Poké Vicio.
 * Used by both frontend (sqliteEngine.ts) and backend/tools (validate_sql_migrations.ts).
 */

/**
 * Splits SQL by semicolon, respecting $$ blocks and strings.
 */
export function splitSQLStatements(sql: string): string[] {
  const statements: string[] = [];
  let current = '';
  let inDollarQuote = false;
  let inString = false;
  let inBlockComment = false;
  let inLineComment = false;

  for (let i = 0; i < sql.length; i++) {
    const char = sql[i];
    const nextChar = sql[i + 1];

    // 1. Handle Line Comments (--)
    if (inLineComment) {
      if (char === '\n') inLineComment = false;
      if (i === sql.length - 1) inLineComment = false; 
      continue;
    }

    // 2. Handle Block Comments (/* */)
    if (inBlockComment) {
      if (char === '*' && nextChar === '/') {
        inBlockComment = false;
        i++;
      }
      continue;
    }

    if (!inDollarQuote && !inString) {
      // Detect start of Line Comment
      if (char === '-' && nextChar === '-') {
        inLineComment = true;
        i++;
        continue;
      }
      // Detect start of Block Comment
      if (char === '/' && nextChar === '*') {
        inBlockComment = true;
        i++;
        continue;
      }

      if (char === '$' && nextChar === '$') {
        inDollarQuote = true;
        current += '$$';
        i++;
        continue;
      }
      if (char === "'") {
        inString = true;
        current += "'";
        continue;
      }
      if (char === ';') {
        if (current.trim()) statements.push(current.trim());
        current = '';
        continue;
      }
    } else if (inDollarQuote) {
      if (char === '$' && nextChar === '$') {
        inDollarQuote = false;
        current += '$$';
        i++;
        continue;
      }
    } else if (inString) {
      if (char === "'" && sql[i-1] !== '\\') {
        inString = false;
        current += "'";
        continue;
      }
    }
    current += char;
  }

  if (current.trim()) statements.push(current.trim());
  return statements.filter(s => s.length > 0);
}

/**
 * Translates common Postgres syntax to SQLite.
 */
export function translatePostgresToSqlite(sql: string): string {
  if (!sql) return '';
  const cleanSql = sql.trim();
  const upperSql = cleanSql.toUpperCase();

  // Logic Skipping for PostgreSQL-only constructs
  const skipPatterns = [
    'CREATE FUNCTION',
    'CREATE OR REPLACE FUNCTION',
    'DROP FUNCTION',
    'DO $$',
    'CREATE POLICY',
    'DROP POLICY',
    'ALTER PUBLICATION',
    'COMMENT ON',
    'CREATE TRIGGER',
    'DROP TRIGGER',
    'CREATE EXTENSION',
    'REVOKE',
    'GRANT',
    'ALTER FUNCTION',
    'SELECT SETVAL'
  ];

  if (skipPatterns.some(pattern => upperSql.startsWith(pattern))) {
    return '';
  }

  if (upperSql.startsWith('ALTER TABLE') && (
    upperSql.includes('ENABLE ROW LEVEL SECURITY') ||
    upperSql.includes('FORCE ROW LEVEL SECURITY') ||
    upperSql.includes('REPLICA IDENTITY')
  )) {
    return '';
  }

  return cleanSql
    .replace(/public\./gi, '')
    // 1. Types & Casts
    .replace(/\bJSONB\b/gi, 'TEXT')
    .replace(/\bUUID\b/gi, 'TEXT')
    .replace(/\bTIMESTAMPTZ\b/gi, 'TEXT')
    .replace(/\bTIMESTAMP\b/gi, 'TEXT')
    .replace(/\bBIGINT\b/gi, 'INTEGER')
    .replace(/\b(BIGSERIAL|SERIAL)\s+PRIMARY\s+KEY\b/gi, 'INTEGER PRIMARY KEY AUTOINCREMENT')
    .replace(/\b(BIGSERIAL|SERIAL)\b/gi, 'INTEGER')
    .replace(/::[a-z0-9]+/gi, '')
    // 2. Functions
    .replace(/\bNOW\(\)/gi, "strftime('%Y-%m-%dT%H:%M:%SZ', 'now')")
    .replace(/\bgen_random_uuid\(\)/gi, "hex(randomblob(16))")
    .replace(/\bEXTRACT\(epoch\s+FROM\s+([^)]+)\)/gi, "unixepoch($1)")
    .replace(/\bARRAY_AGG\b/gi, "json_group_array")
    .replace(/\bstring_agg\b/gi, "group_concat")
    .replace(/\bjsonb_build_object\b/gi, "json_object")
    .replace(/\bjsonb_set\b/gi, "json_set")
    .replace(/\bjsonb_agg\b/gi, "json_group_array")
    .replace(/\bjsonb_object_agg\b/gi, "json_group_object")
    .replace(/\bjsonb_build_array\b/gi, "json_array")
    .replace(/\bjsonb_array_elements\b/gi, "json_each")
    .replace(/\bjsonb_array_length\b/gi, "json_array_length")
    .replace(/\bto_jsonb\b/gi, "json")
    .replace(/\bjsonb_(\w+)\b/gi, "json_$1")
    .replace(/\bSUBSTRING\b/gi, "SUBSTR")
    // 3. Operators & Constants
    .replace(/\bTRUE\b/gi, '1')
    .replace(/\bFALSE\b/gi, '0')
    .replace(/->>/g, '->>')
    .replace(/->/g, '->')
    // 4. SQL Patterns
    .replace(/FOR\s+UPDATE/gi, '')
    .replace(/DEFAULT\s+strftime\('%Y-%m-%dT%H:%M:%SZ',\s*'now'\)/gi, "DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))")
    .replace(/DEFAULT\s+hex\(randomblob\(16\)\)/gi, "DEFAULT (hex(randomblob(16)))")
    .replace(/RAISE\s+EXCEPTION\s+'[^']*'/gi, 'SELECT 1')
    .replace(/\bADD\s+COLUMN\s+IF\s+NOT\s+EXISTS\b/gi, 'ADD COLUMN')
    // 5. References & Schemas
    .replace(/REFERENCES\s+auth\.users/gi, 'REFERENCES profiles')
    .trim();
}

// fallow-ignore-file circular-dependencies
/**
 * src/logic/db/sqliteEngine.ts
 * Unified SQL.js (SQLite WASM) Engine with IndexedDB Persistence.
 */
import { getFromIDB, setToIDB } from './idbHelper.ts'
import { TABLES_SCHEMA } from './schema.ts'
import { DATABASE_MIGRATIONS } from './migrations_data.ts'
import { logger } from '../utils/logger.ts'
import { ensureSchemaIntegrity } from './sqliteSchemaIntegrity.ts'

export interface SQLiteResult {
  columns: string[];
  values: unknown[][];
}

export interface SQLiteDatabase {
  run: (sql: string, params?: unknown[]) => void;
  exec: (sql: string, params?: unknown[]) => SQLiteResult[];
  export: () => Uint8Array;
  prepare: (sql: string) => unknown;
}

export interface LoadingStore {
  start: (id: string, title?: string, description?: string, lockSession?: boolean, icon?: string) => void;
  finish: (id: string) => void;
}

declare global {
  interface Window {
    initSqlJs: (o: unknown) => Promise<{ Database: new (data?: Uint8Array) => SQLiteDatabase }>;
  }
}

let _sqliteDb: SQLiteDatabase | null = null
let _initPromise: Promise<SQLiteDatabase | null> | null = null
let _sqliteKey = 'pokevicio_sqlite_v2'
let _isInMemory = false



export async function queryLocal(sql: string, params: unknown[] = []): Promise<Record<string, unknown>[]> {
  if (!_sqliteDb) await initSQLite()
  if (!_sqliteDb) return []
  const res = _sqliteDb.exec(sql, params)
  if (!res.length) return []
  return res[0]!.values.map((row: unknown[]) => {
    const obj: Record<string, unknown> = {}
    const result = res[0]!;
    result.columns.forEach((col: string, i: number) => {
      obj[col] = row[i];
    });
    return obj;
  })
}

export async function persistSQLite(): Promise<void> {
  if (!_sqliteDb || _isInMemory) return
  try {
    const binary = _sqliteDb.export()
    await setToIDB(_sqliteKey, binary)
    // Shadow Backup for DB
    await setToIDB(_sqliteKey + '_backup', binary)
    logger.success('SQLite', `Persistence successful (Main + Backup)`)
  } catch (e: unknown) { logger.error('SQLite', `Persistence failed: ${(e as Error).message}`) }
}

export async function initSQLite(options: { sqliteKey?: string, inMemory?: boolean } = {}): Promise<SQLiteDatabase | null> {
  if (_initPromise) return _initPromise
  _initPromise = (async () => {
    if (options.sqliteKey) _sqliteKey = options.sqliteKey
    if (options.inMemory !== undefined) _isInMemory = options.inMemory

    const SQL = await window.initSqlJs({ locateFile: (file: string) => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.12.0/${file}` })

    // Check if we are in development mode and if there is a pending import
    if (import.meta.env.DEV) {
      try {
        const checkRes = await fetch('/api/dev-import-db-check', { cache: 'no-store' })
        if (checkRes.ok) {
          const { exists } = await checkRes.json() as { exists: boolean }
          if (exists) {
            const response = await fetch('/api/dev-import-db', { cache: 'no-store' })
            if (response.ok) {
              logger.info('SQLite', 'Pending import found! Downloading dev_imported.db...')

              // Show importing overlay to the user
              try {
                if (typeof window !== 'undefined') {
                  const { useLoadingStore } = await import('@/stores/loading')
                  const loadingStore = useLoadingStore()
                  loadingStore.start('db_import', 'Importando Base de Datos...', 'Instalando copia de seguridad, por favor espera', true, '💾')
                }
              } catch (_) {
                // Safe fallback if store/pinia not ready
              }

              const arrayBuffer = await response.arrayBuffer()
              const binary = new Uint8Array(arrayBuffer)

              // Save directly to IDB (both primary and backup)
              await setToIDB(_sqliteKey, binary)
              await setToIDB(_sqliteKey + '_backup', binary)
              logger.success('SQLite', 'Dev DB successfully imported and persisted to IndexedDB!')

              // Trigger file cleanup on the dev server
              try {
                await fetch('/api/dev-import-db-cleanup', { method: 'POST' })
              } catch (e) {
                logger.warn('SQLite', 'Failed to cleanup import db file:', e)
              }

              // Set import reload flag to preserve session during reload
              try {
                sessionStorage.setItem('pokevicio_import_reload', 'true')
                sessionStorage.setItem('pokevicio_import_original_path', window.location.pathname)
              } catch (_) {
                // Ignore if sessionStorage is not available
              }

              // Small delay so user sees the message
              await new Promise(resolve => setTimeout(resolve, 1500))

              // Force page reload to initialize the game state with the new database
              window.location.reload()
              return null
            }
          }
        }
      } catch (err) {
        logger.debug('SQLite', `No pending dev import DB found: ${(err as Error).message}`)
      }
    }

    let savedBinary = await getFromIDB(_sqliteKey)

    if (!savedBinary) {
      logger.warn('SQLite', 'Primary database missing, checking Shadow Backup...')
      savedBinary = await getFromIDB(_sqliteKey + '_backup')
      if (savedBinary) {
        logger.info('SQLite', 'Restored from Shadow Backup!')
      }
    }

    if (savedBinary) {
      try {
        _sqliteDb = new SQL.Database(new Uint8Array(savedBinary)) as unknown as SQLiteDatabase
        logger.info('SQLite', 'Loaded from IndexedDB')
      } catch (dbErr) {
        logger.error('SQLite', 'Database corruption detected! Attempting Backup Rescue...')
        const backupBinary = await getFromIDB(_sqliteKey + '_backup')
        if (backupBinary) {
          _sqliteDb = new SQL.Database(new Uint8Array(backupBinary)) as unknown as SQLiteDatabase
          logger.success('SQLite', 'Rescue successful from Backup.')
        } else {
          throw dbErr
        }
      }
    } else {
      _sqliteDb = new SQL.Database() as unknown as SQLiteDatabase
      logger.info('SQLite', 'Created new in-memory database')
      TABLES_SCHEMA.forEach(schema => { if (_sqliteDb) _sqliteDb.run(`CREATE TABLE IF NOT EXISTS ${schema}`) })
      await persistSQLite()
    }

    await ensureSchemaIntegrity(_sqliteDb)
    await runMigrations()
    return _sqliteDb
  })()
  return _initPromise
}

async function runMigrations(): Promise<void> {
  if (!_sqliteDb) return
  _sqliteDb.run("PRAGMA foreign_keys = OFF") // Disable FKs during structural changes
  _sqliteDb.run("CREATE TABLE IF NOT EXISTS _migrations (id TEXT PRIMARY KEY, applied_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')))")
  const appliedRes = _sqliteDb.exec("SELECT id FROM _migrations")
  const applied = appliedRes[0]?.values.map((v: unknown[]) => v[0] as string) || []

  let loadingStore: LoadingStore | null = null
  try {
    if (typeof window !== 'undefined') {
      const { useLoadingStore } = await import('@/stores/loading')
      loadingStore = useLoadingStore()
    }
  } catch (_) {
    // Fail silently in node test context
  }

  for (const m of DATABASE_MIGRATIONS as { id: string, sql: string, sqlite_sql?: string }[]) {
    if (!applied.includes(m.id)) {
      logger.info('SQLite', `Applying migration: ${m.id}`)
      if (loadingStore) {
        loadingStore.start('db_migration', 'Actualizando Base de Datos...', `Aplicando: ${m.id}`, false, '⚙️')
      }
      try {
        const sqlSource = m.sqlite_sql !== undefined ? m.sqlite_sql : m.sql
        const isSqliteSpec = m.sqlite_sql !== undefined
        const statements = splitSQLStatements(sqlSource)
        statements.forEach(stmt => {
          const sql = isSqliteSpec ? stmt : translatePostgresToSqlite(stmt)
          if (sql) {
            try {
              if (_sqliteDb) _sqliteDb.run(sql)
            } catch (stmtErr: unknown) {
              const msg = (stmtErr as Error).message.toLowerCase()
              const isDuplicate = msg.includes('duplicate column name') || msg.includes('already exists')
              const isMissing = msg.includes('no such column')

              if (isDuplicate || isMissing) {
                logger.warn('SQLite', `Statement skipped (idempotent/safe): ${stmt}`)
              } else {
                logger.error('SQLite', `Statement failed: ${stmt} - ${msg}`)
                throw stmtErr
              }
            }
          }
        })
        _sqliteDb.run("INSERT OR IGNORE INTO _migrations (id) VALUES (?)", [m.id])
        logger.success('SQLite', `Migration applied successfully: ${m.id}`)
        await persistSQLite()
        if (loadingStore) loadingStore.finish('db_migration')
      } catch (e: unknown) { 
        if (loadingStore) loadingStore.finish('db_migration')
        logger.error('SQLite', `Migration ${m.id} failed: ${(e as Error).message}`) 
      }
    }
  }
  // Update system_config.db_version to match the latest migration
  if (DATABASE_MIGRATIONS.length > 0) {
    const latestId = DATABASE_MIGRATIONS[DATABASE_MIGRATIONS.length - 1]!.id
    const version = parseInt(latestId.split('_')[0] || '0')
    logger.info('SQLite', `Updating system_config.db_version to ${version}`)
    _sqliteDb.run("INSERT OR REPLACE INTO system_config (key, value, updated_at) VALUES ('db_version', ?, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))", [version])
  }

  _sqliteDb.run("PRAGMA foreign_keys = ON")
}

import { splitSQLStatements, translatePostgresToSqlite } from './sqlTranslator.ts'


export function resetSQLite(): void {
  _sqliteDb = null;
  _initPromise = null;
  _isInMemory = false;
  _sqliteKey = 'pokevicio_sqlite_v2';
}

interface QueryFilter {
  col: string;
  val: unknown;
  op: string;
}

export interface QueryBuilder {
  _table: string;
  _filters: QueryFilter[];
  _limit: number | null;
  _order: string | null;
  _select: string;
  select: (fields: string) => QueryBuilder;
  eq: (col: string, val: unknown) => QueryBuilder;
  neq: (col: string, val: unknown) => QueryBuilder;
  in: (col: string, vals: unknown[]) => QueryBuilder;
  order: (col: string, options?: { ascending?: boolean }) => QueryBuilder;
  limit: (n: number) => QueryBuilder;
  single: () => Promise<{ data: Record<string, unknown> | null, error: string | null }>;
  then: (resolve?: (val: Record<string, unknown>[]) => void) => Promise<Record<string, unknown>[]>;
  insert: (payload: unknown) => Promise<{ data: unknown, error: string | null }>;
  update: (payload: Record<string, unknown>) => Promise<{ data: Record<string, unknown>, error: string | null }>;
  delete: () => Promise<{ data: boolean, error: string | null }>;
  rpc: (_fn: string, _params: unknown) => Promise<{ data: boolean, error: string | null }>;
}

class SQLiteQueryBuilder implements QueryBuilder {
  _table: string;
  _filters: QueryFilter[] = [];
  _limit: number | null = null;
  _order: string | null = null;
  _select: string = '*';

  constructor(table: string) {
    this._table = table;
  }

  select(fields: string): QueryBuilder {
    this._select = fields;
    return this;
  }

  eq(col: string, val: unknown): QueryBuilder {
    this._filters.push({ col, val, op: '=' });
    return this;
  }

  neq(col: string, val: unknown): QueryBuilder {
    this._filters.push({ col, val, op: '!=' });
    return this;
  }

  in(col: string, vals: unknown[]): QueryBuilder {
    this._filters.push({ col, val: vals, op: 'IN' });
    return this;
  }

  order(col: string, { ascending = true } = {}): QueryBuilder {
    this._order = `${col} ${ascending ? 'ASC' : 'DESC'}`;
    return this;
  }

  limit(n: number): QueryBuilder {
    this._limit = n;
    return this;
  }

  async single() {
    const res = await this.then();
    return { data: res[0] || null, error: null };
  }

  async then(resolve?: (val: Record<string, unknown>[]) => void): Promise<Record<string, unknown>[]> {
    if (!_sqliteDb) return [];
    let sql = `SELECT ${this._select} FROM ${this._table}`;
    const params: unknown[] = [];
    if (this._filters.length) {
      sql += ' WHERE ' + this._filters.map((f: QueryFilter) => {
        if (f.op === 'IN') {
          const placeholders = (f.val as unknown[]).map(() => '?').join(',');
          (f.val as unknown[]).forEach((v) => params.push(v));
          return `${f.col} IN (${placeholders})`;
        }
        params.push(f.val);
        return `${f.col} ${f.op} ?`;
      }).join(' AND ');
    }
    if (this._order) sql += ` ORDER BY ${this._order}`;
    if (this._limit) sql += ` LIMIT ${this._limit}`;

    const res = _sqliteDb.exec(sql, params);
    if (!res || res.length === 0) {
      if (resolve) resolve([]);
      return [];
    }
    const result = res[0]!;
    const data = result.values.map((row: unknown[]) => {
      const obj: Record<string, unknown> = {};
      result.columns.forEach((col: string, i: number) => (obj as Record<string, unknown>)[col] = row[i]);
      return obj;
    });
    if (resolve) resolve(data);
    return data;
  }

  async insert(payload: unknown) {
    if (!_sqliteDb) return { data: payload, error: 'DB not ready' };
    const items = Array.isArray(payload) ? payload : [payload];
    for (const item of items) {
      if (typeof item !== 'object' || item === null) continue;
      const r = item as Record<string, unknown>;
      const cols = Object.keys(r);
      const vals = Object.values(r);
      const sql = `INSERT INTO ${this._table} (${cols.join(',')}) VALUES (${cols.map(() => '?').join(',')})`;
      _sqliteDb.run(sql, vals);
    }
    await persistSQLite();
    return { data: payload, error: null };
  }

  async update(payload: Record<string, unknown>) {
    if (!_sqliteDb) return { data: payload, error: 'DB not ready' };
    const cols = Object.keys(payload);
    const vals = Object.values(payload);
    let sql = `UPDATE ${this._table} SET ` + cols.map(c => `${c} = ?`).join(',');
    const params = [...vals];
    if (this._filters.length) {
      sql += ' WHERE ' + this._filters.map((f: QueryFilter) => { params.push(f.val); return `${f.col} ${f.op} ?`; }).join(' AND ');
    }
    _sqliteDb.run(sql, params);
    await persistSQLite();
    return { data: payload, error: null };
  }

  async delete() {
    if (!_sqliteDb) return { data: false, error: 'DB not ready' };
    let sql = `DELETE FROM ${this._table}`;
    const params: unknown[] = [];
    if (this._filters.length) {
      sql += ' WHERE ' + this._filters.map((f: QueryFilter) => { params.push(f.val); return `${f.col} ${f.op} ?`; }).join(' AND ');
    }
    _sqliteDb.run(sql, params);
    await persistSQLite();
    return { data: true, error: null };
  }

  async rpc(_fn: string, _params: unknown) {
    return { data: true, error: null };
  }
}

export const db: {
  run: (sql: string, params?: unknown[]) => void;
  exec: (sql: string, params?: unknown[]) => SQLiteResult[];
  prepare: (sql: string) => unknown;
  from: (table: string) => QueryBuilder;
} = {
  run: (sql: string, params: unknown[] = []) => { if (!_sqliteDb) return; _sqliteDb.run(sql, params); persistSQLite() },
  exec: (sql: string, params: unknown[] = []) => { if (!_sqliteDb) return []; return _sqliteDb.exec(sql, params) },
  prepare: (sql: string) => { if (!_sqliteDb) return null; return _sqliteDb.prepare(sql) },
  from: (table: string) => new SQLiteQueryBuilder(table)
}

import { persistSQLite, type SQLiteDatabase } from './sqliteEngine.ts';
import { TABLES_SCHEMA } from './schema.ts';
import { logger } from '../utils/logger.ts';

export async function ensureSchemaIntegrity(db: SQLiteDatabase): Promise<void> {
  logger.info('SQLite', 'Verifying schema integrity...');

  // Migración segura para la clave primaria de trade_offers (INTEGER -> TEXT/UUID)
  try {
    const info = db.exec("PRAGMA table_info(trade_offers)")
    if (info.length > 0) {
      const idCol = info[0]!.values.find((row: unknown[]) => (row[1] as string) === 'id')
      if (idCol && (idCol[2] as string).toUpperCase() === 'INTEGER') {
        logger.info('SQLite', 'Upgrading trade_offers.id from INTEGER to TEXT...');
        db.run("PRAGMA foreign_keys = OFF")
        db.run(`
          CREATE TABLE trade_offers_new (
            id TEXT PRIMARY KEY,
            sender_id TEXT,
            receiver_id TEXT,
            offer_pokemon TEXT,
            offer_items TEXT,
            offer_money INTEGER DEFAULT 0,
            request_pokemon TEXT,
            request_items TEXT,
            request_money INTEGER DEFAULT 0,
            message TEXT,
            status TEXT DEFAULT 'pending',
            created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
            updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
          )
        `)
        db.run(`
          INSERT INTO trade_offers_new (
            id, sender_id, receiver_id, offer_pokemon, offer_items, offer_money,
            request_pokemon, request_items, request_money, message, status, created_at, updated_at
          )
          SELECT 
            CAST(id AS TEXT), sender_id, receiver_id, offer_pokemon, offer_items, offer_money,
            request_pokemon, request_items, request_money, message, status, created_at, updated_at
          FROM trade_offers
        `)
        db.run("DROP TABLE trade_offers")
        db.run("ALTER TABLE trade_offers_new RENAME TO trade_offers")
        db.run("PRAGMA foreign_keys = ON")
        logger.success('SQLite', 'trade_offers table primary key successfully converted to TEXT.')
      }
    }
  } catch (e: unknown) {
    logger.error('SQLite', `Failed to migrate trade_offers PK: ${(e as Error).message}`)
  }

  for (const schemaStr of TABLES_SCHEMA) {
    try {
      const parts = schemaStr.split('(')
      if (parts.length < 2) continue
      const tableName = parts[0]!.replace('CREATE TABLE IF NOT EXISTS', '').trim()
      const info = db.exec(`PRAGMA table_info(${tableName})`)

      if (!info.length) {
        logger.warn('SQLite', `Table "${tableName}" missing from DB, creating...`)
        db.run(`CREATE TABLE IF NOT EXISTS ${schemaStr}`)
        continue
      }

      const existingCols = info[0]!.values.map((v: unknown[]) => (v[1] as string).toLowerCase())
      const colPart = schemaStr.substring(schemaStr.indexOf('(') + 1, schemaStr.lastIndexOf(')'))

      const colDefs: string[] = []
      let current = ''
      let depth = 0
      for (let i = 0; i < colPart.length; i++) {
        if (colPart[i] === '(') depth++
        else if (colPart[i] === ')') depth--

        if (colPart[i] === ',' && depth === 0) {
          colDefs.push(current.trim())
          current = ''
        } else {
          current += colPart[i]
        }
      }
      if (current.trim()) colDefs.push(current.trim())

      for (const def of colDefs) {
        const upperDef = def.toUpperCase()
        if (upperDef.startsWith('PRIMARY KEY') || upperDef.startsWith('FOREIGN KEY') || upperDef.startsWith('UNIQUE')) {
          continue
        }

        const colName = def.split(/\s+/)[0]!.toLowerCase()
        if (!existingCols.includes(colName)) {
          logger.info('SQLite', `Auto-repair: Adding missing column "${colName}" to "${tableName}"`)
          try {
            const cleanDef = def.replace(/\s+PRIMARY\s+KEY/gi, '').replace(/\s+AUTOINCREMENT/gi, '')
            db.run(`ALTER TABLE ${tableName} ADD COLUMN ${cleanDef}`)
          } catch (e: unknown) {
            logger.warn('SQLite', `Auto-repair failed for ${tableName}.${colName}: ${(e as Error).message}`)
          }
        }
      }
    } catch (e: unknown) {
      logger.error('SQLite', `Error during integrity check for: ${schemaStr} - ${(e as Error).message}`)
    }
  }

  // Post-repair: Migrate legacy chat columns if they exist in the database
  try {
    db.run("UPDATE global_chat_messages SET user_id = sender_id WHERE user_id IS NULL AND sender_id IS NOT NULL")
    db.run("UPDATE global_chat_messages SET username = sender_name WHERE username IS NULL AND sender_name IS NOT NULL")
    // Align sender IDs for mock accounts to ensure correct profile loading
    db.run("UPDATE global_chat_messages SET user_id = 'local_ash' WHERE username = 'ash'")
    db.run("UPDATE global_chat_messages SET user_id = 'local_entrenador' WHERE username = 'Entrenador' OR username = 'entrenador'")

    logger.info('SQLite', 'Legacy global chat columns migrated and aligned successfully.');
  } catch (_err: unknown) {
    // Columns or table might not exist or be loaded yet, which is safe to ignore
  }

  // Auto-repair: Populate missing profiles from game_saves to restore cosmetics and profile visibility
  try {
    const savesRes = db.exec("SELECT user_id, save_data FROM game_saves")
    if (savesRes.length > 0) {
      const rows = savesRes[0]!.values
      for (const row of rows) {
        const userId = row[0] as string
        const rawSave = row[1] as string
        if (!userId || !rawSave) continue

        let saveData: Record<string, unknown> = {}
        try {
          if (typeof rawSave === 'string') {
            saveData = JSON.parse(rawSave) as Record<string, unknown>
          }
        } catch (_) {
          continue
        }

        // Check if profile exists
        const profRes = db.exec("SELECT id FROM profiles WHERE id = ?", [userId])
        if (profRes.length === 0) {
          logger.info('SQLite', `Auto-repair: Creating missing profile for user ${userId} from save_data`)
          const fallbackName = userId.startsWith('local_') ? userId.replace('local_', '') : 'Entrenador'
          const capitalizedFallback = fallbackName.charAt(0).toUpperCase() + fallbackName.slice(1)
          const username = (saveData.trainer as string) || capitalizedFallback
          const trainerLevel = (saveData.trainerLevel as number) || 1
          const playerClass = (saveData.playerClass as string) || 'entrenador'
          const faction = (saveData.faction as string) || null
          const avatarStyle = (saveData.avatar_style as string) || ''
          const nickStyle = (saveData.nick_style as string) || ''

          const badges = (saveData.badges as number) || 0
          db.run(
            `INSERT INTO profiles (id, username, trainer_level, player_class, faction, avatar_style, nick_style, badges, db_version) 
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, 3)`,
            [userId, username, trainerLevel, playerClass, faction, avatarStyle, nickStyle, badges]
          )
        } else {
          // Force set version 3 for profiles during repair check
          db.run("UPDATE profiles SET db_version = 3 WHERE id = ?", [userId])
        }
      }
    }
    logger.info('SQLite', 'Auto-repair for missing profiles complete.')
  } catch (err: unknown) {
    logger.warn('SQLite', `Auto-repair for profiles failed: ${(err as Error).message}`)
  }

  logger.success('SQLite', 'Schema integrity check complete.')
  await persistSQLite()
}

import { makePokemon, recalcPokemonStats, getExpNeeded } from '@/logic/pokemon/pokemonFactory';
import { useGameStore } from '@/stores/game';
import { useBattleStore } from '@/stores/battle';
import { useUIStore } from '@/stores/ui';
import { useModalStore } from '@/stores/modals';
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';
import type { Pokemon } from '@/types/pokemon';
import { logger } from '../utils/logger.ts';

interface DebugPokemon extends Pokemon {
  mapId?: string | null
}

interface GenerateParams {
  id?: string
  level?: number
  ivs?: Partial<Pokemon['ivs']> | null
  isShiny?: boolean
  isGuardian?: boolean
  nature?: string | null
  ability?: string | null
  gender?: 'male' | 'female' | 'genderless' | null
  moves?: string[] | null
  nickname?: string | null
  friendship?: number
  heldItem?: string | null
  mapId?: string | null
}

interface EggData {
  uid: string
  id: string
  name: string
  isEgg: boolean
  steps: number
  ivs: Pokemon['ivs']
  nature: string
  movesAtBirth: string[]
  abilitySlot: number
  isShiny: boolean
  isGuardian: boolean
  ready: boolean
}

/**
 * Service for administrative and debug operations related to Pokémon.
 * CLI-First implementation.
 */
export const pokemonDebugService = {
  /**
   * Generates a custom pokemon object with specific overrides.
   */
  generate(params: GenerateParams = {}): Pokemon {
    const {
      id = 'pidgey',
      level = 5,
      ivs = null,
      isShiny = false,
      isGuardian = false,
      nature = null,
      ability = null,
      gender = null,
      moves = null,
      nickname = null,
      friendship = 70,
      heldItem = null,
      mapId = null
    } = params;

    // 1. Create base instance
    const genderMap: Record<string, 'M' | 'F' | 'N'> = { 'male': 'M', 'female': 'F', 'genderless': 'N' };
    const mappedGender = (gender && genderMap[gender]) ? genderMap[gender] : undefined;
    const p = makePokemon(id, level, { isShiny, nature: nature || undefined, ability: ability || undefined, gender: mappedGender, heldItem: heldItem || undefined })
    if (!p) return {} as Pokemon

    if (mapId) {
      (p as DebugPokemon).mapId = mapId
    }

    // 2. Apply Overrides
    if (ivs) {
      p.ivs = { ...p.ivs, ...ivs }
    }

    if (isGuardian) p.isGuardian = true;
    if (nickname) p.nickname = nickname;
    if (friendship !== undefined) p.friendship = friendship;

    // 3. Handle Moves
    if (moves && Array.isArray(moves)) {
      p.moves = moves.map((mName: string) => {
        const mData = pokemonDataProvider.getMoveData(mName)
        return { 
          name: mName || '???', 
          pp: mData?.pp || 35, 
          maxPP: mData?.pp || 35,
          type: mData?.type || 'normal',
          power: mData?.power || 0,
          acc: mData?.acc || 100,
          cat: (mData?.cat || 'physical') as 'physical' | 'special' | 'status'
        };
      }).slice(0, 4);
    }

    // 4. Final Recalc
    recalcPokemonStats(p);
    p.hp = p.maxHp;
    p.expNeeded = getExpNeeded(p.level);

    return p;
  },

  /**
   * Adds the pokemon to the state using a specific protocol.
   */
  async executeProtocol(p: Pokemon, protocol: string = 'catch'): Promise<void> {
    const game = useGameStore();
    const ui = useUIStore();
    const animationsEnabled = ui.debugAnimationsEnabled ?? true;

    logger.debug('DEBUG', `Executing ${protocol.toUpperCase()} protocol for ${p.name}`);

    switch (protocol) {
      case 'catch':
        // Protocol: Standard catch (wild origin)
        p.obtainedMethod = 'wild';
        game.addPokemon(p, { notify: !animationsEnabled });

        if (animationsEnabled) {
          ui.notify(`[DEBUG] Pokémon atrapado: ${p.name}`, '✨');
        }
        break;

      case 'hatch':
      case 'egg_silent': {
        // Protocol: Add UNHATCHED egg to inventory
        const eggForInventory: Partial<EggData> = {
          uid: `egg_${Temporal.Now.instant().epochMilliseconds}`,
          id: p.id,
          name: 'Huevo Pokémon',
          isEgg: true,
          steps: 1, // 1 step remaining for quick debug testing
          ivs: p.ivs,
          nature: p.nature,
          movesAtBirth: p.moves.map(m => m?.name || '???'),
          abilitySlot: (p as Pokemon & { abilityIndex?: number }).abilityIndex || 0,
          isShiny: p.isShiny,
          isGuardian: p.isGuardian
        };

        const state = game.state as Record<string, unknown>;
        const key = `${p.id}TicketSecs`;
        if (state[key] !== undefined) {
          state[key] = (Number(state[key]) || 0) + 12 * 3600;
        }

        if (!game.state.eggs) game.state.eggs = [];
        const eggToPush: EggData = {
          ...(eggForInventory as EggData),
          uid: `${eggForInventory.id}-${Temporal.Now.instant().epochMilliseconds}`,
          ready: false
        };
        game.state.eggs.push(eggToPush);
        ui.notify(`[DEBUG] Huevo de ${p.name} añadido a la mochila`, '🥚');
        await game.save(false);
        break;
      }

      case 'egg_warehouse': {
        // Protocol: Add DaycareEgg directly to Daycare Warehouse (almacén)
        const { useBreedingStore } = await import('@/stores/breeding');
        const breedingStore = useBreedingStore();

        const { eggFactory } = await import('@/logic/breeding/eggFactory');
        const egg = eggFactory.createDaycareEgg({
          species: p.id,
          ivs: p.ivs,
          nature: p.nature,
          movesAtBirth: p.moves.map(m => m?.name || '???'),
          abilityIndex: (p as Pokemon & { abilityIndex?: number }).abilityIndex || 0,
          isShiny: !!p.isShiny,
          cost: 0
        });

        breedingStore.warehouseEggs.push(egg);
        if (breedingStore.saveWarehouseEggs) {
          breedingStore.saveWarehouseEggs();
        }

        ui.notify(`[DEBUG] Huevo de ${p.name} añadido al almacén de la guardería`, '🥚');
        break;
      }

      case 'hatch_anim':
      case 'egg_anim':
        // Protocol: Visual hatching sequence (VUE MIGRATED)
        p.obtainedMethod = 'egg';

        // Add to game state silently first
        game.addPokemon(p, { notify: false });

        // Trigger Vue Modal Sequence
        ui.open('HatchAnimation', { pokemon: p });
        break;

      case 'fishing_minigame': {
        const { showFishingIntro, startFishingMinigame } = await import('@/logic/encounters/encounterUI')
        const battleStore = useBattleStore();
        showFishingIntro(p, 50, () => {
          startFishingMinigame(
            p,
            50,
            async () => {
              ui.notify(`¡Pesca exitosa! Iniciando combate...`, '🎣')
              await battleStore._startBattle(p, { 
                locationId: (p as DebugPokemon).mapId || 'route12',
                isDebug: true,
                isFishing: true
              })
              const modalStore = useModalStore()
              modalStore.closeAll()
            },
            () => {
              ui.notify('El Pokémon escapó...', '💨')
            }
          )
        })
        break;
      }

      case 'archaeology_minigame': {
        const { showArchaeologyIntro, startArchaeologyMinigame } = await import('@/logic/encounters/encounterUI')
        const battleStore = useBattleStore();
        showArchaeologyIntro(p, 50, () => {
          startArchaeologyMinigame(
            p,
            50,
            async () => {
              ui.notify(`¡Excavación exitosa! Iniciando combate...`, '⛏️')
              await battleStore._startBattle(p, { 
                locationId: (p as DebugPokemon).mapId || 'mt_moon',
                isDebug: true,
                isArchaeology: true
              })
              const modalStore = useModalStore()
              modalStore.closeAll()
            },
            () => {
              ui.notify('El fósil se desmoronó...', '💨')
            }
          )
        })
        break;
      }

      default:
        logger.error('DEBUG', `Unknown protocol: ${protocol}`);
    }
  },

  /**
   * Starts a custom encounter.
   */
  async triggerEncounter(p: Pokemon, mapId: string = 'plains'): Promise<void> {
    const battleStore = useBattleStore();
    // const _ui = useUIStore();

    // 1. Force flee if there's an active battle
    if (battleStore.isBattleActive) {
      logger.warn('DEBUG', 'Combate activo detectado. Forzando huida del anterior para iniciar el nuevo...');
      await battleStore.endBattle(false, true);
    }

    logger.debug('DEBUG', `Triggering encounter with ${p.name} at ${mapId}`);

    // Register as seen
    const game = useGameStore();
    game.registerPokedex(p.id, false);

    // Start battle
    await battleStore._startBattle(p, { 
      locationId: mapId,
      isDebug: true
    });

    const modalStore = useModalStore();
    modalStore.closeAll();
  }
};

import { GAME_RATIOS } from '@/data/constants';
import { makePokemon } from '@/logic/pokemon/pokemonFactory';
import { isDisputePhase } from '@/logic/war/warEngine';
import { getGuardianData, GUARDIAN_CHANCE } from '@/logic/war/guardianEngine';
import type { Pokemon } from '@/types/pokemon';
import type { MapLocation, Encounter, EncounterOptions, EncounterState } from '@/types/encounters';
import type { Event as GameEvent, EventConfig } from '@/logic/events/eventEngine';

/**
 * Gets the valid pool of Pokémon for a location and time cycle.
 * Incorporates active events.
 */
export function getEncounterPool(loc: MapLocation, cycle: string, weather: string = 'clear', activeEvents: GameEvent[]) {
  if (!loc || !loc.wild) return { pool: [] as string[], rates: [] as number[] };

  const pool = [...(loc.wild[cycle] || loc.wild.day || [])];
  const rates = [...((loc.rates && (loc.rates[cycle] || loc.rates.day)) ? (loc.rates[cycle] || loc.rates.day) : []) as number[]];

  // Ensure rates match pool length before transformations
  while (rates.length < pool.length) rates.push(10);

  // 1. Inyección por Clima (Visitantes y Exclusivos)
  const wConfig = loc.weather?.[weather];
  if (weather && weather !== 'clear' && wConfig) {
    // Especies Exclusivas (Pesos dinámicos o base 5)
    if (wConfig.exclusive) {
      const exclusives = Array.isArray(wConfig.exclusive) ? wConfig.exclusive : Object.keys(wConfig.exclusive);
      exclusives.forEach(id => {
        if (!pool.includes(id)) {
          pool.push(id);
          const weight = Array.isArray(wConfig.exclusive) ? 5 : ((wConfig.exclusive as Record<string, number>)[id] || 5);
          rates.push(weight || 5); 
        }
      });
    }

    // Visitantes (Marcados con peso negativo para normalización proporcional)
    if (wConfig.visitors) {
      const visitors = Array.isArray(wConfig.visitors) ? wConfig.visitors : Object.keys(wConfig.visitors);
      visitors.forEach(id => {
        if (!pool.includes(id)) {
          pool.push(id);
          const weight = Array.isArray(wConfig.visitors) ? -10 : -((wConfig.visitors as Record<string, number>)[id] || 10);
          rates.push(weight || -10); 
        }
      });
    }
  }

  // 2. Apply Event Injections
  activeEvents.forEach(ev => {
    const cfg = (typeof ev.config === 'string' ? JSON.parse(ev.config) : ev.config) as EventConfig | undefined;
    if (ev.active && cfg?.ignoreTimeRestrictions && cfg.species) {
      const eventSpecies = cfg.species.split(',').map((s: string) => s.trim().toLowerCase());
      eventSpecies.forEach((spId: string) => {
        if (!pool.includes(spId)) {
          // Check if species exists in other cycles for this map
          const wild = loc.wild || {};
          for (const c in wild) {
            const cyclePool = wild[c];
            if (!cyclePool) continue;
            const idx = cyclePool.indexOf(spId);
            if (idx !== -1) {
              pool.push(spId);
              const originalRates = loc.rates?.[c] || [];
              rates.push(originalRates[idx] || 10);
              break;
            }
          }
        }
      });
    }
  });

  return { pool, rates };
}

/**
 * Selects a random Pokémon ID from a pool using weights.
 */
export function selectFromPool(pool: string[], rates: number[]): string {
  if (!pool.length) return '';
  const totalRate = rates.reduce((a, b) => a + b, 0);
  const rand = Math.random() * totalRate;
  let cumulative = 0;

  for (let i = 0; i < pool.length; i++) {
    cumulative += rates[i] || 0;
    if (rand <= cumulative) return pool[i] || '';
  }
  return pool[0] || '';
}

/**
 * Checks for special, non-wild override encounters (debug overrides, rival, defender battles, guardians).
 */
export function checkSpecialEncounters(
  locId: string,
  state: EncounterState,
  options: EncounterOptions,
  allMapIds: string[]
): Encounter | null {
  // 0. Debug: 50% trainer override
  const win = (typeof window !== 'undefined' ? window : null) as unknown as Record<string, unknown>;
  const debug = win?.__VITE_DEBUG__ as Record<string, unknown> | undefined;
  if (!options.forceEncounter && debug?.trainerChance50) {
    if (Math.random() < 0.50) {
      return { type: 'trainer' };
    }
  }

  // 0. Especial: Rival Azul
  if (!options.forceEncounter) {
    let rivalChance = GAME_RATIOS.encounters.rival;
    const eventRivalBonus = options.eventRivalBonus || 1;
    rivalChance *= eventRivalBonus;

    if (state.playerClass === 'entrenador' && (state.classLevel || 1) >= 20) {
      const gymIds = ['pewter', 'cerulean', 'vermilion', 'celadon', 'fuchsia', 'saffron', 'cinnabar', 'viridian'];
      const allGymsHard = gymIds.every(id => state.gymProgress?.[id]?.hard === true);
      if (allGymsHard) {
        rivalChance *= 2;
      }
    }

    if (Math.random() < rivalChance) {
      return { type: 'rival' };
    }
  }

  // 1. Especial: Fase de Dominancia (Finde) - Batallas de Defensores
  if (!isDisputePhase() && !options.forceEncounter) {
    if (Math.random() < 0.20 && state.faction) {
      const dominance = (options.dominanceData || {})[locId];
      const winner = dominance?.winner || null;
      if (winner && winner !== state.faction) {
        return { type: 'defender', faction: winner };
      }
    }
  }

  // 2. Especial: Guardianes (Pokémon Alfa)
  const guardian = getGuardianData(locId, allMapIds);
  if (guardian && !options.forceEncounter) {
    const capturedToday = (state.dailyGuardianCaptures || []).includes(locId);
    if (!capturedToday && Math.random() < GUARDIAN_CHANCE) {
      return { 
        type: 'guardian', 
        pokemon: makePokemon(guardian.id, guardian.lv, { shinyMultiplier: options.shinyMultiplier }) as Pokemon,
        pts: guardian.pts
      };
    }
  }

  return null;
}

/**
 * Handles repel filters and normalizes repellent encounter rules.
 */
export function handleRepellentEncounter(
  loc: MapLocation,
  cycle: string,
  state: EncounterState,
  options: EncounterOptions,
  activeEvents: GameEvent[]
): Encounter | null {
  if (Math.random() < GAME_RATIOS.encounters.trainerRepel) {
    return { type: 'trainer' };
  }

  const weather = options.weather || 'clear';
  const { pool, rates: rawRates } = getEncounterPool(loc, cycle, weather, activeEvents);
  const rates = rawRates.map(r => r === -1 ? 5 : r); 

  const firstPokemon = state.team?.[0];

  for (let attempt = 0; attempt < 10; attempt++) {
    const selectedId = selectFromPool(pool, rates);
    const minLv = loc.lv[0] || 2;
    const maxLv = loc.lv[1] || 5;
    const level = Math.floor(Math.random() * (maxLv - minLv + 1)) + minLv;

    if (!firstPokemon || level >= firstPokemon.level) {
      return { 
        type: 'wild', 
        pokemon: makePokemon(selectedId, level, { shinyMultiplier: options.shinyMultiplier }) as Pokemon 
      };
    }
  }
  return { type: 'trainer' };
}

/**
 * Handles archaeology node drops and details.
 */
export function generateArchaeologyEncounter(
  loc: MapLocation,
  options: EncounterOptions
): Encounter | null {
  if (!loc.archaeology) return null;
  const archPool = loc.archaeology.pool;
  const archRates = loc.archaeology.rates;
  const selectedId = selectFromPool(archPool, archRates);
  const minLv = loc.archaeology.lv[0] || 15;
  const maxLv = loc.archaeology.lv[1] || 25;
  const level = Math.floor(Math.random() * (maxLv - minLv + 1)) + minLv;
  const totalRate = archRates.reduce((a: number, b: number) => a + b, 0);
  const rateIdx = archPool.indexOf(selectedId);
  const rateVal = archRates[rateIdx];
  const rarity = ((rateVal !== undefined ? rateVal : 0) / (totalRate || 1)) * 100;

  return {
    type: 'archaeology',
    pokemon: makePokemon(selectedId, level, { shinyMultiplier: options.shinyMultiplier }) as Pokemon,
    rarity
  };
}

/**
 * Calculates weights for ground, fishing, and archaeology encounter methods.
 */
export function calculateEncounterTypeWeights(
  loc: MapLocation,
  weather: string,
  state: EncounterState,
  options: EncounterOptions
): { groundWeight: number; fishingWeight: number; archWeight: number; totalWeight: number } {
  const isRainy = ['rain', 'heavy_rain', 'storm', 'thunderstorm'].includes(weather.toLowerCase());
  const climateFishingMultiplier = isRainy ? 1.20 : 1.0;
  const fishingBonus = (options.eventFishingBonus || 1) * climateFishingMultiplier;

  const groundWeight = 100;

  let fishingWeight = 0;
  if (loc.fishing) {
    fishingWeight = GAME_RATIOS.encounters.fishing * 100 * fishingBonus;
    if ((state.fishingRodSecs || 0) > 0) {
      fishingWeight += 600;
    }
  }

  let archWeight = 0;
  if (loc.archaeology) {
    const isCave = !!loc.isCave;
    const isMountain = !!loc.isMountain;
    archWeight = isCave ? 10 : (isMountain ? 5 : 0);
    if ((state.pickaxeSecs || 0) > 0 || (state.brushSecs || 0) > 0) {
      archWeight += 600;
    }
  }

  return {
    groundWeight,
    fishingWeight,
    archWeight,
    totalWeight: groundWeight + fishingWeight + archWeight
  };
}

