/**
 * Gets effect for TMs and other dynamic items not in the main list
 */
export const getDynamicItemEffect = (itemName: string, p: Pokemon): ItemEffectResult | null => {
  const tmMatch = itemName.match(/([Tt][Mm]|[Mm][Tt])(\d+)/);
  if (tmMatch) {
    const tmId = `TM${tmMatch[2]}`;
    const species = p.id;
    const compatList = (TM_COMPAT as Record<string, string[]>)[species] || [];
    if (!compatList.includes(tmId)) {
      return { success: false, message: 'Incompatible.' };
    }
    const tmData = (GAME_TMS as TMData[]).find(t => t.id === tmId);
    if (!tmData) return { success: false, message: 'MT inválida.' };

    // Check if pokemon already knows the move
    if (p.moves.some(m => m && m.name === tmData.name)) {
      return { success: false, message: 'Ya conoce este movimiento.' };
    }

    return { 
      success: true, 
      message: `aprenderá ${tmData.name}`, 
      deferred: true, 
      resultType: 'learn_move', 
      moveName: tmData.name 
    };
  }
  return null;
}

// Helper Functions
function healHp(p: Pokemon, amount: number): ItemEffectResult {
  const currentHp = Number(p.hp || 0);
  const maxHp = Number(p.maxHp || 0);
  const healAmount = Number(amount || 0);

  if (currentHp >= maxHp) return { success: false, message: 'HP ya está al máximo.' };
  if (currentHp <= 0) return { success: false, message: 'El Pokémon está debilitado.' };

  const prev = currentHp;
  p.hp = Math.min(maxHp, currentHp + healAmount);
  return { success: true, message: `restauró ${p.hp - prev} HP` };
}

function revive(p: Pokemon, amount: number): ItemEffectResult {
  if (p.hp > 0) return { success: false, message: 'El Pokémon no está debilitado.' };
  p.hp = amount;
  return { success: true, message: `revivió con ${p.hp} HP` };
}

function clearStatus(p: Pokemon, type: string): ItemEffectResult {
  if (p.hp <= 0) return { success: false, message: 'El Pokémon está debilitado.' };
  if (p.status !== type && type !== 'any') return { success: false, message: 'No tiene ese estado.' };
  if (!p.status) return { success: false, message: 'No tiene problemas de estado.' };
  const old = p.status;
  p.status = null;
  if (old === 'sleep') p.sleepTurns = 0;
  return { success: true, message: `se curó del estado ${old}` };
}

function curaTotal(p: Pokemon): ItemEffectResult {
  if (p.hp <= 0) return { success: false, message: 'El Pokémon está debilitado.' };
  if (!p.status && Number(p.hp) === Number(p.maxHp)) return { success: false, message: 'No tiene efecto.' };
  p.hp = Number(p.maxHp);
  p.status = null;
  p.sleepTurns = 0;
  return { success: true, message: 'se curó completamente' };
}

function restorePP(p: Pokemon, amount: number): ItemEffectResult {
  let changed = false;
  p.moves.forEach(m => {
    if (!m) return;
    const max = m.maxPP || 35; // Fallback
    if (m.pp < max) {
      m.pp = Math.min(max, (m.pp || 0) + amount);
      changed = true;
    }
  });
  return changed 
    ? { success: true, message: 'recuperó PP' }
    : { success: false, message: 'Los PP ya están al máximo.' };
}

function handleStone(p: Pokemon, stoneName: string): ItemEffectResult {
  const nextId = checkStoneEvolution(p, stoneName);
  if (!nextId) return { success: false, message: 'No tiene efecto sobre este Pokémon.' };
  return { 
    success: true, 
    message: '¡Está evolucionando!', 
    resultType: 'evolution', 
    targetId: nextId 
  };
}

/**
 * src/logic/player/classEngine.ts
 * Core engine for calculating class modifiers and mission validation.
 */
import { PLAYER_CLASSES } from '@/data/playerClasses';

export interface ModifierContext {
  isPvP?: boolean;
  isTrainer?: boolean;
  isGym?: boolean;
}

/**
 * Returns the processed modifier for a specific type and context.
 */
export function getClassModifier(playerClass: string, type: string, context: ModifierContext = {}): number {
  // PvP Balance: No advantages allowed during PvP
  if (context.isPvP) {
    if (type === 'shopDiscount') return 0;
    return 1.0;
  }

  const cls = (PLAYER_CLASSES as Record<string, { modifiers: Record<string, number> }>)[playerClass];
  if (!cls) return type === 'shopDiscount' ? 0 : 1.0;

  const m = cls.modifiers;

  switch (type) {
    case 'expMult':
      if (playerClass === 'cazabichos' && context.isTrainer) return m.expMultTrainer || 1.0;
      return m.expMult || 1.0;
    case 'bcMult':
      if (playerClass === 'entrenador' && context.isGym) return m.bcGymMult || 1.0;
      return m.bcMult || 1.0;
    case 'healCostMult':
      return m.healCostMult || 1.0;
    case 'daycareCostMult':
      return m.daycareCostMult || 1.0;
    case 'catchMult':
      return m.catchMult || 1.0;
    case 'shopDiscount':
      return m.shopDiscount || 0;
    default:
      return 1.0;
  }
}

/**
 * Calculates the rewards and costs for a passive mission.
 */
export function getMissionCostInfo(missionId: string, playerClass: string): Record<string, unknown> | null {
  const cls = (PLAYER_CLASSES as Record<string, { id: string }>)[playerClass];
  if (!cls) return null;

  if (playerClass === 'cazabichos') {
    const data: Record<string, Record<string, unknown>> = {
      mission_6h: { cost: 5000, ivFloor: 5, shinyDiv: 2 },
      mission_12h: { cost: 10000, ivFloor: 10, shinyDiv: 4 },
      mission_24h: { cost: 20000, ivFloor: 15, shinyDiv: 8 }
    };
    return { type: 'money', ...data[missionId] };
  }

  if (playerClass === 'rocket') {
    const data: Record<string, Record<string, unknown>> = {
      mission_6h: { pokReq: 1, mult: 1.0 },
      mission_12h: { pokReq: 2, mult: 1.3 },
      mission_24h: { pokReq: 3, mult: 1.8 }
    };
    return { type: 'pokemon_sacrifice', ...data[missionId] };
  }

  if (playerClass === 'entrenador') {
    const data: Record<string, Record<string, unknown>> = {
      mission_6h: { cost: 5000, blocks: 1, bonusLevel: false },
      mission_12h: { cost: 10000, blocks: 2, bonusLevel: false },
      mission_24h: { cost: 20000, blocks: 4, bonusLevel: true }
    };
    return { type: 'money_pokemon', ...data[missionId] };
  }

  if (playerClass === 'criador') {
    const data: Record<string, Record<string, unknown>> = {
      mission_6h: { cost: 300, blocks: 1, vigorSaveChance: 0 },
      mission_12h: { cost: 600, blocks: 2, vigorSaveChance: 0 },
      mission_24h: { cost: 1000, blocks: 4, vigorSaveChance: 0.10 }
    };
    return { type: 'bc_pokemon', ...data[missionId] };
  }

  return null;
}

/**
 * classMath.ts
 * Módulo con funciones y fórmulas puras para las mecánicas de las clases de jugador
 * sin efectos colaterales de base de datos o almacenamiento de estado.
 */

/**
 * Team Rocket:
 * Calcula la probabilidad de éxito de "Robo Rápido" al inicio del combate basado en el nivel de clase.
 * Nivel 1: 5%, Nivel 2: 10%, Nivel 3: 15% (Límite cap).
 */
export function calculateQuickStealChance(classLevel: number): number {
  const level = Math.max(1, classLevel);
  const chance = 0.15 + (level - 1) * 0.01;
  return parseFloat(Math.min(0.30, chance).toFixed(2));
}

/**
 * Cazabichos:
 * Retorna el multiplicador de Catch Rate de "Sinergia Bicho" según el número de Pokémon tipo Bicho en el equipo.
 * Por cada Pokémon de tipo 'bug' o 'bicho' en el equipo activo, incrementa la tasa de captura un 5% (acumulativo lineal, max +30%).
 */
export function calculateBugSymmetryBonus(activeTeam: { type1: string; type2?: string | null }[]): number {
  const bugCount = activeTeam.filter(p => {
    const t1 = String(p.type1 || '').toLowerCase();
    const t2 = String(p.type2 || '').toLowerCase();
    return t1 === 'bug' || t1 === 'bicho' || t2 === 'bug' || t2 === 'bicho';
  }).length;
  // Aumenta linealmente 5% por cada bicho en el equipo, máximo 30% (+0.30)
  return 1.0 + Math.min(6, bugCount) * 0.05;
}

/**
 * Entrenador:
 * Aplica una penalización del 10% a la tasa de captura base si el Pokémon salvaje tiene IVs excepcionales (IV Total > 120).
 */
export function calculateTrainerCatchRateModifier(baseCatchRate: number, ivTotal: number): number {
  if (ivTotal > 120) {
    return Math.max(1, Math.floor(baseCatchRate * 0.9));
  }
  return baseCatchRate;
}

/**
 * Entrenador:
 * Retorna true si el jugador tiene la posibilidad de doble combate de rival debido a vencer todos los gimnasios en Difícil.
 */
export function hasDoubleRivalChance(
  defeatedGyms: string[],
  gymProgress: Record<string, { easy?: boolean; normal?: boolean; hard?: boolean } | undefined>
): boolean {
  if (!defeatedGyms || defeatedGyms.length === 0) return false;
  // Debe haber vencido todos los gimnasios derrotados en dificultad "hard"
  return defeatedGyms.every(gymId => {
    const progress = gymProgress[gymId];
    return !!(progress && progress.hard);
  });
}

/**
 * Retorna la experiencia necesaria para subir al siguiente nivel de clase.
 */
export function getXPNeededForClassLevel(level: number): number {
  if (level >= 30) return 99999999;
  const ranks = [
    100, 250, 500, 900, 1400, 2100, 3000, 4200, 6000, 8500,
    11500, 15000, 19000, 23500, 28500, 34000, 40000, 46500, 53500, 61000,
    69000, 77500, 86500, 96000, 106000, 116500, 127500, 139000, 151500
  ];
  return ranks[level - 1] || (level * 1000);
}

/**
 * Team Rocket ENEMIGO:
 * Retorna el límite máximo de dinero/valor de recursos que puede robar un NPC basándose en su nivel medio.
 * Escalado: V_max(L) = 8 * L^2
 */
export function calculateMaxNpcRobberyLimit(avgLevel: number): number {
  const level = Math.max(1, avgLevel);
  return 8 * Math.pow(level, 2);
}

