 */
export function getTypeEffectivenessMsg(eff: number): string | null {
  if (eff === 0) return '¡No afecta!';
  if (eff >= 2) return '¡Es muy eficaz!';
  if (eff <= 0.5) return 'No es muy eficaz...';
  return null;
}

