import { sleep } from '@/logic/utils/timeUtils'

import { calculateDamage } from '@/logic/battle/battleEngine'
import { getStatMultiplier, getAccuracyMultiplier } from '@/logic/pokemon/statEngine'
import { applyMoveEffect } from '@/logic/battle/battleMoves'
import { MOVE_DATA } from '@/data/moves'
import type { Pokemon } from '@/types/pokemon'
import type { BattleStages } from '@/types/battle'
import type { MoveBaseData } from '@/types/database'

/**
 * Resolves a turn in a Live PvP battle. (Host only)
 */

export interface PvPAction {
  type: 'move' | 'switch';
  moveIndex?: number;
  switchIndex?: number;
}

export interface PvPActionResult {
  type: 'move' | 'switch';
  moveName?: string;
  actorIsHost: boolean;
  damage?: number;
  eff?: number;
  newHp?: number;
  newIdx?: number;
  missed?: boolean;
  statusBlocked?: string;
  effectLog: string[];
}

export interface PvPChannel {
  send: (payload: { type: 'presence' | 'postgres_changes' | 'broadcast', event: string, payload: unknown }) => void;
  unsubscribe: () => void;
}

export interface PvPBattleState {
  isHost: boolean;
  isRanked: boolean;
  phase: 'sync' | 'choosing' | 'resolving' | 'animating' | 'faint_switch' | 'over' | 'waiting';
  myTeam: Pokemon[];
  enemyTeam: Pokemon[];
  myActiveIdx: number;
  enemyActiveIdx: number;
  myHp: number[];
  enemyHp: number[];
  myStages: BattleStages;
  enemyStages: BattleStages;
  myPick: PvPAction | null;
  enemyPick: PvPAction | null;
  logs: string[];
  ch: PvPChannel | null;
  isPvP?: boolean;
}

export interface PvPTurnResult {
  firstIsHost: boolean;
  first: PvPActionResult;
  second: PvPActionResult | null;
  hostActiveIdx: number;
  clientActiveIdx: number;
  hostHp: number[];
  clientHp: number[];
  hostStages: BattleStages;
  clientStages: BattleStages;
}

/**
 * Resolves a turn in a Live PvP battle. (Host only)
 */
export function resolvePvPTurn(battleState: PvPBattleState): PvPTurnResult | undefined {
  if (!battleState.isHost || battleState.phase === 'resolving') return
  battleState.phase = 'resolving'

  const hostPoke = battleState.myTeam[battleState.myActiveIdx]
  const clientPoke = battleState.enemyTeam[battleState.enemyActiveIdx]

  if (!hostPoke || !clientPoke) return

  const hostPick = battleState.myPick
  const clientPick = battleState.enemyPick

  if (!hostPick || !clientPick) return

  // 1. Determine priority and order
  let firstIsHost = true
  if (hostPick.type === 'switch' && clientPick.type !== 'switch') {
    firstIsHost = true
  } else if (clientPick.type === 'switch' && hostPick.type !== 'switch') {
    firstIsHost = false
  } else if (hostPick.type === 'move' && clientPick.type === 'move') {
    const hIdx = hostPick.moveIndex ?? 0
    const cIdx = clientPick.moveIndex ?? 0
    const hMove = hostPoke.moves[hIdx]
    const cMove = clientPoke.moves[cIdx]
    const hPrio = (MOVE_DATA as Record<string, MoveBaseData>)[hMove?.name || '']?.priority || 0
    const cPrio = (MOVE_DATA as Record<string, MoveBaseData>)[cMove?.name || '']?.priority || 0

    if (hPrio !== cPrio) {
      firstIsHost = hPrio > cPrio
    } else {
      const hSpe = Math.floor(hostPoke.spe * getStatMultiplier(battleState.myStages.spe))
      const cSpe = Math.floor(clientPoke.spe * getStatMultiplier(battleState.enemyStages.spe))
      firstIsHost = hSpe > cSpe || (hSpe === cSpe && Math.random() < 0.5)
    }
  }

  // 2. Helper to calculate a single action
  const calcAction = (actorIsHost: boolean): PvPActionResult => {
    const effectLog: string[] = []
    const attacker = actorIsHost ? hostPoke : clientPoke
    const defender = actorIsHost ? clientPoke : hostPoke
    const atkS = actorIsHost ? battleState.myStages : battleState.enemyStages
    const defS = actorIsHost ? battleState.enemyStages : battleState.myStages
    const pick = actorIsHost ? hostPick : clientPick

    if (pick.type === 'switch') {
      return { type: 'switch', newIdx: pick.switchIndex, actorIsHost, effectLog }
    }

    const moveIdx = pick.moveIndex ?? 0
    const move = attacker.moves[moveIdx]
    const moveName = move?.name || '???'
    const md = ((MOVE_DATA as unknown) as Record<string, MoveBaseData>)[moveName] || { 
      power: 40, 
      type: 'normal', 
      cat: 'physical' as const, 
      acc: 100, 
      priority: 0, 
      effect: 'none' 
    } as MoveBaseData

    if (attacker.status === 'sleep') {
      const sleepTurns = (attacker as unknown as { sleepTurns?: number }).sleepTurns ?? 0
      if (sleepTurns > 0) {
        (attacker as unknown as { sleepTurns: number }).sleepTurns = sleepTurns - 1
        return { type: 'move', moveName, actorIsHost, statusBlocked: 'sleep', effectLog }
      }
      attacker.status = null
      effectLog.push(`¡${attacker.name} se despertó!`)
    }

    if (attacker.status === 'paralysis' && Math.random() < 0.25) {
      return { type: 'move', moveName, actorIsHost, statusBlocked: 'paralysis', effectLog }
    }

    if (md.acc && Math.random() * 100 > md.acc * getAccuracyMultiplier(atkS.acc || 0)) {
      return { type: 'move', moveName, actorIsHost, missed: true, effectLog }
    }

    if (md.cat === 'status') {
      applyMoveEffect(md.effect, attacker, defender, atkS, defS, (m: string) => effectLog.push(m))
      return { type: 'move', moveName, actorIsHost, effectLog }
    }

    const { dmg, eff } = calculateDamage(attacker, defender, md, { 
      atkStages: (atkS as unknown as Record<string, number>)[md.cat === 'physical' ? 'atk' : 'spa'], 
      defStages: (defS as unknown as Record<string, number>)[md.cat === 'physical' ? 'def' : 'spd'] 
    })
    const targetHpArr = actorIsHost ? battleState.enemyHp : battleState.myHp
    const targetIdx = actorIsHost ? battleState.enemyActiveIdx : battleState.myActiveIdx
    const newHp = Math.max(0, (targetHpArr[targetIdx] ?? 0) - dmg)

    if (md.effect && md.effect !== 'none' && dmg > 0) {
      applyMoveEffect(md.effect, attacker, defender, atkS, defS, (m: string) => effectLog.push(m))
    }

    return { type: 'move', moveName, actorIsHost, damage: dmg, eff, newHp, effectLog }
  }

  // 3. Execute actions
  const firstAction = calcAction(firstIsHost)
  if (firstAction.newHp !== undefined) {
    if (firstIsHost) {
      if (battleState.enemyHp) battleState.enemyHp[battleState.enemyActiveIdx] = firstAction.newHp
    } else {
      if (battleState.myHp) battleState.myHp[battleState.myActiveIdx] = firstAction.newHp
    }
  }

  let secondAction: PvPActionResult | null = null
  const defenderHp = firstIsHost ? (battleState.enemyHp[battleState.enemyActiveIdx] ?? 0) : (battleState.myHp[battleState.myActiveIdx] ?? 0)
  if (defenderHp > 0 && firstAction.type !== 'switch') {
    secondAction = calcAction(!firstIsHost)
  }

  const result: PvPTurnResult = {
    firstIsHost, first: firstAction, second: secondAction,
    hostActiveIdx: battleState.myActiveIdx, clientActiveIdx: battleState.enemyActiveIdx,
    hostHp: battleState.myHp, clientHp: battleState.enemyHp,
    hostStages: battleState.myStages, clientStages: battleState.enemyStages
  }

  if (battleState.ch && typeof battleState.ch.send === 'function') {
    battleState.ch.send({ type: 'broadcast', event: 'pvp_turn_result', payload: result })
  }
  return result
}

export async function applyPvPTurnResult(battleState: PvPBattleState, result: PvPTurnResult, endBattleCallback: (won: boolean, msg: string) => void): Promise<void> {
  battleState.phase = 'animating'
  const isHost = battleState.isHost
  const actions = [result.first, result.second].filter((a): a is PvPActionResult => a !== null)

  for (const action of actions) {
    if ((battleState.phase as string) === 'over') break
    const isMyAction = isHost ? action.actorIsHost : !action.actorIsHost

    if (action.type === 'switch') {
      const team = isMyAction ? battleState.myTeam : battleState.enemyTeam
      const targetPoke = team[action.newIdx ?? 0]
      if (targetPoke) {
        battleState.logs.push(`¡${isMyAction ? 'Vas a cambiar a' : 'El rival cambió a'} ${targetPoke.name}!`)
      }
      await sleep(600)
      if (isMyAction) battleState.myActiveIdx = action.newIdx ?? 0
      else battleState.enemyActiveIdx = action.newIdx ?? 0
    } else {
      const team = action.actorIsHost ? (isHost ? battleState.myTeam : battleState.enemyTeam) : (isHost ? battleState.enemyTeam : battleState.myTeam)
      const actorIdx = action.actorIsHost ? (isHost ? battleState.myActiveIdx : battleState.enemyActiveIdx) : (isHost ? battleState.enemyActiveIdx : battleState.myActiveIdx)
      const actorPoke = team[actorIdx]

      battleState.logs.push(`¡${isMyAction ? 'Tu' : 'El'} ${actorPoke?.name || 'Pokémon'} usó ${action.moveName}!`)
      if (action.statusBlocked) battleState.logs.push(`¡No pudo moverse por ${action.statusBlocked}!`)
      else if (action.missed) battleState.logs.push('¡Falló!')
      else if (action.damage !== undefined && action.damage > 0) {
        battleState.logs.push(`(-${action.damage} HP)${action.eff !== undefined && action.eff >= 2 ? ' ¡Muy eficaz!' : action.eff !== undefined && action.eff <= 0.5 ? ' No muy eficaz...' : ''}`)
        if (isMyAction) battleState.enemyHp[battleState.enemyActiveIdx] = action.newHp ?? 0
        else battleState.myHp[battleState.myActiveIdx] = action.newHp ?? 0
      }
      action.effectLog?.forEach((m: string) => battleState.logs.push(m))
    }
    await sleep(800)
  }

  // Post-turn checks
  const myHp = battleState.myHp[battleState.myActiveIdx] ?? 0
  const enHp = battleState.enemyHp[battleState.enemyActiveIdx] ?? 0

  if (myHp <= 0) {
    if (!battleState.myHp.some((h: number) => h > 0)) endBattleCallback(false, '¡Has sido derrotado!')
    else battleState.phase = 'faint_switch'
  } else if (enHp <= 0) {
    if (!battleState.enemyHp.some((h: number) => h > 0)) endBattleCallback(true, '¡Has ganado la batalla!')
    else battleState.phase = 'waiting'
  } else {
    battleState.phase = 'choosing'
    battleState.myPick = null
    battleState.enemyPick = null
  }
}

import { POKEMON_SPRITE_IDS } from '@/logic/constants/pokedexConstants';
export { POKEMON_SPRITE_IDS };
import { resolveAsset } from '../utils/assetResolver.ts';
import { MAPS_WITH_CYCLES } from '@/data/map-assets';
import { getItemById } from '@/data/items';

/**
 * POKEAPI_BASE: Now local paths for downloaded sprites.
 */
const POKEAPI_BASE = '/assets/sprites/pokemon/static/';



/**
 * ASSET_TYPES: Supported categories for the Asset Service.
 */
export const ASSET_TYPES = {
  POKEMON: 'pokemon',
  MAP: 'map',
  TRAINER: 'trainer',
  ITEM: 'item',
  BANNER: 'banner',
  BATTLE_BG: 'battle_bg',
  UI: 'ui',
  VFX: 'vfx',
  ATLAS: 'atlas',
  FACTION: 'faction',
  RANK: 'rank',
  ICON: 'icon',
  ENVIRONMENT: 'environment',
  FX: 'fx',
  DATA: 'data',
  BADGE: 'badge'
} as const;

export type AssetType = typeof ASSET_TYPES[keyof typeof ASSET_TYPES];

export interface AssetOptions {
  isShiny?: boolean;
  shiny?: boolean; // Legacy fallback
  isBack?: boolean;
  back?: boolean; // Legacy fallback
  isAnimated?: boolean;
  animated?: boolean;
  cycle?: 'morning' | 'day' | 'dusk' | 'night';
  trainerSuffix?: 'avatar' | 'front' | 'back';
  gender?: 'h' | 'm' | string;
  isLowPower?: boolean;
  [key: string]: unknown;
}

/**
 * Global Asset Service / Router
 * Centralizes asset path construction and LOD application.
 */
export const getAssetUrl = (type: AssetType, rawId: string | number, options: AssetOptions = {}): string => {
  if (!rawId) return '';
  const { 
    isShiny: isShinyPrimary,
    shiny: isShinyLegacy,
    isBack: isBackPrimary,
    back: isBackLegacy
  } = options;

  const isShiny = isShinyPrimary ?? isShinyLegacy ?? false;
  const isBack = isBackPrimary ?? isBackLegacy ?? false;

  // If it's already a full URL, return it
  if (typeof rawId === 'string' && (rawId.startsWith('http') || rawId.startsWith('data:'))) {
    return rawId;
  }

  // Clean ID: strip extensions if present (e.g., 'item.png' -> 'item')
  const id = typeof rawId === 'string' 
    ? rawId.replace(/\.(png|webp|jpg|jpeg|gif|bmp|json)$/i, '') 
    : rawId;

  const extension = (typeof rawId === 'string' && rawId.endsWith('.json')) ? '.json' : '.webp';

  switch (type) {
    case ASSET_TYPES.POKEMON: {
      const stringId = String(id).toLowerCase();
      const num = (POKEMON_SPRITE_IDS as Record<string, number>)[stringId] || id;
      if (typeof id === 'string' && id.toLowerCase().startsWith('egg')) return resolveAsset(`/assets/sprites/egg${extension}`);

      if (options.isAnimated || options.animated) {
        const sideDir = isBack ? 'Back' : 'Front';
        const shinyDir = isShiny ? ' shiny' : '';
        return resolveAsset(`/assets/sprites/pokemon/animated/${sideDir}${shinyDir}/${num}${extension}`);
      }

      const folder = isShiny ? 'shiny/' : '';
      const back = isBack ? 'back/' : '';
      return resolveAsset(`${POKEAPI_BASE}${back}${folder}${num}${extension}`);
    }

    case ASSET_TYPES.MAP: {
      let finalId = id;

      // Aplicar sufijos de ciclo horario si el mapa lo soporta
      if (options.cycle && MAPS_WITH_CYCLES.includes(String(id))) {
        const suffixes: Record<string, string> = {
          morning: '_amanecer',
          day: '_dia',
          dusk: '_atardecer',
          night: '_noche'
        };
        finalId = `${id}${suffixes[options.cycle] || '_dia'}`;
      }

      if (options.isLowPower) {
        finalId = `${finalId}_mobile`;
      }

      const mapPath = `/assets/maps/${finalId}${extension}`;
      return resolveAsset(mapPath);
    }


    case ASSET_TYPES.TRAINER: {
      // Legacy mapping for mission keys (if trainerType was used as spriteId)
      const LEGACY_MAPPING: Record<string, string> = {
        'caza_bichos': 'cazabichos',
        'ornitologo': 'entrenador',
        'cientifico': 'criador',
        'luchador': 'entrenador',
        'pescador': 'tamer',
        'nadador': 'tamer',
        'domador': 'tamer',
        'medium': 'entrenador',
        'motorista': 'teamrocket',
        'montanero': 'tamer',
        'rocket': 'rocket',
        'cazador': 'cazabichos'
      };

      // Sanitize ID: remove spaces and dots (e.g., "Lt. Surge" -> "ltsurge")
      const idStr = String(id);
      const sanitizedId = idStr.toLowerCase().replace(/[\s.]/g, '');
      const finalId = LEGACY_MAPPING[sanitizedId] || sanitizedId;

      // Other remote URLs fallback
      if (idStr.startsWith('http')) return idStr;

      const PLAYER_CLASSES_LIST = ['rocket', 'cazabichos', 'entrenador', 'criador'];
      if (PLAYER_CLASSES_LIST.includes(finalId)) {
        const suffix = options.trainerSuffix || (isBack ? 'back' : 'front');
        const gender = options.gender || 'h';
        return resolveAsset(`/assets/sprites/trainers/${finalId}_${gender}_${suffix}${extension}`);
      }

      const NPC_MAPPING: Record<string, string> = {
        'brock': 'brock',
        'misty': 'misty',
        'ltsurge': 'ltsurge',
        'erika': 'erika',
        'koga': 'koga',
        'sabrina': 'sabrina',
        'blaine': 'blaine',
        'giovanni': 'giovanni',
        'blue': 'blue-gen3',
        'youngster': 'youngster',
        'lass': 'lass',
        'picnicker': 'picnicker',
        'camper': 'camper_b',
        'hiker': 'hiker',
        'sailor': 'sailor',
        'scientist': 'scientist',
        'juggler': 'juggler',
        'blackbelt': 'blackbelt',
        'swimmer': 'swimmer',
        'tamer': 'tamer-gen3',
        'birdkeeper': 'birdkeeper',
        'psychic': 'psychic',
        'gentleman': 'gentleman',
        'richboy': 'richboy',
        'tuber': 'tuber',
        'cyclist': 'cyclist',
        'roughneck': 'roughneck',
        'biker': 'biker',
        'teamrocket': 'teamrocket',
        'beauty': 'beauty',
        'supernerd': 'supernerd',
        'burglar': 'burglar',
        'dragontamer': 'dragontamer',
        'acetrainer': 'acetrainer',
        'veteran': 'veteran'
      };

      const npcId = NPC_MAPPING[finalId] || finalId;
      return resolveAsset(`/assets/sprites/npc/${npcId}${extension}`);
    }

    case ASSET_TYPES.ENVIRONMENT:
      return resolveAsset(`/assets/environment/${id}.webp`);

    case ASSET_TYPES.FX:
      return resolveAsset(`/assets/fx/${id}.webp`);

    case ASSET_TYPES.BANNER:
      return resolveAsset(`/assets/ui/banners/${id}${extension}`);

    case ASSET_TYPES.BATTLE_BG:
      return resolveAsset(`/assets/maps_battle/${id}${extension}`);

    case ASSET_TYPES.UI:
    case ASSET_TYPES.VFX:
    case ASSET_TYPES.ATLAS:
      return resolveAsset(`/assets/ui/${id}${extension}`);

    case ASSET_TYPES.FACTION:
      return resolveAsset(`/assets/factions/${id}${extension}`);

    case ASSET_TYPES.RANK:
      return resolveAsset(`/assets/ui/ranks/${id}${extension}`);

    case ASSET_TYPES.ICON:
      return resolveAsset(`/assets/ui/icons/${id}${extension}`);

    case ASSET_TYPES.DATA:
      return resolveAsset(`/assets/data/${id}.json`);

    case ASSET_TYPES.ITEM: {
      const idStr = String(id).toLowerCase();

      // Direct matching if they passed the full sprite path directly
      if (idStr.startsWith('crafting/') || idStr.startsWith('ores/') || idStr.startsWith('tools/')) {
        return resolveAsset(`/assets/sprites/${idStr}${extension}`);
      }

      // Match by ID against SHOP_ITEMS
      const shopItem = getItemById(idStr);
      if (shopItem) {
        return resolveAsset(`/assets/sprites/${shopItem.sprite}${extension}`);
      }

      // No fallback! Return standard tier3 location
      return resolveAsset(`/assets/sprites/crafting/tier3/${idStr}${extension}`);
    }

    case ASSET_TYPES.BADGE:
      return resolveAsset(`/assets/sprites/badges/${id}${extension}`);

    default:
      return String(id);
  }
};

export function useAssets() {
  return { getAssetUrl, ASSET_TYPES };
}

