export const useBattleStore = defineStore('battle', () => {
  const gs = useGameStore()
  const warStore = useWarStore()
  const eventStore = useEventStore()
  const classStore = usePlayerClassStore()
  const audio = useAudioStore()
  const uiStore = useUIStore()
  const mapStore = useMapStore()

  const activeBattle = ref<BattleState | null>(null)
  const fsm = createBattleStateMachine()
  const currentFsmState = computed(() => fsm.currentState.value)
  const currentSubState = computed(() => fsm.currentSubState.value)
  const faintedSides = ref(new Set<string>())

  const isBattleActive = computed(() => 
    activeBattle.value !== null && (
      fsm.currentState.value === BATTLE_STATES.CONTEXT_SETUP ||
      fsm.currentState.value === BATTLE_STATES.ACTIVE_BATTLE || 
      fsm.currentState.value === BATTLE_STATES.REWARDS_PHASE ||
      fsm.currentState.value === BATTLE_STATES.LEVEL_UP_MODAL ||
      fsm.currentState.value === BATTLE_STATES.REORDER_TEAM ||
      fsm.currentState.value === BATTLE_STATES.FIRST_INTRO ||
      fsm.currentState.value === BATTLE_STATES.INITIALIZING ||
      fsm.currentState.value === BATTLE_STATES.SEARCH_PHASE ||
      fsm.currentState.value === BATTLE_STATES.EXIT_BATTLE
    )
  )
  const isFinishing = computed(() => 
    fsm.currentState.value === BATTLE_STATES.REWARDS_PHASE || 
    fsm.currentState.value === BATTLE_STATES.LEVEL_UP_MODAL ||
    fsm.currentSubState.value === BATTLE_SUBSTATES.ENEMY_REPLACEMENT_SEQ ||
    fsm.currentSubState.value === BATTLE_SUBSTATES.PLAYER_FAINT_SEQ ||
    fsm.currentSubState.value === BATTLE_SUBSTATES.CATCH_SUCCESS
  )
  const isSearching = computed(() => fsm.currentState.value === BATTLE_STATES.SEARCH_PHASE)
  const isReadyToExit = computed(() => 
    fsm.currentState.value === BATTLE_STATES.EXIT_BATTLE && 
    fsm.currentSubState.value === BATTLE_SUBSTATES.DEFEAT_WAIT
  )
  const isIntroAnimating = ref(false)


  const isProcessing = ref(false)
  const debugBinoculars = ref(false)
  const debugShowGuides = ref(false)
  const debugShowFxRadius = ref(false)
  const debugShowPokeRadius = ref(false)

  const savedZoomVal = safeStorage.getItem('pvs_combat_zoom')
  const parsedZoom = savedZoomVal !== null ? parseFloat(savedZoomVal) : 1.0
  const initialZoom = !isNaN(parsedZoom) ? Math.max(0.5, Math.min(1.0, parsedZoom)) : 1.0
  const debugZoom = ref(initialZoom)

  watch(debugZoom, (newZoom) => {
    safeStorage.setItem('pvs_combat_zoom', String(newZoom))
  })

  const battleLogs = ref<BattleLog[]>([])
  const logQueue = ref<BattleLog[]>([])
  const isProcessingLogs = ref(false)
  const battleEndCallback = ref<(() => void) | null>(null)
  const attackerSide = ref<'player' | 'enemy' | null>(null)
  const activeMove = ref<Move | null>(null)

  const trainerAnimState = ref<'idle' | 'in' | 'out'>('idle')
  const isSilhouetteMode = ref(false)

  const playerStages = ref<BattleStages>({ ...INITIAL_STAGES })
  const enemyStages = ref<BattleStages>({ ...INITIAL_STAGES })
  const debugLoopPokemon = ref<Pokemon | null>(null)
  const exitingPlayer = ref<Pokemon | null>(null)
  const exitingEnemy = ref<Pokemon | null>(null)
  const animations = ref<BattleContext['animations']>()

  const player = computed(() => activeBattle.value?.player)
  const enemy = computed(() => activeBattle.value?.enemy)

  watch(() => mapStore.currentWeather, (newWeather) => {
    if (activeBattle.value && activeBattle.value.weather && activeBattle.value.weather.turns === -1) {
      // Sincronizar tanto el tipo mecánico como el visual con el clima actual del mapa
      activeBattle.value.weather.type = getMechanicalWeather(newWeather || 'clear')
      activeBattle.value.weather.visual = newWeather || 'clear'
    }
  })

  watch(() => [fsm.currentState.value, fsm.currentSubState.value], ([state, sub]) => {
    if (
      state === BATTLE_STATES.CONTEXT_SETUP ||
      state === BATTLE_STATES.EXIT_BATTLE ||
      sub === BATTLE_SUBSTATES.RESET_FLAGS
    ) {
      if (activeBattle.value) {
        activeBattle.value.isFishing = false
        activeBattle.value.isArchaeology = false
      }
      // Ensure minigame modals are closed on exit or reset
      try {
        const modalStore = useModalStore()
        modalStore.close('Fishing')
        modalStore.close('Archaeology')
      } catch (e) {
        logger.warn('BattleStore', 'Could not close minigame modals:', e)
      }
    }
  })

  const isPvP = computed(() => !!activeBattle.value?.isPvP)

  const getContext = (): BattleContext => ({
    gs: gs as unknown as GameStore, 
    warStore, 
    eventStore: eventStore as unknown as EventStore, 
    classStore, 
    audio: audio as unknown as AudioStore, 
    uiStore: uiStore as unknown as UIStore,
    activeBattle, 
    player, 
    enemy, 
    fsm, 
    BATTLE_STATES, 
    BATTLE_SUBSTATES,
    isBattleActive, 
    isFinishing, 
    isSearching, 
    isReadyToExit, 
    isIntroAnimating,
    isPvP,
    isProcessing, 
    debugBinoculars, 
    debugLoopPokemon,
    playerStages, 
    enemyStages, 
    battleLogs, 
    attackerSide, 
    activeMove,
    faintedSides,
    exitingPlayer,
    exitingEnemy,
    get animations() { return animations.value || undefined },
    addLog, 
    endBattle, 
    completeBattleFlow, 
    persistBattle, 
    waitForLogs, 
    clearLogs, 
    clearVolatileStatus, 
    startBattle, 
    _startBattle: startBattle, 
    initBattle,
    handleFaint
  })

  const restoreBattle = (battleData: BattleState) => restoreBattleState(getContext(), battleData)

  const persistBattle = () => syncAndPersist(getContext())

  const startBattle = async (enemyPoke: Pokemon, options?: BattleOptions) => {
    logger.info('BattleStore', `startBattle called for ${enemyPoke.name}`, options)
    return startBattleSequence(getContext(), enemyPoke, options)
  }

  const initBattle = async () => 
    initBattleSequence(getContext(), { 
      initialEnemy: activeBattle.value?.enemy || null,
      initialPlayer: (gs.state.team as Pokemon[]).find(p => p && p.hp > 0) || null
    })

  const addLog = (msg: string, type = 'log-info', source: BattleSource | null = null, sideOverride: 'player' | 'enemy' | null = null) => {
    const ctx = {
      gs,
      activeBattle: activeBattle.value,
      attackerSide: attackerSide.value
    }

    const logItem = formatBattleLog(msg, type, source as BattleSource, ctx)
    if (sideOverride) logItem.side = sideOverride

    logQueue.value.push(logItem)
    if (!isProcessingLogs.value) processNextLog()
  }


  const processNextLog = async () => {
    if (isProcessingLogs.value) return 
    isProcessingLogs.value = true

    while (true) {
      if (logQueue.value.length === 0) {
        isProcessingLogs.value = false
        if (logQueue.value.length > 0) {
          isProcessingLogs.value = true
          continue
        }
        break
      }

      const batchSize = logQueue.value.length > 6 ? 3 : (logQueue.value.length > 3 ? 2 : 1)

      for (let i = 0; i < batchSize; i++) {
        if (logQueue.value.length === 0) break
        const nextItem = logQueue.value.shift()
        if (nextItem) {
          battleLogs.value.push(nextItem)
          if (battleLogs.value.length > 30) battleLogs.value.shift()
        }
      }

      const delay = logQueue.value.length > 0 ? 100 : 350
      await sleep(delay)
    }
  }

  const clearLogs = () => {
    battleLogs.value = []; logQueue.value = []; isProcessingLogs.value = false;
    playerStages.value = { ...INITIAL_STAGES }
    enemyStages.value = { ...INITIAL_STAGES }
    activeMove.value = null
    attackerSide.value = null
  }

  const waitForLogs = async () => {
    while (isProcessingLogs.value || logQueue.value.length > 0) {
      await sleep(100)
    }
  }

  const executeMove = async (moveIndex: number) => {
    if (isProcessing.value || !isBattleActive.value) return
    isProcessing.value = true
    try {
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EXEC_TURN)
      fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.TURN_ENGINE)
      await executeTurn(getContext(), moveIndex)

      if (!activeBattle.value) {
        return
      }

      if (!activeBattle.value.over) await applyEndTurnEffects()
      activeMove.value = null

      if (activeBattle.value && !activeBattle.value.over && fsm.currentState.value === BATTLE_STATES.ACTIVE_BATTLE) {
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ANIM_SYNC)
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.UPDATE_BUTTON)
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT)
      }
    } catch (error) {
      logger.error('BattleStore', `Error executing move index ${moveIndex}: ${(error as Error).message}`, error)
      addLog('¡Ocurrió un error al ejecutar el movimiento!', 'log-error')
      useErrorStore().setError(error, { type: 'Battle Engine Error', source: `battleStore.executeMove(index:${moveIndex})` })
    } finally {
      isProcessing.value = false
    }
  }

  const applyEndTurnEffects = async () => await executeEndTurnEffects(getContext())

  const handleFaint = async (side: 'player' | 'enemy') => await processFaint(getContext(), side)

  const useItemInBattle = async (itemId: string, targetIndex: number | null = null) => {
    if (isProcessing.value || !isBattleActive.value || !activeBattle.value) return
    isProcessing.value = true

    try {
      const targetPoke = (targetIndex !== null) ? gs.state.team[targetIndex] : activeBattle.value.player
      if (!targetPoke) { isProcessing.value = false; return }

      attackerSide.value = 'player'
      if (!activeBattle.value || !activeBattle.value.enemy) { isProcessing.value = false; return }

      const res = await handleItemUsage(itemId, targetPoke, activeBattle.value.enemy, { 
        eventStore, addLog, audio, consumeItem, ctx: getContext(), fsm, itemId
      })
      attackerSide.value = null
      activeMove.value = null

      const castRes = res as { action: string, pokemon?: Pokemon }
      if (castRes.action === 'capture') {
        activeBattle.value.isCapture = true
        activeBattle.value.over = true 

        // Cazabichos: Red Maestra (20% chance to duplicate captured bug Pokemon)
        if (gs.state.playerClass === 'cazabichos' && castRes.pokemon) {
          const cap = castRes.pokemon;
          const t1 = String(cap.type || '').toLowerCase();
          const t2 = String(cap.type2 || '').toLowerCase();
          const isBug = t1 === 'bug' || t1 === 'bicho' || t2 === 'bug' || t2 === 'bicho';

          if (isBug && Math.random() < 0.20) {
            const { makePokemon } = await import('@/logic/pokemon/pokemonFactory');
            const clone = makePokemon(cap.id || cap.name, cap.level || 5);
            if (clone) {
              clone.caught = true;
              clone.nickname = cap.nickname;
              gs.state.box.push(clone);
              addLog(`¡Red Maestra duplicó la captura! Se envió una copia de ${clone.name} a la caja.`, 'log-success', 'player');
              uiStore.notify(`¡Captura duplicada! Copia de ${clone.name} en la caja`, '🕸️');
            }
          }
        }

        gs.addPokemon(castRes.pokemon || null, { notify: true })
        isProcessing.value = false
        await endBattle(true, false)
        return
      } else if (castRes.action !== 'fail') {
        if (castRes.pokemon && activeBattle.value?.player) {
          const isTargetActive = (targetIndex === null || targetIndex === activeBattle.value.playerTeamIndex)
          if (isTargetActive) {
            activeBattle.value.player = { ...castRes.pokemon }
            syncTeamHP()
          }
        }
        persistBattle()
        if (castRes.action === 'heal') {
          await sleep(800)
        }
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.APPLY_MOVE)
        await runEnemyAction(getContext())
        await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.EVAL_HP)

        if (activeBattle.value?.player && activeBattle.value.player.hp <= 0) {
          await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.PLAYER_FAINT_SEQ)
          await handleFaint('player')
          isProcessing.value = false
          return
        }
        if (activeBattle.value?.enemy && activeBattle.value.enemy.hp <= 0) {
          await fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.ENEMY_REPLACEMENT_SEQ)
          await handleFaint('enemy')
          isProcessing.value = false
          return
        }
      }
      if (activeBattle.value && !activeBattle.value.over && fsm.currentState.value === BATTLE_STATES.ACTIVE_BATTLE) {
        fsm.transition(BATTLE_STATES.ACTIVE_BATTLE, BATTLE_SUBSTATES.WAIT_INPUT)
      }
    } catch (error) {
      logger.error('BattleStore', `Error using item in battle: ${(error as Error).message}`, error)
      addLog('¡Ocurrió un error al usar el objeto!', 'log-error')
      useErrorStore().setError(error, { type: 'Battle Item Error', source: 'battleStore.useItemInBattle' })
    } finally {
      isProcessing.value = false
    }
  }
  const endBattle = async (win: boolean, fled: boolean) => {
    logger.info('BattleStore', `endBattle called. Win: ${win}, Fled: ${fled}`)
    return terminateBattle(getContext(), win, fled)
  }
  const syncTeamHP = () => {
    const team = gs.state.team;
    const active = activeBattle.value;
    if (active?.player && team && team[active.playerTeamIndex]) {
      const p = team[active.playerTeamIndex];
      if (p) p.hp = active.player.hp
    }
  }
  const _executeSwitch = async (teamIndex: number, isForced = false) => {
    if (isProcessing.value && !isForced) return
    isProcessing.value = true
    try {
      await switchAction(getContext(), teamIndex, isForced)
    } catch (error) {
      logger.error('BattleStore', `Error switching pokemon: ${(error as Error).message}`, error)
      addLog('¡Ocurrió un error al cambiar de Pokémon!', 'log-error')
      useErrorStore().setError(error, { type: 'Battle Switch Error', source: 'battleStore.executeSwitch' })
    } finally {
      isProcessing.value = false
    }
  }

  const consumeItem = (itemName: string) => {
    if (gs.state && gs.state.inventory[itemName]) {
      gs.state.inventory[itemName]--
      if (gs.state && gs.state.inventory[itemName] <= 0) delete gs.state.inventory[itemName]
    }
  }

  const completeBattleFlow = async (option?: string) => await handleBattleFlowCompletion(getContext(), option)

  const triggerSearchEncounter = async () => await triggerNextEncounter(getContext())

  const awardDebugExp = async () => {
    const { awardDebugExp: awardExpFn } = await import('../logic/battle/resolution.ts')
    await awardExpFn(getContext())
  }

  if (typeof window !== 'undefined') {
    const win = window as unknown as { __VITE_DEBUG_STORE_RESOLVER__?: () => unknown }
    win.__VITE_DEBUG_STORE_RESOLVER__ = () => useBattleStore()
    setupBattleDebug(getContext())
  }

  return {
    state: activeBattle,
    isBattleActive,
    awardDebugExp,
    isFinishing,
    isProcessing,
    isSearching,
    player,
    enemy,
    isIntroAnimating,
    isPvP,
    playerStages,
    enemyStages,
    battleLogs,
    debugLoopPokemon,
    debugBinoculars,
    debugShowGuides,
    debugShowFxRadius,
    debugShowPokeRadius,
    debugZoom,
    attackerSide,
    activeMove,
    exitingPlayer,
    exitingEnemy,
    animations,
    trainerAnimState,
    isSilhouetteMode,
    fsm,
    currentFsmState,
    currentSubState,
    isReadyToExit,
    restoreBattle,
    addLog,
    clearLogs,
    executeMove,
    persistBattle,
    flee: async () => {
      try {
        await executeFlee(getContext())
      } catch (error) {
        logger.error('BattleStore', `Error fleeing from battle: ${(error as Error).message}`, error)
        useErrorStore().setError(error, { type: 'Battle Flee Error', source: 'battleStore.flee' })
      }
    },
    completeBattleFlow: (option?: string) => completeBattleFlow(option),
    triggerSearchEncounter,
    setFinishing: (cb: () => void) => { fsm.transition(BATTLE_STATES.REWARDS_PHASE); battleEndCallback.value = cb },
    useItemInBattle,
    endBattle,
    handleFaint,
    applyEndTurnEffects,
    startBattle,
    _startBattle: startBattle,
    initBattle,
    startEncounter: async () => await startEncounter(getContext()),
    executeSwitch: _executeSwitch
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { calculateRocketSellPrice as calculatePrice } from '@/logic/pokemon/pokemonUtils'
import { useBoxFilters } from '@/composables/useBoxFilters'
import type { Pokemon } from '@/types/pokemon'

import { usePlayerClassStore } from './playerClass.ts'

export const useBoxStore = defineStore('box', () => {
  const gameStore = useGameStore()
  const uiStore = useUIStore()

  // --- BOX STATE ---
  const currentBoxIndex = ref(0)
  const boxReleaseMode = ref(false)
  const boxReleaseSelected = ref<number[]>([]) // Indices
  const boxRocketMode = ref(false)
  const boxRocketSelected = ref<number[]>([]) // Indices

  // --- TEAM STATE ---
  const teamReleaseMode = ref(false)
  const teamReleaseSelected = ref<number[]>([]) // Indices
  const teamRocketMode = ref(false)
  const teamRocketSelected = ref<number[]>([]) // Indices

  // --- FILTERS & SORTING COMPOSABLE ---
  const boxDataRef = computed(() => gameStore.state.box || [])
  const {
    filters,
    sortMode: boxSortMode,
    processedBoxList: filteredBox,
    hasActiveFilters,
    toggleFilters,
    resetFilters,
    setBoxSort
  } = useBoxFilters(boxDataRef)

  // --- COMPUTED ---
  const boxRocketSellValue = computed(() => getRocketSellValue())

  // --- ACTIONS ---
  function switchBox(index: number) {
    currentBoxIndex.value = index
  }

  function toggleBoxReleaseMode() {
    boxReleaseMode.value = !boxReleaseMode.value
    boxReleaseSelected.value = []
    if (boxReleaseMode.value) {
      boxRocketMode.value = false
      boxRocketSelected.value = []
    }
  }

  function toggleBoxReleaseSelect(index: number) {
    const p = gameStore.state.box[index]
    if (p && (p.onMission || p.inDaycare || p.onDefense)) return

    const idx = boxReleaseSelected.value.indexOf(index)
    if (idx > -1) {
      boxReleaseSelected.value.splice(idx, 1)
    } else {
      boxReleaseSelected.value.push(index)
    }
  }

  function doBoxRelease() {
    const indices = [...boxReleaseSelected.value].sort((a, b) => b - a)
    const releasedNames: string[] = []

    indices.forEach(i => {
      const p = gameStore.state.box[i]
      if (p) {
        if (p.onMission || p.inDaycare || p.onDefense) return
        releasedNames.push(p.name)
        returnHeldItem(p)
        gameStore.state.box.splice(i, 1)
      }
    })

    boxReleaseMode.value = false
    boxReleaseSelected.value = []
    gameStore.autoFillPvpTeam()
    gameStore.scheduleSave()
    return releasedNames
  }

  function toggleBoxRocketMode() {
    if (gameStore.state.playerClass !== 'rocket') return
    boxRocketMode.value = !boxRocketMode.value
    boxRocketSelected.value = []
    if (boxRocketMode.value) {
      boxReleaseMode.value = false
      boxReleaseSelected.value = []
    }
  }

  function toggleSelection(index: number) {
    if (boxReleaseMode.value) toggleBoxReleaseSelect(index)
    else if (boxRocketMode.value) toggleBoxRocketSelect(index)
  }

  function toggleBoxRocketSelect(index: number) {
    const p = gameStore.state.box[index]
    if (p && (p.onMission || p.inDaycare || p.onDefense)) return

    const idx = boxRocketSelected.value.indexOf(index)
    if (idx > -1) {
      boxRocketSelected.value.splice(idx, 1)
    } else {
      boxRocketSelected.value.push(index)
    }
  }

  function getRocketSellValue() {
    let total = 0
    boxRocketSelected.value.forEach(i => {
      const p = gameStore.state.box[i]
      if (!p || p.onMission || p.inDaycare || p.onDefense) return
      total += calculatePrice(p)
    })
    return total
  }

  function doBoxRocketSell() {
    const value = getRocketSellValue()
    const indices = [...boxRocketSelected.value].sort((a, b) => b - a)
    let soldCount = 0

    indices.forEach(i => {
      const p = gameStore.state.box[i]
      if (p) {
        if (p.onMission || p.inDaycare || p.onDefense) return
        soldCount++
        returnHeldItem(p)
        gameStore.state.box.splice(i, 1)
      }
    })

    gameStore.state.money += value
    if (gameStore.state.classData) {
      gameStore.state.classData.blackMarketSales = (gameStore.state.classData.blackMarketSales || 0) + soldCount
    }

    const classStore = usePlayerClassStore()
    if (soldCount > 0) {
      classStore.addCriminality(soldCount * 10)
    }

    boxRocketMode.value = false
    boxRocketSelected.value = []
    gameStore.autoFillPvpTeam()
    gameStore.scheduleSave()
    return { value, count: soldCount }
  }

  function movePokemonToBox(boxIndex: number, targetBoxIndex: number) {
    const p = gameStore.state.box[boxIndex]
    if (!p) return { success: false, msg: 'Pokémon no encontrado.' }

    const targetStart = targetBoxIndex * 50
    gameStore.state.box.splice(boxIndex, 1)

    // Ensure array is large enough to reach target box
    while (gameStore.state.box.length < targetStart) {
      gameStore.state.box.push(null as unknown as Pokemon)
    }

    gameStore.state.box.splice(targetStart, 0, p)

    gameStore.scheduleSave()
    return { success: true, msg: `¡${p.name} movido a la Caja ${targetBoxIndex + 1}!` }
  }

  function togglePokeTag(boxIndex: number, tag: string) {
    const p = gameStore.state.box[boxIndex]
    if (!p) return
    if (!p.tags) p.tags = []
    const idx = p.tags.indexOf(tag)
    if (idx > -1) p.tags.splice(idx, 1)
    else p.tags.push(tag)
    gameStore.scheduleSave()
  }

  // --- TEAM ACTIONS ---
  function toggleTeamReleaseMode() {
    teamReleaseMode.value = !teamReleaseMode.value
    teamReleaseSelected.value = []
    if (teamReleaseMode.value) {
      teamRocketMode.value = false
      teamRocketSelected.value = []
    }
  }

  function toggleTeamReleaseSelect(index: number) {
    const idx = teamReleaseSelected.value.indexOf(index)
    if (idx > -1) {
      teamReleaseSelected.value.splice(idx, 1)
    } else {
      teamReleaseSelected.value.push(index)
    }
  }

  function confirmTeamRelease() {
    if (teamReleaseSelected.value.length === 0) return

    const team = gameStore.state.team || []
    if (team.length - teamReleaseSelected.value.length < 1) {
      uiStore.notify('No puedes soltar a todos tus Pokémon.', '⚠️')
      return
    }

    uiStore.openConfirm({
      title: 'Soltar Pokémon',
      message: `¿Estás seguro de que quieres soltar ${teamReleaseSelected.value.length} Pokémon?`,
      onConfirm: () => {
        const indices = [...teamReleaseSelected.value].sort((a, b) => b - a)
        const names: string[] = []

        indices.forEach(i => {
          const p = team[i]
          if (p) {
            names.push(p.name)
            returnHeldItem(p)
            team.splice(i, 1)
          }
        })

        uiStore.notify(`¡${names.join(', ')} fueron soltados!`, '🌿')
        teamReleaseMode.value = false
        teamReleaseSelected.value = []
        gameStore.autoFillPvpTeam()
        gameStore.scheduleSave()
      }
    })
  }

  function toggleTeamRocketMode() {
    if (gameStore.state.playerClass !== 'rocket') return
    teamRocketMode.value = !teamRocketMode.value
    teamRocketSelected.value = []
    if (teamRocketMode.value) {
      teamReleaseMode.value = false
      teamReleaseSelected.value = []
    }
  }

  // Helpers
  function returnHeldItem(pokemon: Pokemon) {
    if (!pokemon || !pokemon.heldItem) return
    const item = pokemon.heldItem
    const inv = gameStore.state.inventory
    inv[item] = (inv[item] || 0) + 1;
    pokemon.heldItem = null
  }

  function moveBoxToTeam(boxIndex: number) {
    const boxPoke = gameStore.state.box[boxIndex]
    if (!boxPoke) return { success: false, msg: 'Pokémon no encontrado.' }
    if (gameStore.state.team.length >= 6) return { success: false, msg: 'Equipo lleno.' }

    if (boxPoke.onMission) return { success: false, msg: 'En misión idle.' }
    if (boxPoke.inDaycare) return { success: false, msg: 'En la Guardería.' }
    if (boxPoke.onDefense) return { success: false, msg: 'En Defensa Pasiva.' }

    gameStore.state.box.splice(boxIndex, 1)
    gameStore.state.team.push(boxPoke)
    gameStore.autoFillPvpTeam()
    gameStore.scheduleSave()
    return { success: true, msg: `${boxPoke.name} se unió al equipo.` }
  }

  function swapBoxWithTeam(boxIndex: number, teamIndex: number) {
    const boxPoke = gameStore.state.box[boxIndex]
    const teamPoke = gameStore.state.team[teamIndex]
    if (!boxPoke || !teamPoke) return { success: false, msg: 'Pokémon no encontrado.' }

    if (boxPoke.onMission || boxPoke.inDaycare || boxPoke.onDefense) return { success: false, msg: 'Pokémon ocupado.' }

    gameStore.state.box.splice(boxIndex, 1)
    const swapped = gameStore.state.team.splice(teamIndex, 1, boxPoke)[0]!

    gameStore.state.box.splice(boxIndex, 0, swapped)
    gameStore.autoFillPvpTeam()
    gameStore.scheduleSave()
    return { success: true, msg: 'Intercambio realizado.' }
  }

  function getBoxBuyCost() {
    const count = gameStore.state.boxCount || 4
    if (count < 4) return 500000
    if (count === 4) return 500000
    if (count === 5) return 1000000
    return 1000000 * Math.pow(2, count - 5)
  }

  function buyNewBox() {
    const cost = getBoxBuyCost()
    if (gameStore.state.money < cost) return { success: false, msg: 'Dinero insuficiente.' }

    gameStore.state.money -= cost
    gameStore.state.boxCount = (gameStore.state.boxCount || 4) + 1
    gameStore.scheduleSave()
    return { success: true, boxNum: gameStore.state.boxCount }
  }

  function toggleTeamRocketSelect(index: number) {
    const idx = teamRocketSelected.value.indexOf(index)
    if (idx > -1) {
      teamRocketSelected.value.splice(idx, 1)
    } else {
      teamRocketSelected.value.push(index)
    }
  }

  function confirmTeamRocketSell() {
    const count = teamRocketSelected.value.length
    if (count === 0) return

    const team = gameStore.state.team || []
    let totalGain = 0
    teamRocketSelected.value.forEach(i => {
      const p = team[i]
      if (p) totalGain += calculatePrice(p)
    })

    uiStore.openConfirm({
      title: 'Vender Pokémon (Team Rocket)',
      message: `¿Vender ${count} Pokémon por ₽${totalGain.toLocaleString()}?`,
      onConfirm: () => {
        const indices = [...teamRocketSelected.value].sort((a, b) => b - a)
        const names: string[] = []

        indices.forEach(i => {
          const p = team[i]
          if (p) {
            names.push(p.name)
            returnHeldItem(p)
            team.splice(i, 1)
          }
        })

        gameStore.state.money += totalGain
        if (gameStore.state.classData) {
          gameStore.state.classData.blackMarketSales = (gameStore.state.classData.blackMarketSales || 0) + count
        }

        uiStore.notify(`¡${count} Pokémon vendidos por ₽${totalGain.toLocaleString()}! 🚀`, '🚀')
        teamRocketMode.value = false
        teamRocketSelected.value = []
        gameStore.autoFillPvpTeam()
        gameStore.scheduleSave()
      }
    })
  }

  return {
    currentBoxIndex,
    boxSortMode,
    boxReleaseMode,
    boxReleaseSelected,
    boxRocketMode,
    boxRocketSelected,
    boxRocketSellValue,
    filters,
    filteredBox,
    hasActiveFilters,
    teamReleaseMode,
    teamReleaseSelected,
    teamRocketMode,
    teamRocketSelected,
    toggleFilters,
    resetFilters,
    switchBox,
    setBoxSort,
    toggleBoxReleaseMode,
    toggleBoxReleaseSelect,
    doBoxRelease,
    toggleBoxRocketMode,
    toggleBoxRocketSelect,
    toggleSelection,
    getRocketSellValue,
    doBoxRocketSell,
    movePokemonToBox,
    toggleTeamReleaseMode,
    toggleTeamReleaseSelect,
    confirmTeamRelease,
    toggleTeamRocketMode,
    toggleTeamRocketSelect,
    confirmTeamRocketSell,
    moveBoxToTeam,
    swapBoxWithTeam,
    togglePokeTag,
    getBoxBuyCost,
    buyNewBox
  }
})

// [PureVue-Ignore-Length]
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import { useGameStore } from './game.ts';
import { useUIStore } from './ui.ts';
import { useAuthStore } from './auth.ts';
import gsap from 'gsap';
import { 
  checkCompatibility, 
  calculateInheritance, 
  inheritNature,
  inheritMoves,
  inheritAbility,
  calculateShinyChance,
} from '@/logic/breeding/breedingEngine';
import { eggFactory } from '@/logic/breeding/eggFactory';
import { EGG_SPAWN_INTERVAL_MS } from '@/logic/breeding/breedingData';
import { POKEMON_DB } from '@/data/pokemonDB';
import { usePlayerClassStore } from './playerClass.ts';
import { useEventStore } from './events.ts';
import { useDaycareMissionsStore } from './daycareMissions.ts';
import { calculateBreedingCost, executeCloneFossil } from './breedingActions.ts';
import type { DaycareSlot, DaycareEgg, DaycareMission } from '@/types/breeding';
import type { Pokemon, PokemonIVs } from '@/types/pokemon';

export const useBreedingStore = defineStore('breeding', () => {
  const gameStore = useGameStore();
  const uiStore = useUIStore();
  const classStore = usePlayerClassStore();
  const eventStore = useEventStore();
  const authStore = useAuthStore();
  const daycareMissionsStore = useDaycareMissionsStore();

  const slots = ref<DaycareSlot[]>([
    { pokemon: null, slotIndex: 0, deposited_at: null },
    { pokemon: null, slotIndex: 1, deposited_at: null }
  ]); // [{ pokemon, slot_index, deposited_at }]
  const warehouseEggs = ref<DaycareEgg[]>([]); // Eggs waiting to be claimed
  const dailyMissions = computed<DaycareMission[]>({
    get: () => daycareMissionsStore.dailyMissions,
    set: (val) => { daycareMissionsStore.dailyMissions = val }
  });
  const missionRefreshes = computed<number>({
    get: () => daycareMissionsStore.missionRefreshes,
    set: (val) => { daycareMissionsStore.missionRefreshes = val }
  });
  const loading = ref(false);

  // --- HELPERS & PERSISTENCE ---



  function saveWarehouseEggs() {
    const userId = authStore.user?.id || 'default';
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(`daycare_warehouse_eggs_${userId}`, JSON.stringify(warehouseEggs.value));
    }
  }

  // --- GETTERS ---
  const fulfillableMissionsCount = computed(() => daycareMissionsStore.fulfillableMissionsCount);

  const isBreeding = computed(() => slots.value.length === 2 && !!slots.value[0]?.pokemon && !!slots.value[1]?.pokemon);

  const compatibility = computed(() => {
    if (!isBreeding.value) {
      return { level: 0, reason: 'Deposita 2 Pokémon', sharedGroups: [], eggSpecies: '' };
    }
    const p1 = slots.value[0]?.pokemon;
    const p2 = slots.value[1]?.pokemon;
    if (!p1 || !p2) return { level: 0, reason: 'Deposita 2 Pokémon', sharedGroups: [], eggSpecies: '' };
    return checkCompatibility(p1, p2);
  });

  const nextEggTime = computed(() => {
    const level = compatibility.value.level;
    if (level === 0) return null;
    const interval = (EGG_SPAWN_INTERVAL_MS as Record<number, number>)[level];
    if (!interval) return null;

    if (!slots.value[0]?.deposited_at || !slots.value[1]?.deposited_at) return null;

    const pA = slots.value[0]?.pokemon;
    const pB = slots.value[1]?.pokemon;
    if (!pA || !pB || (pA.vigor || 0) <= 0 || (pB.vigor || 0) <= 0) return null;

    const depA = Temporal.Instant.from(slots.value[0].deposited_at).epochMilliseconds;
    const depB = Temporal.Instant.from(slots.value[1].deposited_at).epochMilliseconds;
    const earliest = Math.max(depA, depB);

    return earliest + interval;
  });

  // --- ACTIONS ---

  async function loadDaycare() {
    loading.value = true;
    try {
      slots.value = [
        { pokemon: null, slotIndex: 0, deposited_at: null },
        { pokemon: null, slotIndex: 1, deposited_at: null }
      ];

      // Restore eggs from LocalStorage
      const userId = authStore.user?.id || 'default';
      const stored = typeof localStorage !== 'undefined' ? localStorage.getItem(`daycare_warehouse_eggs_${userId}`) : null;
      warehouseEggs.value = stored ? JSON.parse(stored) : [];

      const team = gameStore.state.team || [];
      const box = gameStore.state.box || [];
      const all = [...team, ...box];
      const deposited = all.filter(p => p && p.inDaycare);

      let needsSave = false;
      deposited.forEach(p => {
        let idx = typeof p.daycareSlot === 'number' ? p.daycareSlot : -1;
        if (idx === -1) {
          idx = slots.value.findIndex(s => s.pokemon === null);
          if (idx === -1) idx = 0;
          p.daycareSlot = idx;
          needsSave = true;
        }
        // If daycareDepositedAt is missing (save predates this feature),
        // assign it now and mark for save so it persists on future loads
        if (!p.daycareDepositedAt) {
          p.daycareDepositedAt = Temporal.Now.instant().toString();
          needsSave = true;
        }
        slots.value[idx] = {
          pokemon: p,
          slotIndex: idx,
          deposited_at: p.daycareDepositedAt
        };
      });

      if (needsSave) {
        gameStore.scheduleSave();
      }

      // Capa 1: Check retroactively if a new egg should be generated
      await checkAndGenerateEgg();
    } finally {
      loading.value = false;
    }
  }

  async function deposit(pokemon: Pokemon, slotIndex: number) {
    if (pokemon.hp <= 0) {
      uiStore.notify('No puedes depositar un Pokémon debilitado en la Guardería.', '⚠️');
      return false;
    }

    const legendaries = new Set([
      'articuno', 'zapdos', 'moltres', 'mewtwo', 'mew',
      'raikou', 'entei', 'suicune', 'lugia', 'ho_oh', 'ho-oh', 'celebi'
    ]);
    if (pokemon.id && legendaries.has(pokemon.id.toLowerCase())) {
      uiStore.notify('Los Pokémon legendarios no pueden reproducirse en la Guardería.', '⚠️');
      return false;
    }

    if (pokemon.onMission || pokemon.onDefense) {
      uiStore.notify('Este Pokémon está ocupado.', '⚠️');
      return false;
    }

    // Move to box if it was in the active team
    const teamIdx = gameStore.state.team.findIndex((p: Pokemon | null) => p && p.uid === pokemon.uid);
    if (teamIdx !== -1) {
      if (gameStore.state.team.length <= 1) {
        uiStore.notify('No puedes depositar a tu único Pokémon del equipo.', '⚠️');
        return false;
      }
      const p = gameStore.state.team.splice(teamIdx, 1)[0];
      if (p) {
        gameStore.state.box.push(p);
        gameStore.autoFillPvpTeam();
      }
    }

    pokemon.inDaycare = true;
    pokemon.daycareSlot = slotIndex;
    // Preserve deposited_at from the first deposit so the egg timer never resets
    if (!pokemon.daycareDepositedAt) {
      pokemon.daycareDepositedAt = Temporal.Now.instant().toString();
    }
    const now = pokemon.daycareDepositedAt;
    slots.value[slotIndex] = { pokemon, slotIndex, deposited_at: now };

    uiStore.notify(`¡${pokemon.name} depositado en la Guardería!`, '🏡');
    gameStore.scheduleSave();
    return true;
  }

  function withdraw(slotIndex: number) {
    const slot = slots.value[slotIndex];
    if (!slot || !slot.pokemon) return false;

    const pokemonUid = slot.pokemon.uid;
    const team = gameStore.state.team || [];
    const box = gameStore.state.box || [];
    const found = [...team, ...box].find(p => p && p.uid === pokemonUid);
    if (found) {
      found.inDaycare = false;
      found.daycareSlot = undefined;
      found.daycareDepositedAt = undefined;
    } else {
      slot.pokemon.inDaycare = false;
      slot.pokemon.daycareSlot = undefined;
      slot.pokemon.daycareDepositedAt = undefined;
    }

    slots.value[slotIndex] = { pokemon: null, slotIndex, deposited_at: null };
    uiStore.notify(`¡${slot.pokemon.name} retirado de la Guardería!`, '🏡');
    gameStore.scheduleSave();
    return true;
  }

  async function checkAndGenerateEgg() {
    if (!isBreeding.value || compatibility.value.level === 0) return;
    if (!slots.value[0]?.pokemon || !slots.value[1]?.pokemon) return;
    if (!nextEggTime.value) return;

    const now = Temporal.Now.instant().epochMilliseconds;
    if (now < nextEggTime.value) return;

    const pA = slots.value[0].pokemon as Pokemon;
    const pB = slots.value[1].pokemon as Pokemon;
    const compat = compatibility.value;

    if ((pA.vigor || 0) <= 0 || (pB.vigor || 0) <= 0) {
      return;
    }

    const eggSpecies = compat.eggSpecies || '';
    const itemA = pA.heldItem || '';
    const itemB = pB.heldItem || '';
    const playerClass = classStore.playerClass as string;

    const abilityName = inheritAbility(pA, pB);
    const abilityIndex = abilityName ? 1 : 0;

    const breedingCost = calculateBreedingCost(pA, pB);

    const egg = eggFactory.createDaycareEgg({
      species: eggSpecies,
      motherId: compat.motherId,
      ivs: calculateInheritance(pA, pB, itemA, itemB, playerClass),
      nature: inheritNature(pA, pB, itemA, itemB) || 'Serio',
      movesAtBirth: inheritMoves(pA, pB, eggSpecies),
      abilityIndex: abilityIndex,
      isShiny: Math.random() < calculateShinyChance(pA, pB, 1/4096, eventStore.globalMultipliers?.shiny || 1),
      cost: breedingCost
    });

    // Consume parent vigor by 1 point
    pA.vigor = Math.max(0, (pA.vigor || 0) - 1);
    pB.vigor = Math.max(0, (pB.vigor || 0) - 1);

    warehouseEggs.value.push(egg);
    saveWarehouseEggs();

    const isoNow = Temporal.Now.instant().toString();
    if (slots.value[0]) {
      slots.value[0].deposited_at = isoNow;
      pA.daycareDepositedAt = isoNow;
    }
    if (slots.value[1]) {
      slots.value[1].deposited_at = isoNow;
      pB.daycareDepositedAt = isoNow;
    }

    uiStore.notify(' ¡Apareció un huevo en la Guardería!', '🥚');
    if ((pA.vigor || 0) <= 0 || (pB.vigor || 0) <= 0) {
      uiStore.notify('¡Uno de los padres se ha quedado sin vigor! Consigue Caramelos de vigor o Restauradores de vigor para continuar criando.', '💤');
    }
    gameStore.scheduleSave();
  }

  function claimEgg(eggId: string) {
    const eggIndex = warehouseEggs.value.findIndex((e) => e.id === eggId);
    if (eggIndex === -1) return;

    const egg = warehouseEggs.value[eggIndex];
    if (!egg) return;

    if (!gameStore.state.eggs) gameStore.state.eggs = [];

    // Slot limit: max 6 regular eggs. Slot 7 is reserved for NPC quest eggs only.
    const regularEggs = gameStore.state.eggs.filter(e => !e.isNpc);
    if (regularEggs.length >= 6) {
      uiStore.notify('Tu incubadora está llena. Puedes llevar un máximo de 6 huevos.', '🥚');
      return;
    }

    if (gameStore.state.money < egg.cost) {
      uiStore.notify(`No tienes suficiente dinero ($${egg.cost.toLocaleString()}).`, '💰');
      return;
    }

    const eggToPush = eggFactory.createPokemonEgg({
      species: egg.species,
      steps: egg.steps,
      ivs: egg.ivs,
      nature: egg.nature,
      movesAtBirth: egg.movesAtBirth,
      abilitySlot: egg.abilityIndex,
      isShiny: egg.isShiny,
      tint: egg.tint,
      isAncestral: egg.isAncestral
    });
    gameStore.state.eggs.push(eggToPush);
    gameStore.state.money -= egg.cost;
    warehouseEggs.value.splice(eggIndex, 1);
    saveWarehouseEggs();

    uiStore.notify('¡Huevo recogido! Camina para eclosionarlo.', '🥚');
    gameStore.scheduleSave();
  }

  function scanEgg(eggId: string) {
    if (classStore.playerClass !== 'criador') {
      uiStore.notify('Solo los Criadores pueden escanear huevos.', '🔒');
      return;
    }
    if ((gameStore.state.classLevel || 1) < 20) {
      uiStore.notify('Necesitas nivel 20 de Criador para usar el escáner.', '🔒');
      return;
    }

    // Cooldown diario
    const lastScan = gameStore.state.classData?.lastEggScanDate;
    const todayStr = Temporal.Now.instant().toString().split('T')[0] || '';
    if (lastScan && lastScan.startsWith(todayStr)) {
      uiStore.notify('Ya has usado el escáner de IVs hoy.', '⚠️');
      return;
    }

    const egg = warehouseEggs.value.find((e) => e.id === eggId);
    if (!egg) return;

    if (egg.ivs) {
      if (!egg.inherited_ivs) egg.inherited_ivs = { };
      egg.inherited_ivs._scanned = true;

      if (!gameStore.state.classData) {
        gameStore.state.classData = {
          captureStreak: 0,
          longestStreak: 0,
          reputation: 0,
          blackMarketSales: 0,
          criminality: 0,
          blackMarketDaily: { date: '', items: [], purchased: [] }
        };
      }
      gameStore.state.classData.lastEggScanDate = Temporal.Now.instant().toString();

      saveWarehouseEggs();
      const name = (POKEMON_DB as Record<string, { name: string }>)[egg.species]?.name || 'Huevo';
      uiStore.notify(`¡Huevo de ${name} escaneado!`, '🔍');
      gameStore.scheduleSave();
    }
  }

  function checkDailyReset() {
    daycareMissionsStore.checkDailyReset();
  }

  function regenerateMissions(dateStr: string) {
    daycareMissionsStore.regenerateMissions(dateStr);
  }

  function refreshMissions() {
    daycareMissionsStore.refreshMissions();
  }

  function completeMission(missionIndex: number, pokemonUid: string) {
    daycareMissionsStore.completeMission(missionIndex, pokemonUid);
  }

  function reduceHatchTimers(activity: 'battle' | 'capture' | 'gym' | 'minigame') {
    const REDUCTIONS = { battle: 2, capture: 3, gym: 10, minigame: 1 };
    const reduction = REDUCTIONS[activity] || 0;
    if (reduction === 0) return;

    const eggs = gameStore.state.eggs || [];
    if (eggs.length === 0) return;

    let newlyReady = false;
    eggs.forEach((egg) => {
      if (!egg.ready && egg.steps > 0) {
        egg.steps = Math.max(0, egg.steps - reduction);
        if (egg.steps === 0) {
          egg.ready = true;
          newlyReady = true;
        }
      }
    });

    if (newlyReady) {
      uiStore.notify('¡Un Huevo Pokémon está listo para eclosionar!', '🐣');
    }
    gameStore.scheduleSave();
  }

  function updateEggIvs(eggId: string, ivs: Partial<PokemonIVs>) {
    const egg = warehouseEggs.value.find(e => e.id === eggId);
    if (egg) {
      egg.ivs = { ...egg.ivs, ...ivs } as PokemonIVs;
      saveWarehouseEggs();
      gameStore.scheduleSave();
    }
  }

  function deleteEgg(eggId: string) {
    const idx = warehouseEggs.value.findIndex(e => e.id === eggId);
    if (idx !== -1) {
      warehouseEggs.value.splice(idx, 1);
      saveWarehouseEggs();
      gameStore.scheduleSave();
    }
  }

  function cloneFossil(fossilName: string, extraQty: number) {
    return executeCloneFossil(fossilName, extraQty, warehouseEggs, saveWarehouseEggs);
  }

  let bgPoller: gsap.core.Tween | null = null;

  function initBackgroundPoller() {
    if (bgPoller) bgPoller.kill();

    const poll = async () => {
      if (isBreeding.value && nextEggTime.value) {
        const nowMs = Temporal.Now.instant().epochMilliseconds;
        if (nowMs >= nextEggTime.value) {
          await checkAndGenerateEgg();
        }
      }
      bgPoller = gsap.delayedCall(10, poll);
    };
    bgPoller = gsap.delayedCall(10, poll);
  }

  function cleanupBackgroundPoller() {
    if (bgPoller) {
      bgPoller.kill();
      bgPoller = null;
    }
  }

  return {
    slots,
    warehouseEggs,
    dailyMissions,
    fulfillableMissionsCount,
    missionRefreshes,
    loading,
    isBreeding,
    compatibility,
    nextEggTime,
    loadDaycare,
    deposit,
    withdraw,
    claimEgg,
    checkDailyReset,
    refreshMissions,
    regenerateMissions,
    completeMission,
    reduceHatchTimers,
    scanEgg,
    checkAndGenerateEgg,
    updateEggIvs,
    deleteEgg,
    cloneFossil,
    initBackgroundPoller,
    cleanupBackgroundPoller,
    saveWarehouseEggs,
    eggs: computed(() => warehouseEggs.value)
  };
});

import { useGameStore } from './game.ts';
import { useUIStore } from './ui.ts';
import { useInventoryStore } from './inventory.ts';
import { eggFactory } from '@/logic/breeding/eggFactory';
import { POKEMON_DB } from '@/data/pokemonDB';
import { calculateCloningCost, calculateCloningRerolls, calculateCloningShinyChance } from '@/logic/minigames/minigameMath';
import { generateRandomIVs } from '@/logic/pokemon/pokemonUtils';
import type { Pokemon, PokemonIVs } from '@/types/pokemon';
import type { Ref } from 'vue';
import type { DaycareEgg } from '@/types/breeding';

export function calculateBreedingCost(pA: Pokemon, pB: Pokemon): number {
  const countPerfect = (p: Pokemon) => {
    if (!p.ivs) return 0;
    return Object.values(p.ivs).filter(val => val === 30 || val === 31).length;
  };
  const totalPerfect = countPerfect(pA) + countPerfect(pB);
  if (totalPerfect <= 2) return 2000;
  if (totalPerfect <= 5) return 5000;
  if (totalPerfect <= 8) return 12000;
  return 25000;
}

export function executeCloneFossil(
  fossilId: string,
  extraQty: number,
  warehouseEggs: Ref<DaycareEgg[]>,
  saveWarehouseEggs: () => void
): boolean {
  const gameStore = useGameStore();
  const uiStore = useUIStore();
  const inventoryStore = useInventoryStore();

  if (warehouseEggs.value.length >= 30) {
    uiStore.notify('El almacén de huevos está lleno.', '❌');
    return false;
  }

  const count = gameStore.state.inventory[fossilId] || 0;
  const requiredFossils = 1 + extraQty;

  if (count < requiredFossils) {
    uiStore.notify(`No tienes suficientes fósiles. Requieres ${requiredFossils} y tienes ${count}.`, '❌');
    return false;
  }

  const totalCost = calculateCloningCost(extraQty);
  if (gameStore.state.money < totalCost) {
    uiStore.notify(`No tienes suficiente dinero. Requieres ₽${totalCost.toLocaleString()} y tienes ₽${gameStore.state.money.toLocaleString()}.`, '💰');
    return false;
  }

  const FOSSIL_SPECIES_MAP: Record<string, string> = {
    'dome_fossil': 'kabuto',
    'helix_fossil': 'omanyte',
    'old_amber': 'aerodactyl',
    'Fósil Domo': 'kabuto',
    'Fósil Hélix': 'omanyte',
    'Ámbar Viejo': 'aerodactyl'
  };
  const speciesId = FOSSIL_SPECIES_MAP[fossilId];
  if (!speciesId) {
    uiStore.notify('Fósil no reconocido para clonar.', '❌');
    return false;
  }

  // Consume resources first
  inventoryStore.removeItem(fossilId, requiredFossils);
  gameStore.state.money -= totalCost;

  // Roll success (5% per fossil consumed)
  const successChance = 0.05 * requiredFossils;
  const isSuccess = Math.random() < successChance;

  if (!isSuccess) {
    uiStore.notify('La extracción de ADN del fósil ha fallado.', '⚠️');
    gameStore.scheduleSave();
    return false;
  }

  const rolls = calculateCloningRerolls(extraQty);
  const rollIVs = (): PokemonIVs => generateRandomIVs();

  let bestIVs = rollIVs();
  let bestSum = bestIVs.hp + bestIVs.atk + bestIVs.def + bestIVs.spa + bestIVs.spd + bestIVs.spe;
  for (let i = 1; i < rolls; i++) {
    const currentIVs = rollIVs();
    const currentSum = currentIVs.hp + currentIVs.atk + currentIVs.def + currentIVs.spa + currentIVs.spd + currentIVs.spe;
    if (currentSum > bestSum) {
      bestIVs = currentIVs;
      bestSum = currentSum;
    }
  }

  const shinyChance = calculateCloningShinyChance(extraQty);
  const isShiny = Math.random() < shinyChance;

  const egg = eggFactory.createDaycareEgg({
    species: speciesId,
    ivs: bestIVs,
    nature: 'Serio',
    movesAtBirth: [],
    abilityIndex: 0,
    isShiny,
    cost: 0, // Paid upfront
    tint: 'rgba(139, 90, 43, 0.7)',
    isAncestral: true
  });

  warehouseEggs.value.push(egg);
  saveWarehouseEggs();

  uiStore.notify(`¡Clonación exitosa! Huevo Ancestral de ${POKEMON_DB[speciesId as keyof typeof POKEMON_DB]?.name} creado.`, '🥚');
  gameStore.scheduleSave();
  return true;
}

import { defineStore } from 'pinia'
import { computed } from 'vue'
import { gsap } from 'gsap'
import { useGameStore } from './game.ts'
import { getAssetUrl, ASSET_TYPES } from '@/logic/services/assetService'

export const useBuffsStore = defineStore('buffs', () => {
  const gameStore = useGameStore()

  let tickInterval: gsap.core.Tween | null = null

  function initTick() {
    if (tickInterval) tickInterval.kill()

    const tick = () => {
      // Pause timers if player is in an active battle
      if (gameStore.state.battle && !gameStore.state.battle.over) {
        tickInterval = gsap.delayedCall(1, tick)
        return
      }

      const s = gameStore.state
      let changed = false
      if (s.repelSecs > 0) { s.repelSecs--; changed = true }
      if (s.fishingRodSecs > 0) {
        s.fishingRodSecs--
        if (s.fishingRodSecs <= 0) s.fishingRodType = null
        changed = true
      }
      if (s.pickaxeSecs > 0) {
        s.pickaxeSecs--
        if (s.pickaxeSecs <= 0) s.pickaxeType = null
        changed = true
      }
      if (s.brushSecs > 0) {
        s.brushSecs--
        if (s.brushSecs <= 0) s.brushType = null
        changed = true
      }
      if (s.shinyBoostSecs > 0) { s.shinyBoostSecs--; changed = true }
      if (s.amuletCoinSecs > 0) { s.amuletCoinSecs--; changed = true }
      if (s.luckyEggSecs > 0) { s.luckyEggSecs--; changed = true }
      if (s.safariTicketSecs > 0) { s.safariTicketSecs--; changed = true }
      if (s.ceruleanTicketSecs > 0) { s.ceruleanTicketSecs--; changed = true }
      if (s.articunoTicketSecs > 0) { s.articunoTicketSecs--; changed = true }
      if (s.mewtwoTicketSecs > 0) { s.mewtwoTicketSecs--; changed = true }
      if (s.ivScannerSecs > 0) { s.ivScannerSecs--; changed = true }
      if (s.incenseSecs > 0) { s.incenseSecs--; changed = true }

      if (changed) {
        // Silent save every 30 seconds to persist active timers (ignoring 0 values)
        const hasRepelTick = s.repelSecs > 0 && s.repelSecs % 30 === 0
        const hasFishingTick = s.fishingRodSecs > 0 && s.fishingRodSecs % 30 === 0
        const hasPickaxeTick = s.pickaxeSecs > 0 && s.pickaxeSecs % 30 === 0
        const hasBrushTick = s.brushSecs > 0 && s.brushSecs % 30 === 0
        const hasShinyTick = s.shinyBoostSecs > 0 && s.shinyBoostSecs % 30 === 0
        const hasAmuletTick = s.amuletCoinSecs > 0 && s.amuletCoinSecs % 30 === 0
        const hasEggTick = s.luckyEggSecs > 0 && s.luckyEggSecs % 30 === 0
        const hasIncenseTick = s.incenseSecs > 0 && s.incenseSecs % 30 === 0
        const hasScannerTick = s.ivScannerSecs > 0 && s.ivScannerSecs % 30 === 0

        if (
          hasRepelTick || 
          hasFishingTick || 
          hasPickaxeTick || 
          hasBrushTick ||
          hasShinyTick || 
          hasAmuletTick || 
          hasEggTick || 
          hasIncenseTick || 
          hasScannerTick
        ) {
          gameStore.save(false)
        }
      }

      tickInterval = gsap.delayedCall(1, tick)
    }

    tickInterval = gsap.delayedCall(1, tick)
  }

  function addBuff(buffName: string, seconds: number, extraData: string | null = null) {
    const s = gameStore.state
    if (buffName === 'repel') s.repelSecs = (s.repelSecs || 0) + seconds
    else if (buffName === 'fishing-rod') {
      s.fishingRodSecs = seconds
      s.fishingRodType = (extraData as 'standard' | 'good' | 'super' | null) || 'standard'
    }
    else if (buffName === 'pickaxe') {
      s.pickaxeSecs = seconds
      s.pickaxeType = (extraData as 'standard' | 'good' | 'super' | null) || 'standard'
      s.brushSecs = 0
      s.brushType = null
    }
    else if (buffName === 'brush') {
      s.brushSecs = seconds
      s.brushType = (extraData as 'standard' | 'good' | 'super' | null) || 'standard'
      s.pickaxeSecs = 0
      s.pickaxeType = null
    }
    else if (buffName === 'shiny') s.shinyBoostSecs = (s.shinyBoostSecs || 0) + seconds
    else if (buffName === 'amulet') s.amuletCoinSecs = (s.amuletCoinSecs || 0) + seconds
    else if (buffName === 'lucky-egg') s.luckyEggSecs = (s.luckyEggSecs || 0) + seconds
    else if (buffName === 'safari') s.safariTicketSecs = (s.safariTicketSecs || 0) + seconds
    else if (buffName === 'cerulean') s.ceruleanTicketSecs = (s.ceruleanTicketSecs || 0) + seconds
    else if (buffName === 'articuno') s.articunoTicketSecs = (s.articunoTicketSecs || 0) + seconds
    else if (buffName === 'mewtwo') s.mewtwoTicketSecs = (s.mewtwoTicketSecs || 0) + seconds
    else if (buffName === 'iv-scanner') s.ivScannerSecs = seconds
    else if (buffName === 'incense') {
      s.incenseSecs = (s.incenseSecs || 0) + seconds
      if (extraData) s.incenseType = extraData
    }
    gameStore.save(false)
  }

  const activeBuffs = computed(() => {
    const s = gameStore.state
    const list = []
    if (s.repelSecs > 0) list.push({ id: 'repel', secs: s.repelSecs, name: 'Repelente', desc: 'Aleja Pokémon salvajes de nivel inferior al tuyo.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'repel') })
    if (s.fishingRodSecs > 0) {
      const type = s.fishingRodType || 'standard'
      const names: Record<string, string> = { standard: 'Caña de pescar', good: 'Caña Buena', super: 'Supercaña' }
      const budgets: Record<string, number> = { standard: 0, good: 500, super: 1000 }
      const fName = names[type] || 'Caña de pescar'
      const fBudget = budgets[type] || 0
      const descText = type === 'standard' 
        ? 'Sube mucho la pesca por 20 min. Ver % exacto en el mapa.'
        : `Sube la pesca y bonifica a los Pokémon raros (+${fBudget} pts).` + (type === 'super' ? ' Aumenta chance de Shiny x1.5.' : '')
      list.push({ 
        id: 'fishing-rod', 
        secs: s.fishingRodSecs, 
        name: `🎣 ${fName}`, 
        desc: descText, 
        icon: getAssetUrl(ASSET_TYPES.ITEM, `fishing_rod_${type === 'standard' ? '0' : (type === 'good' ? '1' : '2')}`),
        tier: type
      })
    }
    if (s.pickaxeSecs > 0) {
      const type = s.pickaxeType || 'standard'
      const names: Record<string, string> = { standard: 'Pico de excavación', good: 'Pico Bueno', super: 'Superpico' }
      const budgets: Record<string, number> = { standard: 0, good: 500, super: 1000 }
      const pName = names[type] || 'Pico de excavación'
      const pBudget = budgets[type] || 0
      const descText = type === 'standard'
        ? 'Sube la arqueología por 20 min. Ver % exacto en el mapa.'
        : `Sube la arqueología y bonifica minerales y gemas (+${pBudget} pts).`
      list.push({ 
        id: 'pickaxe', 
        secs: s.pickaxeSecs, 
        name: `⛏️ ${pName}`, 
        desc: descText, 
        icon: getAssetUrl(ASSET_TYPES.ITEM, `pickaxe_${type === 'standard' ? '0' : (type === 'good' ? '1' : '2')}`),
        tier: type
      })
    }
    if (s.brushSecs > 0) {
      const type = s.brushType || 'standard'
      const names: Record<string, string> = { standard: 'Pincel de excavación', good: 'Pincel Bueno', super: 'Superpincel' }
      const budgets: Record<string, number> = { standard: 0, good: 500, super: 1000 }
      const bName = names[type] || 'Pincel de excavación'
      const bBudget = budgets[type] || 0
      const descText = type === 'standard'
        ? 'Sube la arqueología por 20 min. Ver % exacto en el mapa.'
        : `Sube la arqueología y bonifica fósiles (+${bBudget} pts).`
      list.push({ 
        id: 'brush', 
        secs: s.brushSecs, 
        name: `🖌️ ${bName}`, 
        desc: descText, 
        icon: getAssetUrl(ASSET_TYPES.ITEM, `brush_${type === 'standard' ? '0' : (type === 'good' ? '1' : '2')}`),
        tier: type
      })
    }
    if (s.shinyBoostSecs > 0) list.push({ id: 'shiny', secs: s.shinyBoostSecs, name: '✨ Ticket Shiny', desc: 'Aumenta la probabilidad de encontrar Pokémon shiny.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon_ticket') })
    if (s.amuletCoinSecs > 0) list.push({ id: 'amulet', secs: s.amuletCoinSecs, name: '💰 Moneda Amuleto', desc: 'Duplica el dinero ganado en combate.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'amulet_coin') })
    if (s.luckyEggSecs > 0) list.push({ id: 'lucky-egg', secs: s.luckyEggSecs, name: '🥚 Huevo Suerte Pequeño', desc: 'Aumenta la EXP ganada en un 50% durante 30 minutos.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'lucky_egg') })
    if (s.safariTicketSecs > 0) list.push({ id: 'safari', secs: s.safariTicketSecs, name: '🎫 Ticket Safari', desc: 'Permite entrar a la Zona Safari.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon_ticket') })
    if (s.ceruleanTicketSecs > 0) list.push({ id: 'cerulean', secs: s.ceruleanTicketSecs, name: '🌀 Ticket Cueva Celeste', desc: 'Permite entrar a la Cueva Celeste.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon_ticket') })
    if (s.articunoTicketSecs > 0) list.push({ id: 'articuno', secs: s.articunoTicketSecs, name: '❄️ Ticket Articuno', desc: 'Permite entrar a las Islas Espuma.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon_ticket') })
    if (s.mewtwoTicketSecs > 0) list.push({ id: 'mewtwo', secs: s.mewtwoTicketSecs, name: '🧬 Ticket Mewtwo', desc: 'Permite entrar a la Cueva Celeste (Mewtwo).', icon: getAssetUrl(ASSET_TYPES.ITEM, 'eon_ticket') })
    if (s.ivScannerSecs > 0) list.push({ id: 'iv-scanner', secs: s.ivScannerSecs, name: '🔍 Escáner de IVs', desc: 'Muestra los IVs totales de Pokémon salvajes.', icon: getAssetUrl(ASSET_TYPES.ITEM, 'poke_radar') })

    if (s.incenseSecs > 0) {
      const types: Record<string, string> = { fire: 'Fuego', water: 'Agua', grass: 'Planta', normal: 'Normal', ghost: 'Fantasma', psychic: 'Psíquico' }
      const sprites: Record<string, string> = { fire: 'luck_incense', water: 'luck_incense', grass: 'luck_incense', normal: 'luck_incense', ghost: 'luck_incense', psychic: 'luck_incense' }
      const tName = types[s.incenseType || ''] || 'Desconocido'
      const tSprite = sprites[s.incenseType || ''] || 'luck_incense'
      list.push({ 
        id: 'incense', 
        secs: s.incenseSecs, 
        name: `💨 Incienso ${tName}`, 
        desc: `Atrae Pokémon de tipo ${tName}.`, 
        icon: getAssetUrl(ASSET_TYPES.ITEM, tSprite)
      })
    }

    return list
  })

  return { initTick, addBuff, activeBuffs }
})

// fallow-ignore-file circular-dependencies
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useAuthStore } from './auth.ts'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { useAudioStore } from './audio.ts'
import { logger } from '@/logic/utils/logger'
import { useChatCosmeticsStore } from './chatCosmetics.ts'
import { useChatPrivateStore, type ChatMessage } from './chatPrivate.ts'

import type { RealtimeChannel } from '@supabase/supabase-js'
import { validateChatMessage } from '@/logic/validation/schemas'

export const useChatStore = defineStore('chat', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()
  const uiStore = useUIStore()
  const audioStore = useAudioStore()

  const globalMessages = ref<ChatMessage[]>([])

  const cosmeticsStore = useChatCosmeticsStore()
  const profileCosmetics = computed(() => cosmeticsStore.profileCosmetics)
  const fetchMissingCosmetics = cosmeticsStore.fetchMissingCosmetics

  const privateStore = useChatPrivateStore()
  const privateChats = privateStore.privateChats
  const activeChatId = computed({
    get: () => privateStore.activeChatId,
    set: (val: string) => { privateStore.activeChatId = val }
  })
  const totalUnreadChats = computed(() => privateStore.totalUnreadChats)

  const initPrivateInbox = privateStore.initPrivateInbox
  const sendPrivateMessage = privateStore.sendPrivateMessage
  const openChat = privateStore.openChat
  const closeChat = privateStore.closeChat

  let globalChannel: RealtimeChannel | null = null
  let lastMessageSentTimestamp = 0

  async function loadGlobalHistory() {
    // If offline, ProxyQuery will handle the local SELECT

    const db = gameStore.db
    if (!db) return
    const { data, error } = await db
      .from('global_chat_messages')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(50) as { data: ChatMessage[] | null, error: unknown }

    if (!error && data) {
      globalMessages.value = [...data].reverse()
      await fetchMissingCosmetics()
    }
  }

  async function initGlobalChat() {
    if (globalChannel) return

    await loadGlobalHistory()

    const db = gameStore.db
    if (!db) return
    globalChannel = db.channel('global-chat-room')
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'global_chat_messages'
      }, ({ new: row }: { new: Record<string, unknown> }) => {
        const validation = validateChatMessage(row)
        if (!validation.success) {
          logger.error('Chat', 'Mensaje de chat entrante inválido omitido por esquema incorrecto', validation.issues)
          return
        }

        // Deduplicar por ID real de Supabase
        const alreadyById = globalMessages.value.some(m => m.id !== undefined && m.id === row.id)
        if (alreadyById) return

        // Deduplicar el push optimista propio: mismo user_id + mismo mensaje + timestamp muy cercano (<3s)
        const isOwnOptimistic = row.user_id === authStore.user?.id &&
          globalMessages.value.some(m => {
            if (m.user_id !== row.user_id || m.message !== row.message) return false
            // Si el ID del optimista es un número temporal (epochMs) y no un UUID, es el push optimista
            if (typeof m.id === 'number') {
              const diff = Math.abs((m.id as number) - (Temporal.Instant.from(row.created_at as string).epochMilliseconds))
              return diff < 3000
            }
            return false
          })

        if (isOwnOptimistic) {
          // Reemplazar el mensaje optimista con el definitivo (que tiene el ID real de Supabase)
          const idx = globalMessages.value.findIndex(m =>
            typeof m.id === 'number' &&
            m.user_id === row.user_id &&
            m.message === row.message
          )
          if (idx !== -1 && globalMessages.value[idx]) {
            // Preserve the numeric optimistic ID so Vue doesn't re-animate the element on key change
            const updatedRow = {
              ...row,
              id: globalMessages.value[idx].id
            } as unknown as ChatMessage
            globalMessages.value.splice(idx, 1, updatedRow)
          }
          return
        }

        globalMessages.value.push(row as unknown as ChatMessage)
        if (globalMessages.value.length > 50) globalMessages.value.shift()

        const senderId = row.user_id as string
        const cached = profileCosmetics.value[senderId]
        const needsUpdate = !cached || cached.username !== row.username || cached.player_class !== row.player_class || cached.trainer_level !== row.trainer_level
        fetchMissingCosmetics(needsUpdate ? [senderId] : [])

        // Sonido si el mensaje no es mío
        if (row.user_id !== authStore.user?.id) {
          audioStore.receivedMsg();
        }
      })
      .subscribe()
  }



  async function sendGlobalMessage(text: string) {
    if (!authStore.user || !text.trim() || !gameStore.db) return

    const now = Temporal.Now.instant().epochMilliseconds
    if (now - lastMessageSentTimestamp < 1000) {
      uiStore.notify('Debes esperar 1 segundo entre mensajes', '⏳')
      return
    }
    lastMessageSentTimestamp = now

    const payload = {
      user_id: authStore.user.id,
      username: gameStore.state.trainer || authStore.user.user_metadata?.username || 'Entrenador',
      message: text.slice(0, 180),
      player_class: gameStore.state.playerClass,
      trainer_level: gameStore.state.trainerLevel || 1
    }

    // Immediate optimistic push before the async insert to prevent race conditions with Realtime
    const optimisticId = Temporal.Now.instant().epochMilliseconds
    const optimisticRow = {
      id: optimisticId,
      ...payload,
      created_at: Temporal.Now.instant().toString()
    }
    globalMessages.value.push(optimisticRow as unknown as ChatMessage)
    if (globalMessages.value.length > 50) globalMessages.value.shift()
    fetchMissingCosmetics(authStore.user?.id ? [authStore.user.id] : [])

    audioStore.sentMsg() // Sound on immediate send

    const { error } = await gameStore.db.from('global_chat_messages').insert(payload)
    if (error) {
      logger.error('Chat', `Global message error: ${(error as Error).message}`)
      // If there is an error, remove the optimistic message from list
      const idx = globalMessages.value.findIndex(m => m.id === optimisticId)
      if (idx !== -1) {
        globalMessages.value.splice(idx, 1)
      }
    }
  }



  return {
    globalMessages,
    privateChats,
    activeChatId,
    profileCosmetics,
    totalUnreadChats,
    initGlobalChat,
    initPrivateInbox,
    sendGlobalMessage,
    sendPrivateMessage,
    openChat,
    closeChat,
    fetchMissingCosmetics
  }
})

import { defineStore } from 'pinia'
import { ref, watch } from 'vue'
import { useAuthStore } from './auth.ts'
import { useGameStore } from './game.ts'
import { useChatStore } from './chat.ts'
import { logger } from '@/logic/utils/logger'

export interface ProfileCacheItem {
  username?: string;
  player_class?: string;
  trainer_level?: number;
  avatar_style?: string;
  nick_style?: string;
  gender?: string;
}

export const useChatCosmeticsStore = defineStore('chatCosmetics', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()

  const profileCosmetics = ref<Record<string, ProfileCacheItem>>({})

  // Sychronize trainer's own cosmetics reactively
  watch(
    () => [
      gameStore.state.trainer,
      gameStore.state.playerClass,
      gameStore.state.trainerLevel,
      gameStore.state.avatar_style,
      gameStore.state.nick_style,
      gameStore.state.gender,
      authStore.user?.id
    ],
    () => {
      if (authStore.user?.id) {
        profileCosmetics.value[authStore.user.id] = {
          username: gameStore.state.trainer || authStore.user.user_metadata?.username || 'Entrenador',
          player_class: gameStore.state.playerClass || 'entrenador',
          trainer_level: gameStore.state.trainerLevel || 1,
          avatar_style: gameStore.state.avatar_style || '',
          nick_style: gameStore.state.nick_style || '',
          gender: gameStore.state.gender || 'h'
        }
      }
    },
    { immediate: true, deep: true }
  )

  async function fetchMissingCosmetics(forceIds: string[] = []) {
    const db = gameStore.db
    if (!db) return

    // Populate own cosmetics
    if (authStore.user?.id) {
      profileCosmetics.value[authStore.user.id] = {
        username: gameStore.state.trainer || authStore.user.user_metadata?.username || 'Entrenador',
        player_class: gameStore.state.playerClass || 'entrenador',
        trainer_level: gameStore.state.trainerLevel || 1,
        avatar_style: gameStore.state.avatar_style || '',
        nick_style: gameStore.state.nick_style || '',
        gender: gameStore.state.gender || 'h'
      }
    }

    const chatStore = useChatStore()

    // Collect all user IDs: global chat + private chat participants
    const uniqueUserIds = new Set<string>()
    chatStore.globalMessages.forEach(m => { if (m.user_id) uniqueUserIds.add(m.user_id) })
    Object.keys(chatStore.privateChats).forEach(friendId => {
      uniqueUserIds.add(friendId)
      chatStore.privateChats[friendId]?.messages.forEach(m => { if (m.senderId) uniqueUserIds.add(m.senderId) })
    })
    forceIds.forEach(id => { if (id) uniqueUserIds.add(id) })

    const missingIds = [...uniqueUserIds].filter(id => id && !profileCosmetics.value[id])
    if (missingIds.length === 0) return

    try {
      const [profRes, saveRes] = await Promise.all([
        db.from('profiles').select('id, username, player_class, trainer_level, avatar_style, nick_style, gender').in('id', missingIds),
        db.from('game_saves').select('user_id, save_data').in('user_id', missingIds)
      ]) as [
        { data: { id: string; username?: string | null; player_class?: string | null; trainer_level?: number | null; avatar_style?: string | null; nick_style?: string | null; gender?: string | null }[] | null, error: unknown },
        { data: { user_id: string; save_data?: unknown }[] | null, error: unknown }
      ]

      if (!profRes.error) {
        const profilesList = profRes.data || []
        const savesList = saveRes.data || []

        missingIds.forEach(id => {
          const p = profilesList.find(prof => prof.id === id)
          const saveRow = savesList.find(s => s.user_id === id)
          const save = saveRow?.save_data ? (typeof saveRow.save_data === 'string' ? JSON.parse(saveRow.save_data) : saveRow.save_data) as Record<string, unknown> : {}

          const fallbackName = id.startsWith('local_') ? id.replace('local_', '') : 'Entrenador'
          const capitalizedFallback = fallbackName.charAt(0).toUpperCase() + fallbackName.slice(1)
          const username = (save.trainer as string) || p?.username || capitalizedFallback

          profileCosmetics.value[id] = {
            username,
            player_class: (save.playerClass as string) || p?.player_class || 'entrenador',
            trainer_level: (save.trainerLevel as number) || p?.trainer_level || 1,
            avatar_style: (save.avatar_style as string) || p?.avatar_style || '',
            nick_style: (save.nick_style as string) || p?.nick_style || '',
            gender: (save.gender as string) || p?.gender || 'h'
          }
        })
      }
    } catch (err) {
      logger.error('Chat', `Error fetching profile cosmetics: ${(err as Error).message}`)
    }
  }

  return {
    profileCosmetics,
    fetchMissingCosmetics
  }
})

import { defineStore } from 'pinia'
import { ref, reactive, watch, computed } from 'vue'
import { gsap } from 'gsap'
import { useAuthStore } from './auth.ts'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { useAudioStore } from './audio.ts'
import { useSocialStore } from './social.ts'
import { logger } from '@/logic/utils/logger'
import type { RealtimeChannel } from '@supabase/supabase-js'

export interface ChatMessage {
  id?: string | number;
  user_id?: string;
  senderId?: string;
  senderName?: string;
  username?: string;
  message?: string;
  text?: string;
  timestamp?: string | number;
  created_at?: string;
  player_class?: string;
  trainer_level?: number;
  gender?: string;
}

export interface PrivateChat {
  username: string;
  messages: ChatMessage[];
  unreadCount: number;
  isCollapsed: boolean;
  lastInteraction: number;
}

export const useChatPrivateStore = defineStore('chatPrivate', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()
  const uiStore = useUIStore()
  const audioStore = useAudioStore()

  const activeChatId = ref('global') // 'global' or userId
  const privateChats = reactive<Record<string, PrivateChat>>({})

  let inboxChannel: RealtimeChannel | null = null
  let lastMessageSentTimestamp = 0
  const outboxChannels: Record<string, RealtimeChannel> = {}
  let isInitialized = false

  const getSanitizedChats = (chats: Record<string, PrivateChat> | undefined, forceCollapse = false): Record<string, PrivateChat> => {
    const sanitized: Record<string, PrivateChat> = {}
    if (chats) {
      for (const [id, chat] of Object.entries(chats)) {
        if (authStore.user?.id && id === authStore.user.id) continue

        const isLocalKey = id === 'local_user' || id === 'eq.local_user' || id.startsWith('local_')
        if (authStore.sessionMode === 'online' && isLocalKey) {
          logger.info('Chat', `Filtrando chat local contaminado en modo online: ${id}`)
          continue
        }

        const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
        if (authStore.sessionMode === 'offline' && uuidRegex.test(id)) {
          logger.info('Chat', `Filtrando chat remoto en modo offline: ${id}`)
          continue
        }

        const currentCollapsed = isInitialized && privateChats[id] ? privateChats[id].isCollapsed : true

        sanitized[id] = {
          ...chat,
          isCollapsed: forceCollapse ? true : currentCollapsed
        }
      }
    }
    return sanitized
  }

  // Initialize existing chats
  if (gameStore.state.chats) {
    Object.assign(privateChats, getSanitizedChats(gameStore.state.chats as Record<string, PrivateChat>, true))
  }
  isInitialized = true

  // Sync chats with game state updates
  watch(() => gameStore.state.chats, (newChats) => {
    if (newChats) {
      const sanitized = getSanitizedChats(newChats as Record<string, PrivateChat>, false)
      for (const key in privateChats) {
        if (!sanitized[key]) {
          delete privateChats[key]
        }
      }
      Object.assign(privateChats, sanitized)
    } else {
      for (const key in privateChats) {
        delete privateChats[key]
      }
    }
  }, { deep: true })

  function parseInstantEpoch(val: string | number | undefined): number {
    if (!val) return 0
    try {
      if (typeof val === 'number') return val
      let isoStr = val.trim()
      const num = Number(isoStr)
      if (!isNaN(num) && isoStr.length > 8) return num
      if (isoStr.includes(' ') && !isoStr.includes('T')) {
        isoStr = isoStr.replace(' ', 'T')
      }
      if (!isoStr.endsWith('Z') && !isoStr.includes('+') && !isoStr.includes('-')) {
        isoStr += 'Z'
      }
      return Temporal.Instant.from(isoStr).epochMilliseconds
    } catch {
      return 0
    }
  }

  async function loadPrivateHistory() {
    if (!authStore.user || !gameStore.db) return
    const myId = authStore.user.id

    const { data, error } = await gameStore.db.from('chat_messages')
      .select('*')
      .or(`type.eq.private:${myId},senderId.eq.${myId}`)
      .order('created_at', { ascending: true })

    if (error) {
      logger.error('Chat', `Private history load error: ${(error as Error).message}`)
      return
    }

    if (data && Array.isArray(data)) {
      const lastSaveTime = ((gameStore.state as Record<string, unknown>)._last_updated as number) || 0
      const initialLastInteractions: Record<string, number> = {}

      data.forEach((row: Record<string, unknown>) => {
        const senderId = (row.senderId as string) || (row.senderid as string) || ''
        const typeStr = (row.type as string) || ''
        const isIncoming = senderId !== myId
        const friendId = isIncoming ? senderId : typeStr.replace('private:', '')
        if (!friendId) return

        if (privateChats[friendId] && initialLastInteractions[friendId] === undefined) {
          initialLastInteractions[friendId] = privateChats[friendId].lastInteraction || 0
        }
      })

      data.forEach((row: Record<string, unknown>) => {
        const senderId = (row.senderId as string) || (row.senderid as string) || ''
        const senderName = (row.senderName as string) || (row.sendername as string) || 'Entrenador'
        const message = (row.message as string) || ''
        const typeStr = (row.type as string) || ''
        const createdAt = (row.created_at as string) || Temporal.Now.instant().toString()

        const isIncoming = senderId !== myId
        const friendId = isIncoming ? senderId : typeStr.replace('private:', '')
        if (!friendId) return

        const chatKey = friendId

        if (!privateChats[chatKey]) {
          privateChats[chatKey] = {
            username: isIncoming ? senderName : 'Entrenador',
            messages: [],
            unreadCount: 0,
            isCollapsed: true,
            lastInteraction: 0
          }
          initialLastInteractions[chatKey] = 0
        }
        const chat = privateChats[chatKey]
        if (chat) {
          const msgObj: ChatMessage = {
            senderId,
            senderName,
            text: message,
            timestamp: createdAt
          }

          const msgEpoch = parseInstantEpoch(createdAt)
          const isDup = chat.messages.some((m: ChatMessage) => {
            return m.text === message && Math.abs(parseInstantEpoch(m.timestamp) - msgEpoch) < 2000
          })

          if (!isDup) {
            chat.messages.push(msgObj)
            if (chat.messages.length > 25) {
              chat.messages.shift()
            }
            chat.lastInteraction = msgEpoch

            const initialLast = initialLastInteractions[chatKey] || 0
            const baselineTime = initialLast > 0 ? initialLast : lastSaveTime

            if (isIncoming && chat.isCollapsed && baselineTime > 0 && msgEpoch > baselineTime) {
              chat.unreadCount++
            }
          }
        }
      })
      gameStore.state.chats = { ...privateChats }
      pruneOldMessages()
    }
  }

  async function pruneOldMessages() {
    if (!authStore.user || !gameStore.db) return
    const myId = authStore.user.id

    try {
      const { data } = await gameStore.db.from('chat_messages')
        .select('created_at')
        .eq('senderId', myId)
        .order('created_at', { ascending: false })
        .limit(1000)

      if (data && Array.isArray(data) && data.length === 1000) {
        const thresholdDate = ((data as unknown[])[999] as Record<string, unknown>)?.created_at as string
        if (thresholdDate) {
          await gameStore.db.from('chat_messages')
            .delete()
            .eq('senderId', myId)
            .lt('created_at', thresholdDate)
        }
      }
    } catch (err) {
      logger.warn('Chat', `Pruning error: ${(err as Error).message}`)
    }
  }

  async function initPrivateInbox() {
    if (!authStore.user || inboxChannel) return

    const db = gameStore.db
    if (!db) return

    await loadPrivateHistory()

    inboxChannel = db.channel(`chat-inbox-${authStore.user.id}`)
    inboxChannel.on('broadcast', { event: 'private_message' }, ({ payload }: { payload: ChatMessage }) => {
      handleIncomingPrivate(payload)
      audioStore.receivedMsg()
    })
    .subscribe()
  }

  watch(() => authStore.user, (user) => {
    if (user) {
      gsap.delayedCall(0.5, () => {
        if (inboxChannel) {
          inboxChannel.unsubscribe()
          inboxChannel = null
        }
        initPrivateInbox()
      })
    } else {
      if (inboxChannel) {
        inboxChannel.unsubscribe()
        inboxChannel = null
      }
    }
  }, { immediate: true })

  function handleIncomingPrivate(payload: ChatMessage, targetChatId?: string) {
    const chatKey = targetChatId || (payload.senderId as string)

    if (!privateChats[chatKey]) {
      privateChats[chatKey] = {
        username: payload.senderName || 'Entrenador',
        messages: [],
        unreadCount: 0,
        isCollapsed: true,
        lastInteraction: Temporal.Now.instant().epochMilliseconds
      }
    }

    const chat = privateChats[chatKey]
    if (!chat) return

    const isDup = chat.messages.some((m: ChatMessage) => m.timestamp === payload.timestamp && m.text === payload.text)
    if (isDup) return

    chat.messages.push(payload as ChatMessage)
    chat.lastInteraction = Temporal.Now.instant().epochMilliseconds

    if (chat.messages.length > 25) chat.messages.shift()

    if (activeChatId.value !== chatKey && payload.senderId !== authStore.user?.id) {
      chat.unreadCount++
      uiStore.notify(`Mensaje de ${chat.username}`, '💬')
    }

    gameStore.state.chats = { ...privateChats }
  }

  async function sendPrivateMessage(friendId: string, text: string) {
    if (!authStore.user || !text.trim() || !privateChats[friendId] || !gameStore.db) return

    const now = Temporal.Now.instant().epochMilliseconds
    if (now - lastMessageSentTimestamp < 1000) {
      uiStore.notify('Debes esperar 1 segundo entre mensajes', '⏳')
      return
    }
    lastMessageSentTimestamp = now

    const payload = {
      senderId: authStore.user.id,
      senderName: gameStore.state.trainer || authStore.user.user_metadata?.username || 'Entrenador',
      text: text.slice(0, 250),
      timestamp: Temporal.Now.instant().toString()
    }

    const db = gameStore.db
    if (!outboxChannels[friendId]) {
      const chan = db.channel(`chat-inbox-${friendId}`)
      outboxChannels[friendId] = chan
      chan.subscribe((status: string) => {
        if (status === 'SUBSCRIBED' && outboxChannels[friendId]) {
          outboxChannels[friendId]?.send({ type: 'broadcast', event: 'private_message', payload })
        }
      })
    } else {
      outboxChannels[friendId]?.send({ type: 'broadcast', event: 'private_message', payload })
    }

    handleIncomingPrivate({ ...payload, senderId: authStore.user.id }, friendId)
    audioStore.sentMsg()

    const dbPayload = {
      senderId: authStore.user.id,
      senderName: payload.senderName,
      message: payload.text,
      type: `private:${friendId}`,
      created_at: payload.timestamp
    }
    const { error } = await db.from('chat_messages').insert(dbPayload)
    if (error) {
      logger.error('Chat', `Private message db error: ${(error as Error).message}`)
    }
  }

  function openChat(friendId: string, username: string) {
    const existingChat = privateChats[friendId]
    if (existingChat && activeChatId.value === friendId && !existingChat.isCollapsed) {
      return
    }

    if (!privateChats[friendId]) {
      privateChats[friendId] = {
        username: username || 'Entrenador',
        messages: [],
        unreadCount: 0,
        isCollapsed: false,
        lastInteraction: Temporal.Now.instant().epochMilliseconds
      }
    }
    const chat = privateChats[friendId]
    if (chat) {
      chat.unreadCount = 0
      chat.isCollapsed = false
    }
    activeChatId.value = friendId
    gameStore.state.chats = { ...privateChats }
    gameStore.scheduleSave()
    loadPrivateHistory()
  }

  function closeChat(friendId: string) {
    if (privateChats[friendId]) {
      privateChats[friendId].isCollapsed = true
      gameStore.state.chats = { ...privateChats }
    }
    if (activeChatId.value === friendId) {
      activeChatId.value = 'global'
    }
  }

  const totalUnreadChats = computed(() => {
    const socialStore = useSocialStore()
    const activeFriendIds = new Set((socialStore.friends || []).map(f => f.id))
    return Object.entries(privateChats).reduce((sum, [friendId, chat]) => {
      if (!activeFriendIds.has(friendId)) return sum
      return sum + chat.unreadCount
    }, 0)
  })

  return {
    activeChatId,
    privateChats,
    totalUnreadChats,
    initPrivateInbox,
    sendPrivateMessage,
    openChat,
    closeChat
  }
})

import { defineStore } from 'pinia'
import { reactive } from 'vue'
import { POKEMON_FEET_DATABASE } from '@/data/pokemonFeetDatabase'

/**
 * Combat Shadow Store
 * Centralized management for shadows in the virtual battle arena.
 */
interface FeetPoints {
  feetY: number;
  feetX: number;
}

interface CombatShadow {
  id: string;
  side: string;
  entityX: number;
  entityY: number;
  entitySize: number;
  width: string;
  isFlying: boolean;
  feetY: number;
  feetX: number;
  spriteUrl: string;
  visible: boolean;
  force?: boolean;
}

export const useCombatShadowStore = defineStore('combatShadows', () => {
  const activeShadows = reactive(new Map<string, CombatShadow>())

  function getCleanDatabaseKey(url: string): string {
    if (!url) return ''
    let key = url
    const base = import.meta.env.BASE_URL || '/'
    if (base !== '/' && url.startsWith(base)) {
      key = url.slice(base.length - 1)
    }
    try {
      return decodeURIComponent(key)
    } catch (_e) {
      return key
    }
  }

  async function detectFeetPoints(url: string): Promise<FeetPoints> {
    if (!url) {
      throw new Error(`[PokemonFeetDatabase] Cannot detect feet points: url is empty or undefined.`);
    }
    const key = getCleanDatabaseKey(url)
    const points = POKEMON_FEET_DATABASE[key]
    if (!points) {
      throw new Error(`[PokemonFeetDatabase] Sprite key "${key}" not found in POKEMON_FEET_DATABASE. Did you forget to compile assets? Run "npm run assets:convert".`)
    }
    return points
  }

  async function requestShadow(id: string, options: Partial<CombatShadow> = {}) {
    const existing = activeShadows.get(id)

    // Bloqueo de propiedad: Si ya tiene una sombra activa para este sprite, no le damos otra (Evitar parpadeos)
    if (existing && options.spriteUrl === existing.spriteUrl && !options.force) {
      // Solo actualizamos visibilidad si cambió, sin disparar todo el proceso de re-creación
      if (options.visible !== undefined && existing.visible !== options.visible) {
        existing.visible = options.visible
      }
      return Promise.resolve(existing)
    }

    // Obtener valores de la base de datos estática para evitar el salto inicial (Sync)
    const dbKey = getCleanDatabaseKey(options.spriteUrl || '')
    const cachedPoints = dbKey ? POKEMON_FEET_DATABASE[dbKey] : null

    if (options.spriteUrl && !cachedPoints) {
      throw new Error(`[PokemonFeetDatabase] Sprite key "${dbKey}" not found in POKEMON_FEET_DATABASE. Did you forget to compile assets? Run "npm run assets:convert".`)
    }

    let feetY = options.feetY || (cachedPoints?.feetY ?? (existing?.feetY ?? 0.9))
    // Si es volador, ignoramos el valor detectado y forzamos el suelo
    if (options.isFlying) feetY = 0.9

    const feetX = options.feetX || (cachedPoints?.feetX ?? (existing?.feetX ?? 0.5))
    const visible = options.visible !== undefined ? options.visible : true

    // Guardamos/actualizamos la sombra inmediatamente para que sea visible
    const newShadow = {
      id,
      side: options.side || 'generic',
      entityX: options.entityX ?? (existing?.entityX ?? 0),
      entityY: options.entityY ?? (existing?.entityY ?? 0),
      entitySize: options.entitySize ?? (existing?.entitySize ?? 300),
      width: options.width || (existing?.width ?? '70%'),
      isFlying: options.isFlying || false,
      feetY,
      feetX,
      spriteUrl: options.spriteUrl || existing?.spriteUrl || '',
      visible
    } as CombatShadow

    activeShadows.set(id, newShadow)

    return Promise.resolve(newShadow)
  }

  function showShadow(id: string) {
    if (!id) return
    const shadow = activeShadows.get(id)
    if (shadow) {
      shadow.visible = true
    }
  }

  function hideShadow(id: string) {
    if (!id) return
    const shadow = activeShadows.get(id)
    if (shadow) {
      shadow.visible = false
    }
  }

  function removeShadow(id: string) {
    activeShadows.delete(id)
  }

  function clearAll() {
    activeShadows.clear()
  }

  return {
    activeShadows,
    detectFeetPoints,
    requestShadow,
    showShadow,
    hideShadow,
    removeShadow,
    clearAll
  }
})

import { defineStore } from 'pinia';
import { computed } from 'vue';
import { useGameStore } from './game.ts';
import { useUIStore } from './ui.ts';
import { generateMission, validateMissionPokemon } from '@/logic/breeding/missionEngine';
import type { DaycareMission } from '@/types/breeding';
import type { Pokemon } from '@/types/pokemon';

export const useDaycareMissionsStore = defineStore('daycareMissions', () => {
  const gameStore = useGameStore();
  const uiStore = useUIStore();

  const dailyMissions = computed<DaycareMission[]>({
    get: () => gameStore.state.daycare_missions || [],
    set: (val) => { gameStore.state.daycare_missions = val }
  });

  const missionRefreshes = computed<number>({
    get: () => gameStore.state.daycare_mission_refreshes || 0,
    set: (val) => { gameStore.state.daycare_mission_refreshes = val }
  });

  const fulfillableMissionsCount = computed(() => {
    const missions = dailyMissions.value.filter(m => !m.completed);
    if (missions.length === 0) return 0;

    const team = gameStore.state.team || [];
    const box = gameStore.state.box || [];
    const allPokes = [...team, ...box].filter((p): p is Pokemon => p !== null);

    return missions.filter(mission => {
      const targetId = mission.targetId;
      return allPokes.some(p => {
        if (p.onMission || p.inDaycare || p.onDefense) return false;
        if (p.id !== targetId) return false;

        const req = mission.requirement || { type: 'level', minLevel: 0 };
        if (req.type === 'level') return p.level >= (req.minLevel || 0);
        if (req.type === 'iv_total') {
          const total = (p.ivs?.hp || 0) + (p.ivs?.atk || 0) + (p.ivs?.def || 0) + (p.ivs?.spa || 0) + (p.ivs?.spd || 0) + (p.ivs?.spe || 0);
          return total >= (req.minIvTotal || 0);
        }
        if (req.type === 'nature') return p.nature === req.nature;
        if (req.type === 'iv_31') return p.ivs?.[req.stat31 as keyof Pokemon['ivs']] === 31;
        return true;
      });
    }).length;
  });

  function checkDailyReset() {
    const today = Temporal.Now.plainDateISO().toString();
    const missions = dailyMissions.value;
    const lastDate = missions.length > 0 && missions[0] ? missions[0].date : '';

    if (lastDate !== today) {
      regenerateMissions(today);
      missionRefreshes.value = 3;
    }
  }

  function regenerateMissions(dateStr: string) {
    const level = gameStore.state.trainerLevel || 1;
    const m1 = generateMission(level, dateStr) as DaycareMission;
    let m2 = generateMission(level, dateStr) as DaycareMission;

    while (m2.targetId === m1.targetId) {
      m2 = generateMission(level, dateStr) as DaycareMission;
    }

    dailyMissions.value = [m1, m2];
    gameStore.scheduleSave();
  }

  function refreshMissions() {
    if (missionRefreshes.value <= 0) {
      uiStore.notify('No te quedan refrescos por hoy.', '⚠️');
      return;
    }

    missionRefreshes.value--;
    const today = Temporal.Now.instant().toString().split('T')[0] as string;
    regenerateMissions(today);
    uiStore.notify('Misiones actualizadas.', '🔄');
  }

  function completeMission(missionIndex: number, pokemonUid: string) {
    const mission = dailyMissions.value[missionIndex];
    if (!mission || mission.completed) return;

    const team = gameStore.state.team || [];
    const box = gameStore.state.box || [];
    const all = [...team, ...box];
    const pokemon = all.find(p => p.uid === pokemonUid);

    if (!pokemon) return;
    if (!validateMissionPokemon(pokemon, mission)) {
      uiStore.notify('Este Pokémon no cumple los requisitos.', '❌');
      return;
    }

    if (team.length <= 1 && team.some((p) => p.uid === pokemonUid)) {
      uiStore.notify('No puedes entregar tu único Pokémon.', '⚠️');
      return;
    }

    if (!gameStore.removePokemon(pokemonUid)) {
      uiStore.notify('Error al procesar la entrega.', '❌');
      return;
    }

    mission.completed = true;
    const inv = gameStore.state.inventory as Record<string, number>;
    inv[mission.reward.id] = (inv[mission.reward.id] || 0) + mission.reward.qty;

    uiStore.notify(`¡Misión completada! Recibiste ${mission.reward.name} x${mission.reward.qty}`, mission.reward.icon);
    gameStore.scheduleSave();
  }

  return {
    dailyMissions,
    missionRefreshes,
    fulfillableMissionsCount,
    checkDailyReset,
    regenerateMissions,
    refreshMissions,
    completeMission
  };
});

