  debug.register({
    id: 'mission-clear',
    label: 'LIMPIAR MISIONES',
    command: 'clearMissions',
    category: 'missions',
    action: () => {
      game.state.daycare_missions = []
      ui.notify('Misiones de Guardería eliminadas', '🗑️')
      game.saveGame(false)
