// fallow-ignore-file circular-dependencies
import { defineStore } from 'pinia'
import { reactive, ref, computed, watch, type Ref } from 'vue'
import { logger } from '@/logic/utils/logger'
import { useAuthStore } from './auth.ts'
import { supabase } from '@/logic/db/supabase'
import { INITIAL_STATE } from './gameInitialState.ts'
import type { GameState } from '@/types/game'


// Actions Modules
import { useSaveActions } from './game/actions/saveActions.ts'
import { usePokemonActions } from './game/actions/pokemonActions.ts'
import { useTrainerActions } from './game/actions/trainerActions.ts'
import { useBreedingActions } from './game/actions/breedingActions.ts'
import { useTeamActions } from './game/actions/teamActions.ts'

import { DBRouter } from '@/logic/db/dbRouter'

export const useGameStore = defineStore('game', () => {
  const authStore = useAuthStore()
  const state = reactive<GameState>(JSON.parse(JSON.stringify(INITIAL_STATE)))

  const db = ref<DBRouter>(supabase)
  const isDataLoaded = ref(false)
  const isEngineReady = ref(false)
  const isSaveLocked = ref(false)
  const isReady = computed(() => isDataLoaded.value && isEngineReady.value)
  const isSandboxActive = ref(false)
  const realStateBackup = ref<GameState | null>(null)

  function updateState(newData: Partial<GameState>) {
    if (newData.team && newData.team.length > 0) newData.starterChosen = true
    Object.assign(state, newData)
    // Standard state updates
    logger.debug('STORE', 'Game state updated.')
  }

  function resetToInitial() {
    Object.keys(state).forEach(key => {
      delete (state as Record<string, unknown>)[key]
    })
    Object.assign(state, JSON.parse(JSON.stringify(INITIAL_STATE)))
    isDataLoaded.value = false
  }

  // --- ACTIONS INITIALIZATION ---

  // 1. Save Actions (Basics needed for others)
  const { loadGame: rawLoad, save, scheduleSave, claimAsset, fetchClaimQueue } = useSaveActions(
    state, 
    authStore, 
    db as Ref<DBRouter>, 
    updateState, 
    isSandboxActive
  )

  // 2. Team Actions (Special teams management)
  const { autoFillPvpTeam, swapPvpSlot, reorderPvpTeam, autoFillWarTeam, swapWarSlot, reorderWarTeam } = useTeamActions(state, scheduleSave)

  // 3. Pokemon Actions
  const { registerPokedex, chooseStarter, addPokemon, removePokemon, reorderTeam, reorderMoves, sendToBox, togglePokeTag, sanitizeAll } = usePokemonActions(state, scheduleSave, autoFillPvpTeam, autoFillWarTeam)

  // 4. Trainer Actions
  const { getTrainerRank, addTrainerExp, checkLevelUp, getMaxObeyLevel } = useTrainerActions(state, scheduleSave)

  // 5. Breeding Actions
  const { hatchEggs, executeHatch } = useBreedingActions(state, scheduleSave, addPokemon)

  // Wrapper for LoadGame to manage local state
  async function loadGame(): Promise<void> {
    const res = await rawLoad()

    if (res.success) {
      // Sync time ONLY after successful load/auth
      const { syncServerTime } = await import('@/logic/utils/timeUtils')
      await syncServerTime()

      isDataLoaded.value = true
      isEngineReady.value = true

      // Sanitize all pokemon to update types/metadata from DB
      sanitizeAll()

      // Clear expired routes
      checkRouteExpirations()


      // Initialize Session Hub for multi-tab/device locking
      if (authStore.user) {
        const { initSessionHub } = await import('@/logic/auth/sessionHub')
        initSessionHub(authStore.user.id)

        window.addEventListener('pv-save-lock', () => {
          isSaveLocked.value = true
        })

        window.addEventListener('pv-save-unlock', () => {
          isSaveLocked.value = false
        })

        // Cargar datos sociales y notificar solicitudes pendientes al iniciar sesión
        import('./social.ts').then(async ({ useSocialStore }) => {
          const socialStore = useSocialStore()
          await socialStore.loadSocialData()
          if (socialStore.pendingRequests.length > 0) {
            const { useUIStore } = await import('./ui.ts')
            const uiStore = useUIStore()
            uiStore.notify(`¡Tenés ${socialStore.pendingRequests.length} solicitud(es) de amistad pendiente(s)!`, '🤝')
          }
        }).catch(err => {
          logger.error('Social', `Error al cargar notificaciones iniciales: ${(err as Error).message}`)
        })
      }
    }
  }

  function checkRouteExpirations(): void {
    if (!state.classData) return
    const now = Temporal.Now.instant().epochMilliseconds

    let changed = false

    // 1. Rocket extorted route expiration (24 hours)
    if (state.classData.extortedRouteId && state.classData.extortedRouteTimestamp) {
      const timestamp = Number(state.classData.extortedRouteTimestamp || 0)
      if ((now - timestamp) > 24 * 3600 * 1000) {
        logger.info('CLASS', `Extortion of route ${state.classData.extortedRouteId} expired. Clearing.`)
        state.classData.extortedRouteId = null
        state.classData.extortedRouteTimestamp = null
        changed = true
      }
    }

    // 2. Trainer official route active expiration (30 minutes)
    if (state.classData.officialRouteId && state.classData.officialRouteTimestamp) {
      const timestamp = Number(state.classData.officialRouteTimestamp || 0)
      if ((now - timestamp) > 30 * 60 * 1000) {
        logger.info('CLASS', `Patrol on official route ${state.classData.officialRouteId} finished. Clearing active status.`)
        state.classData.officialRouteId = null
        changed = true
      }
    }

    if (changed) {
      scheduleSave()
    }
  }

  async function reclaimControl() {
    const { reclaimControl: rawReclaim } = await import('@/logic/auth/sessionHub')
    await rawReclaim()
    isSaveLocked.value = false
  }

  function enterSandboxMode() {
    if (isSandboxActive.value) return
    realStateBackup.value = JSON.parse(JSON.stringify(state))

    // Limpiar el estado actual y cargar el guardado del sandbox si existe
    Object.keys(state).forEach(key => {
      delete (state as Record<string, unknown>)[key]
    })

    let initialSandbox = JSON.parse(JSON.stringify(INITIAL_STATE))
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('pvs_sandbox_save')
      if (saved) {
        try {
          initialSandbox = JSON.parse(saved)
        } catch (e) {
          logger.error('SANDBOX', 'Error parsing sandbox save, using initial state:', e)
        }
      }
    }

    Object.assign(state, initialSandbox)
    isSandboxActive.value = true
    logger.info('SANDBOX', 'Modo Sandbox activado para Test Aventura. Partida real respaldada.')
  }

  function exitSandboxMode() {
    if (!isSandboxActive.value) return

    // Guardar el estado del sandbox localmente antes de salir
    if (typeof window !== 'undefined') {
      localStorage.setItem('pvs_sandbox_save', JSON.stringify(state))
    }

    // Limpiar y restaurar la partida real
    Object.keys(state).forEach(key => {
      delete (state as Record<string, unknown>)[key]
    })

    if (realStateBackup.value) {
      Object.assign(state, realStateBackup.value)
      realStateBackup.value = null
    } else {
      Object.assign(state, JSON.parse(JSON.stringify(INITIAL_STATE)))
    }

    isDataLoaded.value = false // Reset data loaded so real save gets fetched when entering normal game
    isSandboxActive.value = false
    logger.info('SANDBOX', 'Modo Sandbox desactivado. Partida real restaurada.')
  }

  // --- WATCHERS ---
  watch(() => state.team.length, (newLen, oldLen) => {
    if (newLen > oldLen && state.pvpTeam.length < 3) autoFillPvpTeam()
  })

  return {
    state,
    db,
    updateState,
    resetToInitial,
    registerPokedex,
    scheduleSave,
    hatchEggs,
    claimAsset,
    fetchClaimQueue,
    loadGame,
    save,
    isDataLoaded,
    isEngineReady,
    isReady,
    isSaveLocked,
    chooseStarter,
    addTrainerExp,
    checkLevelUp,
    getTrainerRank,
    getMaxObeyLevel,
    reorderTeam,
    reorderPvpTeam,
    reorderWarTeam,
    reorderMoves,
    sendToBox,
    addPokemon,
    removePokemon,
    autoFillPvpTeam,
    swapPvpSlot,
    autoFillWarTeam,
    swapWarSlot,
    togglePokeTag,
    executeHatch,
    reclaimControl,
    saveGame: save, // Alias
    isSandboxActive,
    enterSandboxMode,
    exitSandboxMode,
    checkRouteExpirations
  }
})

import { makePokemon, sanitizePokemon } from '@/logic/pokemon/pokemonFactory'
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider'
import { useUIStore } from '@/stores/ui'
import { useLoadingStore } from '@/stores/loading'
import type { GameState } from '@/types/game'
import type { Pokemon, PokemonEgg } from '@/types/pokemon'
import { getItemByName, getItemById } from '@/data/items'

export function usePokemonActions(
  state: GameState, 
  scheduleSave: () => Promise<void>, 
  autoFillPvpTeam: () => void, 
  autoFillWarTeam: () => void
) {
  function registerPokedex(id: string, caught = false) {
    if (!state.seenPokedex.includes(id)) state.seenPokedex.push(id)
    if (caught && !state.pokedex.includes(id)) state.pokedex.push(id)
  }

  async function chooseStarter(id: string) {
    const loadingStore = useLoadingStore()
    loadingStore.start('choose_starter', 'Preparando aventura...', 'Asignando primer compañero', true, '🎒')

    const uiStore = useUIStore()
    const starter = makePokemon(id, 5)

    if (starter) {
      addPokemon(starter, { notify: false })
      state.starterChosen = true
      uiStore.activeTab = 'map'

      const speciesData = pokemonDataProvider.getPokemonData(id)
      if (speciesData) {
        uiStore.notify(`¡${speciesData.name} es tu compañero! ¡Buena suerte!`, '🎉')
      }
    }

    await scheduleSave() // Save immediately
    loadingStore.finish('choose_starter')
  }

  function addPokemon(pokemon: Pokemon | null, options = { notify: true }) {
    if (!pokemon) return { success: false, target: null }
    registerPokedex(pokemon.id, true)

    let target: 'team' | 'box' = 'team'
    if (state.team.length < 6) {
      state.team.push(pokemon)
    } else {
      state.box = state.box || []
      state.box.push(pokemon)
      target = 'box'
    }

    if (options.notify) {
      const location = target === 'team' ? 'tu equipo' : 'la Caja PC'
      useUIStore().notify(`¡${pokemon.name} se unió a ${location}!`, '✨')
    }

    scheduleSave()
    autoFillPvpTeam()
    autoFillWarTeam()
    return { success: true, target }
  }



  function removePokemon(uid: string) {
    const teamIdx = state.team.findIndex(p => p.uid === uid)
    if (teamIdx !== -1) {
      state.team.splice(teamIdx, 1)
      autoFillPvpTeam()
      scheduleSave()
      return true
    }
    const boxIdx = state.box.findIndex(p => p.uid === uid)
    if (boxIdx !== -1) {
      const p = state.box[boxIdx]
      if (!p || p.onMission) return false
      state.box.splice(boxIdx, 1)
      autoFillPvpTeam()
      autoFillWarTeam()
      scheduleSave()
      return true
    }
    return false
  }

  function reorderTeam(draggedIndex: number, targetIndex: number) {
    if (draggedIndex === targetIndex) return
    const newTeam = [...state.team]
    const [moved] = newTeam.splice(draggedIndex, 1)
    if (!moved) return
    newTeam.splice(targetIndex, 0, moved)
    state.team = newTeam
    scheduleSave()
  }

  function reorderMoves(pokemon: Pokemon, fromIndex: number, toIndex: number) {
    if (fromIndex === toIndex || !pokemon || !pokemon.moves) return
    const newMoves = [...pokemon.moves]
    const moved = newMoves[fromIndex]
    if (moved === undefined) return
    newMoves.splice(fromIndex, 1)
    newMoves.splice(toIndex, 0, moved);
    pokemon.moves = newMoves
    scheduleSave()
  }

  function sendToBox(index: number) {
    if (state.team.length <= 1) {
      useUIStore().notify('No puedes quedarte sin Pokémon en el equipo.', '⚠️')
      return false
    }
    const p = state.team[index];
    if (!p) return false;

    state.team.splice(index, 1)
    state.box.push(p)
    useUIStore().notify(`¡${p.name} fue enviado a la Caja PC!`, '📦')
    autoFillPvpTeam()
    autoFillWarTeam()
    scheduleSave()
    return true
  }

  function togglePokeTag(context: 'team' | 'box', index: number, tagId: string) {
    const p = context === 'team' ? state.team[index] : (state.box ? state.box[index] : null)
    if (!p) return

    if (!p.tags) p.tags = []
    const idx = p.tags.indexOf(tagId)
    if (idx > -1) {
      p.tags.splice(idx, 1)
    } else {
      p.tags.push(tagId)
    }
    scheduleSave()
  }

  interface LegacyEgg extends PokemonEgg {
    pokemonId?: string;
  }

  function sanitizeAll() {
    state.team.forEach(p => p && sanitizePokemon(p))
    if (state.box) state.box.forEach(p => p && sanitizePokemon(p))

    // Inventory Self-Healing: convert legacy Spanish names to current official English IDs
    if (state.inventory) {
      const healedInventory: Record<string, number> = {};
      for (const [key, qty] of Object.entries(state.inventory)) {
        let officialId = key;

        // Find in SHOP_ITEMS by name or id
        const item = getItemByName(key) || getItemById(key);

        if (item) {
          officialId = item.id;
        }

        healedInventory[officialId] = (healedInventory[officialId] || 0) + qty;
      }
      state.inventory = healedInventory;
    }

    // Migración automática: Mover Pokémon del equipo ocupados (guardería, misión, defensa) a la caja PC
    const teamToKeep: Pokemon[] = []
    const teamToMove: Pokemon[] = []

    state.team.forEach(p => {
      if (!p) return
      if (p.inDaycare || p.onMission || p.onDefense) {
        teamToMove.push(p)
      } else {
        teamToKeep.push(p)
      }
    })

    if (teamToMove.length > 0) {
      // Si moverlos a todos dejaría el equipo completamente vacío, preservamos el primero ocupado en el equipo
      if (teamToKeep.length === 0 && teamToMove.length > 0) {
        const first = teamToMove.shift()
        if (first) teamToKeep.push(first)
      }

      teamToMove.forEach(p => {
        state.box.push(p)
      })

      state.team = teamToKeep
      autoFillPvpTeam()
      autoFillWarTeam()
      scheduleSave()
    }

    if (state.eggs && Array.isArray(state.eggs)) {
      state.eggs.forEach((egg: PokemonEgg) => {
        if (!egg) return;
        const legacyEgg = egg as LegacyEgg;

        if (legacyEgg.pokemonId && legacyEgg.pokemonId !== legacyEgg.id) {
          if (!legacyEgg.uid) {
            legacyEgg.uid = `egg_${legacyEgg.id}`;
          }
          legacyEgg.id = legacyEgg.pokemonId;
        }

        if (!legacyEgg.uid) {
          const timestamp = Temporal.Now.instant().epochMilliseconds;
          legacyEgg.uid = `egg_${legacyEgg.id || 'unknown'}-${timestamp}-${Math.random().toString(36).substring(2, 7)}`;
        }

        if (legacyEgg.ready === undefined) {
          legacyEgg.ready = (legacyEgg.steps <= 0);
        }
      });
    }
  }

  return { registerPokedex, chooseStarter, addPokemon, removePokemon, reorderTeam, reorderMoves, sendToBox, togglePokeTag, sanitizeAll }
}

import { useUIStore } from '@/stores/ui'
import type { GameState } from '@/types/game'
import type { Pokemon } from '@/types/pokemon'

export function useTeamActions(state: GameState, scheduleSave: () => Promise<void>) {
  function autoFillPvpTeam() {
    const uiStore = useUIStore()
    if (uiStore.pvpAutoFillDisabled) return

    const allPokes = [...state.team, ...(state.box || [])].filter((p): p is Pokemon => p != null)
    if (allPokes.length === 0) {
      state.pvpTeam = []
      return
    }

    const existingUids = new Set(allPokes.map(p => p.uid))
    state.pvpTeam = (state.pvpTeam || []).filter(uid => existingUids.has(uid))

    const targetCount = Math.min(3, allPokes.length)
    if (state.pvpTeam.length < targetCount) {
      for (const p of allPokes) {
        if (state.pvpTeam.length >= targetCount) break
        if (!state.pvpTeam.includes(p.uid)) {
          state.pvpTeam.push(p.uid)
        }
      }
    }

    if (state.pvpTeam.length > 3) {
      state.pvpTeam = state.pvpTeam.slice(0, 3)
    }
  }

  function swapPvpSlot(slotIndex: number, newPokemonUid: string) {
    if (slotIndex < 0 || slotIndex >= 3) return
    const allPokes = [...state.team, ...(state.box || [])]
    const exists = allPokes.some(p => p?.uid === newPokemonUid)
    const pvpTeam = state.pvpTeam || []
    const alreadyIn = pvpTeam.includes(newPokemonUid)

    if (exists && !alreadyIn) {
      if (!state.pvpTeam) state.pvpTeam = []
      state.pvpTeam[slotIndex] = newPokemonUid
      scheduleSave()
    }
  }

  function reorderPvpTeam(draggedIndex: number, targetIndex: number) {
    if (draggedIndex === targetIndex) return
    const newPvpTeam = [...(state.pvpTeam || [])]
    const moved = newPvpTeam[draggedIndex]
    if (!moved) return
    newPvpTeam.splice(draggedIndex, 1)
    newPvpTeam.splice(targetIndex, 0, moved)
    state.pvpTeam = newPvpTeam
    scheduleSave()
  }

  function unequipFromTeam(uid: string) {
    const p = state.team.find(x => x?.uid === uid)
    if (!p || !p.heldItem) return
    const item = p.heldItem as string
    state.inventory[item] = (state.inventory[item] || 0) + 1
    p.heldItem = null
    scheduleSave()
  }

  function unequipFromBox(uid: string) {
    const p = state.box.find(x => x?.uid === uid)
    if (!p || !p.heldItem) return
    const item = p.heldItem as string
    state.inventory[item] = (state.inventory[item] || 0) + 1
    p.heldItem = null
    scheduleSave()
  }

  function autoFillWarTeam() {
    const allPokes = [...state.team, ...(state.box || [])].filter((p): p is Pokemon => p != null)
    if (allPokes.length === 0) {
      state.warTeam = []
      return
    }

    const existingUids = new Set(allPokes.map(p => p.uid))
    state.warTeam = (state.warTeam || []).filter(uid => existingUids.has(uid))

    const targetCount = Math.min(state.warSlots || 6, allPokes.length)
    if (state.warTeam.length < targetCount) {
      for (const p of allPokes) {
        if (state.warTeam.length >= targetCount) break
        if (!state.warTeam.includes(p.uid)) {
          state.warTeam.push(p.uid)
        }
      }
    }

    if (state.warTeam.length > (state.warSlots || 6)) {
      state.warTeam = state.warTeam.slice(0, state.warSlots || 6)
    }
  }

  function swapWarSlot(slotIndex: number, newPokemonUid: string) {
    const maxSlots = state.warSlots || 6
    if (slotIndex < 0 || slotIndex >= maxSlots) return

    const allPokes = [...state.team, ...(state.box || [])]
    const exists = allPokes.some(p => p?.uid === newPokemonUid)
    const warTeam = state.warTeam || []
    const alreadyIn = warTeam.includes(newPokemonUid)

    if (exists && !alreadyIn) {
      if (!state.warTeam) state.warTeam = []
      state.warTeam[slotIndex] = newPokemonUid
      scheduleSave()
    }
  }

  function reorderWarTeam(draggedIndex: number, targetIndex: number) {
    if (draggedIndex === targetIndex) return
    const newWarTeam = [...(state.warTeam || [])]
    const moved = newWarTeam[draggedIndex]
    if (!moved) return
    newWarTeam.splice(draggedIndex, 1)
    newWarTeam.splice(targetIndex, 0, moved)
    state.warTeam = newWarTeam
    scheduleSave()
  }

  return { autoFillPvpTeam, swapPvpSlot, reorderPvpTeam, unequipFromTeam, unequipFromBox, autoFillWarTeam, swapWarSlot, reorderWarTeam }
}

import { TRAINER_RANKS, MARKET_UNLOCKS } from '@/data/trainer'
import { MAX_POKEMON_LEVEL } from '@/data/constants'
import { gsap } from 'gsap'
import { levelUpPokemon } from '@/logic/pokemon/pokemonFactory'
import { useUIStore, type LearnItem } from '@/stores/ui'
import { useEventStore } from '@/stores/events'
import { usePlayerClassStore } from '@/stores/playerClass'
import type { GameState } from '@/types/game'
import type { Pokemon } from '@/types/pokemon'

export function useTrainerActions(state: GameState, scheduleSave: () => Promise<void>) {
  function getTrainerRank() {
    const idx = Math.min(state.trainerLevel - 1, TRAINER_RANKS.length - 1)
    return TRAINER_RANKS[idx]
  }

  function addTrainerExp(amount: number) {
    const uiStore = useUIStore()
    const eventStore = useEventStore()
    const evBonus = (eventStore.globalMultipliers?.exp || 1) - 1
    const totalMult = 1 + evBonus
    if (totalMult > 1) amount = Math.round(amount * totalMult)

    state.trainerExp += amount

    // Sumar XP a la clase activa también
    const classStore = usePlayerClassStore()
    classStore.addXP(amount)

    const MAX_LEVEL = 30

    let currentRank = getTrainerRank()
    if (!currentRank) return

    while (state.trainerExp >= (currentRank?.expNeeded || 0) && state.trainerLevel < MAX_LEVEL) {
      state.trainerExp -= (currentRank?.expNeeded || 0)
      state.trainerLevel++

      currentRank = getTrainerRank()
      if (currentRank) {
        uiStore.notify(`¡Subiste al rango ${currentRank.title}! Nivel ${state.trainerLevel}`, '⭐')
      }

      const unlocks = (MARKET_UNLOCKS as Record<number, string[]>)[state.trainerLevel]
      if (unlocks) {
        gsap.delayedCall(1.5, () => uiStore.notify(`¡Nuevos items en el Poké Market!`, '🛒'))
      }
    }

    if (currentRank) {
      state.trainerExpNeeded = currentRank.expNeeded
    }

    scheduleSave()
  }

  function checkLevelUp(pokemon: Pokemon) {
    const uiStore = useUIStore()
    const learnQueue: LearnItem[] = []

    if (pokemon.level >= MAX_POKEMON_LEVEL) {
      pokemon.exp = 0
      pokemon.expNeeded = Infinity
      scheduleSave()
      return
    }

    while (pokemon.exp >= pokemon.expNeeded && pokemon.level < MAX_POKEMON_LEVEL) {
      pokemon.exp -= pokemon.expNeeded
      const pendingMoves = levelUpPokemon(pokemon)

      if (pendingMoves === null) break // Blocked by Everstone

      uiStore.notify(`¡${pokemon.name} subió al nivel ${pokemon.level}!`, '📈')

      if (pendingMoves && pendingMoves.length > 0) {
        pendingMoves.forEach(m => learnQueue.push({ pokemon, move: m }))
      }
    }

    if (learnQueue.length > 0) {
      uiStore.addToLearnQueue(learnQueue)
    }

    scheduleSave()
  }

  function getMaxObeyLevel() {
    const badges = state.defeatedGyms?.length || 0
    if (badges >= 8) return 100
    if (badges >= 7) return 75
    if (badges >= 6) return 65
    if (badges >= 5) return 55
    if (badges >= 4) return 45
    if (badges >= 3) return 35
    if (badges >= 2) return 30
    if (badges >= 1) return 25
    return 20
  }

  return { getTrainerRank, addTrainerExp, checkLevelUp, getMaxObeyLevel }
}

