import { defineStore } from 'pinia'
import { ref, computed, watch } from 'vue'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { safeStorage } from '@/logic/utils/storage'
import { getItemById, getItemByName } from '@/data/items'
import { isGlobalItem } from '../logic/providers/itemProvider.ts'
import { useBattleStore } from './battle.ts'
import type { Pokemon } from '@/types/pokemon'
import type { ItemEffectResult } from '@/types/items'
import { executeUseItem } from './inventoryUseAction.ts'
import {
  resolveNormalizedName,
  findInventoryKey as helperFindInventoryKey,
  isItemUsableOn as helperIsItemUsableOn,
  getItemTier,
  isItemProduct,
  getAdjustedProductCategory
} from './inventoryHelpers.ts'

export interface Item {
  name: string;
  qty: number;
  id: string;
  cat?: string;
  type?: string;
  sprite?: string;
  desc?: string;
  price?: number;
  craftingTier?: number;
  tier?: 'common' | 'rare' | 'epic' | 'legend';
  nonCombat?: boolean;
}

export function isItemUsableOutsideCombat(item: { id: string; cat?: string; type?: string } | null | undefined): boolean {
  if (!item) return false
  const cat = item.cat
  const type = item.type
  const id = item.id

  const valuables = ['nugget', 'pearl', 'big_pearl', 'stardust', 'star_piece']
  if (valuables.includes(id)) return false

  if (cat === 'pokeballs') return false

  if (id && id.toLowerCase().startsWith('tm')) return true

  if (
    cat === 'potions' ||
    cat === 'stones' || type === 'stone' ||
    cat === 'combat_held' || cat === 'breeding_held' || type === 'held' ||
    cat === 'tools' || type === 'booster' || type === 'usable'
  ) {
    return true
  }

  return false
}

export const useInventoryStore = defineStore('inventory', () => {
  const gameStore = useGameStore()
  const uiStore = useUIStore()

  // --- BAG STATE ---
  const bagSellMode = ref(false)
  const bagSellSelected = ref<Record<string, number>>({}) // { itemName: quantity }
  const activeMainTab = ref<'productos' | 'materiales'>('productos')
  const activeCategory = ref(safeStorage.getItem('inventory_last_tab') || 'todos')
  const searchQuery = ref('')
  const currentSort = ref<'name' | 'price' | 'rarity'>('name')
  const currentSortOrder = ref<'asc' | 'desc'>('asc')

  watch(activeCategory, (newVal) => {
    safeStorage.setItem('inventory_last_tab', newVal)
  })

  function findInventoryKey(name: string): string | null {
    return helperFindInventoryKey(gameStore, name)
  }

  // --- GETTERS ---
  const bagItems = computed(() => {
    const inventory = gameStore.state.inventory || {}
    let items: Item[] = Object.entries(inventory)
      .map(([id, qty]) => {
        const item = getItemById(id) || (id === 'bicycle' ? { id: 'bicycle', name: 'Bicicleta', sprite: 'tools/bicycle', desc: 'Bicicleta para moverte rápido.', cat: 'tools' } : null)
        if (!item) return { name: id, qty, id, cat: 'otros', sprite: id, desc: 'Objeto desconocido' } as Item
        return { ...item, qty, name: item.name } as Item
      })

    const isBattleActive = useBattleStore().isBattleActive
    if (isBattleActive) {
      items = items.filter(item => {
        const dbItem = getItemById(item.id)
        return !(dbItem && dbItem.nonCombat)
      })
    }

    // Filter by main tab
    if (activeMainTab.value === 'materiales') {
      items = items
        .filter(item => getItemTier(item) < 3)
        .map(item => {
          const tier = getItemTier(item)
          let cat = item.cat
          if (tier === 0) cat = 'raw_material'
          else if (tier === 1) cat = 'refined_material'
          else if (tier === 2) cat = 'component'
          return { ...item, cat }
        })
    } else {
      // Tab is productos
      items = items
        .filter(item => getItemTier(item) === 3 || isItemProduct(item))
        .map(item => ({
          ...item,
          cat: getAdjustedProductCategory(item)
        }))
    }

    if (activeCategory.value === 'utilizables') {
      const target = uiStore.inventoryTarget
      const isBattleActive = useBattleStore().isBattleActive
      if (target) {
        const list = target.context === 'team' ? gameStore.state.team : gameStore.state.box
        const pokemon = list[target.index]
        if (pokemon) {
          items = items.filter(item => {
            const dbItem = getItemById(item.id)
            if (isBattleActive && dbItem?.nonCombat) return false
            return helperIsItemUsableOn(item.id, pokemon)
          })
        }
      } else {
        items = items.filter(item => {
          if (!isItemUsableOutsideCombat(item)) return false

          if (isGlobalItem(item.id)) return true


          const isHeld = item.cat === 'combat_held' || item.cat === 'breeding_held' || item.type === 'held'
          if (isHeld) return (gameStore.state.team || []).length > 0

          const dbItem = getItemById(item.id)
          if (isBattleActive && dbItem?.nonCombat) return false

          return (gameStore.state.team || []).some((pokemon: Pokemon) => helperIsItemUsableOn(item.id, pokemon))
        })
      }
    }

    // Filter items first
    const result = items.filter(item => {
      if (item.qty <= 0) return false
      const resolvedCat = item.cat || 'otros'
      if (activeCategory.value !== 'todos' && activeCategory.value !== 'utilizables' && resolvedCat !== activeCategory.value) return false
      // Do not apply the global store searchQuery if a battle is active (to avoid sharing the filter with the battle modal)
      if (!isBattleActive && searchQuery.value && !item.name.toLowerCase().includes(searchQuery.value.toLowerCase())) return false
      return true
    })

    // Sort items
    result.sort((a, b) => {
      let comp = 0
      if (currentSort.value === 'price') {
        comp = (a.price || 0) - (b.price || 0)
      } else if (currentSort.value === 'rarity') {
        const tiers: Record<string, number> = { common: 0, rare: 1, epic: 2, legend: 3 }
        const aVal = tiers[a.tier || 'common'] ?? 0
        const bVal = tiers[b.tier || 'common'] ?? 0
        comp = bVal - aVal
      } else {
        comp = a.name.localeCompare(b.name)
      }
      return currentSortOrder.value === 'asc' ? comp : -comp
    })

    return result
  })

  const CATEGORY_LABELS = {
    utilizables: 'Utilizables',
    todos: 'Todos',
    // Materiales
    raw_material: 'Materia Prima',
    refined_material: 'Materia Refinada',
    component: 'Componentes',
    // Productos
    pokeballs: 'Pokéballs',
    potions: 'Curativos',
    stones: 'Piedras',
    combat_held: 'Equipables',
    breeding_held: 'Crianza',
    machinery: 'Maquinaria',
    tools: 'Herramientas',
    tms: 'Discos MT',
    otros: 'Otros'
  }

  // --- BAG ACTIONS ---
  function toggleBagSellMode() {
    bagSellMode.value = !bagSellMode.value
    bagSellSelected.value = {}
  }

  function toggleBagSellSelect(itemName: string, maxQty: number) {
    if (bagSellSelected.value[itemName]) {
      delete bagSellSelected.value[itemName]
    } else {
      bagSellSelected.value[itemName] = maxQty
    }
  }

  function updateBagSellQty(itemName: string, qty: string | number, maxQty: number) {
    let q = typeof qty === 'string' ? parseInt(qty) : qty
    if (isNaN(q) || q < 1) q = 1
    if (q > maxQty) q = maxQty
    bagSellSelected.value[itemName] = q
  }

  function getBagSellTotalGain() {
    let total = 0
    Object.entries(bagSellSelected.value).forEach(([name, q]) => {
      const itemInfo = getItemByName(name)
      if (itemInfo) total += Math.floor((itemInfo.price || 0) * 0.5) * q
    })
    return total
  }

  function confirmBagSell() {
    const selectedEntries = Object.entries(bagSellSelected.value)
    if (selectedEntries.length === 0) return false

    const totalGain = getBagSellTotalGain()
    const inv = gameStore.state.inventory || {}

    selectedEntries.forEach(([name, qty]) => {
      const actualKey = findInventoryKey(name)
      if (!actualKey) return
      inv[actualKey] = (inv[actualKey] || 0) - qty
      if (inv[actualKey] <= 0) delete inv[actualKey]
    })

    gameStore.state.inventory = { ...inv }
    gameStore.state.money += totalGain
    toggleBagSellMode()
    gameStore.save()
    return totalGain
  }

  function removeItem(itemName: string, qty: number = 1) {
    const inv = gameStore.state.inventory
    if (!inv) return

    const actualKey = findInventoryKey(itemName)
    if (!actualKey || !inv[actualKey]) return

    if (qty === 999) {
      delete inv[actualKey]
    } else {
      inv[actualKey] -= qty
      if (inv[actualKey] <= 0) delete inv[actualKey]
    }

    // Force reactivity for inventory object
    gameStore.state.inventory = { ...inv }
    gameStore.save(false)
  }

  function addItem(itemName: string, qty: number = 1) {
    if (!itemName) return
    const inventory = gameStore.state.inventory || {}

    const actualKey = findInventoryKey(itemName) || itemName
    inventory[actualKey] = (inventory[actualKey] || 0) + qty
    gameStore.state.inventory = { ...inventory } // Force reactivity
    gameStore.save(false)
  }

  function sellItem(itemName: string, qty: number = 1) {
    const officialName = resolveNormalizedName(itemName)
    const itemInfo = getItemByName(officialName) || getItemById(officialName)
    if (!itemInfo) return

    const actualKey = findInventoryKey(itemName) || itemName
    const inventoryQty = gameStore.state.inventory[actualKey] || 0
    const sellQty = qty === 999 ? inventoryQty : Math.min(qty, inventoryQty)

    const gain = Math.floor((itemInfo.price || 0) * 0.5) * sellQty

    removeItem(actualKey, sellQty)
    gameStore.state.money += gain
    gameStore.save(false)
  }

  async function processBatchAction(itemMap: Map<string, number>, mode: 'sell' | 'release') {
    let totalGain = 0
    const inventory = gameStore.state.inventory || {}

    for (const [name, qty] of itemMap.entries()) {
      const actualKey = findInventoryKey(name)
      if (!actualKey || !inventory[actualKey]) continue

      const actualQty = Math.min(qty, inventory[actualKey])

      if (mode === 'sell') {
        const officialName = resolveNormalizedName(name)
        const itemInfo = getItemByName(officialName)
        if (itemInfo) totalGain += Math.floor((itemInfo.price || 0) * 0.5) * actualQty
      }

      inventory[actualKey] -= actualQty
      if (inventory[actualKey] <= 0) delete inventory[actualKey]
    }

    gameStore.state.inventory = { ...inventory }
    if (mode === 'sell') gameStore.state.money += totalGain

    await gameStore.save(false)
    return totalGain
  }

  // --- ITEM ACTIONS ---
  function useItem(itemName: string, context: 'team' | 'box' | null = null, index: number | null = null): ItemEffectResult {
    return executeUseItem(itemName, context, index)
  }

  function equipItem(itemName: string, context: 'team' | 'box', index: number) {
    const list = context === 'team' ? gameStore.state.team : gameStore.state.box
    const pokemon = list[index]
    if (!pokemon) return false

    const inv = gameStore.state.inventory || {}

    // If already has an item, return it to inventory
    if (pokemon.heldItem) {
      const oldItem = pokemon.heldItem
      const oldItemKey = findInventoryKey(oldItem) || oldItem
      inv[oldItemKey] = (inv[oldItemKey] || 0) + 1
    }

    pokemon.heldItem = itemName
    const actualKey = findInventoryKey(itemName)
    if (actualKey && inv[actualKey] !== undefined) {
      inv[actualKey] = (inv[actualKey] || 0) - 1
      if (inv[actualKey] <= 0) delete inv[actualKey]
    }

    gameStore.state.inventory = { ...inv }
    gameStore.save()
    return true
  }

  function unequipItem(context: 'team' | 'box', index: number) {
    const list = context === 'team' ? gameStore.state.team : gameStore.state.box
    const pokemon = list[index]
    if (!pokemon || !pokemon.heldItem) return false

    const item = pokemon.heldItem
    const inv = gameStore.state.inventory || {}
    const actualKey = findInventoryKey(item) || item

    inv[actualKey] = (inv[actualKey] || 0) + 1;
    pokemon.heldItem = null

    gameStore.state.inventory = { ...inv }
    gameStore.save()
    return item
  }

  return {
    // Bag
    bagSellMode,
    bagSellSelected,
    activeMainTab,
    activeCategory,
    searchQuery,
    currentSort,
    currentSortOrder,
    bagItems,
    CATEGORY_LABELS,
    toggleBagSellMode,
    toggleBagSellSelect,
    updateBagSellQty,
    getBagSellTotalGain,
    confirmBagSell,
    // Items
    useItem,
    equipItem,
    unequipItem,
    addItem,
    removeItem,
    sellItem,
    processBatchAction
  }
})

import { useGameStore } from './game.ts';
import { getItemByName, getItemById } from '@/data/items';
import { itemEffects as ITEM_EFFECTS, getDynamicItemEffect } from '@/logic/items/itemEffects';
import { isGlobalItem } from '../logic/providers/itemProvider.ts';
import type { Pokemon } from '@/types/pokemon';

export function resolveNormalizedName(name: string): string {
  const norm = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');

  const aliases: Record<string, string> = {
    'potion': 'Poción',
    'pocion': 'Poción',
    'pocian': 'Poción',
    'pociaon': 'Poción',
    'pokeball': 'Pokéball',
    'pokaball': 'Pokéball',
    'carbon': 'Carbón vegetal',
    'superpotion': 'Súper Poción',
    'superpocion': 'Súper Poción',
    'hyperpotion': 'Hiper Poción',
    'hiperpocion': 'Hiper Poción',
    'maxpotion': 'Poción Máxima',
    'pocionmaxima': 'Poción Máxima',
    'firestone': 'Piedra Fuego',
    'waterstone': 'Piedra Agua',
    'thunderstone': 'Piedra Trueno',
    'leafstone': 'Piedra Hoja',
    'moonstone': 'Piedra Lunar',
    'sunstone': 'Piedra Solar',
    'vigorcandy': 'Caramelo de vigor',
    'repel': 'Repelente',
    'iman': 'Imán',
    'elixir': 'Elixir',
    'subidapp': 'Subida de PP',
    'mttoxico': 'MT06 Tóxico',
    'ocasoball': 'Ocaso Ball',
    'turnoball': 'Turno Ball',
    'ultraball': 'Ultra Ball',
    'masterball': 'Master Ball',
    'superball': 'Súper Ball',
    'brazalrecio': 'Brazal Recio',
    'brazalrecia': 'Brazal Recio',
    'cintorecio': 'Cinto Recio',
    'cintorecia': 'Cinto Recio',
    'pesarecia': 'Pesa Recia',
    'bandarecia': 'Banda Recia',
    'lenterecia': 'Lente Recia',
    'franjarecia': 'Franja Recia',
    'bayadeoro': 'Baya de Oro',
    'bayaoro': 'Baya de Oro',
    'piedraeterna': 'Piedra Eterna',
    'lazodestino': 'Lazo Destino',
    'caramelovigor': 'Caramelo de vigor',
    'fishingrod': 'Caña de pescar',
    'fishingrodgood': 'Caña Buena',
    'fishingrodsuper': 'Supercaña',
    'pickaxe': 'Pico de excavación',
    'pickaxesilver': 'Pico Bueno',
    'pickaxegold': 'Superpico',
    'brush': 'Pincel de excavación',
    'brushgood': 'Pincel Bueno',
    'brushsuper': 'Superpincel',
    'naturepatch': 'Parche de naturaleza',
    'ppup': 'Subida de PP',
    'tm06': 'MT06 Tóxico'
  };

  return aliases[norm] || name;
}

export function findInventoryKey(gameStore: ReturnType<typeof useGameStore>, name: string): string | null {
  const item = getItemById(name) || getItemByName(name) || getItemById(resolveNormalizedName(name)) || getItemByName(resolveNormalizedName(name));
  if (item) return item.id;

  const inv = gameStore.state.inventory || {};
  if (inv[name] !== undefined) return name;

  const targetOfficial = resolveNormalizedName(name);
  const targetOfficialNorm = targetOfficial.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');

  for (const key of Object.keys(inv)) {
    const keyItem = getItemById(key);
    const keyOfficial = keyItem ? keyItem.name : key;
    const keyOfficialNorm = keyOfficial.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
    if (keyOfficialNorm === targetOfficialNorm) {
      return key;
    }
  }
  return null;
}

export function isItemUsableOn(itemName: string, pokemon: Pokemon) {
  if (!pokemon) return false;

  // Resolve Spanish names to their English ID if necessary
  const dbItem = getItemByName(itemName) || getItemById(itemName);
  const itemId = dbItem ? dbItem.id : itemName.toLowerCase();

  if (isGlobalItem(itemId)) return false;

  const item = getItemById(itemId);

  if (pokemon.inDaycare) {
    if (!item) return false;
    const isVigorRestorer = item.id === 'vigor_restorer' || item.id === 'vigor_candy';
    const isBreedingHeld = item.cat === 'breeding';
    return !!(isVigorRestorer || isBreedingHeld);
  }

  if (item && (
    item.cat === 'held' || 
    item.type === 'held' || 
    (item.cat === 'breeding' && item.id !== 'vigor_restorer' && !item.id.includes('berry'))
  )) return true;

  const p = JSON.parse(JSON.stringify(pokemon));

  const effectFn = ITEM_EFFECTS[itemId];
  if (effectFn) {
    const res = effectFn(p);
    return res && res.success;
  }

  const dynamicRes = getDynamicItemEffect(itemId, p);
  return dynamicRes && dynamicRes.success;
}

export function consumeItem(gameStore: ReturnType<typeof useGameStore>, itemName: string) {
  const inv = gameStore.state.inventory;
  if (!inv) return;
  const itemId = itemName.toLowerCase();
  const actualKey = findInventoryKey(gameStore, itemId);
  if (actualKey && inv[actualKey]) {
    inv[actualKey]--;
    if (inv[actualKey] <= 0) {
      delete inv[actualKey];
    }
    gameStore.state.inventory = { ...inv };
  }
}

export function getItemTier(item: { cat?: string; sprite?: string; craftingTier?: number }): number {
  if (item.craftingTier !== undefined) return item.craftingTier;
  const cat = item.cat || 'otros';
  if (cat === 'raw_material' || item.sprite?.includes('crafting/tier0/')) return 0;
  if (cat === 'refined_material' || item.sprite?.includes('crafting/tier1/')) return 1;
  if (cat === 'component' || item.sprite?.includes('crafting/tier2/')) return 2;
  return 3;
}

export function isItemProduct(item: { name: string; cat?: string; type?: string; id?: string; sprite?: string }): boolean {
  if (getItemTier(item) === 3) return true;

  const cat = item.cat;
  const type = item.type;
  const id = item.id;

  if (
    cat === 'potions' ||
    cat === 'pokeballs' ||
    cat === 'stones' ||
    cat === 'combat_held' ||
    cat === 'breeding_held' ||
    type === 'stone' ||
    type === 'held' ||
    type === 'usable' ||
    type === 'booster' ||
    cat === 'tools' ||
    cat === 'tms'
  ) {
    return true;
  }

  const officialName = resolveNormalizedName(item.name);
  if (ITEM_EFFECTS[officialName]) return true;
  if (item.name.toLowerCase().match(/m[tt]\d+/)) return true;
  if (id?.toLowerCase().startsWith('tm')) return true;

  return false;
}

export function getAdjustedProductCategory(item: { name: string; cat?: string; id?: string }): string {
  const cat = item.cat || 'otros';

  if (!['raw_material', 'refined_material', 'component'].includes(cat)) {
    return cat;
  }

  const id = item.id || '';
  if (id.includes('stone') || item.name.toLowerCase().includes('piedra')) {
    return 'stones';
  }

  if (id.includes('root') || id.includes('revive') || item.name.toLowerCase().includes('pocion') || item.name.toLowerCase().includes('revivir')) {
    return 'potions';
  }

  return 'otros';
}

import { useGameStore } from './game.ts';
import { useUIStore } from './ui.ts';
import { useBattleStore } from './battle.ts';
import { itemEffects as ITEM_EFFECTS, getDynamicItemEffect } from '@/logic/items/itemEffects';
import { isGlobalItem } from '../logic/providers/itemProvider.ts';
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';
import { consumeItem } from './inventoryHelpers.ts';
import type { Pokemon, Move } from '@/types/pokemon';
import type { ItemEffectResult } from '@/types/items';
import { useAudioStore } from './audio.ts';
import type { GameState } from '@/types/game';
import { SHOP_ITEMS } from '@/data/items';
import { useErrorStore } from './errorStore.ts';

export function executeUseItem(
  itemName: string,
  context: 'team' | 'box' | null = null,
  index: number | null = null
): ItemEffectResult {
  try {
    const gameStore = useGameStore();
    const uiStore = useUIStore();
    const battleStore = useBattleStore();

    const itemId = itemName.toLowerCase();

    // Verify item exists in SHOP_ITEMS catalog or is a TM
    const isTM = itemId.startsWith('tm') || itemId.startsWith('mt');
    const dbItem = SHOP_ITEMS.find(i => i.id === itemId);
    const itemExists = isTM || !!dbItem;
    if (!itemExists) {
      throw new Error(`[InventoryStore] Intento de usar un objeto inexistente: ${itemName}`);
    }

    const list = context === 'team' ? gameStore.state.team : gameStore.state.box;
    const pokemon = index !== null ? (list as Pokemon[])[index] : null;

    if (battleStore.isBattleActive && dbItem?.nonCombat) {
      return { success: false, message: 'Este objeto no se puede usar en combate.' };
    }

    // Combat check
    if (battleStore.isBattleActive && !battleStore.isProcessing) {
      battleStore.useItemInBattle(itemId, context === 'team' ? index : null);
      return { success: true, message: 'Usando objeto en combate...' };
    }

    // Global items
    if (isGlobalItem(itemId)) {
      const effectFn = (ITEM_EFFECTS as Record<string, (p: GameState) => ItemEffectResult>)[itemId];
      if (!effectFn) return { success: false, message: 'Efecto global no implementado.' };

      const result = effectFn(gameStore.state);
      if (result.success) {
        consumeItem(gameStore, itemId);
        gameStore.save(false);
      }
      return result;
    }

    if (!pokemon) return { success: false, message: 'Seleccioná un Pokémon.' };

    const effectFn = (ITEM_EFFECTS as Record<string, (p: Pokemon) => ItemEffectResult>)[itemId];
    let result: ItemEffectResult | null;

    if (effectFn) {
      result = effectFn(pokemon);
    } else {
      result = getDynamicItemEffect(itemId, pokemon);
    }

    if (!result || !result.success) {
      return result || { success: false, message: 'Este objeto no tiene efecto.' };
    }

    // Post effects
    let shouldConsumeImmediately = true;

    if (result.resultType === 'relearner') {
      uiStore.activePokemonForRelearner = pokemon;
      uiStore.isMoveRelearnerOpen = true;
      shouldConsumeImmediately = false; // Handled by MoveRelearnerModal
    } else if (result.resultType === 'evolution') {
      uiStore.startEvolution(pokemon, result.targetId || '', itemId);
    } else if (result.resultType === 'levelup') {
      gameStore.checkLevelUp(pokemon);
    } else if (result.resultType === 'learn_move') {
      const moveName = result.moveName || '';
      const moveData = pokemonDataProvider.getMoveData(moveName);
      const moveObj = { 
        name: moveName, 
        pp: moveData?.pp || 35, 
        maxPP: moveData?.pp || 35 
      };

      if (pokemon.moves.length < 4) {
        pokemon.moves.push(moveObj as Move);
        uiStore.notify(`¡${pokemon.name} aprendió ${moveName}!`, '📖');
      } else {
        shouldConsumeImmediately = false;
        uiStore.addToLearnQueue({ 
          pokemon, 
          move: moveObj as Move,
          onComplete: () => {
            consumeItem(gameStore, itemId);
            gameStore.save(false);
          }
        });
      }
    } else if (result.resultType === 'nature_patch') {
      uiStore.activePokemonForNature = pokemon;
      uiStore.isNaturePatchOpen = true;
    } else if (result.resultType === 'pp_up' || result.resultType === 'pp_max') {
      uiStore.activePokemonForPPUp = pokemon;
      uiStore.activeItemForPPUp = itemId;
      uiStore.isPPUpOpen = true;
    } else if (result.resultType === 'ability_pill') {
      uiStore.activePokemonForAbility = pokemon;
      uiStore.isAbilityPillOpen = true;
    }

    if (shouldConsumeImmediately) {
      consumeItem(gameStore, itemId);
      gameStore.save(false);
    }

    const audioStore = useAudioStore();
    const healItems = [
      'potion', 'super_potion', 'hyper_potion', 'max_potion',
      'revive', 'revive_max', 'antidote', 'burn_heal',
      'paralyze_heal', 'awakening', 'ice_heal', 'full_heal', 'soda_pop', 'lemonade'
    ];
    if (healItems.includes(itemId)) {
      audioStore.play('heal');
    } else {
      audioStore.play('item');
    }

    return result;
  } catch (error) {
    const errorStore = useErrorStore();
    errorStore.setError(error as Error, { type: 'Item Usage Error', source: `executeUseItem(${itemName})` });
    return { success: false, message: '¡Ocurrió un error al usar el objeto!' };
  }
}

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { logger } from '@/logic/utils/logger'

export interface LoadingItem {
  id: string;
  message: string;
  subMessage: string;
  isGlobal: boolean;
  timestamp: number;
  icon?: string;
}

export const useLoadingStore = defineStore('loading', () => {

  // A stack of loading states to support nested/parallel operations without overwriting each other
  const stack = ref<LoadingItem[]>([])
  const isAppMounted = ref(false)

  /**
   * Starts a loading operation and adds it to the stack.
   * @param {string} id - Unique identifier for the operation
   * @param {string} message - Primary message to display
   * @param {string} subMessage - Secondary/hint text
   * @param {boolean} isGlobal - If true, it uses the dark global overlay (higher priority)
   * @param {string} icon - Emoji or icon to display (default: '📶')
   */
  function start(id: string, message = 'Procesando...', subMessage = 'Por favor, no cierres la ventana', isGlobal = true, icon = '📶') {
    // If ID already exists, update it instead of pushing
    const index = stack.value.findIndex(item => item.id === id)
    const payload: LoadingItem = { id, message, subMessage, isGlobal, timestamp: Temporal.Now.instant().epochMilliseconds, icon }

    if (index !== -1) {
      stack.value[index] = payload
    } else {
      stack.value.push(payload)
    }

    logger.debug('LoadingStore', `Started: ${id} ("${message}")`)
  }

  /**
   * Removes a loading operation from the stack by its ID.
   * @param {string} id - The identifier used in start()
   */
  function finish(id: string) {
    const originalLen = stack.value.length
    stack.value = stack.value.filter(item => item.id !== id)

    if (stack.value.length !== originalLen) {
      logger.debug('LoadingStore', `Finished: ${id}`)
    }
  }

  /**
   * Clears the entire loading stack.
   */
  function clearAll() {
    stack.value = []
  }

  // Returns the current active loading state (the one at the top of the stack)
  const current = computed(() => {
    if (stack.value.length === 0) return null

    // Prioritize global overlays if any
    const globalItems = stack.value.filter(i => i.isGlobal)
    if (globalItems.length > 0) {
      return globalItems[globalItems.length - 1]
    }

    // Otherwise return the most recent one
    return stack.value[stack.value.length - 1]
  })

  const isActive = computed(() => stack.value.length > 0)

  /**
   * Updates the message or subMessage of an active loading state.
   * @param {string} id - The identifier used in start()
   * @param {string} message - New primary message (optional)
   * @param {string} subMessage - New secondary message (optional)
   */
  function setProgress(id: string, message: string | null = null, subMessage: string | null = null) {
    const item = stack.value.find(i => i.id === id)
    if (item) {
      if (message !== null) item.message = message
      if (subMessage !== null) item.subMessage = subMessage
    }
  }

  function markAppMounted() {
    isAppMounted.value = true
    logger.success('LoadingStore', 'App View Mounted')
  }

  const isGateOpen = computed(() => {
    // The gate opens ONLY when the app is mounted AND there are no active loading tasks
    return isAppMounted.value && stack.value.length === 0
  })

  return {
    stack,
    current,
    isActive,
    isAppMounted,
    isGateOpen,
    start,
    finish,
    setProgress,
    clearAll,
    markAppMounted
  }
})

import { useGameStore } from './game.ts';
import { useBattleStore } from './battle.ts';
import { useUIStore } from './ui.ts';
import { useEventStore } from './events.ts';
import { useInventoryStore } from './inventory.ts';
import { FIRE_RED_MAPS } from '@/data/maps';
import { generateEncounter } from '@/logic/encounters/encounters';
import { syncServerTime, getServerTime } from '@/logic/utils/timeUtils';
import { pokemonDataProvider } from '@/logic/providers/pokemonDataProvider';
import { getItemByName } from '@/data/items.ts';
import { logger } from '@/logic/utils/logger';
import { TRAINER_TYPES } from '@/data/trainerTypes';
import { getRandomQuoteForTrainer } from '@/data/trainerPhrases';
import { getSpritesForArchetype } from '@/logic/utils/npcSpriteRouter';
import type { Pokemon } from '@/types/pokemon';
import type { MapLocation } from '@/types/encounters';

import type { Event } from '@/logic/events/eventEngine';
import type { DominanceInfo } from '@/types/stores';

export async function executeNavigation(
  locId: string,
  state: {
    currentMap: string;
    currentEpochHour: number;
    lastNavigateTime: number;
    lastTrainerChanceIncrementAt: number;
    currentWeather: string;
    activeEvents: Event[];
    mapWinners: Record<string, DominanceInfo>;
  },
  callbacks: {
    setCurrentMap: (val: string) => void;
    setCurrentEpochHour: (val: number) => void;
    setLastNavigateTime: (val: number) => void;
    setLastTrainerChanceIncrementAt: (val: number) => void;
  }
) {
  const gs = useGameStore();
  const battleStore = useBattleStore();
  const uiStore = useUIStore();
  const eventStore = useEventStore();

  const now = Temporal.Now.instant().epochMilliseconds;
  if (now - state.lastNavigateTime < 400) {
    logger.warn('MapStore', 'Navigate throttled');
    return;
  }
  callbacks.setLastNavigateTime(now);
  logger.info('MapStore', `Navigating to ${locId}...`);

  // Pity timer logic
  const elapsedPity = now - state.lastTrainerChanceIncrementAt;
  if (elapsedPity >= 120000) {
    const increments = Math.floor(elapsedPity / 120000);
    gs.state.trainerChance = Math.min(20, (gs.state.trainerChance || 5) + increments * 5);
    callbacks.setLastTrainerChanceIncrementAt(now);
    logger.info('MapStore', `PITY: Trainer chance increased to ${gs.state.trainerChance}%`);
  }

  // 1. Verify health
  const healthy = (gs.state.team as Pokemon[]).find(p => p.hp > 0 && !p.onMission && !p.onDefense);
  if (!healthy) {
    uiStore.notify('Todos tus Pokémon están debilitados. ¡Ve al Centro Pokémon!', '🏥');
    return;
  }

  // Update loc and sync time
  await syncServerTime();
  const nextHour = Math.floor(getServerTime() / 3600000);
  callbacks.setCurrentEpochHour(nextHour);
  callbacks.setCurrentMap(locId);

  // 2. Hatch progress — steps only reduce via explicit activities (battle, capture, gym, minigame)

  // 3. Generate Encounter
  const encounter = battleStore.debugLoopPokemon 
    ? (() => {
        const nextPoke = JSON.parse(JSON.stringify(battleStore.debugLoopPokemon)) as Pokemon;
        nextPoke.hp = nextPoke.maxHp;
        nextPoke.status = null;
        nextPoke.confused = 0;
        nextPoke.flinched = false;
        logger.debug('DEBUG', `Navegación: Usando bucle infinito de ${nextPoke.name}`);
        return { type: 'wild', pokemon: nextPoke };
      })()
    : await generateEncounter(locId, gs.state, {
        activeEvents: state.activeEvents,
        dominanceData: state.mapWinners,
        shinyMultiplier: eventStore.globalMultipliers?.shiny || 1,
        weather: state.currentWeather,
        eventFishingBonus: eventStore.globalMultipliers?.fishing || 1
      });

  if (!encounter) {
    logger.info('MapStore', `No encounter generated for ${locId}`);
    return;
  }
  logger.success('MapStore', `Encounter generated: ${encounter.type}`);

  // 4. Process Encounter
  const wildEnc = encounter as { type: string; pokemon: Pokemon; pts?: number; faction?: string; rarity?: number };
  if (wildEnc.type === 'wild' || wildEnc.type === 'fishing' || wildEnc.type === 'archaeology') {
    battleStore._startBattle(wildEnc.pokemon, { 
      locationId: locId,
      wasSearching: true,
      isFishing: wildEnc.type === 'fishing',
      isArchaeology: wildEnc.type === 'archaeology'
    });
  } else if (wildEnc.type === 'guardian') {
    wildEnc.pokemon.isGuardian = true;
    battleStore._startBattle(wildEnc.pokemon, { 
      locationId: locId,
      wasSearching: true,
      isGuardian: true,
      pts: wildEnc.pts
    });
  } else if (wildEnc.type === 'defender') {
    uiStore.notify(`¡Defensor del Team ${wildEnc.faction?.toUpperCase()} detectado!`, '⚔️');
  } else if (wildEnc.type === 'trainer') {
    gs.state.trainerChance = 5;
    callbacks.setLastTrainerChanceIncrementAt(now);

    const { buildTrainerTeam } = await import('@/logic/battle/trainerFactory');

    const isMaxCriminality = (gs.state.playerClass === 'rocket' && (gs.state.classData?.criminality ?? 0) >= 100);
    const targetMap = FIRE_RED_MAPS.find(m => m.id === locId);
    const baseLv = targetMap?.lv?.[0] || 5;

    let tName = 'Entrenador';
    let tSprite = 'youngster';
    let tQuote = '¡Prepárate para combatir! ¡No te lo pondré fácil!';
    const enemyTeam: Pokemon[] = [];

    let typeKey: keyof typeof TRAINER_TYPES = 'default';
    if (isMaxCriminality) {
      const t = TRAINER_TYPES['policeman'];
      tName = t.name;
      const availableSprites = getSpritesForArchetype('policeman');
      const chosenSprite = availableSprites[Math.floor(Math.random() * availableSprites.length)];
      tSprite = chosenSprite || t.sprite;
      tQuote = getRandomQuoteForTrainer('policeman');
      const criminality = gs.state.classData?.criminality || 100;
      const excess = Math.max(0, criminality - 100);
      const bonusLv = Math.floor(excess / 50);
      const trainerLv = baseLv + 5 + bonusLv;
      const teamSize = Math.floor(Math.random() * 2) + 3;

      const team = await buildTrainerTeam(t.pool as unknown as string[], trainerLv, teamSize);
      enemyTeam.push(...team);
    } else {
      const keys = Object.keys(TRAINER_TYPES) as Array<keyof typeof TRAINER_TYPES>;
      typeKey = keys[Math.floor(Math.random() * keys.length)] || 'caza_bichos';
      const t = TRAINER_TYPES[typeKey];

      tName = t.name;
      // Pick a random sprite from the full archetype catalog (not just the hardcoded fallback)
      const archetypeSprites = getSpritesForArchetype(t.archetype);
      tSprite = archetypeSprites[Math.floor(Math.random() * archetypeSprites.length)] || t.sprite;
      tQuote = getRandomQuoteForTrainer(typeKey);
      const trainerLv = baseLv + 2;
      const teamSize = Math.floor(Math.random() * 3) + 1;

      const { buildTrainerTeam } = await import('@/logic/battle/trainerFactory');
      const team = await buildTrainerTeam(t.pool as unknown as string[], trainerLv, teamSize);
      enemyTeam.push(...team);
    }

    if (enemyTeam.length > 0 && enemyTeam[0]) {
      battleStore._startBattle(enemyTeam[0], {
        locationId: locId,
        wasSearching: true,
        isTrainer: true,
        enemyTeam,
        trainerName: tName,
        trainerSprite: tSprite,
        trainerArchetype: isMaxCriminality ? 'policeman' : TRAINER_TYPES[typeKey].archetype,
        trainerQuote: tQuote,
        cannotEscape: true
      });
    }
  } else if (wildEnc.type === 'rival') {
    const { getEvolvedForm } = await import('@/logic/evolution/evolutionLogic');
    const { makePokemon } = await import('@/logic/pokemon/pokemonFactory');

    const trainerNameVal = 'Rival Azul';
    const trainerSpriteVal = 'blue';

    const teamSize = Math.max(3, gs.state.team.length || 1);
    const avgLevel = gs.state.team.reduce((sum, p) => sum + p.level, 0) / (gs.state.team.length || 1);
    const rivalLevel = Math.floor(avgLevel) + 2;

    const rivalPoolBase = ['pidgeot', 'alakazam', 'gyarados', 'arcanine', 'exeggutor', 'charizard'];
    const shuffledPool = [...rivalPoolBase].sort(() => Math.random() - 0.5).slice(0, teamSize);

    const enemyTeam: Pokemon[] = shuffledPool.map(id => {
      const species = getEvolvedForm(id, rivalLevel);
      const p = makePokemon(species, rivalLevel) as Pokemon;
      if (p) (p as Pokemon & { _revealed?: boolean })._revealed = true;
      return p;
    }).filter((p): p is Pokemon => !!p);

    if (enemyTeam.length > 0 && enemyTeam[0]) {
      battleStore._startBattle(enemyTeam[0], {
        locationId: locId,
        wasSearching: true,
        isTrainer: true,
        enemyTeam,
        trainerName: trainerNameVal,
        trainerSprite: trainerSpriteVal,
        trainerArchetype: 'trainers',
        isRival: true,
        cannotEscape: true
      });
    }
  }
}

export async function executeArchaeologyRewards(locId: string, gs: ReturnType<typeof useGameStore>, difficulty?: string) {
  const mapsList = pokemonDataProvider.getMaps() as unknown as MapLocation[];
  const loc = mapsList.find(m => m.id === locId);
  const inventoryStore = useInventoryStore();
  const uiStore = useUIStore();
  const battleStore = useBattleStore();
  const { getAssetUrl, ASSET_TYPES } = await import('@/logic/services/assetService.ts');

  let maxRolls = 1;
  if (difficulty === 'medium') maxRolls = 2;
  else if (difficulty === 'hard') maxRolls = 3;
  else if (difficulty === 'expert') maxRolls = 4;

  const categoryWeights = {
    fossil: 45,
    stone: 25,
    common: 20,
    rare: 10
  };

  const pickaxeType = gs.state.pickaxeSecs > 0 ? (gs.state.pickaxeType || 'standard') : null;
  const brushType = gs.state.brushSecs > 0 ? (gs.state.brushType || 'standard') : null;

  if (pickaxeType === 'good' || pickaxeType === 'super') {
    const budget = pickaxeType === 'good' ? 500 : 1000;
    const affected = [
      { key: 'rare', base: 10 },
      { key: 'common', base: 20 },
      { key: 'stone', base: 25 }
    ];
    let remaining = budget;
    for (let i = 0; i < affected.length; i++) {
      const item = affected[i]!;
      let added = 0;
      if (i === affected.length - 1) {
        added = remaining;
      } else {
        added = Math.round(remaining * 0.5);
      }
      categoryWeights[item.key as 'rare' | 'common' | 'stone'] += added;
      remaining -= added;
    }
  }

  if (brushType === 'good' || brushType === 'super') {
    const budget = brushType === 'good' ? 500 : 1000;
    categoryWeights.fossil += budget;
  }

  const totalWeight = categoryWeights.fossil + categoryWeights.stone + categoryWeights.common + categoryWeights.rare;

  for (let r = 0; r < maxRolls; r++) {
    if (r > 0 && Math.random() >= 0.5) {
      continue;
    }

    const rand = Math.random() * totalWeight;
    let selectedCategory: 'fossil' | 'stone' | 'common' | 'rare' = 'common';

    if (rand < categoryWeights.fossil) {
      selectedCategory = 'fossil';
    } else if (rand < categoryWeights.fossil + categoryWeights.stone) {
      selectedCategory = 'stone';
    } else if (rand < categoryWeights.fossil + categoryWeights.stone + categoryWeights.common) {
      selectedCategory = 'common';
    } else {
      selectedCategory = 'rare';
    }

    let rewardName = '';
    let rewardIcon = '💎';

    if (selectedCategory === 'fossil') {
      const pool = loc?.archaeology?.pool || ['kabuto', 'omanyte'];
      const selectedPoke = pool[Math.floor(Math.random() * pool.length)];
      if (selectedPoke === 'kabuto') {
        rewardName = 'Fósil Domo';
        rewardIcon = '🛡';
      } else if (selectedPoke === 'omanyte') {
        rewardName = 'Fósil Hélix';
        rewardIcon = '🐚';
      } else {
        rewardName = 'Ámbar Viejo';
        rewardIcon = '💎';
      }
    } else if (selectedCategory === 'stone') {
      const stones = [
        { name: 'Piedra Fuego', icon: '🔥' },
        { name: 'Piedra Agua', icon: '💧' },
        { name: 'Piedra Trueno', icon: '⚡' },
        { name: 'Piedra Hoja', icon: '🌿' },
        { name: 'Piedra Lunar', icon: '🌙' },
        { name: 'Piedra Solar', icon: '☀️' }
      ];
      const stone = stones[Math.floor(Math.random() * stones.length)]!;
      rewardName = stone.name;
      rewardIcon = stone.icon;
    } else if (selectedCategory === 'common') {
      const commons = [
        { name: 'Perla', icon: '⚪' },
        { name: 'Polvo Estelar', icon: '✨' },
        { name: 'Mineral de Carbón', icon: '🪨' },
        { name: 'Mineral de Cobre', icon: '🟫' },
        { name: 'Mineral de Hierro', icon: '🧱' }
      ];
      const item = commons[Math.floor(Math.random() * commons.length)]!;
      rewardName = item.name;
      rewardIcon = item.icon;
    } else {
      const rares = [
        { name: 'Pepita', icon: '🟡' },
        { name: 'Perla Grande', icon: '🔘' },
        { name: 'Trozo Estrella', icon: '⭐' },
        { name: 'Mineral de Plata', icon: '⬜' },
        { name: 'Mineral de Oro', icon: '🟨' },
        { name: 'Mineral de Wolframio', icon: '🌑' },
        { name: 'Mineral de Uranio', icon: '🟢' },
        { name: 'Mineral de Rubí', icon: '🔺' },
        { name: 'Mineral de Zafiro', icon: '🔹' },
        { name: 'Mineral de Esmeralda', icon: '💚' },
        { name: 'Mineral de Topacio', icon: '🟡' },
        { name: 'Mineral de Diamante', icon: '💎' }
      ];
      const item = rares[Math.floor(Math.random() * rares.length)]!;
      rewardName = item.name;
      rewardIcon = item.icon;
    }

    const itemData = getItemByName(rewardName);
    const itemSprite = itemData ? getAssetUrl(ASSET_TYPES.ITEM, itemData.sprite) : rewardIcon;

    inventoryStore.addItem(rewardName, 1);
    uiStore.notify(`¡Desenterraste un ${rewardName}!`, itemSprite);
    battleStore.addLog(`¡Desenterraste un <strong style="color:var(--yellow);">${rewardName}</strong>!`, 'log-info', rewardName);
  }
}

import { defineStore } from 'pinia'
import { ref, markRaw } from 'vue'
import gsap from 'gsap'
import { logger } from '@/logic/utils/logger'

import { MODAL_REGISTRY } from '@/logic/modals/registry'

import type { Component } from 'vue'

export interface Modal {
  id: string;
  name: string;
  component: Component;
  props: Record<string, unknown>;
  opening: boolean;
  closing: boolean;
}

export const useModalStore = defineStore('modals', () => {
  const stack = ref<Modal[]>([])

  const open = (name: string, props: Record<string, unknown> = {}) => {
    if ((name === 'Confirm' || name === 'Prompt') && isOpen(name)) {
      logger.warn('ModalStore', `Modal "${name}" is already open. Ignoring duplicate request.`)
      return null
    }

    const registryKey = Object.keys(MODAL_REGISTRY).find(
      key => key.toLowerCase() === name.toLowerCase()
    )
    const component = registryKey ? (MODAL_REGISTRY as Record<string, Component>)[registryKey] : undefined
    if (!component) {
      logger.error('ModalStore', `Modal "${name}" not found in registry`)
      return null
    }

    const id = Math.random().toString(36).substring(7)
    const modal: Modal = {
      id,
      name,
      component: markRaw(component),
      props,
      opening: true, // Initial state for animations
      closing: false
    }

    stack.value.push(modal)

    // GSAP fallback to ensure the "opening" state doesn't hang 
    // This also allows unit tests to pass by simulating visual completion
    gsap.delayedCall(0.45, () => finishOpening(id))

    return id
  }

  /**
   * Called by the component when the opening animation finishes.
   */
  const finishOpening = (id: string) => {
    const target = stack.value.find(m => m.id === id)
    if (target) {
      target.opening = false
    }
  }

  /**
   * Closes a specific modal by ID or Name.
   */
  const close = (identifier: string) => {
    const index = stack.value.findIndex(m => m.id === identifier || m.name === identifier)
    if (index !== -1) {
      const modal = stack.value[index]
      if (!modal || modal.closing) return 
      modal.closing = true

      // GSAP fallback to ensure the modal is eventually removed from the stack
      // even if the component fails to call finalizeClose
      gsap.delayedCall(0.5, () => finalizeClose(modal.id))
    }
  }

  /**
   * Called by the component when the closing animation finishes.
   */
  const finalizeClose = (id: string) => {
    const index = stack.value.findIndex(m => m.id === id)
    if (index !== -1) {
      stack.value.splice(index, 1)
    }
  }

  /**
   * Closes the top-most modal in the stack (LIFO).
   */
  const closeTop = () => {
    if (stack.value.length > 0) {
      const topModal = stack.value[stack.value.length - 1]
      if (topModal) close(topModal.id)
    }
  }

  const closeAll = () => {
    stack.value = []
  }

  const isOpen = (name: string) => {
    return stack.value.some(m => m.name === name && !m.closing)
  }

  return {
    stack,
    open,
    close,
    closeTop,
    closeAll,
    isOpen,
    finishOpening,
    finalizeClose
  }
})

import { defineStore } from 'pinia'
import { computed, watch } from 'vue'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { PLAYER_CLASSES, CLASS_MISSIONS } from '@/data/playerClasses'
import { supabase } from '@/logic/db/supabase'
import { useInventoryStore } from '@/stores/inventory'
import { getClassModifier } from '@/logic/player/classEngine'
import type { Pokemon } from '@/types/pokemon'
import { MAX_POKEMON_LEVEL } from '@/data/constants'
import { getXPNeededForClassLevel } from '@/logic/player/classMath'


import { AVATAR_STYLES } from '@/data/cosmeticsData'

export interface ActiveMission {
  id: string
  startedAt: number
  endsAt: number
  targetPokemonIdx?: number
  projectedReward?: number
  [key: string]: unknown
}

export interface ClassDefinition {
  id: string
  name: string
  icon: string
  color: string
  colorDark: string
  description: string
  bonuses?: string[]
  bonusLevels?: number[]
  penalties?: string[]
  technicalBonuses?: string[]
  technicalPenalties?: string[]
  showdownSpriteId?: string
  avatarSpriteId?: string
}

interface ClassData {
  captureStreak?: number
  longestStreak?: number
  reputation?: number
  blackMarketSales?: number
  criminality?: number
  activeMission?: ActiveMission | null
  blackMarketDaily?: { date: string, items: unknown[], purchased: unknown[] }
  extortedRouteId?: string | null
  extortedRouteTimestamp?: string | null
  lastEggScanDate?: string | null
  officialRouteId?: string | null
  kitCaptures?: number
}



export const usePlayerClassStore = defineStore('playerClass', () => {
  const gameStore = useGameStore()
  const uiStore = useUIStore()

  const db = supabase

  // --- Getters ---
  const playerClass = computed(() => gameStore.state.playerClass)
  const classLevel = computed(() => gameStore.state.classLevel || 1)
  const classXP = computed(() => gameStore.state.classXP || 0)
  const classXPNeeded = computed(() => getXPNeededForClassLevel(classLevel.value))
  const classData = computed<ClassData>(() => (gameStore.state.classData as unknown as ClassData) || {})

  const currentClassDef = computed<ClassDefinition | null>(() => {
    if (!playerClass.value) return null
    return (PLAYER_CLASSES as Record<string, ClassDefinition>)[playerClass.value] || null
  })

  const activeMission = computed(() => classData.value.activeMission || null)

  /**
   * Obtiene modificadores de clase para batalla o economía.
   * Centraliza la lógica de getClassModifier() de legacy.
   */
  function getModifier(type: string, context: Record<string, unknown> = {}) {
    return getClassModifier(playerClass.value || '', type, {
      ...context,
      isPvP: (gameStore.state as { activeBattle?: { isPvP?: boolean } }).activeBattle?.isPvP
    })
  }

  /**
   * Sincroniza las variables CSS globales con el tema de la clase activa.
   */
  function syncTheme() {
    if (typeof document === 'undefined') return
    const root = document.documentElement
    const cls = currentClassDef.value

    if (!cls) {
      root.style.setProperty('--class-primary', '#3b82f6')
      root.style.setProperty('--class-dark', '#1e40af')
      return
    }

    root.style.setProperty('--class-primary', cls.color)
    root.style.setProperty('--class-dark', cls.colorDark)
  }

  watch(playerClass, () => syncTheme())

  // --- Actions ---

  /**
   * Selecciona o cambia la clase del jugador.
   */
  async function selectClass(classId: string) {
    const cls = (PLAYER_CLASSES as Record<string, ClassDefinition>)[classId]
    if (!cls) return { success: false, msg: 'Clase no válida' }

    const isChange = !!playerClass.value
    if (isChange) {
      const cost = 10000
      if ((gameStore.state.battleCoins || 0) < cost) {
        uiStore.notify(`Necesitas ${cost.toLocaleString()} Battle Coins para cambiar.`, '❌')
        return { success: false, msg: `Necesitas ${cost.toLocaleString()} Battle Coins para cambiar.` }
      }
      gameStore.state.battleCoins -= cost
    }

    // Reset de datos específicos y liberación de Pokémon en misión
    [...(gameStore.state.team || []), ...(gameStore.state.box || [])].forEach((p: Pokemon | null) => {
      if (p && p.onMission) p.onMission = false
    })

    // Lógica de transición de cosméticos de clase
    const currentAvatar = gameStore.state.avatar_style || ''
    if (currentAvatar) {
      const avatarDef = AVATAR_STYLES.find(a => a.id === currentAvatar)
      if (avatarDef && avatarDef.requiredClass) {
        const isSquare = currentAvatar.includes('-sq-')
        const classToStyleMap: Record<string, string> = {
          cazabichos: 'av-class-cazabichos',
          criador: 'av-class-criador',
          rocket: 'av-class-rocket',
          entrenador: 'av-class-entrenador'
        }

        const newBaseStyle = classToStyleMap[classId]
        if (newBaseStyle) {
          gameStore.state.avatar_style = isSquare 
            ? newBaseStyle.replace('av-class-', 'av-sq-')
            : newBaseStyle
        } else {
          gameStore.state.avatar_style = null // Volver al por defecto
        }
      }
    }

    gameStore.state.playerClass = classId
    gameStore.state.classLevel = 1
    gameStore.state.classXP = 0
    gameStore.state.classData = {
      captureStreak: 0,
      longestStreak: 0,
      reputation: 0,
      blackMarketSales: 0,
      criminality: 0,
      blackMarketDaily: { date: '', items: [], purchased: [] },
      extortedRouteId: null,
      officialRouteId: null,
      kitCaptures: 0
    }

    uiStore.notify(`¡Elegiste ser ${cls.name}!`, cls.icon)
    await gameStore.save(false)
    return { success: true }
  }

  /**
   * Establece la facción del jugador (Unión o Poder).
   */
  async function setFaction(factionId: string) {
    if (!['union', 'poder', 'rocket'].includes(factionId)) return { success: false }

    const currentFaction = gameStore.state.faction
    if (currentFaction === factionId) {
      uiStore.notify('Ya perteneces a este bando.', '⚠️')
      return { success: false }
    }

    // Costo de cambio (si ya tenía uno)
    if (currentFaction) {
      const cost = 25000
      if ((gameStore.state.money || 0) < cost) {
        uiStore.notify(`Necesitas 🪙 ${cost.toLocaleString()} para cambiar de bando.`, '❌')
        return { success: false }
      }
      gameStore.state.money -= cost
      uiStore.notify(`Cambiaste de bando por 🪙 ${cost.toLocaleString()}`, '💸')
    }

    gameStore.state.faction = factionId
    uiStore.notify(`¡Te uniste al Equipo ${factionId.toUpperCase()}!`, '🚩')
    await gameStore.save(false)
    return { success: true }
  }

  /**
   * Incrementa XP de clase y maneja las subidas de nivel.
   */
  function addXP(amount: number) {
    if (!playerClass.value || amount <= 0) return

    gameStore.state.classXP = (gameStore.state.classXP || 0) + amount
    const MAX_CLASS_LEVEL = 30

    let xpNeeded = getXPNeededForClassLevel(gameStore.state.classLevel)
    while (gameStore.state.classXP >= xpNeeded && gameStore.state.classLevel < MAX_CLASS_LEVEL) {
      gameStore.state.classXP -= xpNeeded
      gameStore.state.classLevel = (gameStore.state.classLevel || 1) + 1
      uiStore.notify(`¡Tu clase ${currentClassDef.value?.name || ''} subió al Nivel ${gameStore.state.classLevel}!`, '🎓')
      xpNeeded = getXPNeededForClassLevel(gameStore.state.classLevel)
    }
  }

  /**
   * Maneja el nivel de criminalidad del Rocket.
   */
  function addCriminality(amount: number) {
    if (playerClass.value !== 'rocket' || amount <= 0) return
    const currentData = gameStore.state.classData as ClassData
    const prev = currentData.criminality || 0
    currentData.criminality = prev + amount

    if (prev < 100 && currentData.criminality >= 100) {
      uiStore.notify("¡Nivel de criminalidad máximo! La policía te busca.", "🚔")
    }
  }

  /**
   * Inicia una misión idle con validación de tiempo del servidor.
   */
  async function startMission(missionId: string, extraData: Record<string, unknown> = {}) {
    const m = CLASS_MISSIONS.find(x => x.id === missionId)
    if (!m) return

    // Marcar pokemon como ocupado
    if (extraData.targetPokemonIdx !== undefined) {
      const p = gameStore.state.box[extraData.targetPokemonIdx as number]
      if (p) {
        if (p.hp <= 0) {
          uiStore.notify('No puedes enviar un Pokémon debilitado a una misión.', '⚠️')
          return
        }
        const teamIdx = gameStore.state.team.findIndex((tp: Pokemon | null) => tp && tp.uid === p.uid)
        if (teamIdx !== -1) {
          if (gameStore.state.team.length <= 1) {
            uiStore.notify('No puedes enviar a tu único Pokémon del equipo.', '⚠️')
            return
          }
          const tp = gameStore.state.team.splice(teamIdx, 1)[0]
          if (tp) {
            gameStore.state.box.push(tp)
            gameStore.autoFillPvpTeam()
            extraData.targetPokemonIdx = gameStore.state.box.findIndex((bp: Pokemon | null) => bp && bp.uid === tp.uid)
          }
        }
        p.onMission = true
      }
    }

    const now = await db.getServerTime()
    const currentData = gameStore.state.classData as unknown as ClassData

    currentData.activeMission = {
      id: missionId,
      startedAt: now as number,
      endsAt: (now as number) + (m.durationHs * 3600 * 1000),
      ...extraData
    }

    uiStore.notify(`¡Misión iniciada! (${m.durationHs}h)`, '📋')
    await gameStore.save(false)
  }

  /**
   * Finaliza y cobra una misión. (Implementación de Phase 21).
   */
  async function collectMission() {
    const mission = activeMission.value
    if (!mission) return

    const now = await db.getServerTime()
    if ((now as number) < mission.endsAt) {
      uiStore.notify('La misión aún no ha terminado.', '⏳')
      return;
    }

    const cls = playerClass.value
    let msg = 'Misión completada. '

    if (cls === 'rocket') {
      // Recompensa en dinero (el Pokémon ya no está)
      const reward = mission.projectedReward || 0
      gameStore.state.battleCoins = (gameStore.state.battleCoins || 0) + reward
      msg += `¡Recibiste ₽${reward.toLocaleString()}! 🚀`

      // Eliminar el Pokémon de la caja (sacrificio)
      if (mission.targetPokemonIdx !== undefined) {
        const p = gameStore.state.box[mission.targetPokemonIdx]
        if (p) {
          if (p.heldItem) {
            const invStore = useInventoryStore()
            invStore.addItem(p.heldItem, 1)
          }
          p.onMission = false
          gameStore.removePokemon(p.uid)
        }
      }
    } else if (cls === 'cazabichos') {
      // Aquí iría la lógica de generar encuentros salvajes bicho o recompensas de IVs
      msg += '¡Nuevos Pokémon Bicho avistados!'
    } else if (cls === 'entrenador') {
      // Recompensa en EXP para el Pokémon enviado
      if (mission.targetPokemonIdx !== undefined) {
        const p = gameStore.state.box[mission.targetPokemonIdx]
        if (p) {
          p.onMission = false;
          if (p.level >= MAX_POKEMON_LEVEL) {
            p.exp = 0;
            p.expNeeded = Infinity;
            msg += `¡${p.name} ya está en su nivel máximo! 🏅`
          } else {
            const blocks = (mission.endsAt - mission.startedAt) / (3600000 * 6) // bloques de 6h
            const expGain = (25000 + (p.level || 1) * 1000) * blocks;
            p.exp = (p.exp || 0) + expGain;
            msg += `¡${p.name} ganó ${expGain.toLocaleString()} EXP! 🏅`
            gameStore.checkLevelUp(p)
          }
        }
      }
    } else if (cls === 'criador') {
      // Recompensa en IVs aleatorios a cambio de Vigor
      if (mission.targetPokemonIdx !== undefined) {
        const p = gameStore.state.box[mission.targetPokemonIdx]
        if (p) {
          const stats = ['hp', 'atk', 'def', 'spa', 'spd', 'spe'] as const;
          const stat = stats[Math.floor(Math.random() * stats.length)];
          if (stat) {
            const gain = Math.floor(Math.random() * 3) + 1;
            if (!p.ivs) p.ivs = { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 };
            const curVal = p.ivs[stat] || 0;
            p.ivs[stat] = Math.min(31, curVal + gain);
            p.vigor = Math.max(0, (p.vigor || 20) - 5);
            p.onMission = false;
            msg += `¡${p.name} mejoró su ${String(stat).toUpperCase()} (+${gain})! 🧬`
          }
        }
      }
    } else {
      // Liberar al Pokémon que estaba en misión
      if (mission.targetPokemonIdx !== undefined) {
        const p = gameStore.state.box[mission.targetPokemonIdx]
        if (p) p.onMission = false
      }
      msg += 'Tus Pokémon han regresado con éxito.'
    }

    const currentData = gameStore.state.classData as ClassData
    currentData.activeMission = null
    uiStore.notify(msg, '🎁')
    await gameStore.save()
  }

  return {
    playerClass,
    classLevel,
    classXP,
    classXPNeeded,
    classData,
    currentClassDef,
    activeMission,
    getModifier,
    selectClass,
    addXP,
    addCriminality,
    startMission,
    collectMission,
    setFaction,
    syncTheme
  }
})

import { defineStore } from 'pinia'
import { ref, computed, watch } from 'vue'

import { useAuthStore } from './auth.ts'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { logger } from '@/logic/utils/logger'
import { RANKED_REWARD_MILESTONES } from '@/data/rankedData'
export { RANKED_REWARD_MILESTONES }
import { getEloTier } from '@/logic/pvp/rankedEngine'
import type { Pokemon } from '@/types/pokemon'
import { GAME_TIMEZONE, parseZonedTime } from '@/logic/utils/timeUtils'


export const RANKED_REWARD_TIER_MARKS = [
  { name: 'Plata', elo: 1200, color: '#9E9E9E' },
  { name: 'Oro', elo: 1600, color: '#FFB800' },
  { name: 'Platino', elo: 2100, color: '#E5C100' },
  { name: 'Diamante', elo: 2700, color: '#89CFF0' },
  { name: 'Maestro', elo: 3400, color: '#FFD700' }
]

interface PvPStats {
  wins: number
  losses: number
  draws: number
}

interface SeasonRules {
  name: string
  startDate?: string
  endDate?: string
  seasonStartDate?: string
  seasonEndDate?: string
  bannedPokemonIds?: string[]
  levelCap: number
  allowedTypes?: string[]
  maxPokemon: number
  [key: string]: unknown
}

interface LeaderboardEntry {
  id: string
  username: string | null
  elo_rating: number
  trainer_level: number
  player_class: string
  nick_style: string | null
  avatar_style: string | null
}

/**
 * usePvPStore - Gestor de Arena Clasificatoria y Defensa Pasiva.
 * Centraliza el ELO, las temporadas y el registro de equipos competitivos.
 */
export const usePvPStore = defineStore('pvp', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()
  const uiStore = useUIStore()

  const elo = ref(1000)
  const stats = ref<PvPStats>({ wins: 0, losses: 0, draws: 0 })
  const maxElo = ref(1000)
  const rewardsClaimed = ref<string[]>([])
  const passiveTeamActive = ref(false)
  const currentSeasonRules = ref<SeasonRules | null>(null)
  const leaderboard = ref<LeaderboardEntry[]>([])
  const lastSyncAt = ref<number | null>(null)
  const isLoading = ref(false)
  const error = ref('')

  // Sync ELO with game state
  watch(() => gameStore.state.eloRating, (newElo) => {
    if (newElo !== undefined) elo.value = newElo
  }, { immediate: true })

  const eloTier = computed(() => getEloTier(elo.value))

  async function loadPvPData() {
    if (!authStore.user || !gameStore.db) return

    interface ProfileRow {
      elo_rating: number;
      pvp_wins: number;
      pvp_losses: number;
      pvp_draws: number;
      role: string;
    }
    const { data: profile } = await gameStore.db.from('profiles')
      .select('elo_rating, pvp_wins, pvp_losses, pvp_draws, role')
      .eq('id', authStore.user.id)
      .single() as { data: ProfileRow | null }

    if (profile) {
      elo.value = profile.elo_rating || 1000
      stats.value = { 
        wins: profile.pvp_wins || 0, 
        losses: profile.pvp_losses || 0, 
        draws: profile.pvp_draws || 0 
      }

      // Admin Check (requested by user)
      if (profile.role === 'admin' && authStore.user) {
        authStore.user.role = 'admin'
      }
    }

    // Sync maxElo from game state for rewards
    maxElo.value = (gameStore.state.rankedMaxElo as number) || elo.value
    rewardsClaimed.value = (gameStore.state.rankedRewardsClaimed as string[]) || []

    const { data: passive } = await gameStore.db.from('passive_teams')
      .select('is_active')
      .eq('user_id', authStore.user.id)
      .maybeSingle() as { data: { is_active: boolean } | null }

    passiveTeamActive.value = passive?.is_active || false

    await fetchSeasonRules()
  }

  async function fetchSeasonRules() {
    if (!gameStore.db) return
    const { data } = await gameStore.db.from('ranked_rules_config').select('*').eq('id', 'current').maybeSingle() as { data: { season_name: string, config: string | Record<string, unknown> } | null }
    if (data) {
      const configObj = typeof data.config === 'string' ? JSON.parse(data.config || '{}') : (data.config || {})
      currentSeasonRules.value = {
        name: data.season_name,
        ...configObj
      }
    }
  }

  async function fetchLeaderboard(force = false) {
    if (!force && lastSyncAt.value && (Temporal.Now.instant().epochMilliseconds - lastSyncAt.value < 1800000)) {
      return // 30 min cache
    }

    isLoading.value = true
    error.value = ''

    try {
      if (!gameStore.db) return
      const { data, error: err } = await (gameStore.db
        .from('profiles')
        .select('id, username, elo_rating, trainer_level, player_class, nick_style, avatar_style')
        .not('username', 'is', null)
        .order('elo_rating', { ascending: false })
        .limit(100) as unknown as Promise<{ data: LeaderboardEntry[] | null, error: { message: string } | null }>)

      if (err) throw err
      leaderboard.value = (data || []) as LeaderboardEntry[]
      lastSyncAt.value = Temporal.Now.instant().epochMilliseconds
    } catch (e) {
      error.value = 'No se pudo cargar el ranking global.'
      logger.error('PvP', `Leaderboard error: ${(e as Error).message}`)
    } finally {
      isLoading.value = false
    }
  }

  async function togglePassiveTeam() {
    const newState = !passiveTeamActive.value

    if (newState) {
      if (!gameStore.db || !authStore.user) return
      // Create Snapshot
      const snapshot = (gameStore.state.team as Pokemon[]).map((p) => ({
        id: p.id,
        name: p.name,
        level: p.level,
        type: p.type,
        hp: p.hp,
        maxHp: p.maxHp,
        atk: p.atk,
        def: p.def,
        spa: p.spa,
        spd: p.spd,
        spe: p.spe,
        moves: p.moves.filter(m => !!m).map((m) => ({ name: m!.name, pp: m!.maxPP || 20 })),
        heldItem: p.heldItem,
        isShiny: p.isShiny
      }))

      const { error } = await gameStore.db.from('passive_teams').upsert({
        user_id: authStore.user.id,
        team_data: JSON.stringify(snapshot),
        is_active: true,
        updated_at: Temporal.Now.instant().toString()
      })

      if (!error) {
        passiveTeamActive.value = true
        uiStore.notify('Equipo de Defensa Pasiva activado.', '🛡️')
      }
    } else {
      if (!gameStore.db || !authStore.user) return
      await gameStore.db.from('passive_teams').update({ is_active: false }).eq('user_id', authStore.user.id)
      passiveTeamActive.value = false
      uiStore.notify('Defensa Pasiva desactivada.', '⏸️')
    }
  }

  async function claimReward(milestoneId: string) {
    if (rewardsClaimed.value.includes(milestoneId)) return

    const milestone = RANKED_REWARD_MILESTONES.find(m => m.id === milestoneId)
    if (!milestone) return

    if (maxElo.value < milestone.elo) {
      uiStore.notify('Hito no alcanzado', '⚠️')
      return
    }

    // Add items to inventory
    const inventory = gameStore.state.inventory as Record<string, number>
    Object.entries(milestone.rewards).forEach(([itemName, qty]) => {
      inventory[itemName] = (inventory[itemName] || 0) + (qty as number)
    })

    rewardsClaimed.value.push(milestoneId)
    gameStore.state.rankedRewardsClaimed = [...rewardsClaimed.value]
    uiStore.notify('¡Recompensa reclamada!', '🎁')
    await gameStore.saveGame(true)
  }

  const seasonRange = computed(() => {
    const rules = currentSeasonRules.value || { name: 'Default', levelCap: 100, maxPokemon: 6 } as SeasonRules

    const start = parseZonedTime(rules.startDate || rules.seasonStartDate, '2026-04-01T00:00:00')

    const defaultEndStr = start.add({ months: 3 }).toString()
    const end = parseZonedTime(rules.endDate || rules.seasonEndDate, defaultEndStr)

    const now = Temporal.Now.zonedDateTimeISO(GAME_TIMEZONE)
    const diff = end.since(now, { largestUnit: 'day' })
    const daysLeft = Math.max(0, Math.ceil(diff.days))

    return {
      start: start.toInstant(),
      end: end.toInstant(),
      daysLeft
    }
  })

  async function updateElo(won: boolean) {
    if (!authStore.user || !gameStore.db) return 0

    const delta = won ? 15 + Math.floor(Math.random() * 5) : -(10 + Math.floor(Math.random() * 5))
    elo.value = Math.max(0, elo.value + delta)

    if (won) {
      stats.value.wins++
      if (elo.value > maxElo.value) {
        maxElo.value = elo.value
        gameStore.state.rankedMaxElo = maxElo.value
      }
    } else {
      stats.value.losses++
    }

    // Save to DB
    await gameStore.db.from('profiles').update({
      elo_rating: elo.value,
      pvp_wins: stats.value.wins,
      pvp_losses: stats.value.losses
    }).eq('id', authStore.user.id)

    gameStore.save(false)
    return delta
  }

  return {
    elo,
    stats,
    maxElo,
    eloTier,
    rewardsClaimed,
    passiveTeamActive,
    currentSeasonRules,
    seasonRange,
    loadPvPData,
    togglePassiveTeam,
    claimReward,
    updateElo,
    fetchLeaderboard,
    leaderboard,
    isLoading,
    error,
    rules: currentSeasonRules,
    currentTier: getEloTier
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { useWarStore } from './war.ts'
import type { Pokemon, Move } from '@/types/pokemon'
import { getItemById, SHOP_ITEMS, ITEM_CATEGORIES, CATEGORY_LABELS } from '@/data/items'
import { PLAYER_CLASSES } from '@/data/playerClasses'
import { TRAINER_RANKS } from '@/data/trainer'
import { calculateTotalHealCost } from '@/logic/economy/economyFormulas'

import { clearVolatileStatus } from '@/logic/battle/battleStatus'

export const useShopStore = defineStore('shop', () => {
  const gameStore = useGameStore()
  const uiStore = useUIStore()
  const warStore = useWarStore()


  const marketCategory = ref('todos')
  const searchQuery = ref('')
  const quantities = ref<Record<string, number>>({})

  const getTrainerRank = computed(() => {
    const lv = gameStore.state.trainerLevel || 1
    const idx = Math.min(lv - 1, TRAINER_RANKS.length - 1)
    return TRAINER_RANKS[idx]
  })

  function getQuantity(itemId: string) {
    return quantities.value[itemId] || 1
  }

  function setQuantity(itemId: string, val: string | number) {
    let q = parseInt(String(val))
    if (isNaN(q) || q < 1) q = 1
    if (q > 999) q = 999
    quantities.value[itemId] = q
  }

  /**
   * Calculates the price modifier based on player class.
   */
  function getPriceModifier() {
    const playerClass = gameStore.state.playerClass
    if (!playerClass) return 1.0

    const classDef = (PLAYER_CLASSES as Record<string, { modifiers?: Record<string, number> }>)[playerClass || '']
    if (!classDef || !classDef.modifiers) return 1.0

    // For regular shop, we use the recargo penalty if member of Rocket
    if ((playerClass as string) === 'rocket') return 1.20 
    return 1.0
  }

  function buyItem(itemId: string) {
    const item = getItemById(itemId)
    if (!item) return

    if (gameStore.state.trainerLevel < (item.unlockLv || 1)) {
      uiStore.notify('¡Item bloqueado!', '🔒')
      return
    }

    const qty = getQuantity(itemId)
    let unitPrice = item.price
    unitPrice = Math.floor(unitPrice * getPriceModifier())

    const total = unitPrice * qty

    if (gameStore.state.money < total) {
      uiStore.notify('¡No tenés suficiente dinero!', '💸')
      return
    }

    // Process purchase
    gameStore.state.money -= total
    gameStore.state.inventory[item.id] = (gameStore.state.inventory[item.id] || 0) + qty

    // Process special category effects (like balls count)
    if (item.cat === 'pokeballs') {
       const mult = item.id === 'great_ball' ? 1.5 : (item.id === 'ultra_ball' ? 2 : 1)
       gameStore.state.balls = (gameStore.state.balls || 0) + Math.floor(qty * mult)
    }

    uiStore.notify(`¡Compraste x${qty} ${item.name}!`, item.icon)
    uiStore.notify(`Gastaste ₽${total.toLocaleString()}`, '💸')
    gameStore.scheduleSave()
  }

  function buyItemBC(itemId: string) {
    const item = getItemById(itemId)
    if (!item || !item.showInBCShop) return

    const bcPrice = item.bcPrice || 0

    if (gameStore.state.trainerLevel < (item.unlockLv || 1)) {
      uiStore.notify('¡Ítem bloqueado!', '🔒')
      return
    }

    if ((gameStore.state.battleCoins || 0) < bcPrice) {
      uiStore.notify('¡No tenés suficientes Battle Coins!', '💰')
      return
    }

    gameStore.state.battleCoins = (gameStore.state.battleCoins || 0) - bcPrice
    gameStore.state.inventory[item.id] = (gameStore.state.inventory[item.id] || 0) + 1

    if (item.cat === 'pokeballs') {
       const mult = item.id === 'great_ball' ? 1.5 : (item.id === 'ultra_ball' ? 2 : 1)
       gameStore.state.balls = (gameStore.state.balls || 0) + Math.floor(1 * mult)
    }

    uiStore.notify(`¡Compraste ${item.name}!`, '🏅')
    uiStore.notify(`Gastaste ${bcPrice} BC`, '🪙')
    gameStore.scheduleSave()
  }

  function buyItemWar(itemId: string) {
    const item = getItemById(itemId)
    if (!item || !item.showInWarShop) return

    const warPrice = item.warPrice || 0

    if (gameStore.state.trainerLevel < (item.unlockLv || 1)) {
      uiStore.notify('¡Ítem bloqueado!', '🔒')
      return
    }

    if ((warStore.warCoins || 0) < warPrice) {
      uiStore.notify('¡No tenés suficientes Monedas de Guerra!', '⚡')
      return
    }

    // Deduct coins
    warStore.warCoins -= warPrice
    gameStore.state.warCoins = warStore.warCoins

    // Add to inventory
    gameStore.state.inventory[item.id] = (gameStore.state.inventory[item.id] || 0) + 1

    uiStore.notify(`¡Compraste ${item.name}!`, '⚔️')
    uiStore.notify(`Gastaste ${warPrice} Monedas de Guerra`, '⚡')
    gameStore.scheduleSave()
  }

  // ── POKÉMON CENTER HEALING ─────────────────────────────────────────────────

  function getHealCost() {
    return calculateTotalHealCost(
      gameStore.state.team, 
      gameStore.state.trainerLevel || 1, 
      gameStore.state.playerClass || ''
    )
  }

  function healAllPokemon(manualCost: number | null = null) {
    const costToCharge = manualCost !== null ? manualCost : getHealCost()

    if (gameStore.state.money < costToCharge) {
      uiStore.notify('No tenés suficiente dinero para la enfermería.', '💸')
      return false
    }

    gameStore.state.money -= costToCharge
    gameStore.state.lastPokemonCenterHeal = Temporal.Now.instant().epochMilliseconds

    // Restore all pokemon in team
    gameStore.state.team.forEach((p: Pokemon | null) => {
      if (!p) return;
      p.hp = p.maxHp;
      p.status = null;
      clearVolatileStatus(p);
      if (p.moves) {
        p.moves.forEach((m: Move | null) => {
          if (m) m.pp = m.maxPP || 20;
        });
      }
    });

    if (costToCharge > 0) {
      uiStore.notify(`¡Sanación pagada! Gastaste ₽${costToCharge.toLocaleString()}`, '💰')
    } else {
      uiStore.notify('¡Tus Pokémon están totalmente recuperados!', '🏥')
    }

    gameStore.scheduleSave()
    return true
  }

  // ── BLACK MARKET (TEAM ROCKET) ─────────────────────────────────────────────

  function getBlackMarketItems() {
    if (gameStore.state.playerClass !== 'rocket') return []

    if (!gameStore.state.classData) {
      gameStore.state.classData = {
        captureStreak: 0,
        longestStreak: 0,
        reputation: 0,
        blackMarketSales: 0,
        criminality: 0,
        blackMarketDaily: { date: '', items: [], purchased: [] }
      }
    }
    if (!gameStore.state.classData.blackMarketDaily) {
      gameStore.state.classData.blackMarketDaily = { date: '', items: [], purchased: [] }
    }

    const today = Temporal.Now.instant().toString().split('T')[0] || ''
    const daily = gameStore.state.classData.blackMarketDaily

    if (daily.date !== today) {
      const possibleItems = SHOP_ITEMS.filter(i => i.showInBCShop === true && (i.bcPrice || 0) > 0)
      const shuffled = [...possibleItems].sort(() => 0.5 - Math.random())
      const bmd = gameStore.state.classData?.blackMarketDaily
      if (bmd) {
        bmd.items = shuffled.slice(0, 3).map(i => (i.id || '') as string)
        if (bmd) bmd.date = today
        bmd.purchased = [] as string[]
      }
      gameStore.scheduleSave()
    }

    return daily.items.map((id: string) => getItemById(id)).filter(Boolean)
  }

  function buyBlackMarketItem(itemId: string) {
    if (gameStore.state.playerClass !== 'rocket') return
    const daily = gameStore.state.classData.blackMarketDaily
    if (!daily || !daily.items.includes(itemId)) return

    if (daily.purchased.includes(itemId)) {
      useUIStore().notify('Ya compraste este objeto hoy.', '🚫')
      return
    }

    const item = getItemById(itemId)
    if (!item) return

    const discount = PLAYER_CLASSES.rocket.modifiers?.shopDiscount || 0.20
    const priceInMoney = Math.floor(((item.bcPrice || 0) * 50) * (1 - discount))

    if (gameStore.state.money < priceInMoney) {
      useUIStore().notify('No tenés suficiente dinero (₽).', '❌')
      return
    }

    gameStore.state.money -= priceInMoney
    daily.purchased.push(itemId)

    // Add to inventory
    gameStore.state.inventory[item.id] = (gameStore.state.inventory[item.id] || 0) + 1

    useUIStore().notify(`¡Compraste ${item.name} en el Mercado Negro! 🚀`, '💰')
    gameStore.scheduleSave()
  }

  return {
    marketCategory,
    searchQuery,
    ITEM_CATEGORIES,
    CATEGORY_LABELS,
    SHOP_ITEMS,
    getTrainerRank,
    getQuantity,
    setQuantity,
    buyItem,
    buyItemBC,
    healAllPokemon,
    getHealCost,
    getBlackMarketItems,
    buyBlackMarketItem,
    buyItemWar
  }
})

import { defineStore } from 'pinia'
import { ref, reactive, watch, computed } from 'vue'
import { gsap } from 'gsap'

import { useAuthStore } from './auth.ts'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { useAudioStore } from './audio.ts'
import { useChatStore } from './chat.ts'
import { useLeaderboardStore } from './leaderboard.ts'
import { usePlayerSearchStore } from './playerSearch.ts'
import { logger } from '@/logic/utils/logger'
import { parseInstantSafe } from '@/logic/utils/timeUtils'
import type { GameState } from '@/types/game'


export interface Friend {
  id: string;
  username: string;
  level: number;
  badges: number;
  playerClass?: string;
  faction?: string;
  nick_style?: string;
  avatar_style?: string;
  gender?: string;
  isOnline: boolean;
  lastSeen: Temporal.Instant | null;
}

export interface PendingRequest {
  id: string;
  requester_id: string;
  status: string;
  profiles?: { 
    username: string;
    level?: number;
    trainer_level?: number;
    playerClass?: string;
    player_class?: string;
    full_name?: string;
    nick_style?: string;
    avatar_style?: string;
    gender?: string;
    save_data?: GameState;
  };
}

export interface SearchResult {
  id: string;
  username: string;
  level: number;
  playerClass?: string;
  faction?: string;
  nick_style?: string;
  avatar_style?: string;
  gender?: string;
  status: string;
  relId: string | null;
  isRequester: boolean;
}

export interface LeaderboardEntry {
  id: string;
  username: string;
  level: number;
  badges: number;
  elo: number;
  playerClass?: string;
  faction?: string;
  nick_style?: string;
  avatar_style?: string;
  gender?: string;
  isOnline?: boolean;
}

interface FriendshipRow {
  id: string
  requester_id: string
  addressee_id: string
  status: string
}

interface ProfileRow {
  id: string
  username: string
  elo_rating?: number
  trainer_level?: number
  badges?: number
  player_class?: string
  faction?: string
  nick_style?: string
  avatar_style?: string
  gender?: string
}

interface GameSaveRow {
  user_id: string
  save_data: Record<string, unknown>
  updated_at: string
}

export const useSocialStore = defineStore('social', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()
  const uiStore = useUIStore()
  const audioStore = useAudioStore()
  const leaderboardStore = useLeaderboardStore()
  const playerSearchStore = usePlayerSearchStore()

  const friends = ref<Friend[]>([])
  const pendingRequests = ref<PendingRequest[]>([])
  const searchResults = computed<SearchResult[]>({
    get: () => playerSearchStore.searchResults,
    set: (val: SearchResult[]) => { playerSearchStore.searchResults = val }
  })
  const searchLoading = computed<boolean>({
    get: () => playerSearchStore.searchLoading,
    set: (val: boolean) => { playerSearchStore.searchLoading = val }
  })
  const loading = ref(false)
  const sentRequestTimestamps = ref<number[]>([])

  const notifications = reactive({
    friends: 0,
    trades: 0,
    battles: 0,
    chats: 0,
    total: 0
  })

  watch(() => {
    const chatStore = useChatStore()
    return chatStore.totalUnreadChats
  }, (unread) => {
    notifications.chats = unread
    notifications.total = notifications.friends + notifications.trades + notifications.battles + notifications.chats
  }, { immediate: true })

  let presenceInterval: gsap.core.Tween | null = null

  /**
   * Carga datos sociales (amigos y solicitudes) usando DBRouter.
   */
  async function loadSocialData() {
    if (!authStore.user) {
      friends.value = []
      pendingRequests.value = []
      return
    }

    loading.value = true
    const db = gameStore.db
    if (!db) { loading.value = false; return }

    try {
      // 1. Obtener amistades confirmadas
      const { data: friendships, error: fErr } = await db
        .from('friendships')
        .select('*')
        .or(`requester_id.eq.${authStore.user.id},addressee_id.eq.${authStore.user.id}`)
        .eq('status', 'accepted') as { data: FriendshipRow[] | null; error: unknown }

      if (fErr) throw fErr

      if (friendships && friendships.length > 0) {
        const friendIds = friendships.map((f: FriendshipRow) => 
          f.requester_id === authStore.user?.id ? f.addressee_id : f.requester_id
        )

        const [profRes, saveRes] = await Promise.all([
          db.from('profiles').select('*').in('id', friendIds),
          db.from('game_saves').select('user_id,save_data,updated_at').in('user_id', friendIds)
        ]) as [
          { data: ProfileRow[] | null; error: unknown },
          { data: GameSaveRow[] | null; error: unknown }
        ]

        friends.value = friendIds.map((fId: string) => {
          const p = (profRes.data as ProfileRow[] || []).find((prof: ProfileRow) => prof.id === fId)
          const saveRow = (saveRes.data as GameSaveRow[])?.find((s: GameSaveRow) => s.user_id === fId)
          const save = saveRow?.save_data ? (typeof saveRow.save_data === 'string' ? JSON.parse(saveRow.save_data) : saveRow.save_data) as Partial<GameState> : {} as Partial<GameState>
          const lastSeen = parseInstantSafe(saveRow?.updated_at)
          const isOnline = !!(lastSeen && (Temporal.Now.instant().epochMilliseconds - lastSeen.epochMilliseconds) < 5 * 60 * 1000)

          const fallbackName = fId.startsWith('local_') ? fId.replace('local_', '') : 'Entrenador'
          const capitalizedFallback = fallbackName.charAt(0).toUpperCase() + fallbackName.slice(1)
          const username = (save.trainer as string) || p?.username || capitalizedFallback

          return {
            id: fId,
            username,
            level: (save.trainerLevel as number) || p?.trainer_level || 1,
            badges: typeof save.badges === 'object' ? Object.keys(save.badges).length : ((save.badges as number) || 0),
            playerClass: (save.playerClass as string) || p?.player_class || '',
            faction: (save.faction as string) || p?.faction || '',
            nick_style: (save.nick_style as string) || p?.nick_style || '',
            avatar_style: (save.avatar_style as string) || p?.avatar_style || '',
            gender: (save.gender as string) || p?.gender || 'h',
            isOnline,
            lastSeen
          }
        })
      } else {
        friends.value = []
      }

      // 2. Solicitudes pendientes
      const { data: pending } = await db
        .from('friendships')
        .select('*')
        .eq('addressee_id', authStore.user?.id)
        .eq('status', 'pending') as { data: PendingRequest[] | null; error: unknown }

      if (pending && pending.length > 0) {
        const requesterIds = pending.map((r: PendingRequest) => r.requester_id)
        const [profRes, saveRes] = await Promise.all([
          db.from('profiles').select('*').in('id', requesterIds),
          db.from('game_saves').select('user_id,save_data').in('user_id', requesterIds)
        ]) as [
          { data: ProfileRow[] | null; error: unknown },
          { data: GameSaveRow[] | null; error: unknown }
        ]

        const profilesMap = requesterIds.reduce((acc, reqId) => {
          const p = (profRes.data || []).find((prof: ProfileRow) => prof.id === reqId)
          const saveRow = (saveRes.data || []).find((s: GameSaveRow) => s.user_id === reqId)
          const save = saveRow?.save_data ? (typeof saveRow.save_data === 'string' ? JSON.parse(saveRow.save_data) : saveRow.save_data) as Partial<GameState> : {} as Partial<GameState>

          const fallbackName = reqId.startsWith('local_') ? reqId.replace('local_', '') : 'Entrenador'
          const capitalizedFallback = fallbackName.charAt(0).toUpperCase() + fallbackName.slice(1)
          const username = (save.trainer as string) || p?.username || capitalizedFallback

          acc[reqId] = {
            username,
            nick_style: (save.nick_style as string) || p?.nick_style || '',
            trainer_level: (save.trainerLevel as number) || p?.trainer_level || 1,
            player_class: (save.playerClass as string) || p?.player_class || 'entrenador',
            avatar_style: (save.avatar_style as string) || p?.avatar_style || '',
            gender: (save.gender as string) || p?.gender || 'h'
          }
          return acc
        }, {} as Record<string, { username: string; nick_style: string; trainer_level: number; player_class: string; avatar_style: string; gender: string }>)

        pending.forEach((r: PendingRequest) => {
          const profInfo = profilesMap[r.requester_id]
          if (profInfo) {
            r.profiles = {
              username: profInfo.username,
              nick_style: profInfo.nick_style,
              trainer_level: profInfo.trainer_level,
              player_class: profInfo.player_class,
              playerClass: profInfo.player_class,
              level: profInfo.trainer_level,
              avatar_style: profInfo.avatar_style,
              gender: profInfo.gender
            }
          }
        })
      }

      pendingRequests.value = (pending || []) as PendingRequest[]

      await refreshNotificationCount()
    } catch (err) {
      logger.error('Social', `Error loading data: ${(err as Error).message}`)
    } finally {
      loading.value = false
    }
  }

  async function searchPlayers(query: string, filters?: { playerClass?: string; faction?: string }) {
    await playerSearchStore.searchPlayers(query, filters)
  }

  async function sendFriendRequest(targetId: string) {
    if (!gameStore.db || !authStore.user) return

    const now = Temporal.Now.instant().epochMilliseconds
    sentRequestTimestamps.value = sentRequestTimestamps.value.filter(t => now - t < 60000)

    if (sentRequestTimestamps.value.length >= 10) {
      uiStore.notify('Límite de solicitudes de amistad alcanzado (máx. 10 por minuto)', '⚠️')
      return
    }

    const { error } = await gameStore.db.from('friendships').insert({
      requester_id: authStore.user?.id,
      addressee_id: targetId,
      status: 'pending'
    })

    if (error) {
      uiStore.notify('Error al enviar solicitud', '❌')
    } else {
      sentRequestTimestamps.value.push(now)
      uiStore.notify('Solicitud enviada correctamente', '👥')
      audioStore.sentMsg() // Sonido al enviar solicitud
      const res = searchResults.value.find((p: SearchResult) => p.id === targetId)
      if (res) { 
        res.status = 'pending';
        res.isRequester = true 
      }
    }
  }

  async function respondRequest(fId: string, status: string) {
    if (!gameStore.db) return
    const { error } = await gameStore.db.from('friendships').update({ status }).eq('id', fId)
    if (!error) {
      uiStore.notify(status === 'accepted' ? '¡Amistad aceptada!' : 'Solicitud rechazada', '✅')
      await loadSocialData()
    }
  }

  async function removeFriend(targetId: string) {
    if (!authStore.user || !gameStore.db) return
    const { error } = await gameStore.db.from('friendships')
      .delete()
      .or(`and(requester_id.eq.${authStore.user?.id},addressee_id.eq.${targetId}),and(requester_id.eq.${targetId},addressee_id.eq.${authStore.user?.id})`)

    if (!error) {
      uiStore.notify('Amigo eliminado', '👋')
      const chatStore = useChatStore()
      chatStore.closeChat(targetId)
      await loadSocialData()
    }
  }

  async function refreshNotificationCount() {
    if (!authStore.user) return

    const db = gameStore.db
    if (!db) return
    const [
      res1,
      res2,
      res3,
      res4
    ] = await Promise.all([
      db.from('friendships').select('id', { count: 'exact', head: true }).eq('addressee_id', authStore.user?.id).eq('status', 'pending'),
      db.from('trade_offers').select('id', { count: 'exact', head: true }).eq('receiver_id', authStore.user?.id).eq('status', 'pending'),
      db.from('trade_offers').select('id', { count: 'exact', head: true }).eq('sender_id', authStore.user?.id).eq('status', 'accepted'),
      db.from('battle_invites').select('id', { count: 'exact', head: true }).eq('opponent_id', authStore.user?.id).eq('status', 'pending').gte('created_at', Temporal.Now.instant().subtract({ seconds: 60 }).toString())
    ])

    notifications.friends = res1.count || 0
    notifications.trades = (res2.count || 0) + (res3.count || 0)
    notifications.battles = res4.count || 0
    notifications.total = notifications.friends + notifications.trades + notifications.battles + notifications.chats
  }

  /**
   * Re-fetches the updated_at for all current friends and recalculates isOnline.
   * Lightweight — only queries game_saves for friend IDs already loaded.
   */
  async function refreshFriendsPresence() {
    const db = gameStore.db
    if (!db || friends.value.length === 0) return
    try {
      const ids = friends.value.map(f => f.id)
      const { data } = await db
        .from('game_saves')
        .select('user_id, updated_at')
        .in('user_id', ids) as { data: { user_id: string; updated_at: string }[] | null }

      if (!data) return
      const now = Temporal.Now.instant().epochMilliseconds
      friends.value = friends.value.map(f => {
        const row = data.find(r => r.user_id === f.id)
        const lastSeen = parseInstantSafe(row?.updated_at)
        return {
          ...f,
          lastSeen,
          isOnline: !!(lastSeen && (now - lastSeen.epochMilliseconds) < 5 * 60 * 1000)
        }
      })
    } catch (err) {
      logger.warn('Social', `refreshFriendsPresence error: ${(err as Error).message}`)
    }
  }

  function startPresence() {
    if (presenceInterval) presenceInterval.kill()
    if (authStore.sessionMode === 'offline') return

    const ping = async () => {
      if (!authStore.user || !gameStore.db) return
      await gameStore.db.from('game_saves').update({ 
        updated_at: Temporal.Now.instant().toString() 
      }).eq('user_id', authStore.user?.id)

      // Refresh friends' presence on every ping cycle
      await refreshFriendsPresence()

      presenceInterval = gsap.delayedCall(60, ping)
    }

    ping()
  }

  function stopPresence() {
    if (presenceInterval) presenceInterval.kill()
    presenceInterval = null
  }

  const leaderboard = computed<LeaderboardEntry[]>({
    get: () => leaderboardStore.leaderboard,
    set: (val: LeaderboardEntry[]) => { leaderboardStore.leaderboard = val }
  })
  const leaderboardLoading = computed<boolean>({
    get: () => leaderboardStore.leaderboardLoading,
    set: (val: boolean) => { leaderboardStore.leaderboardLoading = val }
  })

  async function fetchLeaderboard(sortBy = 'elo_rating') {
    await leaderboardStore.fetchLeaderboard(sortBy)
  }

  return {
    friends,
    pendingRequests,
    searchResults,
    searchLoading,
    loading,
    notifications,
    leaderboard,
    leaderboardLoading,
    loadSocialData,
    searchPlayers,
    sendFriendRequest,
    respondRequest,
    removeFriend,
    startPresence,
    stopPresence,
    refreshFriendsPresence,
    refreshNotificationCount,
    fetchLeaderboard
  }
})

import { defineStore } from 'pinia'
import { ref, reactive, computed } from 'vue'
import { useAuthStore } from './auth.ts'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { useSocialStore } from './social.ts'
import { useAudioStore } from './audio.ts'
import { useLoadingStore } from './loading.ts'
import { logger } from '@/logic/utils/logger'
import { validateTradeOffer } from '@/logic/validation/schemas'
import type { 
  TradeOffer
} from '@/types/stores'
import type { Pokemon } from '@/types/pokemon'
import type { GameState } from '@/types/game'
import type { RealtimeChannel } from '@supabase/supabase-js'

export const useTradeStore = defineStore('trade', () => {
  const authStore = useAuthStore()
  const gameStore = useGameStore()
  const uiStore = useUIStore()
  const socialStore = useSocialStore()
  const audioStore = useAudioStore()
  const loadingStore = useLoadingStore()

  const tradeTarget = ref<{ id: string; username: string } | null>(null)
  const tradeFriendSave = ref<GameState | null>(null)

  const tradeOfferPoke = ref<Pokemon | null>(null)
  const tradeRequestPoke = ref<Pokemon | null>(null)
  const tradeOfferItems = reactive<Record<string, number>>({})
  const tradeRequestItems = reactive<Record<string, number>>({})

  const pendingIncoming = ref<TradeOffer[]>([])
  const pendingOutgoing = ref<TradeOffer[]>([])
  const pendingAccepted = ref<TradeOffer[]>([])

  let tradeChannel: RealtimeChannel | null = null

  async function subscribeTradeNotifs() {
    if (!authStore.user || authStore.sessionMode === 'offline') return
    if (tradeChannel) tradeChannel.unsubscribe()

    const db = gameStore.db
    if (!db) return
    tradeChannel = db.channel('trade-notifs-' + authStore.user.id)
      .on('postgres_changes', {
        event: 'INSERT', schema: 'public', table: 'claim_queue',
        filter: `user_id=eq.${authStore.user.id}`
      }, () => {
        uiStore.notify(' ¡Nuevos activos disponibles para reclamar!', '🎁')
        gameStore.fetchClaimQueue()
      })
      .on('postgres_changes', {
        event: 'INSERT', schema: 'public', table: 'trade_offers',
        filter: `receiver_id=eq.${authStore.user.id}`
      }, () => {
        uiStore.notify('¡Has recibido una nueva oferta de intercambio!', '🔄')
        audioStore.notif()
        refreshPendingTrades()
      })
      .subscribe()
  }

  async function refreshPendingTrades() {
    if (!authStore.user) return

    const db = gameStore.db
    const [incomingRes, outgoingRes, acceptedRes] = await Promise.all([
      db.from('trade_offers').select('*').eq('receiver_id', authStore.user.id).eq('status', 'pending') as unknown as Promise<{ data: TradeOffer[] | null }>,
      db.from('trade_offers').select('*').eq('sender_id', authStore.user.id).eq('status', 'pending') as unknown as Promise<{ data: TradeOffer[] | null }>,
      db.from('trade_offers').select('*').eq('sender_id', authStore.user.id).eq('status', 'accepted') as unknown as Promise<{ data: TradeOffer[] | null }>
    ])

    const validateOffers = (offers: TradeOffer[] | null): TradeOffer[] => {
      if (!offers) return []
      return offers.filter(o => {
        const v = validateTradeOffer(o)
        if (!v.success) {
          logger.error('TRADE', 'Oferta de intercambio inválida omitida de la lista:', v.issues)
          return false
        }
        return true
      })
    }

    pendingIncoming.value = validateOffers(incomingRes.data)
    pendingOutgoing.value = validateOffers(outgoingRes.data)
    pendingAccepted.value = validateOffers(acceptedRes.data)

    // Sincronizar contador en socialStore
    await socialStore.refreshNotificationCount()
  }

  async function openTradeModal(friendId: string, friendUsername: string) {
    tradeTarget.value = { id: friendId, username: friendUsername }
    tradeOfferPoke.value = null
    tradeRequestPoke.value = null
    Object.keys(tradeOfferItems).forEach(k => delete tradeOfferItems[k])
    Object.keys(tradeRequestItems).forEach(k => delete tradeRequestItems[k])

    const { data, error } = await gameStore.db.from('game_saves').select('save_data').eq('user_id', friendId).single() as unknown as { data: { save_data: GameState } | null, error: { message: string } | null }

    if (error || !data) {
      tradeFriendSave.value = { team: [], box: [], inventory: {}, money: 0 } as unknown as GameState
      uiStore.notify('No se pudo cargar el inventario del amigo.', '⚠️')
    } else {
      tradeFriendSave.value = data.save_data as unknown as GameState
    }
    uiStore.open('Trade')
  }

  async function sendTradeOffer({ isGift, offerMoney, requestMoney, message }: { isGift: boolean; offerMoney: number; requestMoney: number; message: string }) {
    if (!tradeTarget.value) return false

    const hasOffer = tradeOfferPoke.value !== null || Object.keys(tradeOfferItems).length > 0 || offerMoney > 0
    if (!hasOffer) {
      uiStore.notify('Tenés que ofrecer algo.', '⚠️')
      return false
    }

    if (offerMoney > gameStore.state.money) {
      uiStore.notify('No tenés suficiente dinero.', '💸')
      return false
    }

    // Anti-Duplicate check
    if (tradeOfferPoke.value && lockedUids.value.has(tradeOfferPoke.value.uid)) {
      uiStore.notify('Este Pokémon ya está en otra oferta pendiente.', '⚠️')
      return false
    }

    // MANDATORY: Deduct items locally before saving to SQLite so DBs match
    for (const [itemName, qty] of Object.entries(tradeOfferItems)) {
      if (gameStore.state.inventory[itemName]) {
        gameStore.state.inventory[itemName] -= qty
        if (gameStore.state.inventory[itemName] <= 0) {
          delete gameStore.state.inventory[itemName]
        }
      }
    }
    if (offerMoney > 0) {
      gameStore.state.money -= offerMoney
    }

    // MANDATORY: Pre-Action Flush (Always save before social actions with assets)
    uiStore.notify('Sincronizando inventario...', '🔄')
    await gameStore.save(false)

    const { data: tradeId, error } = await gameStore.db.rpc('send_trade_offer_v2', {
      p_receiver_id: tradeTarget.value.id,
      p_offer_pokemon: tradeOfferPoke.value,
      p_offer_items: { ...tradeOfferItems },
      p_offer_money: offerMoney,
      p_request_pokemon: isGift ? null : tradeRequestPoke.value,
      p_request_items: isGift ? {} : { ...tradeRequestItems },
      p_request_money: isGift ? 0 : requestMoney,
      p_message: message || ''
    })

    if (!error && tradeId) {
      uiStore.notify(`¡Oferta enviada a ${tradeTarget.value.username}!`, '🔄')
      audioStore.sentMsg() 
      await gameStore.loadGame() // <-- OBLIGATORIO: Actualizar cliente post-escrow
      refreshPendingTrades()
      return true
    } else {
      // ROLLBACK LOCAL: Si falla, devolver los items
      for (const [itemName, qty] of Object.entries(tradeOfferItems)) {
        gameStore.state.inventory[itemName] = (gameStore.state.inventory[itemName] || 0) + qty
      }
      if (offerMoney > 0) {
        gameStore.state.money += offerMoney
      }
      logger.error('TRADE', `Error al enviar oferta: ${(error as Error).message}`)
      uiStore.notify('Error al enviar oferta: ' + (error as { message: string }).message, '❌')
      return false
    }
  }

  async function acceptTrade(tradeId: string | number) {

    try {
      loadingStore.start('accept_trade', 'Procesando intercambio...', 'Sincronizando con el servidor', true, '🔄')

      // MANDATORY: Pre-Action Flush
      uiStore.notify('Sincronizando inventario...', '🔄')
      await gameStore.save(false)

      const db = gameStore.db
      const { error: rpcErr } = await db.rpc('accept_trade_v2', {
        p_trade_id: tradeId
      })

      if (rpcErr) throw new Error((rpcErr as { message: string }).message)

      uiStore.notify('¡Intercambio aceptado! Los activos están en tu cola de reclamo.', '🎉')
      await gameStore.fetchClaimQueue()

      loadingStore.finish('accept_trade')
      await refreshPendingTrades()
      return true
    } catch (err) {
      loadingStore.finish('accept_trade')
      logger.error('TRADE', `Error en el intercambio: ${(err as Error).message}`)
      uiStore.notify('Error en el intercambio: ' + (err as { message: string }).message, '❌')
      return false
    }
  }

  async function rejectTrade(tradeId: string | number) {
    try {
      loadingStore.start('reject_trade', 'Cancelando intercambio...', 'Sincronizando con el servidor', true, '🔄')

      // MANDATORY: Pre-Action Flush
      uiStore.notify('Sincronizando inventario...', '🔄')
      await gameStore.save(false)

      const { error } = await gameStore.db.rpc('reject_trade_v2', {
        p_trade_id: tradeId
      })
      if (error) throw new Error((error as { message: string }).message)

      uiStore.notify('Oferta cancelada/rechazada. Reembolso enviado a Reclamos.', '👋')
      await gameStore.fetchClaimQueue()
      await gameStore.loadGame() // <-- OBLIGATORIO: Actualizar cliente tras cambios de escrow
      await refreshPendingTrades()

      loadingStore.finish('reject_trade')
    } catch (err) {
      loadingStore.finish('reject_trade')
      logger.error('TRADE', `Error al cancelar/rechazar intercambio: ${(err as Error).message}`)
      uiStore.notify('Error al procesar: ' + (err as { message: string }).message, '❌')
    }
  }

  async function claimTrade(tradeId: string | number) {
    try {
      const { error } = await gameStore.db.from('trade_offers').update({ status: 'claimed' }).eq('id', tradeId)
      if (error) throw new Error((error as { message: string }).message)
      await refreshPendingTrades()
    } catch (err) {
      logger.error('TRADE', `Error al confirmar intercambio: ${(err as Error).message}`)
      uiStore.notify('Error al confirmar: ' + (err as { message: string }).message, '❌')
    }
  }

  const lockedUids = computed(() => {
    const locked = new Set<string>()
    pendingIncoming.value.forEach((t: TradeOffer) => {
      if (t.request_pokemon?.uid) locked.add(t.request_pokemon.uid)
    })
    pendingOutgoing.value.forEach((t: TradeOffer) => {
      if (t.offer_pokemon?.uid) locked.add(t.offer_pokemon.uid)
    })
    return locked
  })

  const pendingCount = computed(() => pendingIncoming.value.length)

  return {
    tradeTarget,
    tradeFriendSave,
    tradeOfferPoke,
    tradeRequestPoke,
    tradeOfferItems,
    tradeRequestItems,
    pendingIncoming,
    pendingOutgoing,
    pendingAccepted,
    pendingCount,
    lockedUids,
    subscribeTradeNotifs,
    refreshPendingTrades,
    openTradeModal,
    sendTradeOffer,
    acceptTrade,
    rejectTrade,
    claimTrade
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useAuthStore } from './auth.ts'
import { useGameStore } from './game.ts'
import { useUIStore } from './ui.ts'
import { getWeekId, isDisputePhase, getPointReward, FACTION_CHANGE_COST, DAILY_MAP_CAP, WEEKLY_REWARD_MILESTONES, WEEKLY_WIN_BONUS_COINS } from '@/logic/war/warEngine'
import { getGuardianData, GUARDIAN_CHANCE } from '@/logic/war/guardianEngine'

import type { DominanceInfo } from '@/types/stores'

interface WarPointsRecord {
  map_id: string
  faction: 'union' | 'poder'
  points: number
}

interface DominanceRecord {
  map_id: string
  winner_faction: string
}

export const useWarStore = defineStore('war', () => {
  const gameStore = useGameStore()
  const authStore = useAuthStore()
  const uiStore = useUIStore()

  const faction = ref<'union' | 'poder' | null>(null)
  const warCoins = ref(0)
  const weeklyPoints = ref(0)
  const mapDominance = ref<Record<string, DominanceInfo>>({})
  const dailyGuardianCaptures = ref<string[]>([])
  const isLoading = ref(false)

  // Reactive engine-based state
  const currentWeekId = computed(() => getWeekId())
  const isDisputeActive = computed(() => isDisputePhase())

  /**
   * Loads all war-related data for the current session.
   * Handles Global vs Local instance isolation via gameStore.db (DBRouter).
   */
  async function loadWarData() {
    isLoading.value = true
    try {
      // 1. Load Faction and Coins from Game State (Synchronized via DBRouter)
      faction.value = (gameStore.state.faction as 'union' | 'poder' | null) || null
      warCoins.value = gameStore.state.warCoins || 0

      // 2. Load Individual Weekly Progress
      if (authStore.user && gameStore.db) {
        const { data: pts } = await gameStore.db.from('war_user_points')
          .select('points')
          .eq('user_id', authStore.user.id)
          .eq('week_id', currentWeekId.value)

        weeklyPoints.value = (pts as { points: number }[] | null)?.reduce((acc, r) => acc + (r.points || 0), 0) || 0

        // 3. Load Guardian Captures for today (isolated world)
        const today = Temporal.Now.plainDateISO().toString()
        const { data: guardians } = await gameStore.db.from('guardian_captures')
          .select('map_id')
          .eq('user_id', authStore.user.id)
          .eq('capture_date', today)

        dailyGuardianCaptures.value = (guardians as { map_id: string }[] | null)?.map(g => g.map_id) || []
      }

      // 4. Load Dominance Data
      await fetchMapDominance()
    } finally {
      isLoading.value = false
    }
  }

  /**
   * Adds war points for the current faction.
   * Logic handles Daily Cap and Faction requirement.
   */
  async function addPoints(mapId: string, eventType: string, success: boolean) {
    if (!faction.value || !isDisputeActive.value || !gameStore.db) return 0

    // 1. Calculate points from Engine
    const pts = getPointReward(eventType, success)
    if (pts <= 0) return 0

    // 2. Daily PT Cap Check (Isolated by World)
    const today = Temporal.Now.plainDateISO().toString()
    if (!gameStore.state.warDailyCap) gameStore.state.warDailyCap = {}

    const dailyCap = gameStore.state.warDailyCap as Record<string, Record<string, number>>
    if (!dailyCap[today]) dailyCap[today] = {}

    const currentMapPts = dailyCap[today]?.[mapId] || 0
    if (currentMapPts >= DAILY_MAP_CAP) {
      // Only notify once per map session
      return 0
    }

    const allowedPts = Math.min(pts, DAILY_MAP_CAP - currentMapPts)

    // 3. Registration via DBRouter (Handles RPC online or SQL local)
    const { error } = await gameStore.db.rpc('add_war_points', {
      p_week_id: currentWeekId.value,
      p_map_id: mapId,
      p_faction: faction.value,
      p_points: allowedPts
    })

    if (!error) {
       weeklyPoints.value += allowedPts
       dailyCap[today]![mapId] = currentMapPts + allowedPts

       // Handle War Coins (1 coin per 10 PT)
       handleWarCoins(allowedPts)

       await fetchMapDominance()
       return allowedPts
    }
    return 0
  }

  /**
   * Progressively awards War Coins based on points earned.
   * Cap: 50 coins per day (Legacy Parity).
   */
  function handleWarCoins(pts: number) {
    const today = Temporal.Now.plainDateISO().toString()
    if (!gameStore.state.warDailyCoins) gameStore.state.warDailyCoins = {}

    const dailyCoins = gameStore.state.warDailyCoins as Record<string, number>
    if (!dailyCoins[today]) dailyCoins[today] = 0
    if (!gameStore.state.warPointsAccumulator) gameStore.state.warPointsAccumulator = 0

    const DAILY_COIN_CAP = 50 
    if ((dailyCoins[today] ?? 0) >= DAILY_COIN_CAP) return

    gameStore.state.warPointsAccumulator += pts
    if (gameStore.state.warPointsAccumulator >= 10) {
      const newCoins = Math.floor(gameStore.state.warPointsAccumulator / 10)
      const allowedCoins = Math.min(newCoins, DAILY_COIN_CAP - (dailyCoins[today] ?? 0))

      if (allowedCoins > 0) {
        warCoins.value += allowedCoins
        gameStore.state.warCoins = (gameStore.state.warCoins || 0) + allowedCoins
        dailyCoins[today] = (dailyCoins[today] ?? 0) + allowedCoins
        uiStore.notify(`¡Ganaste ${allowedCoins} Moneda${allowedCoins > 1 ? 's' : ''} de Guerra!`, '⚡')
      }
      gameStore.state.warPointsAccumulator %= 10
    }
  }

  /**
   * Assigns or changes the player's faction.
   * Cost: 25k for changes.
   */
  async function chooseFaction(newFaction: string) {
    if (!authStore.user || !gameStore.db) return false

    const isChange = !!faction.value
    if (isChange) {
      if (faction.value === newFaction) return true
      if (gameStore.state.money < FACTION_CHANGE_COST) {
        uiStore.notify(`Necesitás 🪙${FACTION_CHANGE_COST.toLocaleString()} para cambiar de bando.`, '⛔')
        return false
      }

      // Legacy rule: Reset points on faction change
      gameStore.state.money -= FACTION_CHANGE_COST
      await gameStore.db.from('war_user_points').delete()
        .eq('user_id', authStore.user.id)
        .eq('week_id', currentWeekId.value)

      weeklyPoints.value = 0
    }

    const { error } = await gameStore.db.from('war_factions')
      .upsert({ user_id: authStore.user.id, faction: newFaction })

    if (!error) {
      faction.value = newFaction as 'union' | 'poder'
      gameStore.state.faction = newFaction
      uiStore.notify(`¡Ahora eres parte del Team ${newFaction === 'union' ? 'Unión' : 'Poder'}!`, '⚔️')
      return true
    }
    return false
  }

  /**
   * Records a guardian capture or defeat.
   */
  async function claimGuardian(mapId: string, isDefeat = false) {
    if (!authStore.user || !faction.value || !gameStore.db) return

    const today = Temporal.Now.plainDateISO().toString()
    const guardian = getGuardianData(mapId, []) // In real use we pass map list
    if (!guardian) return

    const ptsAwarded = isDefeat ? Math.floor(guardian.pts * 0.7) : guardian.pts

    const { error } = await gameStore.db.from('guardian_captures').insert({
      capture_date: today,
      map_id: mapId,
      user_id: authStore.user.id,
      winner_faction: faction.value,
      pts_awarded: ptsAwarded
    })

    if (!error) {
      if (!dailyGuardianCaptures.value.includes(mapId)) {
        dailyGuardianCaptures.value.push(mapId)
      }
      await addPoints(mapId, 'GUARDIAN', true) // Points logic handles Coins/State
      uiStore.notify(`¡Guardián ${isDefeat ? 'Derrotado' : 'Capturado'}! +${ptsAwarded} PT.`, '🏆')
    }
  }

  /**
   * Fetches the current dominance state.
   * Local Instances will simulate data if no records exist.
   */
  async function fetchMapDominance() {
    if (!gameStore.db) return
    // 1. Fetch points for the current week
    const { data: points } = await gameStore.db.from('war_points')
      .select('map_id, faction, points')
      .eq('week_id', currentWeekId.value)

    const newDom: Record<string, DominanceInfo> = {}
    ;(points as WarPointsRecord[] | null)?.forEach(row => {
      if (!newDom[row.map_id]) newDom[row.map_id] = { union: 0, poder: 0, winner: null }
      newDom[row.map_id]![row.faction] = row.points
    })

    // 2. Fetch settled winners if not in dispute phase
    if (!isDisputeActive.value) {
      const { data: dom } = await gameStore.db.from('war_dominance')
        .select('map_id, winner_faction')
        .eq('week_id', currentWeekId.value)

      ;(dom as DominanceRecord[] | null)?.forEach(row => {
        if (!newDom[row.map_id]) newDom[row.map_id] = { union: 0, poder: 0, winner: null }
        newDom[row.map_id]!.winner = row.winner_faction
      })
    }

    mapDominance.value = newDom
  }

  /**
   * Triggers a guardian appearance check.
   */
  function checkGuardian(mapId: string, allMapIds: string[]) {
    if (dailyGuardianCaptures.value.includes(mapId)) return null
    if (Math.random() > GUARDIAN_CHANCE) return null

    return getGuardianData(mapId, allMapIds)
  }

  /**
   * Settles the weekly results and distributes coins.
   * This is typically called during the dominance phase transition.
   */
  async function resolveWeeklySeason() {
    if (isDisputeActive.value || !gameStore.db) return
    if (gameStore.state.lastResolvedWeek === currentWeekId.value) return

    // Calculate contribution coins based on milestones
    let totalCoins = 0
    const milestones = [...WEEKLY_REWARD_MILESTONES].reverse()
    const match = milestones.find(m => weeklyPoints.value >= m.pt)
    if (match) totalCoins = match.coins

    // Winner bonus
    const { data: winners } = await gameStore.db.from('war_dominance')
      .select('winner_faction')
      .eq('week_id', currentWeekId.value)

    let unionWins = 0, poderWins = 0
    ;(winners as { winner_faction: string }[] | null)?.forEach(w => {
      if (w.winner_faction === 'union') unionWins++
      else poderWins++
    })

    const isWinner = (faction.value === 'union' && unionWins >= poderWins) ||
                     (faction.value === 'poder' && poderWins > unionWins)

    if (isWinner) totalCoins += WEEKLY_WIN_BONUS_COINS

    if (totalCoins > 0) {
      warCoins.value += totalCoins
      gameStore.state.warCoins = (gameStore.state.warCoins || 0) + totalCoins
      uiStore.notify(`Fin de guerra. ¡Recibiste ${totalCoins} Monedas de Guerra!`, '⚡')
    }

    gameStore.state.lastResolvedWeek = currentWeekId.value
  }

  return {
    faction,
    warCoins,
    weeklyPoints,
    mapDominance,
    isDisputeActive,
    currentWeekId,
    dailyGuardianCaptures,
    isLoading,
    loadWarData,
    addPoints,
    fetchMapDominance,
    checkGuardian,
    chooseFaction,
    claimGuardian,
    resolveWeeklySeason
  }
})

/**
 * @file setup_supabase.ts
 * @description Orquestador CLI en TypeScript (Node.js 26+) para gestionar
 * despliegues multi-servidor de Supabase, reemplazando la versión legacy en Python.
 * 
 * CARACTERÍSTICAS MODERNAS (Node.js 26+):
 * - Uso exclusivo de prefijos 'node:' para imports nativos.
 * - Explicit Resource Management (ERM) mediante 'await using'.
 * - Compilación ultrarrápida nativa sin dependencias externas.
 * - Formato estandarizado mediante ANSI util 'styleText'.
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';
import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
import readline from 'node:readline';
import { fileURLToPath } from 'node:url';

enableCompileCache();

// ── Constantes y Configuración de Rutas ──────────────────────────────────────
const BASE_DIR          = path.dirname(fileURLToPath(import.meta.url));
const ARCHIVO_MAESTRO   = path.resolve(BASE_DIR, '..', '.env'); // .env maestro en raíz de PokeBorrador
const CARPETA_GENERADOS = path.resolve(BASE_DIR, 'generated');
const CARPETA_DOCKER    = path.resolve(BASE_DIR, 'docker');

// ── Contenido de Dockerfile Personalizado (1:1) ──────────────────────────────
const DOCKERFILE_CONTENT = `# ─────────────────────────────────────────────────────────────────────────────
