    mismodestino: 'destiny_bond',
    pantalla_humo: 'smokescreen',
    super_colmillo: 'super_fang',
    huevo_bomba: 'egg_bomb',
    hueso_rus: 'bone_rush',
    mega_patada: 'mega_kick',
    mega_puno: 'mega_punch',
    pozo_venenoso: 'toxic_spikes',
    vampiro: 'horn_leech',
    psicocorte: 'psycho_cut',
    arena: 'sand_attack',
    minimizar: 'minimize',
    golpe_karatazo: 'karate_chop',
    mov_sismico: 'seismic_toss',
    tajo_aereo: 'air_slash',
    acidificacion: 'acid_armor',
    recurrente: 'bullet_seed',
    tormenta_de_arena: 'sandstorm'
  };

  function normalizeAbilityName(abilityName: string): string {
    return abilityName.toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]/g, '');
  }

  function getLegacyAbilityTranslation(abilityName: string | undefined): string | undefined {
    if (!abilityName) return undefined;
    const abKey = normalizeAbilityName(abilityName);
    return legacyAbilityMap[abKey];
  }

  function getLegacyItemTranslation(heldItem: string | undefined): string | undefined {
    if (!heldItem) return undefined;
    const itemKey = heldItem.toLowerCase().trim();
    return legacyItemMap[itemKey];
  }

  function getLegacyMoveTranslation(moveId: string | undefined): string | undefined {
    if (!moveId) return undefined;
    const moveKey = moveId.toLowerCase().replace(/[\s_-]+/g, '_').trim();
    return legacyMoveMap[moveKey];
  }

  function migratePoke(p: any) {
    if (!p) return;

    // 1. Legendaries to 0 vigor
    if (p.id && legendaries.has(p.id.toLowerCase())) {
      p.vigor = 0;
    }

    // 2. Mapped held items
    const mappedItem = getLegacyItemTranslation(p.heldItem);
    if (mappedItem) {
      p.heldItem = mappedItem;
    }

    // 3. Mapped abilities
    const mappedAbility = getLegacyAbilityTranslation(p.ability);
    if (mappedAbility) {
      p.ability = mappedAbility;
    }

    // 4. Mapped moves
    if (p.moves && Array.isArray(p.moves)) {
      p.moves.forEach((m: any) => {
        if (m) {
          const mappedMove = getLegacyMoveTranslation(m.id);
          if (mappedMove) {
            m.id = mappedMove;
          }
        }
      });
    }
  }

  const backups = [
    'database/backups/nas_franco/nas_franco_backup_2026-05-31T01-57-05-676918945Z.json',
    'database/backups/official-prod/official-prod_backup_2026-05-20T10-31-22-170657959Z.json'
  ];

  backups.forEach(backupRelPath => {
    const filename = path.basename(backupRelPath);

    it(`should successfully parse and migrate all game saves in ${filename} without breaking data`, () => {
      const backupPath = path.resolve(backupRelPath);
      assert.ok(fs.existsSync(backupPath), `Backup file ${filename} must exist`);

      const backupContent = fs.readFileSync(backupPath, 'utf8');
      const backupData = JSON.parse(backupContent);
      assert.ok(backupData.data, 'Backup must contain a data object');

      const gameSaves = backupData.data.game_saves || [];
      assert.ok(gameSaves.length > 0, 'Backup must contain game_saves');

      let legendariesFoundAndFixedCount = 0;
      let legacyHeldItemsFixedCount = 0;
      let legacyAbilitiesFixedCount = 0;
      let legacyMovesFixedCount = 0;

      gameSaves.forEach((saveWrapper: any) => {
        let saveData: GameState;
        if (typeof saveWrapper.save_data === 'string') {
          saveData = JSON.parse(saveWrapper.save_data);
        } else {
          saveData = saveWrapper.save_data;
        }

        const team = saveData.team || [];
        const box = saveData.box || [];

        // Track properties before migration to ensure they change
        const preCheck = (p: any) => {
          if (!p) return;
          if (p.id && legendaries.has(p.id.toLowerCase()) && p.vigor > 0) {
            legendariesFoundAndFixedCount++;
          }
          if (p.heldItem && getLegacyItemTranslation(p.heldItem)) {
            legacyHeldItemsFixedCount++;
          }
          if (getLegacyAbilityTranslation(p.ability)) {
            legacyAbilitiesFixedCount++;
          }
          if (p.moves && Array.isArray(p.moves)) {
            p.moves.forEach((m: any) => {
              if (m && getLegacyMoveTranslation(m.id)) {
                legacyMovesFixedCount++;
              }
            });
          }
        };

        team.forEach(preCheck);
        box.forEach(preCheck);

        // Run migration
        team.forEach(migratePoke);
        box.forEach(migratePoke);

        // Assertions post-migration
        const postCheck = (p: any) => {
          if (!p) return;
          // Legendaries must have 0 vigor
          if (p.id && legendaries.has(p.id.toLowerCase())) {
            assert.strictEqual(p.vigor, 0, `Legendary ${p.name} (${p.id}) must have 0 vigor after migration`);
          }
          // Held items must not be legacy
          if (p.heldItem) {
            const mappedItem = getLegacyItemTranslation(p.heldItem);
            if (mappedItem) {
              assert.strictEqual(p.heldItem, mappedItem, `Held item ${p.heldItem} was not migrated to ${mappedItem}`);
            }
          }
          // Abilities must not be legacy
          const mappedAbility = getLegacyAbilityTranslation(p.ability);
          if (mappedAbility) {
            assert.strictEqual(p.ability, mappedAbility, `Ability ${p.ability} was not migrated to ${mappedAbility}`);
          }
          // Moves must not be legacy
          if (p.moves && Array.isArray(p.moves)) {
            p.moves.forEach((m: any) => {
              if (m) {
                const mappedMove = getLegacyMoveTranslation(m.id);
                if (mappedMove) {
                  assert.strictEqual(m.id, mappedMove, `Move ${m.id} was not migrated to ${mappedMove}`);
                }
              }
            });
          }
        };

        team.forEach(postCheck);
        box.forEach(postCheck);
      });

      console.log(`\n[Test: ${filename}] Migrated successfully:`);
      console.log(` - Legendaries fixed to 0 vigor: ${legendariesFoundAndFixedCount}`);
      console.log(` - Legacy held items mapped: ${legacyHeldItemsFixedCount}`);
      console.log(` - Legacy abilities translated: ${legacyAbilitiesFixedCount}`);
      console.log(` - Legacy moves converted: ${legacyMovesFixedCount}\n`);
    });
  });
});

/**
 * tests/node/gts_transactions.test.ts
 *
 * NATIVE NODE.JS TEST (Node.js 26+)
 *
 * Simulates high-fidelity GTS transactions using the DBRouter offline logic.
 * Validates:
 * 1. Publishing assets (Pokemon/Items) and deducting them from the player save.
 * 2. Buying assets, deducting money from buyer, and moving assets to escrow.
 * 3. Claiming assets from the claim_queue and updating the player save.
 */

import { describe, it, beforeEach } from 'node:test';
import assert from 'node:assert/strict';

// Mock DBRouter local logic because initSqlJs requires WASM/Browser
// We will test the logic flow of the RPCs implemented in DBRouter.ts
interface MockSave {
  save_data: Record<string, unknown>;
  last_save_id: string;
}

interface MockListing {
  id: string;
  listing_type: string;
  seller_id: string;
  seller_name?: string;
  price: number;
  data: Record<string, unknown>;
  status: string;
}

interface MockClaim {
  user_id: string;
  claim_id: string;
  type: string;
  data: unknown;
}

class MockDatabase {
  game_saves: Record<string, MockSave> = {};
  market_listings: MockListing[] = [];
  claim_queue: MockClaim[] = [];

  run(sql: string, params: unknown[] = []) {
    // Basic SQL behavior simulation for tests
    if (sql.includes('INSERT INTO game_saves')) {
      const p = params as [string, string, string];
      this.game_saves[p[0]] = { save_data: JSON.parse(p[1]), last_save_id: p[2] };
    }
    if (sql.includes('INSERT INTO market_listings')) {
      const p = params as [string, string, string, string, number, string, string];
      this.market_listings.push({
        id: p[0],
        listing_type: p[1],
        seller_id: p[2],
        seller_name: p[3],
        price: p[4],
        data: JSON.parse(p[5]),
        status: p[6] || 'active'
      });
    }
    if (sql.includes('INSERT INTO claim_queue')) {
      const p = params as [string, string, string, string];
      this.claim_queue.push({
        user_id: p[0],
        claim_id: p[1],
        type: p[2],
        data: JSON.parse(p[3])
      });
    }
    if (sql.includes('UPDATE market_listings SET status')) {
      const p = params as [string, string];
      const listing = this.market_listings.find(l => l.id === p[1]);
      if (listing) listing.status = p[0];
    }
  }

  async query(sql: string, params: unknown[] = []): Promise<MockSave[]> {
    if (sql.includes('FROM game_saves')) {
      const p = params as [string];
      const save = this.game_saves[p[0]];
      return save ? [save] : [];
    }
    if (sql.includes('FROM market_listings')) {
      const p = params as [string];
      const listings = this.market_listings.filter(l => l.id === p[0]);
      // Mocking return as saves for simplicity in this specific test flow
      return listings.map(l => ({ save_data: l.data, last_save_id: 'mock' }));
    }
    return [];
  }
}

describe('GTS Offline SQL Emulation (Transactions)', () => {
  let db: MockDatabase;
  const SELLER_ID = 'local_ash';
  const BUYER_ID = 'local_gary';

  beforeEach(() => {
    db = new MockDatabase();

    // Setup initial saves
    db.run('INSERT INTO game_saves (user_id, save_data, last_save_id) VALUES (?, ?, ?)', [
      SELLER_ID,
      JSON.stringify({
        money: 1000,
        team: [{ uid: 'pika_1', id: 'pikachu', name: 'Pika' }],
        box: []
      }),
      'save_1'
    ]);

    db.run('INSERT INTO game_saves (user_id, save_data, last_save_id) VALUES (?, ?, ?)', [
      BUYER_ID,
      JSON.stringify({
        money: 5000,
        team: [],
        box: []
      }),
      'save_2'
    ]);
  });

  it('should publish a pokemon and remove it from the seller save', async () => {
    // Simulating publish_listing_v2 logic
    const p_listing_type = 'pokemon';
    const p_asset_data = { uid: 'pika_1', id: 'pikachu', name: 'Pika' };
    const p_price = 500;

    const saves = await db.query("SELECT save_data FROM game_saves WHERE user_id = ?", [SELLER_ID]);
    const saveObj = saves[0]!.save_data;

    // Logic from DBRouter: remove pokemon
    const team = (saveObj.team as Array<{uid: string}>);
    saveObj.team = team.filter((p) => p.uid !== p_asset_data.uid);

    db.run('INSERT INTO market_listings (id, listing_type, seller_id, seller_name, price, data, status) VALUES (?, ?, ?, ?, ?, ?, ?)', [
      'list_1', p_listing_type, SELLER_ID, 'Ash', p_price, JSON.stringify(p_asset_data), 'active'
    ]);
    db.run('INSERT INTO game_saves (user_id, save_data, last_save_id) VALUES (?, ?, ?)', [
      SELLER_ID, JSON.stringify(saveObj), 'save_3'
    ]);

    assert.strictEqual(db.market_listings.length, 1);
    assert.strictEqual((db.game_saves[SELLER_ID]!.save_data.team as unknown[]).length, 0);
  });

  it('should handle a purchase: deduct money from buyer and move assets to escrow', async () => {
    // 1. Setup listing
    db.market_listings.push({
      id: 'list_1',
      listing_type: 'pokemon',
      seller_id: SELLER_ID,
      price: 1000,
      data: { uid: 'pika_1', name: 'Pikachu' },
      status: 'active'
    });

    // 2. Buy logic
    const buyerSaves = await db.query("SELECT save_data FROM game_saves WHERE user_id = ?", [BUYER_ID]);
    const buyerSave = buyerSaves[0]!.save_data;

    assert.ok((buyerSave.money as number) >= 1000);
    buyerSave.money = (buyerSave.money as number) - 1000;

    // Update buyer save
    db.run('INSERT INTO game_saves (user_id, save_data, last_save_id) VALUES (?, ?, ?)', [
      BUYER_ID, JSON.stringify(buyerSave), 'save_4'
    ]);

    // Move to claim_queue for buyer
    db.run('INSERT INTO claim_queue (user_id, claim_id, type, data) VALUES (?, ?, ?, ?)', [
      BUYER_ID, 'claim_b_1', 'pokemon', JSON.stringify({ uid: 'pika_1', name: 'Pikachu' })
    ]);

    // Move money to claim_queue for seller (with 5% commission)
    const net = 1000 * 0.95;
    db.run('INSERT INTO claim_queue (user_id, claim_id, type, data) VALUES (?, ?, ?, ?)', [
      SELLER_ID, 'claim_s_1', 'money', JSON.stringify(net)
    ]);

    // Mark listing as sold
    db.run('UPDATE market_listings SET status = ? WHERE id = ?', ['sold', 'list_1']);

    assert.strictEqual(db.game_saves[BUYER_ID]!.save_data.money, 4000);
    assert.strictEqual(db.claim_queue.length, 2);
    assert.strictEqual(db.market_listings[0]!.status, 'sold');

    const sellerClaim = db.claim_queue.find(c => c.user_id === SELLER_ID);
    assert.strictEqual(sellerClaim?.data, 950);
  });
});

/**
 * tests/node/item_budgets.test.ts
 *
 * NATIVE NODE.JS TEST (Node.js 26+)
 *
 * Tests probability budget redistribution math for Fishing Rods, Pickaxes and Brushes.
 */

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';

// Helper functions duplicating the exact mathematical algorithms in encounters.ts and map.ts
function redistributeFishingBudget(rates: number[], budget: number): number[] {
  const result = [...rates];
  const indexedPool = rates
    .map((rate, index) => ({ rate, index }))
    .sort((a, b) => a.rate - b.rate);

  let remaining = budget;
  for (let i = 0; i < indexedPool.length; i++) {
    const item = indexedPool[i]!;
    if (i === indexedPool.length - 1) {
      result[item.index] = (result[item.index] || 10) + remaining;
      remaining = 0;
    } else {
      const portion = Math.round(remaining / 2);
      result[item.index] = (result[item.index] || 10) + portion;
      remaining -= portion;
    }
  }
  return result;
}

function distributeArchaeologyBudget(
  pickaxeType: 'standard' | 'good' | 'super' | null,
  brushType: 'standard' | 'good' | 'super' | null
) {
  const categoryWeights = {
    fossil: 45,
    stone: 25,
    common: 20,
    rare: 10
  };

  if (pickaxeType === 'good' || pickaxeType === 'super') {
    const budget = pickaxeType === 'good' ? 500 : 1000;
    const affected = [
      { key: 'rare', base: 10 },
      { key: 'common', base: 20 },
      { key: 'stone', base: 25 }
    ];
    let remaining = budget;
    for (let i = 0; i < affected.length; i++) {
      const item = affected[i]!;
      let added = 0;
      if (i === affected.length - 1) {
        added = remaining;
      } else {
        added = Math.round(remaining * 0.5);
      }
      categoryWeights[item.key as 'rare' | 'common' | 'stone'] += added;
      remaining -= added;
    }
  }

  if (brushType === 'good' || brushType === 'super') {
    const budget = brushType === 'good' ? 500 : 1000;
    categoryWeights.fossil += budget;
  }

  return categoryWeights;
}

describe('Tool Probability Budget Redistribution Math', () => {
  describe('Fishing Rod Budget Redistribution', () => {
    it('should correctly redistribute 500 budget (good rod) among three species', () => {
      const baseRates = [10, 20, 30]; // Rare to common
      const finalRates = redistributeFishingBudget(baseRates, 500);

      // Expected math:
      // Sort: 10 (idx 0), 20 (idx 1), 30 (idx 2)
      // idx 0 gets Math.round(500 / 2) = 250 -> 10 + 250 = 260
      // idx 1 gets Math.round(250 / 2) = 125 -> 20 + 125 = 145
      // idx 2 gets remaining 125 -> 30 + 125 = 155
      assert.deepEqual(finalRates, [260, 145, 155]);
    });

    it('should correctly redistribute 1000 budget (super rod) among three species', () => {
      const baseRates = [10, 20, 30];
      const finalRates = redistributeFishingBudget(baseRates, 1000);

      // Expected math:
      // Sort: 10 (idx 0), 20 (idx 1), 30 (idx 2)
      // idx 0 gets Math.round(1000 / 2) = 500 -> 10 + 500 = 510
      // idx 1 gets Math.round(500 / 2) = 250 -> 20 + 250 = 270
      // idx 2 gets remaining 250 -> 30 + 250 = 280
      assert.deepEqual(finalRates, [510, 270, 280]);
    });

    it('should handle unsorted input arrays and distribute based on sorted order', () => {
      const unsortedRates = [30, 10, 20];
      const finalRates = redistributeFishingBudget(unsortedRates, 500);

      // Sort order by rate: 10 (idx 1), 20 (idx 2), 30 (idx 0)
      // idx 1 gets 250 -> 10 + 250 = 260
      // idx 2 gets 125 -> 20 + 125 = 145
      // idx 0 gets 125 -> 30 + 125 = 155
      assert.deepEqual(finalRates, [155, 260, 145]);
    });
  });

  describe('Archaeology Category Budget Redistribution', () => {
    it('should return base weights when no tools are active', () => {
      const weights = distributeArchaeologyBudget(null, null);
      assert.deepEqual(weights, { fossil: 45, stone: 25, common: 20, rare: 10 });
    });

    it('should apply pickaxe budget (+500) only to mineral/stone categories', () => {
      const weights = distributeArchaeologyBudget('good', null);
      // Expected math:
      // Sort affected: rare (10), common (20), stone (25)
      // rare gets 250 -> 260
      // common gets 125 -> 145
      // stone gets 125 -> 150
      // fossil remains 45
      assert.deepEqual(weights, { fossil: 45, stone: 150, common: 145, rare: 260 });
    });

    it('should apply pickaxe budget (+1000) only to mineral/stone categories', () => {
      const weights = distributeArchaeologyBudget('super', null);
      // Expected math:
      // Sort affected: rare (10), common (20), stone (25)
      // rare gets 500 -> 510
      // common gets 250 -> 270
      // stone gets 250 -> 275
      // fossil remains 45
      assert.deepEqual(weights, { fossil: 45, stone: 275, common: 270, rare: 510 });
    });

    it('should apply brush budget (+500) only to fossil category', () => {
      const weights = distributeArchaeologyBudget(null, 'good');
      // Expected math:
      // fossil gets 45 + 500 = 545
      // others remain unchanged
      assert.deepEqual(weights, { fossil: 545, stone: 25, common: 20, rare: 10 });
    });

    it('should apply brush budget (+1000) only to fossil category', () => {
      const weights = distributeArchaeologyBudget(null, 'super');
      // Expected math:
      // fossil gets 45 + 1000 = 1045
      // others remain unchanged
      assert.deepEqual(weights, { fossil: 1045, stone: 25, common: 20, rare: 10 });
    });
  });
});

