describe('Item Reactivity & Integrity', () => {
  let mockPokemon: Pokemon

  beforeEach(() => {
    mockPokemon = {
      id: 'pikachu',
      name: 'Pikachu',
      hp: 10,
      maxHp: 100,
      status: 'poison',
      moves: [
        { name: 'Thunderbolt', pp: 5, maxPP: 15 }
      ]
    } as unknown as Pokemon
  })

  it('should heal HP and return the modified pokemon object', () => {
    const result = useItemOnPokemon('hyper_potion', mockPokemon)

    expect(result).toBeDefined()
    expect('success' in result!).toBe(false) // El proveedor devuelve { message, pokemon }
    expect(result!.message).toContain('restauró')
    expect(result!.pokemon.hp).toBe(100) // 10 + 200 clamped to 100
  })

  it('should clear status and return the modified pokemon object', () => {
    const result = useItemOnPokemon('antidote', mockPokemon)

    expect(result).toBeDefined()
    expect(result!.pokemon.status).toBeNull()
    expect(result!.message).toContain('se curó')
  })

  it('should restore PP and return the modified pokemon object', () => {
    const result = useItemOnPokemon('elixir', mockPokemon)

    expect(result).toBeDefined()
    expect(result!.pokemon.moves[0]!.pp).toBe(15)
    expect(result!.message).toContain('recuperó PP')
  })

  it('all registered items should return the standard object format, never a string', () => {
    const itemsToTest = Object.keys(itemEffects)

    itemsToTest.forEach(itemName => {
      // Usamos el pokemon mock o un estado genérico
      const effect = itemEffects[itemName];
      if (effect) {
        const result = effect(mockPokemon)

        expect(typeof result).toBe('object')
        expect(result).toHaveProperty('success')
        expect(result).toHaveProperty('message')
        expect(typeof result.message).toBe('string')
      }
    })
  })

  it('should fail gracefully if pokemon is already at full health', () => {
    mockPokemon.hp = 100
    const result = useItemOnPokemon('hyper_potion', mockPokemon)

    expect(result).toBeNull() // El proveedor devuelve null si result.success es falso
  })
})

import { describe, it, expect } from 'vitest';
import { POKEMON_DB } from '@/data/pokemonDB';

describe('Pokemon Database Integrity', () => {
  const species = Object.entries(POKEMON_DB);

  it('should have at least the original 151 species', () => {
    expect(species.length).toBeGreaterThanOrEqual(151);
  });

  it('every species must have a valid catchRate', () => {
    species.forEach(([id, data]) => {
      expect(data.catchRate, `Pokemon "${id}" is missing catchRate`).toBeDefined();
      expect(typeof data.catchRate, `Pokemon "${id}" catchRate must be a number`).toBe('number');
      expect(data.catchRate, `Pokemon "${id}" catchRate must be between 3 and 255`).toBeGreaterThanOrEqual(3);
      expect(data.catchRate, `Pokemon "${id}" catchRate must be between 3 and 255`).toBeLessThanOrEqual(255);
    });
  });

  it('every species must have core combat stats', () => {
    const stats = ['hp', 'atk', 'def', 'spa', 'spd', 'spe'];
    species.forEach(([id, data]) => {
      const record = data as unknown as Record<string, unknown>;
      stats.forEach(stat => {
        expect(record[stat], `Pokemon "${id}" is missing stat: ${stat}`).toBeDefined();
        expect(typeof record[stat], `Pokemon "${id}" stat ${stat} must be a number`).toBe('number');
        expect(record[stat] as number, `Pokemon "${id}" stat ${stat} must be positive`).toBeGreaterThan(0);
      });
    });
  });

  it('every species must have a valid learnset', () => {
    species.forEach(([id, data]) => {
      expect(Array.isArray(data.learnset), `Pokemon "${id}" learnset must be an array`).toBe(true);
      expect(data.learnset.length, `Pokemon "${id}" learnset cannot be empty`).toBeGreaterThan(0);

      data.learnset.forEach((move, index) => {
        expect(move.lv, `Pokemon "${id}" move at index ${index} missing level`).toBeDefined();
        expect(move.name, `Pokemon "${id}" move at index ${index} missing name`).toBeDefined();
        expect(move.pp, `Pokemon "${id}" move at index ${index} missing pp`).toBeDefined();
      });
    });
  });

  it('every species ID (key) must be lowercase and consistent', () => {
    Object.keys(POKEMON_DB).forEach(id => {
      expect(id, `Pokemon ID "${id}" must be lowercase`).toBe(id.toLowerCase());
      expect(id.includes(' '), `Pokemon ID "${id}" should not contain spaces`).toBe(false);
    });
  });
});

import { describe, it, expect } from 'vitest';

interface MockLoc {
  id: string;
  wild: {
    day?: string[];
    night?: string[];
    [key: string]: string[] | undefined;
  };
  fishing?: {
    pool: string[];
    rates?: number[];
  };
  rates: {
    day?: number[];
    night?: number[];
    [key: string]: number[] | undefined;
  };
}

// Lógica aislada extraída para el test (o importar si estuviera en un helper)
function getPokemonSpriteHtml(id: string, isRare = false) {
    const num = 1; // Simplified mock
    const name = id;
    return `<img src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${num}.png"
          title="${name}" width="54" height="54" loading="lazy"
          onerror="this.style.display='none'" 
          class="${isRare ? 'rare-spawn' : ''}">`;
}

function processActiveRates(pool: string[] | undefined, rates: number[] | undefined, minRatesObj: Record<string, number>) {
    if (!pool || !rates) return;
    pool.forEach((id: string, index: number) => {
        const rate = rates[index] || 0;
        if (minRatesObj[id] === undefined || rate < (minRatesObj[id] ?? Infinity)) {
            minRatesObj[id] = rate;
        }
    });
}

function generateLocationSpanwHTML(loc: MockLoc, cycle: string) {
    const currentCycleWild = loc.wild[cycle] || [];
    const baseWild = loc.wild.day || [];

    const genericSpawns: string[] = [];
    const specificSpawns: string[] = [];

    currentCycleWild.forEach((id: string) => {
        if (baseWild.includes(id)) genericSpawns.push(id);
        else specificSpawns.push(id);
    });

    const fishingPool = loc.fishing ? loc.fishing.pool : [];
    fishingPool.forEach((id: string) => {
        if (!genericSpawns.includes(id) && !specificSpawns.includes(id)) {
            genericSpawns.push(id);
        }
    });

    const minActiveRate: Record<string, number> = {};
    processActiveRates(currentCycleWild, loc.rates[cycle], minActiveRate);
    if (loc.fishing) processActiveRates(loc.fishing.pool, loc.fishing.rates || [], minActiveRate);

    const anyRare = [...genericSpawns, ...specificSpawns].some((id: string) => (minActiveRate[id] ?? 0) < 10);

    const renderSpritesHTML = (ids: string[]) => ids.map((id: string) => {
        const isRare = anyRare && ((minActiveRate[id] ?? 0) < 10);
        return getPokemonSpriteHtml(id, isRare);
    }).join('');

    const html = `<div class="location-spawns">
                  <div class="spawn-row">
                    ${renderSpritesHTML(genericSpawns)}
                  </div>
                  ${specificSpawns.length > 0 ? `
                    <div class="spawn-row cycle-specific-spawns">
                      <span class="cycle-emoji-label">🌙</span>
                      ${renderSpritesHTML(specificSpawns)}
                    </div>
                  ` : ''}
                </div>`;

    return {
        html,
        genericCount: genericSpawns.length,
        specificCount: specificSpawns.length,
        totalTarget: genericSpawns.length + specificSpawns.length
    }
}

describe('Map Spawns UI Logic', () => {
    const mockLoc: MockLoc = {
        id: 'route12',
        wild: {
            day: ['pidgey', 'venonat'],
            night: ['venonat', 'oddish']
        },
        fishing: {
            pool: ['magikarp']
        },
        rates: {
            day: [20, 20],
            night: [40, 30]
        }
    };

    it('should generate correct number of sprites', () => {
        const results = generateLocationSpanwHTML(mockLoc, 'day');
        const imgs = (results.html.match(/<img/g) || []).length;
        // pidgey, venonat, magikarp = 3
        expect(imgs).toBe(3);
        expect(results.html).toContain('width="54"');
    });

    it('should identify rare spawns (rate < 10)', () => {
        const rareLoc: MockLoc = {
            ...mockLoc,
            rates: { day: [5, 20] } // pidgey is rare
        };
        const results = generateLocationSpanwHTML(rareLoc, 'day');
        expect(results.html).toContain('class="rare-spawn"');
    });
});

